//新方块
namespace Game
{
    public class NewBlock : Block
    {
        public static int Index = 300;

        public Texture2D[] m_texture;

        public override void Initialize()
        {
            AccessNewBlockManager.Initialize("AccessNewBlockManager");
            m_texture = new Texture2D[AccessNewBlockManager.Data.Count];
            for (int i = 0; i < AccessNewBlockManager.Data.Count; i++)
            {
                m_texture[i] = ContentManager.Get<Texture2D>(AccessNewBlockManager.Get(i).Texture);
            }
            base.Initialize();
        }

        public override int GetTextureSlotCount(int value)
        {
            return 3;
        }

        public override int GetFaceTextureSlot(int face, int value)
        {
            switch (face)
            {
                case 0: return 0;//  右				
                case 1: return 1; //后
                case 2: return 2; //左
                case 3: return 3;//前
                case 4: return 4;//上
                case 5: return 5;//下
            }
            return 0;
        }

        public override void GenerateTerrainVertices(BlockGeometryGenerator generator, TerrainGeometry geometry, int value, int x, int y, int z)
        {
            int type = GetType(value);
            generator.GenerateCubeVertices(this, value, x, y, z, Color.White, geometry.GetGeometry(m_texture[type]).OpaqueSubsetsByFace);
        }

        //绘制
        public override void DrawBlock(PrimitivesRenderer3D primitivesRenderer, int value, Color color, float size, ref Matrix matrix, DrawBlockEnvironmentData environmentData)
        {
            int type = GetType(value);
            BlocksManager.DrawCubeBlock(primitivesRenderer, value, new Vector3(size), ref matrix, Color.White, Color.White, environmentData, m_texture[type]);
        }

        //在创造背包显示不同类型
        public override IEnumerable<int> GetCreativeValues()
        {
            List<int> list = new List<int>();
            for (int i = 0; i < AccessNewBlockManager.Data.Count; i++)
            {
                int value = Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i));
                list.Add(value);
            }
            return list;
        }

        //给不同类型的命名
        public override string GetDisplayName(SubsystemTerrain subsystemTerrain, int value)
        {
            int type = GetType(value);
            return AccessNewBlockManager.Get(type).Name;
        }

        //给不同类型的描述说明
        public override string GetDescription(int value)
        {
            int type = GetType(value);
            return LanguageControl.Get("NewBlock", type + 1);
        }

        //设置掉落物品
        public override void GetDropValues(SubsystemTerrain subsystemTerrain, int oldValue, int newValue, int toolLevel, List<BlockDropValue> dropValues, out bool showDebris)
        {
            showDebris = DestructionDebrisScale > 0f;
            int type = GetType(oldValue);
            showDebris = DestructionDebrisScale > 0f;
            if (toolLevel < AccessNewBlockManager.Get(type).RequiredToolLevel)
            {
                return;
            }
            BlockDropValue item;
            if (AccessNewBlockManager.Get(type).DefaultDropContent != "")
            {
                int num = (int)AccessNewBlockManager.Get(type).DefaultDropCount;
                if (Random.Bool(AccessNewBlockManager.Get(type).DefaultDropCount - num))
                {
                    num++;
                }
                for (int i = 0; i < (int)AccessNewBlockManager.Get(type).DefaultDropCount; i++)
                {
                    item = new BlockDropValue
                    {
                        Value = CraftingRecipesManager.DecodeResult(AccessNewBlockManager.Get(type).DefaultDropContent),
                        Count = 1
                    };
                    dropValues.Add(item);
                }
            }
        }

        //设置挖掘抗性
        public override float GetDigResilience(int value)
        {
            int type = GetType(value);
            return AccessNewBlockManager.Get(type).DigResilience;
        }

        //设置爆炸抗性
        public override float GetExplosionResilience(int value)
        {
            int type = GetType(value);
            return AccessNewBlockManager.Get(type).ExplosionResilience;
        }

        //设置所需工具等级
        public override float GetRequiredToolLevel(int value)
        {
            int type = GetType(value);
            return AccessNewBlockManager.Get(type).RequiredToolLevel;
        }

        //设置背包最大堆叠
        public override int GetMaxStacking(int value)
        {
            int type = GetType(value);
            return AccessNewBlockManager.Get(type).MaxStacking;
        }

        //设置挖掘方式
        public override BlockDigMethod GetBlockDigMethod(int value)
        {
            int type = GetType(value);
            return AccessNewBlockManager.Get(type).BlockDigMethod;
        }

        //挖掘粒子
        public override BlockDebrisParticleSystem CreateDebrisParticleSystem(SubsystemTerrain subsystemTerrain, Vector3 position, int value, float strength)
        {
            int type = GetType(value);
            return new BlockDebrisParticleSystem(subsystemTerrain, position, strength, this.DestructionDebrisScale, Color.White, this.GetFaceTextureSlot(1, value), m_texture[type]);
        }

        //获取类型
        public static int GetType(int value)
        {
            int data = Terrain.ExtractData(value);
            return data & 0xFF;
        }

        //设置类型，type取值0～255 (即可定义256种类型)
        public static int SetType(int value, int type)
        {
            int data = Terrain.ExtractData(value);
            return (data & -256) | MathUtils.Clamp(type, 0, 255);
        }

        //除了damage的set方法返回的为方块的value值，其他set方法返回方块的data值
        //新枪(data)数据存储: 00 0000 0000 0000 0000
        //从右到左8个位存储类型，往后8位存储
    }
}
//新工具
namespace Game
{
    public class NewToolsBlock : Block
    {
        public static int Index = 301;

        public Texture2D[] m_texture;

        public BlockMesh[] m_standaloneBlockMesh;

        public override void Initialize()
        {
            AccessNewToolsBlockManager.Initialize("AccessNewToolsBlockManager");
            m_texture = new Texture2D[AccessNewToolsBlockManager.Data.Count];
            m_standaloneBlockMesh = new BlockMesh[AccessNewToolsBlockManager.Data.Count];
            for (int i = 0; i < AccessNewToolsBlockManager.Data.Count; i++)
            {
                Model model = ContentManager.Get<Model>(AccessNewToolsBlockManager.Get(i).TheModelPath);
                Matrix boneAbsoluteTransform = BlockMesh.GetBoneAbsoluteTransform(model.FindMesh(AccessNewToolsBlockManager.Get(i).ModelComponents).ParentBone);
                m_standaloneBlockMesh[i] = new BlockMesh();
                m_standaloneBlockMesh[i].AppendModelMeshPart(model.FindMesh(AccessNewToolsBlockManager.Get(i).ModelComponents).MeshParts[0], boneAbsoluteTransform, makeEmissive: false, flipWindingOrder: false, doubleSided: false, flipNormals: false, Color.White);
                m_standaloneBlockMesh[i].TransformTextureCoordinates(Matrix.CreateTranslation((float)(0 % 16) / 16f, (float)(0 / 16) / 16f, 0f));
                m_texture[i] = ContentManager.Get<Texture2D>(AccessNewToolsBlockManager.Get(i).Texture);
            }
            base.Initialize();
        }

        public override void GenerateTerrainVertices(BlockGeometryGenerator generator, TerrainGeometry geometry, int value, int x, int y, int z)
        {
        }

        //绘制
        public override void DrawBlock(PrimitivesRenderer3D primitivesRenderer, int value, Color color, float size, ref Matrix matrix, DrawBlockEnvironmentData environmentData)
        {
            int type = GetType(value);
            if (GetMoreDurable(value))
            {
                BlocksManager.DrawMeshBlock(primitivesRenderer, m_standaloneBlockMesh[type], m_texture[type], new Color(120, 230, 120), size * 2f, ref matrix, environmentData);
            }
            else
            {
                BlocksManager.DrawMeshBlock(primitivesRenderer, m_standaloneBlockMesh[type], m_texture[type], Color.White, size * 2f, ref matrix, environmentData);
            }
        }

        //在创造背包显示不同类型
        public override IEnumerable<int> GetCreativeValues()
        {
            List<int> list = new List<int>();
            for (int i = 0; i < AccessNewToolsBlockManager.Data.Count; i++)
            {
                int value = Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i));
                list.Add(value);
                value = Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i) + SetMoreDurable(Index, true));
                list.Add(value);
            }
            return list;
        }

        //给不同类型的命名
        public override string GetDisplayName(SubsystemTerrain subsystemTerrain, int value)
        {
            int type = GetType(value);
            if (GetMoreDurable(value))
            {
                return "更耐久的" + AccessNewToolsBlockManager.Get(type).Name;
            }
            else
            {
                return AccessNewToolsBlockManager.Get(type).Name;
            }
        }

        //给不同类型的描述说明
        public override string GetDescription(int value)
        {
            int type = GetType(value);
            return LanguageControl.Get("NewToolsBlock", type + 1);
        }

        public override float GetShovelPower(int value)
        {
            int type = GetType(value);
            return AccessNewToolsBlockManager.Get(type).ShovelPower;
        }

        public override float GetQuarryPower(int value)
        {
            int type = GetType(value);
            return AccessNewToolsBlockManager.Get(type).QuarryPower;
        }

        public override float GetHackPower(int value)
        {
            int type = GetType(value);
            return AccessNewToolsBlockManager.Get(type).HackPower;
        }

        public override float GetMeleePower(int value)
        {
            int type = GetType(value);
            return AccessNewToolsBlockManager.Get(type).MeleePower;
        }

        public override float GetMeleeHitProbability(int value)
        {
            int type = GetType(value);
            return AccessNewToolsBlockManager.Get(type).MeleeHitProbability;
        }

        public override int GetDurability(int value)
        {
            int type = GetType(value);
            if (GetMoreDurable(value))
            {
                return AccessNewToolsBlockManager.Get(type).Durability * 2;
            }
            else
            {
                return AccessNewToolsBlockManager.Get(type).Durability;
            }
        }

        public static float GetCriticalStrikeRate(int value)
        {
            int type = GetType(value);
            return AccessNewToolsBlockManager.Get(type).CriticalStrikeRate;
        }

        public static float GetCriticalStrikeMultiplier(int value)
        {
            int type = GetType(value);
            return AccessNewToolsBlockManager.Get(type).CriticalStrikeMultiplier;
        }

        public static string GetTypeOfTool(int value)
        {
            int type = GetType(value);
            return AccessNewToolsBlockManager.Get(type).TypeOfTool;
        }

        public static float GetAttackDistance(int value)
        {
            int type = GetType(value);
            return AccessNewToolsBlockManager.Get(type).AttackDistance;
        }

        public static float GetRepellingRate(int value)
        {
            int type = GetType(value);
            return AccessNewToolsBlockManager.Get(type).RepellingRate;
        }

        public static float GetVertigoRate(int value)
        {
            int type = GetType(value);
            return AccessNewToolsBlockManager.Get(type).VertigoRate;
        }

        public static float GetBloodSuckingPercentage(int value)
        {
            int type = GetType(value);
            return AccessNewToolsBlockManager.Get(type).BloodSuckingPercentage;
        }

        public static float GetShockRate(int value)
        {
            int type = GetType(value);
            return AccessNewToolsBlockManager.Get(type).ShockRate;
        }

        public static float GetBloodAbsorptionRate(int value)
        {
            int type = GetType(value);
            return AccessNewToolsBlockManager.Get(type).BloodAbsorptionRate;
        }

        public static float GetRepellingDistance(int value)
        {
            int type = GetType(value);
            return AccessNewToolsBlockManager.Get(type).RepellingDistance;
        }

        public static float GetDizzinessTime(int value)
        {
            int type = GetType(value);
            return AccessNewToolsBlockManager.Get(type).DizzinessTime;
        }

        //获取类型
        public static int GetType(int value)
        {
            int data = Terrain.ExtractData(value);
            return data & 0x7F;
        }

        //设置类型，type取值0～127 (即可定义128种类型)
        public static int SetType(int value, int type)
        {
            int data = Terrain.ExtractData(value);
            return (data & -128) | MathUtils.Clamp(type, 0, 127);
        }

        //获取耐久
        public override int GetDamage(int value)
        {
            int data = Terrain.ExtractData(value);
            return (data >> 7) & 0x3FF;
        }

        //设置耐久，damage取值为0～1023
        public override int SetDamage(int value, int damage)
        {
            int data = Terrain.ExtractData(value);
            data &= -130945;
            data |= MathUtils.Clamp(damage, 0, 1023) << 7;
            return Terrain.ReplaceData(value, data);
        }

        //获取更耐久
        public static bool GetMoreDurable(int value)
        {
            int data = Terrain.ExtractData(value);
            return ((data >> 17) & 1) != 0;
        }

        //设置更耐久，type取值0～1 (即可定义2种类型)
        public static int SetMoreDurable(int value, bool state)
        {
            int data = Terrain.ExtractData(value);
            return (data & -131073) | ((state ? 1 : 0) << 17);
        }

        //除了damage的set方法返回的为方块的value值，其他set方法返回方块的data值
        //新枪(data)数据存储: 00 0000 0000 0000 0000
        //从右到左7个位存储类型，往后10位存储耐久，再往后1位储存更耐久的工具
    }
}
//新物品
namespace Game
{
    public class NewArticles : Block
    {
        public static int Index = 302;

        public Texture2D[] m_texture;

        public BlockMesh[] m_standaloneBlockMesh;

        public BoundingBox[][] m_boundingBoxesByLevel;

        public override void Initialize()
        {
            AccessNewArticlesManager.Initialize("AccessNewArticlesManager");
            m_texture = new Texture2D[AccessNewArticlesManager.Data.Count];
            m_standaloneBlockMesh = new BlockMesh[AccessNewArticlesManager.Data.Count];
            m_boundingBoxesByLevel = new BoundingBox[AccessNewArticlesManager.Data.Count][];
            for (int i = 0; i < AccessNewArticlesManager.Data.Count; i++)
            {
                Model model = ContentManager.Get<Model>(AccessNewArticlesManager.Get(i).TheModelPath);
                Matrix boneAbsoluteTransform = BlockMesh.GetBoneAbsoluteTransform(model.FindMesh(AccessNewArticlesManager.Get(i).ModelComponents).ParentBone);
                m_standaloneBlockMesh[i] = new BlockMesh();
                m_standaloneBlockMesh[i].AppendModelMeshPart(model.FindMesh(AccessNewArticlesManager.Get(i).ModelComponents).MeshParts[0], boneAbsoluteTransform * Matrix.CreateTranslation(0.5f, 0.1875f, 0.5f), makeEmissive: false, flipWindingOrder: false, doubleSided: false, flipNormals: false, Color.White);
                m_standaloneBlockMesh[i].TransformTextureCoordinates(Matrix.CreateTranslation((float)(0 % 16) / 16f, (float)(0 / 16) / 16f, 0f));
                m_boundingBoxesByLevel[i] = [new BoundingBox(AccessNewArticlesManager.Get(i).StartingPositionOfCollisionBox, AccessNewArticlesManager.Get(i).EndPositionOfCollisionBox)];
                m_texture[i] = ContentManager.Get<Texture2D>(AccessNewArticlesManager.Get(i).Texture);
            }
            base.Initialize();
        }

        public override void GenerateTerrainVertices(BlockGeometryGenerator generator, TerrainGeometry geometry, int value, int x, int y, int z)
        {
            int type = GetType(value);
            generator.GenerateShadedMeshVertices(this, x, y, z, m_standaloneBlockMesh[type], Color.White, default, null, geometry.GetGeometry(m_texture[type]).SubsetAlphaTest);
        }

        //绘制
        public override void DrawBlock(PrimitivesRenderer3D primitivesRenderer, int value, Color color, float size, ref Matrix matrix, DrawBlockEnvironmentData environmentData)
        {
            int type = GetType(value);
