                m_standaloneBlockMesh[i] = new BlockMesh();
                m_standaloneBlockMesh[i].AppendModelMeshPart(model.FindMesh(AccessNewFoodManager.Get(i).ModelComponents).MeshParts[0], boneAbsoluteTransform * Matrix.CreateTranslation(0.5f, 0.5f, 0.5f), makeEmissive: false, flipWindingOrder: false, doubleSided: false, flipNormals: false, Color.White);
                m_standaloneBlockMesh[i].TransformTextureCoordinates(Matrix.CreateTranslation((float)(0 % 16) / 16f, (float)(0 / 16) / 16f, 0f));
                m_boundingBoxesByLevel[i] = [new BoundingBox(AccessNewFoodManager.Get(i).StartingPositionOfCollisionBox, AccessNewFoodManager.Get(i).EndPositionOfCollisionBox)];
                m_texture[i] = ContentManager.Get<Texture2D>(AccessNewFoodManager.Get(i).Texture);
            }
            base.Initialize();
        }

        public override void GenerateTerrainVertices(BlockGeometryGenerator generator, TerrainGeometry geometry, int value, int x, int y, int z)
        {
            if (IsPlaceable_(value))
            {
                int type = GetType(value);
                generator.GenerateShadedMeshVertices(this, x, y, z, m_standaloneBlockMesh[type], Color.White, default, null, geometry.GetGeometry(m_texture[type]).SubsetAlphaTest);
            }
        }

        //绘制
        public override void DrawBlock(PrimitivesRenderer3D primitivesRenderer, int value, Color color, float size, ref Matrix matrix, DrawBlockEnvironmentData environmentData)
        {
            int type = GetType(value);
            if (GetItIsBetter(value))
            {
                BlocksManager.DrawMeshBlock(primitivesRenderer, m_standaloneBlockMesh[type], m_texture[type], new Color(220, 160, 80), size * 2f, ref matrix, environmentData);
            }
            else
            {
                BlocksManager.DrawMeshBlock(primitivesRenderer, m_standaloneBlockMesh[type], m_texture[type], Color.White, size * 2f, ref matrix, environmentData);
            }
        }

        //在创造背包显示不同类型
        public override IEnumerable<int> GetCreativeValues()
        {
            List<int> list = new List<int>();
            for (int i = 0; i < AccessNewFoodManager.Data.Count; i++)
            {
                int value = Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i));
                list.Add(value);
                if (GetButDelicious(value))
                {
                    value = Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i) + SetItIsBetter(Index, true));
                    list.Add(value);
                }
            }
            return list;
        }

        //给不同类型的命名
        public override string GetDisplayName(SubsystemTerrain subsystemTerrain, int value)
        {
            int type = GetType(value);
            if (GetItIsBetter(value))
            {
                return "更美味的" + AccessNewFoodManager.Get(type).Name;
            }
            else
            {
                return AccessNewFoodManager.Get(type).Name;
            }
        }

        //营养价值
        public override float GetNutritionalValue(int value)
        {
            int type = GetType(value);
            if (GetItIsBetter(value))
            {
                return AccessNewFoodManager.Get(type).NutritionalValue + 0.2f;
            }
            else
            {
                return AccessNewFoodManager.Get(type).NutritionalValue;
            }
        }

        //可美味
        public virtual bool GetButDelicious(int value)
        {
            int type = GetType(value);
            return AccessNewFoodManager.Get(type).ButDelicious;
        }

        //放置
        public override bool IsPlaceable_(int value)
        {
            int type = GetType(value);
            return AccessNewFoodManager.Get(type).IsPlaceable;
        }

        //设置挖掘抗性
        public override float GetDigResilience(int value)
        {
            int type = GetType(value);
            return AccessNewFoodManager.Get(type).DigResilience;
        }

        //设置爆炸抗性
        public override float GetExplosionResilience(int value)
        {
            int type = GetType(value);
            return AccessNewFoodManager.Get(type).ExplosionResilience;
        }

        //设置挖掘方式
        public override BlockDigMethod GetBlockDigMethod(int value)
        {
            int type = GetType(value);
            return AccessNewFoodManager.Get(type).BlockDigMethod;
        }

        //设置掉落物品
        public override void GetDropValues(SubsystemTerrain subsystemTerrain, int oldValue, int newValue, int toolLevel, List<BlockDropValue> dropValues, out bool showDebris)
        {
            int type = GetType(oldValue);
            showDebris = DestructionDebrisScale > 0f;
            if (toolLevel < RequiredToolLevel)
            {
                return;
            }
            BlockDropValue item;
            if (AccessNewFoodManager.Get(type).DefaultDropContent != "")
            {
                int num = (int)AccessNewFoodManager.Get(type).DefaultDropCount;
                if (Random.Bool(AccessNewFoodManager.Get(type).DefaultDropCount - num))
                {
                    num++;
                }
                for (int i = 0; i < (int)AccessNewFoodManager.Get(type).DefaultDropCount; i++)
                {
                    item = new BlockDropValue
                    {
                        Value = CraftingRecipesManager.DecodeResult(AccessNewFoodManager.Get(type).DefaultDropContent),
                        Count = 1
                    };
                    dropValues.Add(item);
                }
            }
        }

        //挖掘粒子
        public override BlockDebrisParticleSystem CreateDebrisParticleSystem(SubsystemTerrain subsystemTerrain, Vector3 position, int value, float strength)
        {
            int type = GetType(value);
            return new BlockDebrisParticleSystem(subsystemTerrain, position, strength, this.DestructionDebrisScale, Color.White, this.GetFaceTextureSlot(1, value), m_texture[type]);
        }

        //碰撞箱
        public override BoundingBox[] GetCustomCollisionBoxes(SubsystemTerrain terrain, int value)
        {
            return m_boundingBoxesByLevel[GetType(value)];
        }

        //给不同类型的描述说明
        public override string GetDescription(int value)
        {
            int type = GetType(value);
            return LanguageControl.Get("NewFood", type + 1);
        }

        //获取类型
        public static int GetType(int value)
        {
            int data = Terrain.ExtractData(value);
            return data & 0x1FFFF;
        }

        //设置类型，type取值0～131071 (即可定义131072种类型)
        public static int SetType(int value, int type)
        {
            int data = Terrain.ExtractData(value);
            return (data & -131072) | MathUtils.Clamp(type, 0, 131071);
        }

        //获取更美味
        public static bool GetItIsBetter(int value)
        {
            int data = Terrain.ExtractData(value);
            return ((data >> 17) & 1) != 0;
        }

        //设置更美味，state取值0～1 (即可定义2种状态)
        public static int SetItIsBetter(int value, bool state)
        {
            int data = Terrain.ExtractData(value);
            return (data & -131073) | ((state ? 1 : 0) << 17);
        }

        //除了damage的set方法返回的为方块的value值，其他set方法返回方块的data值
        //新枪(data)数据存储: 00 0000 0000 0000 0000
        //从右到左17个位存储类型，往后1位储存更美味的食物
    }
}
//新植物
namespace Game
{
    public class NewPlants : Block
    {
        public static int Index = 304;

        public Texture2D[] m_texture;

        public BlockMesh[] m_standaloneBlockMesh;

        public BoundingBox[][] m_boundingBoxesByLevel;

        public override void Initialize()
        {
            AccessNewPlantsManager.Initialize("AccessNewPlantsManager");
            m_texture = new Texture2D[AccessNewPlantsManager.Data.Count * 4];
            m_standaloneBlockMesh = new BlockMesh[AccessNewPlantsManager.Data.Count * 4];
            m_boundingBoxesByLevel = new BoundingBox[AccessNewPlantsManager.Data.Count * 4][];
            for (int a = 0; a < AccessNewPlantsManager.Data.Count; a++)
            {
                for (int i = a * 4; i < (a + 1) * 4; i++)
                {
                    float num = MathUtils.Lerp(0.25f, 1f, ((i - a * 4) + 1) * 0.25f);
                    float num2 = MathUtils.Lerp(0.125f, 0.5f, ((i - a * 4) + 1) * 0.125f);
                    Model model = ContentManager.Get<Model>(AccessNewPlantsManager.Get(a).TheModelPath);
                    Matrix boneAbsoluteTransform = BlockMesh.GetBoneAbsoluteTransform(model.FindMesh(AccessNewPlantsManager.Get(a).ModelComponents).ParentBone);
                    m_standaloneBlockMesh[i] = new BlockMesh();
                    m_standaloneBlockMesh[i].AppendModelMeshPart(model.FindMesh(AccessNewPlantsManager.Get(a).ModelComponents).MeshParts[0], boneAbsoluteTransform * Matrix.CreateScale(num) * Matrix.CreateTranslation(0.5f, num2, 0.5f), makeEmissive: false, flipWindingOrder: false, doubleSided: false, flipNormals: false, Color.White);
                    m_standaloneBlockMesh[i].TransformTextureCoordinates(Matrix.CreateTranslation((float)(0 % 16) / 16f, (float)(0 / 16) / 16f, 0f));
                    m_boundingBoxesByLevel[i] = [new BoundingBox(AccessNewPlantsManager.Get(a).StartingPositionOfCollisionBox, AccessNewPlantsManager.Get(a).EndPositionOfCollisionBox)];
                    m_texture[i] = ContentManager.Get<Texture2D>(AccessNewPlantsManager.Get(a).Texture);
                }
            }
            base.Initialize();
        }

        public override void GenerateTerrainVertices(BlockGeometryGenerator generator, TerrainGeometry geometry, int value, int x, int y, int z)
        {
            int type = GetType(value);
            int theStateOfGrowth = GetTheStateOfGrowth(value);
            Color color = Color.White;
            if (IsGrowth(value) && !GetItemStatus(value) && !GetStateOfTheWild(value))
            {
                if (theStateOfGrowth == 0)
                {
                    color = AccessNewPlantsManager.Get(type).GrowthTheStateOfGrowth1Color;
                }
                else if (theStateOfGrowth == 1)
                {
                    color = AccessNewPlantsManager.Get(type).GrowthTheStateOfGrowth2Color;
                }
                else if (theStateOfGrowth == 2)
                {
                    color = AccessNewPlantsManager.Get(type).GrowthTheStateOfGrowth3Color;
                }
                else
                {
                    color = AccessNewPlantsManager.Get(type).GrowthFruitColor;
                }
                generator.GenerateShadedMeshVertices(this, x, y, z, m_standaloneBlockMesh[type * 4 + theStateOfGrowth], color, default, null, geometry.GetGeometry(m_texture[type * 4 + theStateOfGrowth]).SubsetAlphaTest);
            }
            else
            {
                if (IsWild(value))
                {
                    color = AccessNewPlantsManager.Get(type).WildColor;
                    generator.GenerateShadedMeshVertices(this, x, y, z, m_standaloneBlockMesh[type * 4 + 3], color, default, null, geometry.GetGeometry(m_texture[type * 4 + 3]).SubsetAlphaTest);
                }
                else
                {
                    generator.GenerateShadedMeshVertices(this, x, y, z, m_standaloneBlockMesh[type * 4 + 3], color, default, null, geometry.GetGeometry(m_texture[type * 4 + 3]).SubsetAlphaTest);
                }
            }
        }

        //绘制
        public override void DrawBlock(PrimitivesRenderer3D primitivesRenderer, int value, Color color, float size, ref Matrix matrix, DrawBlockEnvironmentData environmentData)
        {
            int type = GetType(value);
            int theStateOfGrowth = GetTheStateOfGrowth(value);
            if (IsGrowth(value) && !GetItemStatus(value) && !GetStateOfTheWild(value))
            {
                if (theStateOfGrowth == 0)
                {
                    color = AccessNewPlantsManager.Get(type).GrowthTheStateOfGrowth1Color;
                }
                else if (theStateOfGrowth == 1)
                {
                    color = AccessNewPlantsManager.Get(type).GrowthTheStateOfGrowth2Color;
                }
                else if (theStateOfGrowth == 2)
                {
                    color = AccessNewPlantsManager.Get(type).GrowthTheStateOfGrowth3Color;
                }
                else
                {
                    color = AccessNewPlantsManager.Get(type).GrowthFruitColor;
                }
                BlocksManager.DrawMeshBlock(primitivesRenderer, m_standaloneBlockMesh[type * 4 + theStateOfGrowth], m_texture[type * 4 + theStateOfGrowth], color, size * 2f, ref matrix, environmentData);
            }
            else
            {
                if (IsWild(value))
                {
                    color = AccessNewPlantsManager.Get(type).WildColor;
                    BlocksManager.DrawMeshBlock(primitivesRenderer, m_standaloneBlockMesh[type * 4 + 3], m_texture[type * 4 + 3], color, size * 2f, ref matrix, environmentData);
                }
                else
                {
                    BlocksManager.DrawMeshBlock(primitivesRenderer, m_standaloneBlockMesh[type * 4 + 3], m_texture[type * 4 + 3], color, size * 2f, ref matrix, environmentData);
                }
            }
        }

        //在创造背包显示不同类型
        public override IEnumerable<int> GetCreativeValues()
        {
            List<int> list = new List<int>();
            for (int i = 0; i < AccessNewPlantsManager.Data.Count; i++)
            {
                int value = Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i));
                if (IsGrowth(value))
                {
                    for (int a = 0; a < 4; a++)
                    {
                        value = Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i) + SetTheStateOfGrowth(Index, a));
                        list.Add(value);
                    }
                }
                value = Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i) + SetItIsBetter(Index, true));
                list.Add(value);
                if (IsWild(value))
                {
                    value = Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i) + SetStateOfTheWild(Index, true));
                    list.Add(value);
                }
            }
            return list;
        }

        //给不同类型的命名
        public override string GetDisplayName(SubsystemTerrain subsystemTerrain, int value)
        {
            int type = GetType(value);
            int theStateOfGrowth = GetTheStateOfGrowth(value);
            if (IsGrowth(value) && !GetItemStatus(value) && !GetStateOfTheWild(value))
            {
                return AccessNewPlantsManager.Get(type).Name + "(生长状态" + (theStateOfGrowth + 1) + ")";
            }
            if (IsWild(value) && !GetItemStatus(value))
            {
                return AccessNewPlantsManager.Get(type).Name + "(野生)";
            }
            return AccessNewPlantsManager.Get(type).Name;
        }

        //给不同类型的描述说明
        public override string GetDescription(int value)
        {
            int type = GetType(value);
            return LanguageControl.Get("NewPlants", type + 1);
        }

        //设置掉落物品
        public override void GetDropValues(SubsystemTerrain subsystemTerrain, int oldValue, int newValue, int toolLevel, List<BlockDropValue> dropValues, out bool showDebris)
        {
            int type = GetType(oldValue);
            showDebris = DestructionDebrisScale > 0f;
            if (toolLevel < AccessNewPlantsManager.Get(type).RequiredToolLevel)
            {
                return;
            }
            BlockDropValue item;
            if (AccessNewPlantsManager.Get(type).DefaultDropContent != "" || (IsGrowth(oldValue) && !GetItemStatus(oldValue) && !GetStateOfTheWild(oldValue)) && GetTheStateOfGrowth(oldValue) > 2)
            {
                int num = (int)AccessNewPlantsManager.Get(type).DefaultDropCount;
                if (Random.Bool(AccessNewPlantsManager.Get(type).DefaultDropCount - num))
                {
                    num++;
                }
                for (int i = 0; i < (int)AccessNewPlantsManager.Get(type).DefaultDropCount; i++)
                {
                    item = new BlockDropValue
                    {
                        Value = CraftingRecipesManager.DecodeResult(AccessNewPlantsManager.Get(type).DefaultDropContent),
                        Count = 1
                    };
                    dropValues.Add(item);
                }
            }
            if (IsGrowth(oldValue) && !GetItemStatus(oldValue) && !GetStateOfTheWild(oldValue) && GetTheStateOfGrowth(oldValue) > 2)
            {
                int num = (int)AccessNewPlantsManager.Get(type).FruitDefaultDropCount;
                if (Random.Bool(AccessNewPlantsManager.Get(type).FruitDefaultDropCount - num))
                {
                    num++;
                }
                for (int i = 0; i < (int)AccessNewPlantsManager.Get(type).FruitDefaultDropCount; i++)
                {
                    item = new BlockDropValue
                    {
                        Value = CraftingRecipesManager.DecodeResult(AccessNewPlantsManager.Get(type).FruitDefaultDropContent),
                        Count = 1
                    };
                    dropValues.Add(item);
                }
            }
        }

        //设置挖掘抗性
        public override float GetDigResilience(int value)
        {
            int type = GetType(value);
            return AccessNewPlantsManager.Get(type).DigResilience;
        }

        //设置爆炸抗性
        public override float GetExplosionResilience(int value)
        {
            int type = GetType(value);
            return AccessNewPlantsManager.Get(type).ExplosionResilience;
        }

        //设置所需工具等级
        public override float GetRequiredToolLevel(int value)
        {
            int type = GetType(value);
            return AccessNewPlantsManager.Get(type).RequiredToolLevel;
        }

        //设置背包最大堆叠
        public override int GetMaxStacking(int value)
        {
            int type = GetType(value);
            return AccessNewPlantsManager.Get(type).MaxStacking;
        }

        //设置挖掘方式
        public override BlockDigMethod GetBlockDigMethod(int value)
        {
            int type = GetType(value);
            return AccessNewPlantsManager.Get(type).BlockDigMethod;
        }

        //设置是否可以放置
        public override bool IsPlaceable_(int value)
        {
            int type = GetType(value);
            if (GetItemStatus(value))
            {
                return false;
            }
            return AccessNewPlantsManager.Get(type).IsPlaceable;
        }

        public virtual bool IsGrowth(int value)
        {
            int type = GetType(value);
            return AccessNewPlantsManager.Get(type).IsGrowth;
        }

        public virtual bool IsWild(int value)
        {
            int type = GetType(value);
            return AccessNewPlantsManager.Get(type).IsWild;
        }

        //营养价值
        public override float GetNutritionalValue(int value)
        {
            int type = GetType(value);
            return AccessNewPlantsManager.Get(type).NutritionalValue;
        }

        //挖掘粒子
        public override BlockDebrisParticleSystem CreateDebrisParticleSystem(SubsystemTerrain subsystemTerrain, Vector3 position, int value, float strength)
        {
            int type = GetType(value);
            return new BlockDebrisParticleSystem(subsystemTerrain, position, strength, this.DestructionDebrisScale, Color.White, this.GetFaceTextureSlot(1, value), m_texture[type]);
        }

        //碰撞箱
        public override BoundingBox[] GetCustomCollisionBoxes(SubsystemTerrain terrain, int value)
        {
            return m_boundingBoxesByLevel[GetType(value)];
        }

        //获取类型
        public static int GetType(int value)
        {
            int data = Terrain.ExtractData(value);
            return data & 0x3FFF;
        }

        //设置类型，type取值0～16384 (即可定义16385种类型)
        public static int SetType(int value, int type)
        {
            int data = Terrain.ExtractData(value);
            return (data & -16384) | MathUtils.Clamp(type, 0, 16384);
        }

        //获取生长状态
        public static int GetTheStateOfGrowth(int value)
        {
            int data = Terrain.ExtractData(value);
            return (data >> 14) & 0x3;
        }

        //设置生长状态，state取值0～3 (即一种植物的生长状态的范围为0～3)
        public static int SetTheStateOfGrowth(int value, int state)
        {
            int data = Terrain.ExtractData(value);
            return (data & -49153) | (MathUtils.Clamp(state, 0, 3) << 14);
        }

        //获取物品状态
        public static bool GetItemStatus(int value)
        {
            int data = Terrain.ExtractData(value);
            return ((data >> 16) & 1) != 0;
        }

        //设置物品状态state取值0～1 (即可定义2种状态)
        public static int SetItIsBetter(int value, bool state)
        {
            int data = Terrain.ExtractData(value);
            return (data & -65537) | ((state ? 1 : 0) << 16);
        }

        //获取野生状态
        public static bool GetStateOfTheWild(int value)
        {
            int data = Terrain.ExtractData(value);
            return ((data >> 17) & 1) != 0;
        }

        //设置野生状态state取值0～1 (即可定义2种状态)
        public static int SetStateOfTheWild(int value, bool state)
        {
            int data = Terrain.ExtractData(value);
            return (data & -131073) | ((state ? 1 : 0) << 17);
        }

        //除了damage的set方法返回的为方块的value值，其他set方法返回方块的data值
        //新枪(data)数据存储: 00 0000 0000 0000 0000
        //从右到左14个位存储类型，往后2位存储生长状态，再往后1位存储物品状态，最后1位存储物野生状态
    }
}
