            generator.GenerateShadedMeshVertices(this, x, y, z, m_standaloneBlockMesh[type], Color.White, default, null, geometry.GetGeometry(m_texture[type]).SubsetAlphaTest);
        }

        //绘制
        public override void DrawBlock(PrimitivesRenderer3D primitivesRenderer, int value, Color color, float size, ref Matrix matrix, DrawBlockEnvironmentData environmentData)
        {
            int type = GetType(value);
            BlocksManager.DrawMeshBlock(primitivesRenderer, m_standaloneBlockMesh[type], m_texture[type], Color.White, size * 2f, ref matrix, environmentData);
        }

        //在创造背包显示不同类型
        public override IEnumerable<int> GetCreativeValues()
        {
            List<int> list = new List<int>();
            for (int i = 0; i < AccessNewTableManager.Data.Count; i++)
            {
                int value = SetDamage(Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i)), GetDurability(Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i))));
                list.Add(value);
            }
            return list;
        }

        //给不同类型的命名
        public override string GetDisplayName(SubsystemTerrain subsystemTerrain, int value)
        {
            int type = GetType(value);
            return AccessNewTableManager.Get(type).Name;
        }

        //给不同类型的描述说明
        public override string GetDescription(int value)
        {
            int type = GetType(value);
            return LanguageControl.Get("NewTable", type + 1);
        }

        //设置掉落物品
        public override void GetDropValues(SubsystemTerrain subsystemTerrain, int oldValue, int newValue, int toolLevel, List<BlockDropValue> dropValues, out bool showDebris)
        {
            int type = GetType(oldValue);
            showDebris = DestructionDebrisScale > 0f;
            BlockDropValue item;
            if (AccessNewTableManager.Get(type).DefaultDropContent != "")
            {
                int num = (int)AccessNewTableManager.Get(type).DefaultDropCount;
                if (Random.Bool(AccessNewTableManager.Get(type).DefaultDropCount - num))
                {
                    num++;
                }
                for (int i = 0; i < (int)AccessNewTableManager.Get(type).DefaultDropCount; i++)
                {
                    item = new BlockDropValue
                    {
                        Value = CraftingRecipesManager.DecodeResult(AccessNewTableManager.Get(type).DefaultDropContent),
                        Count = 1
                    };
                    dropValues.Add(item);
                }
            }
        }

        //设置挖掘抗性
        public override float GetDigResilience(int value)
        {
            int type = GetType(value);
            return AccessNewTableManager.Get(type).DigResilience;
        }

        //设置爆炸抗性
        public override float GetExplosionResilience(int value)
        {
            int type = GetType(value);
            return AccessNewTableManager.Get(type).ExplosionResilience;
        }

        //设置耐久
        public override int GetDurability(int value)
        {
            int type = GetType(value);
            foreach (AccessTalent accessTalent in AccessTalentManager.Data)
            {
                if (accessTalent.TalentID == 24 && accessTalent.Field > 0)
                {
                    return AccessNewTableManager.Get(type).Durability + (int)(accessTalent.IncreaseInTheUpperLimitOfBuildingDurability + (accessTalent.Level - 1) * 5f);
