                m_standaloneBlockMesh[i] = new BlockMesh();
                m_standaloneBlockMesh[i].AppendModelMeshPart(model.FindMesh(AccessNewCookingTableManager.Get(i).ModelComponents).MeshParts[0], boneAbsoluteTransform * Matrix.CreateTranslation(0.5f, 0.5f, 0.5f), makeEmissive: false, flipWindingOrder: false, doubleSided: false, flipNormals: false, Color.White);
                m_standaloneBlockMesh[i].TransformTextureCoordinates(Matrix.CreateTranslation((float)(0 % 16) / 16f, (float)(0 / 16) / 16f, 0f));
