        public override void GetDropValues(SubsystemTerrain subsystemTerrain, int oldValue, int newValue, int toolLevel, List<BlockDropValue> dropValues, out bool showDebris)
        {
            int type = GetType(oldValue);
            showDebris = DestructionDebrisScale > 0f;
            BlockDropValue item;
            if (AccessNewCookingTableManager.Get(type).DefaultDropContent != "")
            {
                int num = (int)AccessNewCookingTableManager.Get(type).DefaultDropCount;
                if (Random.Bool(AccessNewCookingTableManager.Get(type).DefaultDropCount - num))
                {
                    num++;
                }
                for (int i = 0; i < (int)AccessNewCookingTableManager.Get(type).DefaultDropCount; i++)
                {
                    item = new BlockDropValue
                    {
                        Value = CraftingRecipesManager.DecodeResult(AccessNewCookingTableManager.Get(type).DefaultDropContent),
