//新远程武器
namespace Game
{
    public class NewLongRangeWeaponsBlock : Block
    {
        public static int Index = 308;

        public Texture2D[] m_texture;

        public BlockMesh[] m_standaloneBlockMeshes;

        public override void Initialize()
        {
            AccessNewLongRangeWeaponsManager.Initialize("AccessNewLongRangeWeaponsManager");
            m_texture = new Texture2D[AccessNewLongRangeWeaponsManager.Data.Count * 4];
            m_standaloneBlockMeshes = new BlockMesh[AccessNewLongRangeWeaponsManager.Data.Count * 4];
            for (int a = 0; a < AccessNewLongRangeWeaponsManager.Data.Count; a++)
            {
                Model model = ContentManager.Get<Model>(AccessNewLongRangeWeaponsManager.Get(a).TheModelPath);
                Matrix boneAbsoluteTransform = BlockMesh.GetBoneAbsoluteTransform(model.FindMesh(AccessNewLongRangeWeaponsManager.Get(a).ModelComponents1).ParentBone);
                Matrix boneAbsoluteTransform2 = BlockMesh.GetBoneAbsoluteTransform(model.FindMesh(AccessNewLongRangeWeaponsManager.Get(a).ModelComponents2).ParentBone);
                BlockMesh blockMesh = new();
                blockMesh.AppendModelMeshPart(model.FindMesh(AccessNewLongRangeWeaponsManager.Get(a).ModelComponents1).MeshParts[0], boneAbsoluteTransform * Matrix.CreateTranslation(0f, 0f, 0f), false, false, false, false, Color.White);
                blockMesh.TransformTextureCoordinates(Matrix.CreateTranslation((float)(0 % 16) / 16f, (float)(0 / 16) / 16f, 0f));
                blockMesh.AppendModelMeshPart(model.FindMesh(AccessNewLongRangeWeaponsManager.Get(a).ModelComponents2).MeshParts[0], boneAbsoluteTransform2 * Matrix.CreateTranslation(0f, 0f, 0f), false, false, false, false, Color.White);
                blockMesh.TransformTextureCoordinates(Matrix.CreateTranslation((float)(0 % 16) / 16f, (float)(0 / 16) / 16f, 0f));
                for (int i = a * 4; i < (a + 1) * 4; i++)
                {
                    m_standaloneBlockMeshes[i] = new BlockMesh();
                    m_standaloneBlockMeshes[i].AppendBlockMesh(blockMesh);
                    m_texture[i] = ContentManager.Get<Texture2D>(AccessNewLongRangeWeaponsManager.Get(a).Texture);
                }
            }
            base.Initialize();
        }

        public override void GenerateTerrainVertices(BlockGeometryGenerator generator, TerrainGeometry geometry, int value, int x, int y, int z)
        {
        }

        public override void DrawBlock(PrimitivesRenderer3D primitivesRenderer, int value, Color color, float size, ref Matrix matrix, DrawBlockEnvironmentData environmentData)
        {
            int data = Terrain.ExtractData(value);
            int type = GetType(value);
            int draw = GetDraw(data);
            int arrowType = GetArrowType(data);
            if (GetMoreDurable(value))
            {
                BlocksManager.DrawMeshBlock(primitivesRenderer, m_standaloneBlockMeshes[type * 4 + draw], m_texture[type * 4 + draw], new Color(120, 230, 120), size * 2f, ref matrix, environmentData);
            }
            else
            {
                BlocksManager.DrawMeshBlock(primitivesRenderer, m_standaloneBlockMeshes[type * 4 + draw], m_texture[type * 4 + draw], Color.White, size * 2f, ref matrix, environmentData);
            }
            if (arrowType > 0)
            {
                Matrix matrix2 = Matrix.CreateRotationX(-(float)Math.PI / 2f) * Matrix.CreateTranslation(0f, 0.2f * size, -0.09f * size) * matrix;
                int value2 = Terrain.MakeBlockValue(BlocksManager.GetBlockGeneral<NewProjectiles>().BlockIndex, 0, NewProjectiles.SetType(0, arrowType - 1));
                BlocksManager.GetBlockGeneral<NewProjectiles>().DrawBlock(primitivesRenderer, value2, color, size, ref matrix2, environmentData);
            }
        }

        //在创造背包显示不同类型
        public override IEnumerable<int> GetCreativeValues()
        {
            List<int> list = new List<int>();
            for (int i = 0; i < AccessNewLongRangeWeaponsManager.Data.Count; i++)
            {
                int value = Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i));
                list.Add(value);
                value = Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i) + SetMoreDurable(Index, true));
                list.Add(value);
            }
            return list;
        }

        //给不同类型的命名
        public override string GetDisplayName(SubsystemTerrain subsystemTerrain, int value)
        {
            int type = GetType(value);
            if (GetMoreDurable(value))
            {
                return "更耐久的" + AccessNewLongRangeWeaponsManager.Get(type).Name;
            }
            else
            {
                return AccessNewLongRangeWeaponsManager.Get(type).Name;
            }
        }

        //设置耐久
        public override int GetDurability(int value)
        {
            int type = GetType(value);
            if (GetMoreDurable(value))
            {
                return AccessNewLongRangeWeaponsManager.Get(type).Durability * 2;
            }
            else
            {
                return AccessNewLongRangeWeaponsManager.Get(type).Durability;
            }
        }

        //给不同类型的描述说明
        public override string GetDescription(int value)
        {
            int type = GetType(value);
            return LanguageControl.Get("NewLongRangeWeaponsBlock", type + 1);
        }

        //远程伤害
        public override float GetProjectilePower(int value)
        {
            int type = GetType(value);
            return AccessNewLongRangeWeaponsManager.Get(type).ProjectilePower;
        }

        public static float GetProjectileCriticalStrikeRate(int value)
        {
            int type = GetType(value);
            return AccessNewLongRangeWeaponsManager.Get(type).ProjectileCriticalStrikeRate;
        }

        public static float GetProjectileCriticalStrikeMultiplier(int value)
        {
            int type = GetType(value);
            return AccessNewLongRangeWeaponsManager.Get(type).ProjectileCriticalStrikeMultiplier;
        }

        public override float GetMeleePower(int value)
        {
            int type = GetType(value);
            return AccessNewLongRangeWeaponsManager.Get(type).MeleePower;
        }

        public override float GetMeleeHitProbability(int value)
        {
            int type = GetType(value);
            return AccessNewLongRangeWeaponsManager.Get(type).MeleeHitProbability;
        }

        public static float GetMeleeCriticalStrikeRate(int value)
        {
            int type = GetType(value);
            return AccessNewLongRangeWeaponsManager.Get(type).MeleeCriticalStrikeRate;
        }

        public static float GetMeleeCriticalStrikeMultiplier(int value)
        {
            int type = GetType(value);
            return AccessNewLongRangeWeaponsManager.Get(type).MeleeCriticalStrikeMultiplier;
        }

        public static int GetNumberOfArrowsFired(int value)
        {
            int type = GetType(value);
            return AccessNewLongRangeWeaponsManager.Get(type).NumberOfArrowsFired;
        }

        //获取类型
        public static int GetType(int value)
        {
            int data = Terrain.ExtractData(value);
            return data & 0xF;
        }

        //设置类型，type取值0～15 (即可定义16种类型)
        public static int SetType(int value, int type)
        {
            int data = Terrain.ExtractData(value);
            return (data & -16) | MathUtils.Clamp(type, 0, 15);
        }

        public override int GetDamage(int value) => (Terrain.ExtractData(value) >> 9) & 0xFF;

        public override int SetDamage(int value, int damage)
        {
            int num = Terrain.ExtractData(value);
            num &= -130561;
            num |= Math.Clamp(damage, 0, 255) << 9;
            return Terrain.ReplaceData(value, num);
        }

        public override bool IsSwapAnimationNeeded(int oldValue, int newValue)
        {
            int num = Terrain.ExtractContents(oldValue);
            int data = Terrain.ExtractData(oldValue);
            int data2 = Terrain.ExtractData(newValue);
            if (num == BlockIndex && GetArrowType(data) == GetArrowType(data2))
            {
                return false;
            }
            return true;
        }

        public static int GetArrowType(int data) => (data >> 5) & 0xF;

        public static int SetArrowType(int data, int arrowType) => (data & -481) | (Math.Clamp(arrowType, 0, 15) << 5);

        public static int GetDraw(int data) => (data >> 4) & 0x1;

        public static int SetDraw(int data, int draw) => (data & -17) | (Math.Clamp(draw, 0, 1) << 4);

        //获取更耐久
        public static bool GetMoreDurable(int value)
        {
            int data = Terrain.ExtractData(value);
            return ((data >> 17) & 1) != 0;
        }

        //设置更耐久，type取值0～1 (即可定义2种类型)
        public static int SetMoreDurable(int value, bool state)
        {
            int data = Terrain.ExtractData(value);
            return (data & -131073) | ((state ? 1 : 0) << 17);
        }

        //除了damage的set方法返回的为方块的value值，其他set方法返回方块的data值
        //新枪(data)数据存储: 00 0000 0000 0000 0000
        //从右到左4个位存储类型，往后1位存储弓弦的绘画，再往后4位存储箭的类型，再往后8位存储耐久，最后1位存储更耐久
    }
}
