                m_standaloneBlockMesh[i].TransformTextureCoordinates(Matrix.CreateTranslation((float)(0 % 16) / 16f, (float)(0 / 16) / 16f, 0f));
                m_boundingBoxesByLevel[i] = [new BoundingBox(AccessNewBedManager.Get(i).StartingPositionOfCollisionBox, AccessNewBedManager.Get(i).EndPositionOfCollisionBox)];
                m_texture[i] = ContentManager.Get<Texture2D>(AccessNewBedManager.Get(i).Texture);
            }
            base.Initialize();
