        public override void GenerateTerrainVertices(BlockGeometryGenerator generator, TerrainGeometry geometry, int value, int x, int y, int z)
        {
            int type = GetType(value);
            generator.GenerateShadedMeshVertices(this, x, y, z, m_standaloneBlockMesh[type], Color.White, default, null, geometry.GetGeometry(m_texture[type]).SubsetAlphaTest);
        }

        //绘制
        public override void DrawBlock(PrimitivesRenderer3D primitivesRenderer, int value, Color color, float size, ref Matrix matrix, DrawBlockEnvironmentData environmentData)
        {
            int type = GetType(value);
            BlocksManager.DrawMeshBlock(primitivesRenderer, m_standaloneBlockMesh[type], m_texture[type], Color.White, size * 2f, ref matrix, environmentData);
        }

        //在创造背包显示不同类型
        public override IEnumerable<int> GetCreativeValues()
        {
            List<int> list = new List<int>();
            for (int i = 0; i < AccessNewBedManager.Data.Count; i++)
            {
                int value = SetDamage(Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i)), GetDurability(Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i))));
                list.Add(value);
            }
            return list;
        }

        //给不同类型的命名
        public override string GetDisplayName(SubsystemTerrain subsystemTerrain, int value)
        {
            int type = GetType(value);
            return AccessNewBedManager.Get(type).Name;
        }

        //给不同类型的描述说明
        public override string GetDescription(int value)
        {
            int type = GetType(value);
            return LanguageControl.Get("NewBed", type + 1);
        }

        //设置掉落物品
        public override void GetDropValues(SubsystemTerrain subsystemTerrain, int oldValue, int newValue, int toolLevel, List<BlockDropValue> dropValues, out bool showDebris)
        {
            int type = GetType(oldValue);
            showDebris = DestructionDebrisScale > 0f;
            BlockDropValue item;
            if (AccessNewBedManager.Get(type).DefaultDropContent != "")
            {
                int num = (int)AccessNewBedManager.Get(type).DefaultDropCount;
                if (Random.Bool(AccessNewBedManager.Get(type).DefaultDropCount - num))
                {
                    num++;
                }
                for (int i = 0; i < (int)AccessNewBedManager.Get(type).DefaultDropCount; i++)
                {
                    item = new BlockDropValue
                    {
                        Value = CraftingRecipesManager.DecodeResult(AccessNewBedManager.Get(type).DefaultDropContent),
                        Count = 1
                    };
                    dropValues.Add(item);
                }
            }
        }

        //设置挖掘抗性
        public override float GetDigResilience(int value)
        {
            int type = GetType(value);
            return AccessNewBedManager.Get(type).DigResilience;
        }

        //设置爆炸抗性
        public override float GetExplosionResilience(int value)
        {
            int type = GetType(value);
            return AccessNewBedManager.Get(type).ExplosionResilience;
        }

        //设置耐久
        public override int GetDurability(int value)
        {
            int type = GetType(value);
            foreach (AccessTalent accessTalent in AccessTalentManager.Data)
            {
                if (accessTalent.TalentID == 24 && accessTalent.Field > 0)
                {
                    return AccessNewBedManager.Get(type).Durability + (int)(accessTalent.IncreaseInTheUpperLimitOfBuildingDurability + (accessTalent.Level - 1) * 5f);
                }
            }
            return AccessNewBedManager.Get(type).Durability;
        }

        //挖掘粒子
        public override BlockDebrisParticleSystem CreateDebrisParticleSystem(SubsystemTerrain subsystemTerrain, Vector3 position, int value, float strength)
        {
            int type = GetType(value);
            return new BlockDebrisParticleSystem(subsystemTerrain, position, strength, this.DestructionDebrisScale, Color.White, this.GetFaceTextureSlot(1, value), m_texture[type]);
        }

        //碰撞箱
        public override BoundingBox[] GetCustomCollisionBoxes(SubsystemTerrain terrain, int value)
        {
            return m_boundingBoxesByLevel[GetType(value)];
        }

        //获取类型
        public static int GetType(int value)
        {
            int data = Terrain.ExtractData(value);
            return data & 0x7F;
        }

        //获取损坏度
        public override int GetDamage(int value)
        {
            int data = Terrain.ExtractData(value);
            return (data >> 7) & 0x7FF;
        }

        //设置类型，type取值0～127 (即可定义128种类型)
        public static int SetType(int value, int type)
        {
            int data = Terrain.ExtractData(value);
            return (data & -128) | MathUtils.Clamp(type, 0, 127);
        }

        //设置损坏度，damage取值为0～2047
        public override int SetDamage(int value, int damage)
        {
            int data = Terrain.ExtractData(value);
            data &= -262017;
            data |= MathUtils.Clamp(damage, 0, 2047) << 7;
            return Terrain.ReplaceData(value, data);
        }

        //除了damage的set方法返回的为方块的value值，其他set方法返回方块的data值
        //新枪(data)数据存储: 00 0000 0000 0000 0000
        //从右到左7个位存储类型，往后11位存储耐久
    }
}
//新陷阱
namespace Game
{
    public class NewTrap : Block
    {
        public static int Index = 314;

        public Texture2D[] m_texture;

        public BlockMesh[] m_standaloneBlockMesh;

        public override void Initialize()
        {
            AccessNewTrapManager.Initialize("AccessNewTrapManager");
            m_texture = new Texture2D[AccessNewTrapManager.Data.Count * 12];
            m_standaloneBlockMesh = new BlockMesh[AccessNewTrapManager.Data.Count * 12];
            for (int i = 0; i < AccessNewTrapManager.Data.Count; i++)
            {
                Model model = ContentManager.Get<Model>(AccessNewTrapManager.Get(i).TheModelPath);
                for (int b = 0; b < 4; b++)
                {
                    for (int a = 1; a < 4; a++)
                    {
                        m_standaloneBlockMesh[i * 12 + (a - 1) + b * 3] = new BlockMesh();
                        m_standaloneBlockMesh[i * 12 + (a - 1) + b * 3].AppendModelMeshPart(model.FindMesh("Part1" + a).MeshParts[0], BlockMesh.GetBoneAbsoluteTransform(model.FindMesh("Part1" + a).ParentBone) * Matrix.CreateTranslation(0.5f, 0.1875f, 0.5f), makeEmissive: false, flipWindingOrder: false, doubleSided: false, flipNormals: false, Color.White);
                        m_standaloneBlockMesh[i * 12 + (a - 1) + b * 3].TransformTextureCoordinates(Matrix.CreateTranslation((float)(0 % 16) / 16f, (float)(0 / 16) / 16f, 0f));
                        string texture = AccessNewTrapManager.Get(i).Texture + a;
                        if (b > 0)
                        {
                            m_standaloneBlockMesh[i * 12 + (a - 1) + b * 3].AppendModelMeshPart(model.FindMesh("Part2" + a).MeshParts[0], BlockMesh.GetBoneAbsoluteTransform(model.FindMesh("Part2" + a).ParentBone) * Matrix.CreateTranslation(0.5f, 0.1875f, 0.5f), makeEmissive: false, flipWindingOrder: false, doubleSided: false, flipNormals: false, Color.White);
                            m_standaloneBlockMesh[i * 12 + (a - 1) + b * 3].TransformTextureCoordinates(Matrix.CreateTranslation((float)(0 % 16) / 16f, (float)(0 / 16) / 16f, 0f));
                            texture += b;
                        }
                        m_texture[i * 12 + (a - 1) + b * 3] = ContentManager.Get<Texture2D>(texture);
                    }
                }
            }
            base.Initialize();
        }

        public override void GenerateTerrainVertices(BlockGeometryGenerator generator, TerrainGeometry geometry, int value, int x, int y, int z)
        {
            int type = GetType(value);
            int part1 = GetPart1Damage(value) + 1;
            int part2 = GetPart2Damage(value);
            generator.GenerateShadedMeshVertices(this, x, y, z, m_standaloneBlockMesh[type * 12 + (part1 + part2 * 3) - 1], Color.White, default, null, geometry.GetGeometry(m_texture[type * 12 + (part1 + part2 * 3) - 1]).SubsetAlphaTest);
        }

        //绘制
        public override void DrawBlock(PrimitivesRenderer3D primitivesRenderer, int value, Color color, float size, ref Matrix matrix, DrawBlockEnvironmentData environmentData)
        {
            int type = GetType(value);
            int part1 = GetPart1Damage(value) + 1;
            int part2 = GetPart2Damage(value);
            BlocksManager.DrawMeshBlock(primitivesRenderer, m_standaloneBlockMesh[type * 12 + (part1 + part2 * 3) - 1], m_texture[type * 12 + (part1 + part2 * 3) - 1], Color.White, size * 2f, ref matrix, environmentData);
        }

        //在创造背包显示不同类型
        public override IEnumerable<int> GetCreativeValues()
        {
            List<int> list = new List<int>();
            return list;
        }

        //给不同类型的命名
        public override string GetDisplayName(SubsystemTerrain subsystemTerrain, int value)
        {
            int type = GetType(value);
            return AccessNewTrapManager.Get(type).Name;
        }

        //设置耐久
        public override int GetDurability(int value)
        {
            int part1 = GetPart1Damage(value);
            int part2 = GetPart2Damage(value);
            if (part2 == 0)
            {
                return 0;
            }
            return (int)(((50 + part1 * 25) + (50 + (part2 - 1) * 25)) / 2);
        }

        //设置掉落物品
        public override void GetDropValues(SubsystemTerrain subsystemTerrain, int oldValue, int newValue, int toolLevel, List<BlockDropValue> dropValues, out bool showDebris)
        {
            int type = GetType(oldValue);
            showDebris = DestructionDebrisScale > 0f;
            BlockDropValue item;
            if (AccessNewTrapManager.Get(type).DefaultDropContent != "")
            {
                int num = (int)AccessNewTrapManager.Get(type).DefaultDropCount;
                if (Random.Bool(AccessNewTrapManager.Get(type).DefaultDropCount - num))
                {
                    num++;
                }
                for (int i = 0; i < (int)AccessNewTrapManager.Get(type).DefaultDropCount; i++)
                {
                    item = new BlockDropValue
                    {
                        Value = CraftingRecipesManager.DecodeResult(AccessNewTrapManager.Get(type).DefaultDropContent),
                        Count = 1
                    };
                    dropValues.Add(item);
                }
            }
        }

        //设置挖掘抗性
        public override float GetDigResilience(int value)
        {
            int type = GetType(value);
            return AccessNewTrapManager.Get(type).DigResilience;
        }

        //设置爆炸抗性
        public override float GetExplosionResilience(int value)
        {
            int type = GetType(value);
            return AccessNewTrapManager.Get(type).ExplosionResilience;
        }

        //挖掘粒子
        public override BlockDebrisParticleSystem CreateDebrisParticleSystem(SubsystemTerrain subsystemTerrain, Vector3 position, int value, float strength)
        {
            int type = GetType(value);
            return new BlockDebrisParticleSystem(subsystemTerrain, position, strength, this.DestructionDebrisScale, Color.White, this.GetFaceTextureSlot(1, value), m_texture[type]);
        }

        //获取类型
        public static int GetType(int value)
        {
            int data = Terrain.ExtractData(value);
            return data & 0x7;
        }

        //获取第1部分耐久度
        public static int GetPart1Damage(int value)
        {
            int data = Terrain.ExtractData(value);
            return (data >> 3) & 0x3;
        }

        //获取第2部分耐久度
        public static int GetPart2Damage(int value)
        {
            int data = Terrain.ExtractData(value);
            return (data >> 5) & 0x3;
        }

        //获取损坏度
        public override int GetDamage(int value)
        {
            int data = Terrain.ExtractData(value);
            return (data >> 11) & 0x7F;
        }

        //设置类型，type取值0～7 (即可定义8种类型)
        public static int SetType(int value, int type)
        {
            int data = Terrain.ExtractData(value);
            return (data & -8) | MathUtils.Clamp(type, 0, 7);
        }

        //设置第1部分耐久度，damage取值为0～3
        public static int SetPart1Damage(int value, int damage)
        {
            int data = Terrain.ExtractData(value);
            data &= -25;
            data |= MathUtils.Clamp(damage, 0, 3) << 3;
            return Terrain.ReplaceData(value, data);
        }

        //设置第2部分耐久度，damage取值为0～3
        public static int SetPart2Damage(int value, int damage)
        {
            int data = Terrain.ExtractData(value);
            data &= -97;
            data |= MathUtils.Clamp(damage, 0, 3) << 5;
            return Terrain.ReplaceData(value, data);
        }

        //设置损坏度，damage取值为0～127
        public override int SetDamage(int value, int damage)
        {
            int data = Terrain.ExtractData(value);
            data &= -260097;
            data |= MathUtils.Clamp(damage, 0, 127) << 11;
            return Terrain.ReplaceData(value, data);
        }

        //除了damage的set方法返回的为方块的value值，其他set方法返回方块的data值
        //新枪(data)数据存储: 00 0000 0000 0000 0000
        //从右到左3个位存储类型，往后2位存储第1部分耐久度，再往后2位存储第2部分耐久度，后7位存储耐久度
    }
}
//新箱子
namespace Game
{
    public class NewBox : Block
    {
        public static int Index = 315;

        public Texture2D[] m_texture;

        public BlockMesh[] m_standaloneBlockMesh;

        public BoundingBox[][] m_boundingBoxesByLevel;

        public override void Initialize()
        {
            AccessNewBoxManager.Initialize("AccessNewBoxManager");
            m_texture = new Texture2D[AccessNewBoxManager.Data.Count];
            m_standaloneBlockMesh = new BlockMesh[AccessNewBoxManager.Data.Count];
            m_boundingBoxesByLevel = new BoundingBox[AccessNewBoxManager.Data.Count][];
            for (int i = 0; i < AccessNewBoxManager.Data.Count; i++)
            {
                Model model = ContentManager.Get<Model>(AccessNewBoxManager.Get(i).TheModelPath);
                Matrix boneAbsoluteTransform = BlockMesh.GetBoneAbsoluteTransform(model.FindMesh(AccessNewBoxManager.Get(i).ModelComponents).ParentBone);
                m_standaloneBlockMesh[i] = new BlockMesh();
                m_standaloneBlockMesh[i].AppendModelMeshPart(model.FindMesh(AccessNewBoxManager.Get(i).ModelComponents).MeshParts[0], boneAbsoluteTransform * Matrix.CreateTranslation(0.5f, 0.5f, 0.5f), makeEmissive: false, flipWindingOrder: false, doubleSided: false, flipNormals: false, Color.White);
                m_standaloneBlockMesh[i].TransformTextureCoordinates(Matrix.CreateTranslation((float)(0 % 16) / 16f, (float)(0 / 16) / 16f, 0f));
                m_boundingBoxesByLevel[i] = [new BoundingBox(AccessNewBoxManager.Get(i).StartingPositionOfCollisionBox, AccessNewBoxManager.Get(i).EndPositionOfCollisionBox)];
                m_texture[i] = ContentManager.Get<Texture2D>(AccessNewBoxManager.Get(i).Texture);
            }
            base.Initialize();
        }

        public override void GenerateTerrainVertices(BlockGeometryGenerator generator, TerrainGeometry geometry, int value, int x, int y, int z)
        {
            int type = GetType(value);
            generator.GenerateShadedMeshVertices(this, x, y, z, m_standaloneBlockMesh[type], Color.White, default, null, geometry.GetGeometry(m_texture[type]).SubsetAlphaTest);
        }

        //绘制
        public override void DrawBlock(PrimitivesRenderer3D primitivesRenderer, int value, Color color, float size, ref Matrix matrix, DrawBlockEnvironmentData environmentData)
        {
            int type = GetType(value);
            BlocksManager.DrawMeshBlock(primitivesRenderer, m_standaloneBlockMesh[type], m_texture[type], Color.White, size * 2f, ref matrix, environmentData);
        }

        //在创造背包显示不同类型
        public override IEnumerable<int> GetCreativeValues()
        {
            List<int> list = new List<int>();
            for (int i = 0; i < AccessNewBoxManager.Data.Count; i++)
            {
                int value = SetDamage(Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i)), GetDurability(Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i))));
                list.Add(value);
            }
            return list;
        }

        //给不同类型的命名
        public override string GetDisplayName(SubsystemTerrain subsystemTerrain, int value)
        {
            int type = GetType(value);
            return AccessNewBoxManager.Get(type).Name;
        }

        //给不同类型的描述说明
        public override string GetDescription(int value)
        {
            int type = GetType(value);
            return LanguageControl.Get("NewBox", type + 1);
        }

        //设置掉落物品
        public override void GetDropValues(SubsystemTerrain subsystemTerrain, int oldValue, int newValue, int toolLevel, List<BlockDropValue> dropValues, out bool showDebris)
        {
            int type = GetType(oldValue);
            showDebris = DestructionDebrisScale > 0f;
            BlockDropValue item;
            if (AccessNewBoxManager.Get(type).DefaultDropContent != "")
            {
                int num = (int)AccessNewBoxManager.Get(type).DefaultDropCount;
                if (Random.Bool(AccessNewBoxManager.Get(type).DefaultDropCount - num))
                {
                    num++;
                }
                for (int i = 0; i < (int)AccessNewBoxManager.Get(type).DefaultDropCount; i++)
                {
                    item = new BlockDropValue
                    {
                        Value = CraftingRecipesManager.DecodeResult(AccessNewBoxManager.Get(type).DefaultDropContent),
                        Count = 1
                    };
                    dropValues.Add(item);
                }
            }
        }

        //设置挖掘抗性
        public override float GetDigResilience(int value)
        {
            int type = GetType(value);
            return AccessNewBoxManager.Get(type).DigResilience;
        }

        //设置爆炸抗性
        public override float GetExplosionResilience(int value)
        {
            int type = GetType(value);
            return AccessNewBoxManager.Get(type).ExplosionResilience;
        }

        //挖掘粒子
        public override BlockDebrisParticleSystem CreateDebrisParticleSystem(SubsystemTerrain subsystemTerrain, Vector3 position, int value, float strength)
        {
            int type = GetType(value);
            return new BlockDebrisParticleSystem(subsystemTerrain, position, strength, this.DestructionDebrisScale, Color.White, this.GetFaceTextureSlot(1, value), m_texture[type]);
        }

        //碰撞箱
        public override BoundingBox[] GetCustomCollisionBoxes(SubsystemTerrain terrain, int value)
        {
            return m_boundingBoxesByLevel[GetType(value)];
        }

        //获取类型
        public static int GetType(int value)
        {
            int data = Terrain.ExtractData(value);
            return data & 0xFF;
        }

        //设置类型，type取值0～255 (即可定义256种类型)
        public static int SetType(int value, int type)
        {
            int data = Terrain.ExtractData(value);
            return (data & -256) | MathUtils.Clamp(type, 0, 255);
        }

        //除了damage的set方法返回的为方块的value值，其他set方法返回方块的data值
        //新枪(data)数据存储: 00 0000 0000 0000 0000
        //从右到左8个位存储类型，往后
    }
}
