            base.Initialize();
        }

        public override void GenerateTerrainVertices(BlockGeometryGenerator generator, TerrainGeometry geometry, int value, int x, int y, int z)
        {
        }

        //绘制
        public override void DrawBlock(PrimitivesRenderer3D primitivesRenderer, int value, Color color, float size, ref Matrix matrix, DrawBlockEnvironmentData environmentData)
        {
            int type = GetType(value);
            if (GetMoreDurable(value))
            {
                BlocksManager.DrawMeshBlock(primitivesRenderer, m_standaloneBlockMesh[type], m_texture[type], new Color(120, 230, 120), size * 2f, ref matrix, environmentData);
            }
            else
            {
                BlocksManager.DrawMeshBlock(primitivesRenderer, m_standaloneBlockMesh[type], m_texture[type], Color.White, size * 2f, ref matrix, environmentData);
            }
        }

        //在创造背包显示不同类型
        public override IEnumerable<int> GetCreativeValues()
        {
            List<int> list = new List<int>();
            for (int i = 0; i < AccessMusketNewBlockManager.Data.Count; i++)
            {
                int value = Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i));
                list.Add(value);
                value = Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i) + SetMoreDurable(Index, true));
                list.Add(value);
            }
            return list;
        }

        //给不同类型的命名
        public override string GetDisplayName(SubsystemTerrain subsystemTerrain, int value)
        {
            int type = GetType(value);
            if (GetMoreDurable(value))
            {
                return "更耐久的" + AccessMusketNewBlockManager.Get(type).Name;
            }
            else
            {
                return AccessMusketNewBlockManager.Get(type).Name;
            }
        }

        //给不同类型的描述说明
        public override string GetDescription(int value)
        {
            int type = GetType(value);
            return LanguageControl.Get("MusketNewBlock", type + 1);
        }

        //获取类型
        public static int GetType(int value)
        {
            int data = Terrain.ExtractData(value);
            return data & 0x1FFF;
        }

        //设置类型，type取值0～8191 (即可定义8192种类型)
        public static int SetType(int value, int type)
        {
            int data = Terrain.ExtractData(value);
            return (data & -8192) | MathUtils.Clamp(type, 0, 8191);
        }

        //获取损坏度
        public override int GetDamage(int value)
        {
            int data = Terrain.ExtractData(value);
            return (data >> 13) & 0xF;
        }

        //设置损坏度，damage取值为0～15
        public override int SetDamage(int value, int damage)
        {
            int data = Terrain.ExtractData(value);
            data &= -122881;
            data |= MathUtils.Clamp(damage, 0, 15) << 13;
            return Terrain.ReplaceData(value, data);
        }

        //获取更耐久
        public static bool GetMoreDurable(int value)
        {
            int data = Terrain.ExtractData(value);
            return ((data >> 17) & 1) != 0;
        }

        //设置更耐久，type取值0～1 (即可定义2种类型)
        public static int SetMoreDurable(int value, bool state)
        {
            int data = Terrain.ExtractData(value);
            return (data & -131073) | ((state ? 1 : 0) << 17);
        }

        //除了damage的set方法返回的为方块的value值，其他set方法返回方块的data值
        //新枪(data)数据存储: 00 0000 0000 0000 0000
        //从右到左13个位存储类型，往后4位储存耐久，最后1位存储更耐久
    }
    public class MusketParameter
    {
        public string Bulletvalue;         //枪对应子弹的方块完整值
        public float Bulletspeed;       //枪对应子弹的射速（对应射程）
        public float Impulse;           //后坐力影响因素值，该值越大，后坐力越大
        public bool Emission;           //是否持续发射
        public bool Gunsmoke;           //是否冒烟
        public float Damage;            //损坏度影响因素值，该值越大，损坏程度越大
        public float Intervaltime;      //连续发射时子弹的间隔时间
        public bool InfiniteBullet;

        //定义各类型枪的固定属性
        public static MusketParameter GetMusketParameter(int type)
        {
            MusketParameter musketParameter = new MusketParameter();
            musketParameter.Bulletvalue = AccessMusketNewBlockManager.Get(type).Bulletvalue;
            musketParameter.Bulletspeed = AccessMusketNewBlockManager.Get(type).Bulletspeed;
            musketParameter.Emission = AccessMusketNewBlockManager.Get(type).Emission;
            musketParameter.Gunsmoke = AccessMusketNewBlockManager.Get(type).Gunsmoke;
            musketParameter.Impulse = AccessMusketNewBlockManager.Get(type).Impulse;
            musketParameter.Damage = AccessMusketNewBlockManager.Get(type).Damage;
            musketParameter.Intervaltime = AccessMusketNewBlockManager.Get(type).Intervaltime;
            musketParameter.InfiniteBullet = AccessMusketNewBlockManager.Get(type).InfiniteBullet;

            return musketParameter;
        }
    }
}
