            m_boundingBoxesByLevel = new BoundingBox[AccessNewArchitectureManager.Data.Count][];
            for (int i = 0; i < AccessNewArchitectureManager.Data.Count; i++)
            {
                Model model = ContentManager.Get<Model>(AccessNewArchitectureManager.Get(i).TheModelPath);
                Matrix boneAbsoluteTransform = BlockMesh.GetBoneAbsoluteTransform(model.FindMesh(AccessNewArchitectureManager.Get(i).ModelComponents).ParentBone) * Matrix.CreateScale(AccessNewArchitectureManager.Get(i).ModelScale);
                Matrix m = Matrix.CreateRotationX(AccessNewArchitectureManager.Get(i).ModelRotation.X * (float)Math.PI / 180f) * Matrix.CreateRotationY(AccessNewArchitectureManager.Get(i).ModelRotation.Y * (float)Math.PI / 180f) * Matrix.CreateRotationZ(AccessNewArchitectureManager.Get(i).ModelRotation.Z * (float)Math.PI / 180f);
                m_standaloneBlockMesh[i] = new BlockMesh();
                m_standaloneBlockMesh[i].AppendModelMeshPart(model.FindMesh(AccessNewArchitectureManager.Get(i).ModelComponents).MeshParts[0], boneAbsoluteTransform * m * Matrix.CreateTranslation(0.5f, 0.1875f, 0.5f) * Matrix.CreateTranslation(AccessNewArchitectureManager.Get(i).ModelAdditionalPositionOffset.X, AccessNewArchitectureManager.Get(i).ModelAdditionalPositionOffset.Y, AccessNewArchitectureManager.Get(i).ModelAdditionalPositionOffset.Z), makeEmissive: false, flipWindingOrder: false, doubleSided: false, flipNormals: false, Color.White);
                m_standaloneBlockMesh[i].TransformTextureCoordinates(Matrix.CreateTranslation((float)(0 % 16) / 16f, (float)(0 / 16) / 16f, 0f));
                m_boundingBoxesByLevel[i] = [new BoundingBox(new Vector3(MathUtils.Clamp((AccessNewArchitectureManager.Get(i).StartingPositionOfCollisionBox.X + AccessNewArchitectureManager.Get(i).ModelAdditionalPositionOffset.X) * AccessNewArchitectureManager.Get(i).ModelScale.X, 0, 1), MathUtils.Clamp((AccessNewArchitectureManager.Get(i).StartingPositionOfCollisionBox.Y + AccessNewArchitectureManager.Get(i).ModelAdditionalPositionOffset.Y) * AccessNewArchitectureManager.Get(i).ModelScale.Y, 0, 1), MathUtils.Clamp((AccessNewArchitectureManager.Get(i).StartingPositionOfCollisionBox.Z + AccessNewArchitectureManager.Get(i).ModelAdditionalPositionOffset.Z) * AccessNewArchitectureManager.Get(i).ModelScale.Z, 0, 1)), new Vector3(MathUtils.Clamp((AccessNewArchitectureManager.Get(i).EndPositionOfCollisionBox.X + AccessNewArchitectureManager.Get(i).ModelAdditionalPositionOffset.X) * AccessNewArchitectureManager.Get(i).ModelScale.X, 0, 1), MathUtils.Clamp((AccessNewArchitectureManager.Get(i).EndPositionOfCollisionBox.Y + AccessNewArchitectureManager.Get(i).ModelAdditionalPositionOffset.Y) * AccessNewArchitectureManager.Get(i).ModelScale.Y, 0, 1), MathUtils.Clamp((AccessNewArchitectureManager.Get(i).EndPositionOfCollisionBox.Z + AccessNewArchitectureManager.Get(i).ModelAdditionalPositionOffset.Z) * AccessNewArchitectureManager.Get(i).ModelScale.Z, 0, 1)))];
                m_texture[i] = ContentManager.Get<Texture2D>(AccessNewArchitectureManager.Get(i).Texture);
            }
            base.Initialize();
        }

