namespace Game
{
    public class NewMaterialBox : Block
    {
        public static int Index = 321;

        public Texture2D[] m_texture;

        public BlockMesh[] m_standaloneBlockMesh;

        public BoundingBox[][] m_boundingBoxesByLevel;

        public override void Initialize()
        {
            AccessNewMaterialBoxManager.Initialize("AccessNewMaterialBoxManager");
            m_texture = new Texture2D[AccessNewMaterialBoxManager.Data.Count * 4];
            m_standaloneBlockMesh = new BlockMesh[AccessNewMaterialBoxManager.Data.Count * 4];
            m_boundingBoxesByLevel = new BoundingBox[AccessNewMaterialBoxManager.Data.Count * 4][];
            for (int i = 0; i < AccessNewMaterialBoxManager.Data.Count; i++)
            {
                for (int a = 0; a < 4; a++)
                {
                    Model model = ContentManager.Get<Model>(AccessNewMaterialBoxManager.Get(i).TheModelPath);
                    Matrix boneAbsoluteTransform = BlockMesh.GetBoneAbsoluteTransform(model.FindMesh(AccessNewMaterialBoxManager.Get(i).ModelComponents).ParentBone);
                    Matrix m = Matrix.CreateRotationY((a - 1) * (float)Math.PI / 2f);
                    m_standaloneBlockMesh[i * 4 + a] = new BlockMesh();
                    m_standaloneBlockMesh[i * 4 + a].AppendModelMeshPart(model.FindMesh(AccessNewMaterialBoxManager.Get(i).ModelComponents).MeshParts[0], boneAbsoluteTransform * m * Matrix.CreateTranslation(0.5f, 0.5f, 0.5f), makeEmissive: false, flipWindingOrder: false, doubleSided: false, flipNormals: false, Color.White);
                    m_standaloneBlockMesh[i * 4 + a].TransformTextureCoordinates(Matrix.CreateTranslation((float)(0 % 16) / 16f, (float)(0 / 16) / 16f, 0f));
                    m_boundingBoxesByLevel[i * 4 + a] = [new BoundingBox(AccessNewMaterialBoxManager.Get(i).StartingPositionOfCollisionBox, AccessNewMaterialBoxManager.Get(i).EndPositionOfCollisionBox)];
                    m_texture[i * 4 + a] = ContentManager.Get<Texture2D>(AccessNewMaterialBoxManager.Get(i).Texture);
                }
            }
            base.Initialize();
        }

        public override void GenerateTerrainVertices(BlockGeometryGenerator generator, TerrainGeometry geometry, int value, int x, int y, int z)
        {
            int type = GetType(value);
            int direction = GetDirection(value);
            generator.GenerateShadedMeshVertices(this, x, y, z, m_standaloneBlockMesh[type * 4 + direction], Color.White, default, null, geometry.GetGeometry(m_texture[type * 4 + direction]).SubsetAlphaTest);
        }

        //绘制
        public override void DrawBlock(PrimitivesRenderer3D primitivesRenderer, int value, Color color, float size, ref Matrix matrix, DrawBlockEnvironmentData environmentData)
        {
            int type = GetType(value);
            int direction = GetDirection(value);
            BlocksManager.DrawMeshBlock(primitivesRenderer, m_standaloneBlockMesh[type * 4 + direction], m_texture[type * 4 + direction], Color.White, size * 2f, ref matrix, environmentData);
        }

        //在创造背包显示不同类型
        public override IEnumerable<int> GetCreativeValues()
        {
            List<int> list = new List<int>();
            for (int i = 0; i < AccessNewMaterialBoxManager.Data.Count; i++)
            {
                for (int a = 0; a < 4; a++)
                {
                    int value = Terrain.MakeBlockValue(BlockIndex, 0, SetType(Index, i) + SetDirection(Index, a));
                    list.Add(value);
                }
            }
            return list;
        }

        //给不同类型的命名
        public override string GetDisplayName(SubsystemTerrain subsystemTerrain, int value)
        {
            int type = GetType(value);
            StringBuilder sb = new StringBuilder();
            for (int a = 0; a < AccessNewMaterialBoxManager.Get(type).DroppedItems.Length; a++)
            {
                string[] Items = AccessNewMaterialBoxManager.Get(type).DroppedItems[a].Split(',');
                string[] safeParts = Items[0].Split(':');
                string beforeChar = safeParts[0];
                string afterChar = safeParts.Length > 1 ? safeParts[1] : string.Empty;
                sb.Append(BlocksManager.Blocks[Terrain.ExtractContents(CraftingRecipesManager.DecodeResult(Items[0]))].GetDisplayName(null, CraftingRecipesManager.DecodeResult(Items[0])) + "X" + Items[1] + "到" + Items[2]);
                if (a != AccessNewMaterialBoxManager.Get(type).DroppedItems.Length - 1)
                {
                    sb.Append("，");
                }
            }
            return AccessNewMaterialBoxManager.Get(type).Name + "(" + sb.ToString() + ")";
        }

        //给不同类型的描述说明
        public override string GetDescription(int value)
        {
            int type = GetType(value);
            StringBuilder sb = new StringBuilder();
            for (int a = 0; a < AccessNewMaterialBoxManager.Get(type).DroppedItems.Length; a++)
            {
                string[] Items = AccessNewMaterialBoxManager.Get(type).DroppedItems[a].Split(',');
                string[] safeParts = Items[0].Split(':');
                string beforeChar = safeParts[0];
                string afterChar = safeParts.Length > 1 ? safeParts[1] : string.Empty;
                sb.Append(BlocksManager.Blocks[Terrain.ExtractContents(CraftingRecipesManager.DecodeResult(Items[0]))].GetDisplayName(null, CraftingRecipesManager.DecodeResult(Items[0])) + "X" + Items[1] + "到" + Items[2]);
                if (a != AccessNewMaterialBoxManager.Get(type).DroppedItems.Length - 1)
                {
                    sb.Append("，");
                }
            }
            return "挖掘获得" + sb.ToString();
        }

        //设置掉落物品
        public override void GetDropValues(SubsystemTerrain subsystemTerrain, int oldValue, int newValue, int toolLevel, List<BlockDropValue> dropValues, out bool showDebris)
        {
            showDebris = DestructionDebrisScale > 0f;
            int type = GetType(oldValue);
            if (toolLevel < AccessNewMaterialBoxManager.Get(type).RequiredToolLevel)
            {
                return;
            }
            BlockDropValue item;
            for (int b = 0; b < AccessNewMaterialBoxManager.Get(type).DroppedItems.Length; b++)
            {
                string[] Items = AccessNewMaterialBoxManager.Get(type).DroppedItems[b].Split(',');
                int Quantity = Random.Int(int.Parse(Items[1]), int.Parse(Items[2]));
                for (int i = 0; i < Quantity; i++)
                {
                    item = new BlockDropValue
                    {
                        Value = CraftingRecipesManager.DecodeResult(Items[0]),
                        Count = 1
                    };
                    dropValues.Add(item);
                }
            }
        }

        //设置挖掘抗性
        public override float GetDigResilience(int value)
        {
            int type = GetType(value);
            return AccessNewMaterialBoxManager.Get(type).DigResilience;
        }

        //设置爆炸抗性
        public override float GetExplosionResilience(int value)
        {
            int type = GetType(value);
            return AccessNewMaterialBoxManager.Get(type).ExplosionResilience;
        }

        //设置所需工具等级
