        {
            int type = GetType(value);
            return AccessNewMaterialBoxManager.Get(type).RequiredToolLevel;
        }

        //设置背包最大堆叠
        public override int GetMaxStacking(int value)
        {
            int type = GetType(value);
            return AccessNewMaterialBoxManager.Get(type).MaxStacking;
        }

        //设置挖掘方式
        public override BlockDigMethod GetBlockDigMethod(int value)
        {
            int type = GetType(value);
            return AccessNewMaterialBoxManager.Get(type).BlockDigMethod;
        }

        //挖掘粒子
        public override BlockDebrisParticleSystem CreateDebrisParticleSystem(SubsystemTerrain subsystemTerrain, Vector3 position, int value, float strength)
        {
            int type = GetType(value);
            return new BlockDebrisParticleSystem(subsystemTerrain, position, strength, this.DestructionDebrisScale, Color.White, this.GetFaceTextureSlot(1, value), m_texture[type]);
        }

        //碰撞箱
        public override BoundingBox[] GetCustomCollisionBoxes(SubsystemTerrain terrain, int value)
        {
            return m_boundingBoxesByLevel[GetType(value)];
        }

        //获取类型
        public static int GetType(int value)
        {
            int data = Terrain.ExtractData(value);
            return data & 0xFFFF;
        }

        //设置类型，type取值0～65535 (即可定义65536种类型)
        public static int SetType(int value, int type)
        {
            int data = Terrain.ExtractData(value);
            return (data & -65536) | MathUtils.Clamp(type, 0, 65535);
        }

        //获取方向
        public static int GetDirection(int value)
        {
            int data = Terrain.ExtractData(value);
            return (data >> 16) & 0x3;
        }

        //设置方向，type取值0～3 (即可定义4种类型)
        public static int SetDirection(int value, int direction)
        {
            int data = Terrain.ExtractData(value);
            return (data & -196609) | (MathUtils.Clamp(direction, 0, 3) << 16);
        }

        //除了damage的set方法返回的为方块的value值，其他set方法返回方块的data值
        //新枪(data)数据存储: 00 0000 0000 0000 0000
        //从右到左16个位存储类型，往后2位存储方向
    }
}
//新水方块
namespace Game
{
    public class NewWaterBlock : FluidBlock
    {
        public static int Index = 322;

        public new static int MaxLevel = 7;

        public NewWaterBlock() : base(MaxLevel) => CanBeBuiltIntoFurniture = true;

        public override void GenerateTerrainVertices(BlockGeometryGenerator generator, TerrainGeometry geometry, int value, int x, int y, int z)
        {
            int type = GetType(value);
            Color OverlayColors = AccessNewWaterBlockManager.Get(type).OverlayColors;
            Color Lookup = BlockColorsMap.Water.Lookup(generator.Terrain, x, y, z);
            Color sideColor;
            Color color = sideColor = new Color((OverlayColors.R + Lookup.R) / 2, (OverlayColors.G + Lookup.G) / 2, (OverlayColors.B + Lookup.B) / 2, (byte.MaxValue + Lookup.A) / 2);
            Color topColor = color;
            topColor.A = 0;
            GenerateFluidTerrainVertices(generator, value, x, y, z, sideColor, topColor, geometry.TransparentSubsetsByFace);
        }

        //获取类型
        public static int GetType(int value)
        {
            int data = Terrain.ExtractData(value);
            return (data >> 5) & 0x1FFF;
        }

        //设置类型，type取值0～8191 (即可定义8192种类型)
        public static int SetType(int value, int type)
        {
            int data = Terrain.ExtractData(value);
            return (data & -262113) | MathUtils.Clamp(type, 0, 8191);
        }
    }
}
