        public override void TerrainContentsGenerator24Initialize(ITerrainContentsGenerator terrainContentsGenerator, SubsystemTerrain subsystemTerrain)
        {
            if (terrainContentsGenerator is TerrainContentsGenerator24 generator24)
            {
                terrainContentsGenerator24 = generator24;
                m_subsystemTerrain = subsystemTerrain;
                var gameInfo = subsystemTerrain.Project.FindSubsystem<SubsystemGameInfo>();
                string worldName = gameInfo?.DirectoryName;

                int index = -1;
                WorldName = "";
                for (int i = 0; i < 3; i++)
                {
                    index = worldName.IndexOf('/', index + 1);
                    if (index == -1) WorldName = "MainWorld";
                }
                if (WorldName == "")
                    WorldName = worldName.Substring(index + 1);

                ChunkGenerationStep GenerateSurfaceParameters = generator24.ChunkGenerationStep1.Find(step => (step.GenerateOrder == 1000));
                ChunkGenerationStep GenerateTerrain = generator24.ChunkGenerationStep1.Find(step => (step.GenerateOrder == 2000));
                ChunkGenerationStep GenerateSurfaceParameters2 = generator24.ChunkGenerationStep2.Find(step => (step.GenerateOrder == 1000));
                ChunkGenerationStep GenerateTerrain2 = generator24.ChunkGenerationStep2.Find(step => (step.GenerateOrder == 2000));
                ChunkGenerationStep GenerateCaves = generator24.ChunkGenerationStep3.Find(step => (step.GenerateOrder == 100));
                ChunkGenerationStep GeneratePockets = generator24.ChunkGenerationStep3.Find(step => (step.GenerateOrder == 200));
                ChunkGenerationStep MineralsGeneration = generator24.ChunkGenerationStep3.Find(step => (step.GenerateOrder == 300));
                ChunkGenerationStep GenerateSurface = generator24.ChunkGenerationStep3.Find(step => (step.GenerateOrder == 400));
                ChunkGenerationStep PropagateFluidsDownwards = generator24.ChunkGenerationStep3.Find(step => (step.GenerateOrder == 500));
                ChunkGenerationStep GrassAndPlantsGenerate = generator24.ChunkGenerationStep4.Find(step => (step.GenerateOrder == 100));
                ChunkGenerationStep LogsGeneration = generator24.ChunkGenerationStep4.Find(step => (step.GenerateOrder == 200));
                ChunkGenerationStep TreesGeneration = generator24.ChunkGenerationStep4.Find(step => (step.GenerateOrder == 300));
                ChunkGenerationStep GenerateCacti = generator24.ChunkGenerationStep4.Find(step => (step.GenerateOrder == 400));
                ChunkGenerationStep PumpkinsGeneration = generator24.ChunkGenerationStep4.Find(step => (step.GenerateOrder == 500));
                ChunkGenerationStep KelpGeneration = generator24.ChunkGenerationStep4.Find(step => (step.GenerateOrder == 600));
                ChunkGenerationStep SeagrassGeneration = generator24.ChunkGenerationStep4.Find(step => (step.GenerateOrder == 700));
                ChunkGenerationStep BottomSuckersGeneration = generator24.ChunkGenerationStep4.Find(step => (step.GenerateOrder == 800));
                ChunkGenerationStep TrapsGeneration = generator24.ChunkGenerationStep4.Find(step => (step.GenerateOrder == 900));
                ChunkGenerationStep IvyGeneration = generator24.ChunkGenerationStep4.Find(step => (step.GenerateOrder == 1000));
                ChunkGenerationStep GravesGeneration = generator24.ChunkGenerationStep4.Find(step => (step.GenerateOrder == 1100));
                ChunkGenerationStep CairnsGeneration = generator24.ChunkGenerationStep4.Find(step => (step.GenerateOrder == 1200));
                ChunkGenerationStep GenerateSnowAndIce = generator24.ChunkGenerationStep4.Find(step => (step.GenerateOrder == 1300));
                ChunkGenerationStep GenerateBedrockAndAir = generator24.ChunkGenerationStep4.Find(step => (step.GenerateOrder == 1400));
                ChunkGenerationStep UpdateFluidIsTop = generator24.ChunkGenerationStep4.Find(step => (step.GenerateOrder == 1500));

                if (WorldName == "MainWorld")
                {
                    generator24.TGOceanSlope = 0.002f;
                    generator24.TGOceanSlopeVariation = 0.001f;
                    generator24.TGIslandsFrequency = 0.005f;
                    generator24.TGDensityBias = 48f;
                    generator24.TGHeightBias = 0.8f;
                    generator24.TGRiversStrength = 0.8f;
                    generator24.TGMountainsStrength = 180f;
                    generator24.TGMountainRangeFreq = 0.0004f;
                    generator24.TGMountainsPercentage = 0.07f;
                    TerrainContentsGenerator24.TGMountainsDetailFreq = 0.004f;
                    TerrainContentsGenerator24.TGMountainsDetailOctaves = 4;
                    TerrainContentsGenerator24.TGMountainsDetailPersistence = 0.6f;
                    generator24.TGHillsPercentage = 0.35f;
                    generator24.TGHillsStrength = 40f;
                    generator24.TGHillsOctaves = 2;
                    generator24.TGHillsFrequency = 0.01f;
                    generator24.TGHillsPersistence = 0.55f;
                    generator24.TGTurbulenceStrength = 65f;
                    generator24.TGTurbulenceOctaves = 2;
                    generator24.TGTurbulencePersistence = 0.6f;
                    generator24.TGTurbulenceZero = 0.8f;
                    TerrainContentsGenerator24.TGSurfaceMultiplier = 1.8f;

                    generator24.ChunkGenerationStep3.Remove(MineralsGeneration);
                    generator24.ChunkGenerationStep4.Remove(LogsGeneration);
                    generator24.ChunkGenerationStep4.Remove(TreesGeneration);
                    generator24.ChunkGenerationStep4.Remove(PumpkinsGeneration);
                    generator24.ChunkGenerationStep4.Remove(KelpGeneration);
                    generator24.ChunkGenerationStep4.Remove(KelpGeneration);
                    generator24.ChunkGenerationStep4.Remove(SeagrassGeneration);
                    generator24.ChunkGenerationStep4.Remove(BottomSuckersGeneration);
                    generator24.ChunkGenerationStep4.Remove(TrapsGeneration);
                    generator24.ChunkGenerationStep4.Remove(IvyGeneration);
                    generator24.ChunkGenerationStep4.Remove(GravesGeneration);
                    generator24.ChunkGenerationStep4.Remove(CairnsGeneration);

                    generator24.ChunkGenerationStep3.Add(new ChunkGenerationStep(501, GenerateStoneForest));
                    generator24.ChunkGenerationStep4.Add(new ChunkGenerationStep(1501, GeneratePalmTrees));
                    generator24.ChunkGenerationStep4.Add(new ChunkGenerationStep(1502, GenerateRockyForest));
                    generator24.ChunkGenerationStep4.Add(new ChunkGenerationStep(1503, GenerateCave));
                    generator24.ChunkGenerationStep4.Add(new ChunkGenerationStep(1600, GeneratePlants));
                }
                else if (WorldName == "Windholes")
                {
                    generator24.ChunkGenerationStep1.Remove(GenerateSurfaceParameters);
                    generator24.ChunkGenerationStep1.Remove(GenerateTerrain);
                    generator24.ChunkGenerationStep2.Remove(GenerateSurfaceParameters2);
                    generator24.ChunkGenerationStep2.Remove(GenerateTerrain2);
                    generator24.ChunkGenerationStep3.Remove(GenerateCaves);
                    generator24.ChunkGenerationStep3.Remove(GeneratePockets);
                    generator24.ChunkGenerationStep3.Remove(MineralsGeneration);
                    generator24.ChunkGenerationStep3.Remove(GenerateSurface);
                    generator24.ChunkGenerationStep3.Remove(PropagateFluidsDownwards);
                    generator24.ChunkGenerationStep4.Remove(GrassAndPlantsGenerate);
                    generator24.ChunkGenerationStep4.Remove(LogsGeneration);
                    generator24.ChunkGenerationStep4.Remove(TreesGeneration);
                    generator24.ChunkGenerationStep4.Remove(GenerateCacti);
                    generator24.ChunkGenerationStep4.Remove(PumpkinsGeneration);
                    generator24.ChunkGenerationStep4.Remove(KelpGeneration);
                    generator24.ChunkGenerationStep4.Remove(SeagrassGeneration);
                    generator24.ChunkGenerationStep4.Remove(BottomSuckersGeneration);
                    generator24.ChunkGenerationStep4.Remove(TrapsGeneration);
                    generator24.ChunkGenerationStep4.Remove(IvyGeneration);
                    generator24.ChunkGenerationStep4.Remove(GravesGeneration);
                    generator24.ChunkGenerationStep4.Remove(CairnsGeneration);
                    generator24.ChunkGenerationStep4.Remove(GenerateSnowAndIce);
                    generator24.ChunkGenerationStep4.Remove(GenerateBedrockAndAir);
                    generator24.ChunkGenerationStep4.Remove(UpdateFluidIsTop);

                    generator24.ChunkGenerationStep4.Add(new ChunkGenerationStep(1, GenerateWindholesCave));
                }

                if (WorldName != "MainWorld")
                {
                    generator24.ChunkGenerationStep3.Add(new ChunkGenerationStep(1, GenerateMultidimensionalWorldTerrainFramewor));
                    generator24.ChunkGenerationStep4.Add(new ChunkGenerationStep(2, GenerateMultidimensionalWorldBuildings));
                    generator24.ChunkGenerationStep4.Add(new ChunkGenerationStep(3, GeneratePlants));
                }
            }
        }

