        public override void OnMinerHit(ComponentMiner miner, ComponentBody componentBody, Vector3 hitPoint, Vector3 hitDirection, ref float attackPower, ref float playerProbability, ref float creatureProbability, out bool hitted)
        {
            //miner.Project.FindSubsystem<SubsystemUpdate>().UpdateTimeDebug = true;
            ComponentHealth componentHealth = miner.Entity.FindComponent<ComponentHealth>();
            ComponentHealth componentHealth1 = componentBody.Entity.FindComponent<ComponentHealth>();
            if (componentHealth.AttackResilience != float.PositiveInfinity && componentHealth1.AttackResilience != float.PositiveInfinity)
            {
                ComponentTalent componentTalent1 = componentBody.Entity.FindComponent<ComponentTalent>();
                ComponentPlayer componentPlayer = componentBody.Entity.FindComponent<ComponentPlayer>();

                float hitRate = miner.ComponentPlayer == null && (Terrain.ExtractContents(miner.ActiveBlockValue) != NewToolsBlock.Index || Terrain.ExtractContents(miner.ActiveBlockValue) != NewLongRangeWeaponsBlock.Index) ? miner.Entity.FindComponent<ComponentExtraAttributes>().HitRate : BlocksManager.Blocks[Terrain.ExtractContents(miner.ActiveBlockValue)].GetMeleeHitProbability(miner.ActiveBlockValue);
                float dodgeRate = miner.ComponentPlayer == null ? miner.Entity.FindComponent<ComponentExtraAttributes>().DodgeRate : componentBody.Entity.FindComponent<ComponentExtraAttributes>().DodgeRate;
                float num1 = 1;
                if (miner.ComponentPlayer == null)
                {
                    if (componentPlayer != null)
                    {
                        for (int a = 0; a < componentTalent1.TalentAttributes.Count; a++)
                        {
                            if (componentTalent1.TalentAttributes[a].AmountOfVariationInAvoidance != 0 && componentTalent1.TalentAttributes[a].Field > 0)
                            {
                                dodgeRate += componentTalent1.TalentAttributes[a].AmountOfVariationInAvoidance + (componentTalent1.TalentAttributes[a].Level - 1) * 0.1f;
                            }
                            if (componentTalent1.TalentAttributes[a].InternalAndExternalInjuriesReduceTheSpeed != 0 && componentTalent1.TalentAttributes[a].Field > 0)
                            {
                                num1 -= componentTalent1.TalentAttributes[a].InternalAndExternalInjuriesReduceTheSpeed + (componentTalent1.TalentAttributes[a].Level - 1) * 0.05f;
                            }
                        }
                        float num = m_random.Float(0f, 1f);
                        ClothingSlot slot = num < 0.1f ? ClothingSlot.Feet :
                            num < 0.3f ? ClothingSlot.Legs :
                            num < 0.9f ? ClothingSlot.Torso : ClothingSlot.Head;
                        dodgeRate += componentBody.Entity.FindComponent<ComponentPhysicalAttributes>().ClothingAttributes[slot].Item2;
                    }
                    if (dodgeRate > 0.75f)
                    {
                        dodgeRate = 0.75f;
                    }
                    creatureProbability = hitRate - dodgeRate;
                }
                else
                {
                    playerProbability = hitRate - dodgeRate;
                }
            }
            hitted = false;
        }

        public override void ClothingProcessSlotItems(ComponentClothing componentClothing, int slotIndex, ref int inputValue, ref int inputCount, ref int processedValue, ref int processedCount, bool skippedByOtherMods, out bool skipVanilla)
        {
            ComponentPhysicalAttributes componentPhysicalAttributes = componentClothing.Entity.FindComponent<ComponentPhysicalAttributes>();
            ComponentIntestinalInfection componentIntestinalInfection = componentClothing.Entity.FindComponent<ComponentIntestinalInfection>();
            ComponentTalent componentTalent = componentClothing.Entity.FindComponent<ComponentTalent>();
            ComponentHYZLVitalStats componentHYZLVitalStats = componentClothing.Entity.FindComponent<ComponentHYZLVitalStats>();
            ComponentBuff componentBuff = componentClothing.Entity.FindComponent<ComponentBuff>();
            if (Terrain.ExtractContents(inputValue) == NewFood.Index && AccessNewFoodManager.Get(NewFood.GetType(inputValue)) != null)
            {
                int num = NewFood.GetType(inputValue);
                float num1 = 1;
                for (int a = 0; a < componentTalent.TalentAttributes.Count; a++)
                {
                    if (componentTalent.TalentAttributes[a].ImprovedRecoveryFromDrugUse > 0 && componentTalent.TalentAttributes[a].Field > 0)
                    {
                        if (AccessNewFoodManager.Get(num).InternalInjuriesValue < 0)
                        {
                            num1 *= 1 - componentTalent.TalentAttributes[a].ImprovedRecoveryFromDrugUse + (componentTalent.TalentAttributes[a].Level - 1) * 0.05f;
                        }
                        else
                        {
                            num1 *= 1 + componentTalent.TalentAttributes[a].ImprovedRecoveryFromDrugUse + (componentTalent.TalentAttributes[a].Level - 1) * 0.05f;
                        }
                    }
                }
                if (AccessNewFoodManager.Get(num).InternalInjuriesValue != 0f)
                {
                    componentPhysicalAttributes.InternalInjuries += AccessNewFoodManager.Get(num).InternalInjuriesValue * num1 / componentPhysicalAttributes.InternalInjuriesResistance;
                }
                if (AccessNewFoodManager.Get(num).InsomniaValue != 0f)
                {
                    componentPhysicalAttributes.Insomnia += AccessNewFoodManager.Get(num).InsomniaValue / componentPhysicalAttributes.InsomniaResistance;
                }
                if (m_random.Bool(AccessNewFoodManager.Get(num).IntestinalInfectionProbability))
                {
                    componentIntestinalInfection.StartInfection();
                }
            }
            if (Terrain.ExtractContents(inputValue) == NewPlants.Index && NewPlants.GetItemStatus(inputValue) && AccessNewPlantsManager.Get(NewPlants.GetType(inputValue)) != null)
            {
                int num = NewPlants.GetType(inputValue);
                float num1 = 1;
                for (int a = 0; a < componentTalent.TalentAttributes.Count; a++)
                {
                    if (componentTalent.TalentAttributes[a].ImprovedRecoveryFromDrugUse > 0 && componentTalent.TalentAttributes[a].Field > 0)
                    {
                        if (AccessNewPlantsManager.Get(num).InternalInjuriesValue > 0)
                        {
                            num1 *= 1 + componentTalent.TalentAttributes[a].ImprovedRecoveryFromDrugUse + (componentTalent.TalentAttributes[a].Level - 1) * 0.05f;
                        }
                        else
                        {
                            num1 *= 1 - componentTalent.TalentAttributes[a].ImprovedRecoveryFromDrugUse + (componentTalent.TalentAttributes[a].Level - 1) * 0.05f;
                        }
                    }
                }
                if (AccessNewPlantsManager.Get(num).InternalInjuriesValue != 0f)
                {
                    componentPhysicalAttributes.InternalInjuries += AccessNewPlantsManager.Get(num).InternalInjuriesValue * num1 / componentPhysicalAttributes.InternalInjuriesResistance;
                }
                if (m_random.Bool(AccessNewPlantsManager.Get(num).IntestinalInfectionProbability))
                {
                    componentIntestinalInfection.StartInfection();
                }
            }
            if (Terrain.ExtractContents(inputValue) == NewArticles.Index && AccessNewArticlesManager.Get(NewArticles.GetType(inputValue)) != null)
            {
                int num = NewArticles.GetType(inputValue);
                float num1 = 1;
                for (int a = 0; a < componentTalent.TalentAttributes.Count; a++)
                {
                    if (componentTalent.TalentAttributes[a].ImprovedRecoveryFromDrugUse > 0 && componentTalent.TalentAttributes[a].Field > 0)
                    {
                        if (AccessNewArticlesManager.Get(num).InternalInjuriesValue > 0 || AccessNewArticlesManager.Get(num).TraumaValueReduced > 0)
                        {
                            num1 *= 1 + componentTalent.TalentAttributes[a].ImprovedRecoveryFromDrugUse + (componentTalent.TalentAttributes[a].Level - 1) * 0.05f;
                        }
                        else
                        {
                            num1 *= 1 - componentTalent.TalentAttributes[a].InternalAndExternalInjuriesReduceTheSpeed + (componentTalent.TalentAttributes[a].Level - 1) * 0.05f;
                        }
                    }
                }
                if (AccessNewArticlesManager.Get(num).InternalInjuriesValue != 0f)
                {
                    componentPhysicalAttributes.InternalInjuries += Math.Min(AccessNewArticlesManager.Get(num).InternalInjuriesValue * num1 / componentPhysicalAttributes.InternalInjuriesResistance, 1 - AccessNewArticlesManager.Get(num).InternalInjuriesValue);
                }
                if (AccessNewArticlesManager.Get(num).TraumaValueReduced != 0f)
                {
                    componentPhysicalAttributes.Trauma += Math.Min(AccessNewArticlesManager.Get(num).TraumaValueReduced * num1 / componentPhysicalAttributes.TraumaResistance, 1 - componentPhysicalAttributes.Trauma);
                }
                if (AccessNewArticlesManager.Get(num).SpiritValueDecreases != 0f)
                {
                    componentHYZLVitalStats.Sleep += Math.Min(AccessNewArticlesManager.Get(num).SpiritValueDecreases / componentPhysicalAttributes.SleepResistance, 1 - componentHYZLVitalStats.Sleep);
                }
                if (AccessNewArticlesManager.Get(num).HungerValueReduction != 0f)
                {
                    componentHYZLVitalStats.Food += Math.Min(AccessNewArticlesManager.Get(num).HungerValueReduction / componentPhysicalAttributes.FoodResistance, 1 - componentHYZLVitalStats.Food);
                }
                if (AccessNewArticlesManager.Get(num).ReducedInsomniaValue != 0f)
                {
                    componentPhysicalAttributes.Insomnia += Math.Min(AccessNewArticlesManager.Get(num).ReducedInsomniaValue / componentPhysicalAttributes.InsomniaResistance, 1 - componentPhysicalAttributes.Insomnia);
                }
                if (AccessNewArticlesManager.Get(num).TraumaInfectionTreatment)
                {
                    componentIntestinalInfection.ResetInfection();
                }
                if (AccessNewArticlesManager.Get(num).ImmunotoxicTime > 0 || AccessNewArticlesManager.Get(num).ImmuneDizzyTime > 0 || AccessNewArticlesManager.Get(num).TimeToRaiseTheTemperature > 0)
                {
                    componentBuff.ThreePillBuff[AccessNewArticlesManager.Get(num).Name] = (AccessNewArticlesManager.Get(num).ImmunotoxicTime, AccessNewArticlesManager.Get(num).ImmuneDizzyTime, AccessNewArticlesManager.Get(num).TimeToRaiseTheTemperature);
                }
            }
            if (Terrain.ExtractContents(inputValue) == NewFish.Index && AccessNewFishManager.Get(NewFish.GetType(inputValue)) != null)
            {
                int num = NewFish.GetType(inputValue);
                float num1 = 1;
                for (int a = 0; a < componentTalent.TalentAttributes.Count; a++)
                {
                    if (componentTalent.TalentAttributes[a].ImprovedRecoveryFromDrugUse > 0 && componentTalent.TalentAttributes[a].Field > 0)
                    {
                        if (AccessNewFishManager.Get(num).TraumaValue > 0 || AccessNewFishManager.Get(num).InternalInjuryValue > 0)
                        {
                            num1 *= 1 + componentTalent.TalentAttributes[a].ImprovedRecoveryFromDrugUse + (componentTalent.TalentAttributes[a].Level - 1) * 0.05f;
                        }
                        else
                        {
                            num1 *= 1 - componentTalent.TalentAttributes[a].ImprovedRecoveryFromDrugUse + (componentTalent.TalentAttributes[a].Level - 1) * 0.05f;
                        }
                    }
                }
                if (AccessNewFishManager.Get(num).TraumaValue != 0f)
                {
                    componentPhysicalAttributes.Trauma += AccessNewFishManager.Get(num).TraumaValue * num1 / componentPhysicalAttributes.TraumaResistance;
                }
                if (AccessNewFishManager.Get(num).InternalInjuryValue != 0f)
                {
                    componentPhysicalAttributes.InternalInjuries += AccessNewFishManager.Get(num).InternalInjuryValue * num1 / componentPhysicalAttributes.InternalInjuriesResistance;
                }
                if (AccessNewFishManager.Get(num).SpiritualValue != 0f)
                {
                    componentHYZLVitalStats.Sleep += AccessNewFishManager.Get(num).SpiritualValue / componentPhysicalAttributes.SleepResistance;
                }
                if (AccessNewFishManager.Get(num).InsomniaValue != 0f)
                {
                    componentPhysicalAttributes.Insomnia = AccessNewFishManager.Get(num).InsomniaValue / componentPhysicalAttributes.InsomniaResistance;
                }
                if (AccessNewFishManager.Get(num).BuffTime != null)
                {
                    float AttackEnhancement = AccessNewFishManager.Get(num).AttackEnhancement.HasValue ? AccessNewFishManager.Get(num).AttackEnhancement.Value : 0f;
                    float DefenseEnhancement = AccessNewFishManager.Get(num).DefenseEnhancement.HasValue ? AccessNewFishManager.Get(num).DefenseEnhancement.Value : 0f;
                    float IncreasedHitRate = AccessNewFishManager.Get(num).IncreasedHitRate.HasValue ? AccessNewFishManager.Get(num).IncreasedHitRate.Value : 0f;
                    float IncreasedAvoidanceRate = AccessNewFishManager.Get(num).IncreasedAvoidanceRate.HasValue ? AccessNewFishManager.Get(num).IncreasedAvoidanceRate.Value : 0f;
                    float TemperatureIncrease = AccessNewFishManager.Get(num).TemperatureIncrease.HasValue ? AccessNewFishManager.Get(num).TemperatureIncrease.Value : 0f;
                    componentBuff.FishBuff[AccessNewFishManager.Get(num).Name] = (AttackEnhancement, DefenseEnhancement, IncreasedHitRate, IncreasedAvoidanceRate, TemperatureIncrease, AccessNewFishManager.Get(num).BuffTime.Value);
                }
                if (AccessNewFishManager.Get(num).ItemsObtainedAfterProcessing != null)
                {
                    processedValue = CraftingRecipesManager.DecodeResult(AccessNewFishManager.Get(num).ItemsObtainedAfterProcessing);
                    processedCount = AccessNewFishManager.Get(num).NumberPfItemsObtainedAfterProcessing.Value;
                }
            }
            skipVanilla = false;
        }

        public override void OnProjectileHitBody(Projectile projectile, BodyRaycastResult bodyRaycastResult, ref Attackment attackment, ref Vector3 velocityAfterAttack, ref Vector3 angularVelocityAfterAttack, ref bool ignoreBody)
        {
            HitValueParticleSystem particleSystem;
            ComponentBody componentBody = attackment.Target.FindComponent<ComponentBody>();
            ComponentBody componentBody1 = attackment.Attacker.FindComponent<ComponentBody>();
            ComponentExtraAttributes componentExtraAttributes = attackment.Target.FindComponent<ComponentExtraAttributes>();
            ComponentTalent componentTalent = attackment.Attacker.FindComponent<ComponentTalent>();
            ComponentHealth componentHealth = attackment.Attacker.FindComponent<ComponentHealth>();
            ComponentHealth componentHealth1 = attackment.Target.FindComponent<ComponentHealth>();
            ComponentBiologyBuff componentBiologyBuff = attackment.Target.FindComponent<ComponentBiologyBuff>();
            SubsystemAudio subsystemAudio = componentBody1.Project.FindSubsystem<SubsystemAudio>(true);

            int ActiveBlockValue = Terrain.ExtractContents(attackment.Attacker.FindComponent<ComponentMiner>().ActiveBlockValue);

            if (componentHealth.AttackResilience != float.PositiveInfinity && componentHealth1.AttackResilience != float.PositiveInfinity)
            {
                float criticalStrikeRate = 0;
                float criticalStrikeMultiplier = 0;
                if (ActiveBlockValue == NewLongRangeWeaponsBlock.Index || ActiveBlockValue == MusketNewBlock.Index)
                {
                    attackment.AttackPower *= BlocksManager.Blocks[Terrain.ExtractContents(attackment.Attacker.FindComponent<ComponentMiner>().ActiveBlockValue)].GetProjectilePower(attackment.Attacker.FindComponent<ComponentMiner>().ActiveBlockValue);
                    criticalStrikeRate = NewLongRangeWeaponsBlock.GetProjectileCriticalStrikeRate(attackment.Attacker.FindComponent<ComponentMiner>().ActiveBlockValue);
                    criticalStrikeMultiplier = NewLongRangeWeaponsBlock.GetProjectileCriticalStrikeMultiplier(attackment.Attacker.FindComponent<ComponentMiner>().ActiveBlockValue);
                    float poisoningRate = attackment.Attacker.FindComponent<ComponentExtraAttributes>().PoisoningRate;
                    subsystemAudio.PlaySound("Audio/TheArrowHit", 1f, m_random.Float(-0.1f, 0.4f), 0f, 0f);
                    for (int a = 0; a < componentTalent.TalentAttributes.Count; a++)
                    {
                        if (componentTalent.TalentAttributes[a].AttackIncreasesWhenTheHPIsLow > 0 && componentTalent.TalentAttributes[a].Field > 0)
                        {
                            if (componentHealth.Health < 0.5f)
                            {
                                attackment.AttackPower *= 1 + (float)Math.Round(5 - componentHealth.Health * 10) * (componentTalent.TalentAttributes[a].AttackIncreasesWhenTheHPIsLow + (componentTalent.TalentAttributes[a].Level - 1) * 0.015f);
                            }
                        }
                        if (componentTalent.TalentAttributes[a].IncreasedProbabilityOfWeaponPoisoning > 0 && componentTalent.TalentAttributes[a].Field > 0)
                        {
                            poisoningRate += 1 + (componentTalent.TalentAttributes[a].IncreasedProbabilityOfWeaponPoisoning + (componentTalent.TalentAttributes[a].Level - 1) * 0.025f);
                        }
                    }
                }
                if (ActiveBlockValue == NewProjectiles.Index)
                {
                    criticalStrikeRate = attackment.Attacker.FindComponent<ComponentExtraAttributes>().CriticalStrikeRate;
                    criticalStrikeMultiplier = attackment.Attacker.FindComponent<ComponentExtraAttributes>().CriticalStrikeMultiplier;
                    for (int a = 0; a < componentTalent.TalentAttributes.Count; a++)
                    {
                        if (componentTalent.TalentAttributes[a].CriticalStrikeRateOnThrowingAttacks > 0 && componentTalent.TalentAttributes[a].Field > 0)
                        {
                            criticalStrikeMultiplier += (componentTalent.TalentAttributes[a].CriticalStrikeRateOnThrowingAttacks + (componentTalent.TalentAttributes[a].Level - 1) * 0.15f);
                        }
                    }
                }
                if (m_random.Bool(criticalStrikeRate))
                {
                    subsystemAudio.PlaySound("Audio/HitTheNailOnTheHead", 1f, m_random.Float(-0.1f, 0.4f), 0f, 0f);
                    particleSystem = new(
                        attackment.HitPoint + 0.75f * attackment.HitDirection,
                        1f * attackment.HitDirection + componentBody1.Velocity,
                        new Color(255, 50, 50),
                        "命中要害"
                    );
                    componentBody1.Project.FindSubsystem<SubsystemParticles>(true).AddParticleSystem(particleSystem);
                    attackment.AttackPower *= criticalStrikeMultiplier;
                }
                if (m_random.Bool(NewProjectiles.GetPoisonRate(projectile.Value)))
                {
                    for (int a = 0; a < 3; a++)
                    {
                        componentHealth1.Injure(new PoisoningInjury(0.1f, componentHealth1.Health, attackment.HitPoint, attackment.HitDirection, attackment.Attacker.FindComponent<ComponentCreature>(), attackment.Target.FindComponent<ComponentBody>()));
                    }
                }
                if (m_random.Bool(NewProjectiles.GetFreezingRate(projectile.Value)))
                {
                    componentBody.Entity.FindComponent<ComponentLocomotion>().StunTime = 5.4f;
                    particleSystem = new(
                        attackment.HitPoint + 0.75f * attackment.HitDirection,
                        1f * attackment.HitDirection + componentBody1.Velocity,
                        new Color(173, 216, 230),
                        "冰冻"
                    );
                    componentBody1.Project.FindSubsystem<SubsystemParticles>(true).AddParticleSystem(particleSystem);
                }
                if (m_random.Bool(NewProjectiles.GetParalysisRate(projectile.Value)))
                {
                    componentBody.Entity.FindComponent<ComponentLocomotion>().StunTime = 5.4f;
                    particleSystem = new(
                        attackment.HitPoint + 0.75f * attackment.HitDirection,
                        1f * attackment.HitDirection + componentBody1.Velocity,
                        new Color(255, 240, 0),
                        "麻痹"
                    );
                    componentBody1.Project.FindSubsystem<SubsystemParticles>(true).AddParticleSystem(particleSystem);
                }
                attackment.AttackPower -= componentExtraAttributes.Defense;
                if (attackment.AttackPower < 1f)
                {
                    attackment.AttackPower = 1f;
                }
            }
        }

        public override void OnPlayerInputHit(ComponentPlayer componentPlayer, ref bool playerOperated, ref double timeIntervalHit, ref float meleeAttackRange, bool skippedByOtherMods, out bool skipVanilla)
        {
            meleeAttackRange = componentPlayer.Entity.FindComponent<ComponentExtraAttributes>().AttackDistance;
            if (NewToolsBlock.GetAttackDistance(componentPlayer.ComponentMiner.ActiveBlockValue) > 1.75f) meleeAttackRange += NewToolsBlock.GetAttackDistance(componentPlayer.ComponentMiner.ActiveBlockValue) - 1.75f;
            skipVanilla = false;
        }

        public override void ClothingSlotProcessCapacity(ComponentClothing componentClothing, int slotIndex, int blockValue, ref bool notToProcessVanilla, out int capacity)
        {
            capacity = 0;
            if (Terrain.ExtractContents(blockValue) == NewPlants.Index && NewPlants.GetItemStatus(blockValue) && AccessNewPlantsManager.Get(NewPlants.GetType(blockValue)) != null)
            {
                int num = NewPlants.GetType(blockValue);
                if (AccessNewPlantsManager.Get(num).InternalInjuriesValue != 0f)
                {
                    capacity = 1;
                }
            }
            if (Terrain.ExtractContents(blockValue) == NewArticles.Index && AccessNewArticlesManager.Get(NewArticles.GetType(blockValue)) == null)
            {
                int num = NewArticles.GetType(blockValue);
                if (AccessNewArticlesManager.Get(num).InternalInjuriesValue != 0f || AccessNewArticlesManager.Get(num).TraumaValueReduced != 0f || AccessNewArticlesManager.Get(num).SpiritValueDecreases != 0f || AccessNewArticlesManager.Get(num).HungerValueReduction != 0f || AccessNewArticlesManager.Get(num).ReducedInsomniaValue != 0f || AccessNewArticlesManager.Get(num).ImmunotoxicTime > 0 || AccessNewArticlesManager.Get(num).ImmuneDizzyTime > 0 || AccessNewArticlesManager.Get(num).TimeToRaiseTheTemperature > 0)
                {
                    capacity = 1;
                }
            }
        }

        public override void OnMinerHit2(ComponentMiner componentMiner, ComponentBody componentBody, Vector3 hitPoint, Vector3 hitDirection, ref int durabilityReduction, ref Attackment attackment)
        {
            ComponentHealth componentHealth = componentMiner.Entity.FindComponent<ComponentHealth>();
            ComponentHealth componentHealth1 = componentBody.Entity.FindComponent<ComponentHealth>();
            if (componentHealth.AttackResilience != float.PositiveInfinity && componentHealth1.AttackResilience != float.PositiveInfinity)
            {
                float criticalStrikeRate = componentMiner.ComponentPlayer == null && Terrain.ExtractContents(componentMiner.ActiveBlockValue) != NewToolsBlock.Index ? componentMiner.Entity.FindComponent<ComponentExtraAttributes>().CriticalStrikeRate : Terrain.ExtractContents(componentMiner.ActiveBlockValue) == NewLongRangeWeaponsBlock.Index ? NewLongRangeWeaponsBlock.GetMeleeCriticalStrikeRate(componentMiner.ActiveBlockValue) : NewToolsBlock.GetCriticalStrikeRate(componentMiner.ActiveBlockValue);
                float criticalStrikeMultiplier = componentMiner.ComponentPlayer == null && Terrain.ExtractContents(componentMiner.ActiveBlockValue) != NewToolsBlock.Index ? componentMiner.Entity.FindComponent<ComponentExtraAttributes>().CriticalStrikeMultiplier : Terrain.ExtractContents(componentMiner.ActiveBlockValue) == NewLongRangeWeaponsBlock.Index ? NewLongRangeWeaponsBlock.GetMeleeCriticalStrikeMultiplier(componentMiner.ActiveBlockValue) : NewToolsBlock.GetCriticalStrikeMultiplier(componentMiner.ActiveBlockValue);
                float poisoningRate = componentMiner.Entity.FindComponent<ComponentExtraAttributes>().PoisoningRate;
                float vertigoRate = componentMiner.ComponentPlayer == null && Terrain.ExtractContents(componentMiner.ActiveBlockValue) != NewToolsBlock.Index ? componentMiner.Entity.FindComponent<ComponentExtraAttributes>().VertigoRate : NewToolsBlock.GetVertigoRate(componentMiner.ActiveBlockValue);
                float repellingRate = NewToolsBlock.GetRepellingRate(componentMiner.ActiveBlockValue);
                float repellingDistance = NewToolsBlock.GetRepellingDistance(componentMiner.ActiveBlockValue);
                float dizzinessTime = NewToolsBlock.GetDizzinessTime(componentMiner.ActiveBlockValue);
                float bloodAbsorptionRate = NewToolsBlock.GetBloodAbsorptionRate(componentMiner.ActiveBlockValue);
                float bloodSuckingPercentage = NewToolsBlock.GetBloodSuckingPercentage(componentMiner.ActiveBlockValue);
                float shockRate = NewToolsBlock.GetShockRate(componentMiner.ActiveBlockValue);
                float num1 = 1;
                HYZLInventory inventory1;
                HitValueParticleSystem particleSystem;
                ComponentBody componentBody1 = componentMiner.Entity.FindComponent<ComponentBody>();
                ComponentPhysicalAttributes componentPhysicalAttributes = componentBody.Entity.FindComponent<ComponentPhysicalAttributes>();
                ComponentExtraAttributes componentExtraAttributes = componentBody.Entity.FindComponent<ComponentExtraAttributes>();
                ComponentHandModel componentHandModel = componentBody.Entity.FindComponent<ComponentHandModel>();
                ComponentTalent componentTalent = componentMiner.Entity.FindComponent<ComponentTalent>();
                ComponentTalent componentTalent1 = componentBody.Entity.FindComponent<ComponentTalent>();
                ComponentAchievementAttributes componentAchievementAttributes = componentBody.Entity.FindComponent<ComponentAchievementAttributes>();
                ComponentBuff componentBuff = componentBody.Entity.FindComponent<ComponentBuff>();
                ComponentPlayer componentPlayer = componentBody.Entity.FindComponent<ComponentPlayer>();
                SubsystemAudio subsystemAudio = componentMiner.Project.FindSubsystem<SubsystemAudio>(true);
                if (componentMiner.ComponentPlayer == null)
                {
                    if (componentPlayer != null)
                    {
                        for (int a = 0; a < componentTalent1.TalentAttributes.Count; a++)
                        {
                            if (componentTalent1.TalentAttributes[a].InternalAndExternalInjuriesReduceTheSpeed != 0 && componentTalent1.TalentAttributes[a].Field > 0)
                            {
                                num1 -= componentTalent1.TalentAttributes[a].InternalAndExternalInjuriesReduceTheSpeed + (componentTalent1.TalentAttributes[a].Level - 1) * 0.05f;
                            }
                        }
                    }
                    if (m_random.Bool(criticalStrikeRate))
                    {
                        particleSystem = new(
                            hitPoint + 0.75f * hitDirection,
                            1f * hitDirection + componentBody1.Velocity,
                            new Color(255, 50, 50),
                            "命中要害"
                        );
                        subsystemAudio.PlaySound("Audio/HitTheNailOnTheHead", 1f, m_random.Float(-0.1f, 0.4f), 0f, 0f);
                        componentMiner.Project.FindSubsystem<SubsystemParticles>(true).AddParticleSystem(particleSystem);
                        attackment.AttackPower *= criticalStrikeMultiplier;
                    }
                    if (m_random.Bool(poisoningRate))
                    {
                        if (componentPlayer != null)
                        {
                            if ((componentBuff.ThreePillBuff.Any(kvp => kvp.Value.Item1 == 0) || componentBuff.ThreePillBuff.Count == 0) || componentBuff == null)
                            {
                                subsystemAudio.PlaySound("Audio/Creatures/Skills/Intoxication/" + componentBody1.Entity.ValuesDictionary.DatabaseObject.Name, 1f, m_random.Float(-0.1f, 0.4f), 0f, 0f);
                                for (int a = 0; a < 3; a++)
                                {
                                    componentHealth1.Injure(new PoisoningInjury(0.1f, componentHealth1.Health, hitPoint, hitDirection, componentMiner.Entity.FindComponent<ComponentCreature>(), componentBody));
                                }
                            }
                        }
                        else
                        {
                            subsystemAudio.PlaySound("Audio/Creatures/Skills/Intoxication/" + componentBody1.Entity.ValuesDictionary.DatabaseObject.Name, 1f, m_random.Float(-0.1f, 0.4f), 0f, 0f);
                            for (int a = 0; a < 3; a++)
                            {
                                componentHealth1.Injure(new PoisoningInjury(0.1f, componentHealth1.Health, hitPoint, hitDirection, componentMiner.Entity.FindComponent<ComponentCreature>(), componentBody));
                            }
                        }
                    }
                    if (m_random.Bool(vertigoRate))
                    {
                        if (componentPlayer != null)
                        {
                            if (componentBuff.ThreePillBuff.Any(kvp => kvp.Value.Item2 == 0) || componentBuff.ThreePillBuff.Count == 0)
                            {
                                particleSystem = new(
                                    hitPoint + 0.75f * hitDirection,
                                    1f * hitDirection + componentBody1.Velocity,
                                    new Color(255, 255, 100),
                                    "眩晕"
                                );
                                subsystemAudio.PlaySound("Audio/Creatures/Skills/Dizziness/" + componentBody1.Entity.ValuesDictionary.DatabaseObject.Name, 1f, m_random.Float(-0.1f, 0.4f), 0f, 0f);
                                componentMiner.Project.FindSubsystem<SubsystemParticles>(true).AddParticleSystem(particleSystem);
                                componentBody.Entity.FindComponent<ComponentLocomotion>().StunTime = 5.4f;
                            }
                        }
                        else
                        {
                            particleSystem = new(
                                hitPoint + 0.75f * hitDirection,
                                1f * hitDirection + componentBody1.Velocity,
                                new Color(255, 255, 100),
                                "眩晕"
                            );
                            subsystemAudio.PlaySound("Audio/Creatures/Skills/Dizziness/" + componentBody1.Entity.ValuesDictionary.DatabaseObject.Name, 1f, m_random.Float(-0.1f, 0.4f), 0f, 0f);
                            componentMiner.Project.FindSubsystem<SubsystemParticles>(true).AddParticleSystem(particleSystem);
                            componentBody.Entity.FindComponent<ComponentLocomotion>().StunTime = 5.4f;
                        }
                    }
                    if (componentPlayer != null)
                    {
                        inventory1 = componentHandModel.Inventory;
                        if (Terrain.ExtractContents(componentHandModel.ActiveBlockValue) == NewShield.Index)
                        {
                            if (m_random.Bool(NewShield.GetBlockRate(componentHandModel.ActiveBlockValue)))
                            {
                                particleSystem = new(
                                    hitPoint + 0.75f * hitDirection,
                                    1f * hitDirection + componentBody1.Velocity,
                                    new Color(255, 200, 80),
                                    "格挡"
                                );
                                subsystemAudio.PlaySound("Audio/HitTheNailOnTheHead", 1f, m_random.Float(-0.1f, 0.4f), 0f, 0f);
                                componentMiner.Project.FindSubsystem<SubsystemParticles>(true).AddParticleSystem(particleSystem);
                                attackment.AttackPower -= NewShield.GetDefense(componentHandModel.ActiveBlockValue);
                            }
                            else if (componentBody.Entity.FindComponent<ComponentPlayer>() != null)
                            {
                                componentPhysicalAttributes.Trauma -= 1 / componentPhysicalAttributes.TraumaResistance * num1;
                            }
                            int num = BlocksManager.DamageItem(componentHandModel.ActiveBlockValue, 1, componentBody.Entity);
                            if (num != 0)
                            {
                                int slotCount = inventory1.GetSlotCount(inventory1.ActiveSlotIndex);
                                inventory1.RemoveSlotItems(inventory1.ActiveSlotIndex, slotCount);
                                if (inventory1.GetSlotCount(inventory1.ActiveSlotIndex) == 0)
                                {
                                    inventory1.AddSlotItems(inventory1.ActiveSlotIndex, num, slotCount);
                                }
                            }
                            else
                            {
                                inventory1.RemoveSlotItems(inventory1.ActiveSlotIndex, 1);
                            }
                            if (NewShield.GetCounterInjury(componentHandModel.ActiveBlockValue) > 0)
                            {
                                componentHealth.Injure(NewShield.GetCounterInjury(componentHandModel.ActiveBlockValue) / componentHealth.AttackResilience, componentBody.Entity.FindComponent<ComponentCreature>(), true, "被盾牌反伤杀死");
                                particleSystem = new(
                                    hitPoint + 0.75f * hitDirection,
                                    1f * hitDirection + componentBody1.Velocity,
                                    new Color(0, 255, 255),
                                    "-" + NumericalProcessingManager.NumericalProcessing(NewShield.GetCounterInjury(componentHandModel.ActiveBlockValue))
                                );
                                componentMiner.Project.FindSubsystem<SubsystemParticles>(true).AddParticleSystem(particleSystem);
                            }
                        }
                        else
                        {
                            componentPhysicalAttributes.Trauma -= 1 / componentPhysicalAttributes.TraumaResistance * num1;
                        }
                    }
                }
                else
                {
                    if (Terrain.ExtractContents(componentMiner.ActiveBlockValue) == NewToolsBlock.Index)
                    {
                        if (NewToolsBlock.GetTypeOfTool(componentMiner.ActiveBlockValue) != "")
                        {
                            subsystemAudio.PlayRandomSound("Audio/Impacts/" + NewToolsBlock.GetTypeOfTool(componentMiner.ActiveBlockValue), 5f, m_random.Float(-0.1f, 0.4f), 0f, 0f);
                        }
                    }
                    else if (componentMiner.ActiveBlockValue == 0)
                    {
                        subsystemAudio.PlayRandomSound("Audio/Impacts/Fists", 1f, m_random.Float(-0.1f, 0.4f), 0f, 0f);
                    }

                    for (int a = 0; a < componentTalent.TalentAttributes.Count; a++)
                    {
                        if (componentTalent.TalentAttributes[a].WeaponDurabilityCostReduced > 0 && componentTalent.TalentAttributes[a].Field > 0)
                        {
                            if (m_random.Bool(componentTalent.TalentAttributes[a].WeaponDurabilityCostReduced + (componentTalent.TalentAttributes[a].Level - 1) * 0.1f))
                            {
                                durabilityReduction = 0;
                            }
                        }
                        if (componentTalent.TalentAttributes[a].MeleeCriticalStrikeRate > 0 && componentTalent.TalentAttributes[a].Field > 0)
                        {
                            criticalStrikeRate += componentTalent.TalentAttributes[a].MeleeCriticalStrikeRate + (componentTalent.TalentAttributes[a].Level - 1) * 0.015f;
                        }
                        if (componentTalent.TalentAttributes[a].TheDamageDoneToPeopleIncreases > 0 && componentTalent.TalentAttributes[a].Field > 0 && componentAchievementAttributes.BiologicalType == "人")
                        {
                            attackment.AttackPower *= 1 + (componentTalent.TalentAttributes[a].TheDamageDoneToPeopleIncreases + (componentTalent.TalentAttributes[a].Level - 1) * 0.04f);
                        }
                        if (componentTalent.TalentAttributes[a].AttackIncreasesWhenTheHPIsLow > 0 && componentTalent.TalentAttributes[a].Field > 0)
                        {
                            if (componentHealth.Health < 0.5f)
                            {
                                attackment.AttackPower *= 1 + (float)Math.Round(5 - componentHealth.Health * 10) * (componentTalent.TalentAttributes[a].AttackIncreasesWhenTheHPIsLow + (componentTalent.TalentAttributes[a].Level - 1) * 0.015f);
                            }
                        }
                        if (componentTalent.TalentAttributes[a].IncreasedProbabilityOfWeaponPoisoning > 0 && componentTalent.TalentAttributes[a].Field > 0)
                        {
                            poisoningRate += 1 + (componentTalent.TalentAttributes[a].IncreasedProbabilityOfWeaponPoisoning + (componentTalent.TalentAttributes[a].Level - 1) * 0.025f);
                        }
                        if (componentTalent.TalentAttributes[a].AxeWeaponAttackUpgrade > 0 && componentTalent.TalentAttributes[a].Field > 0)
                        {
                            if (Terrain.ExtractContents(componentMiner.ActiveBlockValue) == NewToolsBlock.Index && NewToolsBlock.GetTypeOfTool(componentMiner.ActiveBlockValue) == "斧")
                            {
                                attackment.AttackPower *= 1 + (componentTalent.TalentAttributes[a].AxeWeaponAttackUpgrade + (componentTalent.TalentAttributes[a].Level - 1) * 0.04f);
                            }
                        }
                        if (componentTalent.TalentAttributes[a].EmptyHandedAttackUpgrade > 0 && componentTalent.TalentAttributes[a].Field > 0)
                        {
                            if (componentMiner.ActiveBlockValue == 0)
                            {
                                attackment.AttackPower += componentTalent.TalentAttributes[a].EmptyHandedAttackUpgrade + (componentTalent.TalentAttributes[a].Level - 1) * 7.5f;
                            }
                        }
                    }

                    if (m_random.Bool(criticalStrikeRate))
                    {
                        subsystemAudio.PlaySound("Audio/HitTheNailOnTheHead", 1f, m_random.Float(-0.1f, 0.4f), 0f, 0f);
                        particleSystem = new(
                            hitPoint + 0.75f * hitDirection,
                            1f * hitDirection + componentBody1.Velocity,
                            new Color(255, 50, 50),
                            "命中要害"
                        );
                        componentMiner.Project.FindSubsystem<SubsystemParticles>(true).AddParticleSystem(particleSystem);
                        attackment.AttackPower *= criticalStrikeMultiplier;
                    }

                    if (m_random.Bool(repellingRate))
                    {
                        subsystemAudio.PlaySound("Audio/Impacts/Repelling" + NewToolsBlock.GetTypeOfTool(componentMiner.ActiveBlockValue), 1f, m_random.Float(-0.1f, 0.4f), 0f, 0f);
                        particleSystem = new(
                            hitPoint + 0.75f * hitDirection,
                            1f * hitDirection + componentBody1.Velocity,
                            new Color(0, 200, 255),
                            "击退"
                        );
                        componentMiner.Project.FindSubsystem<SubsystemParticles>(true).AddParticleSystem(particleSystem);
                        componentBody.ApplyImpulse(repellingDistance * componentBody1.Mass * Vector3.Normalize(hitDirection + m_random.Vector3(0.1f) + 0.2f * Vector3.UnitY));
                    }
                    if (m_random.Bool(vertigoRate))
                    {
                        particleSystem = new(
                            hitPoint + 0.75f * hitDirection,
                            1f * hitDirection + componentBody1.Velocity,
                            new Color(255, 255, 100),
                            "眩晕"
                        );
                        subsystemAudio.PlaySound("Audio/Impacts/Dizziness" + NewToolsBlock.GetTypeOfTool(componentMiner.ActiveBlockValue), 1f, m_random.Float(-0.1f, 0.4f), 0f, 0f);
                        componentMiner.Project.FindSubsystem<SubsystemParticles>(true).AddParticleSystem(particleSystem);
                        componentBody.Entity.FindComponent<ComponentLocomotion>().StunTime = dizzinessTime;
                    }
                    if (m_random.Bool(bloodAbsorptionRate))
                    {
                        particleSystem = new(
                            hitPoint + 0.75f * hitDirection,
                            1f * hitDirection + componentBody1.Velocity,
                            new Color(139, 0, 0),
                            "+" + NumericalProcessingManager.NumericalProcessing(attackment.AttackPower * bloodSuckingPercentage)
                        );
                        subsystemAudio.PlaySound("Audio/Impacts/SuckingBlood" + NewToolsBlock.GetTypeOfTool(componentMiner.ActiveBlockValue), 1f, m_random.Float(-0.1f, 0.4f), 0f, 0f);
                        componentMiner.Project.FindSubsystem<SubsystemParticles>(true).AddParticleSystem(particleSystem);
                        componentHealth.Heal(attackment.AttackPower * bloodSuckingPercentage / componentHealth.AttackResilience);
                    }
                    if (m_random.Bool(shockRate))
                    {
                        particleSystem = new(
                            hitPoint + 0.75f * hitDirection,
                            1f * hitDirection + componentBody1.Velocity,
                            new Color(255, 0, 0),
                            "惊吓"
                        );
                        subsystemAudio.PlaySound("Audio/Impacts/Shock" + NewToolsBlock.GetTypeOfTool(componentMiner.ActiveBlockValue), 1f, m_random.Float(-0.1f, 0.4f), 0f, 0f);
                        componentMiner.Project.FindSubsystem<SubsystemParticles>(true).AddParticleSystem(particleSystem);
                        componentBody.Entity.FindComponent<ComponentChaseBehavior>().m_target = null;
                        componentBody.Entity.FindComponent<ComponentRunAwayBehavior>().LowHealthToEscape = 1;
                    }

                    if (m_random.Bool(poisoningRate))
                    {
                        for (int a = 0; a < 3; a++)
                        {
                            componentHealth1.Injure(new PoisoningInjury(0.1f, componentHealth1.Health, hitPoint, hitDirection, componentMiner.Entity.FindComponent<ComponentCreature>(), componentBody));
                        }
                    }
                }
                attackment.AttackPower -= componentExtraAttributes.Defense;
            }
        }

        public override void HandleInventoryDragMove(InventorySlotWidget inventorySlotWidget, IInventory sourceInventory, int sourceSlotIndex, IInventory targetInventory, int targetSlotIndex, bool skippedByOtherMods, out bool skip)
        {
            skip = false;
            if ((sourceInventory is ComponentMerchant && targetInventory is ComponentTradingGoods) ||
            (sourceInventory is ComponentMerchant && targetInventory is ComponentInventory) ||
            (sourceInventory is ComponentMerchant && targetInventory is ComponentCreativeInventory) ||
            (sourceInventory is ComponentInventory && targetInventory is ComponentMerchandise) ||
            (sourceInventory is ComponentInventory && targetInventory is ComponentMerchant) ||
            (sourceInventory is ComponentCreativeInventory && targetInventory is ComponentMerchandise) ||
            (sourceInventory is ComponentCreativeInventory && targetInventory is ComponentMerchant))
            {
                skip = true;
            }
        }

        public override void OnPlayerDead(PlayerData playerData)
        {
            if (playerData.m_stateMachine.PreviousState == "Playing")
            {
                playerData.ComponentPlayer.Entity.FindComponent<ComponentTalent>().Reading = false;
                playerData.ComponentPlayer.Entity.FindComponent<ComponentTalent>().num = 1;
                playerData.ComponentPlayer.Entity.FindComponent<ComponentSkills>().Reading = false;
                playerData.ComponentPlayer.Entity.FindComponent<ComponentSkills>().num = 1;
                playerData.ComponentPlayer.Entity.FindComponent<ComponentHYZLGui>().SkillsButton.NormalSubtexture = playerData.ComponentPlayer.Entity.FindComponent<ComponentHYZLGui>().SkillsButton.ClickedSubtexture = ContentManager.Get<Texture2D>("Textures/Gui/Skills/SkillsButton_None");
            }
        }

        public override void EditBlockDescriptionScreen(Dictionary<string, string> blockProperties, int blockValue)
        {
            int contents = Terrain.ExtractContents(blockValue);
            StringBuilder sb = new StringBuilder();

            if (contents == NewToolsBlock.Index)
            {
                int num = NewToolsBlock.GetType(blockValue);
                var data = AccessNewToolsBlockManager.Get(num);
                if (data != null)
                {
                    if (data.CriticalStrikeRate != 0)
                    {
                        sb.Clear();
                        sb.AppendFormat("{0:P0}", data.CriticalStrikeRate);
                        blockProperties["暴击率"] = sb.ToString();
                    }
                    if (data.CriticalStrikeMultiplier != 0)
                    {
                        sb.Clear();
                        sb.AppendFormat("{0:P0}", data.CriticalStrikeMultiplier);
                        blockProperties["暴击倍率"] = sb.ToString();
                    }
                    if (data.RepellingRate != 0)
                    {
                        sb.Clear();
                        sb.AppendFormat("{0:P0}", data.RepellingRate);
                        blockProperties["击退率"] = sb.ToString();
                    }
                    if (data.RepellingDistance != 0)
                    {
                        sb.Clear();
                        sb.Append(data.RepellingDistance);
                        sb.Append("格");
                        blockProperties["击退距离"] = sb.ToString();
                    }
                    if (data.VertigoRate != 0)
                    {
                        sb.Clear();
                        sb.AppendFormat("{0:P0}", data.VertigoRate);
                        blockProperties["眩晕率"] = sb.ToString();
                    }
                    if (data.DizzinessTime != 0)
                    {
                        sb.Clear();
                        sb.Append(data.DizzinessTime);
                        sb.Append("秒");
                        blockProperties["眩晕时间"] = sb.ToString();
                    }
                    if (data.BloodAbsorptionRate != 0)
                    {
                        sb.Clear();
                        sb.AppendFormat("{0:P0}", data.BloodAbsorptionRate);
                        blockProperties["吸血率"] = sb.ToString();
                    }
                    if (data.BloodSuckingPercentage != 0)
                    {
                        sb.Clear();
                        sb.AppendFormat("{0:P0}", data.BloodSuckingPercentage);
                        blockProperties["吸血百分比"] = sb.ToString();
                    }
                    if (data.ShockRate != 0)
                    {
                        sb.Clear();
                        sb.AppendFormat("{0:P0}", data.ShockRate);
                        blockProperties["惊吓率"] = sb.ToString();
                    }
                    if (data.AttackDistance != 0)
                    {
                        sb.Clear();
