        public override void UpdateCreaturePropertiesInBestiaryDescriptionScreen(BestiaryDescriptionScreen bestiaryDescriptionScreen, BestiaryCreatureInfo bestiaryCreatureInfo, ValuesDictionary entityValuesDictionary)
        {
            ValuesDictionary valuesDictionary = DatabaseManager.FindValuesDictionaryForComponent(entityValuesDictionary, typeof(ComponentExtraAttributes));

            bestiaryCreatureInfo.EntityValuesDictionary["HitRate"] = valuesDictionary.GetValue<float>("HitRate");
            bestiaryCreatureInfo.EntityValuesDictionary["CriticalStrikeRate"] = valuesDictionary.GetValue<float>("CriticalStrikeRate");
            bestiaryCreatureInfo.EntityValuesDictionary["CriticalStrikeMultiplier"] = valuesDictionary.GetValue<float>("CriticalStrikeMultiplier");
            bestiaryCreatureInfo.EntityValuesDictionary["DodgeRate"] = valuesDictionary.GetValue<float>("DodgeRate");
            bestiaryCreatureInfo.EntityValuesDictionary["PoisoningRate"] = valuesDictionary.GetValue<float>("PoisoningRate");
            bestiaryCreatureInfo.EntityValuesDictionary["AttackDistance"] = valuesDictionary.GetValue<float>("AttackDistance");
            bestiaryCreatureInfo.EntityValuesDictionary["Defense"] = valuesDictionary.GetValue<float>("Defense");
            bestiaryCreatureInfo.EntityValuesDictionary["VertigoRate"] = valuesDictionary.GetValue<float>("VertigoRate");

            LabelWidget propertyValues1Widget1 = bestiaryDescriptionScreen.m_propertyValues1Widget;
            var Names1 = new StringBuilder(bestiaryDescriptionScreen.m_propertyNames1Widget.Text);
            var Values1 = new StringBuilder(propertyValues1Widget1.Text);
            Names1.Append("\n命中率:\n");
            Values1.Append($"\n{bestiaryCreatureInfo.EntityValuesDictionary["HitRate"]:P0}\n");
            Names1.Append("暴击倍率:\n");
            Values1.Append($"{bestiaryCreatureInfo.EntityValuesDictionary["CriticalStrikeMultiplier"]:P0}\n");
            Names1.Append("中毒率:\n");
            Values1.Append($"{bestiaryCreatureInfo.EntityValuesDictionary["PoisoningRate"]:P0}\n");
            Names1.Append("防御:");
            Values1.Append($"{bestiaryCreatureInfo.EntityValuesDictionary["Defense"]}");

            bestiaryDescriptionScreen.m_propertyNames1Widget.Text = Names1.ToString();
            bestiaryDescriptionScreen.m_propertyValues1Widget.Text = Values1.ToString();

            LabelWidget propertyValues2Widget1 = bestiaryDescriptionScreen.m_propertyValues2Widget;
            var Names2 = new StringBuilder(bestiaryDescriptionScreen.m_propertyNames2Widget.Text);
            var Values2 = new StringBuilder(propertyValues2Widget1.Text);
            Names2.Append("\n暴击率:\n");
            Values2.Append($"\n{bestiaryCreatureInfo.EntityValuesDictionary["CriticalStrikeRate"]:P0}\n");
            Names2.Append("闪避率:\n");
            Values2.Append($"{bestiaryCreatureInfo.EntityValuesDictionary["DodgeRate"]:P0}\n");
