            bestiaryDescriptionScreen.m_propertyNames2Widget.Text = Names2.ToString();
            bestiaryDescriptionScreen.m_propertyValues2Widget.Text = Values2.ToString();
        }

        public override void ApplyProtectionBeforeClothes(ComponentClothing componentClothing, Attackment attackment, ref float attackPowerAfterProtection)
        {
            if (componentClothing.Entity.FindComponent<ComponentPhysicalAttributes>().SkillShield > 0)
            {
                float num = componentClothing.Entity.FindComponent<ComponentPhysicalAttributes>().SkillShield;
                componentClothing.Entity.FindComponent<ComponentPhysicalAttributes>().SkillShield = Math.Max(num - attackment.AttackPower, 0);
                attackment.AttackPower -= num;
                if (attackment.AttackPower < 0)
                {
                    attackment.AttackPower = 1;
                }
                attackPowerAfterProtection = attackment.AttackPower;
            }
        }

        public override void OnCreatureDying(ComponentHealth componentHealth, Injury injury)
        {
            if (injury.Cause == "被释放的腐食感染技能杀死")
            {
                foreach (Entity entity in componentHealth.Project.Entities)
                {
                    int TargetNumber = 0;
                    foreach (Component component in entity.Components)
                    {
                        if (component is ComponentBody ComponentBody)
                        {
                            if (ComponentBody.Entity.FindComponent<ComponentPlayer>() == null && Vector3.DistanceSquared(ComponentBody.Position, componentHealth.Entity.FindComponent<ComponentBody>().Position) < 1)
                            {
                                foreach (AccessSkills accessSkills in AccessSkillsManager.Data)
                                {
                                    if (accessSkills.SkillsID == 3)
                                    {
                                        for (int b = 0; b < accessSkills.AttackCount; b++)
                                        {
                                            float Damage = 0;
                                            if (accessSkills.MaximumHealthPointsReduction > 0)
                                            {
                                                Damage += ComponentBody.m_componentHealth.AttackResilience * (accessSkills.MaximumHealthPointsReduction + (accessSkills.Level - 1) * 0.02f);
                                            }
                                            HitValueParticleSystem particleSystem = new(ComponentBody.Position, ComponentBody.Velocity, new Color(255, 255, 255), "-" + NumericalProcessingManager.NumericalProcessing((float)Math.Round(MathUtils.Max((Damage - ComponentBody.Entity.FindComponent<ComponentExtraAttributes>().Defense), 1))));
                                            componentHealth.m_subsystemParticles.AddParticleSystem(particleSystem);
                                            ComponentBody.m_componentHealth.Injure((MathUtils.Max(Damage - ComponentBody.Entity.FindComponent<ComponentExtraAttributes>().Defense, 1)) / ComponentBody.m_componentHealth.AttackResilience, ComponentBody.Entity.FindComponent<ComponentChaseBehavior>().Target, true, "被释放的" + accessSkills.Name + "技能杀死");
                                        }
                                    }
                                    TargetNumber++;
                                }
                            }
                        }
                    }
                }
            }
        }

        public override void CalculateCreatureInjuryAmount(Injury injury)
        {
            if (injury.Attackment.Attacker.FindComponent<ComponentPlayer>() == null)
            {
                bool hasPlayerTarget = injury.Attackment.Attacker.FindComponent<ComponentChaseBehavior>().Target is ComponentPlayer;
                if (injury.Attackment.Target.FindComponent<ComponentPlayer>() != null)
                {
                    ComponentSkills componentSkills = injury.Attackment.Target.FindComponent<ComponentSkills>();
                    if (componentSkills.CounterattackCount > 0 && hasPlayerTarget && injury.Amount > 0 && componentSkills.SkillsAttributes[16].Select)
                    {
                        for (int a = 0; a < componentSkills.SkillsAttributes.Count; a++)
                        {
                            if (Vector3.DistanceSquared(injury.Attackment.Attacker.FindComponent<ComponentBody>().Position, injury.Attackment.Target.FindComponent<ComponentBody>().Position) < componentSkills.SkillsAttributes[a].CounterattackDistance * componentSkills.SkillsAttributes[a].CounterattackDistance)
                            {
                                float Damage = 0;
                                if (componentSkills.SkillsAttributes[a].ReducedDurabilityOfMeleeWeapons > 0)
                                {
                                    if (Terrain.ExtractContents(injury.Attackment.Target.FindComponent<ComponentMiner>().ActiveBlockValue) != NewToolsBlock.Index)
                                    {
                                        injury.Attackment.Target.FindComponent<ComponentGui>().DisplaySmallMessage("未手持近战武器", Color.Red, true, true);
                                        break;
                                    }
                                    Damage += injury.Attackment.Target.FindComponent<ComponentMiner>().AttackPower * BlocksManager.Blocks[NewToolsBlock.Index].GetMeleePower(injury.Attackment.Target.FindComponent<ComponentMiner>().ActiveBlockValue) + (injury.Attackment.Target.FindComponent<ComponentSkills>().SkillsAttributes[a].Level - 1) * (BlocksManager.Blocks[NewToolsBlock.Index].GetMeleePower(injury.Attackment.Target.FindComponent<ComponentMiner>().ActiveBlockValue) / 2);
                                    Damage *= componentSkills.SkillsAttributes[a].CommonAttackRatio + (componentSkills.SkillsAttributes[a].Level - 1) * 0.45f;
                                    injury.Attackment.Target.FindComponent<ComponentMiner>().DamageActiveTool(componentSkills.SkillsAttributes[a].ReducedDurabilityOfMeleeWeapons);
                                }
                                HitValueParticleSystem particleSystem = new(injury.Attackment.Attacker.FindComponent<ComponentBody>().Position, injury.Attackment.Attacker.FindComponent<ComponentBody>().Velocity, new Color(255, 255, 255), "-" + NumericalProcessingManager.NumericalProcessing((float)Math.Round(MathUtils.Max(Damage - injury.Attackment.Attacker.FindComponent<ComponentExtraAttributes>().Defense, 1))));
                                injury.Attackment.Target.FindComponent<ComponentMiner>().Project.FindSubsystem<SubsystemParticles>().AddParticleSystem(particleSystem);
                                injury.Attackment.Attacker.FindComponent<ComponentHealth>().Injure(MathUtils.Max(Damage - injury.Attackment.Attacker.FindComponent<ComponentExtraAttributes>().Defense, 1) / injury.Attackment.Attacker.FindComponent<ComponentHealth>().AttackResilience, injury.Attackment.Target.FindComponent<ComponentPlayer>(), true, "被释放的" + injury.Attackment.Target.FindComponent<ComponentSkills>().SkillsAttributes[a].Name + "技能杀死");
                                componentSkills.CounterattackCount--;
                                break;
                            }
                        }
                    }
                }
            }
        }

        public override void SetHitValueParticleSystem(HitValueParticleSystem hitValueParticleSystem, Attackment attackment)
        {
            for (int i = 0; i < hitValueParticleSystem.Particles.Length; i++)
            {
                HitValueParticleSystem.Particle particle = hitValueParticleSystem.Particles[i];
                if (particle.IsActive)
                {
                    string num = particle.Text;
                    if (float.TryParse(num, out float result))
                    {
                        particle.Text = NumericalProcessingManager.NumericalProcessing(result);
                    }
                }
            }
        }

        public override void ProcessAttackment(Attackment attackment)
        {
            if (attackment.Target.FindComponent<ComponentPlayer>() != null)
            {
                float num = m_random.Float(0f, 1f);
                ClothingSlot slot = num < 0.1f ? ClothingSlot.Feet :
                    num < 0.3f ? ClothingSlot.Legs :
                    num < 0.9f ? ClothingSlot.Torso : ClothingSlot.Head;
                attackment.AttackPower -= attackment.Target.FindComponent<ComponentPhysicalAttributes>().ClothingAttributes[slot].Item1;
            }
            if (attackment.AttackPower < 1f)
            {
                attackment.AttackPower = 1f;
            }
            if (attackment.Attacker.FindComponent<ComponentPlayer>() == null)
            {
                HitValueParticleSystem particleSystem = new(
                    attackment.HitPoint + 0.75f * attackment.HitDirection,
                    1f * attackment.HitDirection + attackment.Target.FindComponent<ComponentBody>().Velocity,
                    Color.White,
                    "-" + NumericalProcessingManager.NumericalProcessing(attackment.AttackPower)
                );
                attackment.Attacker.Project.FindSubsystem<SubsystemParticles>(true).AddParticleSystem(particleSystem);
            }
        }

