        public override void LoadSettings(XElement xElement)
        {
            PermanentlySavedAttributesManager.Talent.Clear();
            PermanentlySavedAttributesManager.Skills.Clear();
            PermanentlySavedAttributesManager.ComponentBlock.Clear();
            PermanentlySavedAttributesManager.Mailbox.Clear();
            CraftingHYZLRecipesManager.Initialize();
            AccessTalentManager.Initialize("AccessTalentManager");
            AccessSkillsManager.Initialize("AccessSkillsManager");
            AccessEventCenterManager.Initialize("AccessEventCenterManager");
            PermanentlySavedAttributesManager.Initialize();

            DateTime beijingNow = TimeZoneInfo.ConvertTime(DateTime.UtcNow, TimeZoneInfo.FindSystemTimeZoneById("China Standard Time"));
            DateTime today8Am = beijingNow.Date.AddHours(8);

            XElement dictElement = xElement.Element("HYZLSettings");
            if (dictElement != null)
            {
                foreach (var item99 in dictElement.Elements("PermanentlySavedAttributesManagerLastResetDate"))
                {
                    PermanentlySavedAttributesManager.LastResetDate = (DateTime)item99.Attribute("LastResetDate");
                }
                foreach (var item100 in dictElement.Elements("PermanentlySavedAttributesManagerTalent"))
                {
                    int key = (int)item100.Attribute("TalentID");
                    bool Item1 = (bool)item100.Attribute("Have");
                    int Item2 = (int)item100.Attribute("Level");
                    PermanentlySavedAttributesManager.Talent[key] = (Item1, Item2);
                }
                foreach (var item101 in dictElement.Elements("PermanentlySavedAttributesManagerSkills"))
                {
                    int key = (int)item101.Attribute("SkillsID");
                    bool Item1 = (bool)item101.Attribute("Have");
                    PermanentlySavedAttributesManager.Skills[key] = Item1;
                }
                foreach (var item102 in dictElement.Elements("PermanentlySavedAttributesManagerComponentBlock"))
                {
                    string key = (string)item102.Attribute("ComponentName");
                    bool Item1 = (bool)item102.Attribute("Possessing");
                    bool Item2 = (bool)item102.Attribute("Equipment");
                    int Item3 = (int)item102.Attribute("CurrentExp");
                    int Item4 = (int)item102.Attribute("MaxExp");
                    int Item5 = (int)item102.Attribute("Level");
                    if (key != null)
                        PermanentlySavedAttributesManager.ComponentBlock[key] = (Item1, Item2, Item3, Item4, Item5);
                }
                foreach (var item103 in dictElement.Elements("PermanentlySavedAttributesManagerMailbox"))
                {
                    int key = (int)item103.Attribute("MailboxID");
                    string Item1 = (string)item103.Attribute("Title");
                    string Item2 = (string)item103.Attribute("From");
                    long Item3 = (long)item103.Attribute("FromID");
                    string Item4 = (string)item103.Attribute("Message");
                    string Item5 = (string)item103.Attribute("Items");
                    double Item6 = (double)item103.Attribute("DeletingTime");
                    bool Item7 = (bool)item103.Attribute("WhetherToView");
                    TimeSpan diff = new DateTime((long)(Item6 * TimeSpan.TicksPerMinute), DateTimeKind.Utc) - DateTime.Now;
                    if (diff.Minutes > 0)
                    {
                        PermanentlySavedAttributesManager.Mailbox[key] = (Item1, Item2, Item3, Item4, Item5, Item6, Item7);
                    }
                }
                foreach (var item104 in dictElement.Elements("PermanentlySavedAttributesManagerMoney"))
                {
                    string key = (string)item104.Attribute("MoneyName");
                    float Item1 = (float)item104.Attribute("MoneyValue");
                    PermanentlySavedAttributesManager.Money[key] = Item1;
                }
                foreach (var item105 in dictElement.Elements("PermanentlySavedAttributesManagerActivityParameters"))
                {
                    string key = (string)item105.Attribute("ActivityParametersName");
                    float Item1 = (float)item105.Attribute("ActivityParametersValue");

                    if (!(beijingNow >= today8Am && PermanentlySavedAttributesManager.LastResetDate.Date != beijingNow.Date && Item1 > 0))
                    {
                        PermanentlySavedAttributesManager.ActivityParameters[key] = Item1;
                    }
                }
                foreach (var item106 in dictElement.Elements("PermanentlySavedAttributesManagerActivityCompletion"))
                {
                    int key = (int)item106.Attribute("ActivityCompletionID");
                    bool Item1 = (bool)item106.Attribute("Completion");
                    bool Item2 = (bool)item106.Attribute("Reset");

                    if (!(beijingNow >= today8Am && PermanentlySavedAttributesManager.LastResetDate.Date != beijingNow.Date && Item1 && Item2))
                    {
                        PermanentlySavedAttributesManager.ActivityCompletion[key] = (Item1, Item2);
                    }
                }
                foreach (var item107 in dictElement.Elements("PermanentlySavedAttributesManagerStepping"))
                {
                    string key = (string)item107.Attribute("SteppingName");
                    bool Item1 = (bool)item107.Attribute("SteppingValue");
                    PermanentlySavedAttributesManager.Stepping[key] = Item1;
                }
                foreach (var item108 in dictElement.Elements("PermanentlySavedAttributesManagerArchiveProperties"))
                {
                    int key = (int)item108.Attribute("ArchivePropertiesName");
                    double Item1 = (double)item108.Attribute("InitialSurvivalDays");
                    if (beijingNow >= today8Am && PermanentlySavedAttributesManager.LastResetDate.Date != beijingNow.Date && Item1 > 0)
                    {
                        PermanentlySavedAttributesManager.LastResetDate = beijingNow.Date;
                    }
                    else
                    {
                        PermanentlySavedAttributesManager.ArchiveProperties[key] = Item1;
                    }
                }
            }
        }
