        public override void OnEntityAdd(Entity entity)
        {
            componentPlayer = entity.FindComponent<ComponentPlayer>();
            MailboxScreen mailboxScreen = new(componentPlayer);
            if (!ScreensManager.m_screens.ContainsKey("Mailbox"))
                ScreensManager.AddScreen("Mailbox", mailboxScreen);
            int num = 0;
            if (componentPlayer != null)
            {
                if (!componentPlayer.PlayerStats.ValuesDictionaryForMods.ContainsKey("ArchiveID"))
                {
                    while (PermanentlySavedAttributesManager.ArchiveProperties.ContainsKey(num))
                    {
                        num++;
                    }
                    componentPlayer.PlayerStats.ValuesDictionaryForMods["ArchiveID"] = num;
                    PermanentlySavedAttributesManager.ArchiveProperties[num] = componentPlayer.m_subsystemGameInfo.TotalElapsedGameTime;
                }
                else
                {
                    if (!PermanentlySavedAttributesManager.ArchiveProperties.TryGetValue((int)componentPlayer.PlayerStats.ValuesDictionaryForMods["ArchiveID"], out double val))
                        PermanentlySavedAttributesManager.ArchiveProperties[(int)componentPlayer.PlayerStats.ValuesDictionaryForMods["ArchiveID"]] = componentPlayer.m_subsystemGameInfo.TotalElapsedGameTime;
                }
            }
        }

        public override void UpdateComponentBody(ComponentBody componentBody, float dt, bool skippedByOtherMods, out bool skipVanilla)
        {
            componentBody.UpdateImmersionData();

            Vector3 pos = componentBody.Position;
            int x = Terrain.ToCell(pos.X);
            int y = Terrain.ToCell(pos.Y + 0.01f);
            int z = Terrain.ToCell(pos.Z);
            int cellValue = componentBody.m_subsystemTerrain.Terrain.GetCellValue(x, y, z);
            int contents = Terrain.ExtractContents(cellValue);

            if (contents == NewArchitecture.Index)
            {
                componentBody.ImmersionFluidBlock = null;
                componentBody.ImmersionDepth = 0f;
                componentBody.ImmersionFactor = 0f;
            }
            else
            {
                if (componentBody.ImmersionFluidBlock is NewWaterBlock && componentBody.ImmersionDepth > 0.3f && !componentBody.m_fluidEffectsPlayed)
                {
                    componentBody.m_fluidEffectsPlayed = true;
                    componentBody.m_subsystemAudio.PlayRandomSound("Audio/WaterFallIn",
                        m_random.Float(0.75f, 1f),
                        m_random.Float(-0.3f, 0f),
                        componentBody.Position, 4f, true);
                    componentBody.m_subsystemParticles.AddParticleSystem(
                        new WaterSplashParticleSystem(componentBody.m_subsystemTerrain,
                            componentBody.Position,
                            (componentBody.BoundingBox.Max - componentBody.BoundingBox.Min).Length() > 0.8f));
                }
            }

            skipVanilla = false;
        }

        public virtual void GenerateStoneForest(TerrainChunk chunk)
        {
            int key = chunk.Coords.GetHashCode();
            if (!s_stoneForestCoroutines.TryGetValue(key, out var enumerator))
            {
                enumerator = StoneForestCoroutine(chunk);
                s_stoneForestCoroutines[key] = enumerator;
            }
            float timeBudget = (float)Time.FrameStartTime + 0.005f;
            while (enumerator.MoveNext())
            {
                if (Time.FrameStartTime > timeBudget) return;
            }
            s_stoneForestCoroutines.Remove(key);
        }

        public IEnumerator<bool> StoneForestCoroutine(TerrainChunk chunk)
        {
            int originX = (int)chunk.Origin.X;
            int originZ = (int)chunk.Origin.Y;
            foreach (AccessNewTerrain terrain in AccessNewTerrainManager.Data)
            {
                for (int x = 0; x < 16; x++)
                {
                    for (int z = 0; z < 16; z++)
                    {
                        int worldX = x + originX;
                        int worldZ = z + originZ;
                        int seaLevel = m_subsystemTerrain.Terrain.CalculateTopmostCellHeight(worldX, worldZ);
                        int checkY = Math.Clamp(seaLevel - 1, 0, 255);
                        if (seaLevel <= 0 || seaLevel > 255) continue;

                        float biomeNoise = SimplexNoise.OctavedNoise(
                            worldX + terrainContentsGenerator24.m_temperatureOffset.X * terrain.TerrainXOffsetFactor,
                            worldZ + terrainContentsGenerator24.m_temperatureOffset.Y * terrain.TerrainYOffsetFactor,
                            terrain.TerrainFrequency / terrainContentsGenerator24.TGBiomeScaling,
                            terrain.TerrainOctaves, terrain.TerrainFrequencyStep, terrain.TerrainAmplitudeStep);
                        if (biomeNoise >= terrain.TerrainProbability) continue;

                        float baseHeightNoise = SimplexNoise.OctavedNoise(
                            worldX + terrainContentsGenerator24.m_temperatureOffset.X * terrain.HeightOfFoundationXOffsetFactor,
                            worldZ + terrainContentsGenerator24.m_temperatureOffset.Y * terrain.HeightOfFoundationXOffsetFactor,
                            terrain.HeightOfFoundationFrequency / terrainContentsGenerator24.TGBiomeScaling,
                            terrain.HeightOfFoundationOctaves, terrain.HeightOfFoundationFrequencyStep, terrain.HeightOfFoundationAmplitudeStep);
                        int baseHeight = seaLevel + (int)(baseHeightNoise * terrain.HeightOfFoundationCoefficientOfHeight);

                        float pillarHeightNoise = SimplexNoise.OctavedNoise(
                            worldX + terrainContentsGenerator24.m_temperatureOffset.X * terrain.ExtraHeightXOffsetFactor,
                            worldZ + terrainContentsGenerator24.m_temperatureOffset.Y * terrain.ExtraHeightYOffsetFactor,
                            terrain.ExtraHeightFrequency / terrainContentsGenerator24.TGBiomeScaling,
                            terrain.ExtraHeightOctaves, terrain.ExtraHeightFrequencyStep, terrain.ExtraHeightAmplitudeStep);
                        int pillarHeight = (int)(Math.Abs(pillarHeightNoise) * terrain.ExtraHeightCoefficientOfHeight);

                        float dirtThicknessNoise = SimplexNoise.OctavedNoise(
                            worldX + terrainContentsGenerator24.m_temperatureOffset.X * terrain.HeightOfSoilXOffsetFactor,
                            worldZ + terrainContentsGenerator24.m_temperatureOffset.Y * terrain.HeightOfSoilYOffsetFactor,
                            terrain.HeightOfSoilFrequency / terrainContentsGenerator24.TGBiomeScaling,
                            terrain.HeightOfSoilOctaves, terrain.HeightOfSoilFrequencyStep, terrain.HeightOfSoilAmplitudeStep);
                        int dirtThickness = terrain.HeightOfSoilHeightOfFoundation + (int)((dirtThicknessNoise + terrain.HeightOfSoilAltitudeOffset) * terrain.HeightOfSoilCoefficientOfHeight);

                        float waterNoise = SimplexNoise.OctavedNoise(
                            worldX + terrainContentsGenerator24.m_temperatureOffset.X * terrain.WaterHeightXOffsetFactor,
                            worldZ + terrainContentsGenerator24.m_temperatureOffset.Y * terrain.WaterHeightYOffsetFactor,
                            terrain.WaterHeightFrequency / terrainContentsGenerator24.TGBiomeScaling,
                            terrain.WaterHeightOctaves, terrain.WaterHeightFrequencyStep, terrain.WaterHeightAmplitudeStep);
                        bool shouldGenerateWater = waterNoise > terrain.WaterHeightMinProbability && waterNoise < terrain.WaterHeightMaxProbability;
                        int waterDepth = shouldGenerateWater ?
                            terrain.WaterHeightHeightOfFoundation + (int)((waterNoise - terrain.WaterHeightAltitudeOffset) * terrain.WaterHeightCoefficientOfHeight) :
                            terrain.WaterHeightDefaultHeight;

                        int targetHeight = baseHeight + pillarHeight;
                        targetHeight = Math.Clamp(targetHeight, 1, 255);
                        if (targetHeight < seaLevel || chunk.GetCellContentsFast(x, checkY, z) == NewBlock.Index || chunk.GetCellContentsFast(x, checkY, z) == WaterBlock.Index || chunk.GetCellContentsFast(x, checkY, z) == IceBlock.Index || chunk.GetCellContentsFast(x, checkY, z) == SnowBlock.Index)
                            continue;

                        int grassBlock = CraftingRecipesManager.DecodeResult(terrain.ClassNameOfGrassBox);
                        int soilBlock = CraftingRecipesManager.DecodeResult(terrain.NameOfSoilClass);
                        int stoneBlock = CraftingRecipesManager.DecodeResult(terrain.NamesOfGranitoids);
                        for (int y = targetHeight; y > 0; y--)
                        {
                            int blockValue = (y == targetHeight) ? grassBlock :
                                             (y > targetHeight - dirtThickness) ? soilBlock : stoneBlock;
                            chunk.SetCellValueFast(x, y, z, blockValue);
                        }

                        if (shouldGenerateWater && targetHeight > seaLevel)
                        {
                            int gravelBottom = Math.Max(0, targetHeight - terrain.HeightOffsetOfGeneratedGravel - terrain.HeightShiftOfGeneratedWater);
                            int waterBottom = Math.Max(0, targetHeight - terrain.HeightShiftOfGeneratedWater);
                            int gravelBlock = CraftingRecipesManager.DecodeResult(terrain.NameOfClassOfCrushedStone);
                            int waterBlock = CraftingRecipesManager.DecodeResult(terrain.NamesOfWaterClasses);
                            int topY = Math.Min(targetHeight, 255);
                            for (int y = topY; y > gravelBottom; y--)
                                chunk.SetCellValueFast(x, y, z, gravelBlock);
                            for (int y = topY; y > waterBottom; y--)
                                chunk.SetCellValueFast(x, y, z, waterBlock);
                        }

                        int newTop = (shouldGenerateWater && targetHeight > seaLevel) ? targetHeight : targetHeight;
                        chunk.SetTopHeightFast(x, z, newTop);
                        chunk.SetBottomHeightFast(x, z, 0);
                    }
                    if (x % 4 == 0) yield return true;
                }
            }
            yield break;
        }

        public virtual void GeneratePalmTrees(TerrainChunk chunk)
        {
            int key = chunk.Coords.GetHashCode();
            if (!s_palmTreeCoroutines.TryGetValue(key, out var enumerator))
            {
                enumerator = PalmTreeCoroutine(chunk);
                s_palmTreeCoroutines[key] = enumerator;
            }
            float timeBudget = (float)Time.FrameStartTime + 0.005f;
            while (enumerator.MoveNext())
            {
                if (Time.FrameStartTime > timeBudget) return;
            }
            s_palmTreeCoroutines.Remove(key);
        }

        public IEnumerator<bool> PalmTreeCoroutine(TerrainChunk chunk)
        {
            SubsystemTerrain subsystemTerrain = m_subsystemTerrain;
            int chunkOriginX = chunk.Origin.X;
            int chunkOriginZ = chunk.Origin.Y;
            HashSet<(int, int)> generatedPositions = new HashSet<(int, int)>();
            float noiseSeed1 = m_random.Float(0, 1000);
            float noiseSeed2 = m_random.Float(0, 1000);

            foreach (AccessNewTreeTerrain treeConfig in AccessNewTreeTerrainManager.Data)
            {
                string treeData = ContentManager.Get<string>(treeConfig.TreeFiles).Replace("\r", string.Empty);
                string[] treeLines = treeData.Split('\n', StringSplitOptions.RemoveEmptyEntries);
                var parsedTreeData = new (int offsetX, int offsetY, int offsetZ, int blockId)[treeLines.Length];
                int treeDataCount = 0;
                foreach (string line in treeLines)
                {
                    string[] parts = line.Split(',');
                    if (parts.Length >= 4)
                    {
                        parsedTreeData[treeDataCount++] = (int.Parse(parts[0]), int.Parse(parts[1]), int.Parse(parts[2]), CraftingRecipesManager.DecodeResult(parts[3]));
                    }
                }
                if (treeDataCount == 0) continue;

                List<(int x, int z)> samplePoints = new List<(int x, int z)>();
                for (int x = 0; x < 16; x++)
                    for (int z = 0; z < 16; z++)
                        if (m_random.Float() <= treeConfig.SamplingProbability)
                            samplePoints.Add((x, z));
                samplePoints = samplePoints.OrderBy(p => m_random.Int()).ToList();

                foreach (var (x, z) in samplePoints)
                {
                    float randOffsetX = m_random.Float(-0.5f, 0.5f);
                    float randOffsetZ = m_random.Float(-0.5f, 0.5f);
                    float worldX = chunkOriginX + x + randOffsetX;
                    float worldZ = chunkOriginZ + z + randOffsetZ;

                    bool tooClose = false;
                    float minDistSq = treeConfig.MinimumDistanceBetweenTrees * treeConfig.MinimumDistanceBetweenTrees;
                    foreach (var (genX, genZ) in generatedPositions)
                    {
                        float dx = worldX - (genX + 0.5f);
                        float dz = worldZ - (genZ + 0.5f);
                        if (dx * dx + dz * dz < minDistSq) { tooClose = true; break; }
                    }
                    if (tooClose) continue;

                    float baseNoise = SimplexNoise.OctavedNoise(worldX * treeConfig.TreeXOffsetFactor, worldZ * treeConfig.TreeYOffsetFactor, treeConfig.TreeDistributionFrequency / treeConfig.TreeInterval, treeConfig.TreeOctaves, treeConfig.TreeFrequencyStep, treeConfig.TreeAmplitudeStep);
                    float detailNoise = SimplexNoise.OctavedNoise(worldX * treeConfig.DetailsXOffsetFactor + noiseSeed1 * 2, worldZ * treeConfig.DetailsYOffsetFactor + noiseSeed2 * 2, treeConfig.DetailsInterval, treeConfig.DetailsOctaves, treeConfig.DetailsFrequencyStep, treeConfig.DetailsAmplitudeStep) * treeConfig.DetailsCoefficient;
                    float treeNoise = (baseNoise + detailNoise) * 0.6f + 0.2f;
                    float centerDistX = Math.Abs(x - 7.5f) / 8f;
                    float centerDistZ = Math.Abs(z - 7.5f) / 8f;
                    float centerFactor = 1.2f - Math.Max(centerDistX, centerDistZ) * 0.4f;
                    float randomFactor = m_random.Float(0.7f, 1.3f);
                    float threshold = treeConfig.TreeProbability * randomFactor * centerFactor;

                    if (treeNoise <= threshold) continue;

                    int terrainHeight = subsystemTerrain.Terrain.CalculateTopmostCellHeight((int)Math.Floor(worldX), (int)Math.Floor(worldZ));
                    bool validGround = false;
                    int groundCheckRadius = 1;
                    for (int dx = -groundCheckRadius; dx <= groundCheckRadius && !validGround; dx++)
                    {
                        for (int dz = -groundCheckRadius; dz <= groundCheckRadius && !validGround; dz++)
                        {
                            int checkX = (int)Math.Floor(worldX) + dx;
                            int checkZ = (int)Math.Floor(worldZ) + dz;
                            if (checkX < chunkOriginX || checkX >= chunkOriginX + 16 || checkZ < chunkOriginZ || checkZ >= chunkOriginZ + 16) continue;
                            int localX = checkX - chunkOriginX;
                            int localZ = checkZ - chunkOriginZ;
                            if (chunk.GetCellValueFast(localX, terrainHeight, localZ) == CraftingRecipesManager.DecodeResult(treeConfig.TheSquareAtTheFoot))
                            {
                                validGround = true;
                                int baseY = terrainHeight + 1;
                                for (int i = 0; i < treeDataCount; i++)
                                {
                                    var (offsetX, offsetY, offsetZ, blockId) = parsedTreeData[i];
                                    int treeX = checkX + offsetX;
                                    int treeY = baseY + offsetY;
                                    int treeZ = checkZ + offsetZ;
                                    if (treeX >= chunkOriginX && treeX < chunkOriginX + 16 && treeZ >= chunkOriginZ && treeZ < chunkOriginZ + 16)
                                    {
                                        chunk.SetCellValueFast(treeX - chunkOriginX, treeY, treeZ - chunkOriginZ, blockId);
                                    }
                                }
                                generatedPositions.Add((checkX, checkZ));
                                break;
                            }
                        }
                    }
                    yield return true;
                }
            }
            yield break;
        }

        public virtual void GenerateRockyForest(TerrainChunk chunk)
        {
            int key = chunk.Coords.GetHashCode();
            if (!s_rockyForestCoroutines.TryGetValue(key, out var enumerator))
            {
                enumerator = RockyForestCoroutine(chunk);
                s_rockyForestCoroutines[key] = enumerator;
            }
            float timeBudget = (float)Time.FrameStartTime + 0.005f;
            while (enumerator.MoveNext())
            {
                if (Time.FrameStartTime > timeBudget) return;
            }
            s_rockyForestCoroutines.Remove(key);
        }

        public IEnumerator<bool> RockyForestCoroutine(TerrainChunk chunk)
        {
            int chunkOriginX = chunk.Origin.X;
            int chunkOriginZ = chunk.Origin.Y;
            foreach (AccessNewColumnarTerrain terrain in AccessNewColumnarTerrainManager.Data)
            {
                for (int i = 0; i < 16; i++)
                {
                    for (int j = 0; j < 16; j++)
                    {
                        int worldX = i + chunkOriginX;
                        int worldY = j + chunkOriginZ;

                        float rockNoise = SimplexNoise.OctavedNoise(worldX * terrain.DistributionXOffsetFactor, worldY * terrain.DistributionYOffsetFactor, terrain.DistributionFrequency, terrain.DistributionOctaves, terrain.DistributionFrequencyStep, terrain.DistributionAmplitudeStep);
                        float densityNoise = SimplexNoise.OctavedNoise(worldX * terrain.DensityXOffsetFactor, worldY * terrain.DensityYOffsetFactor, terrain.DensityFrequency, terrain.DensityOctaves, terrain.DensityFrequencyStep, terrain.DensityAmplitudeStep);

                        int surfaceHeight = -1;
                        int surfaceBlockId = CraftingRecipesManager.DecodeResult(terrain.BigPillarsClassNameOfSurfaceBlock);
                        int littleSurfaceBlockId = CraftingRecipesManager.DecodeResult(terrain.LittlePillarsClassNameOfSurfaceBlock);
                        for (int h = 127; h > 0; h--)
                        {
                            int blockType = chunk.GetCellValueFast(i, h, j);
                            if (blockType == surfaceBlockId || blockType == littleSurfaceBlockId)
                            {
                                surfaceHeight = h;
                                break;
                            }
                        }
                        if (surfaceHeight == -1) continue;

                        if (rockNoise > terrain.BigPillarsProbability && densityNoise > terrain.BigPillarsDensity)
                        {
                            int rockHeight = terrain.BigPillarsInitialHeight + (int)((rockNoise - terrain.BigPillarsAltitudeOffset) * terrain.BigPillarsCoefficientOfHeight);
                            if (rockHeight > terrain.BigPillarsUpperLimitOfHeight) rockHeight = terrain.BigPillarsUpperLimitOfHeight;
                            int fillBlock = CraftingRecipesManager.DecodeResult(terrain.BigPillarsFillTheBoxClassName);
                            for (int rockLayer = 0; rockLayer < rockHeight; rockLayer++)
                            {
                                int currentHeight = surfaceHeight + 1 + rockLayer;
                                if (currentHeight < 128)
                                    chunk.SetCellValueFast(i, currentHeight, j, fillBlock);
                            }
                            if (rockHeight > 0)
                            {
                                int newTop = Math.Min(127, surfaceHeight + rockHeight);
                                chunk.SetTopHeightFast(i, j, newTop);
                            }
                        }
                        else if (rockNoise > terrain.LittlePillarsMinProbability && rockNoise < terrain.LittlePillarsMaxProbability)
                        {
                            chunk.SetCellValueFast(i, surfaceHeight + 1, j, CraftingRecipesManager.DecodeResult(terrain.LittlePillarsFillTheBoxClassName));
                            if (surfaceHeight + 1 > 0 && surfaceHeight + 1 < 256)
                            {
                                chunk.SetTopHeightFast(i, j, Math.Max(chunk.GetTopHeightFast(i, j), surfaceHeight + 1));
                            }
                        }
                    }
                    if (i % 4 == 0) yield return true;
                }
            }
            yield break;
        }

