        public IEnumerator<bool> CaveCoroutine(TerrainChunk chunk)
        {
            int ox = chunk.Origin.X;
            int oz = chunk.Origin.Y;
            var carve = new List<(int, int, int)>();

            for (int lx = 0; lx < 16; lx++)
            {
                for (int lz = 0; lz < 16; lz++)
                {
                    int wx = lx + ox, wz = lz + oz;
                    int sh = m_subsystemTerrain.Terrain.CalculateTopmostCellHeight(wx, wz);
                    if (sh <= 30 || chunk.GetCellValueFast(lx, sh, lz) != Terrain.MakeBlockValue(NewBlock.Index, 0, 28)) continue;

                    float n = SimplexNoise.OctavedNoise(wx * 0.05f + wz * 0.03f, wz * 0.05f + wx * 0.03f, 4, 2.2f, 0.45f);
                    float t = SimplexNoise.OctavedNoise(wx * 0.015f, wz * 0.015f, 3, 2.0f, 0.5f) * 25;

                    for (int y = Math.Max(0, sh); y < Math.Min(255, sh + 50); y++)
                    {
                        float hf = 1f - Math.Abs((y - (sh + 15)) / 25f);
                        float vo = SimplexNoise.OctavedNoise(wx * 0.02f, y * 0.02f, wz * 0.02f, 2, 1.5f, 0.5f) * 10;
                        float caveValue = Math.Abs(n + t * 0.1f + vo * 0.05f);
                        if (caveValue >= 0.125f * hf)
                        {
                            float d = SimplexNoise.OctavedNoise(wx * 0.012f + y * 0.003f, y * 0.012f + wz * 0.003f, wz * 0.012f + wx * 0.003f, 3, 2.5f, 0.5f);
                            float b = SimplexNoise.OctavedNoise(wx * 0.008f + y * 0.004f, y * 0.008f + wz * 0.004f, wz * 0.008f + wx * 0.004f, 2, 1.8f, 0.6f);
                            if (Math.Abs(d) < 0.5f || Math.Abs(b) < 0.4f)
                            {
                                carve.Add((lx, y, lz));
                                if (Math.Abs(SimplexNoise.OctavedNoise(wx * 0.01f, y * 0.01f, wz * 0.01f, 1, 1.0f, 0.5f)) < 0.3f)
                                {
                                    if (lx > 0) carve.Add((lx - 1, y, lz));
                                    if (lx < 15) carve.Add((lx + 1, y, lz));
                                    if (lz > 0) carve.Add((lx, y, lz - 1));
                                    if (lz < 15) carve.Add((lx, y, lz + 1));
                                }
                            }
                        }
                    }
                }
                if (lx % 4 == 0) yield return true;
            }

            for (int lx = 0; lx < 16; lx++)
            {
                for (int lz = 0; lz < 16; lz++)
                {
                    int wx = lx + ox, wz = lz + oz;
                    int sh = m_subsystemTerrain.Terrain.CalculateTopmostCellHeight(wx, wz);
                    if (sh <= 30 || chunk.GetCellValueFast(lx, sh, lz) != Terrain.MakeBlockValue(NewBlock.Index, 0, 28)) continue;
                    for (int y = Math.Max(0, sh); y < Math.Min(255, sh + 50); y++)
                        chunk.SetCellValueFast(lx, y, lz, Terrain.MakeBlockValue(NewBlock.Index, 0, 30));
                }
            }

            foreach (var (x, y, z) in carve)
            {
                if (y >= 0 && y < 256) chunk.SetCellValueFast(x, y, z, 0);
            }

            for (int lx = 0; lx < 16; lx++)
            {
                for (int lz = 0; lz < 16; lz++)
                {
                    int top = chunk.CalculateTopmostCellHeight(lx, lz);
                    chunk.SetTopHeightFast(lx, lz, top);
                    chunk.SetBottomHeightFast(lx, lz, 0);
                }
            }
            yield break;
        }

