        public IEnumerator<bool> PlantsCoroutine(TerrainChunk chunk)
        {
            int chunkX = chunk.Coords.X;
            int chunkY = chunk.Coords.Y;
            foreach (AccessNewPlantsTerrain plantTerrain in AccessNewPlantsTerrainManager.Data)
            {
                if (WorldName == plantTerrain.Latitude)
                {
                    for (int a = 0; a < plantTerrain.OffsetOfARandomNumber.Length; a++)
                    {
                        Random random = new Random(terrainContentsGenerator24.m_seed + chunkX + int.Parse(plantTerrain.OffsetOfARandomNumber[a]) * chunkY);
                        int generateCount = random.Int(plantTerrain.MinimumNumberOfGenerationTimes, plantTerrain.MaximumNumberOfGenerationTimes);
                        int boxBelowType = CraftingRecipesManager.DecodeResult(plantTerrain.TheClassNameOfTheBoxBelow[a]);
                        int plantType = CraftingRecipesManager.DecodeResult(plantTerrain.GenerateTheClassNameOfTheBox);

                        for (int i = 0; i < generateCount; i++)
                        {
                            int baseX = random.Int(plantTerrain.MinimumXCoordinateShift, plantTerrain.MaximumXCoordinateShift);
                            int baseZ = random.Int(plantTerrain.MinimumZCoordinateShift, plantTerrain.MaximumZCoordinateShift);
                            for (int attempt = 0; attempt < 5; attempt++)
                            {
                                int finalX = baseX + random.Int(plantTerrain.MinimumXCoordinateExtraOffset, plantTerrain.MaximumXCoordinateExtraOffset);
                                int finalZ = baseZ + random.Int(plantTerrain.MinimumZCoordinateExtraOffset, plantTerrain.MaximumZCoordinateExtraOffset);
                                if (finalX < 0 || finalX >= 16 || finalZ < 0 || finalZ >= 16) continue;
                                for (int height = plantTerrain.GeneratesTheMaximumHeight; height >= 0; height--)
                                {
                                    if (height >= 255) break;
                                    if (chunk.GetCellValueFast(finalX, height, finalZ) == boxBelowType && chunk.GetCellValueFast(finalX, height + 1, finalZ) == 0)
                                    {
                                        int valueToSet = random.Bool(plantTerrain.ProbabilityOfzGeneration) ? plantType : 0;
                                        for (int height2 = 1; height2 < plantTerrain.MaximumHeightOfPlantFormation + 1; height2++)
                                        {
                                            int setY = height + height2;
                                            if (setY < 256)
                                                chunk.SetCellValueFast(finalX, setY, finalZ, valueToSet);
                                        }
                                        if (valueToSet != 0)
                                        {
                                            int newTop = height + plantTerrain.MaximumHeightOfPlantFormation;
                                            if (newTop < 256 && newTop > chunk.GetTopHeightFast(finalX, finalZ))
                                                chunk.SetTopHeightFast(finalX, finalZ, newTop);
                                        }
                                        break;
                                    }
                                }
                            }
                            if (i % 4 == 0) yield return true;
                        }
                    }
                }
            }
            yield break;
        }
        public virtual void GenerateMultidimensionalWorldTerrainFramewor(TerrainChunk chunk)
        {
            int key = chunk.Coords.GetHashCode();
            if (!s_multidimensionalCoroutines.TryGetValue(key, out var enumerator))
            {
                enumerator = Coroutine();
                s_multidimensionalCoroutines[key] = enumerator;
            }

            float timeBudget = (float)Time.FrameStartTime + 0.005f;
            while (enumerator.MoveNext())
            {
                if (Time.FrameStartTime > timeBudget) return;
            }
            s_multidimensionalCoroutines.Remove(key);

            IEnumerator<bool> Coroutine()
            {
                var cfg = AccessNewMultidimensionalWorldTerrainFrameworkManager.Get(WorldName);
                int topHeight = cfg.TopHeight;
                int combinedHeight = cfg.MediumHeight + cfg.TopHeight;
                int topCubeValue = CraftingRecipesManager.DecodeResult(cfg.TopCubeClassName);
                int middleCubeValue = CraftingRecipesManager.DecodeResult(cfg.MiddleCubeClassName);

                for (int i = 0; i < 16; i++)
                {
                    for (int j = 0; j < 16; j++)
                    {
                        for (int a = 0; a < 255; a++)
                        {
                            int value = (a == (255 - combinedHeight - topHeight * 2) + topHeight - 1 || a == combinedHeight + topHeight * 2 - 1) ? topCubeValue : middleCubeValue;
                            chunk.SetCellValueFast(i, a, j, value);
                        }
                        yield return true;
                    }
                }
            }
        }

