        public IEnumerator<bool> WindholesCaveCoroutine(TerrainChunk chunk)
        {
            if (!terrainContentsGenerator24.TGCavesAndPockets) yield break;
            int portalIndex = NewPortalBlock.Index;
            int originX = chunk.Origin.X;
            int originZ = chunk.Origin.Y;
            var branchPoints = new List<(Vector3 pos, Vector3 dir)>();
            for (int dx = -2; dx <= 2; dx++)
            {
                for (int dz = -2; dz <= 2; dz++)
                {
                    int bx = chunk.Coords.X + dx;
                    int bz = chunk.Coords.Y + dz;
                    Random random = new Random(terrainContentsGenerator24.m_seed + bx + 9973 * bz);
                    int snakeCount = random.Int(0, 2);
                    for (int s = 0; s < snakeCount; s++)
                    {
                        Vector3 pos, dir;
                        if (branchPoints.Count > 0 && random.Bool(0.95f))
                        {
                            var branch = branchPoints[random.Int(0, branchPoints.Count - 1)];
                            pos = branch.pos + branch.dir * random.Float(0.5f, 2f);
                            dir = Vector3.Normalize(branch.dir + random.Vector3(0.4f));
                            dir.Y = Math.Clamp(dir.Y, -0.5f, 0.5f);
                        }
                        else
                        {
                            pos = new Vector3(bx * 16 + random.Float(0f, 15f), random.Int(20, 200), bz * 16 + random.Float(0f, 15f));
                            dir = Vector3.Normalize(new Vector3(random.Float(-1f, 1f), random.Float(-0.3f, 0.3f), random.Float(-1f, 1f)));
                        }
                        int length = 100;
                        float stepSize = 2f;
                        bool regular = random.Bool(0.5f);
                        int step = 0;
                        while (step < length)
                        {
                            pos += dir * stepSize;
                            step++;
                            if (step % 10 == 0) branchPoints.Add((pos, dir));
                            float localXf = pos.X - originX;
                            float localZf = pos.Z - originZ;
                            if (localXf < -6f || localXf > 22f || localZf < -6f || localZf > 22f || pos.Y < 2f || pos.Y > 253f)
                            {
                                yield return true;
                                break;
                            }
                            float radius = random.Float(2.2f, 3.3f);
                            int minX = (int)MathF.Floor(pos.X - radius);
                            int maxX = (int)MathF.Ceiling(pos.X + radius);
                            int minY = (int)MathF.Floor(pos.Y - radius);
                            int maxY = (int)MathF.Ceiling(pos.Y + radius);
                            int minZ = (int)MathF.Floor(pos.Z - radius);
                            int maxZ = (int)MathF.Ceiling(pos.Z + radius);
                            for (int x = minX; x <= maxX; x++)
                            {
                                int lx = x - originX;
                                if (lx < 0 || lx >= 16) continue;
                                for (int z = minZ; z <= maxZ; z++)
                                {
                                    int lz = z - originZ;
                                    if (lz < 0 || lz >= 16) continue;
                                    float dx2 = x + 0.5f - pos.X;
                                    float dz2 = z + 0.5f - pos.Z;
                                    float distSq = dx2 * dx2 + dz2 * dz2;
                                    if (distSq > radius * radius) continue;
                                    for (int y = minY; y <= maxY; y++)
                                    {
                                        float dy = y + 0.5f - pos.Y;
                                        if (dx2 * dx2 + dy * dy + dz2 * dz2 > radius * radius) continue;
                                        if (y < 0 || y > 255) continue;
                                        if (chunk.GetCellContentsFast(lx, y, lz) != portalIndex)
                                            chunk.SetCellValueFast(lx, y, lz, 0);
                                    }
                                }
                            }
                            if (step % 70 < 5)
                            {
                                float voidOffset = random.Float(8f, 16f);
                                Vector3 voidDir = Vector3.Normalize(random.Vector3(1f));
                                Vector3 voidCenter = pos + voidDir * voidOffset;
                                float voidRadius = random.Float(5f, 8f);
                                int vMinX = (int)MathF.Floor(voidCenter.X - voidRadius);
                                int vMaxX = (int)MathF.Ceiling(voidCenter.X + voidRadius);
                                int vMinY = (int)MathF.Floor(voidCenter.Y - voidRadius);
                                int vMaxY = (int)MathF.Ceiling(voidCenter.Y + voidRadius);
                                int vMinZ = (int)MathF.Floor(voidCenter.Z - voidRadius);
                                int vMaxZ = (int)MathF.Ceiling(voidCenter.Z + voidRadius);
                                for (int x = vMinX; x <= vMaxX; x++)
                                {
                                    int lx = x - originX;
                                    if (lx < 0 || lx >= 16) continue;
                                    for (int z = vMinZ; z <= vMaxZ; z++)
                                    {
                                        int lz = z - originZ;
                                        if (lz < 0 || lz >= 16) continue;
                                        float dx2 = x + 0.5f - voidCenter.X;
                                        float dz2 = z + 0.5f - voidCenter.Z;
                                        float distSq = dx2 * dx2 + dz2 * dz2;
                                        if (distSq > voidRadius * voidRadius) continue;
                                        for (int y = vMinY; y <= vMaxY; y++)
                                        {
                                            float dy = y + 0.5f - voidCenter.Y;
                                            if (dx2 * dx2 + dy * dy + dz2 * dz2 > voidRadius * voidRadius) continue;
                                            if (y < 0 || y > 255) continue;
                                            if (chunk.GetCellContentsFast(lx, y, lz) != portalIndex)
                                                chunk.SetCellValueFast(lx, y, lz, 0);
                                        }
                                    }
                                }
                            }
                            if (regular)
                            {
                                Vector3 noise = new Vector3(
                                    SimplexNoise.OctavedNoise(pos.X, pos.Y, pos.Z, 0.05f, 1, 1.5f, 0.5f) - 0.5f,
                                    SimplexNoise.OctavedNoise(pos.X + 100, pos.Y, pos.Z, 0.05f, 1, 1.5f, 0.5f) - 0.5f,
                                    SimplexNoise.OctavedNoise(pos.X, pos.Y, pos.Z + 200, 0.05f, 1, 1.5f, 0.5f) - 0.5f
                                );
                                dir = Vector3.Normalize(dir + noise * 0.3f);
                            }
                            else
                            {
                                dir = Vector3.Normalize(dir + random.Vector3(0.4f) * 0.7f);
                                dir.Y = Math.Clamp(dir.Y, -0.6f, 0.6f);
                            }
                            if (random.Bool(0.005f) && pos.Y > 20f) dir.Y -= random.Float(0.1f, 0.3f);
                            if (random.Bool(0.005f) && pos.Y < 220f) dir.Y += random.Float(0.1f, 0.3f);
                            yield return true;
                        }
                    }
                }
            }
            yield break;
        }

