        public IEnumerator<bool> PalmMultidimensionalWorldBuildingsCoroutine(TerrainChunk chunk)
        {
            SubsystemTerrain subsystemTerrain = m_subsystemTerrain;
            Terrain terrain = subsystemTerrain.Terrain;
            int chunkOriginX = chunk.Origin.X;
            int chunkOriginZ = chunk.Origin.Y;
            foreach (AccessNewMultidimensionalWorldBuildings accessNewMultidimensionalWorldBuildings in AccessNewMultidimensionalWorldBuildingsManager.Data)
            {
                if (WorldName == accessNewMultidimensionalWorldBuildings.WorldName)
                {
                    string buildingsData = ContentManager.Get<string>(accessNewMultidimensionalWorldBuildings.ArchitecturePath).Replace("\r", "");
                    string[] buildingsLines = buildingsData.Split('\n', StringSplitOptions.RemoveEmptyEntries);
                    List<(int x, int y, int z, int id)> buildingBlocks = new List<(int, int, int, int)>();
                    int minX = 0, maxX = 0, minY = 0, maxY = 0, minZ = 0, maxZ = 0;
                    bool first = true;
                    foreach (string line in buildingsLines)
                    {
                        string[] parts = line.Split(',');
                        if (parts.Length >= 4)
                        {
                            int x = int.Parse(parts[0]);
                            int y = int.Parse(parts[1]);
                            int z = int.Parse(parts[2]);
                            int id = CraftingRecipesManager.DecodeResult(parts[3]);
                            buildingBlocks.Add((x, y, z, id));
                            if (first)
                            {
                                minX = maxX = x;
                                minY = maxY = y;
                                minZ = maxZ = z;
                                first = false;
                            }
                            else
                            {
                                if (x < minX) minX = x;
                                if (x > maxX) maxX = x;
                                if (y < minY) minY = y;
                                if (y > maxY) maxY = y;
                                if (z < minZ) minZ = z;
                                if (z > maxZ) maxZ = z;
                            }
                        }
                    }
                    int buildingHeight = maxY - minY + 1;
                    List<(int x, int z)> samplePoints = new List<(int, int)>();
                    for (int xi = 0; xi < 16; xi++)
                    {
                        for (int zi = 0; zi < 16; zi++)
                        {
                            if (m_random.Float() <= accessNewMultidimensionalWorldBuildings.GeneratingProbability)
                                samplePoints.Add((xi, zi));
                        }
                    }
                    samplePoints = samplePoints.OrderBy(p => m_random.Int()).ToList();
                    int groundBlockId = CraftingRecipesManager.DecodeResult(accessNewMultidimensionalWorldBuildings.SquareUnderfoot);
                    foreach (var (sx, sz) in samplePoints)
                    {
                        float randOffsetX = m_random.Float(-0.5f, 0.5f);
                        float randOffsetZ = m_random.Float(-0.5f, 0.5f);
                        float worldX = chunkOriginX + sx + randOffsetX;
                        float worldZ = chunkOriginZ + sz + randOffsetZ;
                        bool tooClose = false;
                        foreach (var (genX, genZ) in s_buildingChunks)
                        {
                            float dx = worldX - (genX + 0.5f);
                            float dz = worldZ - (genZ + 0.5f);
                            if (dx * dx + dz * dz < accessNewMultidimensionalWorldBuildings.SquareOfDistance)
                            {
                                tooClose = true;
                                break;
                            }
                        }
                        if (tooClose) continue;
                        int baseX = (int)Math.Floor(worldX);
                        int baseZ = (int)Math.Floor(worldZ);
                        int localBaseX = baseX - chunkOriginX;
                        int localBaseZ = baseZ - chunkOriginZ;
                        if (localBaseX < 0 || localBaseX >= 16 || localBaseZ < 0 || localBaseZ >= 16) continue;
                        int terrainHeight = 0;
                        bool foundGround = false;
                        for (int y = 0; y < 255; y++)
                        {
                            if (chunk.GetCellValueFast(localBaseX, y, localBaseZ) == groundBlockId && chunk.GetCellValueFast(localBaseX, y + 1, localBaseZ) == 0)
                            {
                                terrainHeight = y;
                                foundGround = true;
                                break;
                            }
                        }
                        if (!foundGround) continue;
                        int buildingBaseY = terrainHeight + 1;
                        int buildingWorldMinX = baseX + minX;
                        int buildingWorldMaxX = baseX + maxX;
                        int buildingWorldMinZ = baseZ + minZ;
                        int buildingWorldMaxZ = baseZ + maxZ;
                        int buildingWorldMinY = buildingBaseY;
                        int buildingWorldMaxY = buildingBaseY + buildingHeight - 1;
                        if (buildingWorldMinX < chunkOriginX || buildingWorldMaxX >= chunkOriginX + 16 ||
                            buildingWorldMinZ < chunkOriginZ || buildingWorldMaxZ >= chunkOriginZ + 16 ||
                            buildingWorldMinY < 0 || buildingWorldMaxY >= 256) continue;
                        // 清除区域（使用局部坐标）
                        for (int x = buildingWorldMinX; x <= buildingWorldMaxX; x++)
                        {
                            int localX = x - chunkOriginX;
                            for (int z = buildingWorldMinZ; z <= buildingWorldMaxZ; z++)
                            {
                                int localZ = z - chunkOriginZ;
                                for (int y = buildingWorldMinY; y <= buildingWorldMaxY; y++)
                                {
                                    chunk.SetCellValueFast(localX, y, localZ, 0);
                                }
                            }
                        }
                        bool validGround = false;
                        for (int dx = -1; dx <= 1 && !validGround; dx++)
                        {
                            for (int dz = -1; dz <= 1 && !validGround; dz++)
                            {
                                int checkX = baseX + dx;
                                int checkZ = baseZ + dz;
                                if (checkX < chunkOriginX || checkX >= chunkOriginX + 16 || checkZ < chunkOriginZ || checkZ >= chunkOriginZ + 16) continue;
                                int localX = checkX - chunkOriginX;
                                int localZ = checkZ - chunkOriginZ;
                                if (chunk.GetCellValueFast(localX, terrainHeight, localZ) == groundBlockId)
                                {
                                    validGround = true;
                                    foreach (var (offsetX, offsetY, offsetZ, blockId) in buildingBlocks)
                                    {
                                        int buildingX = checkX + offsetX;
                                        int buildingY = buildingBaseY + offsetY;
                                        int buildingZ = checkZ + offsetZ;
                                        if (buildingX >= chunkOriginX && buildingX < chunkOriginX + 16 &&
                                            buildingZ >= chunkOriginZ && buildingZ < chunkOriginZ + 16 &&
                                            buildingY >= 0 && buildingY < 256)
                                        {
                                            int localX2 = buildingX - chunkOriginX;
                                            int localZ2 = buildingZ - chunkOriginZ;
                                            chunk.SetCellValueFast(localX2, buildingY, localZ2, blockId);
                                        }
                                    }
                                    s_buildingChunks.Add((checkX, checkZ));
                                    chunk.ModificationCounter++;
                                    chunk.State = TerrainChunkState.InvalidLight;
                                    chunk.ThreadState = TerrainChunkState.InvalidLight;
                                    chunk.WasUpgraded = false;
                                    chunk.DowngradedState = null;
                                    subsystemTerrain.TerrainUpdater.Update();
                                    break;
                                }
                            }
                        }
                        yield return true;
                    }
                }
            }
            yield break;
        }
    }
}
//组件额外属性
namespace Game
{
    public class ComponentExtraAttributes : Component, IUpdateable
    {
        public ComponentHealth componentHealth;
        public ComponentRunAwayBehavior componentRunAwayBehavior;
        public ComponentLevel componentLevel;
        public ComponentPlayer componentPlayer;
        public ComponentChaseBehavior componentChaseBehavior;
        public ComponentTalent componentTalent;
        public ComponentMiner componentMiner;
        public SubsystemNewInteroperableCubeBlockBehavior subsystemNewInteroperableCubeBlockBehavior;

        public float HitRate;
        public float NewHitRate;
        public float CriticalStrikeRate;
        public float NewCriticalStrikeRate;
        public float CriticalStrikeMultiplier;
        public float DodgeRate;
        public float NewDodgeRate;
        public float PoisoningRate;
        public float AttackDistance;
        public float Defense;
        public float NewDefense;
        public float VertigoRate;

        public bool hasPlayerTarget;
        public float m_checkTimer;
        public Project m_project;

        public float AttackResilience;
        public float NewAttackResilience;

        public static readonly HashSet<ComponentChaseBehavior> s_allChaseBehaviors = new HashSet<ComponentChaseBehavior>();

        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public void OnProjectEntityAdded(object sender, EntityAddRemoveEventArgs args)
        {
            if (args.Entity.Project != m_project) return;
            var chase = args.Entity.FindComponent<ComponentChaseBehavior>();
            if (chase != null) s_allChaseBehaviors.Add(chase);
        }

        public void OnProjectEntityRemoved(object sender, EntityAddRemoveEventArgs args)
        {
            if (args.Entity.Project != m_project) return;
            var chase = args.Entity.FindComponent<ComponentChaseBehavior>();
            if (chase != null) s_allChaseBehaviors.Remove(chase);
        }

        public void Update(float dt)
        {
            if (componentPlayer != null)
            {
                HitRate = NewHitRate + componentLevel.OtherFactorsResults["HitRate"] / 100f;
                CriticalStrikeRate = NewCriticalStrikeRate + componentLevel.OtherFactorsResults["CriticalStrikeRate"] / 100f;
                DodgeRate = NewDodgeRate + componentLevel.OtherFactorsResults["DodgeRate"] / 100f;
                Defense = NewDefense + componentLevel.OtherFactorsResults["Defense"];
                for (int a = 0; a < componentTalent.TalentAttributes.Count; a++)
                {
                    if (componentTalent.TalentAttributes[a].UpperLimitOfHealthIncreased > 0 && componentTalent.TalentAttributes[a].Field > 0)
                    {
                        componentHealth.m_attackResilience = NewAttackResilience + componentTalent.TalentAttributes[a].UpperLimitOfHealthIncreased + (componentTalent.TalentAttributes[a].Level - 1) * 50f;
                    }
                    if (componentTalent.TalentAttributes[a].AttackRangeIncreased > 0 && componentTalent.TalentAttributes[a].Field > 0)
                    {
                        componentChaseBehavior.MaxAttackRange = AttackDistance + componentTalent.TalentAttributes[a].AttackRangeIncreased + (componentTalent.TalentAttributes[a].Level - 1) * 0.5f;
                    }
                }
                componentMiner.m_digSpeedBasedOnStrengthFactor = false;
                m_checkTimer += dt;
                if (m_checkTimer >= 1f)
                {
                    m_checkTimer = 0f;
                    bool anyTargetingPlayer = false;
                    foreach (var chase in s_allChaseBehaviors)
                    {
                        if (chase.Target is ComponentPlayer)
                        {
                            anyTargetingPlayer = true;
                            break;
                        }
                    }

                    // 下降沿处理
                    if (!anyTargetingPlayer && hasPlayerTarget)
                    {
                        var dict = componentPlayer.PlayerStats.ValuesDictionaryForMods;
                        dict["NumberOfBattles"] = (dict.ContainsKey("NumberOfBattles") ? (int)dict["NumberOfBattles"] + 1 : 1);
                        subsystemNewInteroperableCubeBlockBehavior.CurrentCapacityAdd(1, 1);
                    }

                    hasPlayerTarget = anyTargetingPlayer;
                }
            }
            else
            {
                componentChaseBehavior.MaxAttackRange = AttackDistance;
            }
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            componentHealth = Entity.FindComponent<ComponentHealth>(throwOnError: true);
            componentRunAwayBehavior = Entity.FindComponent<ComponentRunAwayBehavior>();
            componentLevel = Entity.FindComponent<ComponentLevel>();
            componentPlayer = Entity.FindComponent<ComponentPlayer>();
            componentChaseBehavior = Entity.FindComponent<ComponentChaseBehavior>();
            componentTalent = Entity.FindComponent<ComponentTalent>();
            componentMiner = Entity.FindComponent<ComponentMiner>();
            subsystemNewInteroperableCubeBlockBehavior = Project.FindSubsystem<SubsystemNewInteroperableCubeBlockBehavior>();

            HitRate = valuesDictionary.GetValue<float>("HitRate");
            CriticalStrikeRate = valuesDictionary.GetValue<float>("CriticalStrikeRate");
            CriticalStrikeMultiplier = valuesDictionary.GetValue<float>("CriticalStrikeMultiplier");
            DodgeRate = valuesDictionary.GetValue<float>("DodgeRate");
            PoisoningRate = valuesDictionary.GetValue<float>("PoisoningRate");
            AttackDistance = valuesDictionary.GetValue<float>("AttackDistance");
            Defense = valuesDictionary.GetValue<float>("Defense");
            VertigoRate = valuesDictionary.GetValue<float>("VertigoRate");

            NewHitRate = HitRate;
            NewCriticalStrikeRate = CriticalStrikeRate;
            NewDodgeRate = DodgeRate;
            NewAttackResilience = componentHealth.m_attackResilience;
            NewDefense = Defense;

            m_project = Project;

            componentHealth.m_regenerateLifeEnabled = false;
            if (componentRunAwayBehavior != null)
            {
                componentRunAwayBehavior.LowHealthToEscape = 0f;
            }

            Project.EntityAdded += OnProjectEntityAdded;
            Project.EntityRemoved += OnProjectEntityRemoved;

            foreach (Entity entity in Project.Entities)
            {
                var chase = entity.FindComponent<ComponentChaseBehavior>();
                if (chase != null)
                    s_allChaseBehaviors.Add(chase);
            }

            hasPlayerTarget = false;
            foreach (var chase in s_allChaseBehaviors)
            {
                if (chase.Target is ComponentPlayer)
                {
                    hasPlayerTarget = true;
                    break;
                }
            }
        }

        public override void OnEntityRemoved()
        {
            Project.EntityAdded -= OnProjectEntityAdded;
            Project.EntityRemoved -= OnProjectEntityRemoved;
            base.OnEntityRemoved();
        }
    }
}
