//生成生物
namespace Game
{
    public class SubsystemHYZLCreatureSpawn : SubsystemCreatureSpawn
    {
        public string WorldName;

        public override void InitializeCreatureTypes()
        {
            string worldName = m_subsystemGameInfo?.DirectoryName;

            int index = -1;
            WorldName = "";
            for (int i = 0; i < 3; i++)
            {
                index = worldName.IndexOf('/', index + 1);
                if (index == -1) WorldName = "MainWorld";
            }
            if (WorldName == "")
                WorldName = worldName.Substring(index + 1);
            foreach (AccessNeobiogenesis accessNeobiogenesis in AccessNeobiogenesisManager.Data)
            {
                if (accessNeobiogenesis.Latitude == WorldName)
                {
                    for (int a = 0; a < accessNeobiogenesis.ClassNameOfBoxUnderFoot.Length; a++)
                    {
                        string ClassNameOfBoxUnderFoot = accessNeobiogenesis.ClassNameOfBoxUnderFoot[a];
                        m_creatureTypes.Add(
                            new CreatureType(accessNeobiogenesis.NameOfTheBiologicalEntity, SpawnLocationType.Surface, true, false)
                            {
                                SpawnSuitabilityFunction = delegate (CreatureType _, Point3 point)
                                {
                                    int TheSquareATheFoot = m_subsystemTerrain.Terrain.GetCellValueFast(point.X, point.Y - 1, point.Z);
                                    GameMode gameMode = m_subsystemGameInfo.WorldSettings.GameMode;
                                    double TotalElapsedGameTime = m_subsystemGameInfo.TotalElapsedGameTime;
                                    if (TotalElapsedGameTime > accessNeobiogenesis.TotalElapsedGameTime)
                                    {
                                        if (accessNeobiogenesis.NonGeneratedGameMode1 != null && accessNeobiogenesis.NonGeneratedGameMode2 != null)
                                        {
                                            return (gameMode != accessNeobiogenesis.NonGeneratedGameMode1 && gameMode != accessNeobiogenesis.NonGeneratedGameMode2) && TheSquareATheFoot == CraftingRecipesManager.DecodeResult(ClassNameOfBoxUnderFoot) ? accessNeobiogenesis.GeneratingProbabilityOfSatisfyingTheCondition : accessNeobiogenesis.GeneratingProbabilityOfUnsatisfiedCondition;
                                        }
                                        else
                                        {
                                            return TheSquareATheFoot == CraftingRecipesManager.DecodeResult(ClassNameOfBoxUnderFoot) ? accessNeobiogenesis.GeneratingProbabilityOfSatisfyingTheCondition : accessNeobiogenesis.GeneratingProbabilityOfUnsatisfiedCondition;
                                        }
                                    }
                                    else
                                    {
                                        return 0f;
                                    }
                                },
                                SpawnFunction = (creatureType, point) => SpawnCreatures(creatureType, accessNeobiogenesis.NameOfTheBiologicalEntity, point, accessNeobiogenesis.NumberOfUnitsGenerated).Count
                            }
                        );
                    }
                }
            }
            ModsManager.HookAction(
                "InitializeCreatureTypes",
                modLoader =>
                {
                    modLoader.InitializeCreatureTypes(this, m_creatureTypes);
                    return false;
                }
            );
        }

        public override Entity SpawnCreature(string templateName, Vector3 position, bool constantSpawn)
        {
            try
            {
                Entity entity = DatabaseManager.CreateEntity(Project, templateName, true);
                int cellValue = m_subsystemTerrain.Terrain.GetCellValue((int)position.X, (int)position.Y, (int)position.Z);
                int type = NewBlock.GetType(cellValue);
                if (Terrain.ExtractContents(cellValue) == NewBlock.Index && AccessNewBlockManager.Get(type).ReinforcementCoefficient > 1)
                {
                    entity.FindComponent<ComponentHealth>(true).m_attackResilience *= AccessNewBlockManager.Get(type).ReinforcementCoefficient;
                    entity.FindComponent<ComponentMiner>(true).AttackPower *= AccessNewBlockManager.Get(type).ReinforcementCoefficient;
                }
                entity.FindComponent<ComponentBody>(true).Position = position;
                entity.FindComponent<ComponentBody>(true).Rotation = Quaternion.CreateFromAxisAngle(
                    Vector3.UnitY,
                    m_random.Float(0f, (float)Math.PI * 2f)
                );
                entity.FindComponent<ComponentCreature>(true).ConstantSpawn = constantSpawn;
                Project.AddEntity(entity);
                return entity;
            }
            catch (Exception ex)
            {
                Log.Error($"Unable to spawn creature with template \"{templateName}\". Reason: {ex}");
                return null;
            }
        }
    }
}
