//组件蛇模型动画
namespace Game
{
    public class ComponentSnakeModel : ComponentCreatureModel
    {
        public SubsystemAudio m_subsystemAudio;
        public SubsystemSoundMaterials m_subsystemSoundMaterials;

        // 蛇的骨骼
        public ModelBone m_bodyBone;
        public ModelBone m_body2Bone;
        public ModelBone m_body3Bone;
        public ModelBone m_neckBone;
        public ModelBone m_headBone;
        public ModelBone m_tail1Bone;
        public ModelBone m_tail2Bone;
        public ModelBone m_tail3Bone;

        // 动画参数
        public float m_slitherSpeed;
        public float m_slitherAmplitude;
        public float m_bodyWaveFrequency;
        public float m_tailWaveFrequency;
        public float m_strikeSpeed;
        public float m_strikeDistance;
        public float m_feedHeadBobSpeed;
        public float m_bodyFlexibility;
        public float m_tailFlexibility;

        // 动画状态
        public float m_slitherPhase;
        public float m_bodyWavePhase;
        public float m_tailWavePhase;
        public float m_headAngleY;
        public float m_bodyAngle;
        public float m_body2Angle;
        public float m_body3Angle;
        public float m_tail1Angle;
        public float m_tail2Angle;
        public float m_tail3Angle;
        public float m_neckAngle;
        public float m_strikePhase;
        public float m_strikeFactor;
        public float m_feedPhase;
        public float m_feedFactor;

        public override float AttackPhase
        {
            get => m_strikePhase;
            set => m_strikePhase = value;
        }

        public override float AttackFactor
        {
            get => m_strikeFactor;
            set => m_strikeFactor = value;
        }

        public override void Update(float dt)
        {
            float speed = m_componentCreature.ComponentLocomotion.SlipSpeed
                ?? Vector3.Dot(m_componentCreature.ComponentBody.Velocity, m_componentCreature.ComponentBody.Matrix.Forward);

            // 根据速度更新滑动动画
            if (MathF.Abs(speed) > 0.1f)
            {
                float speedFactor = MathUtils.Clamp(MathF.Abs(speed) / m_componentCreature.ComponentLocomotion.WalkSpeed, 0.1f, 1f);
                m_slitherPhase += speedFactor * m_slitherSpeed * dt;
                m_bodyWavePhase += speedFactor * m_bodyWaveFrequency * dt;
                m_tailWavePhase += speedFactor * m_tailWaveFrequency * dt;

                // 播放滑动声音
                float soundPhase = MathF.Floor(m_slitherPhase * 2f);
                if (m_slitherPhase * 2f > soundPhase && (m_slitherPhase - dt) * 2f <= soundPhase)
                {
                    m_componentCreature.ComponentCreatureSounds.PlayFootstepSound(0.3f);
                }
            }
            else
            {
                // 静止时的轻微摆动
                m_bodyWavePhase += 0.2f * dt;
                m_tailWavePhase += 0.3f * dt;
            }

            // 攻击动画
            IsAttackHitMoment = false;
            if (AttackOrder)
            {
                m_strikeFactor = MathUtils.Min(m_strikeFactor + m_strikeSpeed * dt, 1f);
                float oldPhase = m_strikePhase;
                m_strikePhase = MathUtils.Remainder(m_strikePhase + dt * m_strikeSpeed * 2f, 1f);
                if (oldPhase < 0.3f && m_strikePhase >= 0.3f)
                {
                    IsAttackHitMoment = true;
                }
            }
            else
            {
                m_strikeFactor = MathUtils.Max(m_strikeFactor - m_strikeSpeed * dt, 0f);
                if (m_strikePhase != 0f)
                {
                    if (m_strikePhase > 0.5f)
                    {
                        m_strikePhase = MathUtils.Remainder(MathUtils.Min(m_strikePhase + dt * m_strikeSpeed, 1f), 1f);
                    }
                    else if (m_strikePhase > 0f)
                    {
                        m_strikePhase = MathUtils.Max(m_strikePhase - dt * m_strikeSpeed, 0f);
                    }
                }
            }

            // 喂食动画
            m_feedFactor = FeedOrder ? MathUtils.Min(m_feedFactor + 2f * dt, 1f) : MathUtils.Max(m_feedFactor - 2f * dt, 0f);
            if (m_feedFactor > 0f)
            {
                m_feedPhase += m_feedHeadBobSpeed * dt;
            }

            // 重置指令
            FeedOrder = false;
            AttackOrder = false;
            base.Update(dt);
        }

        public override void AnimateCreature()
        {
            Vector3 position = m_componentCreature.ComponentBody.Position;
            Vector3 rotation = m_componentCreature.ComponentBody.Rotation.ToYawPitchRoll();

            if (m_componentCreature.ComponentHealth.Health > 0f)
            {
                AnimateLivingSnake(position, rotation);
            }
            else
            {
                AnimateDeadSnake(position, rotation);
            }
        }

        public void AnimateLivingSnake(Vector3 position, Vector3 rotation)
        {
            float speed = Vector3.Dot(m_componentCreature.ComponentBody.Velocity, m_componentCreature.ComponentBody.Matrix.Forward);
            bool isMoving = MathF.Abs(speed) > 0.1f;

            // 身体波浪运动
            float baseAmplitude = isMoving ? m_slitherAmplitude : m_slitherAmplitude * 0.3f;

            m_bodyAngle = baseAmplitude * MathF.Sin(m_bodyWavePhase);
            m_body2Angle = baseAmplitude * MathF.Sin(m_bodyWavePhase + 1f) * m_bodyFlexibility;
            m_body3Angle = baseAmplitude * MathF.Sin(m_bodyWavePhase + 2f) * m_bodyFlexibility;
            m_tail1Angle = baseAmplitude * MathF.Sin(m_tailWavePhase) * m_tailFlexibility;
            m_tail2Angle = baseAmplitude * MathF.Sin(m_tailWavePhase + 0.7f) * m_tailFlexibility;
            m_tail3Angle = baseAmplitude * MathF.Sin(m_tailWavePhase + 1.4f) * m_tailFlexibility;

            // 头部和颈部运动
            Vector2 lookAngles = m_componentCreature.ComponentLocomotion.LookAngles;
            lookAngles.X = Math.Clamp(lookAngles.X, -MathUtils.DegToRad(60f), MathUtils.DegToRad(60f));
            lookAngles.Y = Math.Clamp(lookAngles.Y, -MathUtils.DegToRad(45f), MathUtils.DegToRad(45f));

            // 颈部承担部分头部转动
            Vector2 neckAngles = Vector2.Zero;
            Vector2 headAngles = lookAngles;
            if (m_neckBone != null)
            {
                neckAngles = 0.6f * lookAngles;
                headAngles = 0.4f * lookAngles;
            }

            // 攻击动画 - 头部前冲
            if (m_strikeFactor > 0f)
            {
                float strikeOffset = m_strikeDistance * MathF.Sin((float)Math.PI * m_strikePhase);
                Vector3 strikeTranslation = m_componentCreature.ComponentBody.Matrix.Forward * strikeOffset * m_strikeFactor;
                position += strikeTranslation;

                // 攻击时的头部角度
                float strikeHeadAngle = -MathUtils.DegToRad(20f) * MathF.Sin((float)Math.PI * 2f * m_strikePhase);
                headAngles.Y = MathUtils.Lerp(headAngles.Y, strikeHeadAngle, m_strikeFactor);
            }

            // 喂食动画 - 头部上下摆动
            if (m_feedFactor > 0f)
            {
                float feedHeadBob = MathUtils.DegToRad(15f) * MathF.Sin((float)Math.PI * 2f * m_feedPhase);
                headAngles.Y = MathUtils.Lerp(headAngles.Y, feedHeadBob, m_feedFactor);
            }

            // 应用平滑过渡
            float smoothFactor = MathUtils.Min(12f * m_subsystemTime.GameTimeDelta, 1f);
            m_headAngleY += smoothFactor * (headAngles.Y - m_headAngleY);
            m_neckAngle += smoothFactor * (neckAngles.Y - m_neckAngle);

            // 设置骨骼变换
            SetBoneTransform(
                m_bodyBone.Index,
                Matrix.CreateRotationY(rotation.X) *
                Matrix.CreateRotationZ(m_bodyAngle) *
                Matrix.CreateTranslation(position)
            );

            if (m_body2Bone != null)
            {
                SetBoneTransform(m_body2Bone.Index, Matrix.CreateRotationZ(m_body2Angle));
            }
            if (m_body3Bone != null)
            {
                SetBoneTransform(m_body3Bone.Index, Matrix.CreateRotationZ(m_body3Angle));
            }
            if (m_neckBone != null)
            {
                SetBoneTransform(m_neckBone.Index, Matrix.CreateRotationZ(m_neckAngle));
            }

            SetBoneTransform(
                m_headBone.Index,
                Matrix.CreateRotationX(m_headAngleY) *
                Matrix.CreateRotationZ(0f - headAngles.X)
            );

            if (m_tail1Bone != null)
            {
                SetBoneTransform(m_tail1Bone.Index, Matrix.CreateRotationZ(m_tail1Angle));
            }
            if (m_tail2Bone != null)
            {
                SetBoneTransform(m_tail2Bone.Index, Matrix.CreateRotationZ(m_tail2Angle));
            }
            if (m_tail3Bone != null)
            {
                SetBoneTransform(m_tail3Bone.Index, Matrix.CreateRotationZ(m_tail3Angle));
            }
        }

        public void AnimateDeadSnake(Vector3 position, Vector3 rotation)
        {
            float deathFactor = 1f - DeathPhase;
            float sideFactor = Vector3.Dot(m_componentFrame.Matrix.Right, DeathCauseOffset) > 0f ? 1f : -1f;
            float height = m_componentCreature.ComponentBody.BoundingBox.Max.Y - m_componentCreature.ComponentBody.BoundingBox.Min.Y;

            SetBoneTransform(
                m_bodyBone.Index,
                Matrix.CreateTranslation(-0.3f * height * Vector3.UnitY * DeathPhase) *
                Matrix.CreateFromYawPitchRoll(rotation.X, 0f, (float)Math.PI / 2f * DeathPhase * sideFactor) *
                Matrix.CreateTranslation(0.1f * height * Vector3.UnitY * DeathPhase) *
                Matrix.CreateTranslation(position)
            );

            if (m_body2Bone != null)
            {
                SetBoneTransform(m_body2Bone.Index, Matrix.CreateRotationZ(m_body2Angle * deathFactor));
            }
            if (m_body3Bone != null)
            {
                SetBoneTransform(m_body3Bone.Index, Matrix.CreateRotationZ(m_body3Angle * deathFactor));
            }
            if (m_neckBone != null)
            {
                SetBoneTransform(m_neckBone.Index, Matrix.Identity);
            }
            SetBoneTransform(m_headBone.Index, Matrix.CreateRotationX(MathUtils.DegToRad(30f) * DeathPhase));
            if (m_tail1Bone != null)
            {
                SetBoneTransform(m_tail1Bone.Index, Matrix.CreateRotationZ(m_tail1Angle * deathFactor));
            }
            if (m_tail2Bone != null)
            {
                SetBoneTransform(m_tail2Bone.Index, Matrix.CreateRotationZ(m_tail2Angle * deathFactor));
            }
            if (m_tail3Bone != null)
            {
                SetBoneTransform(m_tail3Bone.Index, Matrix.CreateRotationZ(m_tail3Angle * deathFactor));
            }
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            m_subsystemAudio = Project.FindSubsystem<SubsystemAudio>(true);
            m_subsystemSoundMaterials = Project.FindSubsystem<SubsystemSoundMaterials>(true);

            m_slitherSpeed = valuesDictionary.GetValue<float>("SlitherSpeed");
            m_slitherAmplitude = valuesDictionary.GetValue<float>("SlitherAmplitude");
            m_bodyWaveFrequency = valuesDictionary.GetValue<float>("BodyWaveFrequency");
            m_tailWaveFrequency = valuesDictionary.GetValue<float>("TailWaveFrequency");
            m_strikeSpeed = valuesDictionary.GetValue<float>("StrikeSpeed");
            m_strikeDistance = valuesDictionary.GetValue<float>("StrikeDistance");
            m_feedHeadBobSpeed = valuesDictionary.GetValue<float>("FeedHeadBobSpeed");
            m_bodyFlexibility = valuesDictionary.GetValue<float>("BodyFlexibility");
            m_tailFlexibility = valuesDictionary.GetValue<float>("TailFlexibility");
        }

        public override void SetModel(Model model)
        {
            base.SetModel(model);
            if (IsSet) return;

            if (Model != null)
            {
                m_bodyBone = Model.FindBone("Body");
                m_body2Bone = Model.FindBone("Body2", false);
                m_body3Bone = Model.FindBone("Body3", false);
                m_neckBone = Model.FindBone("Neck", false);
                m_headBone = Model.FindBone("Head");
                m_tail1Bone = Model.FindBone("Tail1", false);
                m_tail2Bone = Model.FindBone("Tail2", false);
                m_tail3Bone = Model.FindBone("Tail3", false);
            }
            else
            {
                m_bodyBone = null;
                m_body2Bone = null;
                m_body3Bone = null;
                m_neckBone = null;
                m_headBone = null;
                m_tail1Bone = null;
                m_tail2Bone = null;
                m_tail3Bone = null;
            }
        }
    }
}
//组件生命体征
namespace Game
{
    public class ComponentHYZLVitalStats : ComponentVitalStats
    {
        public ComponentPhysicalAttributes componentPhysicalAttributes;
        public ComponentTalent componentTalent;
        public ComponentLevel componentLevel;
        public ComponentBuff componentBuff;
        public SubsystemTerrain subsystemTerrain;

        public override bool Eat(int value)
        {
            int num = Terrain.ExtractContents(value);
            Block obj = BlocksManager.Blocks[num];
            float num2 = obj.GetNutritionalValue(value);
            float sicknessProbability = obj.GetSicknessProbability(value);
            if (num2 > 0f)
            {
                if (m_componentPlayer.ComponentSickness.IsSick
                    && sicknessProbability > 0f)
                {
                    m_componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 1), Color.White, true, true);
                    return false;
                }
                if (Food >= 0.98f)
                {
                    m_componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 2), Color.White, true, true);
                    return false;
                }
                m_subsystemAudio.PlayRandomSound(
                    "Audio/Creatures/HumanEat",
                    1f,
                    m_random.Float(-0.2f, 0.2f),
                    m_componentPlayer.ComponentBody.Position,
                    2f,
                    0f
                );
                for (int a = 0; a < componentTalent.TalentAttributes.Count; a++)
                {
                    if (componentTalent.TalentAttributes[a].ImprovedEffectOfFoodRecovery > 0 && componentTalent.TalentAttributes[a].Field > 0)
                    {
                        num2 *= 1 + componentTalent.TalentAttributes[a].ImprovedEffectOfFoodRecovery + (componentTalent.TalentAttributes[a].Level - 1) * 0.05f;
                    }
                }
                Food += num2 / (componentPhysicalAttributes.FoodResistance / 100f);
                FoodEaten?.Invoke(value);
                m_satiationList.Clear();
                m_satiationList.AddRange(m_satiation);
                m_satiation.Clear();
                if (m_componentPlayer.ComponentSickness.IsSick)
                {
                    m_componentPlayer.ComponentSickness.NauseaEffect();
                }
                else if (sicknessProbability >= 0.5f)
                {
                    m_componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 3), Color.White, true, true);
                }
                else if (sicknessProbability > 0f)
                {
                    m_componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 4), Color.White, true, true);
                }
                else if (Food > 0.85f)
                {
                    m_componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 7), Color.White, true, true);
                }
                else
                {
                    m_componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 8), Color.White, true, false);
                }
                m_componentPlayer.PlayerStats.FoodItemsEaten++;
                return true;
            }
            return false;
        }

        public override void UpdateFood()
        {
            float gameTimeDelta = m_subsystemTime.GameTimeDelta;
            float num = m_componentPlayer.ComponentLocomotion.LastWalkOrder?.Length() ?? 0f;
            float lastJumpOrder = m_componentPlayer.ComponentLocomotion.LastJumpOrder;
            float num2 = m_componentPlayer.ComponentCreatureModel.EyePosition.Y - m_componentPlayer.ComponentBody.Position.Y;
            bool flag = m_componentPlayer.ComponentBody.ImmersionDepth > num2;
            bool flag2 = m_componentPlayer.ComponentBody.ImmersionFactor > 0.33f && !m_componentPlayer.ComponentBody.StandingOnValue.HasValue;
            bool flag3 = m_subsystemTime.PeriodicGameTimeEvent(240.0, 13.0) && !m_componentPlayer.ComponentSickness.IsSick;
            if (m_subsystemGameInfo.WorldSettings.GameMode != 0
                && m_subsystemGameInfo.WorldSettings.AreAdventureSurvivalMechanicsEnabled)
            {
                float hungerFactor = m_componentPlayer.ComponentLevel.HungerFactor;
                Food -= hungerFactor * gameTimeDelta / 1392f / (componentPhysicalAttributes.FoodResistance / 100f);
                if (flag2 | flag)
                {
                    Food -= hungerFactor * gameTimeDelta * num / 1392f / (componentPhysicalAttributes.FoodResistance / 100f);
                }
                else
                {
                    Food -= hungerFactor * gameTimeDelta * num / 2784f / (componentPhysicalAttributes.FoodResistance / 100f);
                }
                Food -= hungerFactor * lastJumpOrder / 1160f / (componentPhysicalAttributes.FoodResistance / 100f);
                if (m_componentPlayer.ComponentMiner.DigCellFace.HasValue)
                {
                    Food -= hungerFactor * gameTimeDelta / 2784f / (componentPhysicalAttributes.FoodResistance / 100f);
                }
                if (!m_componentPlayer.ComponentSleep.IsSleeping)
                {
                    if (Food <= 0f)
                    {
                        if (m_subsystemTime.PeriodicGameTimeEvent(50.0, 0.0))
                        {
                            m_componentPlayer.ComponentHealth.Injure(0.05f, null, false, LanguageControl.Get(fName, 9));
                            m_componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 10), Color.White, true, false);
                            m_componentPlayer.ComponentGui.FoodBarWidget.Flash(10);
                        }
                        if (m_subsystemTime.PeriodicGameTimeEvent(1.0, 0.0))
                        {
                            float num3 = 1;
                            for (int a = 0; a < componentTalent.TalentAttributes.Count; a++)
                            {
                                if (componentTalent.TalentAttributes[a].InternalAndExternalInjuriesReduceTheSpeed > 0 && componentTalent.TalentAttributes[a].Field > 0)
                                {
                                    num3 -= componentTalent.TalentAttributes[a].InternalAndExternalInjuriesReduceTheSpeed + (componentTalent.TalentAttributes[a].Level - 1) * 0.05f;
                                }
                            }
                            componentPhysicalAttributes.InternalInjuries -= 1 / componentPhysicalAttributes.InternalInjuriesResistance * num3;
                        }
                    }
                    else if (Food < 0.1f
                        && (m_lastFood >= 0.1f) | flag3)
                    {
                        m_componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 11), Color.White, true, true);
                    }
                    else if (Food < 0.25f
                        && (m_lastFood >= 0.25f) | flag3)
                    {
                        m_componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 12), Color.White, true, true);
                    }
                    else if (Food < 0.5f
                        && (m_lastFood >= 0.5f) | flag3)
                    {
                        m_componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 13), Color.White, true, false);
                    }
                }
            }
            else
            {
                Food = 0.9f;
            }
            if (m_subsystemTime.PeriodicGameTimeEvent(1.0, -0.01))
            {
                m_satiationList.Clear();
                m_satiationList.AddRange(m_satiation);
                m_satiation.Clear();
                foreach (KeyValuePair<int, float> satiation in m_satiationList)
                {
                    float num3 = MathF.Max(satiation.Value - 0.000416666677f, 0f);
                    if (num3 > 0f)
                    {
                        m_satiation.Add(satiation.Key, num3);
                    }
                }
            }
            m_lastFood = Food;
            m_componentPlayer.ComponentGui.FoodBarWidget.Value = Food;
        }

        public override void UpdateSleep()
        {
            float gameTimeDelta = m_subsystemTime.GameTimeDelta;
            bool flag = m_componentPlayer.ComponentBody.ImmersionFactor > 0.05f;
            bool flag2 = m_subsystemTime.PeriodicGameTimeEvent(240.0, 9.0);
            if (m_subsystemGameInfo.WorldSettings.GameMode != 0
                && m_subsystemGameInfo.WorldSettings.AreAdventureSurvivalMechanicsEnabled)
            {
                if (m_componentPlayer.ComponentSleep.SleepFactor == 1f)
                {
                    Sleep += 0.00196f * gameTimeDelta / (componentPhysicalAttributes.SleepResistance / 100f) * (componentPhysicalAttributes.Insomnia * componentPhysicalAttributes.InsomniaResistance / 100f);
                }
                else if (!flag
                    && (!m_lastAttackedTime.HasValue || m_subsystemTime.GameTime - m_lastAttackedTime > 10.0) && !componentPhysicalAttributes.Sleep)
                {
                    Sleep -= gameTimeDelta / 510f / (componentPhysicalAttributes.SleepResistance / 100f);
                }
            }
            else
            {
                Sleep = 0.9f;
            }
            m_lastSleep = Sleep;
            m_sleepBlackoutDuration -= gameTimeDelta;
            float num2 = MathUtils.Saturate(0.5f * m_sleepBlackoutDuration);
            m_sleepBlackoutFactor = MathUtils.Saturate(m_sleepBlackoutFactor + 2f * gameTimeDelta * (num2 - m_sleepBlackoutFactor));
            if (!m_componentPlayer.ComponentSleep.IsSleeping)
            {
                m_componentPlayer.ComponentScreenOverlays.BlackoutFactor = MathF.Max(
                    m_sleepBlackoutFactor,
                    m_componentPlayer.ComponentScreenOverlays.BlackoutFactor
                );
                if (m_sleepBlackoutFactor > 0.01)
                {
                    m_componentPlayer.ComponentScreenOverlays.FloatingMessage = LanguageControl.Get(fName, 24);
                    m_componentPlayer.ComponentScreenOverlays.FloatingMessageFactor = MathUtils.Saturate(10f * (m_sleepBlackoutFactor - 0.9f));
                }
            }
        }

        public override void UpdateTemperature()
        {
            float gameTimeDelta = m_subsystemTime.GameTimeDelta;
            bool flag = m_subsystemTime.PeriodicGameTimeEvent(300.0, 17.0);
            float num = m_componentPlayer.ComponentClothing.Insulation * MathUtils.Lerp(1f, 0.05f, MathUtils.Saturate(4f * Wetness));
            if (m_subsystemGameInfo.WorldSettings.GameMode <= GameMode.Survival)
            {
                num = num * 1.5f + 1f;
            }
            string arg;
            ClothingSlot leastInsulatedSlot = m_componentPlayer.ComponentClothing.LeastInsulatedSlot;
            arg = leastInsulatedSlot.MessageWhenLeastInsulated;
            if (m_subsystemTime.PeriodicGameTimeEvent(1.0, 1.0 * (GetHashCode() % 1000 / 1000.0)))
            {
                int x = Terrain.ToCell(m_componentPlayer.ComponentBody.Position.X);
                int y = Terrain.ToCell(m_componentPlayer.ComponentBody.Position.Y + 0.1f);
                int z = Terrain.ToCell(m_componentPlayer.ComponentBody.Position.Z);
                m_subsystemMetersBlockBehavior.CalculateTemperature(
                    x,
                    y,
                    z,
                    12f,
                    num,
                    out m_targetTemperature,
                    out m_targetTemperatureFlux,
                    out m_environmentTemperature
                );
            }
            if (m_subsystemGameInfo.WorldSettings.GameMode != 0
                && m_subsystemGameInfo.WorldSettings.AreAdventureSurvivalMechanicsEnabled)
            {
                if (componentLevel.OtherFactorsResults["Temperature"] > 1)
                {
                    if (Temperature < componentLevel.OtherFactorsResults["Temperature"])
                    {
                        m_targetTemperature = componentLevel.OtherFactorsResults["Temperature"];
                    }
                }
                foreach (var key in componentBuff.ThreePillBuff.ToList())
                {
                    if (key.Value.Item3 > 0)
                    {
                        m_targetTemperature = 17;
                    }
                }
                float num2 = m_targetTemperature - Temperature;
                Temperature += MathUtils.Saturate(m_targetTemperatureFlux * gameTimeDelta) * num2;
            }
            else
            {
                Temperature = 12f;
            }
            float num4 = 0;
            for (int a = 0; a < componentTalent.TalentAttributes.Count; a++)
            {
                if (componentTalent.TalentAttributes[a].ImprovementOfLowTemperatureResistance > 0 && componentTalent.TalentAttributes[a].Field > 0)
                {
                    num4 += componentTalent.TalentAttributes[a].ImprovementOfLowTemperatureResistance + (componentTalent.TalentAttributes[a].Level - 1) * 7.5f;
                }
            }
            if (Temperature <= 0f)
            {
                m_componentPlayer.ComponentHealth.Injure(1f / (componentPhysicalAttributes.LowTemperatureResistance + num4), null, false, LanguageControl.Get(fName, 25));
            }
            else if (Temperature < 3f)
            {
                if (m_subsystemTime.PeriodicGameTimeEvent(10.0, 0.0))
                {
                    m_componentPlayer.ComponentHealth.Injure(0.05f / (componentPhysicalAttributes.LowTemperatureResistance + num4), null, false, LanguageControl.Get(fName, 26));
                    string text = Wetness > 0f ? string.Format(LanguageControl.Get(fName, 27), arg) :
                        !(num < 1f) ? string.Format(LanguageControl.Get(fName, 28), arg) : string.Format(LanguageControl.Get(fName, 29), arg);
                    m_componentPlayer.ComponentGui.DisplaySmallMessage(text, Color.White, true, false);
                    m_componentPlayer.ComponentGui.TemperatureBarWidget.Flash(10);
                }
            }
            else if (Temperature < 6f
                && (m_lastTemperature >= 6f) | flag)
            {
                string text2 = Wetness > 0f ? string.Format(LanguageControl.Get(fName, 30), arg) :
                    !(num < 1f) ? string.Format(LanguageControl.Get(fName, 31), arg) : string.Format(LanguageControl.Get(fName, 32), arg);
                m_componentPlayer.ComponentGui.DisplaySmallMessage(text2, Color.White, true, true);
                m_componentPlayer.ComponentGui.TemperatureBarWidget.Flash(10);
            }
            else if (Temperature < 8f
                && (m_lastTemperature >= 8f) | flag)
            {
                m_componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 33), Color.White, false, false);
                m_componentPlayer.ComponentGui.TemperatureBarWidget.Flash(10);
            }
            if (Temperature >= 24f)
            {
                if (m_subsystemTime.PeriodicGameTimeEvent(10.0, 0.0))
                {
                    float num5 = 0;
                    for (int a = 0; a < componentTalent.TalentAttributes.Count; a++)
                    {
                        if (componentTalent.TalentAttributes[a].ImprovementOfResistanceToHighTemperature > 0 && componentTalent.TalentAttributes[a].Field > 0)
                        {
                            num5 += componentTalent.TalentAttributes[a].ImprovementOfResistanceToHighTemperature + (componentTalent.TalentAttributes[a].Level - 1) * 7.5f;
                        }
                    }
                    m_componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 34), Color.White, true, false);
                    m_componentPlayer.ComponentHealth.Injure(0.05f / (componentPhysicalAttributes.HighTemperatureResistance + num5), null, false, LanguageControl.Get(fName, 35));
                    m_componentPlayer.ComponentGui.TemperatureBarWidget.Flash(10);
                }
                if (m_subsystemTime.PeriodicGameTimeEvent(8.0, 0.0))
                {
                    m_temperatureBlackoutDuration = MathF.Max(m_temperatureBlackoutDuration, 6f);
                    m_componentPlayer.ComponentCreatureSounds.PlayMoanSound();
                }
            }
            else if (Temperature > 20f
                && m_subsystemTime.PeriodicGameTimeEvent(10.0, 0.0))
            {
                m_componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 36), Color.White, true, false);
                m_temperatureBlackoutDuration = MathF.Max(m_temperatureBlackoutDuration, 3f);
                m_componentPlayer.ComponentGui.TemperatureBarWidget.Flash(10);
                m_componentPlayer.ComponentCreatureSounds.PlayMoanSound();
            }
            m_lastTemperature = Temperature;
            m_componentPlayer.ComponentScreenOverlays.IceFactor = MathUtils.Saturate(1f - Temperature / 6f);
            m_temperatureBlackoutDuration -= gameTimeDelta;
            float num3 = MathUtils.Saturate(0.5f * m_temperatureBlackoutDuration);
            m_temperatureBlackoutFactor = MathUtils.Saturate(m_temperatureBlackoutFactor + 2f * gameTimeDelta * (num3 - m_temperatureBlackoutFactor));
            m_componentPlayer.ComponentScreenOverlays.BlackoutFactor = MathF.Max(
                m_temperatureBlackoutFactor,
                m_componentPlayer.ComponentScreenOverlays.BlackoutFactor
            );
            if (m_temperatureBlackoutFactor > 0.01)
            {
                m_componentPlayer.ComponentScreenOverlays.FloatingMessage = LanguageControl.Get(fName, 37);
                m_componentPlayer.ComponentScreenOverlays.FloatingMessageFactor = MathUtils.Saturate(10f * (m_temperatureBlackoutFactor - 0.9f));
            }
            if (m_targetTemperature > 22f)
            {
                m_componentPlayer.ComponentGui.TemperatureBarWidget.BarSubtexture = ContentManager.Get<Subtexture>("Textures/Atlas/Temperature6");
            }
            else if (m_targetTemperature > 18f)
            {
                m_componentPlayer.ComponentGui.TemperatureBarWidget.BarSubtexture = ContentManager.Get<Subtexture>("Textures/Atlas/Temperature5");
            }
            else if (m_targetTemperature > 14f)
            {
                m_componentPlayer.ComponentGui.TemperatureBarWidget.BarSubtexture = ContentManager.Get<Subtexture>("Textures/Atlas/Temperature4");
            }
            else if (m_targetTemperature > 10f)
            {
                m_componentPlayer.ComponentGui.TemperatureBarWidget.BarSubtexture = ContentManager.Get<Subtexture>("Textures/Atlas/Temperature3");
            }
            else if (m_targetTemperature > 6f)
            {
                m_componentPlayer.ComponentGui.TemperatureBarWidget.BarSubtexture = ContentManager.Get<Subtexture>("Textures/Atlas/Temperature2");
            }
            else
            {
                m_componentPlayer.ComponentGui.TemperatureBarWidget.BarSubtexture = m_targetTemperature > 2f
                    ? ContentManager.Get<Subtexture>("Textures/Atlas/Temperature1")
                    : ContentManager.Get<Subtexture>("Textures/Atlas/Temperature0");
            }
        }

        public virtual void UpdateTerrain()
        {
            int block = subsystemTerrain.Terrain.GetCellValueFast((int)m_componentPlayer.ComponentBody.Position.X, (int)m_componentPlayer.ComponentBody.Position.Y - 1, (int)m_componentPlayer.ComponentBody.Position.Z);
            string blockName = BlocksManager.Blocks[Terrain.ExtractContents(block)].GetDisplayName(null, block);
            int index = blockName.IndexOf("之");
            string left = index >= 0 ? blockName.Substring(0, index) : blockName;
            if (PermanentlySavedAttributesManager.Stepping.ContainsKey(left))
            {
                PermanentlySavedAttributesManager.Stepping[left] = true;
            }
        }

        public override void Update(float dt)
        {
            if (m_componentPlayer.ComponentHealth.Health > 0f)
            {
                UpdateFood();
                UpdateStamina();
                UpdateSleep();
                UpdateTemperature();
                UpdateWetness();
                UpdateTerrain();
            }
            else
            {
                m_pantingSound.Stop();
            }
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            componentPhysicalAttributes = Entity.FindComponent<ComponentPhysicalAttributes>();
            componentTalent = Entity.FindComponent<ComponentTalent>();
            componentLevel = Entity.FindComponent<ComponentLevel>();
            componentBuff = Entity.FindComponent<ComponentBuff>();
            subsystemTerrain = Project.FindSubsystem<SubsystemTerrain>();
        }
    }
