        public void InsertWidget(Widget targetWidget, Widget addWidget, int order)
        {
            //限制变量在0和1
            int num = (order < 0) ? 0 : (order > 1) ? 1 : order;
            //获取目标控件的容器
            ContainerWidget container = targetWidget.ParentWidget;
            //获取目标控件在容器里的索引
            int widgetIndex = container.Children.IndexOf(targetWidget);
            container.Children.Insert(widgetIndex + num, addWidget);
        }

        public void ReplaceWidget(Widget targetWidget, Widget replaceWidget)
        {
            //获取目标控件的容器
            ContainerWidget container = targetWidget.ParentWidget;
            //获取目标控件容器WidgetList
            WidgetsList children = container.Children;
            //获取目标控件在容器里的索引
            int widgetIndex = children.IndexOf(targetWidget);
            //隐藏目标控件
            //这里用隐藏代替删除是防止原版代码找不到原版控件出现报错
            targetWidget.IsVisible = false;
            children.Insert(widgetIndex, replaceWidget);
        }

        public void OnProjectEntityAdded(object sender, EntityAddRemoveEventArgs args)
        {
            if (args.Entity.Project != m_project) return;
            var chase = args.Entity.FindComponent<ComponentChaseBehavior>();
            if (chase != null) s_allChaseBehaviors.Add(chase);
        }

        public void OnProjectEntityRemoved(object sender, EntityAddRemoveEventArgs args)
        {
            if (args.Entity.Project != m_project) return;
            var chase = args.Entity.FindComponent<ComponentChaseBehavior>();
            if (chase != null) s_allChaseBehaviors.Remove(chase);
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            componentPlayer = Entity.FindComponent<ComponentPlayer>(throwOnError: true);
            componentGui = Entity.FindComponent<ComponentGui>(throwOnError: true);
            componentVitalStats = Entity.FindComponent<ComponentVitalStats>(throwOnError: true);
            componentSkills = Entity.FindComponent<ComponentSkills>(throwOnError: true);
            componentTalent = Entity.FindComponent<ComponentTalent>(throwOnError: true);
            componentInventory = Entity.FindComponent<ComponentInventory>(throwOnError: true);
            componentBody = Entity.FindComponent<ComponentBody>(throwOnError: true);
            subsystemGameInfo = Project.FindSubsystem<SubsystemGameInfo>();
            subsystemTerrain = Project.FindSubsystem<SubsystemTerrain>();

            ContainerWidget guiWidget = componentPlayer.GuiWidget;
            GameWidget gameWidget = componentPlayer.GameWidget;

            controlsContainer = guiWidget.Children.Find<CanvasWidget>("ControlsContainer");
            leftContainer = guiWidget.Children.Find<StackPanelWidget>("LeftControlsContainer");
            lightContainer = guiWidget.Children.Find<StackPanelWidget>("RightControlsContainer");
            moreContents = guiWidget.Children.Find<StackPanelWidget>("MoreContents");
            statusContents = (StackPanelWidget)guiWidget.Children.Find<ValueBarWidget>("HealthBar").ParentWidget;

            try
            {
                TraumaBar = gameWidget.Children.Find<ValueBarWidget>("TraumaBar");
                InternalInjuriesBar = gameWidget.Children.Find<ValueBarWidget>("InternalInjuriesBar");
                SpiritBar = gameWidget.Children.Find<ValueBarWidget>("SpiritBar");
                InsomniaBar = gameWidget.Children.Find<ValueBarWidget>("InsomniaBar");
                PlayerStatsButton = gameWidget.Children.Find<BitmapButtonWidget>("PlayerStatsButton");
                HandGrid = gameWidget.Children.Find<GridPanelWidget>("HandGrid");
                TalentButton = gameWidget.Children.Find<BitmapButtonWidget>("TalentButton");
                TransactionButton = gameWidget.Children.Find<BitmapButtonWidget>("TransactionButton");
                FishingButton = gameWidget.Children.Find<BitmapButtonWidget>("FishingButton");
                FishingRoundRange = gameWidget.Children.Find<RoundProgressWidget>("FishingRoundRange");
                FishingCaptureBar = gameWidget.Children.Find<RoundProgressWidget>("FishingCaptureBar");
                FishBaitGrid = gameWidget.Children.Find<ShortInventoryWidget>("FishBaitGrid");
                SkillsButton = gameWidget.Children.Find<BitmapButtonWidget>("SkillsButton");
                TrapButton = gameWidget.Children.Find<BitmapButtonWidget>("TrapButton");
                TrapContentsWidget = gameWidget.Children.Find<StackPanelWidget>("TrapContentsWidget");
                TrapList = gameWidget.Children.Find<ListPanelWidget>("TrapList");
                FarTrapContentsWidget = gameWidget.Children.Find<StackPanelWidget>("FarTrapContentsWidget");
                MailboxButton = gameWidget.Children.Find<BitmapButtonWidget>("MailboxButton");
                EventCenterButton = gameWidget.Children.Find<BitmapButtonWidget>("EventCenterButton");
                AdvertisingLotteryButton = gameWidget.Children.Find<BitmapButtonWidget>("AdvertisingLotteryButton");
            }
            catch
            {
                InsertWidget(gameWidget.Children.Find("HealthBar"), TraumaBar, 0);
                InsertWidget(gameWidget.Children.Find("HealthBar"), InternalInjuriesBar, 0);
                ReplaceWidget(gameWidget.Children.Find("TemperatureBar"), SpiritBar);
                InsertWidget(gameWidget.Children.Find("FoodBar"), InsomniaBar, 1);
                leftContainer.AddChildren(PlayerStatsButton);
                leftContainer.AddChildren(TalentButton);
                leftContainer.AddChildren(HandGrid);
                lightContainer.AddChildren(TransactionButton);
                lightContainer.AddChildren(FishingButton);
                lightContainer.AddChildren(FishBaitGrid);
                lightContainer.AddChildren(SkillsButton);
                lightContainer.AddChildren(FarTrapContentsWidget);
                FarTrapContentsWidget.AddChildren(TrapContentsWidget);
                TrapContentsWidget.AddChildren(TrapList);
                FarTrapContentsWidget.AddChildren(TrapButton);
                moreContents.AddChildren(AdvertisingLotteryButton);
                moreContents.AddChildren(EventCenterButton);
                moreContents.AddChildren(MailboxButton);
                gameWidget.AddChildren(FishingRoundRange);
                gameWidget.AddChildren(FishingCaptureBar);
                int num = 0;
                for (int a = 0; a < HandGrid.RowsCount; a++)
                {
                    for (int b = 0; b < HandGrid.ColumnsCount; b++)
                    {
                        var inventorySlotWidget = new InventorySlotWidget();
                        inventorySlotWidget.Size = new Vector2(64f, 64f);
                        inventorySlotWidget.AssignInventorySlot(componentPlayer.Entity.FindComponent<ComponentHand>(throwOnError: true), num++);
                        HandGrid.Children.Add(inventorySlotWidget);
                        HandGrid.SetWidgetCell(inventorySlotWidget, new Point2(b, a));
                    }
                }
            }

            m_project = Project;

            Project.EntityAdded += OnProjectEntityAdded;
            Project.EntityRemoved += OnProjectEntityRemoved;

            foreach (Entity entity in Project.Entities)
            {
                var chase = entity.FindComponent<ComponentChaseBehavior>();
                if (chase != null)
                    s_allChaseBehaviors.Add(chase);
            }

            hasPlayerTarget = false;
            foreach (var chase in s_allChaseBehaviors)
            {
                if (chase.Target is ComponentPlayer)
                {
                    hasPlayerTarget = true;
                    break;
                }
            }

            gameMode = subsystemGameInfo.WorldSettings.GameMode;
            TraumaBar.IsVisible = gameMode != GameMode.Creative;
            InternalInjuriesBar.IsVisible = gameMode != GameMode.Creative;
            SpiritBar.IsVisible = gameMode != GameMode.Creative;
            InsomniaBar.IsVisible = gameMode != GameMode.Creative;
            FishingButton.IsVisible = false;
            FishingRoundRange.IsVisible = false;
            FishingCaptureBar.IsVisible = false;
            FishBaitGrid.AssignComponents(null);

            TrapList.ClearItems();

            TrapList.ItemWidgetFactory = delegate (object item)
            {
                var craftingTrapRecipe = (CraftingTrapRecipe)item;
                XElement node2 = ContentManager.Get<XElement>("Widgets/TrapItem");
                var obj = (ContainerWidget)Widget.LoadWidget(this, node2, null);
                obj.Children.Find<BlockIconWidget>("Icon").Value = CraftingRecipesManager.DecodeResult(craftingTrapRecipe.ResultValue);
                return obj;
            };

            foreach (CraftingTrapRecipe recipe in CraftingTrapRecipeManager.Recipes)
            {
                TrapList.AddItem(recipe);
            }

            TrapList.ItemClicked = delegate (object item)
            {
                var craftingTrapRecipe = (CraftingTrapRecipe)item;
                if (TrapList.SelectedIndex.HasValue)
                {
                    string num = "";
                    foreach (var ingredient1 in craftingTrapRecipe.Ingredients)
                    {
                        string[] safeParts = ingredient1.Key.Split(':');
                        string beforeChar = safeParts[0];
                        string afterChar = safeParts.Length > 1 ? safeParts[1] : string.Empty;
                        num += BlocksManager.Blocks[BlocksManager.FindBlocksByCraftingId(beforeChar)[0].BlockIndex].GetDisplayName(null, Terrain.MakeBlockValue(BlocksManager.FindBlocksByCraftingId(beforeChar)[0].BlockIndex, 0, int.Parse(afterChar))) + "X" + ingredient1.Value + " ";
                    }
                    componentGui.DisplaySmallMessage(num, Color.White, true, true);
                    if (CraftingRecipesManager.DecodeResult(CraftingTrapRecipeManager.Recipes[TrapList.SelectedIndex.Value].BottomSquareValue) == subsystemTerrain.Terrain.GetCellValueFast((int)componentBody.Position.X, (int)componentBody.Position.Y - 1, (int)componentBody.Position.Z))
                    {
                        foreach (var ingredient in craftingTrapRecipe.Ingredients)
                        {
                            string ingredientId = ingredient.Key;
                            int requiredCount = ingredient.Value;
                            int remainingToRemove = requiredCount;  // 记录还需要移除多少物品

                            // 先检查是否足够
                            int totalCount = 0;
                            for (int i = 0; i < componentInventory.SlotsCount; i++)
                            {
                                int slotValue = componentInventory.GetSlotValue(i);
                                if (slotValue == 0) continue;

                                int content = Terrain.ExtractContents(slotValue);
                                int data = Terrain.ExtractData(slotValue);
                                Block block = BlocksManager.Blocks[content];
                                string craftingId = block.GetCraftingId(slotValue);
                                string currentIngredientId = $"{craftingId}:{data}";

                                if (currentIngredientId == ingredientId)
                                {
                                    totalCount += componentInventory.GetSlotCount(i);
                                }
                            }

                            if (totalCount < requiredCount)
                            {
                                componentGui.DisplaySmallMessage("材料不足", Color.Red, true, true);
                                goto A;
                            }

                            // 如果足够，实际移除物品
                            for (int a = 0; a < componentInventory.SlotsCount; a++)
                            {
                                if (remainingToRemove <= 0) break;

                                int slotValue = componentInventory.GetSlotValue(a);
                                if (slotValue == 0) continue;

                                int content = Terrain.ExtractContents(slotValue);
                                int data = Terrain.ExtractData(slotValue);
                                Block block = BlocksManager.Blocks[content];
                                string craftingId = block.GetCraftingId(slotValue);
                                string currentIngredientId = $"{craftingId}:{data}";

                                if (currentIngredientId == ingredientId)
                                {
                                    int slotCount = componentInventory.GetSlotCount(a);
                                    int toRemove = Math.Min(slotCount, remainingToRemove);
                                    componentInventory.RemoveSlotItems(a, toRemove);  // 从指定槽位移除指定数量
                                    remainingToRemove -= toRemove;
                                }
                            }
                        }
                        componentGui.ModalPanelWidget = new TrapDurabilitySettingsWidget(componentBody, TrapList.SelectedIndex.Value);
                    }
                    else
                    {
                        componentGui.DisplaySmallMessage("此陷阱无法放置在这上面", Color.Red, true, true);
                    }
                A:
                    TrapList.SelectedIndex = null;
                    TrapContentsWidget.IsVisible = false;
                    TrapButton.IsChecked = false;
                }
            };
        }

        public override void OnEntityAdded()
        {
            FishBaitGrid.AssignComponents(componentPlayer.Entity.FindComponent<ComponentFishBait>(throwOnError: true));
            lightContainer.AddChildren(FarTrapContentsWidget);
            FarTrapContentsWidget.AddChildren(TrapContentsWidget);
            TrapContentsWidget.AddChildren(TrapList);
        }

