        {
            TraumaBar.ParentWidget?.Children.Remove(TraumaBar);
            InternalInjuriesBar.ParentWidget?.Children.Remove(InternalInjuriesBar);
            SpiritBar.ParentWidget?.Children.Remove(SpiritBar);
            InsomniaBar.ParentWidget?.Children.Remove(InsomniaBar);
            PlayerStatsButton.ParentWidget?.Children.Remove(PlayerStatsButton);
            HandGrid.ParentWidget?.Children.Remove(HandGrid);
            TalentButton.ParentWidget?.Children.Remove(TalentButton);
            TransactionButton.ParentWidget?.Children.Remove(TransactionButton);
            FishingButton.ParentWidget?.Children.Remove(FishingButton);
            FishingRoundRange.ParentWidget?.Children.Remove(FishingRoundRange);
            FishingCaptureBar.ParentWidget?.Children.Remove(FishingCaptureBar);
            FishBaitGrid.ParentWidget?.Children.Remove(FishBaitGrid);
            SkillsButton.ParentWidget?.Children.Remove(SkillsButton);
            TrapButton.ParentWidget?.Children.Remove(TrapButton);
            TrapContentsWidget.ParentWidget?.Children.Remove(TrapContentsWidget);
            TrapList.ParentWidget?.Children.Remove(TrapList);
            FarTrapContentsWidget.ParentWidget?.Children.Remove(FarTrapContentsWidget);
            MailboxButton.ParentWidget?.Children.Remove(MailboxButton);
            EventCenterButton.ParentWidget?.Children.Remove(EventCenterButton);
            AdvertisingLotteryButton.ParentWidget?.Children.Remove(AdvertisingLotteryButton);

            Project.EntityAdded -= OnProjectEntityAdded;
            Project.EntityRemoved -= OnProjectEntityRemoved;
        }

        public void Update(float dt)
        {
            if (componentPlayer != null)
            {
                for (int i = 0; i < componentSkills.SkillsAttributes.Count; i++)
                {
                    if (componentSkills.SkillsAttributes[i].Select)
                    {
                        m_checkTimer += dt;
                        if (m_checkTimer >= 1f)
                        {
                            m_checkTimer = 0f;
                            bool anyTargetingPlayer = false;
                            foreach (var chase in s_allChaseBehaviors)
                            {
                                if (chase.Target is ComponentPlayer)
                                {
                                    anyTargetingPlayer = true;
                                    break;
                                }
                            }

                            hasPlayerTarget = anyTargetingPlayer;
                        }

                        SkillsButton.IsVisible = hasPlayerTarget;

                        string Texture = componentSkills.SkillsAttributes[i].Texture;
                        if (componentSkills.SkillsAttributes[i].CooldownTime > 0)
                        {
                            Texture = componentSkills.SkillsAttributes[i].Texture + "_Cooling";
                        }

                        if (NumberLimit && componentSkills.SkillsAttributes[i].NumberLimit)
                        {
                            Texture = componentSkills.SkillsAttributes[i].Texture + "_NumberLimit";
                        }

                        if (SkillsButton.IsClicked)
                        {
                            if (componentSkills.SkillsAttributes[i].CooldownTime == 0)
                            {
                                if (!NumberLimit || !componentSkills.SkillsAttributes[i].NumberLimit)
                                {
                                    foreach (AccessSkills accessSkills in AccessSkillsManager.Data)
                                    {
                                        if (accessSkills.SkillsID == i)
                                        {
                                            componentSkills.TriggerSkills(i);

                                            if (hasPlayerTarget && componentSkills.SkillsAttributes[i].NumberLimit)
                                            {
                                                NumberLimit = true;
                                            }
                                        }
                                    }
                                }
                                else
                                {
                                    componentGui.DisplaySmallMessage("技能限制中", Color.Red, true, true);
                                }
                            }
                            else
                            {
                                componentGui.DisplaySmallMessage("技能冷却中", Color.Red, true, true);
                            }
                        }
                        SkillsButton.NormalSubtexture = SkillsButton.ClickedSubtexture = ContentManager.Get<Texture2D>(Texture);
                    }
                }
                if (PlayerStatsButton.IsClicked)
                {
                    if (PlayerStatsButton.IsChecked)
                    {
                        componentGui.ModalPanelWidget = new PlayerStatsWidget(componentPlayer);
                    }
                    else
                    {
                        componentGui.ModalPanelWidget = null;
                    }
                }
                if (TalentButton.IsClicked)
                {
                    if (TalentButton.IsChecked)
                    {
                        componentGui.ModalPanelWidget = new TalentWidget(componentPlayer);
                    }
                    else
                    {
                        componentGui.ModalPanelWidget = null;
                    }
                }
                if (TransactionButton.IsClicked && componentMerchant != null)
                {
                    if (TransactionButton.IsChecked)
                    {
                        componentGui.ModalPanelWidget = new TransactionWidget(componentPlayer, componentMerchant);
                    }
                    else
                    {
                        componentGui.ModalPanelWidget = null;
                    }
                }
                SpiritBar.Value = componentVitalStats.Sleep;
                if (FishingButton == null)
                {
                    FishBaitGrid.IsVisible = false;
                }
                else
                {
                    FishBaitGrid.IsVisible = FishingButton.IsVisible;
                }
                if (TrapButton.IsClicked)
                {
                    if (TrapButton.IsChecked)
                    {
                        TrapContentsWidget.IsVisible = true;
                    }
                    else
                    {
                        TrapContentsWidget.IsVisible = false;
                    }
                }
                if (MailboxButton.IsClicked)
                {
                    if (MailboxButton.IsChecked)
                    {
                        ScreensManager.SwitchScreen("Mailbox");
                    }
                }
                if (EventCenterButton.IsClicked)
                {
                    if (EventCenterButton.IsChecked)
                    {
                        componentGui.ModalPanelWidget = new EventCenterWidget(componentPlayer);
                    }
                    else
                    {
                        componentGui.ModalPanelWidget = null;
                    }
                }
                if (AdvertisingLotteryButton.IsClicked)
                {
                    if (AdvertisingLotteryButton.IsChecked)
                    {
                        componentGui.ModalPanelWidget = new AdvertisingLotteryWidget(componentPlayer);
                    }
                    else
                    {
                        componentGui.ModalPanelWidget = null;
                    }
                }

            }
        }
    }
}
//组件身体属性
namespace Game
{
    public class ComponentPhysicalAttributes : Component, IUpdateable
    {
        public ComponentHYZLGui componentHYZLGui;
        public ComponentPlayer componentPlayer;
        public ComponentLevel componentLevel;
        public ComponentTalent componentTalent;
        public ComponentExtraAttributes componentExtraAttributes;
        public ComponentMiner componentMiner;
        public SubsystemGameInfo subsystemGameInfo;
        public SubsystemTime subsystemTime;
        public SubsystemAudio subsystemAudio;

        public float FoodResistance;
        public float SleepResistance;
        public float Trauma;
        public float TraumaResistance;
        public float InternalInjuries;
        public float InternalInjuriesResistance;
        public float Insomnia;
        public float InsomniaResistance;
        public float Level;
        public float LevelAtPresent;
        public float LevelResistance;
        public float LowTemperatureResistance;
        public float HighTemperatureResistance;

        public float SkillShield;

        public double NewIntelligence;
        public float NewFoodResistance;

        public bool Sleep = false;

        public double Intelligence;
        public double Agility;
        public double Endurance;
        public double Power;

        public Dictionary<ClothingSlot, (float, float)> ClothingAttributes = [];

        public Random m_random = new();

        public static string fName = "ComponentPhysicalAttributes";

        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public void Update(float dt)
        {
            if (componentHYZLGui.TraumaBar.IsVisible)
            {
                componentHYZLGui.TraumaBar.Value = Trauma;
                componentHYZLGui.InternalInjuriesBar.Value = InternalInjuries;
                componentHYZLGui.InsomniaBar.Value = Insomnia;
            }
            if (componentPlayer.ComponentHealth.Health > 0f)
            {
                LevelResistance = 80f * Level * MathF.Pow(2f, (float)Math.Floor(Level / 10f));
                if (LevelAtPresent >= LevelResistance)
                {
                    LevelAtPresent -= LevelResistance;
                    Level++;
                    subsystemAudio.PlaySound("Audio/Upgrade", 0.2f, m_random.Float(-0.1f, 0.4f), 0f, 0f);
                    componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 8), Color.White, true, true);
                }
                Intelligence = NewIntelligence * componentLevel.OtherFactorsResults["Intelligence"];
                Agility = componentExtraAttributes.DodgeRate * 20 + componentPlayer.ComponentLocomotion.WalkSpeed * componentLevel.SpeedFactor;
                Endurance = componentPlayer.ComponentHealth.AttackResilience * componentLevel.ResilienceFactor / 35f;
                Power = componentMiner.AttackPower * componentLevel.StrengthFactor / 3f + componentExtraAttributes.HitRate * 5;
                for (int a = 0; a < componentTalent.TalentAttributes.Count; a++)
                {
                    if (componentTalent.TalentAttributes[a].IncreasedUpperLimitOfSatiety > 0 && componentTalent.TalentAttributes[a].Field > 0)
                    {
                        FoodResistance = NewFoodResistance + (componentTalent.TalentAttributes[a].IncreasedUpperLimitOfSatiety + (componentTalent.TalentAttributes[a].Level - 1) * 5f);
                    }
                }
                UpdateTrauma();
                UpdateInternalInjuries();
                UpdateInsomnia();

            }
        }

        public virtual void AddExperience(int count, bool playSound)
        {
            if (playSound)
            {
                subsystemAudio.PlaySound("Audio/ExperienceCollected", 0.2f, m_random.Float(-0.1f, 0.4f), 0f, 0f);
            }
            for (int i = 0; i < count; i++)
            {
                LevelAtPresent++;
            }
        }

        public virtual void UpdateTrauma()
        {
            Trauma = MathUtils.Saturate(Trauma);
            if (subsystemGameInfo.WorldSettings.GameMode != 0 && subsystemGameInfo.WorldSettings.AreAdventureSurvivalMechanicsEnabled)
            {
                if (!componentPlayer.ComponentSleep.IsSleeping)
                {
                    if (subsystemTime.PeriodicGameTimeEvent(5.0, 0))
                    {
                        if (Trauma <= 0f)
                        {
                            InternalInjuries -= 20f / (InternalInjuriesResistance / 100f);
                        }
                        else if (Trauma < 0.1f)
                        {
                            componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 1), Color.White, true, true);
                            InternalInjuries -= 15f / (InternalInjuriesResistance / 100f);
                        }
                        else if (Trauma < 0.25f)
                        {
                            componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 2), Color.White, true, true);
                            InternalInjuries -= 10f / (InternalInjuriesResistance / 100f);
                        }
                        else if (Trauma < 0.5f)
                        {
                            componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 3), Color.White, true, false);
                            InternalInjuries -= 5f / (InternalInjuriesResistance / 100f);
                        }
                    }
                }
            }
            else
            {
                Trauma = 1f;
            }
        }

        public virtual void UpdateInternalInjuries()
        {
            InternalInjuries = MathUtils.Saturate(InternalInjuries);
            if (subsystemGameInfo.WorldSettings.GameMode != 0 && subsystemGameInfo.WorldSettings.AreAdventureSurvivalMechanicsEnabled)
            {
                if (!componentPlayer.ComponentSleep.IsSleeping)
                {
                    if (subsystemTime.PeriodicGameTimeEvent(5.0, 0))
                    {
                        if (InternalInjuries < 0.1f)
                        {
                            componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 4), Color.White, true, true);
                        }
                        else if (InternalInjuries < 0.25f)
                        {
                            componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 5), Color.White, true, true);
                        }
                        else if (InternalInjuries < 0.5f)
                        {
                            componentPlayer.ComponentGui.DisplaySmallMessage(LanguageControl.Get(fName, 6), Color.White, true, false);
                        }
                        if (InternalInjuries < 0.8f)
                        {
                            componentPlayer.ComponentHealth.Injure(MathUtils.Max(0.8f - InternalInjuries, 0.1f) * 50f / componentPlayer.ComponentHealth.AttackResilience, null, false, LanguageControl.Get(fName, 7));
                        }
                    }
                }
            }
            else
            {
                InternalInjuries = 1f;
            }
        }

        public virtual void UpdateInsomnia()
        {
            Insomnia = MathUtils.Saturate(Insomnia);
            if (subsystemGameInfo.WorldSettings.GameMode != 0 && subsystemGameInfo.WorldSettings.AreAdventureSurvivalMechanicsEnabled)
            {
                if (!componentPlayer.ComponentSleep.IsSleeping && !Sleep)
                {
                    float num1 = 1;
                    for (int a = 0; a < componentTalent.TalentAttributes.Count; a++)
                    {
                        if (componentTalent.TalentAttributes[a].TheRateAtWhichInsomniaDecreases > 0 && componentTalent.TalentAttributes[a].Field > 0)
                        {
                            num1 -= componentTalent.TalentAttributes[a].TheRateAtWhichInsomniaDecreases + (componentTalent.TalentAttributes[a].Level - 1) * 0.05f;
                        }
                    }
                    if (subsystemGameInfo.WorldSettings.TimeOfDayMode == TimeOfDayMode.Day)
                    {
                        Insomnia -= subsystemTime.GameTimeDelta / 2040f * num1 / (InsomniaResistance / 100f);
                    }
                    else
                    {
                        Insomnia -= subsystemTime.GameTimeDelta / 508f * num1 / (InsomniaResistance / 100f);
                    }
                }
            }
            else
            {
                Insomnia = 1f;
            }
        }

        public override void Save(ValuesDictionary valuesDictionary, EntityToIdMap entityToIdMap)
        {
            valuesDictionary.SetValue<float>("FoodResistance", FoodResistance);
            valuesDictionary.SetValue<float>("SleepResistance", SleepResistance);
            valuesDictionary.SetValue<float>("Trauma", Trauma);
            valuesDictionary.SetValue<float>("TraumaResistance", TraumaResistance);
            valuesDictionary.SetValue<float>("InternalInjuries", InternalInjuries);
            valuesDictionary.SetValue<float>("InternalInjuriesResistance", InternalInjuriesResistance);
            valuesDictionary.SetValue<float>("Insomnia", Insomnia);
            valuesDictionary.SetValue<float>("InsomniaResistance", InsomniaResistance);
            valuesDictionary.SetValue<float>("Level", Level);
            valuesDictionary.SetValue<float>("LevelAtPresent", LevelAtPresent);
            valuesDictionary.SetValue<float>("SkillShield", SkillShield);
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            componentHYZLGui = Entity.FindComponent<ComponentHYZLGui>();
            componentPlayer = Entity.FindComponent<ComponentPlayer>();
            componentLevel = Entity.FindComponent<ComponentLevel>();
            componentTalent = Entity.FindComponent<ComponentTalent>();
            componentExtraAttributes = Entity.FindComponent<ComponentExtraAttributes>();
            componentMiner = Entity.FindComponent<ComponentMiner>();
            subsystemGameInfo = Project.FindSubsystem<SubsystemGameInfo>();
            subsystemTime = Project.FindSubsystem<SubsystemTime>();
            subsystemAudio = Project.FindSubsystem<SubsystemAudio>();

            FoodResistance = valuesDictionary.GetValue<float>("FoodResistance");
            SleepResistance = valuesDictionary.GetValue<float>("SleepResistance");
            Trauma = valuesDictionary.GetValue<float>("Trauma");
            TraumaResistance = valuesDictionary.GetValue<float>("TraumaResistance");
            InternalInjuries = valuesDictionary.GetValue<float>("InternalInjuries");
            InternalInjuriesResistance = valuesDictionary.GetValue<float>("InternalInjuriesResistance");
            Insomnia = valuesDictionary.GetValue<float>("Insomnia");
            InsomniaResistance = valuesDictionary.GetValue<float>("InsomniaResistance");
            Intelligence = valuesDictionary.GetValue<double>("Intelligence");
            Level = valuesDictionary.GetValue<float>("Level");
            LevelAtPresent = valuesDictionary.GetValue<float>("LevelAtPresent");
            LowTemperatureResistance = valuesDictionary.GetValue<float>("LowTemperatureResistance");
            HighTemperatureResistance = valuesDictionary.GetValue<float>("HighTemperatureResistance");
            SkillShield = valuesDictionary.GetValue<float>("SkillShield", 0);

            NewIntelligence = Intelligence;
            NewFoodResistance = FoodResistance;
        }
    }
}
//组件伤口感染
namespace Game
{
    public class ComponentWoundInfection : Component, IUpdateable
    {
        public SubsystemGameInfo m_subsystemGameInfo;
        public SubsystemTerrain m_subsystemTerrain;
        public SubsystemTime m_subsystemTime;
        public SubsystemAudio m_subsystemAudio;
        public SubsystemParticles m_subsystemParticles;
        public ComponentPlayer m_componentPlayer;
        public ComponentPhysicalAttributes componentPhysicalAttributes;
        public ComponentTalent componentTalent;
        public Random m_random = new();

        // 感染相关变量
        public float m_infectionProgress;      // 感染进展程度 (0-100)
        public float m_infectionSeverity;      // 感染严重程度 (0-1)
        public float m_infectionDuration;      // 感染总持续时间（秒）
        public float m_painDuration;           // 疼痛效果持续时间
        public float m_feverDuration;          // 发烧效果持续时间
        public float m_visionBlurDuration;     // 视觉模糊持续时间
        public float m_visionBlurFactor;       // 视觉模糊程度

        // 新增：屏幕效果相关变量
        public float m_blackoutDuration;       // 黑屏效果持续时间
        public float m_blackoutFactor;         // 黑屏程度
        public float m_redoutDuration;         // 红屏效果持续时间
        public float m_redoutFactor;           // 红屏程度

        public double m_lastPainTime = -1000.0;
        public double m_lastFeverTime = -1000.0;
        public double m_lastMessageTime = -1000.0;
        public double m_infectionStartTime = -1000.0; // 感染开始时间

        public static string fName = "ComponentWoundInfection";

        // 感染状态判断属性
        public bool HasInfection => m_infectionSeverity > 0f;
        public bool IsWoundInfection => HasInfection && m_infectionDuration > 0f;
        public bool IsInPain => m_painDuration > 0f;
        public bool HasFever => m_feverDuration > 0f;
        public bool IsEarlyStage => HasInfection && m_infectionDuration < 300f; // 早期阶段（5分钟内）
        public bool IsAdvancedStage => HasInfection && m_infectionDuration >= 300f && m_infectionDuration < 600f; // 中期阶段（5-10分钟）
        public bool IsCriticalStage => HasInfection && m_infectionDuration >= 600f; // 危重阶段（10分钟以上）

        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public virtual void StartInfection(float severity = 0.1f)
        {
            bool isNewInfection = m_infectionSeverity == 0f;

            if (isNewInfection)
            {
                m_infectionStartTime = m_subsystemTime.GameTime;
                m_infectionDuration = 0f;

                // 新感染开始时显示消息
                m_componentPlayer.ComponentGui.DisplaySmallMessage(
                    LanguageControl.Get(fName, 6), Color.Yellow, true, true);
            }

            m_infectionSeverity = MathUtils.Clamp(m_infectionSeverity + severity, 0f, 1f);
            m_infectionProgress = MathUtils.Max(m_infectionProgress, 10f); // 最低感染进度

            // 感染开始时产生虚弱效果
            m_subsystemAudio.PlayRandomSound("Audio/Status/Weakness", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
            m_subsystemTime.QueueGameTimeDelayedExecution(
                m_subsystemTime.GameTime + 5.0,
                delegate
                {
                    m_subsystemAudio.PlayRandomSound("Audio/Status/PhysicalExertion", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
                    m_componentPlayer.ComponentVitalStats.Stamina =
                        MathUtils.Max(m_componentPlayer.ComponentVitalStats.Stamina - 0.3f, 0.1f);
                }
            );

            // 如果是严重感染，立即触发一些效果
            if (severity >= 0.3f)
            {
                TriggerPain();
                // 严重感染开始时触发短暂黑屏
                TriggerBlackout(1.5f, 0.3f);
            }
        }

        public virtual void HealInfection(float healAmount)
        {
            float previousSeverity = m_infectionSeverity;
            m_infectionSeverity = MathUtils.Max(m_infectionSeverity - healAmount, 0f);

            if (m_infectionSeverity <= 0f)
            {
                ClearInfection();
                m_componentPlayer.ComponentGui.DisplaySmallMessage(
                    LanguageControl.Get(fName, 5), Color.LightGreen, true, true);
            }
            else if (previousSeverity >= 0.5f && m_infectionSeverity < 0.5f)
            {
                // 从严重感染转为轻度感染时显示消息
                m_componentPlayer.ComponentGui.DisplaySmallMessage(
                    LanguageControl.Get(fName, 7), Color.LightBlue, true, true);
            }
        }

        public virtual void TriggerPain()
        {
            m_lastPainTime = m_subsystemTime.GameTime;
            m_painDuration = 2f + m_infectionSeverity * 3f;

            // 播放疼痛音效
            m_componentPlayer.ComponentCreatureSounds.PlayPainSound();

            // 产生噪音
            Project.FindSubsystem<SubsystemNoise>(true).MakeNoise(
                m_componentPlayer.ComponentBody.Position, 0.15f, 8f);

            // 疼痛时触发红屏效果（表示血液上涌）
            TriggerRedout(1.0f + m_infectionSeverity * 2f, 0.2f + m_infectionSeverity * 0.3f);
        }

        public virtual void TriggerFever()
        {
            m_lastFeverTime = m_subsystemTime.GameTime;
            m_feverDuration = 8f + m_infectionSeverity * 12f;

            // 发烧效果：视觉模糊和体力消耗
            m_subsystemAudio.PlayRandomSound("Audio/Status/Fever", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
            m_visionBlurDuration = 3f;

            // 发烧时可能触发黑屏（虚弱晕眩）
            if (m_random.Bool(0.4f))
            {
                m_subsystemAudio.PlaySound("Audio/Status/Dizziness", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
                TriggerBlackout(2.0f, 0.15f + m_infectionSeverity * 0.2f);
            }
        }

        // 新增：触发黑屏效果
        public virtual void TriggerBlackout(float duration, float intensity)
        {
            m_blackoutDuration = MathUtils.Max(m_blackoutDuration, duration);
            m_blackoutFactor = MathUtils.Clamp(m_blackoutFactor + intensity, 0f, 0.8f);
        }

        // 新增：触发红屏效果  
        public virtual void TriggerRedout(float duration, float intensity)
        {
            m_redoutDuration = MathUtils.Max(m_redoutDuration, duration);
            m_redoutFactor = MathUtils.Clamp(m_redoutFactor + intensity, 0f, 0.6f);
        }

        public virtual void Update(float dt)
        {
            // 创意模式或禁用生存机制时清除感染
            if (m_subsystemGameInfo.WorldSettings.GameMode == GameMode.Creative ||
                !m_subsystemGameInfo.WorldSettings.AreAdventureSurvivalMechanicsEnabled)
            {
                ClearInfection();
                return;
            }

            // 更新感染持续时间
            if (HasInfection)
            {
                m_infectionDuration += dt;
            }

            UpdateInfectionProgress(dt);
            UpdateInfectionEffects(dt);
            UpdateVisualEffects(dt);
            UpdateStageBasedEffects(dt);
        }

        public void UpdateInfectionProgress(float dt)
        {
            if (HasInfection)
            {
                // 感染恶化逻辑
                float worsenRate = CalculateWorsenRate();
                m_infectionProgress += worsenRate * dt;

                // 感染进度影响严重程度
                if (m_infectionProgress >= 100f)
                {
                    m_infectionSeverity = MathUtils.Min(m_infectionSeverity + 0.1f, 1f);
                    m_infectionProgress = 0f;

                    // 感染加重时显示警告
                    if (m_infectionSeverity >= 0.7f)
                    {
                        m_componentPlayer.ComponentGui.DisplaySmallMessage(
                            LanguageControl.Get(fName, 8), Color.Red, true, true);

                        // 危重感染加重时触发强烈黑屏
                        TriggerBlackout(3.0f, 0.4f);
                    }
                }

                // 定期感染效果
                if (m_componentPlayer.ComponentHealth.Health > 0f &&
                    !m_componentPlayer.ComponentSleep.IsSleeping &&
                    m_subsystemTime.PeriodicGameTimeEvent(8.0, -0.01) &&
                    m_subsystemTime.GameTime - m_lastPainTime > 15.0)
                {
                    InfectionEffect();
                }
            }
            else
            {
                // 检查是否应该开始感染（基于健康值和卫生条件）
                CheckInfectionStart(dt);
            }
        }

        public float CalculateWorsenRate()
        {
            float baseRate = 0.5f;

            // 健康值低时感染恶化更快
            if (componentPhysicalAttributes.Trauma < 0.3f)
            {
                baseRate *= 2f;
            }

            // 卫生条件差时恶化更快
            if (m_componentPlayer.ComponentVitalStats.Food < 0.2f)
            {
                baseRate *= 1.5f;
            }

            // 感染持续时间越长，恶化越快
            if (m_infectionDuration > 600f)
            { // 10分钟后
                baseRate *= 1.8f;
            }
            else if (m_infectionDuration > 300f)
            { // 5分钟后
                baseRate *= 1.3f;
            }

            return baseRate * m_infectionSeverity;
        }

        public void CheckInfectionStart(float dt)
        {
            // 健康值低于50%时有可能感染
            if (componentPhysicalAttributes.Trauma < 0.5f)
            {
                float infectionChance = (0.5f - componentPhysicalAttributes.Trauma);

                for (int a = 0; a < componentTalent.TalentAttributes.Count; a++)
                {
                    if (componentTalent.TalentAttributes[a].TheIncidenceOfTraumaWasReduced != 0 && componentTalent.TalentAttributes[a].Field > 0)
                    {
                        infectionChance -= componentTalent.TalentAttributes[a].TheIncidenceOfTraumaWasReduced + (componentTalent.TalentAttributes[a].Level - 1) * 0.15f;
                    }
                }

                if (m_subsystemTime.PeriodicGameTimeEvent(10.0, 0.0) &&
                    m_random.Bool(infectionChance))
                {
                    StartInfection(0.05f);
                }
            }
        }

        public void UpdateInfectionEffects(float dt)
        {
            // 更新疼痛和发烧持续时间
            m_painDuration = MathUtils.Max(m_painDuration - dt, 0f);
            m_feverDuration = MathUtils.Max(m_feverDuration - dt, 0f);

            // 疼痛效果：屏幕抖动和移动困难
            if (IsInPain && m_componentPlayer.ComponentHealth.Health > 0f &&
                !m_componentPlayer.ComponentSleep.IsSleeping)
            {
                ApplyPainEffects(dt);
            }

            // 发烧效果：体力消耗和视觉模糊
            if (HasFever)
            {
                ApplyFeverEffects(dt);
            }
        }

        public void ApplyPainEffects(float dt)
        {
            // 屏幕抖动效果
            float painIntensity = m_infectionSeverity * 0.8f;
            float shakeAngle = MathUtils.DegToRad(
                MathUtils.Lerp(-15f, -35f,
                    SimplexNoise.Noise(3f * (float)MathUtils.Remainder(m_subsystemTime.GameTime, 10000.0)))
            );

            m_componentPlayer.ComponentLocomotion.LookOrder = new Vector2(
                m_componentPlayer.ComponentLocomotion.LookOrder.X,
                Math.Clamp(shakeAngle - m_componentPlayer.ComponentLocomotion.LookAngles.Y, -2f, 2f)
            );

            // 随机移动阻碍
            if (m_random.Bool(1.5f * dt))
            {
                m_componentPlayer.ComponentBody.ApplyImpulse(
                    -0.8f * m_componentPlayer.ComponentCreatureModel.EyeRotation.GetForwardVector());
            }

            // 剧烈疼痛时可能触发短暂黑屏（晕厥前兆）
            if (m_infectionSeverity > 0.6f && m_random.Bool(0.1f * dt))
            {
                m_subsystemAudio.PlayRandomSound("Audio/Status/SeverePain", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
                TriggerBlackout(0.5f, 0.2f);
            }
        }

        public void ApplyFeverEffects(float dt)
        {
            // 体力缓慢消耗
            if (m_subsystemTime.PeriodicGameTimeEvent(3.0, 0.0))
            {
                m_subsystemAudio.PlayRandomSound("Audio/Status/PhysicalExertion", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
                m_componentPlayer.ComponentVitalStats.Stamina =
                    MathUtils.Max(m_componentPlayer.ComponentVitalStats.Stamina - 0.05f, 0.1f);
            }

            // 高烧时可能随机触发黑屏（意识模糊）
            if (m_infectionSeverity > 0.5f && m_subsystemTime.PeriodicGameTimeEvent(15.0, 0.2) && m_random.Bool(0.3f))
            {
                m_subsystemAudio.PlayRandomSound("Audio/Status/Fever", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
                TriggerBlackout(1.0f, 0.1f + m_infectionSeverity * 0.1f);
            }
        }

        public void UpdateVisualEffects(float dt)
        {
            // 视觉模糊效果
            if (m_visionBlurDuration > 0f)
            {
                m_visionBlurDuration = MathUtils.Max(m_visionBlurDuration - dt, 0f);
                m_visionBlurFactor = MathUtils.Min(m_visionBlurFactor + 0.8f * dt, 0.7f);
            }
            else if (m_visionBlurFactor > 0f)
            {
                m_visionBlurFactor = MathUtils.Max(m_visionBlurFactor - 0.3f * dt, 0f);
            }

            // 黑屏效果
            if (m_blackoutDuration > 0f)
            {
                m_blackoutDuration = MathUtils.Max(m_blackoutDuration - dt, 0f);
                m_blackoutFactor = MathUtils.Min(m_blackoutFactor + 1.5f * dt, 0.8f);
            }
            else if (m_blackoutFactor > 0f)
            {
                m_blackoutFactor = MathUtils.Max(m_blackoutFactor - 0.5f * dt, 0f);
            }

            // 红屏效果
            if (m_redoutDuration > 0f)
            {
                m_redoutDuration = MathUtils.Max(m_redoutDuration - dt, 0f);
                m_redoutFactor = MathUtils.Min(m_redoutFactor + 2.0f * dt, 0.6f);
            }
            else if (m_redoutFactor > 0f)
            {
                m_redoutFactor = MathUtils.Max(m_redoutFactor - 0.8f * dt, 0f);
            }

            // 应用屏幕叠加效果
            m_componentPlayer.ComponentScreenOverlays.BlackoutFactor = m_blackoutFactor;
            m_componentPlayer.ComponentScreenOverlays.RedoutFactor = m_redoutFactor;
        }

        public void UpdateStageBasedEffects(float dt)
        {
            if (!IsWoundInfection) return;

            // 基于感染阶段的特效
            if (IsCriticalStage)
            {
                // 危重阶段：持续的健康损失
                if (m_subsystemTime.PeriodicGameTimeEvent(20.0, 0.0))
                {
                    float damage = 0.02f;
                    m_componentPlayer.ComponentHealth.Injure(damage, null, false,
                        LanguageControl.Get(fName, 9));

                    // 危重阶段随机触发黑屏（濒死体验）
                    if (m_random.Bool(0.4f))
                    {
                        m_subsystemAudio.PlayRandomSound("Audio/Status/Dying", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
                        TriggerBlackout(1.5f, 0.25f);
                    }
                }

                // 危重阶段持续的红屏效果（内出血）
                if (m_subsystemTime.PeriodicGameTimeEvent(30.0, 0.1) && m_redoutFactor < 0.3f)
                {
                    m_subsystemAudio.PlayRandomSound("Audio/Status/InternalBleeding", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
                    TriggerRedout(10.0f, 0.1f);
                }
            }
            else if (IsAdvancedStage)
            {
                // 中期阶段：偶尔的健康损失
                if (m_subsystemTime.PeriodicGameTimeEvent(45.0, 0.0) && m_random.Bool(0.6f))
                {
                    float damage = 0.01f;
                    m_componentPlayer.ComponentHealth.Injure(damage, null, false,
                        LanguageControl.Get(fName, 9));
                }
            }
        }

        public virtual void InfectionEffect()
        {
            m_lastPainTime = m_subsystemTime.GameTime;

            // 健康值伤害（基础伤害）
            float damage = MathUtils.Min(0.08f, m_componentPlayer.ComponentHealth.Health - 0.15f);
            if (damage > 0f)
            {
                m_subsystemTime.QueueGameTimeDelayedExecution(
                    m_subsystemTime.GameTime + 1.0,
                    delegate
                    {
                        m_componentPlayer.ComponentHealth.Injure(damage, null, false,
                            LanguageControl.Get(fName, 4));
                    }
                );
            }

            // 显示感染状态消息
            if (Time.FrameStartTime - m_lastMessageTime > 45.0)
            {
                m_lastMessageTime = Time.FrameStartTime;
                m_subsystemTime.QueueGameTimeDelayedExecution(
                    m_subsystemTime.GameTime + 1.0,
                    delegate
                    {
                        if (m_infectionSeverity < 0.3f)
                        {
                            m_componentPlayer.ComponentGui.DisplaySmallMessage(
                                LanguageControl.Get(fName, 1), Color.Yellow, true, true);
                        }
                        else if (m_infectionSeverity < 0.7f)
                        {
                            m_componentPlayer.ComponentGui.DisplaySmallMessage(
                                LanguageControl.Get(fName, 2), Color.Orange, true, true);
                        }
                        else
                        {
                            m_componentPlayer.ComponentGui.DisplaySmallMessage(
                                LanguageControl.Get(fName, 3), Color.Red, true, true);
                        }
                    }
                );
            }

            // 触发疼痛或发烧
            if (m_painDuration == 0f && (m_subsystemTime.GameTime - m_lastPainTime > 25.0 || m_random.Bool(0.6f)))
            {
                TriggerPain();
            }
            else if (m_feverDuration == 0f && m_random.Bool(0.3f))
            {
                TriggerFever();
            }
        }

        public void ClearInfection()
        {
            m_infectionProgress = 0f;
            m_infectionSeverity = 0f;
            m_infectionDuration = 0f;
            m_painDuration = 0f;
            m_feverDuration = 0f;
            m_visionBlurDuration = 0f;
            m_visionBlurFactor = 0f;
            m_blackoutDuration = 0f;
            m_blackoutFactor = 0f;
            m_redoutDuration = 0f;
            m_redoutFactor = 0f;
            m_infectionStartTime = -1000.0;

            // 清除屏幕效果
            if (m_componentPlayer != null && m_componentPlayer.ComponentScreenOverlays != null)
            {
                m_componentPlayer.ComponentScreenOverlays.BlackoutFactor = 0f;
                m_componentPlayer.ComponentScreenOverlays.RedoutFactor = 0f;
            }
        }

        // 获取感染信息的方法
        public string GetInfectionStatus()
        {
            if (!IsWoundInfection) return "无感染";

            string stage = IsEarlyStage ? "早期" : (IsAdvancedStage ? "中期" : "危重");
            string severity = m_infectionSeverity < 0.3f ? "轻度" :
                             (m_infectionSeverity < 0.7f ? "中度" : "重度");

            return $"{stage} {severity}感染 ({Math.Round(m_infectionDuration / 60f, 1)}分钟)";
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            m_subsystemGameInfo = Project.FindSubsystem<SubsystemGameInfo>(true);
            m_subsystemTerrain = Project.FindSubsystem<SubsystemTerrain>(true);
            m_subsystemTime = Project.FindSubsystem<SubsystemTime>(true);
            m_subsystemAudio = Project.FindSubsystem<SubsystemAudio>(true);
            m_subsystemParticles = Project.FindSubsystem<SubsystemParticles>(true);
            m_componentPlayer = Entity.FindComponent<ComponentPlayer>(true);
            componentPhysicalAttributes = Entity.FindComponent<ComponentPhysicalAttributes>(true);
            componentTalent = Entity.FindComponent<ComponentTalent>(true);

            m_infectionProgress = valuesDictionary.GetValue<float>("InfectionProgress");
            m_infectionSeverity = valuesDictionary.GetValue<float>("InfectionSeverity");
            m_infectionDuration = valuesDictionary.GetValue<float>("InfectionDuration");

            // 如果加载时有感染，设置开始时间
            if (HasInfection)
            {
                m_infectionStartTime = m_subsystemTime.GameTime - m_infectionDuration;
            }
        }

        public override void Save(ValuesDictionary valuesDictionary, EntityToIdMap entityToIdMap)
        {
            valuesDictionary.SetValue("InfectionProgress", m_infectionProgress);
            valuesDictionary.SetValue("InfectionSeverity", m_infectionSeverity);
            valuesDictionary.SetValue("InfectionDuration", m_infectionDuration);
        }
    }
}
//组件Buff
namespace Game
{
    public class ComponentBuff : Component, IUpdateable
    {
        public ComponentWoundInfection componentWoundInfection;
        public ComponentFactors componentFactors;
        public ComponentPhysicalAttributes componentPhysicalAttributes;
        public ComponentLevel componentLevel;
        public ComponentTalent componentTalent;

        public Dictionary<string, (float, float, float, float, float, float)> FishBuff = new Dictionary<string, (float, float, float, float, float, float)>();
        public Dictionary<string, (float, float, float)> ThreePillBuff = new Dictionary<string, (float, float, float)>();

        public static string fName = "ComponentBuff";

        public UpdateOrder UpdateOrder => UpdateOrder.Default;
        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            componentWoundInfection = Entity.FindComponent<ComponentWoundInfection>(true);
            componentFactors = Entity.FindComponent<ComponentFactors>(true);
            componentPhysicalAttributes = Entity.FindComponent<ComponentPhysicalAttributes>(true);
            componentLevel = Entity.FindComponent<ComponentLevel>(true);
            componentTalent = Entity.FindComponent<ComponentTalent>(true);

            componentLevel.OtherFactors["HitRate"] = new List<Factor>();
            componentLevel.OtherFactors["CriticalStrikeRate"] = new List<Factor>();
            componentLevel.OtherFactors["DodgeRate"] = new List<Factor>();
            componentLevel.OtherFactors["Intelligence"] = new List<Factor>();
            componentLevel.OtherFactors["Defense"] = new List<Factor>();
            componentLevel.OtherFactors["Temperature"] = new List<Factor>();


            ValuesDictionary value2 = valuesDictionary.GetValue<ValuesDictionary>("FishBuff", null);
            if (value2 != null)
            {
                for (int j = 0; j < valuesDictionary.GetValue<int>("FishBuffCount"); j++)
                {
                    ValuesDictionary value3 = value2.GetValue<ValuesDictionary>("FishBuff" + j, null);
                    if (value3 != null)
                    {
                        FishBuff[value3.GetValue<string>("BuffName")] = (value3.GetValue<float>("AttackEnhancement"), value3.GetValue<float>("DefenseEnhancement"), value3.GetValue<float>("IncreasedHitRate"), value3.GetValue<float>("IncreasedAvoidanceRate"), value3.GetValue<float>("TemperatureIncrease"), value3.GetValue<float>("BuffTime"));
                    }
                }
            }
            value2 = valuesDictionary.GetValue<ValuesDictionary>("ThreePillBuff", null);
            if (value2 != null)
            {
                for (int j = 0; j < valuesDictionary.GetValue<int>("ThreePillBuffCount"); j++)
                {
                    ValuesDictionary value3 = value2.GetValue<ValuesDictionary>("ThreePillBuff" + j, null);
                    if (value3 != null)
                    {
                        ThreePillBuff[value3.GetValue<string>("BuffName")] = (value3.GetValue<float>("ImmunotoxicTime"), value3.GetValue<float>("ImmuneDizzyTime"), value3.GetValue<float>("TimeToRaiseTheTemperature"));
                    }
                }
            }
        }

        public override void Save(ValuesDictionary valuesDictionary, EntityToIdMap entityToIdMap)
        {
            valuesDictionary.SetValue("FishBuffCount", FishBuff.Count);
            ValuesDictionary valuesDictionary2 = new();
            valuesDictionary.SetValue("FishBuff", valuesDictionary2);
            for (int i = 0; i < FishBuff.Count; i++)
            {
                (float, float, float, float, float, float) fishBuff = FishBuff.ElementAt(i).Value;
                if (fishBuff.Item6 > 0)
                {
                    ValuesDictionary valuesDictionary3 = new();
                    valuesDictionary2.SetValue("FishBuff" + i, valuesDictionary3);
                    valuesDictionary3.SetValue("BuffName", FishBuff.ElementAt(i).Key);
                    valuesDictionary3.SetValue("AttackEnhancement", fishBuff.Item1);
                    valuesDictionary3.SetValue("DefenseEnhancement", fishBuff.Item2);
                    valuesDictionary3.SetValue("IncreasedHitRate", fishBuff.Item3);
                    valuesDictionary3.SetValue("IncreasedAvoidanceRate", fishBuff.Item4);
                    valuesDictionary3.SetValue("TemperatureIncrease", fishBuff.Item5);
                    valuesDictionary3.SetValue("BuffTime", fishBuff.Item6);
                }
            }
            valuesDictionary.SetValue("ThreePillBuffCount", ThreePillBuff.Count);
            ValuesDictionary valuesDictionary5 = new();
            valuesDictionary.SetValue("ThreePillBuff", valuesDictionary5);
            for (int i = 0; i < ThreePillBuff.Count; i++)
            {
                (float, float, float) threePillBuff = ThreePillBuff.ElementAt(i).Value;
                if (threePillBuff.Item1 > 0 || threePillBuff.Item2 > 0 || threePillBuff.Item3 > 0)
                {
                    ValuesDictionary valuesDictionary4 = new();
                    valuesDictionary5.SetValue("ThreePillBuff" + i, valuesDictionary4);
                    valuesDictionary4.SetValue("BuffName", ThreePillBuff.ElementAt(i).Key);
                    valuesDictionary4.SetValue("ImmunotoxicTime", threePillBuff.Item1);
                    valuesDictionary4.SetValue("ImmuneDizzyTime", threePillBuff.Item2);
                    valuesDictionary4.SetValue("TimeToRaiseTheTemperature", threePillBuff.Item3);
                }
            }
        }

        public void Update(float dt)
        {
            GenerateStrengthFactors();
            GenerateResilienceFactors();
            GenerateSpeedFactors();
            GenerateHitRateFactors();
            GenerateCriticalStrikeRateFactors();
            GenerateDodgeRateFactors();
            GenerateIntelligenceFactors();
            GenerateDefenseFactors();
            GenerateTemperatureFactors();
            foreach (var key in FishBuff.Keys.ToList())
            {
                var tuple = FishBuff[key];
                FishBuff[key] = (tuple.Item1, tuple.Item2, tuple.Item3, tuple.Item4, tuple.Item5, MathUtils.Max(tuple.Item6 - dt, 0f));
            }
            foreach (var key2 in ThreePillBuff.ToList())
            {
                var tuple = ThreePillBuff[key2.Key];
                ThreePillBuff[key2.Key] = (MathUtils.Max(tuple.Item1 - dt, 0f), MathUtils.Max(tuple.Item2 - dt, 0f), MathUtils.Max(tuple.Item3 - dt, 0f));
            }
            var keysToRemove = FishBuff.Where(kvp => kvp.Value.Item6 == 0f).Select(kvp => kvp.Key).ToList();
            foreach (var key in keysToRemove)
            {
                FishBuff.Remove(key);
            }
            var keysToRemove2 = ThreePillBuff.Where(kvp => kvp.Value.Item1 == 0f && kvp.Value.Item2 == 0f && kvp.Value.Item3 == 0f).Select(kvp => kvp.Key).ToList();
            foreach (var key in keysToRemove2)
            {
                ThreePillBuff.Remove(key);
            }
        }

        public virtual void GenerateStrengthFactors()
        {
            Factor PlayerClassFactor = componentFactors.m_strengthFactors.Find(factor => (factor.Name == "PlayerClass"));
            Factor GameModeFactor = componentFactors.m_strengthFactors.Find(factor => (factor.Name == "GameMode"));
            Factor LevelFactor = componentFactors.m_strengthFactors.Find(factor => (factor.Name == "Level"));

            componentFactors.m_strengthFactors.Remove(PlayerClassFactor);
            componentFactors.m_strengthFactors.Remove(GameModeFactor);
            componentFactors.m_strengthFactors.Remove(LevelFactor);

            if (componentWoundInfection.IsEarlyStage)
            {
                componentFactors.m_strengthFactors.Add(new Factor
                {
                    Name = "IsEarlyStage",
                    Value = componentWoundInfection.IsEarlyStage ? -0.1f : 0f,
                    Description = LanguageControl.Get(fName, 1),
                    FactorAdditionType = FactorAdditionType.Add
                });
            }
            if (componentWoundInfection.IsAdvancedStage)
            {
                componentFactors.m_strengthFactors.Add(new Factor
                {
                    Name = "IsAdvancedStage",
                    Value = componentWoundInfection.IsAdvancedStage ? -0.2f : 0f,
                    Description = LanguageControl.Get(fName, 2),
                    FactorAdditionType = FactorAdditionType.Add
                });
            }
            if (componentWoundInfection.IsCriticalStage)
            {
                componentFactors.m_strengthFactors.Add(new Factor
                {
                    Name = "IsCriticalStage",
                    Value = componentWoundInfection.IsCriticalStage ? -0.4f : 0f,
                    Description = LanguageControl.Get(fName, 3),
                    FactorAdditionType = FactorAdditionType.Add
                });
            }
            componentFactors.m_strengthFactors.Add(new Factor
            {
                Name = "Level",
                Value = MathF.Pow(1.014f, componentPhysicalAttributes.Level - 1f - (float)Math.Floor(componentPhysicalAttributes.Level / 10f)) * MathF.Pow(1.2f, (float)Math.Floor(componentPhysicalAttributes.Level / 10f)),
                Description = LanguageControl.Get(fName, 4),
                FactorAdditionType = FactorAdditionType.Multiply
            });
            if (FishBuff != null && FishBuff.Any(kvp => kvp.Value.Item1 > 0))
            {
                foreach (var key in FishBuff.Keys.ToList())
                {
                    var tuple = FishBuff[key];
                    componentFactors.m_strengthFactors.Add(new Factor
                    {
                        Name = key + "Buff",
                        Value = tuple.Item1,
                        Description = key + "Buff",
                        FactorAdditionType = FactorAdditionType.Add
                    });
                }
            }
        }

        public virtual void GenerateResilienceFactors()
        {
            Factor PlayerClassFactor = componentFactors.m_resilienceFactors.Find(factor => (factor.Name == "PlayerClass"));
            Factor GameModeFactor = componentFactors.m_resilienceFactors.Find(factor => (factor.Name == "GameMode"));
            Factor LevelFactor = componentFactors.m_resilienceFactors.Find(factor => (factor.Name == "Level"));

            componentFactors.m_resilienceFactors.Remove(PlayerClassFactor);
            componentFactors.m_resilienceFactors.Remove(GameModeFactor);
            componentFactors.m_resilienceFactors.Remove(LevelFactor);

            if (componentWoundInfection.IsEarlyStage)
            {
                componentFactors.m_resilienceFactors.Add(new Factor
                {
                    Name = "IsEarlyStage",
                    Value = componentWoundInfection.IsEarlyStage ? -0.1f : 0f,
                    Description = LanguageControl.Get(fName, 1),
                    FactorAdditionType = FactorAdditionType.Add
                });
            }
            if (componentWoundInfection.IsAdvancedStage)
            {
                componentFactors.m_resilienceFactors.Add(new Factor
                {
                    Name = "IsAdvancedStage",
                    Value = componentWoundInfection.IsAdvancedStage ? -0.15f : 0f,
                    Description = LanguageControl.Get(fName, 2),
                    FactorAdditionType = FactorAdditionType.Add
                });
            }
            if (componentWoundInfection.IsCriticalStage)
            {
                componentFactors.m_resilienceFactors.Add(new Factor
                {
                    Name = "IsCriticalStage",
                    Value = componentWoundInfection.IsCriticalStage ? -0.3f : 0f,
                    Description = LanguageControl.Get(fName, 3),
                    FactorAdditionType = FactorAdditionType.Add
                });
            }
            componentFactors.m_resilienceFactors.Add(new Factor
            {
                Name = "Level",
                Value = MathF.Pow(1.0274f, componentPhysicalAttributes.Level - 1f - 2f * (float)Math.Floor(componentPhysicalAttributes.Level / 10f)) * MathF.Pow(1.0822f, (float)Math.Floor(componentPhysicalAttributes.Level / 10f)),
                Description = LanguageControl.Get(fName, 4),
                FactorAdditionType = FactorAdditionType.Multiply
            });
        }
        public virtual void GenerateSpeedFactors()
        {
            Factor PlayerClassFactor = componentFactors.m_speedFactors.Find(factor => (factor.Name == "PlayerClass"));
            Factor LevelFactor = componentFactors.m_speedFactors.Find(factor => (factor.Name == "Level"));

            componentFactors.m_speedFactors.Remove(PlayerClassFactor);
            componentFactors.m_speedFactors.Remove(LevelFactor);

            if (componentWoundInfection.IsEarlyStage)
            {
                componentFactors.m_speedFactors.Add(new Factor
                {
                    Name = "IsEarlyStage",
                    Value = componentWoundInfection.IsEarlyStage ? -0.1f : 0f,
                    Description = LanguageControl.Get(fName, 1),
                    FactorAdditionType = FactorAdditionType.Add
                });
            }
            if (componentWoundInfection.IsAdvancedStage)
            {
                componentFactors.m_speedFactors.Add(new Factor
                {
                    Name = "IsAdvancedStage",
                    Value = componentWoundInfection.IsAdvancedStage ? -0.15f : 0f,
                    Description = LanguageControl.Get(fName, 2),
                    FactorAdditionType = FactorAdditionType.Add
                });
            }
            if (componentWoundInfection.IsCriticalStage)
            {
                componentFactors.m_speedFactors.Add(new Factor
                {
                    Name = "IsCriticalStage",
                    Value = componentWoundInfection.IsCriticalStage ? -0.3f : 0f,
                    Description = LanguageControl.Get(fName, 3),
                    FactorAdditionType = FactorAdditionType.Add
                });
            }
            componentFactors.m_speedFactors.Add(new Factor
            {
                Name = "Level",
                Value = 1f + 0.0005f * MathF.Pow(componentPhysicalAttributes.Level, 2),
                Description = LanguageControl.Get(fName, 4),
                FactorAdditionType = FactorAdditionType.Multiply
            });
            for (int a = 0; a < componentTalent.TalentAttributes.Count; a++)
            {
                if (componentTalent.TalentAttributes[a].SpeedOfMovementIncreased > 0 && componentTalent.TalentAttributes[a].Field > 0)
                {
                    componentFactors.m_speedFactors.Add(new Factor
                    {
                        Name = "SpeedOfMovementIncreased",
                        Value = 1f + componentTalent.TalentAttributes[a].SpeedOfMovementIncreased + (componentTalent.TalentAttributes[a].Level - 1) * 0.015f,
                        Description = LanguageControl.Get(fName, 5),
                        FactorAdditionType = FactorAdditionType.Multiply
                    });

                }
            }
        }

        public virtual void GenerateHitRateFactors()
        {
            componentLevel.OtherFactors["HitRate"].Add(new Factor
            {
                Name = "Level",
                Value = 0.1f + (componentPhysicalAttributes.Level - 1f) * MathF.Pow(1.01f, (float)Math.Floor(componentPhysicalAttributes.Level / 10f)),
                Description = LanguageControl.Get(fName, 4),
                FactorAdditionType = FactorAdditionType.Add
            });
            if (FishBuff != null && FishBuff.Any(kvp => kvp.Value.Item3 > 0))
            {
                foreach (var key in FishBuff.Keys.ToList())
