                        Description = key + "Buff",
                        FactorAdditionType = FactorAdditionType.Add
                    });
                }
            }
        }

        public virtual void GenerateCriticalStrikeRateFactors()
        {
            componentLevel.OtherFactors["CriticalStrikeRate"].Add(new Factor
            {
                Name = "Level",
                Value = 0.1f + (componentPhysicalAttributes.Level - 1f) * MathF.Pow(1.01f, (float)Math.Floor(componentPhysicalAttributes.Level / 10f)),
                Description = LanguageControl.Get(fName, 4),
                FactorAdditionType = FactorAdditionType.Add
            });
        }

        public virtual void GenerateDodgeRateFactors()
        {
            componentLevel.OtherFactors["DodgeRate"].Add(new Factor
            {
                Name = "Level",
                Value = 0.1f + (componentPhysicalAttributes.Level - 1f) * MathF.Pow(1.01f, (float)Math.Floor(componentPhysicalAttributes.Level / 10f)),
                Description = LanguageControl.Get(fName, 4),
                FactorAdditionType = FactorAdditionType.Add
            });
            if (FishBuff != null && FishBuff.Any(kvp => kvp.Value.Item4 > 0))
            {
                foreach (var key in FishBuff.Keys.ToList())
                {
                    var tuple = FishBuff[key];
                    componentLevel.OtherFactors["DodgeRate"].Add(new Factor
                    {
                        Name = key + "Buff",
                        Value = tuple.Item4,
                        Description = key + "Buff",
                        FactorAdditionType = FactorAdditionType.Add
                    });
                }
            }
        }

        public virtual void GenerateIntelligenceFactors()
        {
            componentLevel.OtherFactors["Intelligence"].Add(new Factor
            {
                Name = "Level",
                Value = MathF.Pow(1.075f, (float)(componentPhysicalAttributes.Level - 1f)) * MathF.Pow(1.2f, (float)Math.Floor(componentPhysicalAttributes.Level / 10f)),
                Description = LanguageControl.Get(fName, 4),
                FactorAdditionType = FactorAdditionType.Multiply
            });
        }

        public virtual void GenerateDefenseFactors()
        {
            if (FishBuff != null && FishBuff.Any(kvp => kvp.Value.Item2 > 0))
            {
                foreach (var key in FishBuff.Keys.ToList())
                {
                    var tuple = FishBuff[key];
                    componentLevel.OtherFactors["Defense"].Add(new Factor
                    {
                        Name = key + "Buff",
                        Value = tuple.Item2,
                        Description = key + "Buff",
                        FactorAdditionType = FactorAdditionType.Add
                    });
                }
            }
        }

        public virtual void GenerateTemperatureFactors()
        {
            if (FishBuff != null && FishBuff.Any(kvp => kvp.Value.Item5 > 0))
            {
                foreach (var key in FishBuff.Keys.ToList())
                {
                    var tuple = FishBuff[key];
                    componentLevel.OtherFactors["Temperature"].Add(new Factor
                    {
                        Name = key + "Buff",
                        Value = tuple.Item5,
                        Description = key + "Buff",
                        FactorAdditionType = FactorAdditionType.Add
                    });
                }
            }
        }
    }
