    {
        public ComponentPlayer m_componentPlayer;
        public ComponentPhysicalAttributes componentPhysicalAttributes;
        public ComponentSkills componentSkills;

        public LabelWidget StrengthLabel;
        public LabelWidget AgilityLabel;
        public LabelWidget EnduranceLabel;
        public LabelWidget IntelligenceLabel;
        public LabelWidget LuckyLabel;
        public LabelWidget SpeedLabel;
        public BitmapButtonWidget SkillsButton;
        public LabelWidget SkillsLabel;
        public BevelledButtonWidget ReplaceButton;
        public ValueBarWidget LevelBar;
        public LabelWidget LevelLabel;

        public string Text;

        // 技能基础值和增量值数组
        public static readonly (float Base, float Increment)[] SkillValues = new[]
        {
            (25f, 12.5f),   // 0
            (30f, 15f),     // 1
            (15f, 7.5f),    // 2
            (4f, 2f),       // 3
            (22f, 11f),     // 4
            (18f, 9f),      // 5
            (20f, 10f),     // 6
            (36f, 18f),     // 7
            (30f, 15f),     // 8
            (18f, 9f),      // 9
            (120f, 60f),    // 10
            (120f, 60f),    // 11
            (7f, 3.5f),     // 12
            (3f, 1.5f),     // 13
            (40f, 20f),     // 14
            (100f, 50f),    // 15
            (90f, 45f)      // 16
        };

        public PlayerStatsWidget(ComponentPlayer componentPlayer)
        {
            m_componentPlayer = componentPlayer;
            componentPhysicalAttributes = m_componentPlayer.Entity.FindComponent<ComponentPhysicalAttributes>();
            componentSkills = m_componentPlayer.Entity.FindComponent<ComponentSkills>();
            XElement node = ContentManager.Get<XElement>("Widgets/PlayerStatsWidget");
            LoadContents(this, node);

            StrengthLabel = Children.Find<LabelWidget>("StrengthLabel");
            AgilityLabel = Children.Find<LabelWidget>("AgilityLabel");
            EnduranceLabel = Children.Find<LabelWidget>("EnduranceLabel");
            IntelligenceLabel = Children.Find<LabelWidget>("IntelligenceLabel");
            LuckyLabel = Children.Find<LabelWidget>("LuckyLabel");
            SpeedLabel = Children.Find<LabelWidget>("SpeedLabel");
            SkillsButton = Children.Find<BitmapButtonWidget>("SkillsButton");
            SkillsLabel = Children.Find<LabelWidget>("SkillsLabel");
            ReplaceButton = Children.Find<BevelledButtonWidget>("ReplaceButton");
            LevelBar = Children.Find<ValueBarWidget>("LevelBar");
            LevelLabel = Children.Find<LabelWidget>("LevelLabel");
        }

        public override void Update()
        {
            var extraAttributes = m_componentPlayer.Entity.FindComponent<ComponentExtraAttributes>();
            var locomotion = m_componentPlayer.ComponentLocomotion;
            var factors = m_componentPlayer.Entity.FindComponent<ComponentFactors>();

            StrengthLabel.Text = $"力量:{NumericalProcessingManager.NumericalProcessing((float)Math.Floor(componentPhysicalAttributes.Power))}";
            AgilityLabel.Text = $"敏捷:{NumericalProcessingManager.NumericalProcessing((float)Math.Floor(componentPhysicalAttributes.Agility))}";
            EnduranceLabel.Text = $"耐力:{NumericalProcessingManager.NumericalProcessing((float)Math.Floor(componentPhysicalAttributes.Endurance))}";
            IntelligenceLabel.Text = $"智力:{NumericalProcessingManager.NumericalProcessing((float)Math.Floor(componentPhysicalAttributes.Intelligence))}";
            LuckyLabel.Text = $"幸运:{NumericalProcessingManager.NumericalProcessing((float)Math.Floor(extraAttributes.CriticalStrikeRate * 5 + extraAttributes.CriticalStrikeMultiplier * 5f))}";
            SpeedLabel.Text = $"移速:{NumericalProcessingManager.NumericalProcessing((float)Math.Floor(locomotion.WalkSpeed * factors.SpeedFactor))}";

            LevelBar.Value = componentPhysicalAttributes.LevelAtPresent / componentPhysicalAttributes.LevelResistance;
            LevelLabel.Text = $"等级:{NumericalProcessingManager.NumericalProcessing(componentPhysicalAttributes.Level)} {NumericalProcessingManager.NumericalProcessing(componentPhysicalAttributes.LevelAtPresent)}/{NumericalProcessingManager.NumericalProcessing(componentPhysicalAttributes.LevelResistance)}";

            if (ReplaceButton.IsClicked)
            {
                DialogsManager.ShowDialog(null, new SkillsChoiceDialog(componentSkills));
            }

            for (int i = 0; i < componentSkills.SkillsAttributes.Count; i++)
            {
                var skill = componentSkills.SkillsAttributes[i];
                if (skill.Select)
                {
                    SkillsButton.NormalSubtexture = SkillsButton.ClickedSubtexture = ContentManager.Get<Texture2D>(skill.Texture);

                    if (i < SkillValues.Length)
                    {
                        var (baseValue, increment) = SkillValues[i];
                        float value = baseValue + (skill.Level - 1) * increment;
                        Text = string.Format(LanguageControl.Get("PlayerStatsWidget", i + 1), value);
                        SkillsLabel.Text = Text;
                    }
                    break;
                }
            }
        }
    }
}
//子系统经验方块行为
namespace Game
{
    public class SubsystemHYZLExperienceBlockBehavior : SubsystemExperienceBlockBehavior
    {
        public override void OnPickableGathered(Pickable pickable, ComponentPickableGatherer target, Vector3 distanceToTarget)
        {
            float distanceSquared = distanceToTarget.LengthSquared();
            if (!pickable.ToRemove && distanceSquared < pickable.DistanceToPick * pickable.DistanceToPick)
            {
                ComponentPhysicalAttributes componentPhysicalAttributes = target.Entity.FindComponent<ComponentPhysicalAttributes>();
                if (componentPhysicalAttributes != null)
                {
                    componentPhysicalAttributes.AddExperience(pickable.Count, true);
                    pickable.ToRemove = true;
                }
            }
        }
    }
}
//组件肠道感染
namespace Game
{
    public class ComponentIntestinalInfection : Component, IUpdateable
    {
        public SubsystemGameInfo m_subsystemGameInfo;
        public SubsystemTerrain m_subsystemTerrain;
        public SubsystemTime m_subsystemTime;
        public SubsystemAudio m_subsystemAudio;
        public SubsystemParticles m_subsystemParticles;
        public ComponentPlayer m_componentPlayer;

        public Random m_random = new();
        public static string fName = "ComponentIntestinalInfection";

        // 感染相关变量
        public float m_infectionOnset;
        public float m_infectionDuration;
        public float m_painDuration;
        public float m_dehydrationDuration;
        public float m_weaknessDuration;

        // 症状强度
        public float m_painIntensity;
        public float m_dehydrationLevel;
        public float m_weaknessFactor;

        public double m_lastEffectTime = -1000.0;
        public double m_lastPainTime = -1000.0;
        public double m_lastMessageTime = -1000.0;

        public bool HasInfection => m_infectionDuration > 0f;
        public bool IsInPain => m_painDuration > 0f;
        public bool IsDehydrated => m_dehydrationDuration > 0f;

        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public virtual void StartInfection()
        {
            m_infectionDuration = 1800f; // 30分钟感染期
            m_dehydrationLevel = 0.1f;
            m_weaknessFactor = 0.1f;

            m_subsystemTime.QueueGameTimeDelayedExecution(
                m_subsystemTime.GameTime + 15.0,
                delegate
                {
                    m_componentPlayer.ComponentVitalStats.MakeSleepy(0.3f);
                    m_componentPlayer.ComponentVitalStats.Food = MathUtils.Max(m_componentPlayer.ComponentVitalStats.Food - 0.2f, 0f);
                }
            );
            m_componentPlayer.ComponentGui.DisplaySmallMessage(
                                LanguageControl.Get(fName, 5), Color.Orange, true, true);
        }

        public virtual void TriggerPain()
        {
            m_lastPainTime = m_subsystemTime.GameTime;
            m_painDuration = 8f;
            m_painIntensity = 0.7f + m_random.Float() * 0.3f;

            // 疼痛声音
            m_componentPlayer.ComponentCreatureSounds.PlayPainSound();
            Project.FindSubsystem<SubsystemNoise>(true).MakeNoise(m_componentPlayer.ComponentBody.Position, 0.15f, 6f);
        }

        public virtual void TriggerDehydration()
        {
            m_dehydrationDuration = 120f; // 2分钟脱水效果
            m_dehydrationLevel = MathUtils.Min(m_dehydrationLevel + 0.15f, 1f);

            m_componentPlayer.ComponentVitalStats.Food = MathUtils.Max(
                m_componentPlayer.ComponentVitalStats.Food - 0.3f, 0f
            );
        }

        public virtual void Update(float dt)
        {
            if (m_subsystemGameInfo.WorldSettings.GameMode == GameMode.Creative
                || !m_subsystemGameInfo.WorldSettings.AreAdventureSurvivalMechanicsEnabled)
            {
                ResetInfection();
                return;
            }

            UpdateInfectionProgress(dt);
            UpdateSymptoms(dt);
            UpdateScreenEffects(dt); // 新增：更新屏幕效果
        }

        public void ResetInfection()
        {
            if (m_subsystemGameInfo.WorldSettings.GameMode != GameMode.Creative)
            {
                m_componentPlayer.ComponentGui.DisplaySmallMessage(
                                    LanguageControl.Get(fName, 6), Color.Green, true, true);
            }
            m_infectionDuration = 0f;
            m_infectionOnset = 0f;
            m_painIntensity = 0f;
            m_dehydrationLevel = 0f;
            m_weaknessFactor = 0f;

            // 重置屏幕效果
            m_componentPlayer.ComponentScreenOverlays.BlackoutFactor = 0f;
            m_componentPlayer.ComponentScreenOverlays.RedoutFactor = 0f;
        }

        public void UpdateInfectionProgress(float dt)
        {
            if (m_infectionDuration > 0f)
            {
                UpdateActiveInfection(dt);
            }
        }

        public void UpdateActiveInfection(float dt)
        {
            m_infectionOnset = 0f;

            // 环境因素影响恢复速度
            float recoveryRate = CalculateRecoveryRate();
            m_infectionDuration = MathUtils.Max(m_infectionDuration - recoveryRate * dt, 0f);

            // 定期触发症状
            if (m_componentPlayer.ComponentHealth.Health > 0f
                && !m_componentPlayer.ComponentSleep.IsSleeping
                && m_subsystemTime.PeriodicGameTimeEvent(8.0, -0.01)
                && m_subsystemTime.GameTime - m_lastEffectTime > 20.0)
            {
                InfectionEffect();
            }
        }

        public float CalculateRecoveryRate()
        {
            float baseRate = 1f;

            // 营养状态影响恢复
            if (m_componentPlayer.ComponentVitalStats.Food < 0.4f)
            {
                baseRate *= 0.7f;
            }

            // 休息状态影响恢复
            if (m_componentPlayer.ComponentSleep.IsSleeping)
            {
                baseRate *= 1.5f;
            }

            return baseRate;
        }

        public void UpdateSymptoms(float dt)
        {
            if ((m_painDuration > 0f || m_dehydrationDuration > 0f)
                && m_componentPlayer.ComponentHealth.Health > 0f
                && !m_componentPlayer.ComponentSleep.IsSleeping)
            {

                UpdatePainEffect(dt);
                UpdateDehydrationEffect(dt);
                UpdateWeaknessEffect(dt);
            }
        }

        public void UpdatePainEffect(float dt)
        {
            m_painDuration = MathUtils.Max(m_painDuration - dt, 0f);

            // 疼痛导致的屏幕抖动和移动困难
            if (m_painDuration > 0f)
            {
                m_subsystemAudio.PlayRandomSound("Audio/Status/SeverePain", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
                float painShake = MathUtils.DegToRad(
                    MathUtils.Lerp(-10f, -25f,
                        SimplexNoise.Noise(3f * (float)MathUtils.Remainder(m_subsystemTime.GameTime, 10000.0)) * m_painIntensity
                    )
                );

                m_componentPlayer.ComponentLocomotion.LookOrder = new Vector2(
                    m_componentPlayer.ComponentLocomotion.LookOrder.X,
                    Math.Clamp(painShake - m_componentPlayer.ComponentLocomotion.LookAngles.Y, -2f, 2f)
                );

                // 疼痛导致的移动障碍
                if (m_random.Bool(3f * dt * m_painIntensity))
                {
                    m_componentPlayer.ComponentBody.ApplyImpulse(
                        -0.8f * m_painIntensity * m_componentPlayer.ComponentCreatureModel.EyeRotation.GetForwardVector()
                    );
                }
            }
        }

        public void UpdateDehydrationEffect(float dt)
        {
            m_dehydrationDuration = MathUtils.Max(m_dehydrationDuration - dt, 0f);

            // 脱水导致的持续口渴
            if (m_dehydrationDuration > 0f)
            {
                m_subsystemAudio.PlaySound("Audio/Status/Dehydration", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
                m_componentPlayer.ComponentVitalStats.Food = MathUtils.Max(
                    m_componentPlayer.ComponentVitalStats.Food - 0.05f * m_dehydrationLevel * dt, 0f
                );
            }
        }

        public void UpdateWeaknessEffect(float dt)
        {
            m_weaknessDuration = MathUtils.Max(m_weaknessDuration - dt, 0f);
            m_weaknessFactor = MathUtils.Lerp(m_weaknessFactor,
                m_infectionDuration > 0f ? 0.3f : 0f, dt * 0.1f);

            // 虚弱导致的移动速度降低
            m_subsystemAudio.PlaySound("Audio/Status/Weakness", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
            m_componentPlayer.ComponentLocomotion.WalkSpeed =
                1f - m_weaknessFactor * 0.6f;
        }

        // 新增：更新屏幕视觉效果
        public void UpdateScreenEffects(float dt)
        {
            if (m_componentPlayer.ComponentHealth.Health > 0f && !m_componentPlayer.ComponentSleep.IsSleeping)
            {
                // 根据脱水程度和疼痛强度计算黑屏系数（眩晕效果）
                float targetBlackout = 0f;
                if (m_dehydrationLevel > 0.5f)
                {
                    // 严重脱水时出现黑屏效果（眩晕）
                    m_subsystemAudio.PlaySound("Audio/Status/Dizziness", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
                    targetBlackout = MathUtils.Min((m_dehydrationLevel - 0.5f) * 0.8f, 0.6f);
                }
                if (m_painDuration > 0f)
                {
                    // 疼痛时增加黑屏效果
                    targetBlackout = MathUtils.Max(targetBlackout, m_painIntensity * 0.3f);
                }

                // 平滑过渡黑屏效果
                m_componentPlayer.ComponentScreenOverlays.BlackoutFactor = MathUtils.Lerp(
                    m_componentPlayer.ComponentScreenOverlays.BlackoutFactor,
                    targetBlackout,
                    dt * 2f
                );

                // 根据健康状况和脱水程度计算红屏系数（生命危险警告）
                float targetRedout = 0f;
                if (m_componentPlayer.ComponentHealth.Health < 0.3f)
                {
                    // 低生命值时红屏效果
                    targetRedout = MathUtils.Min((0.3f - m_componentPlayer.ComponentHealth.Health) * 2f, 0.5f);
                }
                if (m_dehydrationLevel > 0.7f && m_componentPlayer.ComponentVitalStats.Food < 0.2f)
                {
                    // 严重脱水和饥饿时红屏效果
                    targetRedout = MathUtils.Max(targetRedout, 0.4f);
                }

                // 疼痛发作时短暂增强红屏效果
                if (m_subsystemTime.GameTime - m_lastPainTime < 3.0)
                {
                    targetRedout = MathUtils.Max(targetRedout, 0.6f);
                }

                // 平滑过渡红屏效果
                m_componentPlayer.ComponentScreenOverlays.RedoutFactor = MathUtils.Lerp(
                    m_componentPlayer.ComponentScreenOverlays.RedoutFactor,
                    targetRedout,
                    dt * 3f
                );
            }
            else
            {
                // 玩家死亡或睡觉时清除屏幕效果
                m_componentPlayer.ComponentScreenOverlays.BlackoutFactor = 0f;
                m_componentPlayer.ComponentScreenOverlays.RedoutFactor = 0f;
            }
        }

        public virtual void InfectionEffect()
        {
            m_lastEffectTime = m_subsystemTime.GameTime;

            // 严重程度基于健康状况
            float severity = 1f - m_componentPlayer.ComponentHealth.Health;

            // 疼痛发作
            if (m_painDuration == 0f && (m_subsystemTime.GameTime - m_lastPainTime > 60.0 || m_random.Bool(0.7f)))
            {
                TriggerPain();
            }

            // 脱水效果
            if (m_random.Bool(0.4f))
            {
                TriggerDehydration();
            }

            // 健康损害
            float damage = MathUtils.Min(0.08f, m_componentPlayer.ComponentHealth.Health - 0.15f);
            if (damage > 0f)
            {
                m_subsystemTime.QueueGameTimeDelayedExecution(
                    m_subsystemTime.GameTime + 1.0,
                    delegate
                    {
                        m_componentPlayer.ComponentHealth.Injure(damage, null, false, LanguageControl.Get(fName, 4));
                    }
                );
            }

            // 显示症状消息
            if (Time.FrameStartTime - m_lastMessageTime > 30.0)
            {
                m_lastMessageTime = Time.FrameStartTime;
                ShowSymptomMessage();
            }
        }

        public void ShowSymptomMessage()
        {
            m_subsystemTime.QueueGameTimeDelayedExecution(
                m_subsystemTime.GameTime + 1.0,
                delegate
                {
                    string[] symptomMessages = {
                        LanguageControl.Get(fName, 1), // "腹部剧烈疼痛..."
                        LanguageControl.Get(fName, 2), // "感到虚弱无力..."
                        LanguageControl.Get(fName, 3)  // "严重脱水..."
                    };
                    string message = symptomMessages[m_random.Int(0, symptomMessages.Length - 1)];
                    m_componentPlayer.ComponentGui.DisplaySmallMessage(message, Color.LightYellow, true, true);
                }
            );
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            m_subsystemGameInfo = Project.FindSubsystem<SubsystemGameInfo>(true);
            m_subsystemTerrain = Project.FindSubsystem<SubsystemTerrain>(true);
            m_subsystemTime = Project.FindSubsystem<SubsystemTime>(true);
            m_subsystemAudio = Project.FindSubsystem<SubsystemAudio>(true);
            m_subsystemParticles = Project.FindSubsystem<SubsystemParticles>(true);
            m_componentPlayer = Entity.FindComponent<ComponentPlayer>(true);

            m_infectionDuration = valuesDictionary.GetValue<float>("InfectionDuration");
            m_infectionOnset = valuesDictionary.GetValue<float>("InfectionOnset");
            m_dehydrationLevel = valuesDictionary.GetValue<float>("DehydrationLevel");
        }

        public override void Save(ValuesDictionary valuesDictionary, EntityToIdMap entityToIdMap)
        {
            valuesDictionary.SetValue("InfectionDuration", m_infectionDuration);
            valuesDictionary.SetValue("InfectionOnset", m_infectionOnset);
            valuesDictionary.SetValue("DehydrationLevel", m_dehydrationLevel);
        }
    }
}
//组件四脚爬行模型动画
namespace Game
{
    public class ComponentFourLeggedReptileModel : ComponentCreatureModel
    {
        public enum Gait
        {
            Crawl,      // 爬行 - 用于鳄龟、鳄鱼等
            Walk,       // 行走 - 通用四足行走
            Trot,       // 小跑 - 用于蜥蜴、火蜥蜴
            Gallop      // 奔跑 - 用于快速移动
        }

        public SubsystemAudio m_subsystemAudio;
        public SubsystemSoundMaterials m_subsystemSoundMaterials;

        // 骨骼引用
        public ModelBone m_bodyBone;
        public ModelBone m_neckBone;
        public ModelBone m_headBone;
        public ModelBone m_leg1Bone;  // 左前腿
        public ModelBone m_leg2Bone;  // 左后腿  
        public ModelBone m_leg3Bone;  // 右前腿
        public ModelBone m_leg4Bone;  // 右后腿

        // 动画参数
        public float m_walkAnimationSpeed;
        public float m_crawlAnimationSpeed;
        public float m_gallopAnimationSpeed;
        public float m_frontLegsAngle;
        public float m_hindLegsAngle;
        public float m_bodySwingAmplitude;
        public float m_bodyBobHeight;
        public float m_tailSwingAmplitude;
        public bool m_hasTailAnimation;
        public bool m_canGallop;
        public bool m_canTrot;
        public bool m_isAquatic;

        // 动画状态
        public Gait m_gait;
        public float m_feedFactor;
        public float m_attackFactor;
        public float m_attackPhase;
        public float m_movementPhase;
        public float m_legAngle1;
        public float m_legAngle2;
        public float m_legAngle3;
        public float m_legAngle4;
        public float m_bodySwing;
        public float m_headAngleY;
        public float m_tailAngle;

        public override float AttackPhase
        {
            get => m_attackPhase;
            set => m_attackPhase = value;
        }

        public override float AttackFactor
        {
            get => m_attackFactor;
            set => m_attackFactor = value;
        }

        public override void Update(float dt)
        {
            // 计算移动速度
            float speed = m_componentCreature.ComponentLocomotion.SlipSpeed
                ?? Vector3.Dot(m_componentCreature.ComponentBody.Velocity, m_componentCreature.ComponentBody.Matrix.Forward);

            // 根据速度选择步态
            float walkSpeed = m_componentCreature.ComponentLocomotion.WalkSpeed;
            if (m_canGallop && speed > 0.8f * walkSpeed)
            {
                m_gait = Gait.Gallop;
                m_movementPhase += speed * dt * m_gallopAnimationSpeed;
            }
            else if (m_canTrot && speed > 0.5f * walkSpeed)
            {
                m_gait = Gait.Trot;
                m_movementPhase += speed * dt * m_walkAnimationSpeed * 1.5f;
            }
            else if (MathF.Abs(speed) > 0.1f)
            {
                // 低速时使用爬行，中速时使用行走
                if (speed > 0.3f * walkSpeed)
                {
                    m_gait = Gait.Walk;
                    m_movementPhase += speed * dt * m_walkAnimationSpeed;
                }
                else
                {
                    m_gait = Gait.Crawl;
                    m_movementPhase += speed * dt * m_crawlAnimationSpeed;
                }
            }
            else
            {
                m_gait = Gait.Crawl;
                m_movementPhase = 0f;
            }

            // 身体摆动和起伏
            float targetBodySwing = 0f;
            float targetBob = 0f;

            switch (m_gait)
            {
                case Gait.Crawl:
                    targetBodySwing = m_bodySwingAmplitude * 0.3f * MathF.Sin(MathF.PI * 2f * m_movementPhase);
                    targetBob = m_bodyBobHeight * 0.2f * MathF.Sin(MathF.PI * 4f * m_movementPhase);
                    break;
                case Gait.Walk:
                    targetBodySwing = m_bodySwingAmplitude * 0.6f * MathF.Sin(MathF.PI * 2f * m_movementPhase);
                    targetBob = m_bodyBobHeight * 0.8f * MathF.Sin(MathF.PI * 4f * m_movementPhase);
                    break;
                case Gait.Trot:
                    targetBodySwing = m_bodySwingAmplitude * 0.8f * MathF.Sin(MathF.PI * 4f * m_movementPhase);
                    targetBob = m_bodyBobHeight * 1.2f * MathF.Sin(MathF.PI * 8f * m_movementPhase);
                    break;
                case Gait.Gallop:
                    targetBodySwing = m_bodySwingAmplitude * 1.5f * MathF.Sin(MathF.PI * 3f * m_movementPhase);
                    targetBob = m_bodyBobHeight * 2f * MathF.Sin(MathF.PI * 6f * m_movementPhase);
                    break;
            }

            // 平滑插值
            float smoothFactor = MathUtils.Min(12f * dt, 1f);
            m_bodySwing += smoothFactor * (targetBodySwing - m_bodySwing);
            Bob += smoothFactor * (targetBob - Bob);

            // 尾巴摆动
            if (m_hasTailAnimation)
            {
                float targetTailAngle = m_tailSwingAmplitude * MathF.Sin(MathF.PI * 2f * m_movementPhase * 0.5f);
                m_tailAngle += smoothFactor * (targetTailAngle - m_tailAngle);
            }

            // 脚步声
            if (m_movementPhase > MathF.Floor(m_movementPhase) && m_movementPhase - dt <= MathF.Floor(m_movementPhase))
            {
                m_componentCreature.ComponentCreatureSounds.PlayFootstepSound(1f);
            }

            // 喂食动画
            m_feedFactor = FeedOrder ?
                MathUtils.Min(m_feedFactor + 2f * dt, 1f) :
                MathUtils.Max(m_feedFactor - 2f * dt, 0f);

            // 攻击动画
            IsAttackHitMoment = false;
            if (AttackOrder)
            {
                m_attackFactor = MathUtils.Min(m_attackFactor + 4f * dt, 1f);
                float oldPhase = m_attackPhase;
                m_attackPhase = MathUtils.Remainder(m_attackPhase + dt * 3f, 1f);
                if (oldPhase < 0.3f && m_attackPhase >= 0.3f)
                {
                    IsAttackHitMoment = true;
                }
            }
            else
            {
                m_attackFactor = MathUtils.Max(m_attackFactor - 4f * dt, 0f);
                if (m_attackPhase > 0f)
                {
                    m_attackPhase = MathUtils.Max(m_attackPhase - dt * 2f, 0f);
                }
            }

            FeedOrder = false;
            AttackOrder = false;
            base.Update(dt);
        }

        public override void AnimateCreature()
        {
            Vector3 position = m_componentCreature.ComponentBody.Position;
            Vector3 rotation = m_componentCreature.ComponentBody.Rotation.ToYawPitchRoll();

            if (m_componentCreature.ComponentHealth.Health > 0f)
            {
                AnimateAliveCreature(position, rotation);
            }
            else
            {
                AnimateDeadCreature(position, rotation);
            }
        }

        public void AnimateAliveCreature(Vector3 position, Vector3 rotation)
        {
            // 计算腿部角度
            float leg1Angle = 0f, leg2Angle = 0f, leg3Angle = 0f, leg4Angle = 0f;
            float headSwing = 0f;

            if (m_movementPhase != 0f && (m_componentCreature.ComponentBody.StandingOnValue.HasValue || m_componentCreature.ComponentBody.ImmersionFactor > 0f))
            {
                switch (m_gait)
                {
                    case Gait.Crawl:
                        // 爬行步态：对角线同步
                        leg1Angle = m_frontLegsAngle * MathF.Sin(MathF.PI * 2f * (m_movementPhase + 0.0f));
                        leg2Angle = m_hindLegsAngle * MathF.Sin(MathF.PI * 2f * (m_movementPhase + 0.5f));
                        leg3Angle = m_frontLegsAngle * MathF.Sin(MathF.PI * 2f * (m_movementPhase + 0.5f));
                        leg4Angle = m_hindLegsAngle * MathF.Sin(MathF.PI * 2f * (m_movementPhase + 0.0f));
                        headSwing = MathUtils.DegToRad(2f) * MathF.Sin(MathF.PI * 4f * m_movementPhase);
                        break;

                    case Gait.Walk:
                        // 行走步态：四拍步态
                        leg1Angle = m_frontLegsAngle * MathF.Sin(MathF.PI * 2f * (m_movementPhase + 0.0f));
                        leg2Angle = m_hindLegsAngle * MathF.Sin(MathF.PI * 2f * (m_movementPhase + 0.5f));
                        leg3Angle = m_frontLegsAngle * MathF.Sin(MathF.PI * 2f * (m_movementPhase + 0.75f));
                        leg4Angle = m_hindLegsAngle * MathF.Sin(MathF.PI * 2f * (m_movementPhase + 0.25f));
                        headSwing = MathUtils.DegToRad(3f) * MathF.Sin(MathF.PI * 4f * m_movementPhase);
                        break;

                    case Gait.Trot:
                        // 小跑步态：对角线同步
                        leg1Angle = m_frontLegsAngle * 1.2f * MathF.Sin(MathF.PI * 2f * (m_movementPhase + 0.0f));
                        leg2Angle = m_hindLegsAngle * 1.2f * MathF.Sin(MathF.PI * 2f * (m_movementPhase + 0.5f));
                        leg3Angle = m_frontLegsAngle * 1.2f * MathF.Sin(MathF.PI * 2f * (m_movementPhase + 0.5f));
                        leg4Angle = m_hindLegsAngle * 1.2f * MathF.Sin(MathF.PI * 2f * (m_movementPhase + 0.0f));
                        headSwing = MathUtils.DegToRad(5f) * MathF.Sin(MathF.PI * 4f * m_movementPhase);
                        break;

                    case Gait.Gallop:
                        // 奔跑步态：前后腿同步
                        leg1Angle = m_frontLegsAngle * 1.8f * MathF.Sin(MathF.PI * 2f * (m_movementPhase + 0.0f));
                        leg2Angle = m_hindLegsAngle * 1.8f * MathF.Sin(MathF.PI * 2f * (m_movementPhase + 0.0f));
                        leg3Angle = m_frontLegsAngle * 1.8f * MathF.Sin(MathF.PI * 2f * (m_movementPhase + 0.5f));
                        leg4Angle = m_hindLegsAngle * 1.8f * MathF.Sin(MathF.PI * 2f * (m_movementPhase + 0.5f));
                        headSwing = MathUtils.DegToRad(8f) * MathF.Sin(MathF.PI * 6f * m_movementPhase);
                        break;
                }
            }

            // 平滑腿部角度过渡
            float smoothFactor = MathUtils.Min(12f * m_subsystemTime.GameTimeDelta, 1f);
            m_legAngle1 += smoothFactor * (leg1Angle - m_legAngle1);
            m_legAngle2 += smoothFactor * (leg2Angle - m_legAngle2);
            m_legAngle3 += smoothFactor * (leg3Angle - m_legAngle3);
            m_legAngle4 += smoothFactor * (leg4Angle - m_legAngle4);
            m_headAngleY += smoothFactor * (headSwing - m_headAngleY);

            // 头部朝向控制
            Vector2 lookAngles = m_componentCreature.ComponentLocomotion.LookAngles;
            lookAngles.Y += m_headAngleY;
            lookAngles.X = Math.Clamp(lookAngles.X, -MathUtils.DegToRad(65f), MathUtils.DegToRad(65f));
            lookAngles.Y = Math.Clamp(lookAngles.Y, -MathUtils.DegToRad(55f), MathUtils.DegToRad(55f));

            // 颈部骨骼分担头部旋转
            Vector2 neckAngles = Vector2.Zero;
            if (m_neckBone != null)
            {
                neckAngles = 0.6f * lookAngles;
                lookAngles = 0.4f * lookAngles;
            }

            // 喂食动画
            if (m_feedFactor > 0f)
            {
                float feedHeadAngle = -MathUtils.DegToRad(25f + 45f * SimplexNoise.OctavedNoise((float)m_subsystemTime.GameTime, 3f, 2, 2f, 0.75f));
                lookAngles = Vector2.Lerp(lookAngles, new Vector2(0f, feedHeadAngle), m_feedFactor);
            }

            // 攻击动画
            if (m_attackFactor > 0f)
            {
                float attackHeadAngle = -MathUtils.DegToRad(40f) * MathF.Sin(MathF.PI * 2f * MathUtils.Sigmoid(m_attackPhase, 4f));
                lookAngles = Vector2.Lerp(lookAngles, new Vector2(0f, attackHeadAngle), m_attackFactor);
            }

            // 设置骨骼变换
            Matrix bodyTransform = Matrix.CreateRotationY(rotation.X + m_bodySwing)
                                * Matrix.CreateTranslation(position.X, position.Y + Bob, position.Z);

            SetBoneTransform(m_bodyBone.Index, bodyTransform);
            SetBoneTransform(m_headBone.Index, Matrix.CreateRotationX(lookAngles.Y) * Matrix.CreateRotationZ(-lookAngles.X));

            if (m_neckBone != null)
            {
                SetBoneTransform(m_neckBone.Index, Matrix.CreateRotationX(neckAngles.Y) * Matrix.CreateRotationZ(-neckAngles.X));
            }

            // 腿部变换
            SetBoneTransform(m_leg1Bone.Index, Matrix.CreateRotationX(m_legAngle1));
            SetBoneTransform(m_leg2Bone.Index, Matrix.CreateRotationX(m_legAngle2));
            SetBoneTransform(m_leg3Bone.Index, Matrix.CreateRotationX(m_legAngle3));
            SetBoneTransform(m_leg4Bone.Index, Matrix.CreateRotationX(m_legAngle4));

            // 尾巴变换（如果有）
            if (m_hasTailAnimation)
            {
                // 假设有一个尾巴骨骼
                ModelBone tailBone = Model.FindBone("Tail", false);
                if (tailBone != null)
                {
                    SetBoneTransform(tailBone.Index, Matrix.CreateRotationY(m_tailAngle));
                }
            }
        }

        public void AnimateDeadCreature(Vector3 position, Vector3 rotation)
        {
            float deathFactor = 1f - DeathPhase;
            float sideFactor = Vector3.Dot(m_componentFrame.Matrix.Right, DeathCauseOffset) > 0f ? 1 : -1;
            float bodyHeight = m_componentCreature.ComponentBody.BoundingBox.Max.Y - m_componentCreature.ComponentBody.BoundingBox.Min.Y;

            Matrix bodyTransform = Matrix.CreateTranslation(-0.5f * bodyHeight * Vector3.UnitY * DeathPhase)
                                * Matrix.CreateFromYawPitchRoll(rotation.X, 0f, MathF.PI / 2f * DeathPhase * sideFactor)
                                * Matrix.CreateTranslation(0.2f * bodyHeight * Vector3.UnitY * DeathPhase)
                                * Matrix.CreateTranslation(position);

            SetBoneTransform(m_bodyBone.Index, bodyTransform);
            SetBoneTransform(m_headBone.Index, Matrix.CreateRotationX(MathUtils.DegToRad(50f) * DeathPhase));

            if (m_neckBone != null)
            {
                SetBoneTransform(m_neckBone.Index, Matrix.Identity);
            }

            // 死亡时腿部松弛
            SetBoneTransform(m_leg1Bone.Index, Matrix.CreateRotationX(m_legAngle1 * deathFactor));
            SetBoneTransform(m_leg2Bone.Index, Matrix.CreateRotationX(m_legAngle2 * deathFactor));
            SetBoneTransform(m_leg3Bone.Index, Matrix.CreateRotationX(m_legAngle3 * deathFactor));
            SetBoneTransform(m_leg4Bone.Index, Matrix.CreateRotationX(m_legAngle4 * deathFactor));
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            m_subsystemAudio = Project.FindSubsystem<SubsystemAudio>(true);
            m_subsystemSoundMaterials = Project.FindSubsystem<SubsystemSoundMaterials>(true);

            m_walkAnimationSpeed = valuesDictionary.GetValue<float>("WalkAnimationSpeed");
            m_crawlAnimationSpeed = valuesDictionary.GetValue<float>("CrawlAnimationSpeed");
            m_gallopAnimationSpeed = valuesDictionary.GetValue<float>("GallopAnimationSpeed");
            m_frontLegsAngle = valuesDictionary.GetValue<float>("FrontLegsAngle");
            m_hindLegsAngle = valuesDictionary.GetValue<float>("HindLegsAngle");
            m_bodySwingAmplitude = valuesDictionary.GetValue<float>("BodySwingAmplitude");
            m_bodyBobHeight = valuesDictionary.GetValue<float>("BodyBobHeight");
            m_tailSwingAmplitude = valuesDictionary.GetValue<float>("TailSwingAmplitude");
            m_hasTailAnimation = valuesDictionary.GetValue<bool>("HasTailAnimation");
            m_canGallop = valuesDictionary.GetValue<bool>("CanGallop");
            m_canTrot = valuesDictionary.GetValue<bool>("CanTrot");
            m_isAquatic = valuesDictionary.GetValue<bool>("IsAquatic");
        }

        public override void SetModel(Model model)
        {
            base.SetModel(model);
            if (IsSet) return;

            if (Model != null)
            {
                m_bodyBone = Model.FindBone("Body");
                m_neckBone = Model.FindBone("Neck", false);
                m_headBone = Model.FindBone("Head");
                m_leg1Bone = Model.FindBone("Leg1");
                m_leg2Bone = Model.FindBone("Leg2");
                m_leg3Bone = Model.FindBone("Leg3");
                m_leg4Bone = Model.FindBone("Leg4");
            }
            else
            {
                m_bodyBone = m_neckBone = m_headBone = null;
                m_leg1Bone = m_leg2Bone = m_leg3Bone = m_leg4Bone = null;
            }
        }
    }
}
