//配方获取
namespace Game
{
    public class CraftingHYZLRecipe
    {
        public int MaxSize = 3;
        public string Type;
        public string ResultType;
        public string ResultValue;
        public int ResultCount;
        public int RequiredTableLevel;
        public int RequiredCookingTableLevel;
        public int RequiredMedicineStationLevel;
        public bool MechanicalPuppetParts;
        public string Description;
        public string Message;
        public int TimeConsuming;
        public int WaitingTime;
        public int DisplayOrder = 0;

        /// <summary>
        /// 配方材料字典：key=材料ID，value=所需数量
        /// </summary>
        public Dictionary<string, int> Ingredients = new Dictionary<string, int>();
    }

    public static class CraftingHYZLRecipesManager
    {
        public static int Index = 0;
        public static List<CraftingHYZLRecipe> m_recipes = new List<CraftingHYZLRecipe>();
        public static List<CraftingHYZLRecipe> Recipes => m_recipes;
        public static string fName = "CraftingHYZLRecipesManager";
        public static bool EnableLevelRestrictions = true;

        public static void Initialize()
        {
            if (Index == 0)
            {
                // 从XML文件加载配方数据
                XElement recipesRoot = ContentManager.Get<XElement>("CraftingHYZLRecipes");

                foreach (XElement recipeElement in recipesRoot.Descendants("Recipe"))
                {
                    try
                    {
                        CraftingHYZLRecipe recipe = DecodeRecipeElement(recipeElement);
                        if (recipe != null)
                        {
                            m_recipes.Add(recipe);
                            Index++;
                        }
                    }
                    catch (Exception ex)
                    {
                        Log.Error($"Failed to load recipe: {ex.Message}");
                    }
                }

                // 获取方块的过程配方
                Block[] blocks = BlocksManager.Blocks;
                foreach (Block block in blocks)
                {
                    var proceduralRecipes = block.GetProceduralCraftingRecipes();
                    foreach (var recipe in proceduralRecipes)
                    {
                        var hyzlRecipe = ConvertToHYZLRecipe(recipe);
                        if (hyzlRecipe != null)
                        {
                            m_recipes.Add(hyzlRecipe);
                        }
                    }
                }

                // 调用Mod钩子
                bool sort = true;

                // 排序配方
                if (sort)
                {
                    m_recipes.Sort((r1, r2) =>
                    {
                        if (r1.DisplayOrder == r2.DisplayOrder)
                        {
                            return Comparer<int>.Default.Compare(r1.Ingredients.Count, r2.Ingredients.Count);
                        }
                        return Comparer<int>.Default.Compare(r1.DisplayOrder, r2.DisplayOrder);
                    });
                }

                Log.Information($"Loaded {Index} crafting recipes");
            }
        }

        public static CraftingHYZLRecipe DecodeElementToHYZLRecipe(XElement item)
        {
            CraftingHYZLRecipe recipe = new CraftingHYZLRecipe();

            // 解析结果物品
            if (!string.IsNullOrEmpty(XmlUtils.GetAttributeValue<string>(item, "Type", null)))
            {
                recipe.Type = XmlUtils.GetAttributeValue<string>(item, "Type");
            }
            if (!string.IsNullOrEmpty(XmlUtils.GetAttributeValue<string>(item, "ResultType", null)))
            {
                recipe.ResultType = XmlUtils.GetAttributeValue<string>(item, "ResultType");
            }
            recipe.ResultValue = XmlUtils.GetAttributeValue<string>(item, "ResultValue");
            recipe.ResultCount = XmlUtils.GetAttributeValue<int>(item, "ResultCount");

            // 解析描述
            string desc = XmlUtils.GetAttributeValue<string>(item, "Description");
            if (desc.StartsWith('[') && desc.EndsWith(']') &&
                LanguageControl.TryGetBlock(recipe.ResultValue, $"CRDescription:{desc.Substring(1, desc.Length - 2)}", out string r))
            {
                desc = r;
            }
            recipe.Description = desc;

            // 解析其他属性
            recipe.Message = XmlUtils.GetAttributeValue<string>(item, "Message", null);
            recipe.DisplayOrder = XmlUtils.GetAttributeValue(item, "DisplayOrder", 0);
            recipe.RequiredTableLevel = XmlUtils.GetAttributeValue(item, "RequiredTableLevel", 0);
            recipe.RequiredCookingTableLevel = XmlUtils.GetAttributeValue(item, "RequiredCookingTableLevel", 0);
            recipe.RequiredMedicineStationLevel = XmlUtils.GetAttributeValue(item, "RequiredMedicineStationLevel", 0);
            recipe.MechanicalPuppetParts = XmlUtils.GetAttributeValue(item, "MechanicalPuppetParts", false);

            recipe.TimeConsuming = XmlUtils.GetAttributeValue(item, "TimeConsuming", 0);
            recipe.WaitingTime = XmlUtils.GetAttributeValue(item, "WaitingTime", 0);

            // 解析材料 (a-z 和 acount-zcount)
            for (char c = 'a'; c <= 'z'; c++)
            {
                string ingredientKey = c.ToString();
                string countKey = c + "count";

                string ingredientValue = XmlUtils.GetAttributeValue<string>(item, ingredientKey, null);
                int ingredientCount = XmlUtils.GetAttributeValue(item, countKey, 1);

                if (!string.IsNullOrEmpty(ingredientValue))
                {
                    DecodeIngredient(ingredientValue, out string craftingId, out int? data);

                    // 验证材料是否存在
                    if (BlocksManager.FindBlocksByCraftingId(craftingId).Length == 0)
                    {
                        throw new InvalidOperationException($"Block with craftingId \"{ingredientValue}\" not found.");
                    }

                    if (data.HasValue && (data.Value < 0 || data.Value > 262143))
                    {
                        throw new InvalidOperationException($"Data in recipe ingredient \"{ingredientValue}\" must be between 0 and 0x3FFFF.");
                    }

                    // 生成完整的材料ID（包含数据值）
                    string fullIngredientId = craftingId;
                    if (data.HasValue)
                    {
                        fullIngredientId += ":" + data.Value;
                    }

                    // 添加到材料字典
                    if (recipe.Ingredients.ContainsKey(fullIngredientId))
                    {
                        recipe.Ingredients[fullIngredientId] += ingredientCount;
                    }
                    else
                    {
                        recipe.Ingredients[fullIngredientId] = ingredientCount;
                    }
                }
            }

            return recipe;
        }

        public static CraftingHYZLRecipe FindMatchingRecipe(SubsystemTerrain terrain, Dictionary<string, int> inputIngredients, float heatLevel, float playerLevel)
        {
            if (inputIngredients == null || inputIngredients.Count == 0)
            {
                return null;
            }

            // 首先检查方块的即时配方
            Block[] blocks = BlocksManager.Blocks;
            foreach (Block block in blocks)
            {
                // 注意：需要适配GetAdHocCraftingRecipe方法
                // 这里简化处理，实际可能需要转换
            }

            // 检查预定义配方
            foreach (CraftingHYZLRecipe recipe in Recipes)
            {
                if (MatchRecipe(recipe.Ingredients, inputIngredients))
                {
                    // 检查温度等级
                    // 注意：原代码有温度检查，但CraftingHYZLRecipe没有RequiredHeatLevel字段
                    // 这里简化处理

                    // 检查玩家等级限制
                    // 注意：原代码有玩家等级检查，但CraftingHYZLRecipe没有RequiredPlayerLevel字段
                    // 这里简化处理

                    return recipe;
                }
            }

            return null;
        }

        public static bool MatchRecipe(Dictionary<string, int> requiredIngredients, Dictionary<string, int> actualIngredients)
        {
            // 如果材料数量不匹配，直接返回false
            if (requiredIngredients.Count != actualIngredients.Count)
            {
                return false;
            }

            // 检查每个材料是否匹配
            foreach (var kvp in requiredIngredients)
            {
                string ingredientId = kvp.Key;
                int requiredCount = kvp.Value;

                if (!actualIngredients.TryGetValue(ingredientId, out int actualCount) || actualCount != requiredCount)
                {
                    return false;
                }
            }

            return true;
        }

        // 辅助方法：将旧版CraftingRecipe转换为CraftingHYZLRecipe
        public static CraftingHYZLRecipe ConvertToHYZLRecipe(CraftingRecipe oldRecipe)
        {
            if (oldRecipe == null) return null;

            CraftingHYZLRecipe newRecipe = new CraftingHYZLRecipe
            {
                ResultValue = "" + oldRecipe.ResultValue,
                ResultCount = oldRecipe.ResultCount,
                Description = oldRecipe.Description,
                Message = oldRecipe.Message,
                DisplayOrder = oldRecipe.DisplayOrder
            };

            // 转换材料
            foreach (string ingredient in oldRecipe.Ingredients)
            {
                if (!string.IsNullOrEmpty(ingredient))
                {
                    if (newRecipe.Ingredients.ContainsKey(ingredient))
                    {
                        newRecipe.Ingredients[ingredient]++;
                    }
                    else
                    {
                        newRecipe.Ingredients[ingredient] = 1;
                    }
                }
            }

            return newRecipe;
        }

        // 保留原有的解码方法（需要适配）
        public static int DecodeResult(string result)
        {
            bool flag2 = false;
            int result2 = 0;

            if (flag2) return result2;

            if (!string.IsNullOrEmpty(result))
            {
                string[] array = result.Split([':'], StringSplitOptions.None);
                int blockIndex = BlocksManager.GetBlockIndex(array[0], true);
                return Terrain.MakeBlockValue(blockIndex, 0, array.Length == 2 ? int.Parse(array[1], CultureInfo.InvariantCulture) : 0);
            }
            return 0;
        }

        public static void DecodeIngredient(string ingredient, out string craftingId, out int? data)
        {
            bool flag2 = false;
            string craftingId_R = string.Empty;
            int? data_R = null;

            if (flag2)
            {
                craftingId = craftingId_R;
                data = data_R;
                return;
            }

            string[] array = ingredient.Split([':'], StringSplitOptions.None);
            craftingId = array[0];
            data = array.Length >= 2 ? new int?(int.Parse(array[1], CultureInfo.InvariantCulture)) : null;
        }

        public static CraftingHYZLRecipe DecodeRecipeElement(XElement recipeElement)
        {
            CraftingHYZLRecipe recipe = new CraftingHYZLRecipe();

            // 解析基础属性
            if (!string.IsNullOrEmpty(XmlUtils.GetAttributeValue<string>(recipeElement, "Type", null)))
            {
                recipe.Type = XmlUtils.GetAttributeValue<string>(recipeElement, "Type");
            }
            if (!string.IsNullOrEmpty(XmlUtils.GetAttributeValue<string>(recipeElement, "ResultType", null)))
            {
                recipe.ResultType = XmlUtils.GetAttributeValue<string>(recipeElement, "ResultType");
            }
            recipe.ResultValue = XmlUtils.GetAttributeValue<string>(recipeElement, "ResultValue");
            recipe.ResultCount = XmlUtils.GetAttributeValue<int>(recipeElement, "ResultCount");
            recipe.Description = XmlUtils.GetAttributeValue<string>(recipeElement, "Description");
            recipe.Message = XmlUtils.GetAttributeValue<string>(recipeElement, "Message");
            recipe.DisplayOrder = XmlUtils.GetAttributeValue<int>(recipeElement, "DisplayOrder");

            // 解析工作台等级要求
            recipe.RequiredTableLevel = XmlUtils.GetAttributeValue<int>(recipeElement, "RequiredTableLevel");
            recipe.RequiredCookingTableLevel = XmlUtils.GetAttributeValue<int>(recipeElement, "RequiredCookingTableLevel");
            recipe.RequiredMedicineStationLevel = XmlUtils.GetAttributeValue<int>(recipeElement, "RequiredMedicineStationLevel");
            recipe.MechanicalPuppetParts = XmlUtils.GetAttributeValue<bool>(recipeElement, "MechanicalPuppetParts", false);

            recipe.TimeConsuming = XmlUtils.GetAttributeValue<int>(recipeElement, "TimeConsuming");
            recipe.WaitingTime = XmlUtils.GetAttributeValue<int>(recipeElement, "WaitingTime");

            // 解析材料 (a-z 和对应的数量属性)
            ParseRecipeIngredients(recipe, recipeElement);

            return recipe;
        }

        public static void ParseRecipeIngredients(CraftingHYZLRecipe recipe, XElement recipeElement)
        {
            for (char c = 'a'; c <= 'z'; c++)
            {
                string ingredientKey = c.ToString();
                string countKey = c + "count";

                string ingredientValue = XmlUtils.GetAttributeValue<string>(recipeElement, ingredientKey, null);

                if (!string.IsNullOrEmpty(ingredientValue))
                {
                    int ingredientCount = XmlUtils.GetAttributeValue<int>(recipeElement, countKey, 1);
                    AddIngredientToRecipe(recipe, ingredientValue, ingredientCount);
                }
            }
        }

        public static void AddIngredientToRecipe(CraftingHYZLRecipe recipe, string ingredientValue, int count)
        {
            DecodeIngredient(ingredientValue, out string craftingId, out int? data);

            // 验证材料是否存在
            if (BlocksManager.FindBlocksByCraftingId(craftingId).Length == 0)
            {
                throw new InvalidOperationException($"Block with craftingId \"{ingredientValue}\" not found.");
            }

            if (data.HasValue && (data.Value < 0 || data.Value > 262143))
            {
                throw new InvalidOperationException($"Data in recipe ingredient \"{ingredientValue}\" must be between 0 and 0x3FFFF.");
            }

            // 生成完整的材料ID（包含数据值）
            string fullIngredientId = craftingId;
            if (data.HasValue)
            {
                fullIngredientId += ":" + data.Value;
            }

            // 添加到材料字典
            if (recipe.Ingredients.ContainsKey(fullIngredientId))
            {
                recipe.Ingredients[fullIngredientId] += count;
            }
            else
            {
                recipe.Ingredients[fullIngredientId] = count;
            }
        }
    }
}
//组件工作台
namespace Game
{
    public class ComponentTable : ComponentInventoryBase, IUpdateable
    {
        public ComponentBlockEntity componentBlockEntity;
        public ComponentPlayer m_craftingPlayer;
        public SubsystemPickables subsystemPickables;
        public SubsystemTime subsystemTime;
        public SubsystemGameInfo subsystemGameInfo;
        public SubsystemAudio subsystemAudio;
        public SubsystemNewInteroperableCubeBlockBehavior subsystemNewInteroperableCubeBlockBehavior;
        public CraftingHYZLRecipe m_matchedRecipe;
        public bool m_recipeUpdateNeeded;
        public bool m_recipeRefindNeeded;
        public int Level;
        public int Durability;
        public CraftingHYZLRecipe m_selectedRecipe;

        // 合成时间相关字段
        public double m_craftingStartTime;
        public double m_craftingDuration;
        public bool m_isCrafting;
        public CraftingHYZLRecipe m_currentCraftingRecipe;
        public int m_currentCraftingCount;
        public ComponentPlayer m_currentCraftingPlayer;

        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public virtual void Update(float dt)
        {
            // 处理合成时间逻辑
            if (m_isCrafting)
            {
                // 检查合成条件
                if (!CheckCraftingConditions(m_currentCraftingPlayer))
                {
                    CancelCraftingDueToConditions();
                    return;
                }

                subsystemTime.m_gameTimeFactor = 120;
                double currentTime = subsystemGameInfo.TotalElapsedGameTime;
                double elapsedTime = (currentTime - m_craftingStartTime);

                if (elapsedTime >= m_craftingDuration)
                {
                    subsystemTime.m_gameTimeFactor = 1;
                    // 合成完成
                    CompleteCrafting();
                }
            }

            if (m_recipeUpdateNeeded)
            {
                UpdateCraftingResult(m_recipeRefindNeeded);
            }
            m_recipeUpdateNeeded = false;
            m_recipeRefindNeeded = false;
            Level = NewTable.GetType(componentBlockEntity.BlockValue);
            Durability = BlocksManager.Blocks[Terrain.ExtractContents(componentBlockEntity.BlockValue)].GetDamage(componentBlockEntity.BlockValue);
        }

        // 新增：检查合成条件
        public bool CheckCraftingConditions(ComponentPlayer player)
        {
            if (IsPlayerDeadOrInvalid(player))
            {
                return false;
            }

            // 检查玩家睡眠值
            ComponentVitalStats vitalStats = player.ComponentVitalStats;
            if (vitalStats != null && vitalStats.Sleep <= 0.2f)
            {
                player.ComponentGui.DisplaySmallMessage("太困了，无法继续合成！", Color.Red, true, true);
                return false;
            }

            // 检查合成台耐久度
            if (Durability <= 0)
            {
                player.ComponentGui.DisplaySmallMessage("合成台已损坏，无法合成！", Color.Red, true, true);
                return false;
            }

            return true;
        }

        // 新增：因条件不满足取消合成
        public void CancelCraftingDueToConditions()
        {
            if (m_currentCraftingPlayer != null)
            {
                m_currentCraftingPlayer.ComponentGui.DisplaySmallMessage("合成已取消", Color.Yellow, true, true);
            }

            subsystemTime.m_gameTimeFactor = 1;
            m_isCrafting = false;
            m_currentCraftingRecipe = null;
            m_currentCraftingCount = 0;
            m_currentCraftingPlayer = null;
        }

        public override void AddSlotItems(int slotIndex, int value, int count)
        {
            base.AddSlotItems(slotIndex, value, count);
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }

        public override int RemoveSlotItems(int slotIndex, int count)
        {
            int num = base.RemoveSlotItems(slotIndex, count);
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
            return num;
        }

        public virtual void UpdateCraftingResult(bool recipeRefindNeeded)
        {
            ComponentPlayer componentPlayer = FindInteractingPlayer();
            if (componentPlayer == null) return;

            // 检查玩家状态和合成条件
            if (IsPlayerDeadOrInvalid(componentPlayer) || !CheckCraftingConditions(componentPlayer))
            {
                return;
            }

            Dictionary<string, int> playerIngredients = new Dictionary<string, int>();
            ComponentInventory playerInventory = componentPlayer.Entity.FindComponent<ComponentInventory>();

            for (int i = 0; i < playerInventory.SlotsCount; i++)
            {
                int slotValue = playerInventory.GetSlotValue(i);
                int slotCount = playerInventory.GetSlotCount(i);

                if (slotValue != 0 && slotCount > 0)
                {
                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string ingredientKey = $"{craftingId}:{data}";

                    if (playerIngredients.ContainsKey(ingredientKey))
                    {
                        playerIngredients[ingredientKey] += slotCount;
                    }
                    else
                    {
                        playerIngredients[ingredientKey] = slotCount;
                    }
                }
            }

            CraftingHYZLRecipe craftingRecipe;
            if (recipeRefindNeeded || m_matchedRecipe == null)
            {
                craftingRecipe = CraftingHYZLRecipesManager.FindMatchingRecipe(
                    Project.FindSubsystem<SubsystemTerrain>(true),
                    playerIngredients,
                    0f,
                    componentPlayer.PlayerData.Level
                );
            }
            else
            {
                craftingRecipe = m_matchedRecipe;
            }

            if (craftingRecipe != null && !string.IsNullOrEmpty(craftingRecipe.ResultValue))
            {
                m_matchedRecipe = craftingRecipe;

                if (CheckIngredientsAvailable(craftingRecipe, componentPlayer, 1, out var lackDict))
                {
                    if (ConsumeIngredientsAndCraft(componentPlayer, craftingRecipe, 1))
                    {
                        if (!string.IsNullOrEmpty(craftingRecipe.Message))
                        {
                            string message = craftingRecipe.Message;
                            if (message.StartsWith('[') && message.EndsWith(']'))
                            {
                                message = LanguageControl.Get("CRMessage", message.Substring(1, message.Length - 2));
                            }
                            componentPlayer.ComponentGui.DisplaySmallMessage(message, Color.White, true, true);
                        }
                    }
                }
            }
            else
            {
                m_matchedRecipe = null;
            }
        }

        public bool CheckIngredientsAvailable(CraftingHYZLRecipe recipe, ComponentPlayer player, int count, out Dictionary<string, int> lackDict)
        {
            lackDict = new Dictionary<string, int>();
            if (IsPlayerDeadOrInvalid(player))
                return false;

            ComponentInventory playerInventory = player.Entity.FindComponent<ComponentInventory>();

            foreach (var ingredient in recipe.Ingredients)
            {
                string ingredientId = ingredient.Key;
                int requiredCount = ingredient.Value * count;
                int totalCount = 0;

                for (int i = 0; i < playerInventory.SlotsCount; i++)
                {
                    int slotValue = playerInventory.GetSlotValue(i);
                    if (slotValue == 0) continue;

                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string currentIngredientId = $"{craftingId}:{data}";

                    if (currentIngredientId == ingredientId)
                    {
                        totalCount += playerInventory.GetSlotCount(i);
                    }
                }

                if (totalCount < requiredCount)
                {
                    lackDict[ingredientId] = requiredCount - totalCount;
                }
            }

            return lackDict.Count == 0;
        }

        public int CalculateMaxCraftCount(CraftingHYZLRecipe recipe, ComponentPlayer player)
        {
            if (IsPlayerDeadOrInvalid(player))
            {
                return 0;
            }

            ComponentInventory playerInventory = player.Entity.FindComponent<ComponentInventory>();
            int maxCraftCount = int.MaxValue;

            foreach (var ingredient in recipe.Ingredients)
            {
                string ingredientId = ingredient.Key;
                int requiredCount = ingredient.Value;
                int totalCount = 0;

                for (int i = 0; i < playerInventory.SlotsCount; i++)
                {
                    int slotValue = playerInventory.GetSlotValue(i);
                    if (slotValue == 0) continue;

                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string currentIngredientId = $"{craftingId}:{data}";

                    if (currentIngredientId == ingredientId)
                    {
                        totalCount += playerInventory.GetSlotCount(i);
                    }
                }

                int craftCountForThisIngredient = totalCount / requiredCount;
                if (craftCountForThisIngredient < maxCraftCount)
                {
                    maxCraftCount = craftCountForThisIngredient;
                }
            }

            return Math.Max(1, maxCraftCount);
        }

        // 开始合成（消耗时间）
        public bool StartCrafting(ComponentPlayer player, CraftingHYZLRecipe recipe, int count)
        {
            if (IsPlayerDeadOrInvalid(player) || !CheckCraftingConditions(player))
            {
                player.ComponentGui.DisplaySmallMessage("无法开始合成：条件不满足", Color.Red, true, true);
                return false;
            }

            if (m_isCrafting)
            {
                player.ComponentGui.DisplaySmallMessage("正在合成中，请等待完成！", Color.Yellow, true, true);
                return false;
            }

            // 检查材料是否足够，并获取缺少的字典
            if (!CheckIngredientsAvailable(recipe, player, count, out var lackDict))
            {
                player.ComponentGui.DisplaySmallMessage("材料不足！", Color.Red, true, true);
                return false;
            }

            // 以下为原合成开始逻辑...
            double craftingTimeSeconds = recipe.TimeConsuming * count;
            m_craftingDuration = craftingTimeSeconds;
            m_craftingStartTime = subsystemGameInfo.TotalElapsedGameTime;
            m_isCrafting = true;
            m_currentCraftingRecipe = recipe;
            m_currentCraftingCount = count;
            m_currentCraftingPlayer = player;

            string itemName = BlocksManager.Blocks[Terrain.ExtractContents(CraftingRecipesManager.DecodeResult(recipe.ResultValue))].GetDisplayName(null, CraftingRecipesManager.DecodeResult(recipe.ResultValue));
            player.ComponentGui.DisplaySmallMessage($"开始合成 {count * recipe.ResultCount} 个 {itemName}，预计需要 {craftingTimeSeconds} 分钟", Color.Yellow, true, true);
            return true;
        }

        // 完成合成
        public void CompleteCrafting()
        {
            if (IsPlayerDeadOrInvalid(m_currentCraftingPlayer) || !CheckCraftingConditions(m_currentCraftingPlayer))
            {
                CancelCraftingDueToConditions();
                return;
            }

            if (!m_isCrafting || m_currentCraftingRecipe == null || m_currentCraftingPlayer == null)
            {
                m_isCrafting = false;
                return;
            }

            // 消耗材料并生成产物
            if (ConsumeIngredientsAndCraft(m_currentCraftingPlayer, m_currentCraftingRecipe, m_currentCraftingCount))
            {
                string itemName = BlocksManager.Blocks[Terrain.ExtractContents(CraftingRecipesManager.DecodeResult(m_currentCraftingRecipe.ResultValue))].GetDisplayName(null, CraftingRecipesManager.DecodeResult(m_currentCraftingRecipe.ResultValue));
                m_currentCraftingPlayer.ComponentGui.DisplaySmallMessage($"成功合成 {m_currentCraftingCount * m_currentCraftingRecipe.ResultCount} 个 {itemName}！", Color.Green, true, true);
                m_currentCraftingPlayer.ComponentGui.ModalPanelWidget = null;
            }

            // 重置合成状态
            m_isCrafting = false;
            m_currentCraftingRecipe = null;
            m_currentCraftingCount = 0;
            m_currentCraftingPlayer = null;

            // 触发配方更新
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }

        public string GetIngredientId(int slotValue)
        {
            int content = Terrain.ExtractContents(slotValue);
            int data = Terrain.ExtractData(slotValue);
            Block block = BlocksManager.Blocks[content];
            string craftingId = block.GetCraftingId(slotValue);
            return $"{craftingId}:{data}";
        }

        // 修改：现在只消耗材料，不立即生成产物
        public bool ConsumeIngredientsAndCraft(ComponentPlayer player, CraftingHYZLRecipe recipe, int count)
        {
            if (IsPlayerDeadOrInvalid(player) || !CheckCraftingConditions(player))
            {
                return false;
            }

            ComponentInventory playerInventory = player.Entity.FindComponent<ComponentInventory>();

            // 检查材料是否足够合成指定数量
            if (!CheckIngredientsAvailable(recipe, player, count, out var lackDict))
            {
                return false;
            }

            // 消耗材料
            foreach (var ingredient in recipe.Ingredients)
            {
                string ingredientId = ingredient.Key;
                int totalRequiredCount = ingredient.Value * count;
                int remainingToConsume = totalRequiredCount;

                for (int i = 0; i < playerInventory.SlotsCount && remainingToConsume > 0; i++)
                {
                    int slotValue = playerInventory.GetSlotValue(i);
                    if (slotValue == 0) continue;

                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string currentIngredientId = $"{craftingId}:{data}";

                    if (currentIngredientId == ingredientId)
                    {
                        int availableCount = playerInventory.GetSlotCount(i);
                        int consumeCount = Math.Min(availableCount, remainingToConsume);

                        playerInventory.RemoveSlotItems(i, consumeCount);
                        remainingToConsume -= consumeCount;
                    }
                }
            }

            // 添加合成结果
            Vector3 dropPosition = componentBlockEntity.Position + new Vector3(0.5f, 1.5f, 0.5f);
            bool hasMoreDurableTool = false;

            for (int a = 0; a < recipe.ResultCount * count; a++)
            {
                int resultValue = CraftingRecipesManager.DecodeResult(recipe.ResultValue);

                // 检查是否为工具并且随机到更耐久的版本
                if (m_random.Bool(0.05f))
                {
                    if (Terrain.ExtractContents(resultValue) == NewToolsBlock.Index)
                    {
                        resultValue = Terrain.MakeBlockValue(Terrain.ExtractContents(resultValue), 0, NewToolsBlock.SetMoreDurable(resultValue, true));
                        hasMoreDurableTool = true;
                    }
                    if (Terrain.ExtractContents(resultValue) == NewLongRangeWeaponsBlock.Index)
                    {
                        resultValue = Terrain.MakeBlockValue(Terrain.ExtractContents(resultValue), 0, NewLongRangeWeaponsBlock.SetMoreDurable(resultValue, true));
                        hasMoreDurableTool = true;
                    }
                    if (Terrain.ExtractContents(resultValue) == NewShield.Index)
                    {
                        resultValue = Terrain.MakeBlockValue(Terrain.ExtractContents(resultValue), 0, NewShield.SetMoreDurable(resultValue, true));
                        hasMoreDurableTool = true;
                    }
                    if (Terrain.ExtractContents(resultValue) == MusketNewBlock.Index)
                    {
                        resultValue = Terrain.MakeBlockValue(Terrain.ExtractContents(resultValue), 0, MusketNewBlock.SetMoreDurable(resultValue, true));
                        hasMoreDurableTool = true;
                    }
                    if (Terrain.ExtractContents(resultValue) == ClothingBlock.Index)
                    {
                        resultValue = Terrain.MakeBlockValue(Terrain.ExtractContents(resultValue), 0, ClothingBlock.GetClothingIndex(Terrain.ExtractData(resultValue)) + 4);
                        hasMoreDurableTool = true;
                    }
                }
                subsystemPickables.AddPickable(resultValue, 1, dropPosition, null, null);
            }

            subsystemAudio.PlaySound("Audio/UI/Production/SuccessInMakingObjects", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);

            // 如果生成了更耐久的工具，显示提示
            if (hasMoreDurableTool)
            {
                player.ComponentGui.DisplaySmallMessage("幸运！制作出了更耐久的工具！", Color.LightBlue, true, true);
                player.PlayerStats.ValuesDictionaryForMods["MoreDurableProductions"] = (player.PlayerStats.ValuesDictionaryForMods.ContainsKey("MoreDurableProductions") ? (int)player.PlayerStats.ValuesDictionaryForMods["MoreDurableProductions"] + 1 : 1);
            }

            // 减少合成台耐久度
            componentBlockEntity.m_subsystemTerrain.ChangeCell(
                componentBlockEntity.Coordinates.X,
                componentBlockEntity.Coordinates.Y,
                componentBlockEntity.Coordinates.Z,
                BlocksManager.Blocks[Terrain.ExtractContents(componentBlockEntity.BlockValue)].SetDamage(
                    componentBlockEntity.BlockValue,
                    BlocksManager.Blocks[Terrain.ExtractContents(componentBlockEntity.BlockValue)].GetDamage(componentBlockEntity.BlockValue) - count
                )
            );

            // 更新玩家统计
            if (player.PlayerStats != null)
            {
                player.PlayerStats.ItemsCrafted += recipe.ResultCount * count;
                subsystemNewInteroperableCubeBlockBehavior.CurrentCapacityAdd(recipe.ResultCount * count, 2);
            }

            return true;
        }

        // 获取合成进度
        public float GetCraftingProgress()
        {
            if (!m_isCrafting) return 0f;

            double currentTime = subsystemGameInfo.TotalElapsedGameTime;
            double elapsedTime = (currentTime - m_craftingStartTime) * subsystemTime.m_gameTimeFactor;
            return MathUtils.Clamp((float)(elapsedTime / m_craftingDuration), 0f, 1f);
        }

        // 检查是否正在合成
        public bool IsCrafting()
        {
            return m_isCrafting;
        }

        // 获取当前合成信息
        public string GetCurrentCraftingInfo()
        {
            if (!m_isCrafting || m_currentCraftingRecipe == null) return string.Empty;

            string itemName = BlocksManager.Blocks[Terrain.ExtractContents(CraftingRecipesManager.DecodeResult(m_currentCraftingRecipe.ResultValue))].GetDisplayName(null, CraftingRecipesManager.DecodeResult(m_currentCraftingRecipe.ResultValue));
            float progress = GetCraftingProgress() * 100f;
            double remainingTime = (m_craftingDuration - (subsystemGameInfo.TotalElapsedGameTime - m_craftingStartTime) * subsystemTime.m_gameTimeFactor);

            return $"正在合成: {itemName} x{m_currentCraftingCount}\n进度: {progress:F1}%\n剩余时间: {remainingTime:F1}分钟";
        }

        public bool TryCraftSelectedRecipe(CraftingHYZLRecipe recipe, ComponentPlayer player)
        {
            if (recipe == null || player == null) return false;

            // 检查玩家状态和合成条件
            if (IsPlayerDeadOrInvalid(player) || !CheckCraftingConditions(player))
            {
                player.ComponentGui.DisplaySmallMessage("无法合成：条件不满足", Color.Red, true, true);
                return false;
            }

            // 检查合成台等级
            if (Level < recipe.RequiredTableLevel)
            {
                player.ComponentGui.DisplaySmallMessage($"合成台等级不足！需要等级{recipe.RequiredTableLevel}", Color.Red, true, true);
                return false;
            }

            // 检查材料是否匹配
            if (!CheckIngredientsAvailable(recipe, player, 1, out var lackDict))
            {
                DialogsManager.ShowDialog(null, new ShellSupplementMaterialsDialog(player, lackDict));
                player.ComponentGui.DisplaySmallMessage("材料不足！", Color.Red, true, true);
                return false;
            }

            // 计算最大合成数量
            int maxCraftCount = CalculateMaxCraftCount(recipe, player);

            // 保存当前配方和玩家，用于对话框回调
            m_selectedRecipe = recipe;
            m_craftingPlayer = player;

            // 显示数量选择对话框
            DialogsManager.ShowDialog(null, new SynthesisCountDialog(delegate (int count)
            {
                if (count > 0 && m_selectedRecipe != null && m_craftingPlayer != null)
                {
                    // 开始合成（消耗时间）
                    StartCrafting(m_craftingPlayer, m_selectedRecipe, count);
                }

                // 清空临时变量
                m_selectedRecipe = null;
                m_craftingPlayer = null;
            })
            {
                Count = 1,
                MaxCount = maxCraftCount
            });

            return true;
        }

        public bool IsPlayerDeadOrInvalid(ComponentPlayer player)
        {
            if (player == null) return true;

            // 检查玩家是否死亡
            ComponentHealth health = player.Entity.FindComponent<ComponentHealth>();
            if (health != null && health.Health <= 0f)
            {
                return true;
            }

            // 检查玩家是否打开合成界面
            if (player.ComponentGui.ModalPanelWidget is TableWidget)
            {
                // 在合成界面中
            }
            else
            {
                return true;
            }

            // 检查玩家是否离合成台太远
            if (componentBlockEntity != null)
            {
                float distance = Vector3.Distance(player.ComponentBody.Position, componentBlockEntity.Position);
                if (distance > 5f) // 如果玩家离合成台超过5个单位，认为已离开
                {
                    return true;
                }
            }

            return false;
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            componentBlockEntity = Entity.FindComponent<ComponentBlockEntity>(throwOnError: true);
            subsystemPickables = Project.FindSubsystem<SubsystemPickables>(throwOnError: true);
            subsystemTime = Project.FindSubsystem<SubsystemTime>();
            subsystemGameInfo = Project.FindSubsystem<SubsystemGameInfo>();
            subsystemAudio = Project.FindSubsystem<SubsystemAudio>();
            subsystemNewInteroperableCubeBlockBehavior = Project.FindSubsystem<SubsystemNewInteroperableCubeBlockBehavior>(true);
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }
    }
}
