        {
            BlocksManager.GetBlockIndex<NewTable>()
        };

        public override void Load(ValuesDictionary valuesDictionary)
        {
            base.Load(valuesDictionary);
            m_databaseObject = Project.GameDatabase.Database.FindDatabaseObject("Table", Project.GameDatabase.EntityTemplateType, true);
