//组件工作台升级或维修
namespace Game
{
    public class ComponentUpgradeAndMaintenanceTable : ComponentInventoryBase, IUpdateable
    {
        public ComponentBlockEntity componentBlockEntity;
        public ComponentTable componentTable;
        public SubsystemPickables subsystemPickables;
        public SubsystemTime subsystemTime;
        public SubsystemGameInfo subsystemGameInfo;
        public SubsystemTerrain subsystemTerrain;
        public SubsystemAudio subsystemAudio;

        // 配方匹配
        public CraftingTableRecipe m_matchedUpgradeRecipe;
        public CraftingTableRecipe m_matchedMaintenanceRecipe;
        public bool m_recipeUpdateNeeded;
        public bool m_recipeRefindNeeded;
        public int Level;
        public int Durability;

        // 升级时间相关字段
        public double m_upgradeStartTime;
        public double m_upgradeDuration;
        public bool m_isUpgrading;
        public CraftingTableRecipe m_currentUpgradeRecipe;
        public ComponentPlayer m_currentUpgradingPlayer;

        // 维修时间相关字段
        public double m_maintenanceStartTime;
        public double m_maintenanceDuration;
        public bool m_isMaintaining;
        public CraftingTableRecipe m_currentMaintenanceRecipe;
        public ComponentPlayer m_currentMaintainingPlayer;

        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public virtual void Update(float dt)
        {
            // 处理升级时间逻辑
            if (m_isUpgrading)
            {
                if (!CheckConditions(m_currentUpgradingPlayer))
                {
                    CancelOperationDueToConditions("升级");
                    return;
                }

                subsystemTime.m_gameTimeFactor = 120;
                double currentTime = subsystemGameInfo.TotalElapsedGameTime;
                double elapsedTime = (currentTime - m_upgradeStartTime);

                if (elapsedTime >= m_upgradeDuration)
                {
                    subsystemTime.m_gameTimeFactor = 1;
                    CompleteUpgrade();
                }
            }

            // 处理维修时间逻辑
            if (m_isMaintaining)
            {
                if (!CheckConditions(m_currentMaintainingPlayer))
                {
                    CancelOperationDueToConditions("维修");
                    return;
                }

                subsystemTime.m_gameTimeFactor = 120;
                double currentTime = subsystemGameInfo.TotalElapsedGameTime;
                double elapsedTime = (currentTime - m_maintenanceStartTime);

                if (elapsedTime >= m_maintenanceDuration)
                {
                    subsystemTime.m_gameTimeFactor = 1;
                    CompleteMaintenance();
                }
            }

            if (m_recipeUpdateNeeded)
            {
                UpdateRecipeResult(m_recipeRefindNeeded);
            }
            m_recipeUpdateNeeded = false;
            m_recipeRefindNeeded = false;

            UpdateTableStatus();
        }

        public void UpdateTableStatus()
        {
            if (componentBlockEntity != null && componentTable != null)
            {
                Level = componentTable.Level;
                Durability = componentTable.Durability;
            }
        }

        // 通用条件检查
        public bool CheckConditions(ComponentPlayer player)
        {
            if (IsPlayerDeadOrInvalid(player)) return false;

            ComponentVitalStats vitalStats = player.ComponentVitalStats;
            if (vitalStats != null && vitalStats.Sleep <= 0.2f)
            {
                player.ComponentGui.DisplaySmallMessage("太困了，无法继续操作！", Color.Red, true, true);
                return false;
            }

            return true;
        }

        // 通用取消操作
        public void CancelOperationDueToConditions(string operationType)
        {
            ComponentPlayer currentPlayer = operationType == "升级" ? m_currentUpgradingPlayer : m_currentMaintainingPlayer;
            if (currentPlayer != null)
            {
                currentPlayer.ComponentGui.DisplaySmallMessage($"{operationType}已取消", Color.Yellow, true, true);
            }

            subsystemTime.m_gameTimeFactor = 1;

            if (operationType == "升级")
            {
                m_isUpgrading = false;
                m_currentUpgradeRecipe = null;
                m_currentUpgradingPlayer = null;
            }
            else
            {
                m_isMaintaining = false;
                m_currentMaintenanceRecipe = null;
                m_currentMaintainingPlayer = null;
            }
        }

        public override void AddSlotItems(int slotIndex, int value, int count)
        {
            base.AddSlotItems(slotIndex, value, count);
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }

        public override int RemoveSlotItems(int slotIndex, int count)
        {
            int num = base.RemoveSlotItems(slotIndex, count);
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
            return num;
        }

        public virtual void UpdateRecipeResult(bool recipeRefindNeeded)
        {
            ComponentPlayer componentPlayer = FindInteractingPlayer();
            if (componentPlayer == null) return;

            if (IsPlayerDeadOrInvalid(componentPlayer) || !CheckConditions(componentPlayer)) return;

            Dictionary<string, int> playerIngredients = GetPlayerIngredients(componentPlayer);

            // 根据当前界面类型更新对应的配方
            if (componentPlayer.ComponentGui.ModalPanelWidget is TableUpgradeWidget)
            {
                UpdateUpgradeRecipe(recipeRefindNeeded, playerIngredients, componentPlayer);
            }
            else if (componentPlayer.ComponentGui.ModalPanelWidget is TableMaintenanceWidget)
            {
                UpdateMaintenanceRecipe(recipeRefindNeeded, playerIngredients, componentPlayer);
            }
        }

        public void UpdateUpgradeRecipe(bool recipeRefindNeeded, Dictionary<string, int> playerIngredients, ComponentPlayer player)
        {
            CraftingTableRecipe upgradeRecipe;
            if (recipeRefindNeeded || m_matchedUpgradeRecipe == null)
            {
                upgradeRecipe = CraftingTableRecipeManager.FindMatchingRecipe(playerIngredients, Level);
            }
            else
            {
                upgradeRecipe = m_matchedUpgradeRecipe;
            }

            if (upgradeRecipe != null)
            {
                m_matchedUpgradeRecipe = upgradeRecipe;
                if (CheckIngredientsAvailable(upgradeRecipe, player, out var lackDict))
                {
                    player.ComponentGui.DisplaySmallMessage($"可以升级到{upgradeRecipe.Description}！", Color.Green, true, true);
                }
            }
            else
            {
                m_matchedUpgradeRecipe = null;
            }
        }

        public void UpdateMaintenanceRecipe(bool recipeRefindNeeded, Dictionary<string, int> playerIngredients, ComponentPlayer player)
        {
            CraftingTableRecipe maintenanceRecipe;
            if (recipeRefindNeeded || m_matchedMaintenanceRecipe == null)
            {
                maintenanceRecipe = CraftingTableRecipeManager.FindMatchingRecipe(playerIngredients, Level);
            }
            else
            {
                maintenanceRecipe = m_matchedMaintenanceRecipe;
            }

            if (maintenanceRecipe != null)
            {
                m_matchedMaintenanceRecipe = maintenanceRecipe;
                if (CheckIngredientsAvailable(maintenanceRecipe, player, out var lackDict))
                {
                    player.ComponentGui.DisplaySmallMessage($"可以维修工作台！", Color.Green, true, true);
                }
            }
            else
            {
                m_matchedMaintenanceRecipe = null;
            }
        }

        public Dictionary<string, int> GetPlayerIngredients(ComponentPlayer player)
        {
            Dictionary<string, int> playerIngredients = new Dictionary<string, int>();
            ComponentInventory playerInventory = player.Entity.FindComponent<ComponentInventory>();

            for (int i = 0; i < playerInventory.SlotsCount; i++)
            {
                int slotValue = playerInventory.GetSlotValue(i);
                int slotCount = playerInventory.GetSlotCount(i);

                if (slotValue != 0 && slotCount > 0)
                {
                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string ingredientKey = $"{craftingId}:{data}";

                    if (playerIngredients.ContainsKey(ingredientKey))
                    {
                        playerIngredients[ingredientKey] += slotCount;
                    }
                    else
                    {
                        playerIngredients[ingredientKey] = slotCount;
                    }
                }
            }

            return playerIngredients;
        }

        public bool CheckIngredientsAvailable(CraftingTableRecipe recipe, ComponentPlayer player, out Dictionary<string, int> lackDict)
        {
            lackDict = new Dictionary<string, int>();
            if (IsPlayerDeadOrInvalid(player)) return false;

            Dictionary<string, int> playerIngredients = GetPlayerIngredients(player);

            foreach (var ingredient in recipe.Ingredients)
            {
                string ingredientId = ingredient.Key;
                int requiredCount = ingredient.Value;
                int actualCount = playerIngredients.ContainsKey(ingredientId) ? playerIngredients[ingredientId] : 0;

                if (actualCount < requiredCount)
                {
                    lackDict[ingredientId] = requiredCount - actualCount;
                }
            }

            return lackDict.Count == 0;
        }

        // 开始操作（升级或维修）
        public bool StartOperation(ComponentPlayer player, CraftingTableRecipe recipe, string operationType)
        {
            if (IsPlayerDeadOrInvalid(player) || !CheckConditions(player))
            {
                player.ComponentGui.DisplaySmallMessage($"无法开始{operationType}：条件不满足", Color.Red, true, true);
                return false;
            }

            bool isOperating = operationType == "升级" ? m_isUpgrading : m_isMaintaining;
            if (isOperating)
            {
                player.ComponentGui.DisplaySmallMessage($"正在{operationType}中，请等待完成！", Color.Yellow, true, true);
                return false;
            }

            if (!CheckIngredientsAvailable(recipe, player, out var lackDict))
            {
                player.ComponentGui.DisplaySmallMessage("材料不足！", Color.Red, true, true);
                return false;
            }

            double operationTimeSeconds = recipe.TimeConsuming;

            if (operationType == "升级")
            {
                m_upgradeDuration = operationTimeSeconds;
                m_upgradeStartTime = subsystemGameInfo.TotalElapsedGameTime;
                m_isUpgrading = true;
                m_currentUpgradeRecipe = recipe;
                m_currentUpgradingPlayer = player;
            }
            else
            {
                m_maintenanceDuration = operationTimeSeconds;
                m_maintenanceStartTime = subsystemGameInfo.TotalElapsedGameTime;
                m_isMaintaining = true;
                m_currentMaintenanceRecipe = recipe;
                m_currentMaintainingPlayer = player;
            }

            player.ComponentGui.DisplaySmallMessage($"开始{operationType}工作台：{recipe.Description}，预计需要 {operationTimeSeconds} 分钟", Color.Yellow, true, true);
            return true;
        }

        // 完成升级
        public void CompleteUpgrade()
        {
            if (IsPlayerDeadOrInvalid(m_currentUpgradingPlayer) || !CheckConditions(m_currentUpgradingPlayer))
            {
                CancelOperationDueToConditions("升级");
                return;
            }

            if (!m_isUpgrading || m_currentUpgradeRecipe == null || m_currentUpgradingPlayer == null)
            {
                m_isUpgrading = false;
                return;
            }

            if (ConsumeIngredientsAndOperate(m_currentUpgradingPlayer, m_currentUpgradeRecipe, "升级"))
            {
                m_currentUpgradingPlayer.ComponentGui.DisplaySmallMessage($"工作台升级成功：{m_currentUpgradeRecipe.Description}！", Color.Green, true, true);

                if (!string.IsNullOrEmpty(m_currentUpgradeRecipe.Message))
                {
                    m_currentUpgradingPlayer.ComponentGui.DisplaySmallMessage(m_currentUpgradeRecipe.Message, Color.White, true, true);
                }
            }

            ResetOperationState("升级");
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }

        // 完成维修
        public void CompleteMaintenance()
        {
            if (IsPlayerDeadOrInvalid(m_currentMaintainingPlayer) || !CheckConditions(m_currentMaintainingPlayer))
            {
                CancelOperationDueToConditions("维修");
                return;
            }

            if (!m_isMaintaining || m_currentMaintenanceRecipe == null || m_currentMaintainingPlayer == null)
            {
                m_isMaintaining = false;
                return;
            }

            if (ConsumeIngredientsAndOperate(m_currentMaintainingPlayer, m_currentMaintenanceRecipe, "维修"))
            {
                m_currentMaintainingPlayer.ComponentGui.DisplaySmallMessage($"工作台维修成功！", Color.Green, true, true);

                if (!string.IsNullOrEmpty(m_currentMaintenanceRecipe.Message))
                {
                    m_currentMaintainingPlayer.ComponentGui.DisplaySmallMessage(m_currentMaintenanceRecipe.Message, Color.White, true, true);
                }
            }

            ResetOperationState("维修");
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }

        // 消耗材料并执行操作
        public bool ConsumeIngredientsAndOperate(ComponentPlayer player, CraftingTableRecipe recipe, string operationType)
        {
            if (IsPlayerDeadOrInvalid(player) || !CheckConditions(player)) return false;

            ComponentInventory playerInventory = player.Entity.FindComponent<ComponentInventory>();

            if (!CheckIngredientsAvailable(recipe, player, out var lackDict)) return false;

            // 消耗材料
            foreach (var ingredient in recipe.Ingredients)
            {
                string ingredientId = ingredient.Key;
                int totalRequiredCount = ingredient.Value;
                int remainingToConsume = totalRequiredCount;

                for (int i = 0; i < playerInventory.SlotsCount && remainingToConsume > 0; i++)
                {
                    int slotValue = playerInventory.GetSlotValue(i);
                    if (slotValue == 0) continue;

                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string currentIngredientId = $"{craftingId}:{data}";

                    if (currentIngredientId == ingredientId)
                    {
                        int availableCount = playerInventory.GetSlotCount(i);
                        int consumeCount = Math.Min(availableCount, remainingToConsume);
                        playerInventory.RemoveSlotItems(i, consumeCount);
                        remainingToConsume -= consumeCount;
                    }
                }
            }

            // 执行操作
            if (operationType == "升级")
            {
                PerformTableUpgrade(recipe);
            }
            else
            {
                PerformTableMaintenance(recipe);
                player.PlayerStats.ValuesDictionaryForMods["WorkstationRepairCount"] = (player.PlayerStats.ValuesDictionaryForMods.ContainsKey("WorkstationRepairCount") ? (int)player.PlayerStats.ValuesDictionaryForMods["WorkstationRepairCount"] + 1 : 1);
            }

            return true;
        }

        // 执行工作台升级
        public void PerformTableUpgrade(CraftingTableRecipe recipe)
        {
            if (componentBlockEntity == null || subsystemTerrain == null) return;

            int newLevel = Level + 1;
            int newBlockValue = Terrain.MakeBlockValue(NewTable.Index, 0, NewTable.SetType(componentBlockEntity.BlockValue, NewTable.GetType(componentBlockEntity.BlockValue) + 1));
            newBlockValue = BlocksManager.Blocks[Terrain.ExtractContents(newBlockValue)].SetDamage(newBlockValue, BlocksManager.Blocks[Terrain.ExtractContents(newBlockValue)].GetDurability(newBlockValue));

            subsystemTerrain.ChangeCell(
                componentBlockEntity.Coordinates.X,
                componentBlockEntity.Coordinates.Y,
                componentBlockEntity.Coordinates.Z,
                newBlockValue
            );

            componentBlockEntity.BlockValue = newBlockValue;
        }

        // 执行工作台维修
        public void PerformTableMaintenance(CraftingTableRecipe recipe)
        {
            if (componentBlockEntity == null || subsystemTerrain == null) return;

            // 修复工作台耐久度
            int repairedBlockValue = BlocksManager.Blocks[Terrain.ExtractContents(componentBlockEntity.BlockValue)].SetDamage(componentBlockEntity.BlockValue, BlocksManager.Blocks[Terrain.ExtractContents(componentBlockEntity.BlockValue)].GetDurability(componentBlockEntity.BlockValue));

            subsystemTerrain.ChangeCell(
                componentBlockEntity.Coordinates.X,
                componentBlockEntity.Coordinates.Y,
                componentBlockEntity.Coordinates.Z,
                repairedBlockValue
            );
        }

        public int CreateUpgradedBlockValue(int newLevel)
        {
            int content = Terrain.ExtractContents(componentBlockEntity.BlockValue);
            int currentData = Terrain.ExtractData(componentBlockEntity.BlockValue);
            int newData = (currentData & ~0xF) | (newLevel & 0xF);
            return Terrain.MakeBlockValue(content, 0, newData);
        }

        // 获取操作进度
        public float GetOperationProgress(string operationType)
        {
            if (operationType == "升级" && !m_isUpgrading) return 0f;
            if (operationType == "维修" && !m_isMaintaining) return 0f;

            double currentTime = subsystemGameInfo.TotalElapsedGameTime;
            double startTime = operationType == "升级" ? m_upgradeStartTime : m_maintenanceStartTime;
            double duration = operationType == "升级" ? m_upgradeDuration : m_maintenanceDuration;
            double elapsedTime = (currentTime - startTime) * subsystemTime.m_gameTimeFactor;

            return MathUtils.Clamp((float)(elapsedTime / duration), 0f, 1f);
        }

        // 检查是否正在操作
        public bool IsOperating(string operationType)
        {
            return operationType == "升级" ? m_isUpgrading : m_isMaintaining;
        }

        // 获取当前操作信息
        public string GetCurrentOperationInfo(string operationType)
        {
            CraftingTableRecipe currentRecipe = operationType == "升级" ? m_currentUpgradeRecipe : m_currentMaintenanceRecipe;
            if ((operationType == "升级" && !m_isUpgrading) || (operationType == "维修" && !m_isMaintaining) || currentRecipe == null)
                return string.Empty;

            float progress = GetOperationProgress(operationType) * 100f;
            double startTime = operationType == "升级" ? m_upgradeStartTime : m_maintenanceStartTime;
            double duration = operationType == "升级" ? m_upgradeDuration : m_maintenanceDuration;
            double remainingTime = (duration - (subsystemGameInfo.TotalElapsedGameTime - startTime) * subsystemTime.m_gameTimeFactor);

            return $"正在{operationType}: {currentRecipe.Description}\n进度: {progress:F1}%\n剩余时间: {remainingTime:F1}分钟";
        }

        // 尝试升级工作台
        public bool TryUpgradeTable(CraftingTableRecipe recipe, ComponentPlayer player)
        {
            return TryOperateTable(recipe, player, "升级");
        }

        // 尝试维修工作台
        public bool TryMaintainTable(CraftingTableRecipe recipe, ComponentPlayer player)
        {
            return TryOperateTable(recipe, player, "维修");
        }

        public bool TryOperateTable(CraftingTableRecipe recipe, ComponentPlayer player, string operationType)
        {
            if (recipe == null || player == null) return false;

            if (IsPlayerDeadOrInvalid(player) || !CheckConditions(player))
            {
                player.ComponentGui.DisplaySmallMessage($"无法{operationType}：条件不满足", Color.Red, true, true);
                return false;
            }

            // 检查材料，并获取缺少字典
            if (!CheckIngredientsAvailable(recipe, player, out var lackDict))
            {
                // 只在这里弹窗一次，显示缺少的材料
                DialogsManager.ShowDialog(null, new ShellSupplementMaterialsDialog(player, lackDict));
                player.ComponentGui.DisplaySmallMessage("材料不足！", Color.Red, true, true);
                return false;
            }

            // 播放音效
            if (operationType == "维修")
                subsystemAudio.PlaySound("Audio/UI/Production/Maintenance", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
            else
                subsystemAudio.PlaySound("Audio/UI/Production/Upgrade", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);

            return StartOperation(player, recipe, operationType);
        }

        public void ResetOperationState(string operationType)
        {
            if (operationType == "升级")
            {
                m_currentUpgradingPlayer.ComponentGui.ModalPanelWidget = null;
                m_isUpgrading = false;
                m_currentUpgradeRecipe = null;
                m_currentUpgradingPlayer = null;
            }
            else
            {
                m_currentMaintainingPlayer.ComponentGui.ModalPanelWidget = null;
                m_isMaintaining = false;
                m_currentMaintenanceRecipe = null;
                m_currentMaintainingPlayer = null;
            }
        }

        public bool IsPlayerDeadOrInvalid(ComponentPlayer player)
        {
            if (player == null) return true;

            ComponentHealth health = player.Entity.FindComponent<ComponentHealth>();
            if (health != null && health.Health <= 0f) return true;

            // 检查玩家是否打开正确的界面
            if (!(player.ComponentGui.ModalPanelWidget is TableUpgradeWidget) &&
                !(player.ComponentGui.ModalPanelWidget is TableMaintenanceWidget))
            {
                return true;
            }

            if (componentBlockEntity != null)
            {
                float distance = Vector3.Distance(player.ComponentBody.Position, componentBlockEntity.Position);
                if (distance > 5f) return true;
            }

            return false;
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            componentBlockEntity = Entity.FindComponent<ComponentBlockEntity>(throwOnError: true);
            componentTable = Entity.FindComponent<ComponentTable>(throwOnError: true);
            subsystemPickables = Project.FindSubsystem<SubsystemPickables>(throwOnError: true);
            subsystemTime = Project.FindSubsystem<SubsystemTime>();
            subsystemGameInfo = Project.FindSubsystem<SubsystemGameInfo>();
            subsystemTerrain = Project.FindSubsystem<SubsystemTerrain>();
            subsystemAudio = Project.FindSubsystem<SubsystemAudio>();
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }
    }
}
