//子系统新远程武器方块行为
namespace Game
{
    public class SubsystemNewLongRangeWeaponsBlockBehavior : SubsystemBlockBehavior
    {
        public SubsystemTime m_subsystemTime;
        public SubsystemProjectiles m_subsystemProjectiles;
        public SubsystemAudio m_subsystemAudio;
        public SubsystemTerrain m_subsystemTerrain;
        public Random m_random = new Random();
        public Dictionary<ComponentMiner, double> m_aimStartTimes = new Dictionary<ComponentMiner, double>();
        public int m_NewLongRangeWeaponsBlockIndex;
        public int m_NewProjectilesBlockIndex;

        public override int[] HandledBlocks => new int[1] { BlocksManager.GetBlockIndex<NewLongRangeWeaponsBlock>() };

        public override bool OnEditInventoryItem(IInventory inventory, int slotIndex, ComponentPlayer componentPlayer)
        {
            if (Terrain.ExtractContents(inventory.GetSlotValue(slotIndex)) == BlocksManager.GetBlockIndex<NewLongRangeWeaponsBlock>())
            {
                componentPlayer.ComponentGui.ModalPanelWidget = new NewLongRangeWeaponsWidget(inventory, slotIndex);
                return true;
            }
            return false;
        }

        public override bool OnAim(Ray3 aim, ComponentMiner componentMiner, AimState state)
        {
            IInventory inventory = componentMiner.Inventory;
            if (inventory == null) return false;
            int activeSlot = inventory.ActiveSlotIndex;
            if (activeSlot < 0) return false;
            int slotValue = inventory.GetSlotValue(activeSlot);
            int slotCount = inventory.GetSlotCount(activeSlot);
            if (slotCount <= 0 || Terrain.ExtractContents(slotValue) != m_NewLongRangeWeaponsBlockIndex) return false;

            int data = Terrain.ExtractData(slotValue);
            int draw = NewLongRangeWeaponsBlock.GetDraw(data);
            int arrowType = NewLongRangeWeaponsBlock.GetArrowType(data);

            if (!m_aimStartTimes.TryGetValue(componentMiner, out double aimStart))
            {
                aimStart = m_subsystemTime.GameTime;
                m_aimStartTimes[componentMiner] = aimStart;
            }
            float aimTime = (float)(m_subsystemTime.GameTime - aimStart);
            float noiseTime = (float)MathUtils.Remainder(m_subsystemTime.GameTime, 1000.0);
            Vector3 sway = ((componentMiner.ComponentCreature.ComponentBody.IsCrouching ? 0.01f : 0.03f) + 0.15f * MathUtils.Saturate((aimTime - 2.5f) / 6f)) * new Vector3
            {
                X = SimplexNoise.OctavedNoise(noiseTime, 2f, 3, 2f, 0.5f),
                Y = SimplexNoise.OctavedNoise(noiseTime + 100f, 2f, 3, 2f, 0.5f),
                Z = SimplexNoise.OctavedNoise(noiseTime + 200f, 2f, 3, 2f, 0.5f)
            };
            aim.Direction = Vector3.Normalize(aim.Direction + sway);

            if (state == AimState.InProgress)
            {
                if (aimTime >= 10f)
                {
                    componentMiner.ComponentCreature.ComponentCreatureSounds.PlayMoanSound();
                    return true;
                }
                if (aimTime >= 1.5f && draw < 1)
                {
                    draw = 1;
                    data = NewLongRangeWeaponsBlock.SetDraw(data, 1);
                    inventory.RemoveSlotItems(activeSlot, 1);
                    inventory.AddSlotItems(activeSlot, Terrain.MakeBlockValue(m_NewLongRangeWeaponsBlockIndex, 0, data), 1);
                }
                ComponentFirstPersonModel fpModel = componentMiner.Entity.FindComponent<ComponentFirstPersonModel>();
                if (fpModel != null)
                {
                    componentMiner.ComponentPlayer?.ComponentAimingSights.ShowAimingSights(aim.Position, aim.Direction);
                    fpModel.ItemOffsetOrder = new Vector3(-0.22f, 0.15f, 0.1f);
                    fpModel.ItemRotationOrder = new Vector3(-0.7f, 0f, 0f);
                }
                componentMiner.ComponentCreature.ComponentCreatureModel.AimHandAngleOrder = 1.3f;
                componentMiner.ComponentCreature.ComponentCreatureModel.InHandItemOffsetOrder = new Vector3(-0.08f, -0.1f, 0.07f);
                componentMiner.ComponentCreature.ComponentCreatureModel.InHandItemRotationOrder = new Vector3(-1.55f, 0f, 0f);
                return false;
            }

            if (state == AimState.Cancelled)
            {
                m_aimStartTimes.Remove(componentMiner);
                if (draw > 0)
                {
                    data = NewLongRangeWeaponsBlock.SetDraw(data, 0);
                    inventory.RemoveSlotItems(activeSlot, 1);
                    inventory.AddSlotItems(activeSlot, Terrain.MakeBlockValue(m_NewLongRangeWeaponsBlockIndex, 0, data), 1);
                }
                return false;
            }

            if (state == AimState.Completed)
            {
                if (draw != 1)
                {
                    componentMiner.ComponentPlayer?.ComponentGui.DisplaySmallMessage("武器未准备好", Color.White, true, false);
                }
                else if (arrowType == 0)
                {
                    componentMiner.ComponentPlayer?.ComponentGui.DisplaySmallMessage("未装填弹药", Color.White, true, false);
                }
                else
                {
                    int arrowCount = NewLongRangeWeaponsBlock.GetNumberOfArrowsFired(slotValue);
                    float angleStep = MathUtils.DegToRad(2.5f);
                    Vector3 originalDir = aim.Direction;
                    Vector3 axis = Vector3.Normalize(Vector3.Cross(originalDir, Vector3.UnitY));
                    if (axis.LengthSquared() < 0.001f) axis = Vector3.UnitX;
                    Vector3 spawnPos = componentMiner.ComponentCreature.ComponentCreatureModel.EyePosition
                        + componentMiner.ComponentCreature.ComponentBody.Matrix.Right * 0.3f
                        - componentMiner.ComponentCreature.ComponentBody.Matrix.Up * 0.2f;
                    Vector3 spawnOffset = originalDir * 0.5f;
                    int projValue = Terrain.MakeBlockValue(m_NewProjectilesBlockIndex, 0, NewProjectiles.SetType(m_NewProjectilesBlockIndex, arrowType - 1));
                    for (int i = 0; i < arrowCount; i++)
                    {
                        float angle = (arrowCount % 2 == 1) ? (i - (arrowCount - 1) / 2) * angleStep : (i - arrowCount / 2 + 0.5f) * angleStep;
                        float cos = MathUtils.Cos(angle), sin = MathUtils.Sin(angle);
                        Vector3 cross = Vector3.Cross(axis, originalDir);
                        float dot = Vector3.Dot(axis, originalDir);
                        Vector3 newDir = originalDir * cos + cross * sin + axis * (dot * (1 - cos));
                        Vector3 velocity = componentMiner.ComponentCreature.ComponentBody.Velocity + 38f * newDir;
                        m_subsystemProjectiles.FireProjectile(projValue, spawnPos + spawnOffset, velocity, Vector3.Zero, componentMiner.ComponentCreature);
                        m_subsystemAudio.PlaySound("Audio/Bow", 1f, m_random.Float(-0.1f, 0.1f), spawnPos, 3f, 0.05f);
                    }
                }
                inventory.RemoveSlotItems(activeSlot, 1);
                int newData = NewLongRangeWeaponsBlock.SetDraw(data, 0);
                newData = NewLongRangeWeaponsBlock.SetArrowType(newData, 0);
                inventory.AddSlotItems(activeSlot, Terrain.MakeBlockValue(m_NewLongRangeWeaponsBlockIndex, 0, newData), 1);
                if (draw > 0)
                {
                    componentMiner.DamageActiveTool(1);
                    m_subsystemAudio.PlaySound("Audio/CrossbowBoing", 1f, m_random.Float(-0.1f, 0.1f), componentMiner.ComponentCreature.ComponentCreatureModel.EyePosition, 3f, 0f);
                }
                m_aimStartTimes.Remove(componentMiner);
            }
            return false;
        }

        public override int GetProcessInventoryItemCapacity(IInventory inventory, int slotIndex, int value)
        {
            if (Terrain.ExtractContents(value) == m_NewProjectilesBlockIndex && NewProjectiles.GetIsAnArrow(value))
            {
                int data = Terrain.ExtractData(inventory.GetSlotValue(slotIndex));
                if (NewLongRangeWeaponsBlock.GetDraw(data) == 1 && NewLongRangeWeaponsBlock.GetArrowType(data) == 0) return 1;
            }
            return 0;
        }

        public override void ProcessInventoryItem(IInventory inventory, int slotIndex, int value, int count, int processCount, out int processedValue, out int processedCount)
        {
            if (processCount == 1)
            {
                int projType = NewProjectiles.GetType(value);
                int slotVal = inventory.GetSlotValue(slotIndex);
                int data = Terrain.ExtractData(slotVal);
                inventory.RemoveSlotItems(slotIndex, 1);
                data = NewLongRangeWeaponsBlock.SetArrowType(data, projType + 1);
                inventory.AddSlotItems(slotIndex, Terrain.MakeBlockValue(m_NewLongRangeWeaponsBlockIndex, 0, data), 1);
                processedValue = 0;
                processedCount = 0;
            }
            else
            {
                processedValue = value;
                processedCount = count;
            }
        }

        public override void Load(ValuesDictionary valuesDictionary)
        {
            m_subsystemTime = Project.FindSubsystem<SubsystemTime>(true);
            m_subsystemProjectiles = Project.FindSubsystem<SubsystemProjectiles>(true);
            m_subsystemAudio = Project.FindSubsystem<SubsystemAudio>(true);
            m_subsystemTerrain = Project.FindSubsystem<SubsystemTerrain>(true);
            m_NewLongRangeWeaponsBlockIndex = BlocksManager.GetBlockIndex<NewLongRangeWeaponsBlock>();
            m_NewProjectilesBlockIndex = BlocksManager.GetBlockIndex<NewProjectiles>();
            base.Load(valuesDictionary);
        }
    }
}
//新远程武器界面
namespace Game
{
    public class NewLongRangeWeaponsWidget : CanvasWidget
    {
        public IInventory m_inventory;
        public int m_slotIndex;
        public float? m_dragStartOffset;
        public GridPanelWidget m_inventoryGrid;
        public InventorySlotWidget m_inventorySlotWidget;
        public LabelWidget m_instructionsLabel;
        public Random m_random = new Random();

        public NewLongRangeWeaponsWidget(IInventory inventory, int slotIndex)
        {
            m_inventory = inventory;
            m_slotIndex = slotIndex;
            XElement node = ContentManager.Get<XElement>("Widgets/NewLongRangeWeaponsWidget");
            LoadContents(this, node);
            m_inventoryGrid = Children.Find<GridPanelWidget>("InventoryGrid");
            m_inventorySlotWidget = Children.Find<InventorySlotWidget>("InventorySlot");
            m_instructionsLabel = Children.Find<LabelWidget>("InstructionsLabel");
            for (int i = 0; i < m_inventoryGrid.RowsCount; i++)
            {
                for (int j = 0; j < m_inventoryGrid.ColumnsCount; j++)
                {
                    InventorySlotWidget widget = new InventorySlotWidget();
                    m_inventoryGrid.Children.Add(widget);
                    m_inventoryGrid.SetWidgetCell(widget, new Point2(j, i));
                }
            }
            int num = 10;
            foreach (Widget child in m_inventoryGrid.Children)
            {
                (child as InventorySlotWidget)?.AssignInventorySlot(inventory, num++);
            }
            m_inventorySlotWidget.AssignInventorySlot(inventory, slotIndex);
            m_inventorySlotWidget.CustomViewMatrix = Matrix.CreateLookAt(new Vector3(0f, 1f, 0.2f), new Vector3(0f, 0f, 0.2f), -Vector3.UnitZ);
        }

        public override void Update()
        {
            int slotValue = m_inventory.GetSlotValue(m_slotIndex);
            int slotCount = m_inventory.GetSlotCount(m_slotIndex);
            int num = Terrain.ExtractContents(slotValue);
            int data = Terrain.ExtractData(slotValue);
            int draw = NewLongRangeWeaponsBlock.GetDraw(data);
            int arrowType = NewLongRangeWeaponsBlock.GetArrowType(data);
            if (num == BlocksManager.GetBlockIndex<NewLongRangeWeaponsBlock>() && slotCount > 0)
            {
                if (draw < 1)
                {
                    m_instructionsLabel.Text = "拉弦未完成 - 拖动来拉弦";
                }
                else
                {
                    m_instructionsLabel.Text = (arrowType == 0) ? "未装填 - 拖拽弹药到武器上" : "准备发射";
                }
                if ((draw < 1 || arrowType == 0)
                    && Input.Tap.HasValue
                    && HitTestGlobal(Input.Tap.Value) == m_inventorySlotWidget)
                {
                    Vector2 vector = m_inventorySlotWidget.ScreenToWidget(Input.Press.Value);
                    float num2 = vector.Y - DrawToPosition(draw);
                    if (Math.Abs(vector.X - m_inventorySlotWidget.ActualSize.X / 2f) < 25f
                        && Math.Abs(num2) < 25f)
                    {
                        m_dragStartOffset = num2;
                    }
                }
                if (!m_dragStartOffset.HasValue)
                {
                    return;
                }
                if (Input.Press.HasValue)
                {
                    int num3 = PositionToDraw(m_inventorySlotWidget.ScreenToWidget(Input.Press.Value).Y - m_dragStartOffset.Value);
                    SetDraw(num3);
                    if (draw <= 1 && num3 > 1)
                    {
                        AudioManager.PlaySound("Audio/CrossbowDraw", 1f, m_random.Float(-0.2f, 0.2f), 0f);
                    }
                }
                else
                {
                    m_dragStartOffset = null;
                    if (draw == 1)
                    {
                        AudioManager.PlaySound("Audio/UI/ItemMoved", 1f, 0f, 0f);
                        return;
                    }
                    SetDraw(0);
                    AudioManager.PlaySound("Audio/CrossbowBoing", draw, m_random.Float(-0.1f, 0.1f), 0f);
                }
            }
            else
            {
                ParentWidget.Children.Remove(this);
            }
        }

        public void SetDraw(int draw)
        {
            int slotValue = m_inventory.GetSlotValue(m_slotIndex);
            int data = Terrain.ExtractData(slotValue);
            int value = Terrain.MakeBlockValue(BlocksManager.GetBlockIndex<NewLongRangeWeaponsBlock>(), 0, NewLongRangeWeaponsBlock.SetDraw(data, draw));
            m_inventory.RemoveSlotItems(m_slotIndex, 1);
            m_inventory.AddSlotItems(m_slotIndex, value, 1);
        }

        public static float DrawToPosition(int draw)
        {
            return draw * 5.4f + 85f;
        }

        public static int PositionToDraw(float position)
        {
            return (int)Math.Clamp(Math.Round((position - 85f) / 5.4f), 0, 1);
        }
    }
}
//组件自动跳跃
namespace Game
{
    public class ComponentHYZLAutoJump : Component, IUpdateable
    {
        public SubsystemTime m_subsystemTime;
        public SubsystemTerrain m_subsystemTerrain;
        public ComponentCreature m_componentCreature;
        public double m_lastAutoJumpTime;
        public bool m_alwaysEnabled;
        public float m_jumpStrength;
        public bool m_collidedWithBody;

        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public virtual void Update(float dt)
        {
            if ((SettingsManager.AutoJump || m_alwaysEnabled) && m_subsystemTime.GameTime - m_lastAutoJumpTime > 0.25)
            {
                Vector2? lastWalkOrder = m_componentCreature.ComponentLocomotion.LastWalkOrder;
                if (lastWalkOrder.HasValue)
                {
                    Vector2 vector = new Vector2(
                        m_componentCreature.ComponentBody.CollisionVelocityChange.X,
                        m_componentCreature.ComponentBody.CollisionVelocityChange.Z
                    );

                    if (vector != Vector2.Zero && !m_collidedWithBody)
                    {
                        Vector2 v = Vector2.Normalize(vector);
                        Vector3 vector2 = m_componentCreature.ComponentBody.Matrix.Right * lastWalkOrder.Value.X
                            + m_componentCreature.ComponentBody.Matrix.Forward * lastWalkOrder.Value.Y;
                        Vector2 v2 = Vector2.Normalize(new Vector2(vector2.X, vector2.Z));

                        if (Vector2.Dot(v2, -v) > 0.6f)
                        {
                            Vector3 bodyPos = m_componentCreature.ComponentBody.Position;
                            Vector3 bodySize = m_componentCreature.ComponentBody.BoxSize;

                            // 根据生物体型大小确定检测范围
                            int detectionRange = (int)MathUtils.Max(bodySize.X, bodySize.Z) + 1;

                            bool shouldJump = false;

                            // 检测前方多个位置的方块
                            for (int i = 0; i < detectionRange; i++)
                            {
                                Vector3 checkPos = GetCheckPosition(bodyPos, v2, i);
                                Vector3 sidePos1 = GetSidePosition(checkPos, v2, -1);
                                Vector3 sidePos2 = GetSidePosition(checkPos, v2, 1);

                                if (CheckJumpCondition(checkPos, sidePos1, sidePos2))
                                {
                                    shouldJump = true;
                                    break;
                                }
                            }

                            if (shouldJump)
                            {
                                m_componentCreature.ComponentLocomotion.JumpOrder = MathUtils.Max(
                                    m_jumpStrength,
                                    m_componentCreature.ComponentLocomotion.JumpOrder
                                );
                                m_lastAutoJumpTime = m_subsystemTime.GameTime;
                            }
                        }
                    }
                }
            }
            m_collidedWithBody = false;
        }

        public Vector3 GetCheckPosition(Vector3 bodyPos, Vector2 direction, int offset)
        {
            if (Math.Abs(direction.X) > Math.Abs(direction.Y))
            {
                if (direction.X > 0)
                    return bodyPos + Vector3.UnitX * (1 + offset);
                else
                    return bodyPos - Vector3.UnitX * (1 + offset);
            }
            else
            {
                if (direction.Y > 0)
                    return bodyPos + Vector3.UnitZ * (1 + offset);
                else
                    return bodyPos - Vector3.UnitZ * (1 + offset);
            }
        }

        public Vector3 GetSidePosition(Vector3 checkPos, Vector2 direction, int sideOffset)
        {
            if (Math.Abs(direction.X) > Math.Abs(direction.Y))
            {
                return checkPos + Vector3.UnitZ * sideOffset;
            }
            else
            {
                return checkPos + Vector3.UnitX * sideOffset;
            }
        }

        public bool CheckJumpCondition(Vector3 checkPos, Vector3 sidePos1, Vector3 sidePos2)
        {
            int cellValue = m_subsystemTerrain.Terrain.GetCellValue(
                Terrain.ToCell(checkPos.X), Terrain.ToCell(checkPos.Y), Terrain.ToCell(checkPos.Z));
            int cellValue2 = m_subsystemTerrain.Terrain.GetCellValue(
                Terrain.ToCell(sidePos1.X), Terrain.ToCell(sidePos1.Y), Terrain.ToCell(sidePos1.Z));
            int cellValue3 = m_subsystemTerrain.Terrain.GetCellValue(
                Terrain.ToCell(sidePos2.X), Terrain.ToCell(sidePos2.Y), Terrain.ToCell(sidePos2.Z));

            int cellValue4 = m_subsystemTerrain.Terrain.GetCellValue(
                Terrain.ToCell(checkPos.X), Terrain.ToCell(checkPos.Y) + 1, Terrain.ToCell(checkPos.Z));
            int cellValue5 = m_subsystemTerrain.Terrain.GetCellValue(
                Terrain.ToCell(sidePos1.X), Terrain.ToCell(sidePos1.Y) + 1, Terrain.ToCell(sidePos1.Z));
            int cellValue6 = m_subsystemTerrain.Terrain.GetCellValue(
                Terrain.ToCell(sidePos2.X), Terrain.ToCell(sidePos2.Y) + 1, Terrain.ToCell(sidePos2.Z));

            int cellContents = Terrain.ExtractContents(cellValue);
            int cellContents2 = Terrain.ExtractContents(cellValue2);
            int cellContents3 = Terrain.ExtractContents(cellValue3);
            int cellContents4 = Terrain.ExtractContents(cellValue4);
            int cellContents5 = Terrain.ExtractContents(cellValue5);
            int cellContents6 = Terrain.ExtractContents(cellValue6);

            Block block = BlocksManager.Blocks[cellContents];
            Block block2 = BlocksManager.Blocks[cellContents2];
            Block block3 = BlocksManager.Blocks[cellContents3];
            Block block4 = BlocksManager.Blocks[cellContents4];
            Block block5 = BlocksManager.Blocks[cellContents5];
            Block block6 = BlocksManager.Blocks[cellContents6];

            return !block.NoAutoJump && (
                (block.IsCollidable_(cellValue) && !block4.IsCollidable_(cellValue4)) ||
                (block2.IsCollidable_(cellValue2) && !block5.IsCollidable_(cellValue5)) ||
                (block3.IsCollidable_(cellValue3) && !block6.IsCollidable_(cellValue6))
            );
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            m_subsystemTerrain = Project.FindSubsystem<SubsystemTerrain>(true);
            m_subsystemTime = Project.FindSubsystem<SubsystemTime>(true);
            m_componentCreature = Entity.FindComponent<ComponentCreature>(true);
            m_alwaysEnabled = valuesDictionary.GetValue<bool>("AlwaysEnabled");
            m_jumpStrength = valuesDictionary.GetValue<float>("JumpStrength");
            m_componentCreature.ComponentBody.CollidedWithBody += delegate { m_collidedWithBody = true; };
        }
    }
}
