//组件左手模型
namespace Game
{
    public class ComponentHandModel : Component, IDrawable, IUpdateable
    {
        public SubsystemTerrain m_subsystemTerrain;
        public ComponentMiner m_componentMiner;
        public ComponentPlayer m_componentPlayer;
        public ComponentRider m_componentRider;
        public SubsystemGameInfo m_subsystemGameInfo;

        public int m_value;
        public Model m_handModel;
        public Vector3? m_lastYpr;
        public Vector2 m_lagAngles;
        public float m_swapAnimationTime;
        public float m_pokeAnimationTime;

        public Vector3 m_itemOffset;
        public Vector3 m_itemRotation;
        public Vector3 m_handOffset;
        public Vector3 m_handRotation;

        public double m_nextHandLightTime;
        public float m_handLight;
        public int m_itemLight;

        public DrawBlockEnvironmentData m_drawBlockEnvironmentData = new DrawBlockEnvironmentData();
        public PrimitivesRenderer3D m_primitivesRenderer = new PrimitivesRenderer3D();

        public static LitShader LitShader = new LitShader(
            ShaderCodeManager.GetFast("Shaders/Lit.vsh"),
            ShaderCodeManager.GetFast("Shaders/Lit.psh"),
            2,
            useEmissionColor: false,
            useVertexColor: false,
            useTexture: true,
            useFog: false,
            useAlphaThreshold: false
        );

        public static int[] m_drawOrders = new int[1] { 1 };

        public HYZLInventory Inventory { get; set; }

        public Vector3 ItemOffsetOrder { get; set; }
        public Vector3 ItemRotationOrder { get; set; }
        public Vector3 HandOffsetOrder { get; set; }
        public Vector3 HandRotationOrder { get; set; }

        public int[] DrawOrders => m_drawOrders;
        public UpdateOrder UpdateOrder => UpdateOrder.FirstPersonModels;

        public int ActiveBlockValue
        {
            get
            {
                if (Inventory == null) return 0;
                return Inventory.GetSlotValue(Inventory.ActiveSlotIndex);
            }
        }

        public void Draw(Camera camera, int drawOrder)
        {
            if (m_componentPlayer.ComponentHealth.Health > 0f &&
                camera.GameWidget.IsEntityFirstPersonTarget(Entity) &&
                !m_componentPlayer.ComponentInput.IsControlledByVr)
            {
                Viewport viewport = Display.Viewport;
                Viewport viewport2 = viewport;
                viewport2.MaxDepth *= 0.1f;
                Display.Viewport = viewport2;

                try
                {
                    Matrix identity = CreateBaseAnimationMatrix();
                    Vector3 eyePosition = m_componentPlayer.ComponentCreatureModel.EyePosition;

                    Matrix m = Matrix.CreateFromQuaternion(m_componentPlayer.ComponentCreatureModel.EyeRotation);
                    m.Translation = eyePosition;

                    UpdateLighting(eyePosition);

                    if (m_value != 0)
                    {
                        DrawHeldItem(camera, identity, m, eyePosition);
                    }
                    else
                    {
                        DrawEmptyHand(camera, identity, m);
                    }
                }
                finally
                {
                    Display.Viewport = viewport;
                }
            }
        }

        public Matrix CreateBaseAnimationMatrix()
        {
            Matrix identity = Matrix.Identity;

            // 交换动画
            if (m_swapAnimationTime > 0f)
            {
                float swapFactor = MathUtils.Pow(MathUtils.Sin(m_swapAnimationTime * (float)Math.PI), 3f);
                identity *= Matrix.CreateTranslation(0f, -0.8f * swapFactor, 0.2f * swapFactor);
            }

            // 挖掘动画
            if (m_pokeAnimationTime > 0f)
            {
                float pokeFactor = MathUtils.Sin(MathUtils.Sqrt(m_pokeAnimationTime) * (float)Math.PI);
                if (m_value != 0)
                {
                    identity *= Matrix.CreateRotationX(-MathUtils.DegToRad(90f) * pokeFactor);
                    identity *= Matrix.CreateTranslation(-0.5f * pokeFactor, 0.1f * pokeFactor, 0f * pokeFactor);
                }
                else
                {
                    identity *= Matrix.CreateRotationX(-MathUtils.DegToRad(45f) * pokeFactor);
                    identity *= Matrix.CreateTranslation(-0.1f * pokeFactor, 0.2f * pokeFactor, -0.05f * pokeFactor);
                }
            }

            // 坐骑或行走动画
            if (m_componentRider.Mount != null)
            {
                ApplyMountAnimation(ref identity);
            }
            else
            {
                ApplyWalkAnimation(ref identity);
            }

            return identity;
        }

        public void ApplyMountAnimation(ref Matrix matrix)
        {
            ComponentCreatureModel mountModel = m_componentRider.Mount.Entity.FindComponent<ComponentCreatureModel>();
            if (mountModel != null)
            {
                float phase = mountModel.MovementAnimationPhase * (float)Math.PI * 2f + 0.5f;
                Vector3 position = new Vector3(0f, 0.02f * MathUtils.Sin(phase), 0.02f * MathUtils.Sin(phase));
                matrix *= Matrix.CreateRotationX(0.05f * MathUtils.Sin(phase * 1f)) * Matrix.CreateTranslation(position);
            }
        }

        public void ApplyWalkAnimation(ref Matrix matrix)
        {
            float phase = m_componentPlayer.ComponentCreatureModel.MovementAnimationPhase * (float)Math.PI * 2f;
            Vector3 position = new Vector3(
                0.03f * MathUtils.Sin(phase * 1f),
                0.02f * MathUtils.Sin(phase * 2f),
                0.02f * MathUtils.Sin(phase * 1f)
            );
            matrix *= Matrix.CreateRotationZ(1f * position.X) * Matrix.CreateTranslation(position);
        }

        public void UpdateLighting(Vector3 eyePosition)
        {
            int x = Terrain.ToCell(eyePosition.X);
            int y = Terrain.ToCell(eyePosition.Y);
            int z = Terrain.ToCell(eyePosition.Z);

            if (m_value != 0)
            {
                if (y >= 0 && y <= 255)
                {
                    TerrainChunk chunk = m_subsystemTerrain.Terrain.GetChunkAtCell(x, z);
                    if (chunk != null && chunk.State >= TerrainChunkState.InvalidVertices1)
                    {
                        m_itemLight = m_subsystemTerrain.Terrain.GetCellLightFast(x, y, z);
                    }
                }
            }
            else if (Time.FrameStartTime >= m_nextHandLightTime)
            {
                float? light = LightingManager.CalculateSmoothLight(m_subsystemTerrain, eyePosition);
                if (light.HasValue)
                {
                    m_nextHandLightTime = Time.FrameStartTime + 0.1;
                    m_handLight = light.Value;
                }
            }
        }

        public void DrawHeldItem(Camera camera, Matrix identity, Matrix viewMatrix, Vector3 eyePosition)
        {
            int blockId = Terrain.ExtractContents(m_value);
            Block block = BlocksManager.Blocks[blockId];

            int x = Terrain.ToCell(eyePosition.X);
            int z = Terrain.ToCell(eyePosition.Z);
            int y = Terrain.ToCell(eyePosition.Y);

            // 左手对称调整：X轴偏移取反，Y轴旋转取反
            Vector3 rotation = block.GetFirstPersonRotation(m_value) * ((float)Math.PI / 180f) + m_itemRotation;
            rotation.Y = -rotation.Y; // Y轴旋转对称

            Vector3 offset = block.GetFirstPersonOffset(m_value) + m_itemOffset;
            offset.X = -offset.X; // X轴偏移对称

            Matrix worldMatrix = Matrix.CreateFromYawPitchRoll(rotation.Y, rotation.X, rotation.Z)
                * identity
                * Matrix.CreateTranslation(offset)
                * Matrix.CreateFromYawPitchRoll(m_lagAngles.X, m_lagAngles.Y, 0f)
                * viewMatrix;

            Matrix viewWorldMatrix = worldMatrix * camera.ViewMatrix;

            m_drawBlockEnvironmentData.DrawBlockMode = DrawBlockMode.FirstPerson;
            m_drawBlockEnvironmentData.SubsystemTerrain = m_subsystemTerrain;
            m_drawBlockEnvironmentData.InWorldMatrix = worldMatrix;
            m_drawBlockEnvironmentData.Light = m_itemLight;
            m_drawBlockEnvironmentData.Humidity = m_subsystemTerrain.Terrain.GetSeasonalHumidity(x, z);
            m_drawBlockEnvironmentData.Temperature = m_subsystemTerrain.Terrain.GetSeasonalTemperature(x, z) +
                                                   SubsystemWeather.GetTemperatureAdjustmentAtHeight(y);
            m_drawBlockEnvironmentData.EnvironmentTemperature = m_componentPlayer.ComponentVitalStats.EnvironmentTemperature;
            m_drawBlockEnvironmentData.Owner = Entity;

            block.DrawBlock(m_primitivesRenderer, m_value, Color.White,
                          block.GetFirstPersonScale(m_value), ref viewWorldMatrix, m_drawBlockEnvironmentData);
            m_primitivesRenderer.Flush(camera.ProjectionMatrix);
        }

        public void DrawEmptyHand(Camera camera, Matrix identity, Matrix viewMatrix)
        {
            // 左手对称调整：X轴偏移取反，Y轴旋转取反
            Vector3 position = new Vector3(-0.25f, -0.3f, -0.05f) + m_handOffset; // X取反实现左右对称

            Matrix worldMatrix = Matrix.CreateScale(0.01f)
                * Matrix.CreateRotationX(0.8f)
                * Matrix.CreateRotationY(-0.4f) // Y旋转取反实现左右对称
                * identity
                * Matrix.CreateTranslation(position)
                * Matrix.CreateFromYawPitchRoll(m_lagAngles.X, m_lagAngles.Y, 0f)
                * viewMatrix
                * camera.ViewMatrix;

            SetupShader(camera, worldMatrix);
            RenderHandModel();
        }

        public void SetupShader(Camera camera, Matrix worldMatrix)
        {
            Display.DepthStencilState = DepthStencilState.Default;
            Display.RasterizerState = RasterizerState.CullCounterClockwiseScissor;

            LitShader.Texture = m_componentPlayer.ComponentCreatureModel.TextureOverride;
            LitShader.SamplerState = SamplerState.PointClamp;
            LitShader.MaterialColor = Vector4.One;
            LitShader.AmbientLightColor = new Vector3(m_handLight * LightingManager.LightAmbient);
            LitShader.DiffuseLightColor1 = new Vector3(m_handLight);
            LitShader.DiffuseLightColor2 = new Vector3(m_handLight);
            LitShader.LightDirection1 = Vector3.TransformNormal(LightingManager.DirectionToLight1, camera.ViewMatrix);
            LitShader.LightDirection2 = Vector3.TransformNormal(LightingManager.DirectionToLight2, camera.ViewMatrix);

            LitShader.Transforms.World[0] = worldMatrix;
            LitShader.Transforms.View = Matrix.Identity;
            LitShader.Transforms.Projection = camera.ProjectionMatrix;
        }

        public void RenderHandModel()
        {
            foreach (ModelMesh mesh in m_handModel.Meshes)
            {
                foreach (ModelMeshPart meshPart in mesh.MeshParts)
                {
                    Display.DrawIndexed(PrimitiveType.TriangleList, LitShader,
                                      meshPart.VertexBuffer, meshPart.IndexBuffer,
                                      meshPart.StartIndex, meshPart.IndicesCount);
                }
            }
        }

        public void Update(float dt)
        {
            UpdateHeadRotationLag(dt);
            UpdateActiveItem();
            UpdateAnimations(dt);
            UpdateOffsetsAndRotations(dt);
        }

        public void UpdateHeadRotationLag(float dt)
        {
            Vector3 currentYpr = m_componentPlayer.ComponentCreatureModel.EyeRotation.ToYawPitchRoll();
            m_lagAngles *= MathUtils.Pow(0.2f, dt);

            if (m_lastYpr.HasValue)
            {
                Vector3 delta = currentYpr - m_lastYpr.Value;
                m_lagAngles.X = MathUtils.Clamp(m_lagAngles.X - 0.08f * MathUtils.NormalizeAngle(delta.X), -0.1f, 0.1f);
                m_lagAngles.Y = MathUtils.Clamp(m_lagAngles.Y - 0.08f * MathUtils.NormalizeAngle(delta.Y), -0.1f, 0.1f);
            }
            m_lastYpr = currentYpr;
        }

        public void UpdateActiveItem()
        {
            int activeBlockValue = ActiveBlockValue;

            if (m_swapAnimationTime == 0f && activeBlockValue != m_value)
            {
                Block newBlock = BlocksManager.Blocks[Terrain.ExtractContents(activeBlockValue)];
                if (newBlock.IsSwapAnimationNeeded(m_value, activeBlockValue))
                {
                    m_swapAnimationTime = 0.0001f;
                }
                else
                {
                    m_value = activeBlockValue;
                }
            }
        }

        public void UpdateAnimations(float dt)
        {
            if (m_swapAnimationTime > 0f)
            {
                float oldTime = m_swapAnimationTime;
                m_swapAnimationTime += 2f * dt;

                if (oldTime < 0.5f && m_swapAnimationTime >= 0.5f)
                {
                    m_value = ActiveBlockValue;
                }

                if (m_swapAnimationTime > 1f)
                {
                    m_swapAnimationTime = 0f;
                }
            }

            m_pokeAnimationTime = m_componentMiner.PokingPhase;
        }

        public void UpdateOffsetsAndRotations(float dt)
        {
            float lerpFactor = MathUtils.Saturate(10f * dt);

            m_itemOffset = Vector3.Lerp(m_itemOffset, ItemOffsetOrder, lerpFactor);
            m_itemRotation = Vector3.Lerp(m_itemRotation, ItemRotationOrder, lerpFactor);
            m_handOffset = Vector3.Lerp(m_handOffset, HandOffsetOrder, lerpFactor);
            m_handRotation = Vector3.Lerp(m_handRotation, HandRotationOrder, lerpFactor);

            ItemOffsetOrder = Vector3.Zero;
            ItemRotationOrder = Vector3.Zero;
            HandOffsetOrder = Vector3.Zero;
            HandRotationOrder = Vector3.Zero;
        }

        public virtual void DamageActiveTool(int damageCount)
        {
            if (m_subsystemGameInfo.WorldSettings.GameMode == GameMode.Creative || Inventory == null)
            {
                return;
            }

            int damagedValue = BlocksManager.DamageItem(ActiveBlockValue, damageCount);
            if (damagedValue != 0)
            {
                int slotCount = Inventory.GetSlotCount(Inventory.ActiveSlotIndex);
                Inventory.RemoveSlotItems(Inventory.ActiveSlotIndex, slotCount);
                if (Inventory.GetSlotCount(Inventory.ActiveSlotIndex) == 0)
                {
                    Inventory.AddSlotItems(Inventory.ActiveSlotIndex, damagedValue, slotCount);
                }
            }
            else
            {
                Inventory.RemoveSlotItems(Inventory.ActiveSlotIndex, 1);
            }
        }

        public virtual void RemoveActiveTool(int removeCount)
        {
            Inventory?.RemoveSlotItems(Inventory.ActiveSlotIndex, removeCount);
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            Inventory = (HYZLInventory)Entity.FindComponent<ComponentHand>();
            m_subsystemTerrain = Project.FindSubsystem<SubsystemTerrain>(throwOnError: true);
            m_componentPlayer = Entity.FindComponent<ComponentPlayer>(throwOnError: true);
            m_componentRider = Entity.FindComponent<ComponentRider>(throwOnError: true);
            m_componentMiner = Entity.FindComponent<ComponentMiner>(throwOnError: true);
            m_subsystemGameInfo = Project.FindSubsystem<SubsystemGameInfo>(throwOnError: true);
            m_handModel = ContentManager.Get<Model>(valuesDictionary.GetValue<string>("HandModelName"));
        }
    }
}
//组件人类模型
namespace Game
{
    public class ComponentHYZLHumanModel : ComponentHumanModel
    {
        public ComponentHandModel componentHandModel;

        public override void Animate()
        {
            Vector3 position = m_componentCreature.ComponentBody.Position;
            Vector3 vector = m_componentCreature.ComponentBody.Rotation.ToYawPitchRoll();
            if (OnAnimate != null && OnAnimate()) return;
            if (m_lieDownFactorModel == 0f)
            {
                ComponentMount componentMount = (m_componentRider != null) ? m_componentRider.Mount : null;
                float num = MathUtils.Sin((float)Math.PI * 2f * MovementAnimationPhase);
                position.Y += Bob;
                vector.X += m_headingOffset;
                float num2 = (float)MathUtils.Remainder(0.75 * m_subsystemGameInfo.TotalElapsedGameTime + (GetHashCode() & 0xFFFF), 10000.0);
                float x = MathUtils.Clamp(MathUtils.Lerp(-0.3f, 0.3f, SimplexNoise.Noise(1.02f * num2 - 100f)) + m_componentCreature.ComponentLocomotion.LookAngles.X + 1f * m_componentCreature.ComponentLocomotion.LastTurnOrder.X + m_headingOffset, 0f - MathUtils.DegToRad(80f), MathUtils.DegToRad(80f));
                float y = MathUtils.Clamp(MathUtils.Lerp(-0.3f, 0.3f, SimplexNoise.Noise(0.96f * num2 - 200f)) + m_componentCreature.ComponentLocomotion.LookAngles.Y, 0f - MathUtils.DegToRad(45f), MathUtils.DegToRad(45f));
                float num3 = 0f;
                float y2 = 0f;
                float x2 = 0f;
                float y3 = 0f;
                float num4 = 0f;
                float num5 = 0f;
                float num6 = 0f;
                float num7 = 0f;
                if (componentMount != null)
                {
                    if (componentMount.Entity.ValuesDictionary.DatabaseObject.Name == "Boat")
                    {
                        position.Y -= 0.2f;
                        vector.X += (float)Math.PI;
                        num4 = 0.4f;
                        num6 = 0.4f;
                        num5 = 0.2f;
                        num7 = -0.2f;
                        num3 = 1.1f;
                        x2 = 1.1f;
                        y2 = 0.2f;
                        y3 = -0.2f;
                    }
                    else
                    {
                        num4 = 0.5f;
                        num6 = 0.5f;
                        num5 = 0.15f;
                        num7 = -0.15f;
                        y2 = 0.55f;
                        y3 = -0.55f;
                    }
                }
                else if (m_componentCreature.ComponentLocomotion.IsCreativeFlyEnabled)
                {
                    float num8 = m_componentCreature.ComponentLocomotion.LastWalkOrder.HasValue ? MathUtils.Min(0.03f * m_componentCreature.ComponentBody.Velocity.XZ.LengthSquared(), 0.5f) : 0f;
                    num3 = -0.1f - num8;
                    x2 = num3;
                    y2 = MathUtils.Lerp(0f, 0.25f, SimplexNoise.Noise(1.07f * num2 + 400f));
                    y3 = 0f - MathUtils.Lerp(0f, 0.25f, SimplexNoise.Noise(0.93f * num2 + 500f));
                }
                else if (MovementAnimationPhase != 0f)
                {
                    num4 = -0.5f * num;
                    num6 = 0.5f * num;
                    num3 = m_walkLegsAngle * num;
                    x2 = 0f - num3;
                }
                float num9 = 0f;
                if (m_componentMiner != null)
                {
                    float num10 = MathUtils.Sin(MathUtils.Sqrt(m_componentMiner.PokingPhase) * (float)Math.PI);
                    num9 = ((m_componentMiner.ActiveBlockValue == 0) ? (1f * num10) : (0.3f + 1f * num10));
                }
                float num50 = 0f;
                if (componentHandModel != null)
                {
                    float num10 = MathUtils.Sin(MathUtils.Sqrt(0f) * (float)Math.PI);
                    num50 = ((componentHandModel.ActiveBlockValue == 0) ? (1f * num10) : (0.3f + 1f * num10));
                }
                float num11 = (m_punchPhase != 0f) ? ((0f - MathUtils.DegToRad(90f)) * MathUtils.Sin((float)Math.PI * 2f * MathUtils.Sigmoid(m_punchPhase, 4f))) : 0f;
                float num12 = ((m_punchCounter & 1) == 0) ? num11 : 0f;
                float num13 = ((m_punchCounter & 1) != 0) ? num11 : 0f;
                float num14 = 0f;
                float num15 = 0f;
                float num16 = 0f;
                float num17 = 0f;
                if (m_rowLeft || m_rowRight)
                {
                    float num18 = 0.6f * (float)MathUtils.Sin(6.91150426864624 * m_subsystemTime.GameTime);
                    float num19 = 0.2f + 0.2f * (float)MathUtils.Cos(6.91150426864624 * (m_subsystemTime.GameTime + 0.5));
                    if (m_rowLeft)
                    {
                        num14 = num18;
                        num15 = num19;
                    }
                    if (m_rowRight)
                    {
                        num16 = num18;
                        num17 = 0f - num19;
                    }
                }
                float num20 = 0f;
                float num21 = 0f;
                float num22 = 0f;
                float num23 = 0f;
                if (m_aimHandAngle != 0f)
                {
                    num20 = 1.5f;
                    num21 = -0.7f;
                    num22 = m_aimHandAngle * 1f;
                    num23 = 0f;
                }
                float num24 = (!m_componentCreature.ComponentLocomotion.IsCreativeFlyEnabled) ? 1 : 4;
                num4 += num50 + MathUtils.Lerp(-0.1f, 0.1f, SimplexNoise.Noise(num2)) + num12 + num14 + num20;
                num5 += MathUtils.Lerp(0f, num24 * 0.15f, SimplexNoise.Noise(1.1f * num2 + 100f)) + num15 + num21;
                num6 += num9 + MathUtils.Lerp(-0.1f, 0.1f, SimplexNoise.Noise(0.9f * num2 + 200f)) + num13 + num16 + num22;
                num7 += 0f - MathUtils.Lerp(0f, num24 * 0.15f, SimplexNoise.Noise(1.05f * num2 + 300f)) + num17 + num23;
                float s = MathUtils.Min(12f * m_subsystemTime.GameTimeDelta, 1f);
                m_headAngles += s * (new Vector2(x, y) - m_headAngles);
                m_handAngles1 += s * (new Vector2(num4, num5) - m_handAngles1);
                m_handAngles2 += s * (new Vector2(num6, num7) - m_handAngles2);
                m_legAngles1 += s * (new Vector2(num3, y2) - m_legAngles1);
                m_legAngles2 += s * (new Vector2(x2, y3) - m_legAngles2);
                if (m_componentCreature.ComponentBody.CrouchFactor == 1)
                {
                    m_legAngles1 *= 0.5f;
                    m_legAngles2 *= 0.5f;
                }
                float f = MathUtils.Sigmoid(m_componentCreature.ComponentBody.CrouchFactor, 4f);
                Vector3 position2 = new Vector3(0f, MathUtils.Lerp(0f, 4f, f), MathUtils.Lerp(0f, -3.3f, f));
                Vector3 position3 = new Vector3(position.X, position.Y - MathUtils.Lerp(0f, 0.7f, f), position.Z);
                Vector3 position4 = new Vector3(0f, MathUtils.Lerp(0f, 7f, f), MathUtils.Lerp(0f, 28f, f));
                Vector3 scale = new Vector3(1f, 1f, MathUtils.Lerp(1f, 0.5f, f));
                SetBoneTransform(m_bodyBone.Index, Matrix.CreateRotationY(vector.X) * Matrix.CreateTranslation(position3));
                SetBoneTransform(m_headBone.Index, Matrix.CreateRotationX(m_headAngles.Y) * Matrix.CreateRotationZ(0f - m_headAngles.X));
                SetBoneTransform(m_hand1Bone.Index, Matrix.CreateRotationY(m_handAngles1.Y) * Matrix.CreateRotationX(m_handAngles1.X));
                SetBoneTransform(m_hand2Bone.Index, Matrix.CreateRotationY(m_handAngles2.Y) * Matrix.CreateRotationX(m_handAngles2.X));
                SetBoneTransform(m_leg1Bone.Index, Matrix.CreateRotationY(m_legAngles1.Y) * Matrix.CreateRotationX(m_legAngles1.X) * Matrix.CreateTranslation(position4) * Matrix.CreateScale(scale));
                SetBoneTransform(m_leg2Bone.Index, Matrix.CreateRotationY(m_legAngles2.Y) * Matrix.CreateRotationX(m_legAngles2.X) * Matrix.CreateTranslation(position4) * Matrix.CreateScale(scale));
            }
            else
            {
                float num25 = MathUtils.Max(DeathPhase, m_lieDownFactorModel);
                float num26 = 1f - num25;
                Vector3 position2 = position + num25 * 0.5f * m_componentCreature.ComponentBody.BoxSize.Y * Vector3.Normalize(m_componentCreature.ComponentBody.Matrix.Forward * new Vector3(1f, 0f, 1f)) + num25 * Vector3.UnitY * m_componentCreature.ComponentBody.BoxSize.Z * 0.1f;
                SetBoneTransform(m_bodyBone.Index, Matrix.CreateFromYawPitchRoll(vector.X, (float)Math.PI / 2f * num25, 0f) * Matrix.CreateTranslation(position2));
                SetBoneTransform(m_headBone.Index, Matrix.Identity);
                SetBoneTransform(m_hand1Bone.Index, Matrix.CreateRotationY(m_handAngles1.Y * num26) * Matrix.CreateRotationX(m_handAngles1.X * num26));
                SetBoneTransform(m_hand2Bone.Index, Matrix.CreateRotationY(m_handAngles2.Y * num26) * Matrix.CreateRotationX(m_handAngles2.X * num26));
                SetBoneTransform(m_leg1Bone.Index, Matrix.CreateRotationY(m_legAngles1.Y * num26) * Matrix.CreateRotationX(m_legAngles1.X * num26));
                SetBoneTransform(m_leg2Bone.Index, Matrix.CreateRotationY(m_legAngles2.Y * num26) * Matrix.CreateRotationX(m_legAngles2.X * num26));
            }
        }

        public override void DrawExtras(Camera camera)
        {
            if (m_componentCreature.ComponentHealth.Health > 0f && componentHandModel != null && componentHandModel.ActiveBlockValue != 0)
            {
                int num = Terrain.ExtractContents(componentHandModel.ActiveBlockValue);
                Block block = BlocksManager.Blocks[num];
                Matrix m = AbsoluteBoneTransformsForCamera[m_hand1Bone.Index];
                m *= camera.InvertedViewMatrix;
                m.Right = Vector3.Normalize(m.Right);
                m.Up = Vector3.Normalize(m.Up);
                m.Forward = Vector3.Normalize(m.Forward);
                Vector3 InhandRotation = block.GetInHandRotation(componentHandModel.ActiveBlockValue);
                Matrix matrix = Matrix.CreateRotationY(MathUtils.DegToRad(InhandRotation.Y) + m_inHandItemRotation.Y) * Matrix.CreateRotationZ(MathUtils.DegToRad(InhandRotation.Z) + m_inHandItemRotation.Z) * Matrix.CreateRotationX(MathUtils.DegToRad(InhandRotation.X) + m_inHandItemRotation.X) * Matrix.CreateTranslation(block.GetInHandOffset(componentHandModel.ActiveBlockValue) + m_inHandItemOffset) * Matrix.CreateTranslation(new Vector3(-0.05f, 0.05f, -0.56f) * (m_componentCreature.ComponentBody.BoxSize.Y / 1.77f)) * m;
                int x = Terrain.ToCell(matrix.Translation.X);
                int y = Terrain.ToCell(matrix.Translation.Y);
                int z = Terrain.ToCell(matrix.Translation.Z);
                m_drawBlockEnvironmentData.DrawBlockMode = DrawBlockMode.ThirdPerson;
                m_drawBlockEnvironmentData.InWorldMatrix = matrix;
                m_drawBlockEnvironmentData.Humidity = m_subsystemTerrain.Terrain.GetSeasonalHumidity(x, z);
                m_drawBlockEnvironmentData.Temperature = m_subsystemTerrain.Terrain.GetSeasonalTemperature(x, z) + SubsystemWeather.GetTemperatureAdjustmentAtHeight(y);
                m_drawBlockEnvironmentData.Light = m_subsystemTerrain.Terrain.GetCellLight(x, y, z);
                m_drawBlockEnvironmentData.BillboardDirection = -Vector3.UnitZ;
                m_drawBlockEnvironmentData.SubsystemTerrain = m_subsystemTerrain;
                Matrix matrix2 = matrix * camera.ViewMatrix;
                block.DrawBlock(m_subsystemModelsRenderer.PrimitivesRenderer, componentHandModel.ActiveBlockValue, Color.White, block.GetInHandScale(componentHandModel.ActiveBlockValue), ref matrix2, m_drawBlockEnvironmentData);
            }
            base.DrawExtras(camera);
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            componentHandModel = Entity.FindComponent<ComponentHandModel>();
        }
    }
}
//衣服大全
namespace Game
{
    public class ClothingHYZLData : ClothingData
    {
        public float Defense;

        public float EvasionRate;

        public ClothingHYZLData() { }

        public ClothingHYZLData(XElement item)
        {
            int.TryParse(item.Attribute("Index").Value, out int ClothIndex);
            ClothIndex &= 0x3FF;
            string newDescription = item.Attribute("Description")?.Value;
            string newDisplayName = item.Attribute("DisplayName")?.Value;
            if (newDescription != null
                && newDescription.StartsWith('[')
                && newDescription.EndsWith(']')
                && LanguageControl.TryGetBlock($"{typeof(ClothingBlock).Name}:{ClothIndex}", "Description", out string d))
            {
                newDescription = d;
            }
            if (newDisplayName != null
                && newDisplayName.StartsWith('[')
                && newDisplayName.EndsWith(']')
                && LanguageControl.TryGetBlock($"{typeof(ClothingBlock).Name}:{ClothIndex}", "DisplayName", out string n))
            {
                newDisplayName = n;
            }
            xElement = item;
            Index = ClothIndex;
            DisplayName = newDisplayName;
            string slotName = XmlUtils.GetAttributeValue<string>(item, "Slot");
            Slot = ClothingSlot.ClothingSlots[slotName];
            ArmorProtection = XmlUtils.GetAttributeValue<float>(item, "ArmorProtection");
            Sturdiness = XmlUtils.GetAttributeValue<float>(item, "Sturdiness");
            Insulation = XmlUtils.GetAttributeValue<float>(item, "Insulation");
            MovementSpeedFactor = XmlUtils.GetAttributeValue<float>(item, "MovementSpeedFactor");
            SteedMovementSpeedFactor = XmlUtils.GetAttributeValue<float>(item, "SteedMovementSpeedFactor");
            DensityModifier = XmlUtils.GetAttributeValue<float>(item, "DensityModifier");
            IsOuter = XmlUtils.GetAttributeValue<bool>(item, "IsOuter");
            CanBeDyed = XmlUtils.GetAttributeValue<bool>(item, "CanBeDyed");
            Layer = XmlUtils.GetAttributeValue<int>(item, "Layer");
            PlayerLevelRequired = XmlUtils.GetAttributeValue<int>(item, "PlayerLevelRequired");
            Texture = ContentManager.Get<Texture2D>(XmlUtils.GetAttributeValue<string>(item, "TextureName"));
            ImpactSoundsFolder = XmlUtils.GetAttributeValue<string>(item, "ImpactSoundsFolder");
            Defense = XmlUtils.GetAttributeValue<float>(item, "Defense");
            EvasionRate = XmlUtils.GetAttributeValue<float>(item, "EvasionRate", 0);
            Description = newDescription;
        }

        /// <summary>
        ///     在ComponentClothing执行SetClothes()时触发，用于调整ComponentClothing中的一些参数
        /// </summary>
        /// <param name="componentClothing"></param>
        public override void OnClotheSet(ComponentClothing componentClothing)
        {
            base.OnClotheSet(componentClothing);
            if (componentClothing.Entity.FindComponent<ComponentPhysicalAttributes>().ClothingAttributes.TryGetValue(Slot, out (float, float) value) && (value.Item1 == 0 && value.Item2 == 0))
            {
                componentClothing.Entity.FindComponent<ComponentPhysicalAttributes>().ClothingAttributes[Slot] = (value.Item1 + Defense, value.Item2 + EvasionRate);
            }
        }
    }
}
