//组件钓鱼
namespace Game
{
    public class ComponentFishing : Component, IUpdateable, IDrawable
    {
        public SubsystemTerrain m_systemTerrain;
        public SubsystemTime m_subsystemTime;
        public ComponentPlayer m_componentPlayer;
        public ComponentCreature m_componentCreature;
        public SubsystemFluidBlockBehavior m_fluidBlockBehavior;
        public ComponentBody m_componentBody;
        public SubsystemSeasons m_subsystemSeasons;
        public SubsystemAudio m_subsystemAudio;
        public SubsystemParticles m_subsystemParticles;
        public SubsystemNewInteroperableCubeBlockBehavior subsystemNewInteroperableCubeBlockBehavior;

        // 钓鱼状态变量
        public static Vector3 FishingVector;
        public static Vector3 ToDrawFishingVector;
        public static float HoldLastTime = 1f;
        public static bool IsFishing;
        public static double lastfishingtime;
        public static bool IsChangedDirection;
        public Random random = new Random();
        public bool isonTrain;

        // 新增：钓鱼时间控制
        public double m_fishingStartTime;
        public double m_fishingDuration = 25; // 30分钟（秒）
        public bool m_isWaitingForFish;
        public bool m_fishCaught;
        public bool m_timeMessageShown; // 时间提示只显示一次

        public PrimitivesRenderer3D primitivesRenderer = new PrimitivesRenderer3D();
        public int[] DrawOrders => new int[1] { 1 };
        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public float Gravity => 10 - g;
        public float g;

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            m_subsystemAudio = base.Project.FindSubsystem<SubsystemAudio>(throwOnError: true);
            m_subsystemParticles = base.Project.FindSubsystem<SubsystemParticles>(throwOnError: true);
            m_systemTerrain = Project.FindSubsystem<SubsystemTerrain>(true);
            m_componentCreature = Entity.FindComponent<ComponentCreature>(true);
            m_fluidBlockBehavior = Project.FindSubsystem<SubsystemFluidBlockBehavior>(true);
            m_subsystemTime = Project.FindSubsystem<SubsystemTime>(true);
            m_componentPlayer = Entity.FindComponent<ComponentPlayer>(true);
            m_componentBody = Entity.FindComponent<ComponentBody>(true);
            m_subsystemSeasons = Project.FindSubsystem<SubsystemSeasons>(true);
            subsystemNewInteroperableCubeBlockBehavior = Project.FindSubsystem<SubsystemNewInteroperableCubeBlockBehavior>(true);
            isonTrain = valuesDictionary.GetValue<bool>("isonTrain", false);
            base.Load(valuesDictionary, idToEntityMap);
        }

        public override void Save(ValuesDictionary valuesDictionary, EntityToIdMap entityToIdMap)
        {
            base.Save(valuesDictionary, entityToIdMap);
            valuesDictionary.SetValue<bool>("isonTrain", isonTrain);
        }

        public void Update(float dt)
        {
            // 处理钓鱼等待时间
            if (m_isWaitingForFish)
            {
                // 等待时时间加速
                m_subsystemTime.m_gameTimeFactor = 50;

                double currentTime = m_subsystemTime.GameTime;
                double elapsedTime = currentTime - m_fishingStartTime;

                if (elapsedTime >= m_fishingDuration)
                {
                    // 恢复正常时间流速
                    m_subsystemTime.m_gameTimeFactor = 1;

                    // 30分钟到了，随机决定是否有鱼上钩
                    m_fishCaught = random.Bool(0.6f); // 70%概率有鱼上钩

                    if (m_fishCaught)
                    {
                        IsFishing = true;
                        lastfishingtime = currentTime;
                        m_componentPlayer.ComponentGui.DisplaySmallMessage("有鱼上钩了！快收杆！", Color.Green, true, true);
                        m_subsystemAudio.PlayRandomSound("Audio/UI/Fishing/Close", 5, random.Float(-0.3f, 0f), 0, 0);
                    }
                    else
                    {
                        m_subsystemAudio.PlayRandomSound("Audio/UI/Fishing/AirFishing", 5, random.Float(-0.3f, 0f), 0, 0);
                        m_componentPlayer.ComponentGui.DisplaySmallMessage("等了30分钟，没有鱼上钩！", Color.Yellow, true, true);
                        ResetFishingState();
                    }

                    m_isWaitingForFish = false;
                }
                else if (!m_timeMessageShown)
                {
                    // 只显示一次时间提示
                    m_componentPlayer.ComponentGui.DisplaySmallMessage("开始钓鱼，时间加速中...", Color.Blue, true, true);
                    m_timeMessageShown = true;
                }
            }
        }

        public void Draw(Camera camera, int drawOrder)
        {
            FlatBatch3D flatBatch3D = primitivesRenderer.FlatBatch();
            var subsystemTime = Entity.Project.FindSubsystem<SubsystemTime>();
            var FishingWidget = m_componentPlayer.Entity.FindComponent<ComponentHYZLGui>().FishingButton;
            var FishingRoundRange = m_componentPlayer.Entity.FindComponent<ComponentHYZLGui>().FishingRoundRange;
            var FishingCaptureBar = m_componentPlayer.Entity.FindComponent<ComponentHYZLGui>().FishingCaptureBar;

            ComponentMiner componentMiner = m_componentPlayer.ComponentMiner;

            if (Terrain.ExtractContents(componentMiner.ActiveBlockValue) == NewToolsBlock.Index && (NewToolsBlock.GetType(componentMiner.ActiveBlockValue) == 3 || NewToolsBlock.GetType(componentMiner.ActiveBlockValue) == 6))
            {
                var camera1 = m_componentPlayer.GameWidget.FindCamera<FppCamera>();
                Point3 playerposition = Terrain.ToCell(m_componentPlayer.ComponentBody.Position);
                Vector3 V3playerposition = m_componentPlayer.ComponentBody.Position;

                if (camera1 != null)
                {
                    Vector3 cameraPosition = camera1.ViewPosition;
                    Vector3 cameraDirection = camera1.ViewDirection;
                    Vector3 cameraDown = -camera.ViewUp;
                    float offsetDown = 0.5f;
                    Vector3 lineStartPosition = cameraPosition + cameraDown * offsetDown;
                    float raycastDistance = 20f;
                    Vector3 rayEndPoint = cameraPosition + cameraDirection * raycastDistance;

                    var subsystemTerrain = Entity.Project.FindSubsystem<SubsystemTerrain>();
                    TerrainRaycastResult? raycastResult = subsystemTerrain.Raycast(cameraPosition, rayEndPoint, false, true, (value, distance) => true);

                    if (raycastResult.HasValue)
                    {
                        TerrainRaycastResult result = raycastResult.Value;
                        Vector3 hitPosition = result.HitPoint();
                        int blockValue = result.Value;
                        int blockType = Terrain.ExtractContents(blockValue);
                        bool isWaterBlock = blockType == 18;

                        flatBatch3D.QueueLine(lineStartPosition, hitPosition, Color.Red);
                        QueueTorusSector(flatBatch3D, hitPosition, 2f, 0.5f, 0.5f, isWaterBlock ? Color.Green : Color.Blue, value: 0.75f);
                        flatBatch3D.Flush(camera1.ViewProjectionMatrix);

                        if (isWaterBlock)
                        {
                            if (FishingWidget != null) FishingWidget.IsVisible = true;

                            // 钓鱼逻辑
                            if (FishingWidget.IsClicked)
                            {
                                if (isWaterBlock)
                                {
                                    PlayWaterEffects(V3playerposition, hitPosition);
                                }

                                m_componentPlayer.ComponentMiner.DamageActiveTool(1);

                                if (FishingWidget.IsChecked && !m_isWaitingForFish && !IsFishing)
                                {
                                    // 开始钓鱼等待
                                    StartFishingWait(hitPosition, subsystemTime);
                                }
                                else if (!FishingWidget.IsChecked && IsFishing)
                                {
                                    // 收杆操作
                                    HandleFishingResult(FishingRoundRange, FishingCaptureBar, V3playerposition, hitPosition);
                                }
                                else if (!FishingWidget.IsChecked && m_isWaitingForFish)
                                {
                                    // 取消钓鱼等待
                                    m_subsystemTime.m_gameTimeFactor = 1; // 恢复时间
                                    ResetFishingState();
                                    m_componentPlayer.ComponentGui.DisplaySmallMessage("钓鱼已取消", Color.Yellow, true, true);
                                }
                            }

                            if (FishingWidget.IsChecked && (m_isWaitingForFish || IsFishing))
                            {
                                FishingRoundRange.IsVisible = true;
                                FishingCaptureBar.IsVisible = true;

                                if (FishingWidget.Input.m_touchHoldInProgress)
                                    HoldLastTime = MathUtils.Min(HoldLastTime + 0.01f, 4f);

                                if (IsFishing)
                                {
                                    UpdateFishingAnimation(FishingRoundRange, FishingCaptureBar, subsystemTime);
                                }
                            }
                            else
                            {
                                FishingRoundRange.IsVisible = false;
                                FishingCaptureBar.IsVisible = false;
                            }
                        }
                        else
                        {
                            HideFishingUI(FishingWidget, FishingRoundRange, FishingCaptureBar);
                        }
                    }
                    else
                    {
                        HideFishingUI(FishingWidget, FishingRoundRange, FishingCaptureBar);
                    }
                }
            }
            else
            {
                ClearFishingUI(FishingWidget, FishingRoundRange, FishingCaptureBar);
            }
        }

        // 开始钓鱼等待
        public void StartFishingWait(Vector3 hitPosition, SubsystemTime subsystemTime)
        {
            m_subsystemAudio.PlayRandomSound("Audio/UI/Fishing/Swing", 5, random.Float(-0.3f, 0f), 0, 0);
            FishingVector = CalculateFishingPoint(m_componentPlayer.ComponentBody.Position + m_componentPlayer.ComponentBody.Matrix.Forward * 1.5f * HoldLastTime);
            ToDrawFishingVector = FishingVector;
            m_fishingStartTime = subsystemTime.GameTime;
            m_isWaitingForFish = true;
            m_fishCaught = false;
            m_timeMessageShown = false;
        }

        // 处理钓鱼结果
        public void HandleFishingResult(RoundProgressWidget FishingRoundRange, RoundProgressWidget FishingCaptureBar, Vector3 playerPosition, Vector3 hitPosition)
        {
            // 检查捕获条件
            m_componentPlayer.PlayerStats.ValuesDictionaryForMods["FishingCount"] = (m_componentPlayer.PlayerStats.ValuesDictionaryForMods.ContainsKey("FishingCount") ? (int)m_componentPlayer.PlayerStats.ValuesDictionaryForMods["FishingCount"] + 1 : 1);
            subsystemNewInteroperableCubeBlockBehavior.CurrentCapacityAdd(1, 0);
            if (FishingRoundRange.RoundRange.X + FishingRoundRange.StartValue <= FishingCaptureBar.RoundRange.X &&
                FishingCaptureBar.RoundRange.X <= FishingRoundRange.RoundRange.Y * FishingRoundRange.Value)
            {
                TryGenerateFish(playerPosition, hitPosition);
            }
            else
            {
                m_componentPlayer.ComponentGui.DisplaySmallMessage("鱼儿跑掉了！", Color.Red, true, true);
                m_subsystemAudio.PlayRandomSound("Audio/UI/Fishing/RunAway", 5, random.Float(-0.3f, 0f), 0, 0);
            }

            ResetFishingState();
            FishingCaptureBar.RoundRange = new Vector2(-0.375f, -0.35f);
        }

        // 尝试生成鱼
        public void TryGenerateFish(Vector3 playerPosition, Vector3 hitPosition)
        {
            float Temperature = m_componentPlayer.ComponentVitalStats.Temperature;
            float Days = (float)Math.Floor(m_componentPlayer.m_subsystemGameInfo.TotalElapsedGameTime / 1200);
            float TotalElapsedGameTime = (float)m_componentPlayer.m_subsystemGameInfo.TotalElapsedGameTime - Days * 1200;
            Season Season = m_subsystemSeasons.Season;
            HYZLInventory inventory = (HYZLInventory)m_componentPlayer.Entity.FindComponent<ComponentFishBait>();
            int FishBaitValue = inventory.GetSlotValue(inventory.ActiveSlotIndex);
            int FishBaitCount = inventory.GetSlotCount(inventory.ActiveSlotIndex);

            bool fishGenerated = false;

            for (int i = 0; i < AccessNewFishManager.Data.Count; i++)
            {
                if (random.Bool(AccessNewFishManager.Get(i).Probability) &&
                    ((AccessNewFishManager.Get(i).Cloudy != null && m_componentPlayer.ComponentInput.m_playerInput.Precipitation == AccessNewFishManager.Get(i).Cloudy) || AccessNewFishManager.Get(i).Cloudy == null) &&
                    ((AccessNewFishManager.Get(i).Days != null && Days >= AccessNewFishManager.Get(i).Days) || AccessNewFishManager.Get(i).Days == null) &&
                    (((AccessNewFishManager.Get(i).Season1 != null && Season == AccessNewFishManager.Get(i).Season1) || (AccessNewFishManager.Get(i).Season2 != null && Season == AccessNewFishManager.Get(i).Season2)) ||
                    (AccessNewFishManager.Get(i).Season1 == null || AccessNewFishManager.Get(i).Season2 == null)) &&
                    ((AccessNewFishManager.Get(i).MinimumTemperature != null && Temperature >= AccessNewFishManager.Get(i).MinimumTemperature && Temperature <= AccessNewFishManager.Get(i).MaximumTemperature) || AccessNewFishManager.Get(i).MinimumTemperature == null) &&
                    ((AccessNewFishManager.Get(i).TheEarliestTime != null && TotalElapsedGameTime >= AccessNewFishManager.Get(i).TheEarliestTime && TotalElapsedGameTime <= AccessNewFishManager.Get(i).TheLatestTime) || AccessNewFishManager.Get(i).TheEarliestTime == null) &&
                    ((AccessNewFishManager.Get(i).FishBait != null && CraftingRecipesManager.DecodeResult(AccessNewFishManager.Get(i).FishBait) == FishBaitValue && FishBaitCount > 0) || AccessNewFishManager.Get(i).FishBait == null))
                {
                    m_componentPlayer.Entity.FindComponent<ComponentFishBait>().RemoveSlotItems(inventory.ActiveSlotIndex, 1);
                    PlayWaterEffects(playerPosition, hitPosition);
                    GenerateFishItem(hitPosition, i);
                    fishGenerated = true;
                    break;
                }
            }

            if (!fishGenerated)
            {
                m_componentPlayer.ComponentGui.DisplaySmallMessage("钓到了一些杂物...", Color.Gray, true, true);

                m_subsystemAudio.PlayRandomSound("Audio/UI/Fishing/CatchSomeSundries", 5, random.Float(-0.3f, 0f), 0, 0);
            }
        }

        // 生成鱼物品
        public void GenerateFishItem(Vector3 hitPosition, int fishBlockID)
        {
            Vector3 fishingPoint = new Vector3(hitPosition.X, hitPosition.Y + 1, hitPosition.Z);
            Vector3 playerPosition = m_componentPlayer.ComponentBody.Position + new Vector3(0f, 1f, 0f);
            Vector3 flyToPosition = playerPosition;
            Vector3 directionToPlayer = Vector3.Normalize(playerPosition - fishingPoint);
            Vector3 initialVelocity = directionToPlayer * 6f + Vector3.UnitY * 5f;

            var pickable = Entity.Project.FindSubsystem<SubsystemPickables>().AddPickable(
                Terrain.MakeBlockValue(NewFish.Index, 0, fishBlockID),
                1,
                fishingPoint,
                initialVelocity,
                null
            );

            if (pickable != null)
            {
                pickable.FlyToPosition = flyToPosition;
            }

            m_componentPlayer.ComponentGui.ModalPanelWidget = new FishingWidget(m_componentPlayer, Terrain.MakeBlockValue(NewFish.Index, 0, fishBlockID));
            m_componentPlayer.ComponentGui.DisplaySmallMessage("成功钓到一条鱼！", Color.Green, true, true);
            m_componentPlayer.PlayerStats.ValuesDictionaryForMods["NumberOfHooks"] = (m_componentPlayer.PlayerStats.ValuesDictionaryForMods.ContainsKey("NumberOfHooks") ? (int)m_componentPlayer.PlayerStats.ValuesDictionaryForMods["NumberOfHooks"] + 1 : 1);
            m_subsystemAudio.PlayRandomSound("Audio/UI/Fishing/TakeTheBait", 5, random.Float(-0.3f, 0f), 0, 0);
        }

        // 更新钓鱼动画
        public void UpdateFishingAnimation(RoundProgressWidget FishingRoundRange, RoundProgressWidget FishingCaptureBar, SubsystemTime subsystemTime)
        {
            ToDrawFishingVector = FishingVector + (Time.RealTime % 2 == 0 ?
                new Vector3(0f, MathUtils.Min(random.Float(0.4f, 1.2f), 1.5f), 0f) :
                new Vector3(0f, -MathUtils.Min(random.Float(0.4f, 1.2f), 1.5f), 0f));

            if ((FishingCaptureBar.RoundRange.X == FishingRoundRange.RoundRange.Y && IsChangedDirection) ||
                (FishingCaptureBar.RoundRange.X == FishingRoundRange.RoundRange.X && !IsChangedDirection))
            {
                IsChangedDirection = !IsChangedDirection;
            }

            if (subsystemTime.GameTime - lastfishingtime > 8)
            {
                var fishingButton = m_componentPlayer.Entity.FindComponent<ComponentHYZLGui>().FishingButton;
                if (fishingButton != null) fishingButton.IsChecked = false;
            }

            FishingCaptureBar.RoundRange = new Vector2(
                IsChangedDirection ? MathUtils.Min(FishingCaptureBar.RoundRange.X + 0.0025f, FishingRoundRange.RoundRange.Y) :
                MathUtils.Max(FishingCaptureBar.RoundRange.X - 0.0025f, FishingRoundRange.RoundRange.X),
                MathUtils.Min(FishingCaptureBar.RoundRange.X + 0.025f, FishingRoundRange.RoundRange.Y)
            );
        }

        // 重置钓鱼状态
        public void ResetFishingState()
        {
            IsFishing = false;
            m_isWaitingForFish = false;
            m_fishCaught = false;
            m_timeMessageShown = false;
            FishingVector = Vector3.Zero;
            HoldLastTime = 1f;
            lastfishingtime = 0;
            ToDrawFishingVector = Vector3.Zero;
        }

        // 播放水效果
        public void PlayWaterEffects(Vector3 position, Vector3 hitPosition)
        {
            m_subsystemAudio.PlayRandomSound("Audio/WaterFallIn", random.Float(0.75f, 1f), random.Float(-0.3f, 0f), position, 4f, autoDelay: true);
            m_subsystemParticles.AddParticleSystem(new WaterSplashParticleSystem(m_systemTerrain, hitPosition, true));
        }

        // 隐藏钓鱼UI
        public void HideFishingUI(BitmapButtonWidget FishingWidget, RoundProgressWidget FishingRoundRange, RoundProgressWidget FishingCaptureBar)
        {
            if (FishingWidget != null)
            {
                FishingWidget.IsVisible = false;
                FishingRoundRange.IsVisible = false;
                FishingCaptureBar.IsVisible = false;
                FishingWidget.IsChecked = false;
            }
        }

        // 清除钓鱼UI
        public void ClearFishingUI(BitmapButtonWidget FishingWidget, RoundProgressWidget FishingRoundRange, RoundProgressWidget FishingCaptureBar)
        {
            FishingWidget = null;
            FishingRoundRange = null;
            FishingCaptureBar = null;
        }

        // 绘制圆环扇形
        public void QueueTorusSector(FlatBatch3D flatBatch3D, Vector3 position, float outerRadius, float innerRadius, float depth, Color color, float value = 1.0f)
        {
            int sides = 4096;
            float startAngle = 0f;
            float endAngle = (float)Math.PI * 2f * value;

            Vector3 pOuterTop = Vector3.Zero;
            Vector3 pInnerTop = Vector3.Zero;
            Vector3 pOuterBottom = Vector3.Zero;
            Vector3 pInnerBottom = Vector3.Zero;

            for (int i = 0; i <= sides; i++)
            {
                float angle = MathUtils.Lerp(startAngle, endAngle, (float)i / (float)sides);
                Vector3 axis = new Vector3(MathUtils.Sin(angle), 0f, MathUtils.Cos(angle));

                Vector3 vectorOuterTop = position + axis * outerRadius;
                Vector3 vectorInnerTop = position + axis * innerRadius;
                Vector3 vectorOuterBottom = new Vector3(vectorOuterTop.X, vectorOuterTop.Y - depth, vectorOuterTop.Z);
                Vector3 vectorInnerBottom = new Vector3(vectorInnerTop.X, vectorInnerTop.Y - depth, vectorInnerTop.Z);

                if (i > 0)
                {
                    flatBatch3D.QueueTriangle(pOuterTop, vectorOuterTop, vectorOuterBottom, color, color, color);
                    flatBatch3D.QueueTriangle(vectorOuterTop, pOuterBottom, vectorOuterBottom, color, color, color);
                    flatBatch3D.QueueTriangle(pInnerTop, vectorInnerTop, vectorInnerBottom, color, color, color);
                    flatBatch3D.QueueTriangle(vectorInnerTop, pInnerBottom, vectorInnerBottom, color, color, color);
                }

                pOuterTop = vectorOuterTop;
                pInnerTop = vectorInnerTop;
                pOuterBottom = vectorOuterBottom;
                pInnerBottom = vectorInnerBottom;
            }
        }

        public Vector3 CalculateFishingPoint(Vector3 vector)
        {
            return vector - 4f * Vector3.UnitY;
        }
    }
}
//滑轮进度条界面
namespace Game
{
    public class RoundProgressWidget : CanvasWidget
    {
        public RoundProgressWidget()
        {
            BackColor = new Color(180, 180, 180, 225);
            ValueColor = new Color(255, 255, 255, 128);
            IsDrawRequired = true;
            Radiu = 0.75f;
            RoundRange = new Vector2(-0.5f, 0.5f);
            Size1 = 28f;
            StartValue = 0f;
        }

        public Color BackColor
        {
            get;
            set;
        }

        public Color ValueColor
        {
            get;
            set;
        }

        public Vector2 RoundRange
        {
            get;
            set;
        }

        public float StartValue
        {
            get;
            set;
        }

        public float Value
        {
            get;
            set;
        }

        public float Radiu
        {
            get;
            set;
        }

        public float Size1
        {
            get;
            set;
        }

        public override void Draw(DrawContext dc)
        {
            float num = Size1 * GlobalTransform.Right.Length();
            var center = Vector2.Transform(ActualSize / 2f, GlobalTransform);
            FlatBatch2D flatBatch2D = dc.PrimitivesRenderer2D.FlatBatch(100);
            flatBatch2D.QueueDisc(center, new Vector2(num), new Vector2(num * Radiu), 0f, BackColor, BackColor, startAngle: (float)Math.PI * 2f * RoundRange.X, endAngle: (float)Math.PI * 2f * RoundRange.Y);
            flatBatch2D.QueueDisc(center, new Vector2(num), new Vector2(num * Radiu), 0f, ValueColor, ValueColor, startAngle: (float)Math.PI * 2f * RoundRange.X * StartValue, endAngle: (float)Math.PI * 2f * RoundRange.Y * Value);
        }
    }
}
