//子系统工具方块行为
namespace Game
{
    public class SubsystemNewToolsBlockBehavior : SubsystemBlockBehavior, IUpdateable
    {
        public UpdateOrder UpdateOrder
        {
            get
            {
                return 0;
            }
        }


        public override void Load(ValuesDictionary valuesDictionary)
        {
            base.Load(valuesDictionary);
            this.subsystemPlayers = base.Project.FindSubsystem<SubsystemPlayers>();
            this.subsystemTerrain = base.Project.FindSubsystem<SubsystemTerrain>();
            this.subsystemTime = base.Project.FindSubsystem<SubsystemTime>();
            this.subsystemFire = base.Project.FindSubsystem<SubsystemFireBlockBehavior>();
        }


        public void Update(float dt)
        {
            bool flag = this.subsystemTime.PeriodicGameTimeEvent(0.1, 0.0);
            if (flag)
            {
                int num = 0;
                foreach (ComponentPlayer componentPlayer in this.subsystemPlayers.ComponentPlayers)
                {
                    Point3 point = this.GetPoint(componentPlayer.ComponentBody.Position) + Point3.UnitY;
                    HYZLInventory inventory = (HYZLInventory)componentPlayer.Entity.FindComponent<ComponentHand>();
                    bool flag2 = NewToolsBlock.GetType(inventory.GetSlotValue(inventory.ActiveSlotIndex)) == 4 && Terrain.ExtractContents(inventory.GetSlotValue(inventory.ActiveSlotIndex)) == NewToolsBlock.Index;
                    if (flag2)
                    {
                        bool flag3 = point != this.lightingPoints[num];
                        if (flag3)
                        {
                            bool flag4 = base.SubsystemTerrain.Terrain.GetCellContents(point.X, point.Y, point.Z) == 0;
                            if (flag4)
                            {
                                this.subsystemTerrain.ChangeCell(point.X, point.Y, point.Z, LightBlock.Index, true);
                                bool flag5 = this.lightingPoints[num] != Point3.Zero;
                                if (flag5)
                                {
                                    Point3 point2 = this.lightingPoints[num];
                                    this.subsystemTerrain.ChangeCell(point2.X, point2.Y, point2.Z, 0, true);
                                }
                                this.lightingPoints[num] = point;
                            }
                        }
                    }
                    else
                    {
                        bool flag6 = this.lightingPoints[num] != Point3.Zero;
                        if (flag6)
                        {
                            Point3 point3 = this.lightingPoints[num];
                            this.subsystemTerrain.ChangeCell(point3.X, point3.Y, point3.Z, 0, true);
                            this.lightingPoints[num] = Point3.Zero;
                        }
                    }
                    num++;
                }
            }
            if (this.subsystemTime.PeriodicGameTimeEvent(50, 0.0))
            {
                foreach (ComponentPlayer componentPlayer in this.subsystemPlayers.ComponentPlayers)
                {
                    componentPlayer.ComponentMiner.DamageActiveTool(1);
                }
            }
        }


        public Point3 GetPoint(Vector3 v)
        {
            return new Point3((int)MathUtils.Round(v.X), (int)MathUtils.Round(v.Y), (int)MathUtils.Round(v.Z));
        }
        public SubsystemPlayers subsystemPlayers;

        public SubsystemTerrain subsystemTerrain;

        public SubsystemTime subsystemTime;

        public SubsystemFireBlockBehavior subsystemFire;

        public readonly Point3[] lightingPoints = new Point3[4];
    }
}
//组件烹饪台
namespace Game
{
    public class ComponentCookingTable : ComponentInventoryBase, IUpdateable
    {
        public ComponentBlockEntity componentBlockEntity;
        public ComponentPlayer m_craftingPlayer;
        public SubsystemPickables subsystemPickables;
        public SubsystemTime subsystemTime;
        public SubsystemGameInfo subsystemGameInfo;
        public SubsystemAudio subsystemAudio;
        public SubsystemNewInteroperableCubeBlockBehavior subsystemNewInteroperableCubeBlockBehavior;
        public CraftingHYZLRecipe m_matchedRecipe;
        public bool m_recipeUpdateNeeded;
        public bool m_recipeRefindNeeded;
        public int Level;
        public int Durability;
        public CraftingHYZLRecipe m_selectedRecipe;

        // 合成时间相关字段
        public double m_craftingStartTime;
        public double m_acceleratedDuration;
        public double m_waitingDuration;
        public bool m_isCrafting;
        public bool m_isAcceleratedPhase;
        public bool m_waitingForCollection; // 新增：等待手动收集状态
        public CraftingHYZLRecipe m_currentCraftingRecipe;
        public int m_currentCraftingCount;
        public ComponentPlayer m_currentCraftingPlayer;

        // 合成进度和剩余时间显示变量
        public float CraftingProgress => GetCraftingProgress();
        public double RemainingTime => GetRemainingTime();
        public string CurrentPhase => m_isAcceleratedPhase ? "加速阶段" : (m_waitingForCollection ? "等待收集" : "等待阶段");

        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public virtual void Update(float dt)
        {
            // 处理合成时间逻辑
            if (m_isCrafting)
            {
                // 检查合成条件（仅在加速阶段检查）
                if (m_isAcceleratedPhase && !CheckCraftingConditions(m_currentCraftingPlayer))
                {
                    CancelCraftingDueToConditions();
                    return;
                }

                // 设置时间因子：加速阶段120倍，等待阶段1倍
                subsystemTime.m_gameTimeFactor = m_isAcceleratedPhase ? 120 : 1;

                double currentTime = subsystemGameInfo.TotalElapsedGameTime;
                double elapsedTime = currentTime - m_craftingStartTime;

                // 检查当前阶段是否完成
                if (m_isAcceleratedPhase && elapsedTime >= m_acceleratedDuration)
                {
                    // 加速阶段完成，切换到等待阶段
                    SwitchToWaitingPhase();
                }
                else if (!m_isAcceleratedPhase && elapsedTime >= m_waitingDuration)
                {
                    // 等待阶段完成，根据等待时间决定后续操作
                    if (m_waitingDuration > 0)
                    {
                        // 等待时间大于0，进入等待收集状态
                        m_waitingForCollection = true;
                        m_isCrafting = false;
                        subsystemTime.m_gameTimeFactor = 1;

                        if (m_currentCraftingPlayer != null)
                        {
                            string itemName = GetItemName();
                            m_currentCraftingPlayer.ComponentGui.DisplaySmallMessage(
                                $"{itemName} 已合成完成，请手动收集！", Color.Yellow, true, true);
                        }
                    }
                    else
                    {
                        // 等待时间为0，自动完成合成
                        CompleteCrafting();
                    }
                }
            }

            if (m_recipeUpdateNeeded)
            {
                UpdateCraftingResult(m_recipeRefindNeeded);
            }
            m_recipeUpdateNeeded = false;
            m_recipeRefindNeeded = false;
            Level = NewCookingTable.GetType(componentBlockEntity.BlockValue);
            Durability = BlocksManager.Blocks[Terrain.ExtractContents(componentBlockEntity.BlockValue)].GetDamage(componentBlockEntity.BlockValue);
        }

        // 手动收集产物方法
        public bool CollectCraftingResult(ComponentPlayer player)
        {
            if (!m_waitingForCollection || m_currentCraftingRecipe == null)
                return false;

            if (IsPlayerDeadOrInvalid(player) || !CheckCraftingConditions(player))
            {
                player.ComponentGui.DisplaySmallMessage("无法收集：条件不满足", Color.Red, true, true);
                return false;
            }

            CompleteCrafting();
            return true;
        }

        public void SwitchToWaitingPhase()
        {
            m_isAcceleratedPhase = false;
            m_craftingStartTime = subsystemGameInfo.TotalElapsedGameTime;

            if (m_currentCraftingPlayer != null)
            {
                string itemName = GetItemName();
                m_currentCraftingPlayer.ComponentGui.DisplaySmallMessage(
                    $"加速阶段完成，进入等待阶段：{itemName}", Color.Yellow, true, true);
            }
        }

        public bool CheckCraftingConditions(ComponentPlayer player)
        {
            if (IsPlayerDeadOrInvalid(player)) return false;

            ComponentVitalStats vitalStats = player.ComponentVitalStats;
            if (vitalStats != null && vitalStats.Sleep <= 0.2f)
            {
                player.ComponentGui.DisplaySmallMessage("太困了，无法继续合成！", Color.Red, true, true);
                return false;
            }

            if (Durability <= 0)
            {
                player.ComponentGui.DisplaySmallMessage("合成台已损坏，无法合成！", Color.Red, true, true);
                return false;
            }

            return true;
        }

        public void CancelCraftingDueToConditions()
        {
            if (m_currentCraftingPlayer != null)
            {
                m_currentCraftingPlayer.ComponentGui.DisplaySmallMessage("合成已取消", Color.Yellow, true, true);
            }

            subsystemTime.m_gameTimeFactor = 1;
            ResetCraftingState();
        }

        public override void AddSlotItems(int slotIndex, int value, int count)
        {
            base.AddSlotItems(slotIndex, value, count);
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }

        public override int RemoveSlotItems(int slotIndex, int count)
        {
            int num = base.RemoveSlotItems(slotIndex, count);
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
            return num;
        }

        public virtual void UpdateCraftingResult(bool recipeRefindNeeded)
        {
            ComponentPlayer componentPlayer = m_currentCraftingPlayer;
            if (componentPlayer == null || IsPlayerDeadOrInvalid(componentPlayer) || !CheckCraftingConditions(componentPlayer)) return;

            Dictionary<string, int> playerIngredients = new Dictionary<string, int>();
            ComponentInventory inventory = componentPlayer.Entity.FindComponent<ComponentInventory>();

            for (int i = 0; i < inventory.SlotsCount; i++)
            {
                int slotValue = inventory.GetSlotValue(i);
                int slotCount = inventory.GetSlotCount(i);

                if (slotValue != 0 && slotCount > 0)
                {
                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string ingredientKey = $"{craftingId}:{data}";

                    playerIngredients[ingredientKey] = playerIngredients.ContainsKey(ingredientKey) ?
                        playerIngredients[ingredientKey] + slotCount : slotCount;
                }
            }

            CraftingHYZLRecipe craftingRecipe = recipeRefindNeeded || m_matchedRecipe == null
                ? CraftingHYZLRecipesManager.FindMatchingRecipe(
                    Project.FindSubsystem<SubsystemTerrain>(true),
                    playerIngredients,
                    0f,
                    componentPlayer.PlayerData.Level)
                : m_matchedRecipe;

            if (craftingRecipe != null && !string.IsNullOrEmpty(craftingRecipe.ResultValue))
            {
                m_matchedRecipe = craftingRecipe;
                if (CheckIngredientsAvailable(craftingRecipe, componentPlayer, 1, out var lackDict) &&
                    ConsumeIngredientsAndCraft(componentPlayer, craftingRecipe, 1))
                {
                    if (!string.IsNullOrEmpty(craftingRecipe.Message))
                    {
                        string message = craftingRecipe.Message;
                        if (message.StartsWith('[') && message.EndsWith(']'))
                        {
                            message = LanguageControl.Get("CRMessage", message.Substring(1, message.Length - 2));
                        }
                        componentPlayer.ComponentGui.DisplaySmallMessage(message, Color.White, true, true);
                    }
                }
            }
            else
            {
                m_matchedRecipe = null;
            }
        }

        public bool CheckIngredientsAvailable(CraftingHYZLRecipe recipe, ComponentPlayer player, int count, out Dictionary<string, int> lackDict)
        {
            lackDict = new Dictionary<string, int>();
            if (IsPlayerDeadOrInvalid(player))
                return false;

            ComponentInventory playerInventory = player.Entity.FindComponent<ComponentInventory>();

            foreach (var ingredient in recipe.Ingredients)
            {
                string ingredientId = ingredient.Key;
                int requiredCount = ingredient.Value * count;
                int totalCount = 0;

                for (int i = 0; i < playerInventory.SlotsCount; i++)
                {
                    int slotValue = playerInventory.GetSlotValue(i);
                    if (slotValue == 0) continue;

                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string currentIngredientId = $"{craftingId}:{data}";

                    if (currentIngredientId == ingredientId)
                    {
                        totalCount += playerInventory.GetSlotCount(i);
                    }
                }

                if (totalCount < requiredCount)
                {
                    lackDict[ingredientId] = requiredCount - totalCount;
                }
            }

            return lackDict.Count == 0;
        }

        public int CalculateMaxCraftCount(CraftingHYZLRecipe recipe, ComponentPlayer player)
        {
            if (IsPlayerDeadOrInvalid(player)) return 0;

            ComponentInventory inventory = player.Entity.FindComponent<ComponentInventory>();
            int maxCraftCount = int.MaxValue;

            foreach (var ingredient in recipe.Ingredients)
            {
                int totalCount = 0;

                for (int i = 0; i < inventory.SlotsCount; i++)
                {
                    int slotValue = inventory.GetSlotValue(i);
                    if (slotValue == 0) continue;

                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string currentIngredientId = $"{craftingId}:{data}";

                    if (currentIngredientId == ingredient.Key)
                    {
                        totalCount += inventory.GetSlotCount(i);
                    }
                }

                maxCraftCount = Math.Min(maxCraftCount, totalCount / ingredient.Value);
            }

            return Math.Max(1, maxCraftCount);
        }

        public bool StartCrafting(ComponentPlayer player, CraftingHYZLRecipe recipe, int count)
        {
            if (m_isCrafting || m_waitingForCollection)
            {
                player.ComponentGui.DisplaySmallMessage("正在合成中，请等待完成！", Color.Yellow, true, true);
                return false;
            }

            if (IsPlayerDeadOrInvalid(player) || !CheckCraftingConditions(player))
            {
                player.ComponentGui.DisplaySmallMessage("无法开始合成：条件不满足", Color.Red, true, true);
                return false;
            }

            if (!CheckIngredientsAvailable(recipe, player, count, out var lackDict))
            {
                player.ComponentGui.DisplaySmallMessage("材料不足！", Color.Red, true, true);
                return false;
            }

            // 计算双阶段时间
            m_acceleratedDuration = recipe.TimeConsuming * count;
            m_waitingDuration = recipe.WaitingTime;
            m_craftingStartTime = subsystemGameInfo.TotalElapsedGameTime;
            m_isAcceleratedPhase = true;

            m_isCrafting = true;
            m_waitingForCollection = false;
            m_currentCraftingRecipe = recipe;
            m_currentCraftingCount = count;
            m_currentCraftingPlayer = player;

            string itemName = GetItemName();
            player.ComponentGui.DisplaySmallMessage(
                $"开始合成 {count * recipe.ResultCount} 个 {itemName}（加速阶段：{m_acceleratedDuration}分钟 + 等待阶段：{m_waitingDuration}秒）",
                Color.Yellow, true, true);

            return true;
        }

        public string GetItemName()
        {
            if (m_currentCraftingRecipe == null) return string.Empty;
            int resultValue = CraftingRecipesManager.DecodeResult(m_currentCraftingRecipe.ResultValue);
            return BlocksManager.Blocks[Terrain.ExtractContents(resultValue)].GetDisplayName(null, resultValue);
        }

        public void CompleteCrafting()
        {
            if ((!m_isCrafting && !m_waitingForCollection) || m_currentCraftingRecipe == null || m_currentCraftingPlayer == null)
            {
                ResetCraftingState();
                return;
            }

            ComponentPlayer player = m_currentCraftingPlayer;
            CraftingHYZLRecipe recipe = m_currentCraftingRecipe;
            int count = m_currentCraftingCount;

            if (IsPlayerDeadOrInvalid(player) || !CheckCraftingConditions(player))
            {
                ResetCraftingState();
                return;
            }

            ComponentInventory inventory = player.Entity.FindComponent<ComponentInventory>();

            // 消耗材料
            foreach (var ingredient in recipe.Ingredients)
            {
                int remainingToConsume = ingredient.Value * count;

                for (int i = 0; i < inventory.SlotsCount && remainingToConsume > 0; i++)
                {
                    int slotValue = inventory.GetSlotValue(i);
                    if (slotValue == 0) continue;

                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string currentIngredientId = $"{craftingId}:{data}";

                    if (currentIngredientId == ingredient.Key)
                    {
                        int availableCount = inventory.GetSlotCount(i);
                        int consumeCount = Math.Min(availableCount, remainingToConsume);

                        inventory.RemoveSlotItems(i, consumeCount);
                        remainingToConsume -= consumeCount;
                    }
                }
            }

            // 生成产物
            Vector3 dropPosition = componentBlockEntity.Position + new Vector3(0.5f, 1.5f, 0.5f);
            bool hasSpecialResult = false;
            Random m_random = new Random();

            for (int a = 0; a < recipe.ResultCount * count; a++)
            {
                int resultValue = CraftingRecipesManager.DecodeResult(recipe.ResultValue);

                if (Terrain.ExtractContents(resultValue) == NewFood.Index && m_random.Bool(0.05f))
                {
                    resultValue = Terrain.MakeBlockValue(Terrain.ExtractContents(resultValue), 0,
                        NewFood.SetItIsBetter(resultValue, true));
                    hasSpecialResult = true;
                    player.PlayerStats.ValuesDictionaryForMods["MoreDeliciousCooking"] = (player.PlayerStats.ValuesDictionaryForMods.ContainsKey("MoreDeliciousCooking") ? (int)player.PlayerStats.ValuesDictionaryForMods["MoreDeliciousCooking"] + 1 : 1);
                }
                subsystemPickables.AddPickable(resultValue, 1, dropPosition, null, null);
            }

            subsystemAudio.PlaySound("Audio/UI/Production/SuccessInMakingObjects", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);

            if (hasSpecialResult)
            {
                player.ComponentGui.DisplaySmallMessage("幸运！制作出了更美味的食物！", Color.LightBlue, true, true);
            }

            // 减少耐久度
            componentBlockEntity.m_subsystemTerrain.ChangeCell(
                componentBlockEntity.Coordinates.X,
                componentBlockEntity.Coordinates.Y,
                componentBlockEntity.Coordinates.Z,
                BlocksManager.Blocks[Terrain.ExtractContents(componentBlockEntity.BlockValue)].SetDamage(
                    componentBlockEntity.BlockValue,
                    BlocksManager.Blocks[Terrain.ExtractContents(componentBlockEntity.BlockValue)].GetDamage(componentBlockEntity.BlockValue) - count
                )
            );

            if (player.PlayerStats != null)
            {
                player.PlayerStats.ValuesDictionaryForMods["CookingNumber"] = (player.PlayerStats.ValuesDictionaryForMods.ContainsKey("CookingNumber") ? (int)player.PlayerStats.ValuesDictionaryForMods["CookingNumber"] + recipe.ResultCount * count : recipe.ResultCount * count);
                subsystemNewInteroperableCubeBlockBehavior.CurrentCapacityAdd(recipe.ResultCount * count, 2);
            }

            string itemName = GetItemName();
            player.ComponentGui.DisplaySmallMessage(
                $"成功合成 {count * recipe.ResultCount} 个 {itemName}！",
                Color.Green, true, true);

            ResetCraftingState();
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }

        public float GetCraftingProgress()
        {
            if (!m_isCrafting) return 0f;

            double currentTime = subsystemGameInfo.TotalElapsedGameTime;
            double elapsedTime = currentTime - m_craftingStartTime;
            double currentPhaseDuration = m_isAcceleratedPhase ? m_acceleratedDuration : m_waitingDuration;

            return MathUtils.Clamp((float)(elapsedTime / currentPhaseDuration), 0f, 1f);
        }

        public double GetRemainingTime()
        {
            if (!m_isCrafting) return 0;

            double currentTime = subsystemGameInfo.TotalElapsedGameTime;
            double elapsedTime = currentTime - m_craftingStartTime;
            double currentPhaseDuration = m_isAcceleratedPhase ? m_acceleratedDuration : m_waitingDuration;
            double remainingTime = currentPhaseDuration - elapsedTime;

            if (m_isAcceleratedPhase)
            {
                remainingTime += m_waitingDuration;
            }

            return Math.Max(0, remainingTime);
        }

        public bool IsCrafting()
        {
            return m_isCrafting || m_waitingForCollection;
        }

        public string GetCurrentCraftingInfo()
        {
            if ((!m_isCrafting && !m_waitingForCollection) || m_currentCraftingRecipe == null) return string.Empty;

            string itemName = GetItemName();

            if (m_waitingForCollection)
            {
                return $"等待收集: {itemName} x{m_currentCraftingCount}\n请手动收集产物";
            }

            float progress = GetCraftingProgress() * 100f;
            double remainingTime = GetRemainingTime();
            string timeUnit = m_isAcceleratedPhase ? "分钟" : "秒";

            return $"正在合成: {itemName} x{m_currentCraftingCount}\n" +
                   $"阶段: {CurrentPhase}\n" +
                   $"进度: {progress:F1}%\n" +
                   $"剩余时间: {remainingTime:F1}{timeUnit}";
        }

        public bool TryCraftSelectedRecipe(CraftingHYZLRecipe recipe, ComponentPlayer player)
        {
            if (recipe == null || player == null) return false;

            if (IsPlayerDeadOrInvalid(player) || !CheckCraftingConditions(player))
            {
                player.ComponentGui.DisplaySmallMessage("无法合成：条件不满足", Color.Red, true, true);
                return false;
            }

            if (Level < recipe.RequiredCookingTableLevel)
            {
                player.ComponentGui.DisplaySmallMessage($"合成台等级不足！需要等级{recipe.RequiredCookingTableLevel}", Color.Red, true, true);
                return false;
            }

            if (!CheckIngredientsAvailable(recipe, player, 1, out var lackDict))
            {
                DialogsManager.ShowDialog(null, new ShellSupplementMaterialsDialog(player, lackDict));
                player.ComponentGui.DisplaySmallMessage("材料不足！", Color.Red, true, true);
                return false;
            }

            int maxCraftCount = CalculateMaxCraftCount(recipe, player);

            m_selectedRecipe = recipe;
            m_craftingPlayer = player;

            // 如果等待时间大于0，只合成一次，不显示对话框
            if (recipe.WaitingTime > 0)
            {
                StartCrafting(player, recipe, 1);
                m_selectedRecipe = null;
                m_craftingPlayer = null;
                return true;
            }
            else
            {
                // 等待时间为0，显示数量选择对话框
                DialogsManager.ShowDialog(null, new SynthesisCountDialog(delegate (int count)
                {
                    if (count > 0 && m_selectedRecipe != null && m_craftingPlayer != null)
                    {
                        StartCrafting(m_craftingPlayer, m_selectedRecipe, count);
                    }

                    m_selectedRecipe = null;
                    m_craftingPlayer = null;
                })
                {
                    Count = 1,
                    MaxCount = maxCraftCount
                });
            }

            return true;
        }

        public void ResetCraftingState()
        {
            subsystemTime.m_gameTimeFactor = 1;
            m_isCrafting = false;
            m_isAcceleratedPhase = false;
            m_waitingForCollection = false;
            m_currentCraftingRecipe = null;
            m_currentCraftingCount = 0;
            m_currentCraftingPlayer = null;
            m_acceleratedDuration = 0;
            m_waitingDuration = 0;
        }

        public bool IsPlayerDeadOrInvalid(ComponentPlayer player)
        {
            if (player == null) return true;

            ComponentHealth health = player.Entity.FindComponent<ComponentHealth>();
            if (health != null && health.Health <= 0f) return true;

            if (!(player.ComponentGui.ModalPanelWidget is CookingTableWidget)) return true;

            if (componentBlockEntity != null)
            {
                float distance = Vector3.Distance(player.ComponentBody.Position, componentBlockEntity.Position);
                if (distance > 5f) return true;
            }

            return false;
        }

        public bool ConsumeIngredientsAndCraft(ComponentPlayer player, CraftingHYZLRecipe recipe, int count)
        {
            if (IsPlayerDeadOrInvalid(player) || !CheckCraftingConditions(player)) return false;

            ComponentInventory inventory = player.Entity.FindComponent<ComponentInventory>();

            // 消耗材料
            foreach (var ingredient in recipe.Ingredients)
            {
                int remainingToConsume = ingredient.Value * count;

                for (int i = 0; i < inventory.SlotsCount && remainingToConsume > 0; i++)
                {
                    int slotValue = inventory.GetSlotValue(i);
                    if (slotValue == 0) continue;

                    string currentIngredientId = GetIngredientId(slotValue);
                    if (currentIngredientId == ingredient.Key)
                    {
                        int availableCount = inventory.GetSlotCount(i);
                        int consumeCount = Math.Min(availableCount, remainingToConsume);

                        inventory.RemoveSlotItems(i, consumeCount);
                        remainingToConsume -= consumeCount;
                    }
                }
            }

            // 生成产物
            Vector3 dropPosition = componentBlockEntity.Position + new Vector3(0.5f, 1.5f, 0.5f);
            bool hasSpecialResult = false;

            for (int a = 0; a < recipe.ResultCount * count; a++)
            {
                int resultValue = CraftingRecipesManager.DecodeResult(recipe.ResultValue);

                if (Terrain.ExtractContents(resultValue) == NewFood.Index && m_random.Bool(0.05f))
                {
                    resultValue = Terrain.MakeBlockValue(Terrain.ExtractContents(resultValue), 0,
                        NewFood.SetItIsBetter(resultValue, true));
                    hasSpecialResult = true;
                    player.PlayerStats.ValuesDictionaryForMods["MoreDeliciousCooking"] = (player.PlayerStats.ValuesDictionaryForMods.ContainsKey("MoreDeliciousCooking") ? (int)player.PlayerStats.ValuesDictionaryForMods["MoreDeliciousCooking"] + 1 : 1);
                }
                subsystemPickables.AddPickable(resultValue, 1, dropPosition, null, null);
            }

            if (hasSpecialResult)
            {
                player.ComponentGui.DisplaySmallMessage("幸运！制作出了更美味的食物！", Color.LightBlue, true, true);
            }

            // 减少耐久度
            componentBlockEntity.m_subsystemTerrain.ChangeCell(
                componentBlockEntity.Coordinates.X,
                componentBlockEntity.Coordinates.Y,
                componentBlockEntity.Coordinates.Z,
                BlocksManager.Blocks[Terrain.ExtractContents(componentBlockEntity.BlockValue)].SetDamage(
                    componentBlockEntity.BlockValue,
                    BlocksManager.Blocks[Terrain.ExtractContents(componentBlockEntity.BlockValue)].GetDamage(componentBlockEntity.BlockValue) - count
                )
            );

            if (player.PlayerStats != null)
            {
                player.PlayerStats.ValuesDictionaryForMods["CookingNumber"] = (player.PlayerStats.ValuesDictionaryForMods.ContainsKey("CookingNumber") ? (int)player.PlayerStats.ValuesDictionaryForMods["CookingNumber"] + recipe.ResultCount * count : recipe.ResultCount * count);
                subsystemNewInteroperableCubeBlockBehavior.CurrentCapacityAdd(recipe.ResultCount * count, 2);
            }

            return true;
        }

        public string GetIngredientId(int slotValue)
        {
            int content = Terrain.ExtractContents(slotValue);
            int data = Terrain.ExtractData(slotValue);
            Block block = BlocksManager.Blocks[content];
            string craftingId = block.GetCraftingId(slotValue);
            return $"{craftingId}:{data}";
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            componentBlockEntity = Entity.FindComponent<ComponentBlockEntity>(throwOnError: true);
            subsystemPickables = Project.FindSubsystem<SubsystemPickables>(throwOnError: true);
            subsystemTime = Project.FindSubsystem<SubsystemTime>();
            subsystemGameInfo = Project.FindSubsystem<SubsystemGameInfo>();
            subsystemAudio = Project.FindSubsystem<SubsystemAudio>();
            subsystemNewInteroperableCubeBlockBehavior = Project.FindSubsystem<SubsystemNewInteroperableCubeBlockBehavior>(true);

            m_isCrafting = valuesDictionary.GetValue<bool>("IsCrafting", false);
            m_isAcceleratedPhase = valuesDictionary.GetValue<bool>("IsAcceleratedPhase", false);
            m_waitingForCollection = valuesDictionary.GetValue<bool>("WaitingForCollection", false);
            m_craftingStartTime = valuesDictionary.GetValue<double>("CraftingStartTime", 0);
            m_acceleratedDuration = valuesDictionary.GetValue<double>("AcceleratedDuration", 0);
            m_waitingDuration = valuesDictionary.GetValue<double>("WaitingDuration", 0);
            m_currentCraftingCount = valuesDictionary.GetValue<int>("CurrentCraftingCount", 0);

            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }

        public override void Save(ValuesDictionary valuesDictionary, EntityToIdMap entityToIdMap)
        {
            base.Save(valuesDictionary, entityToIdMap);
            valuesDictionary.SetValue("IsCrafting", m_isCrafting);
            valuesDictionary.SetValue("IsAcceleratedPhase", m_isAcceleratedPhase);
            valuesDictionary.SetValue("WaitingForCollection", m_waitingForCollection);
            valuesDictionary.SetValue("CraftingStartTime", m_craftingStartTime);
            valuesDictionary.SetValue("AcceleratedDuration", m_acceleratedDuration);
            valuesDictionary.SetValue("WaitingDuration", m_waitingDuration);
            valuesDictionary.SetValue("CurrentCraftingCount", m_currentCraftingCount);

            if (m_currentCraftingRecipe != null)
            {
                valuesDictionary.SetValue("CurrentRecipeResultValue", m_currentCraftingRecipe.ResultValue);
            }
        }
    }
}
//子系统烹饪台方块行为
namespace Game
{
    public class SubsystemCookingTableBlockBehavior : SubsystemEntityBlockBehavior
    {
        public override int[] HandledBlocks => new int[1]
        {
            BlocksManager.GetBlockIndex<NewCookingTable>()
        };

        public override void Load(ValuesDictionary valuesDictionary)
        {
            base.Load(valuesDictionary);
            m_databaseObject = Project.GameDatabase.Database.FindDatabaseObject("CookingTable", Project.GameDatabase.EntityTemplateType, true);
        }

        public override bool InteractBlockEntity(ComponentBlockEntity blockEntity, ComponentMiner componentMiner)
        {
            if (blockEntity != null && componentMiner.ComponentPlayer != null)
            {
                ComponentCookingTable componentCookingTable = blockEntity.Entity.FindComponent<ComponentCookingTable>(true);
                Point3 Coordinates = blockEntity.Coordinates;
                componentMiner.ComponentPlayer.ComponentGui.ModalPanelWidget = new CookingTableWidget(componentMiner.ComponentPlayer, componentCookingTable);
                AudioManager.PlaySound("Audio/UI/ButtonClick", 1f, 0f, 0f);
                return true;
            }
            return false;
        }
    }
}
//烹饪台界面
namespace Game
{
    public class CookingTableWidget : CanvasWidget
    {
        public ComponentPlayer m_componentPlayer;
        public ComponentCookingTable m_componentCookingTable;
        public SubsystemAudio subsystemAudio;

        public BlockIconWidget icon;
        public LabelWidget durabilityLabel;
        public LabelWidget levelLabel;
        public BitmapButtonWidget upgradeButton;
        public BitmapButtonWidget maintenanceButton;
        public ListPanelWidget typesList;
        public ListPanelWidget blockList;
        public LabelWidget makingThingsLabel;
        public LabelWidget timeConsumingLabel;
        public LabelWidget descriptionLabel;
        public ValueBarWidget timeBar;
        public LabelWidget timeLabel;
        public BevelledButtonWidget productionButton;
        public BevelledButtonWidget chargeButton;

        public Dictionary<BlockIconWidget, LabelWidget> Ingredients = new Dictionary<BlockIconWidget, LabelWidget>();
        public CraftingHYZLRecipe m_craftingHYZLRecipe;
        public List<string> m_typesitems = [];
        public Random m_random = new();

        public CookingTableWidget(ComponentPlayer componentPlayer, ComponentCookingTable componentCookingTable)
        {
            m_componentPlayer = componentPlayer;
            m_componentCookingTable = componentCookingTable;
            subsystemAudio = componentPlayer.Project.FindSubsystem<SubsystemAudio>();

            XElement node = ContentManager.Get<XElement>("Widgets/CookingTableWidget");
            LoadContents(this, node);

            InitializeWidgets();
            InitializeIngredients();
            InitializeTypesList();

            typesList.SelectedIndex = 0;

            componentPlayer.PlayerStats.ValuesDictionaryForMods["CookingTableLevel"] = (componentPlayer.PlayerStats.ValuesDictionaryForMods.ContainsKey("CookingTableLevel") ? ((int)componentPlayer.PlayerStats.ValuesDictionaryForMods["CookingTableLevel"] > m_componentCookingTable.Level ? componentPlayer.PlayerStats.ValuesDictionaryForMods["CookingTableLevel"] : m_componentCookingTable.Level) : m_componentCookingTable.Level);
        }

        public void InitializeWidgets()
        {
            icon = Children.Find<BlockIconWidget>("Icon");
            durabilityLabel = Children.Find<LabelWidget>("DurabilityLabel");
            levelLabel = Children.Find<LabelWidget>("LevelLabel");
            upgradeButton = Children.Find<BitmapButtonWidget>("UpgradeButton");
            maintenanceButton = Children.Find<BitmapButtonWidget>("MaintenanceButton");
            typesList = Children.Find<ListPanelWidget>("TypesList");
            blockList = Children.Find<ListPanelWidget>("BlockList");
            makingThingsLabel = Children.Find<LabelWidget>("MakingThingsLabel");
            timeConsumingLabel = Children.Find<LabelWidget>("TimeConsumingLabel");
            descriptionLabel = Children.Find<LabelWidget>("DescriptionLabel");
            timeBar = Children.Find<ValueBarWidget>("TimeBar");
            timeLabel = Children.Find<LabelWidget>("TimeLabel");
            productionButton = Children.Find<BevelledButtonWidget>("ProductionButton");
            chargeButton = Children.Find<BevelledButtonWidget>("ChargeButton");
        }

        public void InitializeIngredients()
        {
            for (int a = 1; a < 27; a++)
            {
                Ingredients.Add(Children.Find<BlockIconWidget>("Materials" + a), Children.Find<LabelWidget>("Materials" + a + "Label"));
            }
        }

        public void InitializeTypesList()
        {
            typesList.ItemWidgetFactory = delegate (object item)
            {
                var craftingHYZLRecipe = (CraftingHYZLRecipe)item;
                XElement node2 = ContentManager.Get<XElement>("Widgets/TypesItem");
                var obj = (ContainerWidget)LoadWidget(this, node2, null);
                obj.Children.Find<LabelWidget>("Types").Text = craftingHYZLRecipe.Type;
                return obj;
            };

            m_typesitems.Clear();
            foreach (CraftingHYZLRecipe recipe in CraftingHYZLRecipesManager.Recipes)
            {
                if (m_componentCookingTable.Level >= recipe.RequiredCookingTableLevel && recipe.RequiredCookingTableLevel > 0 && recipe.Type != null)
                {
                    typesList.AddItem(recipe);
                    m_typesitems.Add(recipe.Type);
                }
            }
        }

        public override void Update()
        {
            m_componentCookingTable.m_currentCraftingPlayer = m_componentPlayer;

            UpdateBasicInfo();
            UpdateVisibility();
            HandleButtonClicks();
            UpdateRecipeSelection();
        }

        public void UpdateBasicInfo()
        {
            icon.Value = Terrain.MakeBlockValue(NewCookingTable.Index, 0, m_componentCookingTable.Level);
            durabilityLabel.Text = "耐久:" + m_componentCookingTable.Durability;
            levelLabel.Text = "等级:" + m_componentCookingTable.Level;

            double minutes = Math.Floor(m_componentCookingTable.RemainingTime / 60);
            double seconds = Math.Floor(m_componentCookingTable.RemainingTime - minutes * 60);
            timeLabel.Text = "剩余时间:" + minutes + ":" + seconds;
            productionButton.Text = (m_componentCookingTable.m_isCrafting && !m_componentCookingTable.m_isAcceleratedPhase ? "加速" : "制作");

            timeBar.Value = m_componentCookingTable.CraftingProgress;
        }

        public void UpdateVisibility()
        {
            upgradeButton.IsVisible = (m_componentCookingTable.Durability != 0 && m_componentCookingTable.Level < AccessNewCookingTableManager.Data.Count - 1);
            maintenanceButton.IsVisible = m_componentCookingTable.Durability == 0;
            timeBar.IsVisible = timeLabel.IsVisible = (m_componentCookingTable.RemainingTime > 0 && m_componentCookingTable.CurrentPhase == "等待阶段");
            chargeButton.IsVisible = m_componentCookingTable.m_waitingForCollection;
        }

        public void HandleButtonClicks()
        {
            if (productionButton.IsClicked && m_craftingHYZLRecipe != null)
            {
                if (productionButton.Text == "加速")
                {
                    DialogsManager.ShowDialog(null, new NonWaitingAccelerationAccelerationDialog(m_componentPlayer, m_componentCookingTable));
                }
                else
                {
                    m_componentCookingTable.TryCraftSelectedRecipe(m_craftingHYZLRecipe, m_componentPlayer);
                    m_craftingHYZLRecipe = null;
                    subsystemAudio.PlaySound("Audio/UI/Production/SpeedUpTheCreationOfItems", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
                }
            }
            if (chargeButton.IsClicked && m_componentCookingTable.m_waitingForCollection)
            {
                m_componentCookingTable.CollectCraftingResult(m_componentPlayer);
                m_craftingHYZLRecipe = null;
            }
            if (maintenanceButton.IsClicked)
            {
                m_componentPlayer.ComponentGui.ModalPanelWidget = new CookingTableMaintenanceWidget(m_componentPlayer, m_componentCookingTable);
            }
            if (upgradeButton.IsClicked)
            {
                m_componentPlayer.ComponentGui.ModalPanelWidget = new CookingTableUpgradeWidget(m_componentPlayer, m_componentCookingTable);
            }
        }

        public void UpdateRecipeSelection()
        {
            if (!typesList.SelectedIndex.HasValue)
            {
                blockList.ClearItems();
                typesList.SelectedIndex = 0;
                productionButton.IsVisible = false;
                return;
            }

            HandleTypeSelection();
            HandleBlockSelection();
        }

        public void HandleTypeSelection()
        {
            typesList.ItemClicked = delegate (object item)
            {
                if (!typesList.SelectedIndex.HasValue) return;

                string selectedType = m_typesitems[typesList.SelectedIndex.Value];
                UpdateBlockList(selectedType);
            };
        }

        public void UpdateBlockList(string selectedType)
        {
            blockList.ClearItems();

            blockList.ItemWidgetFactory = delegate (object item)
            {
                var craftingHYZLRecipe = (CraftingHYZLRecipe)item;
                XElement node2 = ContentManager.Get<XElement>("Widgets/SyntheticArticlesItem");
                var obj = (ContainerWidget)LoadWidget(this, node2, null);
                obj.Children.Find<BlockIconWidget>("Icon").Value = CraftingRecipesManager.DecodeResult(craftingHYZLRecipe.ResultValue);
                return obj;
            };

            foreach (CraftingHYZLRecipe recipe in CraftingHYZLRecipesManager.Recipes)
            {
                if (m_componentCookingTable.Level >= recipe.RequiredCookingTableLevel &&
                    recipe.RequiredCookingTableLevel > 0 &&
                    selectedType == recipe.ResultType)
                {
                    blockList.AddItem(recipe);
                }
            }

            if (!blockList.SelectedIndex.HasValue)
            {
                blockList.SelectedIndex = 0;
            }
        }

        public void HandleBlockSelection()
        {
            if (!blockList.SelectedIndex.HasValue)
            {
                ClearRecipeInfo();
                blockList.SelectedIndex = 0;
                return;
            }

            blockList.ItemClicked = delegate (object item)
            {
                var craftingHYZLRecipe = (CraftingHYZLRecipe)item;
                UpdateRecipeDetails(craftingHYZLRecipe);
            };
        }

        public void UpdateRecipeDetails(CraftingHYZLRecipe recipe)
        {
            ClearIngredients();

            for (int a = 0; a < 26; a++)
            {
                try
                {
                    var ingredient = recipe.Ingredients.ElementAt(a);
                    string[] safeParts = ingredient.Key.Split(':');
                    string beforeChar = safeParts[0];
                    string afterChar = safeParts.Length > 1 ? safeParts[1] : string.Empty;

                    Ingredients.ElementAt(a).Key.Value = Terrain.MakeBlockValue(
                        BlocksManager.FindBlocksByCraftingId(beforeChar)[0].BlockIndex, 0, int.Parse(afterChar));
                    Ingredients.ElementAt(a).Value.Text = "X" + ingredient.Value;
                }
                catch
                {
                    Ingredients.ElementAt(a).Key.Value = 0;
                    Ingredients.ElementAt(a).Value.Text = "";
                }
            }

            int resultBlockValue = CraftingRecipesManager.DecodeResult(recipe.ResultValue);
            makingThingsLabel.Text = BlocksManager.Blocks[Terrain.ExtractContents(resultBlockValue)]
                .GetDisplayName(m_componentPlayer.m_subsystemTerrain, resultBlockValue) + "X" + recipe.ResultCount;

            timeConsumingLabel.Text = "耗时:" + recipe.TimeConsuming + "分钟";
            descriptionLabel.Text = recipe.Description;
            m_craftingHYZLRecipe = recipe;
            productionButton.IsVisible = true;
        }

        public void ClearIngredients()
        {
            makingThingsLabel.Text = "";
            timeConsumingLabel.Text = "";

            foreach (var ingredient in Ingredients)
            {
                ingredient.Key.Value = 0;
                ingredient.Value.Text = "";
            }
        }

        public void ClearRecipeInfo()
        {
            makingThingsLabel.Text = "";
            timeConsumingLabel.Text = "";
            descriptionLabel.Text = "";
            productionButton.IsVisible = false;
        }
    }
}
//烹饪台升级配方获取
namespace Game
{
    public class CraftingCookingTableRecipe
    {
        public int MaxSize = 3;
        public string Description;
        public string Message;
        public int TimeConsuming;
        public int RequiredCookingTableLevel;
        public int DisplayOrder = 0;

        /// <summary>
        /// 配方材料字典：key=材料ID，value=所需数量
        /// </summary>
        public Dictionary<string, int> Ingredients = new Dictionary<string, int>();
    }

    public static class CraftingCookingTableRecipeManager
    {
        public static int Index = 0;
        public static List<CraftingCookingTableRecipe> m_recipes = new List<CraftingCookingTableRecipe>();
        public static List<CraftingCookingTableRecipe> Recipes => m_recipes;
        public static bool EnableLevelRestrictions = true;

        public static void Initialize()
        {
            if (Index == 0)
            {
                // 从XML文件加载配方数据
                XElement recipesRoot = ContentManager.Get<XElement>("CraftingCookingTableRecipes");

                foreach (XElement recipeElement in recipesRoot.Descendants("Recipe"))
                {
                    try
                    {
                        CraftingCookingTableRecipe recipe = DecodeRecipeElement(recipeElement);
                        if (recipe != null)
                        {
                            m_recipes.Add(recipe);
                            Index++;
                        }
                    }
                    catch (Exception ex)
                    {
                        Log.Error($"Failed to load recipe: {ex.Message}");
                    }
                }

                // 排序配方
                m_recipes.Sort((r1, r2) =>
                {
                    if (r1.DisplayOrder == r2.DisplayOrder)
                    {
                        return Comparer<int>.Default.Compare(r1.Ingredients.Count, r2.Ingredients.Count);
                    }
                    return Comparer<int>.Default.Compare(r1.DisplayOrder, r2.DisplayOrder);
                });

                Log.Information($"Loaded {Index} crafting cookingTable recipes");
            }
        }

        public static CraftingCookingTableRecipe DecodeRecipeElement(XElement recipeElement)
        {
            CraftingCookingTableRecipe recipe = new CraftingCookingTableRecipe();

            // 解析基础属性
            recipe.Description = XmlUtils.GetAttributeValue<string>(recipeElement, "Description");
            recipe.Message = XmlUtils.GetAttributeValue<string>(recipeElement, "Message");
            recipe.DisplayOrder = XmlUtils.GetAttributeValue(recipeElement, "DisplayOrder", 0);
            recipe.RequiredCookingTableLevel = XmlUtils.GetAttributeValue(recipeElement, "RequiredCookingTableLevel", 0);
            recipe.TimeConsuming = XmlUtils.GetAttributeValue(recipeElement, "TimeConsuming", 0);

            // 解析材料 (a-z 和对应的数量属性)
            for (char c = 'a'; c <= 'z'; c++)
            {
                string ingredientKey = c.ToString();
                string countKey = c + "count";

                string ingredientValue = XmlUtils.GetAttributeValue<string>(recipeElement, ingredientKey, null);
                int ingredientCount = XmlUtils.GetAttributeValue(recipeElement, countKey, 1);

                if (!string.IsNullOrEmpty(ingredientValue))
                {
                    string[] array = ingredientValue.Split([':'], StringSplitOptions.None);
                    string craftingId = array[0];
                    int? data = array.Length >= 2 ? new int?(int.Parse(array[1], CultureInfo.InvariantCulture)) : null;

                    // 验证材料是否存在
                    if (BlocksManager.FindBlocksByCraftingId(craftingId).Length == 0)
                    {
                        throw new InvalidOperationException($"Block with craftingId \"{ingredientValue}\" not found.");
                    }

                    if (data.HasValue && (data.Value < 0 || data.Value > 262143))
                    {
                        throw new InvalidOperationException($"Data in recipe ingredient \"{ingredientValue}\" must be between 0 and 0x3FFFF.");
                    }

                    // 生成完整的材料ID（包含数据值）
                    string fullIngredientId = craftingId;
                    if (data.HasValue)
                    {
                        fullIngredientId += ":" + data.Value;
                    }

                    // 添加到材料字典
                    if (recipe.Ingredients.ContainsKey(fullIngredientId))
                    {
                        recipe.Ingredients[fullIngredientId] += ingredientCount;
                    }
                    else
                    {
                        recipe.Ingredients[fullIngredientId] = ingredientCount;
                    }
                }
            }

            return recipe;
        }

        public static CraftingCookingTableRecipe FindMatchingRecipe(Dictionary<string, int> inputIngredients, int cookingTableLevel)
        {
            if (inputIngredients == null || inputIngredients.Count == 0)
            {
                return null;
            }

            // 检查预定义配方
            foreach (CraftingCookingTableRecipe recipe in Recipes)
            {
                // 检查烹饪台等级限制
                if (EnableLevelRestrictions && recipe.RequiredCookingTableLevel != cookingTableLevel)
                {
                    continue;
                }

                if (MatchRecipe(recipe.Ingredients, inputIngredients))
                {
                    return recipe;
                }
            }

            return null;
        }

        public static bool MatchRecipe(Dictionary<string, int> requiredIngredients, Dictionary<string, int> actualIngredients)
        {
            // 如果材料数量不匹配，直接返回false
            if (requiredIngredients.Count != actualIngredients.Count)
            {
                return false;
            }

            // 检查每个材料是否匹配
            foreach (var kvp in requiredIngredients)
            {
                string ingredientId = kvp.Key;
                int requiredCount = kvp.Value;

                if (!actualIngredients.TryGetValue(ingredientId, out int actualCount) || actualCount != requiredCount)
                {
                    return false;
                }
            }

            return true;
        }
    }
}
//烹饪台维修界面
namespace Game
{
    public class CookingTableMaintenanceWidget : CanvasWidget
    {
        public ComponentPlayer m_componentPlayer;
        public ComponentCookingTable m_componentCookingTable;
        public ComponentUpgradeAndMaintenanceCookingTable m_componentUpgradeAndMaintenanceCookingTable;

        public BlockIconWidget icon;
        public LabelWidget levelLabel;
        public LabelWidget descriptionLabel;
        public LabelWidget timeConsumingLabel;
        public BevelledButtonWidget cancelItButton;
        public BevelledButtonWidget iAmSureButton;

        public CraftingCookingTableRecipe craftingCookingTableRecipe;

        public Dictionary<BlockIconWidget, LabelWidget> Ingredients = new Dictionary<BlockIconWidget, LabelWidget>();

        public CookingTableMaintenanceWidget(ComponentPlayer componentPlayer, ComponentCookingTable componentCookingTable)
        {
            m_componentPlayer = componentPlayer;
            m_componentCookingTable = componentCookingTable;
            m_componentUpgradeAndMaintenanceCookingTable = m_componentCookingTable.Entity.FindComponent<ComponentUpgradeAndMaintenanceCookingTable>();
            XElement node = ContentManager.Get<XElement>("Widgets/CookingTableMaintenanceWidget");
            LoadContents(this, node);
            icon = Children.Find<BlockIconWidget>("Icon");
            levelLabel = Children.Find<LabelWidget>("LevelLabel");
            descriptionLabel = Children.Find<LabelWidget>("DescriptionLabel");
            for (int a = 1; a < 27; a++)
            {
                Ingredients.Add(Children.Find<BlockIconWidget>("Materials" + a), Children.Find<LabelWidget>("Materials" + a + "Label"));
            }
            timeConsumingLabel = Children.Find<LabelWidget>("TimeConsumingLabel");
            cancelItButton = Children.Find<BevelledButtonWidget>("CancelItButton");
            iAmSureButton = Children.Find<BevelledButtonWidget>("IAmSureButton");
        }

        public override void Update()
        {
            icon.Value = Terrain.MakeBlockValue(NewCookingTable.Index, 0, m_componentCookingTable.Level);
            levelLabel.Text = "等级:" + (m_componentCookingTable.Level);

            if (cancelItButton.IsClicked)
            {
                m_componentPlayer.ComponentGui.ModalPanelWidget = new CookingTableWidget(m_componentPlayer, m_componentCookingTable);
            }
            if (iAmSureButton.IsClicked && craftingCookingTableRecipe != null)
            {
                m_componentUpgradeAndMaintenanceCookingTable.TryMaintainCookingTable(craftingCookingTableRecipe, m_componentPlayer);
                craftingCookingTableRecipe = null;
            }

            if (craftingCookingTableRecipe == null)
            {
                foreach (CraftingCookingTableRecipe recipe in CraftingCookingTableRecipeManager.Recipes)
                {
                    if (m_componentCookingTable.Level - 1 == recipe.RequiredCookingTableLevel)
                    {
                        craftingCookingTableRecipe = recipe;
                        descriptionLabel.Text = recipe.Description;
                        timeConsumingLabel.Text = "耗时:" + recipe.TimeConsuming + "分钟";
                        for (int a = 0; a < 26; a++)
                        {
                            try
                            {
                                string[] safeParts = recipe.Ingredients.ElementAt(a).Key.Split(':');
                                string beforeChar = safeParts[0];
                                string afterChar = safeParts.Length > 1 ? safeParts[1] : string.Empty;
                                Ingredients.ElementAt(a).Key.Value = Terrain.MakeBlockValue(BlocksManager.FindBlocksByCraftingId(beforeChar)[0].BlockIndex, 0, int.Parse(afterChar));
                                Ingredients.ElementAt(a).Value.Text = "X" + recipe.Ingredients.ElementAt(a).Value;
                            }
                            catch
                            {
                                Ingredients.ElementAt(a).Key.Value = 0;
                                Ingredients.ElementAt(a).Value.Text = "";
                            }
                        }
                    }
                }
            }
        }
    }
}
