//组件烹饪台升级或维修
namespace Game
{
    public class ComponentUpgradeAndMaintenanceCookingTable : ComponentInventoryBase, IUpdateable
    {
        public ComponentBlockEntity componentBlockEntity;
        public ComponentCookingTable componentCookingTable;
        public SubsystemPickables subsystemPickables;
        public SubsystemTime subsystemTime;
        public SubsystemGameInfo subsystemGameInfo;
        public SubsystemTerrain subsystemTerrain;
        public SubsystemAudio subsystemAudio;

        // 配方匹配
        public CraftingCookingTableRecipe m_matchedUpgradeRecipe;
        public CraftingCookingTableRecipe m_matchedMaintenanceRecipe;
        public bool m_recipeUpdateNeeded;
        public bool m_recipeRefindNeeded;
        public int Level;
        public int Durability;

        // 升级时间相关字段
        public double m_upgradeStartTime;
        public double m_upgradeDuration;
        public bool m_isUpgrading;
        public CraftingCookingTableRecipe m_currentUpgradeRecipe;
        public ComponentPlayer m_currentUpgradingPlayer;

        // 维修时间相关字段
        public double m_maintenanceStartTime;
        public double m_maintenanceDuration;
        public bool m_isMaintaining;
        public CraftingCookingTableRecipe m_currentMaintenanceRecipe;
        public ComponentPlayer m_currentMaintainingPlayer;

        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public virtual void Update(float dt)
        {
            // 处理升级时间逻辑
            if (m_isUpgrading)
            {
                if (!CheckConditions(m_currentUpgradingPlayer))
                {
                    CancelOperationDueToConditions("升级");
                    return;
                }

                subsystemTime.m_gameTimeFactor = 120;
                double currentTime = subsystemGameInfo.TotalElapsedGameTime;
                double elapsedTime = (currentTime - m_upgradeStartTime);

                if (elapsedTime >= m_upgradeDuration)
                {
                    subsystemTime.m_gameTimeFactor = 1;
                    CompleteUpgrade();
                }
            }

            // 处理维修时间逻辑
            if (m_isMaintaining)
            {
                if (!CheckConditions(m_currentMaintainingPlayer))
                {
                    CancelOperationDueToConditions("维修");
                    return;
                }

                subsystemTime.m_gameTimeFactor = 120;
                double currentTime = subsystemGameInfo.TotalElapsedGameTime;
                double elapsedTime = (currentTime - m_maintenanceStartTime);

                if (elapsedTime >= m_maintenanceDuration)
                {
                    subsystemTime.m_gameTimeFactor = 1;
                    CompleteMaintenance();
                }
            }

            if (m_recipeUpdateNeeded)
            {
                UpdateRecipeResult(m_recipeRefindNeeded);
            }
            m_recipeUpdateNeeded = false;
            m_recipeRefindNeeded = false;

            UpdateCookingTableStatus();
        }

        public void UpdateCookingTableStatus()
        {
            if (componentBlockEntity != null && componentCookingTable != null)
            {
                Level = componentCookingTable.Level;
                Durability = componentCookingTable.Durability;
            }
        }

        // 通用条件检查
        public bool CheckConditions(ComponentPlayer player)
        {
            if (IsPlayerDeadOrInvalid(player)) return false;

            ComponentVitalStats vitalStats = player.ComponentVitalStats;
            if (vitalStats != null && vitalStats.Sleep <= 0.2f)
            {
                player.ComponentGui.DisplaySmallMessage("太困了，无法继续操作！", Color.Red, true, true);
                return false;
            }

            return true;
        }

        // 通用取消操作
        public void CancelOperationDueToConditions(string operationType)
        {
            ComponentPlayer currentPlayer = operationType == "升级" ? m_currentUpgradingPlayer : m_currentMaintainingPlayer;
            if (currentPlayer != null)
            {
                currentPlayer.ComponentGui.DisplaySmallMessage($"{operationType}已取消", Color.Yellow, true, true);
            }

            subsystemTime.m_gameTimeFactor = 1;

            if (operationType == "升级")
            {
                m_isUpgrading = false;
                m_currentUpgradeRecipe = null;
                m_currentUpgradingPlayer = null;
            }
            else
            {
                m_isMaintaining = false;
                m_currentMaintenanceRecipe = null;
                m_currentMaintainingPlayer = null;
            }
        }

        public override void AddSlotItems(int slotIndex, int value, int count)
        {
            base.AddSlotItems(slotIndex, value, count);
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }

        public override int RemoveSlotItems(int slotIndex, int count)
        {
            int num = base.RemoveSlotItems(slotIndex, count);
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
            return num;
        }

        public virtual void UpdateRecipeResult(bool recipeRefindNeeded)
        {
            ComponentPlayer componentPlayer = FindInteractingPlayer();
            if (componentPlayer == null) return;

            if (IsPlayerDeadOrInvalid(componentPlayer) || !CheckConditions(componentPlayer)) return;

            Dictionary<string, int> playerIngredients = GetPlayerIngredients(componentPlayer);

            // 根据当前界面类型更新对应的配方
            if (componentPlayer.ComponentGui.ModalPanelWidget is CookingTableUpgradeWidget)
            {
                UpdateUpgradeRecipe(recipeRefindNeeded, playerIngredients, componentPlayer);
            }
            else if (componentPlayer.ComponentGui.ModalPanelWidget is CookingTableMaintenanceWidget)
            {
                UpdateMaintenanceRecipe(recipeRefindNeeded, playerIngredients, componentPlayer);
            }
        }

        public void UpdateUpgradeRecipe(bool recipeRefindNeeded, Dictionary<string, int> playerIngredients, ComponentPlayer player)
        {
            CraftingCookingTableRecipe upgradeRecipe;
            if (recipeRefindNeeded || m_matchedUpgradeRecipe == null)
            {
                upgradeRecipe = CraftingCookingTableRecipeManager.FindMatchingRecipe(playerIngredients, Level);
            }
            else
            {
                upgradeRecipe = m_matchedUpgradeRecipe;
            }

            if (upgradeRecipe != null)
            {
                m_matchedUpgradeRecipe = upgradeRecipe;
                if (CheckIngredientsAvailable(upgradeRecipe, player, out var lackDict))
                {
                    player.ComponentGui.DisplaySmallMessage($"可以升级到{upgradeRecipe.Description}！", Color.Green, true, true);
                }
            }
            else
            {
                m_matchedUpgradeRecipe = null;
            }
        }

        public void UpdateMaintenanceRecipe(bool recipeRefindNeeded, Dictionary<string, int> playerIngredients, ComponentPlayer player)
        {
            CraftingCookingTableRecipe maintenanceRecipe;
            if (recipeRefindNeeded || m_matchedMaintenanceRecipe == null)
            {
                maintenanceRecipe = CraftingCookingTableRecipeManager.FindMatchingRecipe(playerIngredients, Level);
            }
            else
            {
                maintenanceRecipe = m_matchedMaintenanceRecipe;
            }

            if (maintenanceRecipe != null)
            {
                m_matchedMaintenanceRecipe = maintenanceRecipe;
                if (CheckIngredientsAvailable(maintenanceRecipe, player, out var lackDict))
                {
                    player.ComponentGui.DisplaySmallMessage($"可以维修烹饪台！", Color.Green, true, true);
                }
            }
            else
            {
                m_matchedMaintenanceRecipe = null;
            }
        }

        public Dictionary<string, int> GetPlayerIngredients(ComponentPlayer player)
        {
            Dictionary<string, int> playerIngredients = new Dictionary<string, int>();
            ComponentInventory playerInventory = player.Entity.FindComponent<ComponentInventory>();

            for (int i = 0; i < playerInventory.SlotsCount; i++)
            {
                int slotValue = playerInventory.GetSlotValue(i);
                int slotCount = playerInventory.GetSlotCount(i);

                if (slotValue != 0 && slotCount > 0)
                {
                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string ingredientKey = $"{craftingId}:{data}";

                    if (playerIngredients.ContainsKey(ingredientKey))
                    {
                        playerIngredients[ingredientKey] += slotCount;
                    }
                    else
                    {
                        playerIngredients[ingredientKey] = slotCount;
                    }
                }
            }

            return playerIngredients;
        }

        public bool CheckIngredientsAvailable(CraftingCookingTableRecipe recipe, ComponentPlayer player, out Dictionary<string, int> lackDict)
        {
            lackDict = new Dictionary<string, int>();
            if (IsPlayerDeadOrInvalid(player)) return false;

            Dictionary<string, int> playerIngredients = GetPlayerIngredients(player);

            foreach (var ingredient in recipe.Ingredients)
            {
                string ingredientId = ingredient.Key;
                int requiredCount = ingredient.Value;
                int actualCount = playerIngredients.ContainsKey(ingredientId) ? playerIngredients[ingredientId] : 0;

                if (actualCount < requiredCount)
                {
                    lackDict[ingredientId] = requiredCount - actualCount;
                }
            }

            return lackDict.Count == 0;
        }

        // 开始操作（升级或维修）
        public bool StartOperation(ComponentPlayer player, CraftingCookingTableRecipe recipe, string operationType)
        {
            if (IsPlayerDeadOrInvalid(player) || !CheckConditions(player))
            {
                player.ComponentGui.DisplaySmallMessage($"无法开始{operationType}：条件不满足", Color.Red, true, true);
                return false;
            }

            bool isOperating = operationType == "升级" ? m_isUpgrading : m_isMaintaining;
            if (isOperating)
            {
                player.ComponentGui.DisplaySmallMessage($"正在{operationType}中，请等待完成！", Color.Yellow, true, true);
                return false;
            }

            if (!CheckIngredientsAvailable(recipe, player, out var lackDict))
            {
                player.ComponentGui.DisplaySmallMessage("材料不足！", Color.Red, true, true);
                return false;
            }

            double operationTimeSeconds = recipe.TimeConsuming;

            if (operationType == "升级")
            {
                m_upgradeDuration = operationTimeSeconds;
                m_upgradeStartTime = subsystemGameInfo.TotalElapsedGameTime;
                m_isUpgrading = true;
                m_currentUpgradeRecipe = recipe;
                m_currentUpgradingPlayer = player;
            }
            else
            {
                m_maintenanceDuration = operationTimeSeconds;
                m_maintenanceStartTime = subsystemGameInfo.TotalElapsedGameTime;
                m_isMaintaining = true;
                m_currentMaintenanceRecipe = recipe;
                m_currentMaintainingPlayer = player;
            }

            player.ComponentGui.DisplaySmallMessage($"开始{operationType}烹饪台：{recipe.Description}，预计需要 {operationTimeSeconds} 分钟", Color.Yellow, true, true);
            return true;
        }

        // 完成升级
        public void CompleteUpgrade()
        {
            if (IsPlayerDeadOrInvalid(m_currentUpgradingPlayer) || !CheckConditions(m_currentUpgradingPlayer))
            {
                CancelOperationDueToConditions("升级");
                return;
            }

            if (!m_isUpgrading || m_currentUpgradeRecipe == null || m_currentUpgradingPlayer == null)
            {
                m_isUpgrading = false;
                return;
            }

            if (ConsumeIngredientsAndOperate(m_currentUpgradingPlayer, m_currentUpgradeRecipe, "升级"))
            {
                m_currentUpgradingPlayer.ComponentGui.DisplaySmallMessage($"烹饪台升级成功：{m_currentUpgradeRecipe.Description}！", Color.Green, true, true);

                if (!string.IsNullOrEmpty(m_currentUpgradeRecipe.Message))
                {
                    m_currentUpgradingPlayer.ComponentGui.DisplaySmallMessage(m_currentUpgradeRecipe.Message, Color.White, true, true);
                }
            }

            ResetOperationState("升级");
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }

        // 完成维修
        public void CompleteMaintenance()
        {
            if (IsPlayerDeadOrInvalid(m_currentMaintainingPlayer) || !CheckConditions(m_currentMaintainingPlayer))
            {
                CancelOperationDueToConditions("维修");
                return;
            }

            if (!m_isMaintaining || m_currentMaintenanceRecipe == null || m_currentMaintainingPlayer == null)
            {
                m_isMaintaining = false;
                return;
            }

            if (ConsumeIngredientsAndOperate(m_currentMaintainingPlayer, m_currentMaintenanceRecipe, "维修"))
            {
                m_currentMaintainingPlayer.ComponentGui.DisplaySmallMessage($"烹饪台维修成功！", Color.Green, true, true);

                if (!string.IsNullOrEmpty(m_currentMaintenanceRecipe.Message))
                {
                    m_currentMaintainingPlayer.ComponentGui.DisplaySmallMessage(m_currentMaintenanceRecipe.Message, Color.White, true, true);
                }
            }

            ResetOperationState("维修");
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }

        // 消耗材料并执行操作
        public bool ConsumeIngredientsAndOperate(ComponentPlayer player, CraftingCookingTableRecipe recipe, string operationType)
        {
            if (IsPlayerDeadOrInvalid(player) || !CheckConditions(player)) return false;

            ComponentInventory playerInventory = player.Entity.FindComponent<ComponentInventory>();

            if (!CheckIngredientsAvailable(recipe, player, out var lackDict)) return false;

            // 消耗材料
            foreach (var ingredient in recipe.Ingredients)
            {
                string ingredientId = ingredient.Key;
                int totalRequiredCount = ingredient.Value;
                int remainingToConsume = totalRequiredCount;

                for (int i = 0; i < playerInventory.SlotsCount && remainingToConsume > 0; i++)
                {
                    int slotValue = playerInventory.GetSlotValue(i);
                    if (slotValue == 0) continue;

                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string currentIngredientId = $"{craftingId}:{data}";

                    if (currentIngredientId == ingredientId)
                    {
                        int availableCount = playerInventory.GetSlotCount(i);
                        int consumeCount = Math.Min(availableCount, remainingToConsume);
                        playerInventory.RemoveSlotItems(i, consumeCount);
                        remainingToConsume -= consumeCount;
                    }
                }
            }

            // 执行操作
            if (operationType == "升级")
            {
                PerformCookingTableUpgrade(recipe);
            }
            else
            {
                PerformCookingTableMaintenance(recipe);
            }

            return true;
        }

        // 执行烹饪台升级
        public void PerformCookingTableUpgrade(CraftingCookingTableRecipe recipe)
        {
            if (componentBlockEntity == null || subsystemTerrain == null) return;

            int newLevel = Level + 1;
            int newBlockValue = Terrain.MakeBlockValue(NewCookingTable.Index, 0, NewCookingTable.SetType(componentBlockEntity.BlockValue, NewCookingTable.GetType(componentBlockEntity.BlockValue) + 1));
            newBlockValue = BlocksManager.Blocks[Terrain.ExtractContents(newBlockValue)].SetDamage(newBlockValue, BlocksManager.Blocks[Terrain.ExtractContents(newBlockValue)].GetDurability(newBlockValue));

            subsystemTerrain.ChangeCell(
                componentBlockEntity.Coordinates.X,
                componentBlockEntity.Coordinates.Y,
                componentBlockEntity.Coordinates.Z,
                newBlockValue
            );

            componentBlockEntity.BlockValue = newBlockValue;
        }

        // 执行烹饪台维修
        public void PerformCookingTableMaintenance(CraftingCookingTableRecipe recipe)
        {
            if (componentBlockEntity == null || subsystemTerrain == null) return;

            // 修复烹饪台耐久度
            int repairedBlockValue = BlocksManager.Blocks[Terrain.ExtractContents(componentBlockEntity.BlockValue)].SetDamage(componentBlockEntity.BlockValue, BlocksManager.Blocks[Terrain.ExtractContents(componentBlockEntity.BlockValue)].GetDurability(componentBlockEntity.BlockValue));

            subsystemTerrain.ChangeCell(
                componentBlockEntity.Coordinates.X,
                componentBlockEntity.Coordinates.Y,
                componentBlockEntity.Coordinates.Z,
                repairedBlockValue
            );
        }

        public int CreateUpgradedBlockValue(int newLevel)
        {
            int content = Terrain.ExtractContents(componentBlockEntity.BlockValue);
            int currentData = Terrain.ExtractData(componentBlockEntity.BlockValue);
            int newData = (currentData & ~0xF) | (newLevel & 0xF);
            return Terrain.MakeBlockValue(content, 0, newData);
        }

        // 获取操作进度
        public float GetOperationProgress(string operationType)
        {
            if (operationType == "升级" && !m_isUpgrading) return 0f;
            if (operationType == "维修" && !m_isMaintaining) return 0f;

            double currentTime = subsystemGameInfo.TotalElapsedGameTime;
            double startTime = operationType == "升级" ? m_upgradeStartTime : m_maintenanceStartTime;
            double duration = operationType == "升级" ? m_upgradeDuration : m_maintenanceDuration;
            double elapsedTime = (currentTime - startTime) * subsystemTime.m_gameTimeFactor;

            return MathUtils.Clamp((float)(elapsedTime / duration), 0f, 1f);
        }

        // 检查是否正在操作
        public bool IsOperating(string operationType)
        {
            return operationType == "升级" ? m_isUpgrading : m_isMaintaining;
        }

        // 获取当前操作信息
        public string GetCurrentOperationInfo(string operationType)
        {
            CraftingCookingTableRecipe currentRecipe = operationType == "升级" ? m_currentUpgradeRecipe : m_currentMaintenanceRecipe;
            if ((operationType == "升级" && !m_isUpgrading) || (operationType == "维修" && !m_isMaintaining) || currentRecipe == null)
                return string.Empty;

            float progress = GetOperationProgress(operationType) * 100f;
            double startTime = operationType == "升级" ? m_upgradeStartTime : m_maintenanceStartTime;
            double duration = operationType == "升级" ? m_upgradeDuration : m_maintenanceDuration;
            double remainingTime = (duration - (subsystemGameInfo.TotalElapsedGameTime - startTime) * subsystemTime.m_gameTimeFactor);

            return $"正在{operationType}: {currentRecipe.Description}\n进度: {progress:F1}%\n剩余时间: {remainingTime:F1}分钟";
        }

        // 尝试升级烹饪台
        public bool TryUpgradeCookingTable(CraftingCookingTableRecipe recipe, ComponentPlayer player)
        {
            return TryOperateCookingTable(recipe, player, "升级");
        }

        // 尝试维修烹饪台
        public bool TryMaintainCookingTable(CraftingCookingTableRecipe recipe, ComponentPlayer player)
        {
            return TryOperateCookingTable(recipe, player, "维修");
        }

        public bool TryOperateCookingTable(CraftingCookingTableRecipe recipe, ComponentPlayer player, string operationType)
        {
            if (recipe == null || player == null) return false;

            if (IsPlayerDeadOrInvalid(player) || !CheckConditions(player))
            {
                player.ComponentGui.DisplaySmallMessage($"无法{operationType}：条件不满足", Color.Red, true, true);
                return false;
            }

            // 检查材料，并获取缺少字典
            if (!CheckIngredientsAvailable(recipe, player, out var lackDict))
            {
                // 只在这里弹窗一次，显示缺少的材料
                DialogsManager.ShowDialog(null, new ShellSupplementMaterialsDialog(player, lackDict));
                player.ComponentGui.DisplaySmallMessage("材料不足！", Color.Red, true, true);
                return false;
            }

            // 播放音效
            if (operationType == "维修")
                subsystemAudio.PlaySound("Audio/UI/Production/Maintenance", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
            else
                subsystemAudio.PlaySound("Audio/UI/Production/Upgrade", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);

            return StartOperation(player, recipe, operationType);
        }

        public void ResetOperationState(string operationType)
        {
            if (operationType == "升级")
            {
                m_currentUpgradingPlayer.ComponentGui.ModalPanelWidget = null;
                m_isUpgrading = false;
                m_currentUpgradeRecipe = null;
                m_currentUpgradingPlayer = null;
            }
            else
            {
                m_currentMaintainingPlayer.PlayerStats.ValuesDictionaryForMods["NumberOfKitchenCounterRepairs"] = (m_currentMaintainingPlayer.PlayerStats.ValuesDictionaryForMods.ContainsKey("NumberOfKitchenCounterRepairs") ? (int)m_currentMaintainingPlayer.PlayerStats.ValuesDictionaryForMods["NumberOfKitchenCounterRepairs"] + 1 : 1);
                m_currentMaintainingPlayer.ComponentGui.ModalPanelWidget = null;
                m_isMaintaining = false;
                m_currentMaintenanceRecipe = null;
                m_currentMaintainingPlayer = null;
            }
        }

        public bool IsPlayerDeadOrInvalid(ComponentPlayer player)
        {
            if (player == null) return true;

            ComponentHealth health = player.Entity.FindComponent<ComponentHealth>();
            if (health != null && health.Health <= 0f) return true;

            // 检查玩家是否打开正确的界面
            if (!(player.ComponentGui.ModalPanelWidget is CookingTableUpgradeWidget) &&
                !(player.ComponentGui.ModalPanelWidget is CookingTableMaintenanceWidget))
            {
                return true;
            }

            if (componentBlockEntity != null)
            {
                float distance = Vector3.Distance(player.ComponentBody.Position, componentBlockEntity.Position);
                if (distance > 5f) return true;
            }

            return false;
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            componentBlockEntity = Entity.FindComponent<ComponentBlockEntity>(throwOnError: true);
            componentCookingTable = Entity.FindComponent<ComponentCookingTable>(throwOnError: true);
            subsystemPickables = Project.FindSubsystem<SubsystemPickables>(throwOnError: true);
            subsystemTime = Project.FindSubsystem<SubsystemTime>();
            subsystemGameInfo = Project.FindSubsystem<SubsystemGameInfo>();
            subsystemTerrain = Project.FindSubsystem<SubsystemTerrain>();
            subsystemAudio = Project.FindSubsystem<SubsystemAudio>();
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }
    }
}
//天赋界面
namespace Game
{
    public class TalentWidget : CanvasWidget
    {
        public ComponentPlayer m_componentPlayer;
        public ComponentTalent m_componentTalent;
        public SubsystemAudio m_subsystemAudio;

        public Random m_random = new();

        public Dictionary<string, (BitmapButtonWidget talent, BitmapButtonWidget level, BitmapButtonWidget lockBtn)> talentButtons =
            new Dictionary<string, (BitmapButtonWidget, BitmapButtonWidget, BitmapButtonWidget)>();
        public Dictionary<string, BitmapButtonWidget> lockDownButtons =
            new Dictionary<string, BitmapButtonWidget>();

        public TalentWidget(ComponentPlayer componentPlayer)
        {
            m_componentPlayer = componentPlayer;
            m_componentTalent = m_componentPlayer.Entity.FindComponent<ComponentTalent>();
            m_subsystemAudio = m_componentPlayer.Project.FindSubsystem<SubsystemAudio>();
            XElement node = ContentManager.Get<XElement>("Widgets/TalentWidget");
            LoadContents(this, node);

            for (int i = 1; i <= 3; i++)
            {
                string key = $"FightingTalent{i}";
                talentButtons[key] = (
                    Children.Find<BitmapButtonWidget>($"FightingTalent{i}Button"),
                    Children.Find<BitmapButtonWidget>($"FightingTalentLevel{i}Button"),
                    Children.Find<BitmapButtonWidget>($"FightingLockTalent{i}Button")
                );
                if (i < 3) lockDownButtons[$"FightingLockItDownTalent{i}"] = Children.Find<BitmapButtonWidget>($"FightingLockItDownTalent{i}Button");
            }

            for (int i = 1; i <= 3; i++)
            {
                string key = $"SurvivalTalent{i}";
                talentButtons[key] = (
                    Children.Find<BitmapButtonWidget>($"SurvivalTalent{i}Button"),
                    Children.Find<BitmapButtonWidget>($"SurvivalTalentLevel{i}Button"),
                    Children.Find<BitmapButtonWidget>($"SurvivalLockTalent{i}Button")
                );
                if (i < 3) lockDownButtons[$"SurvivalLockItDownTalent{i}"] = Children.Find<BitmapButtonWidget>($"SurvivalLockItDownTalent{i}Button");
            }

            for (int i = 1; i <= 3; i++)
            {
                string key = $"ExplorationTalent{i}";
                talentButtons[key] = (
                    Children.Find<BitmapButtonWidget>($"ExplorationTalent{i}Button"),
                    Children.Find<BitmapButtonWidget>($"ExplorationTalentLevel{i}Button"),
                    Children.Find<BitmapButtonWidget>($"ExplorationLockTalent{i}Button")
                );
                if (i < 3) lockDownButtons[$"ExplorationLockItDownTalent{i}"] = Children.Find<BitmapButtonWidget>($"ExplorationLockItDownTalent{i}Button");
            }
        }

        public override void Update()
        {
            // 重置所有锁定按钮状态
            foreach (var btnGroup in talentButtons.Values)
                btnGroup.lockBtn.IsVisible = false;

            // 处理激活的天赋
            foreach (AccessTalent at in AccessTalentManager.Data.Where(a => a.Field > 0))
            {
                string key = $"{at.TalentType}{at.Field}";
                if (talentButtons.TryGetValue(key, out var buttons))
                {
                    // 设置天赋图标
                    Texture2D tex = ContentManager.Get<Texture2D>(at.Texture);
                    buttons.talent.NormalSubtexture = buttons.talent.ClickedSubtexture = tex;

                    // 显示锁定按钮（表示已解锁）
                    buttons.lockBtn.IsVisible = true;

                    // 设置等级图标
                    int level = Math.Min(at.Level, at.MaxLevel);
                    string levelTexPath = $"Textures/Gui/Talent/TalentLevel{level}";
                    Texture2D levelTex = ContentManager.Get<Texture2D>(levelTexPath);
                    buttons.level.NormalSubtexture = buttons.level.ClickedSubtexture = levelTex;
                }
            }

            // 处理锁定按钮的点击（已解锁的天赋）
            foreach (var kvp in talentButtons)
            {
                var lockBtn = kvp.Value.lockBtn;
                if (lockBtn.IsVisible && lockBtn.IsClicked)
                {
                    m_subsystemAudio.PlayRandomSound("Audio/UI/Talent/Chains", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
                }
            }

            // 设置时间锁定的按钮
            double gameTime = m_componentPlayer.m_subsystemGameInfo.TotalElapsedGameTime;
            string[] types = { "Fighting", "Survival", "Exploration" };
            foreach (var type in types)
            {
                for (int i = 1; i <= 2; i++)
                {
                    string key = $"{type}LockItDownTalent{i}";
                    if (lockDownButtons.TryGetValue(key, out var btn))
                    {
                        bool isLocked = gameTime <= (i == 1 ? 24000 : 48000);
                        btn.IsVisible = isLocked;
                        if (btn.IsVisible && btn.IsClicked)
                        {
                            m_subsystemAudio.PlayRandomSound("Audio/UI/Talent/TimeLock", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
                        }
                    }
                }
            }

            // 设置等级按钮的可见性
            foreach (var kvp in talentButtons)
                kvp.Value.level.IsVisible = kvp.Value.lockBtn.IsVisible;

            // 处理天赋按钮点击（触发对话框）
            string[][] talentGroups = new string[][]
            {
                new[] { "FightingTalent1Button", "FightingTalent2Button", "FightingTalent3Button" },
                new[] { "SurvivalTalent1Button", "SurvivalTalent2Button", "SurvivalTalent3Button" },
                new[] { "ExplorationTalent1Button", "ExplorationTalent2Button", "ExplorationTalent3Button" }
            };
            string[] groupNames = { "FightingTalent", "SurvivalTalent", "ExplorationTalent" };

            for (int g = 0; g < talentGroups.Length; g++)
            {
                for (int i = 0; i < talentGroups[g].Length; i++)
                {
                    if (Children.Find<BitmapButtonWidget>(talentGroups[g][i]).IsClicked)
                    {
                        DialogsManager.ShowDialog(null, new TalentChoiceDialog(groupNames[g], i + 1, m_subsystemAudio));
                        return;
                    }
                }
            }
        }
    }
}
//组件天赋
namespace Game
{
    public class ComponentTalent : Component, IUpdateable
    {
        public ComponentHealth componentHealth;
        public ComponentExtraAttributes componentExtraAttributes;
        public ComponentBody componentBody;
        public ComponentPhysicalAttributes componentPhysicalAttributes;
        public ComponentHYZLVitalStats componentHYZLVitalStats;
        public ComponentPlayer componentPlayer;
        public SubsystemParticles subsystemParticles;
        public SubsystemTime subsystemTime;

        public bool LetTheBattleBegin = false;
        public bool Reading;
        public float BloodVolume;
        public int num;
        public List<AccessTalent> TalentAttributes = [];
        public bool hasPlayerTarget;
        public float m_checkTimer;
        public Project m_project;

        public Random m_random = new();

        public static string fName = "ComponentTalent";

        public static readonly HashSet<ComponentChaseBehavior> s_allChaseBehaviors = new();

        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public void OnProjectEntityAdded(object sender, EntityAddRemoveEventArgs args)
        {
            if (args.Entity.Project != m_project) return;
            var chase = args.Entity.FindComponent<ComponentChaseBehavior>();
            if (chase != null) s_allChaseBehaviors.Add(chase);
        }

        public void OnProjectEntityRemoved(object sender, EntityAddRemoveEventArgs args)
        {
            if (args.Entity.Project != m_project) return;
            var chase = args.Entity.FindComponent<ComponentChaseBehavior>();
            if (chase != null) s_allChaseBehaviors.Remove(chase);
        }

        public void Update(float dt)
        {
            // 检查并初始化必需的组件
            if (componentHealth == null || componentExtraAttributes == null ||
                componentBody == null || subsystemParticles == null)
                return;

            // 提前计算常用值
            float healthResilience = componentHealth.Health * componentExtraAttributes.AttackResilience;

            // 遍历所有天赋
            for (int a = 0; a < TalentAttributes.Count; a++)
            {
                AccessTalent talent = TalentAttributes[a];
                if (talent.Field <= 0) continue;

                m_checkTimer += dt;
                if (m_checkTimer >= 1f)
                {
                    m_checkTimer = 0f;
                    bool anyTargetingPlayer = false;
                    foreach (var chase in s_allChaseBehaviors)
                    {
                        if (chase.Target is ComponentPlayer)
                        {
                            anyTargetingPlayer = true;
                            break;
                        }
                    }

                    hasPlayerTarget = anyTargetingPlayer;
                }

                // 处理战斗状态变化
                if (!LetTheBattleBegin && hasPlayerTarget)
                {
                    LetTheBattleBegin = true;
                    if (talent.ReturnBloodWhenBattleIsOver > 0)
                    {
                        BloodVolume = healthResilience;
                    }
                }
                else if (LetTheBattleBegin && !hasPlayerTarget)
                {
                    LetTheBattleBegin = false;

                    // 处理战斗结束后的效果
                    if (talent.ReturnBloodWhenBattleIsOver > 0)
                    {
                        BloodVolume -= healthResilience;
                        float returnAmount = (float)Math.Round(
                            BloodVolume * talent.ReturnBloodWhenBattleIsOver +
                            (talent.Level - 1) * 0.04);

                        var particleSystem = new HitValueParticleSystem(
                            componentBody.Position,
                            componentBody.Velocity,
                            new Color(0, 255, 0),
                            "+" + NumericalProcessingManager.NumericalProcessing(returnAmount)
                        );
                        subsystemParticles.AddParticleSystem(particleSystem);

                        componentHealth.Health += returnAmount / componentExtraAttributes.AttackResilience;
                        if (componentHealth.Health > 1)
                        {
                            componentHealth.Health = 1;
                        }
                    }

                    if (talent.TheSpiritOfTheBattleIsLifted > 0)
                    {
                        float sleepIncrease = (talent.TheSpiritOfTheBattleIsLifted +
                                             (talent.Level - 1) * 0.5f) *
                                             componentPhysicalAttributes.SleepResistance / 100f;

                        var particleSystem = new HitValueParticleSystem(
                            componentBody.Position,
                            componentBody.Velocity,
                            new Color(100, 200, 255),
                            "+" + NumericalProcessingManager.NumericalProcessing(talent.TheSpiritOfTheBattleIsLifted)
                        );
                        subsystemParticles.AddParticleSystem(particleSystem);

                        componentHYZLVitalStats.Sleep += sleepIncrease;
                        if (componentHYZLVitalStats.Sleep > 1)
                        {
                            componentHYZLVitalStats.Sleep = 1;
                        }
                    }
                }
            }
        }

        public override void Save(ValuesDictionary valuesDictionary, EntityToIdMap entityToIdMap)
        {
            ValuesDictionary talentsDict = new();
            valuesDictionary.SetValue("Talents", talentsDict);

            for (int i = 0; i < TalentAttributes.Count; i++)
            {
                AccessTalent talent = TalentAttributes[i];
                ValuesDictionary talentDict = new();
                talentsDict.SetValue($"Talent{i}", talentDict);

                // 使用字典简化保存操作
                var talentProperties = new Dictionary<string, object>
                {
                    ["Have"] = talent.Have,
                    ["Field"] = talent.Field,
                    ["Level"] = talent.Level
                };

                foreach (var kvp in talentProperties)
                {
                    talentDict.SetValue(kvp.Key, kvp.Value);
                }
            }
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            // 初始化组件引用
            componentHealth = Entity.FindComponent<ComponentHealth>() ?? throw new InvalidOperationException("ComponentHealth not found");
            componentExtraAttributes = Entity.FindComponent<ComponentExtraAttributes>() ?? throw new InvalidOperationException("ComponentExtraAttributes not found");
            componentBody = Entity.FindComponent<ComponentBody>() ?? throw new InvalidOperationException("ComponentBody not found");
            componentPhysicalAttributes = Entity.FindComponent<ComponentPhysicalAttributes>();
            componentHYZLVitalStats = Entity.FindComponent<ComponentHYZLVitalStats>();
            componentPlayer = Entity.FindComponent<ComponentPlayer>();
            subsystemParticles = Project.FindSubsystem<SubsystemParticles>() ?? throw new InvalidOperationException("SubsystemParticles not found");
            subsystemTime = Project.FindSubsystem<SubsystemTime>();

            m_project = Project;

            // 初始化天赋列表
            TalentAttributes.Clear();
            TalentAttributes.AddRange(AccessTalentManager.Data);

            Project.EntityAdded += OnProjectEntityAdded;
            Project.EntityRemoved += OnProjectEntityRemoved;

            // 一次性填充当前所有已有的 ChaseBehavior
            foreach (Entity entity in Project.Entities)
            {
                var chase = entity.FindComponent<ComponentChaseBehavior>();
                if (chase != null) s_allChaseBehaviors.Add(chase);
            }

            // 计算初始状态
            hasPlayerTarget = false;
            foreach (var chase in s_allChaseBehaviors)
            {
                if (chase.Target is ComponentPlayer)
                {
                    hasPlayerTarget = true;
                    break;
                }
            }

            // 加载保存的天赋数据
            if (valuesDictionary.TryGetValue<ValuesDictionary>("Talents", out ValuesDictionary talentsDict) && (Reading || num == 0))
            {
                for (int j = 0; j < TalentAttributes.Count; j++)
                {
                    if (talentsDict.TryGetValue<ValuesDictionary>($"Talent{j}", out ValuesDictionary talentData))
                    {
                        AccessTalent talent = TalentAttributes[j];

                        // 使用字典简化加载操作
                        var propertySetters = new Dictionary<string, Action>
                        {
                            ["Have"] = () => talent.Have = PermanentlySavedAttributesManager.Talent[j].Item1,
                            ["Field"] = () => talent.Field = talentData.GetValue<int>("Field", talent.Field),
                            ["Level"] = () => talent.Level = PermanentlySavedAttributesManager.Talent[j].Item2
                        };

                        foreach (var setter in propertySetters.Values)
                        {
                            setter();
                        }
                    }
                }
            }
            else if (!valuesDictionary.TryGetValue<ValuesDictionary>("Talents", out ValuesDictionary talentsDict2))
            {
                for (int j = 0; j < TalentAttributes.Count; j++)
                {
                    TalentAttributes[j].Have = PermanentlySavedAttributesManager.Talent[j].Item1;
                    TalentAttributes[j].Level = PermanentlySavedAttributesManager.Talent[j].Item2;
                }
            }
            Reading = true;
            num++;
        }

        public override void OnEntityRemoved()
        {
            Project.EntityAdded -= OnProjectEntityAdded;
            Project.EntityRemoved -= OnProjectEntityRemoved;
            base.OnEntityRemoved();
        }
