//天赋选择对话
namespace Game
{
    public class TalentChoiceDialog : Dialog
    {
        public ListPanelWidget talentList;
        public BevelledButtonWidget okButton;

        public SubsystemAudio m_subsystemAudio;

        public string talentType;
        public int field;
        public string Text;

        public Random m_random = new();

        // 解释器ID与参数的映射表
        public static readonly Dictionary<int, double[]> TalentParamMap = new Dictionary<int, double[]>
        {
            {1, new double[] {3, 1.5}},
            {2, new double[] {8, 4}},
            {3, new double[] {8, 4}},
            {4, new double[] {15, 7.5}},
            {5, new double[] {3, 1.5}},
            {6, new double[] {5, 2.5}},
            {7, new double[] {8, 4}},
            {8, new double[] {1, 0.5, -20, 10}},
            {9, new double[] {15, 7.5, 15, 7.5}},
            {10, new double[] {1, 0.5}},
            {11, new double[] {3, 1.5}},
            {12, new double[] {10, 5}},
            {13, new double[] {10, 5}},
            {14, new double[] {15, 7.5}},
            {15, new double[] {15, 7.5}},
            {16, new double[] {10, 5}},
            {17, new double[] {30, 15}},
            {18, new double[] {100, 50}},
            {19, new double[] {10, 5}},
            {20, new double[] {10, 5}},
            {21, new double[] {8, 4}},
            {22, new double[] {3, 1.5}},
            {23, new double[] {4, 2}},
            {24, new double[] {8, 4}},
            {25, new double[] {10, 5}},
            {26, new double[] {20, 10}},
            {27, new double[] {4, 2}},
            {28, new double[] {0.5, 0.5}},
            {29, new double[] {10, 5}},
            {30, new double[] {9, -1}} // 特殊处理：9 - (level-1)
        };

        public TalentChoiceDialog(string TalentType, int Field, SubsystemAudio subsystemAudio)
        {
            talentType = TalentType;
            field = Field;

            m_subsystemAudio = subsystemAudio;

            XElement node = ContentManager.Get<XElement>("Dialogs/TalentChoiceDialog");
            LoadContents(this, node);
            talentList = Children.Find<ListPanelWidget>("TalentList");
            okButton = Children.Find<BevelledButtonWidget>("OkButton");
            talentList.ClearItems();

            talentList.ItemWidgetFactory = delegate (object item)
            {
                var accessTalent = (AccessTalent)item;
                XElement node2 = ContentManager.Get<XElement>("Widgets/TalentItem");
                var obj = (ContainerWidget)LoadWidget(this, node2, null);

                // 设置天赋按钮图标
                var talentButton = obj.Children.Find<BitmapButtonWidget>("TalentButton");
                talentButton.NormalSubtexture = talentButton.ClickedSubtexture = ContentManager.Get<Texture2D>(accessTalent.Texture);

                // 设置等级按钮图标
                var talentLevelButton = obj.Children.Find<BitmapButtonWidget>("TalentLevelButton");
                string levelTexture = "Textures/Gui/Talent/TalentLevel" + accessTalent.Level;
                talentLevelButton.NormalSubtexture = talentLevelButton.ClickedSubtexture = ContentManager.Get<Texture2D>(levelTexture);

                // 锁定状态处理
                var lockTalent = obj.Children.Find<BitmapButtonWidget>("LockTalent");
                lockTalent.IsVisible = !accessTalent.Have;
                talentLevelButton.IsVisible = accessTalent.Have;

                if (lockTalent.IsClicked)
                {
                    m_subsystemAudio.PlayRandomSound("Audio/UI/Talent/ItIsUnlocked", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
                }

                // 生成描述文本
                if (TalentParamMap.TryGetValue(accessTalent.InterpretationID, out var param))
                {
                    if (accessTalent.InterpretationID == 8)
                    {
                        Text = string.Format(LanguageControl.Get("ComponentTalent", 8),
                            param[0] + (accessTalent.Level - 1) * param[1],
                            param[2] + (accessTalent.Level - 1) * param[3]);
                    }
                    else if (accessTalent.InterpretationID == 9)
                    {
                        Text = string.Format(LanguageControl.Get("ComponentTalent", 9),
                            param[0] + (accessTalent.Level - 1) * param[1],
                            param[2] + (accessTalent.Level - 1) * param[3]);
                    }
                    else if (accessTalent.InterpretationID == 30)
                    {
                        // 特殊处理：9 - (level-1)
                        Text = string.Format(LanguageControl.Get("ComponentTalent", 30),
                            param[0] - (accessTalent.Level - 1));
                    }
                    else
                    {
                        Text = string.Format(LanguageControl.Get("ComponentTalent", accessTalent.InterpretationID),
                            param[0] + (accessTalent.Level - 1) * param[1]);
                    }
                }

                obj.Children.Find<LabelWidget>("TalentDisplayName").Text = Text;
                return obj;
            };

            // 只显示符合条件的未分配天赋
            foreach (AccessTalent accessTalent in AccessTalentManager.Data)
            {
                if (talentType == accessTalent.TalentType && accessTalent.Field == 0)
                {
                    talentList.AddItem(accessTalent);
                }
            }

            talentList.ItemClicked += delegate (object item)
            {
                var selectedTalent = (AccessTalent)item;
                if (selectedTalent.Have)
                {
                    selectedTalent.Field = field;
                    DialogsManager.HideDialog(this);
                }
            };
        }

        public override void Update()
        {
            if (okButton.IsClicked)
            {
                DialogsManager.HideDialog(this);
            }
        }
    }
}
