//攻击类型
namespace Game
{
    public class PoisoningInjury : Injury
    {
        public PoisoningInjury(float amount, float Health, Vector3 HitPoint, Vector3 HitDirection, ComponentCreature Attacker, ComponentBody Target) : base(Health * amount, Attacker, false, "中毒致死")
        {
            HitValueParticleSystem particleSystem;
            if (amount == 0.1f)
            {
                particleSystem = new(
                    HitPoint + 0.75f * HitDirection,
                    1f * HitDirection + Target.Entity.FindComponent<ComponentBody>().Velocity,
                    new Color(100, 255, 100),
                    "-" + NumericalProcessingManager.NumericalProcessing((float)Math.Round(Health * Target.Entity.FindComponent<ComponentHealth>().AttackResilience * Target.Entity.FindComponent<ComponentFactors>().ResilienceFactor * amount))
                );
            }
            else
            {
                particleSystem = new(
                    HitPoint + 0.75f * HitDirection,
                    1f * HitDirection + Target.Entity.FindComponent<ComponentBody>().Velocity,
                    new Color(76, 255, 76),
                    "-" + NumericalProcessingManager.NumericalProcessing((float)Math.Round(Health * Target.Entity.FindComponent<ComponentHealth>().AttackResilience * Target.Entity.FindComponent<ComponentFactors>().ResilienceFactor * amount))
                );
            }
            Target.Entity.FindComponent<ComponentHealth>().Project.FindSubsystem<SubsystemParticles>().AddParticleSystem(particleSystem);
        }
    }
