//医药台界面
namespace Game
{
    public class MedicineStationWidget : CanvasWidget
    {
        public ComponentPlayer m_componentPlayer;
        public ComponentMedicineStation m_componentMedicineStation;
        public SubsystemAudio subsystemAudio;

        public BlockIconWidget icon;
        public LabelWidget durabilityLabel;
        public LabelWidget levelLabel;
        public BitmapButtonWidget upgradeButton;
        public BitmapButtonWidget maintenanceButton;
        public ListPanelWidget typesList;
        public ListPanelWidget blockList;
        public LabelWidget makingThingsLabel;
        public LabelWidget timeConsumingLabel;
        public LabelWidget descriptionLabel;
        public BevelledButtonWidget productionButton;

        public Dictionary<BlockIconWidget, LabelWidget> Ingredients = new Dictionary<BlockIconWidget, LabelWidget>();
        public CraftingHYZLRecipe m_craftingHYZLRecipe;
        public List<string> m_typesitems = [];
        public Random m_random = new();

        public MedicineStationWidget(ComponentPlayer componentPlayer, ComponentMedicineStation componentMedicineStation)
        {
            m_componentPlayer = componentPlayer;
            m_componentMedicineStation = componentMedicineStation;
            subsystemAudio = componentPlayer.Project.FindSubsystem<SubsystemAudio>();

            XElement node = ContentManager.Get<XElement>("Widgets/MedicineStationWidget");
            LoadContents(this, node);

            InitializeWidgets();
            InitializeIngredients();
            InitializeTypesList();

            typesList.SelectedIndex = 0;

            componentPlayer.PlayerStats.ValuesDictionaryForMods["MedicineStationLevel"] = (componentPlayer.PlayerStats.ValuesDictionaryForMods.ContainsKey("MedicineStationLevel") ? ((int)componentPlayer.PlayerStats.ValuesDictionaryForMods["MedicineStationLevel"] > m_componentMedicineStation.Level ? componentPlayer.PlayerStats.ValuesDictionaryForMods["MedicineStationLevel"] : m_componentMedicineStation.Level) : m_componentMedicineStation.Level);
        }

        public override void Update()
        {
            UpdateBasicInfo();
            UpdateButtons();
            HandleProduction();
            HandleMaintenance();
            HandleUpgrade();
            UpdateLists();
        }

        public void InitializeWidgets()
        {
            icon = Children.Find<BlockIconWidget>("Icon");
            durabilityLabel = Children.Find<LabelWidget>("DurabilityLabel");
            levelLabel = Children.Find<LabelWidget>("LevelLabel");
            upgradeButton = Children.Find<BitmapButtonWidget>("UpgradeButton");
            maintenanceButton = Children.Find<BitmapButtonWidget>("MaintenanceButton");
            typesList = Children.Find<ListPanelWidget>("TypesList");
            blockList = Children.Find<ListPanelWidget>("BlockList");
            makingThingsLabel = Children.Find<LabelWidget>("MakingThingsLabel");
            timeConsumingLabel = Children.Find<LabelWidget>("TimeConsumingLabel");
            descriptionLabel = Children.Find<LabelWidget>("DescriptionLabel");
            productionButton = Children.Find<BevelledButtonWidget>("ProductionButton");
        }

        public void InitializeIngredients()
        {
            for (int a = 1; a < 27; a++)
            {
                Ingredients.Add(
                    Children.Find<BlockIconWidget>("Materials" + a),
                    Children.Find<LabelWidget>("Materials" + a + "Label")
                );
            }
        }

        public void InitializeTypesList()
        {
            m_typesitems.Clear();
            typesList.ItemWidgetFactory = delegate (object item)
            {
                var recipe = (CraftingHYZLRecipe)item;
                XElement node2 = ContentManager.Get<XElement>("Widgets/TypesItem");
                var obj = (ContainerWidget)LoadWidget(this, node2, null);
                obj.Children.Find<LabelWidget>("Types").Text = recipe.Type;
                return obj;
            };

            foreach (CraftingHYZLRecipe recipe in CraftingHYZLRecipesManager.Recipes)
            {
                if (m_componentMedicineStation.Level >= recipe.RequiredMedicineStationLevel && recipe.RequiredMedicineStationLevel > 0 && recipe.Type != null)
                {
                    typesList.AddItem(recipe);
                    m_typesitems.Add(recipe.Type);
                }
            }

            typesList.ItemClicked += OnTypeSelected;
            blockList.ItemClicked += OnBlockSelected;
        }

        public void UpdateBasicInfo()
        {
            icon.Value = Terrain.MakeBlockValue(NewMedicineStation.Index, 0, m_componentMedicineStation.Level);
            durabilityLabel.Text = "耐久:" + m_componentMedicineStation.Durability;
            levelLabel.Text = "等级:" + m_componentMedicineStation.Level;
        }

        public void UpdateButtons()
        {
            upgradeButton.IsVisible = (m_componentMedicineStation.Durability != 0 && m_componentMedicineStation.Level < AccessNewMedicineStationManager.Data.Count - 1);
            maintenanceButton.IsVisible = m_componentMedicineStation.Durability == 0;
        }

        public void HandleProduction()
        {
            if (productionButton.IsClicked && m_craftingHYZLRecipe != null)
            {
                m_componentMedicineStation.TryCraftSelectedRecipe(m_craftingHYZLRecipe, m_componentPlayer);
                subsystemAudio.PlaySound("Audio/UI/Production/SpeedUpTheCreationOfItems", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
                m_craftingHYZLRecipe = null;
            }
        }

        public void HandleMaintenance()
        {
            if (maintenanceButton.IsClicked)
            {
                m_componentPlayer.ComponentGui.ModalPanelWidget = new MedicineStationMaintenanceWidget(m_componentPlayer, m_componentMedicineStation);
            }
        }

        public void HandleUpgrade()
        {
            if (upgradeButton.IsClicked)
            {
                m_componentPlayer.ComponentGui.ModalPanelWidget = new MedicineStationUpgradeWidget(m_componentPlayer, m_componentMedicineStation);
            }
        }

        public void UpdateLists()
        {
            if (!typesList.SelectedIndex.HasValue)
            {
                blockList.ClearItems();
                typesList.SelectedIndex = 0;
                productionButton.IsVisible = false;
            }
            else if (!blockList.SelectedIndex.HasValue)
            {
                ClearRecipeInfo();
                blockList.SelectedIndex = 0;
                productionButton.IsVisible = false;
            }
        }

        public void OnTypeSelected(object item)
        {
            if (!typesList.SelectedIndex.HasValue) return;

            string selectedType = m_typesitems[typesList.SelectedIndex.Value];
            blockList.ClearItems();

            blockList.ItemWidgetFactory = delegate (object blockItem)
            {
                var recipe = (CraftingHYZLRecipe)blockItem;
                XElement node2 = ContentManager.Get<XElement>("Widgets/SyntheticArticlesItem");
                var obj = (ContainerWidget)LoadWidget(this, node2, null);
                obj.Children.Find<BlockIconWidget>("Icon").Value = CraftingRecipesManager.DecodeResult(recipe.ResultValue);
                return obj;
            };

            foreach (CraftingHYZLRecipe recipe in CraftingHYZLRecipesManager.Recipes)
            {
                if (m_componentMedicineStation.Level >= recipe.RequiredMedicineStationLevel &&
                    recipe.RequiredMedicineStationLevel > 0 &&
                    selectedType == recipe.ResultType)
                {
                    blockList.AddItem(recipe);
                }
            }
        }

        public void OnBlockSelected(object item)
        {
            var recipe = (CraftingHYZLRecipe)item;
            UpdateIngredients(recipe);
            UpdateRecipeInfo(recipe);
            m_craftingHYZLRecipe = recipe;
            productionButton.IsVisible = true;
        }

        public void UpdateIngredients(CraftingHYZLRecipe recipe)
        {
            for (int a = 0; a < 26; a++)
            {
                try
                {
                    var ingredient = recipe.Ingredients.ElementAt(a);
                    string[] safeParts = ingredient.Key.Split(':');
                    string beforeChar = safeParts[0];
                    string afterChar = safeParts.Length > 1 ? safeParts[1] : string.Empty;

                    Ingredients.ElementAt(a).Key.Value = Terrain.MakeBlockValue(
                        BlocksManager.FindBlocksByCraftingId(beforeChar)[0].BlockIndex,
                        0,
                        int.Parse(afterChar)
                    );
                    Ingredients.ElementAt(a).Value.Text = "X" + ingredient.Value;
                }
                catch
                {
                    Ingredients.ElementAt(a).Key.Value = 0;
                    Ingredients.ElementAt(a).Value.Text = "";
                }
            }
        }

        public void UpdateRecipeInfo(CraftingHYZLRecipe recipe)
        {
            int resultValue = CraftingRecipesManager.DecodeResult(recipe.ResultValue);
            makingThingsLabel.Text = BlocksManager.Blocks[Terrain.ExtractContents(resultValue)]
                .GetDisplayName(m_componentPlayer.m_subsystemTerrain, resultValue) + "X" + recipe.ResultCount;
            timeConsumingLabel.Text = "耗时:" + recipe.TimeConsuming + "分钟";
            descriptionLabel.Text = recipe.Description;
        }

        public void ClearRecipeInfo()
        {
            makingThingsLabel.Text = "";
            timeConsumingLabel.Text = "";
            descriptionLabel.Text = "";
        }
    }
}
//医药台升级配方获取
namespace Game
{
    public class CraftingMedicineStationRecipe
    {
        public int MaxSize = 3;
        public string Description;
        public string Message;
        public int TimeConsuming;
        public int RequiredMedicineStationLevel;
        public int DisplayOrder = 0;

        /// <summary>
        /// 配方材料字典：key=材料ID，value=所需数量
        /// </summary>
        public Dictionary<string, int> Ingredients = new Dictionary<string, int>();
    }

    public static class CraftingMedicineStationRecipeManager
    {
        public static int Index = 0;
        public static List<CraftingMedicineStationRecipe> m_recipes = new List<CraftingMedicineStationRecipe>();
        public static List<CraftingMedicineStationRecipe> Recipes => m_recipes;
        public static bool EnableLevelRestrictions = true;

        public static void Initialize()
        {
            if (Index == 0)
            {
                // 从XML文件加载配方数据
                XElement recipesRoot = ContentManager.Get<XElement>("CraftingMedicineStationRecipes");

                foreach (XElement recipeElement in recipesRoot.Descendants("Recipe"))
                {
                    try
                    {
                        CraftingMedicineStationRecipe recipe = DecodeRecipeElement(recipeElement);
                        if (recipe != null)
                        {
                            m_recipes.Add(recipe);
                            Index++;
                        }
                    }
                    catch (Exception ex)
                    {
                        Log.Error($"Failed to load recipe: {ex.Message}");
                    }
                }

                // 排序配方
                m_recipes.Sort((r1, r2) =>
                {
                    if (r1.DisplayOrder == r2.DisplayOrder)
                    {
                        return Comparer<int>.Default.Compare(r1.Ingredients.Count, r2.Ingredients.Count);
                    }
                    return Comparer<int>.Default.Compare(r1.DisplayOrder, r2.DisplayOrder);
                });

                Log.Information($"Loaded {Index} crafting medicineStation recipes");
            }
        }

        public static CraftingMedicineStationRecipe DecodeRecipeElement(XElement recipeElement)
        {
            CraftingMedicineStationRecipe recipe = new CraftingMedicineStationRecipe();

            // 解析基础属性
            recipe.Description = XmlUtils.GetAttributeValue<string>(recipeElement, "Description");
            recipe.Message = XmlUtils.GetAttributeValue<string>(recipeElement, "Message");
            recipe.DisplayOrder = XmlUtils.GetAttributeValue(recipeElement, "DisplayOrder", 0);
            recipe.RequiredMedicineStationLevel = XmlUtils.GetAttributeValue(recipeElement, "RequiredMedicineStationLevel", 0);
            recipe.TimeConsuming = XmlUtils.GetAttributeValue(recipeElement, "TimeConsuming", 0);

            // 解析材料 (a-z 和对应的数量属性)
            for (char c = 'a'; c <= 'z'; c++)
            {
                string ingredientKey = c.ToString();
                string countKey = c + "count";

                string ingredientValue = XmlUtils.GetAttributeValue<string>(recipeElement, ingredientKey, null);
                int ingredientCount = XmlUtils.GetAttributeValue(recipeElement, countKey, 1);

                if (!string.IsNullOrEmpty(ingredientValue))
                {
                    string[] array = ingredientValue.Split([':'], StringSplitOptions.None);
                    string craftingId = array[0];
                    int? data = array.Length >= 2 ? new int?(int.Parse(array[1], CultureInfo.InvariantCulture)) : null;

                    // 验证材料是否存在
                    if (BlocksManager.FindBlocksByCraftingId(craftingId).Length == 0)
                    {
                        throw new InvalidOperationException($"Block with craftingId \"{ingredientValue}\" not found.");
                    }

                    if (data.HasValue && (data.Value < 0 || data.Value > 262143))
                    {
                        throw new InvalidOperationException($"Data in recipe ingredient \"{ingredientValue}\" must be between 0 and 0x3FFFF.");
                    }

                    // 生成完整的材料ID（包含数据值）
                    string fullIngredientId = craftingId;
                    if (data.HasValue)
                    {
                        fullIngredientId += ":" + data.Value;
                    }

                    // 添加到材料字典
                    if (recipe.Ingredients.ContainsKey(fullIngredientId))
                    {
                        recipe.Ingredients[fullIngredientId] += ingredientCount;
                    }
                    else
                    {
                        recipe.Ingredients[fullIngredientId] = ingredientCount;
                    }
                }
            }

            return recipe;
        }

        public static CraftingMedicineStationRecipe FindMatchingRecipe(Dictionary<string, int> inputIngredients, int medicineStationLevel)
        {
            if (inputIngredients == null || inputIngredients.Count == 0)
            {
                return null;
            }

            // 检查预定义配方
            foreach (CraftingMedicineStationRecipe recipe in Recipes)
            {
                // 检查医药台等级限制
                if (EnableLevelRestrictions && recipe.RequiredMedicineStationLevel != medicineStationLevel)
                {
                    continue;
                }

                if (MatchRecipe(recipe.Ingredients, inputIngredients))
                {
                    return recipe;
                }
            }

            return null;
        }

        public static bool MatchRecipe(Dictionary<string, int> requiredIngredients, Dictionary<string, int> actualIngredients)
        {
            // 如果材料数量不匹配，直接返回false
            if (requiredIngredients.Count != actualIngredients.Count)
            {
                return false;
            }

            // 检查每个材料是否匹配
            foreach (var kvp in requiredIngredients)
            {
                string ingredientId = kvp.Key;
                int requiredCount = kvp.Value;

                if (!actualIngredients.TryGetValue(ingredientId, out int actualCount) || actualCount != requiredCount)
                {
                    return false;
                }
            }

            return true;
        }
    }
}
//医药台维修界面
namespace Game
{
    public class MedicineStationMaintenanceWidget : CanvasWidget
    {
        public ComponentPlayer m_componentPlayer;
        public ComponentMedicineStation m_componentMedicineStation;
        public ComponentUpgradeAndMaintenanceMedicineStation m_componentUpgradeAndMaintenanceMedicineStation;

        public BlockIconWidget icon;
        public LabelWidget levelLabel;
        public LabelWidget descriptionLabel;
        public LabelWidget timeConsumingLabel;
        public BevelledButtonWidget cancelItButton;
        public BevelledButtonWidget iAmSureButton;

        public CraftingMedicineStationRecipe craftingMedicineStationRecipe;

        public Dictionary<BlockIconWidget, LabelWidget> Ingredients = new Dictionary<BlockIconWidget, LabelWidget>();

        public MedicineStationMaintenanceWidget(ComponentPlayer componentPlayer, ComponentMedicineStation componentMedicineStation)
        {
            m_componentPlayer = componentPlayer;
            m_componentMedicineStation = componentMedicineStation;
            m_componentUpgradeAndMaintenanceMedicineStation = m_componentMedicineStation.Entity.FindComponent<ComponentUpgradeAndMaintenanceMedicineStation>();
            XElement node = ContentManager.Get<XElement>("Widgets/MedicineStationMaintenanceWidget");
            LoadContents(this, node);
            icon = Children.Find<BlockIconWidget>("Icon");
            levelLabel = Children.Find<LabelWidget>("LevelLabel");
            descriptionLabel = Children.Find<LabelWidget>("DescriptionLabel");
            for (int a = 1; a < 27; a++)
            {
                Ingredients.Add(Children.Find<BlockIconWidget>("Materials" + a), Children.Find<LabelWidget>("Materials" + a + "Label"));
            }
            timeConsumingLabel = Children.Find<LabelWidget>("TimeConsumingLabel");
            cancelItButton = Children.Find<BevelledButtonWidget>("CancelItButton");
            iAmSureButton = Children.Find<BevelledButtonWidget>("IAmSureButton");
        }

        public override void Update()
        {
            icon.Value = Terrain.MakeBlockValue(NewMedicineStation.Index, 0, m_componentMedicineStation.Level);
            levelLabel.Text = "等级:" + (m_componentMedicineStation.Level);

            if (cancelItButton.IsClicked)
            {
                m_componentPlayer.ComponentGui.ModalPanelWidget = new MedicineStationWidget(m_componentPlayer, m_componentMedicineStation);
            }
            if (iAmSureButton.IsClicked && craftingMedicineStationRecipe != null)
            {
                m_componentUpgradeAndMaintenanceMedicineStation.TryMaintainMedicineStation(craftingMedicineStationRecipe, m_componentPlayer);
                craftingMedicineStationRecipe = null;
            }

            if (craftingMedicineStationRecipe == null)
            {
                foreach (CraftingMedicineStationRecipe recipe in CraftingMedicineStationRecipeManager.Recipes)
                {
                    if (m_componentMedicineStation.Level - 1 == recipe.RequiredMedicineStationLevel)
                    {
                        craftingMedicineStationRecipe = recipe;
                        descriptionLabel.Text = recipe.Description;
                        timeConsumingLabel.Text = "耗时:" + recipe.TimeConsuming + "分钟";
                        for (int a = 0; a < 26; a++)
                        {
                            try
                            {
                                string[] safeParts = recipe.Ingredients.ElementAt(a).Key.Split(':');
                                string beforeChar = safeParts[0];
                                string afterChar = safeParts.Length > 1 ? safeParts[1] : string.Empty;
                                Ingredients.ElementAt(a).Key.Value = Terrain.MakeBlockValue(BlocksManager.FindBlocksByCraftingId(beforeChar)[0].BlockIndex, 0, int.Parse(afterChar));
                                Ingredients.ElementAt(a).Value.Text = "X" + recipe.Ingredients.ElementAt(a).Value;
                            }
                            catch
                            {
                                Ingredients.ElementAt(a).Key.Value = 0;
                                Ingredients.ElementAt(a).Value.Text = "";
                            }
                        }
                    }
                }
            }
        }
    }
}
