namespace Game
{
    public class ComponentBed : ComponentInventoryBase, IUpdateable
    {
        public ComponentBlockEntity componentBlockEntity;
        public ComponentPlayer m_componentPlayer;
        public SubsystemGameInfo subsystemGameInfo;
        public SubsystemTime subsystemTime;
        public SubsystemAudio subsystemAudio;

        public int Level { get; private set; }
        public int Durability { get; private set; }

        public double m_craftingStartTime;
        public int m_craftingDuration;
        public bool m_isSleeping;

        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public virtual void Update(float dt)
        {
            Level = NewBed.GetType(componentBlockEntity.BlockValue);
            Durability = BlocksManager.Blocks[Terrain.ExtractContents(componentBlockEntity.BlockValue)].GetDamage(componentBlockEntity.BlockValue);

            if (!m_isSleeping) return;

            subsystemTime.m_gameTimeFactor = 120;
            double currentTime = subsystemGameInfo.TotalElapsedGameTime;
            double elapsedTime = currentTime - m_craftingStartTime;
            m_componentPlayer.ComponentScreenOverlays.BlackoutFactor = 1f;
            ComponentHealth componentHealth = m_componentPlayer.Entity.FindComponent<ComponentHealth>();
            ComponentHYZLVitalStats componentHYZLVitalStats = m_componentPlayer.Entity.FindComponent<ComponentHYZLVitalStats>();
            ComponentPhysicalAttributes componentPhysicalAttributes = m_componentPlayer.Entity.FindComponent<ComponentPhysicalAttributes>();
            componentPhysicalAttributes.Sleep = true;

            if (elapsedTime < m_craftingDuration) return;

            subsystemTime.m_gameTimeFactor = 1;

            float healthIncrement = (float)Math.Floor(Level * m_craftingDuration / 4f * (componentPhysicalAttributes.Insomnia * componentPhysicalAttributes.InsomniaResistance / 100f)) / componentHealth.AttackResilience;
            componentHealth.Health = Math.Min(1f, componentHealth.Health + healthIncrement);

            float sleepIncrement = (float)Math.Floor(Level * m_craftingDuration / 2 * (componentPhysicalAttributes.Insomnia * componentPhysicalAttributes.InsomniaResistance / 100f)) / componentPhysicalAttributes.SleepResistance;
            componentHYZLVitalStats.Sleep = Math.Min(1f, m_componentPlayer.ComponentVitalStats.Sleep + sleepIncrement);

            componentBlockEntity.m_subsystemTerrain.ChangeCell(
                componentBlockEntity.Coordinates.X,
                componentBlockEntity.Coordinates.Y,
                componentBlockEntity.Coordinates.Z,
                BlocksManager.Blocks[Terrain.ExtractContents(componentBlockEntity.BlockValue)].SetDamage(
                    componentBlockEntity.BlockValue,
                    BlocksManager.Blocks[Terrain.ExtractContents(componentBlockEntity.BlockValue)].GetDamage(componentBlockEntity.BlockValue) - (int)Math.Min(BlocksManager.Blocks[Terrain.ExtractContents(componentBlockEntity.BlockValue)].GetDamage(componentBlockEntity.BlockValue), Math.Floor(m_craftingDuration / 50f / (Level + 1)))
                )
            );
            componentPhysicalAttributes.Sleep = false;
            subsystemAudio.PlaySound("Audio/UI/Sleep/GetUp", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);

            m_componentPlayer.ComponentScreenOverlays.BlackoutFactor = 0f;
            m_isSleeping = false;
        }

        public void Sleep(ComponentPlayer componentPlayer, int SleepTime)
        {
            m_componentPlayer = componentPlayer;
            m_craftingStartTime = componentPlayer.m_subsystemGameInfo.TotalElapsedGameTime;
            m_craftingDuration = SleepTime;
            m_isSleeping = true;
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            componentBlockEntity = Entity.FindComponent<ComponentBlockEntity>(throwOnError: true);
            subsystemGameInfo = Project.FindSubsystem<SubsystemGameInfo>();
            subsystemTime = Project.FindSubsystem<SubsystemTime>();
            subsystemAudio = Project.FindSubsystem<SubsystemAudio>();
        }
    }
}
