namespace Game
{
    public class BedWidget : CanvasWidget
    {
        public ComponentPlayer m_componentPlayer;
        public ComponentBed m_componentBed;
        public SubsystemAudio subsystemAudio;

        public BlockIconWidget icon;
        public LabelWidget durabilityLabel;
        public LabelWidget levelLabel;
        public BitmapButtonWidget upgradeButton;
        public BitmapButtonWidget maintenanceButton;
        public BitmapButtonWidget sleep1hButton;
        public BitmapButtonWidget sleep4hButton;
        public BitmapButtonWidget sleep8hButton;
        public BitmapButtonWidget sleepDaybreakButton;
        public LabelWidget makingThingsLabel;
        public LabelWidget timeConsumingLabel;
        public LabelWidget descriptionLabel;
        public BevelledButtonWidget productionButton;

        public Random m_random = new();
        public int num;
        public string Text = "";

        public BedWidget(ComponentPlayer componentPlayer, ComponentBed componentBed)
        {
            m_componentPlayer = componentPlayer;
            m_componentBed = componentBed;
            subsystemAudio = componentPlayer.Project.FindSubsystem<SubsystemAudio>();

            XElement node = ContentManager.Get<XElement>("Widgets/BedWidget");
            LoadContents(this, node);

            icon = Children.Find<BlockIconWidget>("Icon");
            durabilityLabel = Children.Find<LabelWidget>("DurabilityLabel");
            levelLabel = Children.Find<LabelWidget>("LevelLabel");
            upgradeButton = Children.Find<BitmapButtonWidget>("UpgradeButton");
            maintenanceButton = Children.Find<BitmapButtonWidget>("MaintenanceButton");
            sleep1hButton = Children.Find<BitmapButtonWidget>("Sleep1hButton");
            sleep4hButton = Children.Find<BitmapButtonWidget>("Sleep4hButton");
            sleep8hButton = Children.Find<BitmapButtonWidget>("Sleep8hButton");
            sleepDaybreakButton = Children.Find<BitmapButtonWidget>("SleepDaybreakButton");
            makingThingsLabel = Children.Find<LabelWidget>("MakingThingsLabel");
            timeConsumingLabel = Children.Find<LabelWidget>("TimeConsumingLabel");
            descriptionLabel = Children.Find<LabelWidget>("DescriptionLabel");
            productionButton = Children.Find<BevelledButtonWidget>("ProductionButton");

            num = 0;
            componentPlayer.PlayerStats.ValuesDictionaryForMods["BedLevel"] = (componentPlayer.PlayerStats.ValuesDictionaryForMods.ContainsKey("BedLevel") ? ((int)componentPlayer.PlayerStats.ValuesDictionaryForMods["BedLevel"] > m_componentBed.Level ? componentPlayer.PlayerStats.ValuesDictionaryForMods["BedLevel"] : m_componentBed.Level) : m_componentBed.Level);
        }

        public override void Update()
        {
            // 更新基本信息
            icon.Value = Terrain.MakeBlockValue(NewBed.Index, 0, m_componentBed.Level);
            durabilityLabel.Text = "耐久:" + m_componentBed.Durability;
            levelLabel.Text = "等级:" + m_componentBed.Level;

            if (num == 1) Text = "50";
            else if (num == 2) Text = "200";
            else if (num == 3) Text = "400";
            else if (num == 4)
            {
                float num2 = (float)Math.Floor(m_componentPlayer.m_subsystemGameInfo.TotalElapsedGameTime - (float)Math.Floor(m_componentPlayer.m_subsystemGameInfo.TotalElapsedGameTime / 1200) * 1200);
                Text = "" + (1200 - num2);
            }

            timeConsumingLabel.Text = "耗时:" + Text + "分钟";
            descriptionLabel.Text = LanguageControl.Get("BedWidget", num);

            // 更新按钮可见性
            upgradeButton.IsVisible = (m_componentBed.Durability != 0 && m_componentBed.Level < AccessNewBedManager.Data.Count - 1);
            maintenanceButton.IsVisible = m_componentBed.Durability == 0;
            sleep1hButton.IsVisible = m_componentBed.Level != 0;
            sleep4hButton.IsVisible = m_componentBed.Level != 0;
            sleep8hButton.IsVisible = m_componentBed.Level != 0;
            sleepDaybreakButton.IsVisible = m_componentBed.Level != 0;
            makingThingsLabel.IsVisible = num != 0;
            timeConsumingLabel.IsVisible = num != 0;
            productionButton.IsVisible = num != 0;

            // 处理生产按钮点击
            if (productionButton.IsClicked)
            {
                subsystemAudio.PlaySound("Audio/UI/Sleep/Sleep", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
                m_componentBed.Sleep(m_componentPlayer, int.Parse(Text));
                num = 0;
            }

            // 处理睡眠按钮点击
            if (sleep1hButton.IsClicked) num = 1;
            if (sleep4hButton.IsClicked) num = 2;
            if (sleep8hButton.IsClicked) num = 3;
            if (sleepDaybreakButton.IsClicked) num = 4;

            // 处理维护按钮点击
            if (maintenanceButton.IsClicked)
            {
                m_componentPlayer.ComponentGui.ModalPanelWidget = new BedMaintenanceWidget(m_componentPlayer, m_componentBed);
            }

            // 处理升级按钮点击
            if (upgradeButton.IsClicked)
            {
                m_componentPlayer.ComponentGui.ModalPanelWidget = new BedUpgradeWidget(m_componentPlayer, m_componentBed);
            }
        }
    }
}
//床升级配方获取
namespace Game
{
    public class CraftingBedRecipe
    {
        public int MaxSize = 3;
        public string Description;
        public string Message;
        public int TimeConsuming;
        public int RequiredBedLevel;
        public int DisplayOrder = 0;

        /// <summary>
        /// 配方材料字典：key=材料ID，value=所需数量
        /// </summary>
        public Dictionary<string, int> Ingredients = new Dictionary<string, int>();
    }

    public static class CraftingBedRecipeManager
    {
        public static int Index = 0;
        public static List<CraftingBedRecipe> m_recipes = new List<CraftingBedRecipe>();
        public static List<CraftingBedRecipe> Recipes => m_recipes;
        public static bool EnableLevelRestrictions = true;

        public static void Initialize()
        {
            if (Index == 0)
            {
                // 从XML文件加载配方数据
                XElement recipesRoot = ContentManager.Get<XElement>("CraftingBedRecipes");

                foreach (XElement recipeElement in recipesRoot.Descendants("Recipe"))
                {
                    try
                    {
                        CraftingBedRecipe recipe = DecodeRecipeElement(recipeElement);
                        if (recipe != null)
                        {
                            m_recipes.Add(recipe);
                            Index++;
                        }
                    }
                    catch (Exception ex)
                    {
                        Log.Error($"Failed to load recipe: {ex.Message}");
                    }
                }

                // 排序配方
                m_recipes.Sort((r1, r2) =>
                {
                    if (r1.DisplayOrder == r2.DisplayOrder)
                    {
                        return Comparer<int>.Default.Compare(r1.Ingredients.Count, r2.Ingredients.Count);
                    }
                    return Comparer<int>.Default.Compare(r1.DisplayOrder, r2.DisplayOrder);
                });

                Log.Information($"Loaded {Index} crafting bed recipes");
            }
        }

        public static CraftingBedRecipe DecodeRecipeElement(XElement recipeElement)
        {
            CraftingBedRecipe recipe = new CraftingBedRecipe();

            // 解析基础属性
            recipe.Description = XmlUtils.GetAttributeValue<string>(recipeElement, "Description");
            recipe.Message = XmlUtils.GetAttributeValue<string>(recipeElement, "Message");
            recipe.DisplayOrder = XmlUtils.GetAttributeValue(recipeElement, "DisplayOrder", 0);
            recipe.RequiredBedLevel = XmlUtils.GetAttributeValue(recipeElement, "RequiredBedLevel", 0);
            recipe.TimeConsuming = XmlUtils.GetAttributeValue(recipeElement, "TimeConsuming", 0);

            // 解析材料 (a-z 和对应的数量属性)
            for (char c = 'a'; c <= 'z'; c++)
            {
                string ingredientKey = c.ToString();
                string countKey = c + "count";

                string ingredientValue = XmlUtils.GetAttributeValue<string>(recipeElement, ingredientKey, null);
                int ingredientCount = XmlUtils.GetAttributeValue(recipeElement, countKey, 1);

                if (!string.IsNullOrEmpty(ingredientValue))
                {
                    string[] array = ingredientValue.Split([':'], StringSplitOptions.None);
                    string craftingId = array[0];
                    int? data = array.Length >= 2 ? new int?(int.Parse(array[1], CultureInfo.InvariantCulture)) : null;

                    // 验证材料是否存在
                    if (BlocksManager.FindBlocksByCraftingId(craftingId).Length == 0)
                    {
                        throw new InvalidOperationException($"Block with craftingId \"{ingredientValue}\" not found.");
                    }

                    if (data.HasValue && (data.Value < 0 || data.Value > 262143))
                    {
                        throw new InvalidOperationException($"Data in recipe ingredient \"{ingredientValue}\" must be between 0 and 0x3FFFF.");
                    }

                    // 生成完整的材料ID（包含数据值）
                    string fullIngredientId = craftingId;
                    if (data.HasValue)
                    {
                        fullIngredientId += ":" + data.Value;
                    }

                    // 添加到材料字典
                    if (recipe.Ingredients.ContainsKey(fullIngredientId))
                    {
                        recipe.Ingredients[fullIngredientId] += ingredientCount;
                    }
                    else
                    {
                        recipe.Ingredients[fullIngredientId] = ingredientCount;
                    }
                }
            }

            return recipe;
        }

        public static CraftingBedRecipe FindMatchingRecipe(Dictionary<string, int> inputIngredients, int bedLevel)
        {
            if (inputIngredients == null || inputIngredients.Count == 0)
            {
                return null;
            }

            // 检查预定义配方
            foreach (CraftingBedRecipe recipe in Recipes)
            {
                // 检查床等级限制
                if (EnableLevelRestrictions && recipe.RequiredBedLevel != bedLevel)
                {
                    continue;
                }

                if (MatchRecipe(recipe.Ingredients, inputIngredients))
                {
                    return recipe;
                }
            }

            return null;
        }

        public static bool MatchRecipe(Dictionary<string, int> requiredIngredients, Dictionary<string, int> actualIngredients)
        {
            // 如果材料数量不匹配，直接返回false
            if (requiredIngredients.Count != actualIngredients.Count)
            {
                return false;
            }

            // 检查每个材料是否匹配
            foreach (var kvp in requiredIngredients)
            {
                string ingredientId = kvp.Key;
                int requiredCount = kvp.Value;

                if (!actualIngredients.TryGetValue(ingredientId, out int actualCount) || actualCount != requiredCount)
                {
                    return false;
                }
            }

            return true;
        }
    }
}
//床维修界面
namespace Game
{
    public class BedMaintenanceWidget : CanvasWidget
    {
        public ComponentPlayer m_componentPlayer;
        public ComponentBed m_componentBed;
        public ComponentUpgradeAndMaintenanceBed m_componentUpgradeAndMaintenanceBed;

        public BlockIconWidget icon;
        public LabelWidget levelLabel;
        public LabelWidget descriptionLabel;
        public LabelWidget timeConsumingLabel;
        public BevelledButtonWidget cancelItButton;
        public BevelledButtonWidget iAmSureButton;

        public CraftingBedRecipe craftingBedRecipe;

        public Dictionary<BlockIconWidget, LabelWidget> Ingredients = new Dictionary<BlockIconWidget, LabelWidget>();

        public BedMaintenanceWidget(ComponentPlayer componentPlayer, ComponentBed componentBed)
        {
            m_componentPlayer = componentPlayer;
            m_componentBed = componentBed;
            m_componentUpgradeAndMaintenanceBed = m_componentBed.Entity.FindComponent<ComponentUpgradeAndMaintenanceBed>();
            XElement node = ContentManager.Get<XElement>("Widgets/BedMaintenanceWidget");
            LoadContents(this, node);
            icon = Children.Find<BlockIconWidget>("Icon");
            levelLabel = Children.Find<LabelWidget>("LevelLabel");
            descriptionLabel = Children.Find<LabelWidget>("DescriptionLabel");
            for (int a = 1; a < 27; a++)
            {
                Ingredients.Add(Children.Find<BlockIconWidget>("Materials" + a), Children.Find<LabelWidget>("Materials" + a + "Label"));
            }
            timeConsumingLabel = Children.Find<LabelWidget>("TimeConsumingLabel");
            cancelItButton = Children.Find<BevelledButtonWidget>("CancelItButton");
            iAmSureButton = Children.Find<BevelledButtonWidget>("IAmSureButton");
        }

        public override void Update()
        {
            icon.Value = Terrain.MakeBlockValue(NewBed.Index, 0, m_componentBed.Level);
            levelLabel.Text = "等级:" + (m_componentBed.Level);

            if (cancelItButton.IsClicked)
            {
                m_componentPlayer.ComponentGui.ModalPanelWidget = new BedWidget(m_componentPlayer, m_componentBed);
            }
            if (iAmSureButton.IsClicked && craftingBedRecipe != null)
            {
                m_componentUpgradeAndMaintenanceBed.TryMaintainBed(craftingBedRecipe, m_componentPlayer);
                craftingBedRecipe = null;
            }

            if (craftingBedRecipe == null)
            {
                foreach (CraftingBedRecipe recipe in CraftingBedRecipeManager.Recipes)
                {
                    if (m_componentBed.Level - 1 == recipe.RequiredBedLevel)
                    {
                        craftingBedRecipe = recipe;
                        descriptionLabel.Text = recipe.Description;
                        timeConsumingLabel.Text = "耗时:" + recipe.TimeConsuming + "分钟";
                        for (int a = 0; a < 26; a++)
                        {
                            try
                            {
                                string[] safeParts = recipe.Ingredients.ElementAt(a).Key.Split(':');
                                string beforeChar = safeParts[0];
                                string afterChar = safeParts.Length > 1 ? safeParts[1] : string.Empty;
                                Ingredients.ElementAt(a).Key.Value = Terrain.MakeBlockValue(BlocksManager.FindBlocksByCraftingId(beforeChar)[0].BlockIndex, 0, int.Parse(afterChar));
                                Ingredients.ElementAt(a).Value.Text = "X" + recipe.Ingredients.ElementAt(a).Value;
                            }
                            catch
                            {
                                Ingredients.ElementAt(a).Key.Value = 0;
                                Ingredients.ElementAt(a).Value.Text = "";
                            }
                        }
                    }
                }
            }
        }
    }
}
//床升级界面
namespace Game
{
    public class BedUpgradeWidget : CanvasWidget
    {
        public ComponentPlayer m_componentPlayer;
        public ComponentBed m_componentBed;
        public ComponentUpgradeAndMaintenanceBed m_componentUpgradeAndMaintenanceBed;

        public BlockIconWidget icon;
        public LabelWidget levelLabel;
        public LabelWidget descriptionLabel;
        public LabelWidget timeConsumingLabel;
        public BevelledButtonWidget cancelItButton;
        public BevelledButtonWidget iAmSureButton;

        public CraftingBedRecipe craftingBedRecipe;

        public Dictionary<BlockIconWidget, LabelWidget> Ingredients = new Dictionary<BlockIconWidget, LabelWidget>();

        public BedUpgradeWidget(ComponentPlayer componentPlayer, ComponentBed componentBed)
        {
            m_componentPlayer = componentPlayer;
            m_componentBed = componentBed;
            m_componentUpgradeAndMaintenanceBed = m_componentBed.Entity.FindComponent<ComponentUpgradeAndMaintenanceBed>();
            XElement node = ContentManager.Get<XElement>("Widgets/BedUpgradeWidget");
            LoadContents(this, node);
            icon = Children.Find<BlockIconWidget>("Icon");
            levelLabel = Children.Find<LabelWidget>("LevelLabel");
            descriptionLabel = Children.Find<LabelWidget>("DescriptionLabel");
            for (int a = 1; a < 27; a++)
            {
                Ingredients.Add(Children.Find<BlockIconWidget>("Materials" + a), Children.Find<LabelWidget>("Materials" + a + "Label"));
            }
            timeConsumingLabel = Children.Find<LabelWidget>("TimeConsumingLabel");
            cancelItButton = Children.Find<BevelledButtonWidget>("CancelItButton");
            iAmSureButton = Children.Find<BevelledButtonWidget>("IAmSureButton");
        }

        public override void Update()
        {
            if (m_componentBed.Level + 1 >= AccessNewBedManager.Data.Count)
            {
                icon.Value = Terrain.MakeBlockValue(NewBed.Index, 0, m_componentBed.Level);
            }
            else
            {
                icon.Value = Terrain.MakeBlockValue(NewBed.Index, 0, m_componentBed.Level + 1);
            }
            levelLabel.Text = "等级:" + (m_componentBed.Level + 1);

            if (cancelItButton.IsClicked)
            {
                m_componentPlayer.ComponentGui.ModalPanelWidget = new BedWidget(m_componentPlayer, m_componentBed);
            }
            if (iAmSureButton.IsClicked && craftingBedRecipe != null)
            {
                m_componentUpgradeAndMaintenanceBed.TryUpgradeBed(craftingBedRecipe, m_componentPlayer);
                craftingBedRecipe = null;
            }

            if (craftingBedRecipe == null)
            {
                foreach (CraftingBedRecipe recipe in CraftingBedRecipeManager.Recipes)
                {
                    if (m_componentBed.Level == recipe.RequiredBedLevel)
                    {
                        craftingBedRecipe = recipe;
                        descriptionLabel.Text = recipe.Description;
                        timeConsumingLabel.Text = "耗时:" + recipe.TimeConsuming + "分钟";
                        for (int a = 0; a < 26; a++)
                        {
                            try
                            {
                                string[] safeParts = recipe.Ingredients.ElementAt(a).Key.Split(':');
                                string beforeChar = safeParts[0];
                                string afterChar = safeParts.Length > 1 ? safeParts[1] : string.Empty;
                                Ingredients.ElementAt(a).Key.Value = Terrain.MakeBlockValue(BlocksManager.FindBlocksByCraftingId(beforeChar)[0].BlockIndex, 0, int.Parse(afterChar));
                                Ingredients.ElementAt(a).Value.Text = "X" + recipe.Ingredients.ElementAt(a).Value;
                            }
                            catch
                            {
                                Ingredients.ElementAt(a).Key.Value = 0;
                                Ingredients.ElementAt(a).Value.Text = "";
                            }
                        }
                    }
                }
            }
        }
    }
}
//组件床升级或维修
namespace Game
{
    public class ComponentUpgradeAndMaintenanceBed : ComponentInventoryBase, IUpdateable
    {
        public ComponentBlockEntity componentBlockEntity;
        public ComponentBed componentBed;
        public SubsystemPickables subsystemPickables;
        public SubsystemTime subsystemTime;
        public SubsystemGameInfo subsystemGameInfo;
        public SubsystemTerrain subsystemTerrain;
        public SubsystemAudio subsystemAudio;

        // 配方匹配
        public CraftingBedRecipe m_matchedUpgradeRecipe;
        public CraftingBedRecipe m_matchedMaintenanceRecipe;
        public bool m_recipeUpdateNeeded;
        public bool m_recipeRefindNeeded;
        public int Level;
        public int Durability;

        // 升级时间相关字段
        public double m_upgradeStartTime;
        public double m_upgradeDuration;
        public bool m_isUpgrading;
        public CraftingBedRecipe m_currentUpgradeRecipe;
        public ComponentPlayer m_currentUpgradingPlayer;

        // 维修时间相关字段
        public double m_maintenanceStartTime;
        public double m_maintenanceDuration;
        public bool m_isMaintaining;
        public CraftingBedRecipe m_currentMaintenanceRecipe;
        public ComponentPlayer m_currentMaintainingPlayer;

        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public virtual void Update(float dt)
        {
            // 处理升级时间逻辑
            if (m_isUpgrading)
            {
                if (!CheckConditions(m_currentUpgradingPlayer))
                {
                    CancelOperationDueToConditions("升级");
                    return;
                }

                subsystemTime.m_gameTimeFactor = 120;
                double currentTime = subsystemGameInfo.TotalElapsedGameTime;
                double elapsedTime = (currentTime - m_upgradeStartTime);

                if (elapsedTime >= m_upgradeDuration)
                {
                    subsystemTime.m_gameTimeFactor = 1;
                    CompleteUpgrade();
                }
            }

            // 处理维修时间逻辑
            if (m_isMaintaining)
            {
                if (!CheckConditions(m_currentMaintainingPlayer))
                {
                    CancelOperationDueToConditions("维修");
                    return;
                }

                subsystemTime.m_gameTimeFactor = 120;
                double currentTime = subsystemGameInfo.TotalElapsedGameTime;
                double elapsedTime = (currentTime - m_maintenanceStartTime);

                if (elapsedTime >= m_maintenanceDuration)
                {
                    subsystemTime.m_gameTimeFactor = 1;
                    CompleteMaintenance();
                }
            }

            if (m_recipeUpdateNeeded)
            {
                UpdateRecipeResult(m_recipeRefindNeeded);
            }
            m_recipeUpdateNeeded = false;
            m_recipeRefindNeeded = false;

            UpdateBedStatus();
        }

        public void UpdateBedStatus()
        {
            if (componentBlockEntity != null && componentBed != null)
            {
                Level = componentBed.Level;
                Durability = componentBed.Durability;
            }
        }

        // 通用条件检查
        public bool CheckConditions(ComponentPlayer player)
        {
            if (IsPlayerDeadOrInvalid(player)) return false;

            ComponentVitalStats vitalStats = player.ComponentVitalStats;
            if (vitalStats != null && vitalStats.Sleep <= 0.2f)
            {
                player.ComponentGui.DisplaySmallMessage("太困了，无法继续操作！", Color.Red, true, true);
                return false;
            }

            return true;
        }

        // 通用取消操作
        public void CancelOperationDueToConditions(string operationType)
        {
            ComponentPlayer currentPlayer = operationType == "升级" ? m_currentUpgradingPlayer : m_currentMaintainingPlayer;
            if (currentPlayer != null)
            {
                currentPlayer.ComponentGui.DisplaySmallMessage($"{operationType}已取消", Color.Yellow, true, true);
            }

            subsystemTime.m_gameTimeFactor = 1;

            if (operationType == "升级")
            {
                m_isUpgrading = false;
                m_currentUpgradeRecipe = null;
                m_currentUpgradingPlayer = null;
            }
            else
            {
                m_isMaintaining = false;
                m_currentMaintenanceRecipe = null;
                m_currentMaintainingPlayer = null;
            }
        }

        public override void AddSlotItems(int slotIndex, int value, int count)
        {
            base.AddSlotItems(slotIndex, value, count);
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }

        public override int RemoveSlotItems(int slotIndex, int count)
        {
            int num = base.RemoveSlotItems(slotIndex, count);
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
            return num;
        }

        public virtual void UpdateRecipeResult(bool recipeRefindNeeded)
        {
            ComponentPlayer componentPlayer = FindInteractingPlayer();
            if (componentPlayer == null) return;

            if (IsPlayerDeadOrInvalid(componentPlayer) || !CheckConditions(componentPlayer)) return;

            Dictionary<string, int> playerIngredients = GetPlayerIngredients(componentPlayer);

            // 根据当前界面类型更新对应的配方
            if (componentPlayer.ComponentGui.ModalPanelWidget is BedUpgradeWidget)
            {
                UpdateUpgradeRecipe(recipeRefindNeeded, playerIngredients, componentPlayer);
            }
            else if (componentPlayer.ComponentGui.ModalPanelWidget is BedMaintenanceWidget)
            {
                UpdateMaintenanceRecipe(recipeRefindNeeded, playerIngredients, componentPlayer);
            }
        }

        public void UpdateUpgradeRecipe(bool recipeRefindNeeded, Dictionary<string, int> playerIngredients, ComponentPlayer player)
        {
            CraftingBedRecipe upgradeRecipe;
            if (recipeRefindNeeded || m_matchedUpgradeRecipe == null)
            {
                upgradeRecipe = CraftingBedRecipeManager.FindMatchingRecipe(playerIngredients, Level);
            }
            else
            {
                upgradeRecipe = m_matchedUpgradeRecipe;
            }

            if (upgradeRecipe != null)
            {
                m_matchedUpgradeRecipe = upgradeRecipe;
                if (CheckIngredientsAvailable(upgradeRecipe, player, out var lackDict))
                {
                    player.ComponentGui.DisplaySmallMessage($"可以升级到{upgradeRecipe.Description}！", Color.Green, true, true);
                }
            }
            else
            {
                m_matchedUpgradeRecipe = null;
            }
        }

        public void UpdateMaintenanceRecipe(bool recipeRefindNeeded, Dictionary<string, int> playerIngredients, ComponentPlayer player)
        {
            CraftingBedRecipe maintenanceRecipe;
            if (recipeRefindNeeded || m_matchedMaintenanceRecipe == null)
            {
                maintenanceRecipe = CraftingBedRecipeManager.FindMatchingRecipe(playerIngredients, Level);
            }
            else
            {
                maintenanceRecipe = m_matchedMaintenanceRecipe;
            }

            if (maintenanceRecipe != null)
            {
                m_matchedMaintenanceRecipe = maintenanceRecipe;
                if (CheckIngredientsAvailable(maintenanceRecipe, player, out var lackDict))
                {
                    player.ComponentGui.DisplaySmallMessage($"可以维修床！", Color.Green, true, true);
                }
            }
            else
            {
                m_matchedMaintenanceRecipe = null;
            }
        }

        public Dictionary<string, int> GetPlayerIngredients(ComponentPlayer player)
        {
            Dictionary<string, int> playerIngredients = new Dictionary<string, int>();
            ComponentInventory playerInventory = player.Entity.FindComponent<ComponentInventory>();

            for (int i = 0; i < playerInventory.SlotsCount; i++)
            {
                int slotValue = playerInventory.GetSlotValue(i);
                int slotCount = playerInventory.GetSlotCount(i);

                if (slotValue != 0 && slotCount > 0)
                {
                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string ingredientKey = $"{craftingId}:{data}";

                    if (playerIngredients.ContainsKey(ingredientKey))
                    {
                        playerIngredients[ingredientKey] += slotCount;
                    }
                    else
                    {
                        playerIngredients[ingredientKey] = slotCount;
                    }
                }
            }

            return playerIngredients;
        }

        public bool CheckIngredientsAvailable(CraftingBedRecipe recipe, ComponentPlayer player, out Dictionary<string, int> lackDict)
        {
            lackDict = new Dictionary<string, int>();
            if (IsPlayerDeadOrInvalid(player)) return false;

            Dictionary<string, int> playerIngredients = GetPlayerIngredients(player);

            foreach (var ingredient in recipe.Ingredients)
            {
                string ingredientId = ingredient.Key;
                int requiredCount = ingredient.Value;
                int actualCount = playerIngredients.ContainsKey(ingredientId) ? playerIngredients[ingredientId] : 0;

                if (actualCount < requiredCount)
                {
                    lackDict[ingredientId] = requiredCount - actualCount;
                }
            }

            return lackDict.Count == 0;
        }

        // 开始操作（升级或维修）
        public bool StartOperation(ComponentPlayer player, CraftingBedRecipe recipe, string operationType)
        {
            if (IsPlayerDeadOrInvalid(player) || !CheckConditions(player))
            {
                player.ComponentGui.DisplaySmallMessage($"无法开始{operationType}：条件不满足", Color.Red, true, true);
                return false;
            }

            bool isOperating = operationType == "升级" ? m_isUpgrading : m_isMaintaining;
            if (isOperating)
            {
                player.ComponentGui.DisplaySmallMessage($"正在{operationType}中，请等待完成！", Color.Yellow, true, true);
                return false;
            }

            if (!CheckIngredientsAvailable(recipe, player, out var lackDict))
            {
                player.ComponentGui.DisplaySmallMessage("材料不足！", Color.Red, true, true);
                return false;
            }

            double operationTimeSeconds = recipe.TimeConsuming;

            if (operationType == "升级")
            {
                m_upgradeDuration = operationTimeSeconds;
                m_upgradeStartTime = subsystemGameInfo.TotalElapsedGameTime;
                m_isUpgrading = true;
                m_currentUpgradeRecipe = recipe;
                m_currentUpgradingPlayer = player;
            }
            else
            {
                m_maintenanceDuration = operationTimeSeconds;
                m_maintenanceStartTime = subsystemGameInfo.TotalElapsedGameTime;
                m_isMaintaining = true;
                m_currentMaintenanceRecipe = recipe;
                m_currentMaintainingPlayer = player;
            }

            player.ComponentGui.DisplaySmallMessage($"开始{operationType}床：{recipe.Description}，预计需要 {operationTimeSeconds} 分钟", Color.Yellow, true, true);
            return true;
        }

        // 完成升级
        public void CompleteUpgrade()
        {
            if (IsPlayerDeadOrInvalid(m_currentUpgradingPlayer) || !CheckConditions(m_currentUpgradingPlayer))
            {
                CancelOperationDueToConditions("升级");
                return;
            }

            if (!m_isUpgrading || m_currentUpgradeRecipe == null || m_currentUpgradingPlayer == null)
            {
                m_isUpgrading = false;
                return;
            }

            if (ConsumeIngredientsAndOperate(m_currentUpgradingPlayer, m_currentUpgradeRecipe, "升级"))
            {
                m_currentUpgradingPlayer.ComponentGui.DisplaySmallMessage($"床升级成功：{m_currentUpgradeRecipe.Description}！", Color.Green, true, true);

                if (!string.IsNullOrEmpty(m_currentUpgradeRecipe.Message))
                {
                    m_currentUpgradingPlayer.ComponentGui.DisplaySmallMessage(m_currentUpgradeRecipe.Message, Color.White, true, true);
                }
            }

            ResetOperationState("升级");
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }

        // 完成维修
        public void CompleteMaintenance()
        {
            m_currentMaintainingPlayer.PlayerStats.ValuesDictionaryForMods["NumberOfBedRepairs"] = (m_currentMaintainingPlayer.PlayerStats.ValuesDictionaryForMods.ContainsKey("NumberOfBedRepairs") ? (int)m_currentMaintainingPlayer.PlayerStats.ValuesDictionaryForMods["NumberOfBedRepairs"] + 1 : 1);
            if (IsPlayerDeadOrInvalid(m_currentMaintainingPlayer) || !CheckConditions(m_currentMaintainingPlayer))
            {
                CancelOperationDueToConditions("维修");
                return;
            }

            if (!m_isMaintaining || m_currentMaintenanceRecipe == null || m_currentMaintainingPlayer == null)
            {
                m_isMaintaining = false;
                return;
            }

            if (ConsumeIngredientsAndOperate(m_currentMaintainingPlayer, m_currentMaintenanceRecipe, "维修"))
            {
                m_currentMaintainingPlayer.ComponentGui.DisplaySmallMessage($"床维修成功！", Color.Green, true, true);

                if (!string.IsNullOrEmpty(m_currentMaintenanceRecipe.Message))
                {
                    m_currentMaintainingPlayer.ComponentGui.DisplaySmallMessage(m_currentMaintenanceRecipe.Message, Color.White, true, true);
                }
            }

            ResetOperationState("维修");
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }

        // 消耗材料并执行操作
        public bool ConsumeIngredientsAndOperate(ComponentPlayer player, CraftingBedRecipe recipe, string operationType)
        {
            if (IsPlayerDeadOrInvalid(player) || !CheckConditions(player)) return false;

            ComponentInventory playerInventory = player.Entity.FindComponent<ComponentInventory>();

            if (!CheckIngredientsAvailable(recipe, player, out var lackDict)) return false;

            // 消耗材料
            foreach (var ingredient in recipe.Ingredients)
            {
                string ingredientId = ingredient.Key;
                int totalRequiredCount = ingredient.Value;
                int remainingToConsume = totalRequiredCount;

                for (int i = 0; i < playerInventory.SlotsCount && remainingToConsume > 0; i++)
                {
                    int slotValue = playerInventory.GetSlotValue(i);
                    if (slotValue == 0) continue;

                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string currentIngredientId = $"{craftingId}:{data}";

                    if (currentIngredientId == ingredientId)
                    {
                        int availableCount = playerInventory.GetSlotCount(i);
                        int consumeCount = Math.Min(availableCount, remainingToConsume);
                        playerInventory.RemoveSlotItems(i, consumeCount);
                        remainingToConsume -= consumeCount;
                    }
                }
            }

            // 执行操作
            if (operationType == "升级")
            {
                PerformBedUpgrade(recipe);
            }
            else
            {
                PerformBedMaintenance(recipe);
            }

            return true;
        }

        // 执行床升级
        public void PerformBedUpgrade(CraftingBedRecipe recipe)
        {
            if (componentBlockEntity == null || subsystemTerrain == null) return;

            int newLevel = Level + 1;
            int newBlockValue = Terrain.MakeBlockValue(NewBed.Index, 0, NewBed.SetType(componentBlockEntity.BlockValue, NewBed.GetType(componentBlockEntity.BlockValue) + 1));
            newBlockValue = BlocksManager.Blocks[Terrain.ExtractContents(newBlockValue)].SetDamage(newBlockValue, BlocksManager.Blocks[Terrain.ExtractContents(newBlockValue)].GetDurability(newBlockValue));

            subsystemTerrain.ChangeCell(
                componentBlockEntity.Coordinates.X,
                componentBlockEntity.Coordinates.Y,
                componentBlockEntity.Coordinates.Z,
                newBlockValue
            );

            componentBlockEntity.BlockValue = newBlockValue;
        }

        // 执行床维修
        public void PerformBedMaintenance(CraftingBedRecipe recipe)
        {
            if (componentBlockEntity == null || subsystemTerrain == null) return;

            // 修复床耐久度
            int repairedBlockValue = BlocksManager.Blocks[Terrain.ExtractContents(componentBlockEntity.BlockValue)].SetDamage(componentBlockEntity.BlockValue, BlocksManager.Blocks[Terrain.ExtractContents(componentBlockEntity.BlockValue)].GetDurability(componentBlockEntity.BlockValue));

            subsystemTerrain.ChangeCell(
                componentBlockEntity.Coordinates.X,
                componentBlockEntity.Coordinates.Y,
                componentBlockEntity.Coordinates.Z,
                repairedBlockValue
            );
        }

        public int CreateUpgradedBlockValue(int newLevel)
        {
            int content = Terrain.ExtractContents(componentBlockEntity.BlockValue);
            int currentData = Terrain.ExtractData(componentBlockEntity.BlockValue);
            int newData = (currentData & ~0xF) | (newLevel & 0xF);
            return Terrain.MakeBlockValue(content, 0, newData);
        }

        // 获取操作进度
        public float GetOperationProgress(string operationType)
        {
            if (operationType == "升级" && !m_isUpgrading) return 0f;
            if (operationType == "维修" && !m_isMaintaining) return 0f;

            double currentTime = subsystemGameInfo.TotalElapsedGameTime;
            double startTime = operationType == "升级" ? m_upgradeStartTime : m_maintenanceStartTime;
            double duration = operationType == "升级" ? m_upgradeDuration : m_maintenanceDuration;
            double elapsedTime = (currentTime - startTime) * subsystemTime.m_gameTimeFactor;

            return MathUtils.Clamp((float)(elapsedTime / duration), 0f, 1f);
        }

        // 检查是否正在操作
        public bool IsOperating(string operationType)
        {
            return operationType == "升级" ? m_isUpgrading : m_isMaintaining;
        }

        // 获取当前操作信息
        public string GetCurrentOperationInfo(string operationType)
        {
            CraftingBedRecipe currentRecipe = operationType == "升级" ? m_currentUpgradeRecipe : m_currentMaintenanceRecipe;
            if ((operationType == "升级" && !m_isUpgrading) || (operationType == "维修" && !m_isMaintaining) || currentRecipe == null)
                return string.Empty;

            float progress = GetOperationProgress(operationType) * 100f;
            double startTime = operationType == "升级" ? m_upgradeStartTime : m_maintenanceStartTime;
            double duration = operationType == "升级" ? m_upgradeDuration : m_maintenanceDuration;
            double remainingTime = (duration - (subsystemGameInfo.TotalElapsedGameTime - startTime) * subsystemTime.m_gameTimeFactor);

            return $"正在{operationType}: {currentRecipe.Description}\n进度: {progress:F1}%\n剩余时间: {remainingTime:F1}分钟";
        }

        // 尝试升级床
        public bool TryUpgradeBed(CraftingBedRecipe recipe, ComponentPlayer player)
        {
            return TryOperateBed(recipe, player, "升级");
        }

        // 尝试维修床
        public bool TryMaintainBed(CraftingBedRecipe recipe, ComponentPlayer player)
        {
            return TryOperateBed(recipe, player, "维修");
        }

        public bool TryOperateBed(CraftingBedRecipe recipe, ComponentPlayer player, string operationType)
        {
            if (recipe == null || player == null) return false;

            if (IsPlayerDeadOrInvalid(player) || !CheckConditions(player))
            {
                player.ComponentGui.DisplaySmallMessage($"无法{operationType}：条件不满足", Color.Red, true, true);
                return false;
            }

            // 检查材料，并获取缺少字典
            if (!CheckIngredientsAvailable(recipe, player, out var lackDict))
            {
                // 只在这里弹窗一次，显示缺少的材料
                DialogsManager.ShowDialog(null, new ShellSupplementMaterialsDialog(player, lackDict));
                player.ComponentGui.DisplaySmallMessage("材料不足！", Color.Red, true, true);
                return false;
            }

            // 播放音效
            if (operationType == "维修")
                subsystemAudio.PlaySound("Audio/UI/Production/Maintenance", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
            else
                subsystemAudio.PlaySound("Audio/UI/Production/Upgrade", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);

            return StartOperation(player, recipe, operationType);
        }

        public void ResetOperationState(string operationType)
        {
            if (operationType == "升级")
            {
                m_currentUpgradingPlayer.ComponentGui.ModalPanelWidget = null;
                m_isUpgrading = false;
                m_currentUpgradeRecipe = null;
                m_currentUpgradingPlayer = null;
            }
            else
            {
                m_currentMaintainingPlayer.ComponentGui.ModalPanelWidget = null;
                m_isMaintaining = false;
                m_currentMaintenanceRecipe = null;
                m_currentMaintainingPlayer = null;
            }
        }

        public bool IsPlayerDeadOrInvalid(ComponentPlayer player)
        {
            if (player == null) return true;

            ComponentHealth health = player.Entity.FindComponent<ComponentHealth>();
            if (health != null && health.Health <= 0f) return true;

            // 检查玩家是否打开正确的界面
            if (!(player.ComponentGui.ModalPanelWidget is BedUpgradeWidget) &&
                !(player.ComponentGui.ModalPanelWidget is BedMaintenanceWidget))
            {
                return true;
            }

            if (componentBlockEntity != null)
            {
                float distance = Vector3.Distance(player.ComponentBody.Position, componentBlockEntity.Position);
                if (distance > 5f) return true;
            }

            return false;
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            componentBlockEntity = Entity.FindComponent<ComponentBlockEntity>(throwOnError: true);
            componentBed = Entity.FindComponent<ComponentBed>(throwOnError: true);
            subsystemPickables = Project.FindSubsystem<SubsystemPickables>(throwOnError: true);
            subsystemTime = Project.FindSubsystem<SubsystemTime>();
            subsystemGameInfo = Project.FindSubsystem<SubsystemGameInfo>();
            subsystemTerrain = Project.FindSubsystem<SubsystemTerrain>();
            subsystemAudio = Project.FindSubsystem<SubsystemAudio>();
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }
    }
}
//组件交易
namespace Game
{
    public class ComponentTransaction : Component, IUpdateable
    {
        public ComponentCreatureModel componentCreatureModel;
        public ComponentMiner componentMiner;
        public ComponentHYZLGui componentHYZLGui;
        public Random m_random = new();
        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public void Update(float dt)
        {
            Vector3 eyePosition = componentCreatureModel.EyePosition;
            Vector3 forwardVector = componentCreatureModel.EyeRotation.GetForwardVector();
            Vector3 randomOffset = m_random.Vector3(0.1f);

            object raycastResult = componentMiner.Raycast(new Ray3(eyePosition, forwardVector + randomOffset), RaycastMode.Gathering, false, true, false, 3);

            // 统一的空值检查和组件查找
            if (raycastResult is BodyRaycastResult bodyResult &&
                bodyResult.ComponentBody?.Entity != null)
            {
                bool hasNPCModel = bodyResult.ComponentBody.Entity.FindComponent<ComponentNPCModel>() != null;
                componentHYZLGui.TransactionButton.IsVisible = hasNPCModel;

                // 安全地查找 Merchant 组件
                componentHYZLGui.componentMerchant = hasNPCModel
                    ? bodyResult.ComponentBody.Entity.FindComponent<ComponentMerchant>()
                    : null;
            }
            else
            {
                componentHYZLGui.TransactionButton.IsVisible = false;
                componentHYZLGui.componentMerchant = null;
            }
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            componentCreatureModel = Entity.FindComponent<ComponentCreatureModel>();
            componentMiner = Entity.FindComponent<ComponentMiner>();
            componentHYZLGui = Entity.FindComponent<ComponentHYZLGui>();
        }
    }
}
//交易界面
namespace Game
{
    public class TransactionWidget : CanvasWidget
    {
        public ComponentPlayer m_componentPlayer;
        public ComponentMerchant m_componentMerchant;
        public SubsystemAudio m_subsystemAudio;

        public LabelWidget nameLabel;
        public GridPanelWidget productDisplayGrid;
        public GridPanelWidget merchandiseGrid;
        public LabelWidget tipsLabel;
        public GridPanelWidget tradingGoodsGrid;
        public GridPanelWidget inventoryGrid;
        public BevelledButtonWidget cancelButton;
        public BevelledButtonWidget determinedButton;

        public int TradingGoodsPrice = 0;
        public int MerchandisePrice = 0;
        public int ID;

        public Random m_random = new();

        public TransactionWidget(ComponentPlayer componentPlayer, ComponentMerchant componentMerchant)
        {
            m_componentPlayer = componentPlayer;
            m_componentMerchant = componentMerchant;
            m_subsystemAudio = m_componentPlayer.Project.FindSubsystem<SubsystemAudio>();
            XElement node = ContentManager.Get<XElement>("Widgets/TransactionWidget");
            LoadContents(this, node);

            nameLabel = Children.Find<LabelWidget>("NameLabel");
            productDisplayGrid = Children.Find<GridPanelWidget>("ProductDisplayGrid");
            merchandiseGrid = Children.Find<GridPanelWidget>("MerchandiseGrid");
            tipsLabel = Children.Find<LabelWidget>("TipsLabel");
            tradingGoodsGrid = Children.Find<GridPanelWidget>("TradingGoodsGrid");
            inventoryGrid = Children.Find<GridPanelWidget>("InventoryGrid");
            cancelButton = Children.Find<BevelledButtonWidget>("CancelButton");
            determinedButton = Children.Find<BevelledButtonWidget>("DeterminedButton");

            InitializeGrid(productDisplayGrid, m_componentMerchant);
            InitializeGrid(merchandiseGrid, m_componentMerchant.Entity.FindComponent<ComponentMerchandise>());
            InitializeGrid(tradingGoodsGrid, m_componentPlayer.Entity.FindComponent<ComponentTradingGoods>());
            InitializeGrid(inventoryGrid, m_componentPlayer.ComponentMiner.Inventory);

            var merchantName = componentMerchant.Entity.FindComponent<ComponentCreature>().DisplayName;
            if (merchantName == "医药商人") ID = 0;
            else if (merchantName == "材料商人") ID = 1;
            else if (merchantName == "食物商人") ID = 2;
            else if (merchantName == "武器商人") ID = 3;

            if (componentMerchant.m_slots.TrueForAll(s => s.Count == 0))
            {
                var attributes = componentPlayer.PlayerStats.ValuesDictionaryForMods;
                foreach (var recipe in TradingItemsRecipesManager.Recipes.Where(r => r.Ingredients.Any()))
                {
                    if ((merchantName == "医药商人" && (int)attributes["CookingTable"] > recipe.MedicinesLevel - 1 && (int)attributes["CookingTable"] < recipe.MedicinesLevel + 1 && (int)attributes["CookingTable"] > 2) ||
                        (merchantName == "材料商人" && (int)attributes["TableLevel"] > recipe.MaterialsLevel - 1 && (int)attributes["TableLevel"] < recipe.MaterialsLevel + 1 && (int)attributes["TableLevel"] > 2) ||
                        (merchantName == "食物商人" && (int)attributes["MedicineStation"] > recipe.FoodLevel - 1 && (int)attributes["MedicineStation"] < recipe.FoodLevel + 1 && (int)attributes["MedicineStation"] > 2) ||
                        (merchantName == "武器商人" && (int)attributes["TableLevel"] > recipe.WeaponsLevel - 1 && (int)attributes["TableLevel"] < recipe.WeaponsLevel + 1 && (int)attributes["TableLevel"] > 2))
                    {
                        int slotIndex = 0;
                        foreach (var ingredient in recipe.Ingredients)
                        {
                            var parts = ingredient.Key.Split(':');
                            int blockValue = Terrain.MakeBlockValue(
                                BlocksManager.FindBlocksByCraftingId(parts[0])[0].BlockIndex,
                                0,
                                parts.Length > 1 ? int.Parse(parts[1]) : 0
                            );
                            componentMerchant.AddSlotItems(slotIndex++, blockValue, ingredient.Value);
                        }
                    }
                }
            }
        }

        public void InitializeGrid(GridPanelWidget grid, IInventory inventory)
        {
            int slotIndex = 0;
            for (int row = 0; row < grid.RowsCount; row++)
            {
                for (int col = 0; col < grid.ColumnsCount; col++)
                {
                    var slotWidget = new InventorySlotWidget
                    {
                        Size = new Vector2(48f, 48f)
                    };
                    slotWidget.AssignInventorySlot(inventory, slotIndex++);
                    grid.Children.Add(slotWidget);
                    grid.SetWidgetCell(slotWidget, new Point2(col, row));
                }
            }
        }

        public override void Update()
        {
            var pickables = m_componentPlayer.Project.FindSubsystem<SubsystemPickables>(true);
            if (pickables.Pickables.Count > 0)
            {
                foreach (var pickable in pickables.m_pickables) pickable.ToRemove = true;
            }

            MerchandisePrice = CalculatePrice(m_componentMerchant.Entity.FindComponent<ComponentMerchandise>().m_slots);
            foreach (AccessTalent accessTalent in AccessTalentManager.Data)
            {
                if (accessTalent.TalentID == 29 && accessTalent.Field > 0)
                {
                    MerchandisePrice = (int)(MerchandisePrice * accessTalent.DiscountAtTheTimeOfTransaction);
                }
            }
            TradingGoodsPrice = CalculatePrice(m_componentPlayer.Entity.FindComponent<ComponentTradingGoods>().m_slots);

            nameLabel.Text = LanguageControl.Get("TransactionWidget", ID * 6 + 1);

            if (MerchandisePrice != 0 && TradingGoodsPrice != 0)
            {
                int tipIndex = ID * 6;
                if (MerchandisePrice > TradingGoodsPrice * 2) tipIndex += 2;
                else if (MerchandisePrice > TradingGoodsPrice) tipIndex += 3;
                else if (MerchandisePrice == TradingGoodsPrice) tipIndex += 4;
                else if (TradingGoodsPrice > MerchandisePrice * 2) tipIndex += 6;
                else if (TradingGoodsPrice > MerchandisePrice) tipIndex += 5;
                tipsLabel.Text = LanguageControl.Get("TransactionWidget", tipIndex);
            }

            if (cancelButton.IsClicked)
            {
                ReturnItems(m_componentMerchant.Entity.FindComponent<ComponentMerchandise>().m_slots, m_componentMerchant.m_slots);
                ReturnItems(m_componentPlayer.Entity.FindComponent<ComponentTradingGoods>().m_slots, m_componentPlayer.Entity.FindComponent<ComponentInventory>().m_slots);
                m_componentPlayer.ComponentGui.ModalPanelWidget = null;
            }

            if (determinedButton.IsClicked)
            {
                if (TradingGoodsPrice >= MerchandisePrice)
                {
                    m_subsystemAudio.PlaySound("Audio/Transaction/TransactionSuccess", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
                    TransferItems(m_componentMerchant.Entity.FindComponent<ComponentMerchandise>().m_slots, m_componentPlayer.Entity.FindComponent<ComponentInventory>().m_slots);
                    ClearTradingGoods();
                    if (m_componentMerchant.m_slots.TrueForAll(s => s.Count == 0))
                    {
                        m_componentPlayer.Project.RemoveEntity(m_componentMerchant.Entity, true);
                    }
                    m_componentPlayer.ComponentGui.ModalPanelWidget = null;
                }
                else
                {
                    m_subsystemAudio.PlaySound("Audio/Transaction/TransactionFailure", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);
                    m_componentPlayer.ComponentGui.DisplaySmallMessage("对方不满意，无法交易成功", Color.White, true, true);
                }
            }
        }

        public int CalculatePrice(List<ComponentInventory.Slot> slots)
        {
            int total = 0;
            foreach (var slot in slots.Where(s => s.Count > 0))
            {
                int content = Terrain.ExtractContents(slot.Value);
                Block block = BlocksManager.Blocks[content];

                string className = block.GetType().Name;
                int specialValue = Terrain.ExtractData(slot.Value);
                total += AccessCubeAdditionalPropertiesManager.Get($"{className}:{specialValue}").Price * slot.Count;
            }
            return total;
        }

        public void ReturnItems(List<ComponentInventory.Slot> fromSlots, List<ComponentInventory.Slot> toSlots)
        {
            for (int i = 0; i < fromSlots.Count; i++)
            {
                var slot = fromSlots[i];
                if (slot.Count == 0) continue;

                bool moved = false;
                for (int j = 0; j < toSlots.Count; j++)
                {
                    if (toSlots[j].Value == slot.Value || (toSlots[j].Count == 0 && toSlots[j].Value == 0))
                    {
                        toSlots[j].Count += slot.Count;
                        fromSlots[i].Count = 0;
                        moved = true;
                        break;
                    }
                }
                if (!moved) break;
            }
        }

        public void TransferItems(List<ComponentInventory.Slot> fromSlots, List<ComponentInventory.Slot> toSlots)
        {
            for (int i = 0; i < fromSlots.Count; i++)
            {
                var slot = fromSlots[i];
                if (slot.Count == 0) continue;

                for (int j = 0; j < toSlots.Count; j++)
                {
                    if (toSlots[j].Value == slot.Value || toSlots[j].Count == 0)
                    {
                        toSlots[j].Value = slot.Value;
                        toSlots[j].Count += slot.Count;
                        fromSlots[i].Count = 0;
                        break;
                    }
                }
            }
        }

        public void ClearTradingGoods()
        {
            var tradingSlots = m_componentPlayer.Entity.FindComponent<ComponentTradingGoods>().m_slots;
            for (int i = 0; i < tradingSlots.Count; i++)
            {
                tradingSlots[i].Count = 0;
            }
        }
    }
}
//组件商人
namespace Game
{
    public class ComponentMerchant : ComponentInventoryBase, HYZLInventory
    {
        public int m_activeSlotIndex;

        public int m_visibleSlotsCount = 17;

        public override int ActiveSlotIndex
        {
            get
            {
                return m_activeSlotIndex;
            }
            set
            {
                m_activeSlotIndex = MathUtils.Clamp(value, 0, VisibleSlotsCount - 1);
            }
        }

        public override int VisibleSlotsCount
        {
            get
            {
                return m_visibleSlotsCount;
            }
            set
            {
                value = MathUtils.Clamp(value, 0, 17);
                if (value == m_visibleSlotsCount)
                {
                    return;
                }
                m_visibleSlotsCount = value;
                ActiveSlotIndex = ActiveSlotIndex;
                ComponentFrame componentFrame = Entity.FindComponent<ComponentFrame>();
                if (componentFrame != null)
                {
                    Vector3 position = componentFrame.Position + new Vector3(0f, 0.5f, 0f);
                    Vector3 velocity = 2f * componentFrame.Rotation.GetForwardVector();
                    for (int i = m_visibleSlotsCount; i < 17; i++)
                    {
                        DropSlotItems(this, i, position, velocity);
                    }
                }
            }
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            ActiveSlotIndex = valuesDictionary.GetValue<int>("ActiveSlotIndex");
        }

        public override void Save(ValuesDictionary valuesDictionary, EntityToIdMap entityToIdMap)
        {
            base.Save(valuesDictionary, entityToIdMap);
            valuesDictionary.SetValue("ActiveSlotIndex", ActiveSlotIndex);
        }

        public override int GetSlotCapacity(int slotIndex, int value)
        {
            if (slotIndex >= VisibleSlotsCount && slotIndex < 17)
            {
                return 0;
            }
            return BlocksManager.Blocks[Terrain.ExtractContents(value)].GetMaxStacking(value);
        }
    }
}
