// NPC交易物品
namespace Game
{
    public class TradingItemsRecipe
    {
        public int MedicinesLevel;
        public int MaterialsLevel;
        public int FoodLevel;
        public int WeaponsLevel;
        public float FavorabilityLevel;
        public double NumberOfDays;

        /// <summary>
        /// 配方材料字典：key=材料ID，value=所需数量
        /// </summary>
        public Dictionary<string, int> Ingredients = new Dictionary<string, int>();
    }

    public static class TradingItemsRecipesManager
    {
        public static int Index = 0;
        public static List<TradingItemsRecipe> m_recipes = new List<TradingItemsRecipe>();
        public static List<TradingItemsRecipe> Recipes => m_recipes;
        public static string fName = "TradingItemsRecipesManager";
        public static bool EnableLevelRestrictions = true;

        public static void Initialize()
        {
            if (Index == 0)
            {
                // 从XML文件加载交易配方数据
                XElement recipesRoot = ContentManager.Get<XElement>("TradingItemsRecipes");

                foreach (XElement recipeElement in recipesRoot.Descendants("Recipe"))
                {
                    try
                    {
                        TradingItemsRecipe recipe = DecodeRecipeElement(recipeElement);
                        if (recipe != null)
                        {
                            m_recipes.Add(recipe);
                            Index++;
                        }
                    }
                    catch (Exception ex)
                    {
                        Log.Error($"Failed to load trading recipe: {ex.Message}");
                    }
                }

                Log.Information($"Loaded {Index} trading recipes");
            }
        }

        public static TradingItemsRecipe DecodeRecipeElement(XElement recipeElement)
        {
            TradingItemsRecipe recipe = new TradingItemsRecipe();

            // 解析交易条件
            recipe.MedicinesLevel = XmlUtils.GetAttributeValue(recipeElement, "MedicinesLevel", 0);
            recipe.MaterialsLevel = XmlUtils.GetAttributeValue(recipeElement, "MaterialsLevel", 0);
            recipe.FoodLevel = XmlUtils.GetAttributeValue(recipeElement, "FoodLevel", 0);
            recipe.WeaponsLevel = XmlUtils.GetAttributeValue(recipeElement, "WeaponsLevel", 0);
            recipe.FavorabilityLevel = XmlUtils.GetAttributeValue(recipeElement, "FavorabilityLevel", 0f);
            recipe.NumberOfDays = XmlUtils.GetAttributeValue(recipeElement, "NumberOfDays", 0.0);

            // 解析材料 (a-z 和对应的数量属性)
            for (char c = 'a'; c <= 'z'; c++)
            {
                string ingredientKey = c.ToString();
                string countKey = c + "count";

                string ingredientValue = XmlUtils.GetAttributeValue<string>(recipeElement, ingredientKey, null);

                if (!string.IsNullOrEmpty(ingredientValue))
                {
                    int ingredientCount = XmlUtils.GetAttributeValue(recipeElement, countKey, 1);

                    // 解析材料ID和数据值
                    string[] array = ingredientValue.Split([':'], StringSplitOptions.None);
                    string craftingId = array[0];
                    int? data = array.Length >= 2 ?
                        new int?(int.Parse(array[1], CultureInfo.InvariantCulture)) : null;

                    // 验证材料是否存在
                    if (BlocksManager.FindBlocksByCraftingId(craftingId).Length == 0)
                    {
                        throw new InvalidOperationException($"Block with craftingId \"{ingredientValue}\" not found.");
                    }

                    if (data.HasValue && (data.Value < 0 || data.Value > 262143))
                    {
                        throw new InvalidOperationException($"Data in recipe ingredient \"{ingredientValue}\" must be between 0 and 0x3FFFF.");
                    }

                    // 生成完整的材料ID（包含数据值）
                    string fullIngredientId = craftingId;
                    if (data.HasValue)
                    {
                        fullIngredientId += ":" + data.Value;
                    }

                    // 添加到材料字典
                    if (recipe.Ingredients.ContainsKey(fullIngredientId))
                    {
                        recipe.Ingredients[fullIngredientId] += ingredientCount;
                    }
                    else
                    {
                        recipe.Ingredients[fullIngredientId] = ingredientCount;
                    }
                }
            }

            return recipe;
        }

        public static TradingItemsRecipe FindMatchingRecipe(
            Dictionary<string, int> playerItems,
            int playerMedicinesLevel,
            int playerMaterialsLevel,
            int playerFoodLevel,
            int playerWeaponsLevel,
            float playerFavorabilityLevel,
            double gameDays)
        {
            if (playerItems == null || playerItems.Count == 0)
            {
                return null;
            }

            foreach (TradingItemsRecipe recipe in Recipes)
            {
                // 检查玩家等级是否满足要求
                if (EnableLevelRestrictions)
                {
                    if (playerMedicinesLevel < recipe.MedicinesLevel ||
                        playerMaterialsLevel < recipe.MaterialsLevel ||
                        playerFoodLevel < recipe.FoodLevel ||
                        playerWeaponsLevel < recipe.WeaponsLevel ||
                        playerFavorabilityLevel < recipe.FavorabilityLevel ||
                        gameDays < recipe.NumberOfDays)
                    {
                        continue;
                    }
                }

                // 检查材料是否匹配
                if (MatchRecipeIngredients(recipe.Ingredients, playerItems))
                {
                    return recipe;
                }
            }

            return null;
        }

        public static bool MatchRecipeIngredients(Dictionary<string, int> requiredItems, Dictionary<string, int> playerItems)
        {
            // 检查每种所需材料
            foreach (var kvp in requiredItems)
            {
                string itemId = kvp.Key;
                int requiredCount = kvp.Value;

                // 如果玩家没有该材料或数量不足
                if (!playerItems.TryGetValue(itemId, out int playerCount) || playerCount < requiredCount)
                {
                    return false;
                }
            }

            return true;
        }
    }
}
