namespace Game
{
    public class SkillsChoiceDialog : Dialog
    {
        public ComponentSkills m_componentSkills;

        // 使用数组代替字典，提高访问效率
        public (BitmapButtonWidget SkillsButton, BitmapButtonWidget SkillsLevelButton,
                BitmapButtonWidget SelectButton, BitmapButtonWidget SkillsLockButton)[] Skills;

        public LabelWidget basicPropertiesLabel;
        public LabelWidget introductionLabel;
        public BevelledButtonWidget returnButton;
        public BevelledButtonWidget okButton;

        public readonly (float BaseValue, float Increment)[] skillConfigs = new[]
        {
            (25f, 12.5f),   // 技能0
            (30f, 15f),     // 技能1
            (15f, 7.5f),    // 技能2
            (4f, 2f),       // 技能3
            (22f, 11f),     // 技能4
            (18f, 9f),      // 技能5
            (20f, 10f),     // 技能6
            (36f, 18f),     // 技能7
            (30f, 15f),     // 技能8
            (18f, 9f),      // 技能9
            (120f, 60f),    // 技能10
            (120f, 60f),    // 技能11
            (7f, 3.5f),     // 技能12
            (3f, 1.5f),     // 技能13
            (40f, 20f),     // 技能14
            (100f, 50f),    // 技能15
            (90f, 45f)      // 技能16
        };

        public SkillsChoiceDialog(ComponentSkills componentSkills)
        {
            m_componentSkills = componentSkills;
            XElement node = ContentManager.Get<XElement>("Dialogs/SkillsChoiceDialog");
            LoadContents(this, node);

            // 初始化技能数组
            Skills = new (BitmapButtonWidget, BitmapButtonWidget, BitmapButtonWidget, BitmapButtonWidget)[17];

            for (int i = 0; i < 17; i++)
            {
                int index = i + 1;
                Skills[i] = (
                    Children.Find<BitmapButtonWidget>($"SkillsButton{index}"),
                    Children.Find<BitmapButtonWidget>($"SkillsLevelButton{index}"),
                    Children.Find<BitmapButtonWidget>($"SelectButton{index}"),
                    Children.Find<BitmapButtonWidget>($"SkillsLockButton{index}")
                );
                Skills[i].SelectButton.IsVisible = false;
            }

            basicPropertiesLabel = Children.Find<LabelWidget>("BasicPropertiesLabel");
            introductionLabel = Children.Find<LabelWidget>("IntroductionLabel");
            returnButton = Children.Find<BevelledButtonWidget>("ReturnButton");
            okButton = Children.Find<BevelledButtonWidget>("OkButton");
        }

        public override void Update()
        {
            // 更新所有技能显示
            for (int i = 0; i < m_componentSkills.SkillsAttributes.Count; i++)
            {
                var skillAttr = m_componentSkills.SkillsAttributes[i];
                var skillUI = Skills[i];

                // 更新技能图标和等级显示
                skillUI.SkillsButton.NormalSubtexture = skillUI.SkillsButton.ClickedSubtexture =
                    ContentManager.Get<Texture2D>(skillAttr.Texture);
                skillUI.SkillsLevelButton.NormalSubtexture = skillUI.SkillsLevelButton.ClickedSubtexture =
                    ContentManager.Get<Texture2D>($"Textures/Gui/Skills/SkillsLevel{skillAttr.Level}");
                skillUI.SkillsLockButton.IsVisible = !skillAttr.Have;

                // 如果当前技能被选中，更新详细信息
                if (skillUI.SelectButton.IsVisible)
                {
                    UpdateSkillDetails(i, skillAttr);
                }

                // 处理技能按钮点击
                if (skillUI.SkillsButton.IsClicked)
                {
                    HideAllSelectButtons();
                    skillUI.SelectButton.IsVisible = true;
                }
            }

            // 处理返回按钮点击
            if (returnButton.IsClicked)
            {
                DialogsManager.HideDialog(this);
            }

            // 处理确认按钮点击
            if (okButton.IsClicked)
            {
                ConfirmSelection();
                DialogsManager.HideDialog(this);
            }
        }

        public void UpdateSkillDetails(int skillIndex, AccessSkills skillAttr)
        {
            basicPropertiesLabel.Text = $"{skillAttr.Name}等级：{skillAttr.Level}";

            if (skillIndex < skillConfigs.Length)
            {
                var config = skillConfigs[skillIndex];
                float value = config.BaseValue + (skillAttr.Level - 1) * config.Increment;
                introductionLabel.Text = string.Format(
                    LanguageControl.Get("SkillsChoiceDialog", skillIndex + 1),
                    value
                );
            }
        }

        public void HideAllSelectButtons()
        {
            for (int i = 0; i < Skills.Length; i++)
            {
                Skills[i].SelectButton.IsVisible = false;
            }
        }

        public void ConfirmSelection()
        {
            // 重置所有技能的选择状态
            foreach (var skillAttr in m_componentSkills.SkillsAttributes)
            {
                skillAttr.Select = false;
            }

            // 设置当前选中的技能
            for (int i = 0; i < Skills.Length; i++)
            {
                if (Skills[i].SelectButton.IsVisible)
                {
                    m_componentSkills.SkillsAttributes[i].Select = true;
                    break;
                }
            }
        }
    }
}
//组件技能
namespace Game
{
    public class ComponentSkills : Component, IUpdateable
    {
        // 组件引用
        public ComponentBody componentBody;
        public ComponentPhysicalAttributes componentPhysicalAttributes;
        public ComponentPlayer componentPlayer;
        public ComponentCreatureModel componentCreatureModel;
        public ComponentMiner componentMiner;
        public ComponentLevel componentLevel;
        public ComponentGui componentGui;
        public ComponentHealth componentHealth;
        public SubsystemParticles subsystemParticles;
        public SubsystemTerrain subsystemTerrain;

        // 状态变量
        public bool Reading;
        public int num;
        public int TargetNumber;
        public List<AccessSkills> SkillsAttributes = [];
        public List<float> CooldownTime = [];
        public bool Death;
        public float CounterattackCount;

        public Random m_random = new();
        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public void Update(float dt)
        {
            for (int i = 0; i < SkillsAttributes.Count; i++)
            {
                var skill = SkillsAttributes[i];
                if (skill.Select)
                {
                    skill.CooldownTime = MathUtils.Max(skill.CooldownTime - dt, 0f);
                }
                skill.Level = (int)MathUtils.Min(Math.Floor(componentPhysicalAttributes.Level / 10) + 1, skill.MaxLevel);
            }
        }

        public virtual void TriggerSkills(int Id)
        {
            CounterattackCount = 0;

            for (int i = 0; i < SkillsAttributes.Count; i++)
            {
                var skill = SkillsAttributes[i];

                if (skill.SkillsID != Id) continue;

                if (skill.AttackRange > 0)
                {
                    ProcessAttackSkill(skill);
                }
                else if (!string.IsNullOrEmpty(skill.ProducingCubeUnderFeet))
                {
                    ProcessTerrainSkill(skill);
                }
                else if (skill.RandomMovement)
                {
                    ProcessMovementSkill(skill);
                }
                else if (skill.InternalAndExternalInjuryRecovery > 0)
                {
                    ProcessHealingSkill(skill);
                }
                else if (skill.HealthPointsRecovery > 0)
                {
                    componentHealth.Health += skill.HealthPointsRecovery + (skill.Level - 1) * 0.035f;
                }
                else if (skill.CounterattackCount > 0)
                {
                    CounterattackCount = skill.CounterattackCount;
                }

                // 冷却时间调整
                float cooldownMultiplier = (Death && skill.KillingCooldownTimeHalved) ? 0.5f : 1f;
                skill.CooldownTime = CooldownTime[i] * cooldownMultiplier;
            }
        }

        public void ProcessAttackSkill(AccessSkills skill)
        {
            TargetNumber = 0;
            List<float> healthList = new List<float>();
            int goals = 0;

            // 预计算数据
            if (skill.AttackMinimumHealthPoints)
            {
                foreach (Entity entity in Project.Entities)
                {
                    foreach (Component component in entity.Components)
                    {
                        if (component is ComponentHealth healthComp)
                        {
                            healthList.Add(healthComp.Health);
                        }
                    }
                }
            }

            if (skill.EqualDamage)
            {
                foreach (Entity entity in Project.Entities)
                {
                    foreach (Component component in entity.Components)
                    {
                        if (component is ComponentBody bodyComp)
                        {
                            if (Vector3.DistanceSquared(bodyComp.Position, componentBody.Position) < skill.AttackRange * skill.AttackRange)
                            {
                                goals++;
                            }
                        }
                    }
                }
            }

            // 处理攻击
            foreach (Entity entity in Project.Entities)
            {
                Vector3 eyePosition = componentCreatureModel.EyePosition;
                Vector3 forwardVector = componentCreatureModel.EyeRotation.GetForwardVector();
                Vector3 randomOffset = m_random.Vector3(0.1f);

                foreach (Component component in entity.Components)
                {
                    if (!(component is ComponentBody targetBody)) continue;
                    if (targetBody.Entity.FindComponent<ComponentPlayer>() != null) continue;

                    float distanceSquared = Vector3.DistanceSquared(targetBody.Position, componentBody.Position);
                    if (distanceSquared >= skill.AttackRange * skill.AttackRange) continue;

                    // 射线检测
                    var raycastResult = componentMiner.Raycast(
                        new Ray3(eyePosition, forwardVector + randomOffset),
                        RaycastMode.Gathering, false, true, false, skill.AttackRange
                    );

                    if (skill.IsItOnTheSameStraightLine &&
                       (!(raycastResult is BodyRaycastResult bodyResult) || bodyResult.ComponentBody?.Entity == null))
                        continue;

                    if (skill.TargetNumber > 0 && TargetNumber >= skill.TargetNumber) continue;
                    if (skill.AttackMinimumHealthPoints &&
                        targetBody.m_componentHealth.Health != (healthList.Count > 0 ? healthList.Min() : 0))
                        continue;

                    // 执行攻击
                    for (int b = 0; b < skill.AttackCount; b++)
                    {
                        float damage = CalculateDamage(skill, targetBody, goals);
                        ProcessDamageEffects(skill, targetBody, damage);
                    }

                    TargetNumber++;
                }
            }
        }

        public float CalculateDamage(AccessSkills skill, ComponentBody targetBody, int goals)
        {
            float damage = 0;
            float weaponDamage = 0;

            // 武器伤害计算
            if (skill.ReducedDurabilityOfLongRangeWeapons > 0)
            {
                if (Terrain.ExtractContents(componentMiner.ActiveBlockValue) != NewLongRangeWeaponsBlock.Index || Terrain.ExtractContents(componentMiner.ActiveBlockValue) != MusketNewBlock.Index)
                {
                    componentGui.DisplaySmallMessage("未手持远程武器", Color.Red, true, true);
                    return 0;
                }
                var block = BlocksManager.Blocks[NewLongRangeWeaponsBlock.Index];
                weaponDamage += block.GetProjectilePower(componentMiner.ActiveBlockValue) +
                               (skill.Level - 1) * (block.GetProjectilePower(componentMiner.ActiveBlockValue) / 2);
                componentMiner.DamageActiveTool(skill.ReducedDurabilityOfLongRangeWeapons);
            }

            if (skill.ReducedDurabilityOfMeleeWeapons > 0)
            {
                if (Terrain.ExtractContents(componentMiner.ActiveBlockValue) != NewToolsBlock.Index)
                {
                    componentGui.DisplaySmallMessage("未手持近战武器", Color.Red, true, true);
                    return 0;
                }
                var block = BlocksManager.Blocks[NewToolsBlock.Index];
                weaponDamage += block.GetMeleePower(componentMiner.ActiveBlockValue) +
                               (skill.Level - 1) * (block.GetMeleePower(componentMiner.ActiveBlockValue) / 2);
                componentMiner.DamageActiveTool(skill.ReducedDurabilityOfMeleeWeapons);
            }

            // 属性伤害计算
            if (skill.CommonAttackRatio > 0)
            {
                damage += componentMiner.AttackPower * componentLevel.StrengthFactor * weaponDamage *
                         (skill.CommonAttackRatio + (skill.Level - 1) * (skill.CommonAttackRatio / 2));
            }

            if (skill.IntellectualProportion > 0)
            {
                damage += (float)componentPhysicalAttributes.Intelligence *
                         (skill.IntellectualProportion + (skill.Level - 1) * (skill.IntellectualProportion / 2));
            }

            if (skill.MaximumHealthPointsReduction > 0)
            {
                damage += targetBody.m_componentHealth.AttackResilience *
                         (skill.MaximumHealthPointsReduction + (skill.Level - 1) * (skill.MaximumHealthPointsReduction / 2));
            }

            if (skill.PowerShare > 0)
            {
                damage += (float)componentPhysicalAttributes.Power *
                         (skill.PowerShare + (skill.Level - 1) * (skill.PowerShare / 2));
            }

            if (skill.EndurancePercentage > 0)
            {
                damage += (float)componentPhysicalAttributes.Endurance *
                         (skill.EndurancePercentage + (skill.Level - 1) * (skill.EndurancePercentage / 2));
            }

            if (skill.MaximumHealthValueShare > 0)
            {
                damage += componentHealth.AttackResilience *
                         (skill.MaximumHealthValueShare + (skill.Level - 1) * (skill.MaximumHealthValueShare / 2));
            }

            if (skill.EqualDamage && goals > 0)
            {
                damage /= goals;
            }

            // 碰撞伤害加成
            if (skill.CollisionDamage)
            {
                var targetEyePosition = targetBody.Entity.FindComponent<ComponentCreatureModel>().EyePosition;
                var targetForwardVector = targetBody.Entity.FindComponent<ComponentCreatureModel>().EyeRotation.GetForwardVector();
                var targetRandomOffset = m_random.Vector3(0.1f);
                var targetRaycastResult = targetBody.Entity.FindComponent<ComponentMiner>().Raycast(
                    new Ray3(targetEyePosition, (targetForwardVector + targetRandomOffset) * -1),
                    RaycastMode.Digging, true, false, false, targetBody.StanceBoxSize.Z
                );
                if (targetRaycastResult is TerrainRaycastResult)
                {
                    damage *= 2f;
                }
            }

            return damage;
        }

        public void ProcessDamageEffects(AccessSkills skill, ComponentBody targetBody, float damage)
        {
            Vector3 forwardVector = componentCreatureModel.EyeRotation.GetForwardVector();

            // 击退效果
            if (skill.RepellingDistance > 0)
            {
                targetBody.ApplyImpulse(new Vector3(forwardVector.X, 0, forwardVector.Z) *
                                       skill.RepellingDistance * targetBody.Mass);
            }

            // 自身移动效果
            if (skill.MoveTheMumberOfCells != 0)
            {
                componentBody.ApplyImpulse(new Vector3(forwardVector.X, 0, forwardVector.Z) *
                                          skill.MoveTheMumberOfCells * componentBody.Mass);
            }

            // 防御计算
            float defense = targetBody.Entity.FindComponent<ComponentExtraAttributes>().Defense;
            if (skill.SpecialAttack) defense = 0f;

            // 伤害显示
            float finalDamage = MathUtils.Max(damage - defense, 1);
            var particleSystem = new HitValueParticleSystem(
                targetBody.Position,
                targetBody.Velocity,
                new Color(255, 255, 255),
                "-" + NumericalProcessingManager.NumericalProcessing((float)Math.Round(finalDamage))
            );
            subsystemParticles.AddParticleSystem(particleSystem);

            // 眩晕效果
            if (skill.Dizziness)
            {
                particleSystem = new HitValueParticleSystem(
                    targetBody.Position,
                    targetBody.Velocity,
                    new Color(255, 255, 100),
                    "眩晕"
                );
                subsystemParticles.AddParticleSystem(particleSystem);
                targetBody.Entity.FindComponent<ComponentLocomotion>().StunTime += 5.4f;
            }

            // 应用伤害
            targetBody.m_componentHealth.Injure(
                finalDamage / targetBody.m_componentHealth.AttackResilience,
                componentPlayer,
                true,
                "被释放的" + skill.Name + "技能杀死"
            );

            Death = (targetBody.m_componentHealth.Health <= 0f);
        }

        public void ProcessTerrainSkill(AccessSkills skill)
        {
            subsystemTerrain.ChangeCell(
                (int)componentBody.Position.X,
                (int)componentBody.Position.Y,
                (int)componentBody.Position.Z,
                CraftingRecipesManager.DecodeResult(skill.ProducingCubeUnderFeet)
            );
        }

        public void ProcessMovementSkill(AccessSkills skill)
        {
            componentBody.ApplyImpulse(new Vector3(
                m_random.Int(-1, 1) * componentBody.Mass * 2,
                0,
                m_random.Int(-1, 1) * componentBody.Mass * 2
            ));
            componentPhysicalAttributes.SkillShield += (float)(
                componentPhysicalAttributes.Endurance *
                (skill.EndurancePercentage + (skill.Level - 1) * 0.075f)
            );
        }

        public void ProcessHealingSkill(AccessSkills skill)
        {
            float recovery = skill.InternalAndExternalInjuryRecovery + (skill.Level - 1) * 0.09f;
            componentPhysicalAttributes.Trauma += recovery;
            componentPhysicalAttributes.InternalInjuries += recovery;
        }

        public override void Save(ValuesDictionary valuesDictionary, EntityToIdMap entityToIdMap)
        {
            var skillssDict = new ValuesDictionary();
            valuesDictionary.SetValue("Skillss", skillssDict);

            for (int i = 0; i < SkillsAttributes.Count; i++)
            {
                var skill = SkillsAttributes[i];
                var skillsDict = new ValuesDictionary();
                skillssDict.SetValue($"Skills{i}", skillsDict);

                skillsDict.SetValue("Have", skill.Have);
                skillsDict.SetValue("Select", skill.Select);
                skillsDict.SetValue("Level", skill.Level);
                skillsDict.SetValue("CooldownTime", skill.CooldownTime);
            }
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            // 初始化组件引用
            componentBody = Entity.FindComponent<ComponentBody>();
            componentPhysicalAttributes = Entity.FindComponent<ComponentPhysicalAttributes>();
            componentPlayer = Entity.FindComponent<ComponentPlayer>();
            componentCreatureModel = Entity.FindComponent<ComponentCreatureModel>();
            componentMiner = Entity.FindComponent<ComponentMiner>();
            componentLevel = Entity.FindComponent<ComponentLevel>();
            componentGui = Entity.FindComponent<ComponentGui>();
            componentHealth = Entity.FindComponent<ComponentHealth>();
            subsystemParticles = Project.FindSubsystem<SubsystemParticles>();
            subsystemTerrain = Project.FindSubsystem<SubsystemTerrain>();

            // 初始化技能数据
            SkillsAttributes.Clear();
            CooldownTime.Clear();
            SkillsAttributes.AddRange(AccessSkillsManager.Data);
            CooldownTime = AccessSkillsManager.Data.Select(skill => skill.CooldownTime).ToList();

            // 加载保存的数据
            if (valuesDictionary.TryGetValue<ValuesDictionary>("Skillss", out ValuesDictionary skillssDict) && (Reading || num == 0))
            {
                for (int j = 0; j < SkillsAttributes.Count; j++)
                {
                    if (skillssDict.TryGetValue<ValuesDictionary>($"Skills{j}", out ValuesDictionary skillsData))
                    {
                        var skill = SkillsAttributes[j];
                        skill.Have = PermanentlySavedAttributesManager.Skills[j];
                        skill.Select = skillsData.GetValue<bool>("Select", skill.Select);
                        skill.Level = skillsData.GetValue<int>("Level", skill.Level);
                        skill.CooldownTime = skillsData.GetValue<float>("CooldownTime", skill.CooldownTime);
                    }
                }
            }
            else if (!valuesDictionary.TryGetValue<ValuesDictionary>("Skillss", out ValuesDictionary skillssDict2))
            {
                for (int j = 0; j < SkillsAttributes.Count; j++)
                {
                    SkillsAttributes[j].Have = PermanentlySavedAttributesManager.Skills[j];
                }
            }

            Reading = true;
            num++;
        }
    }
}
//子系统新物品方块行为
namespace Game
{
    public class SubsystemNewArticlesBlockBehavior : SubsystemBlockBehavior
    {
        public SubsystemTime subsystemTime;
        public SubsystemTerrain subsystemTerrain;
        public SubsystemParticles subsystemParticles;

        public override int[] HandledBlocks => new int[1]
        {
            BlocksManager.GetBlockIndex<NewArticles>()
        };

        public override bool OnUse(Ray3 ray, ComponentMiner componentMiner)
        {
            if (NewArticles.GetType(componentMiner.ActiveBlockValue) == 40)
            {
                IInventory inventory = componentMiner.Inventory;
                int ArticlesValue = CraftingRecipesManager.DecodeResult(AccessNewArticlesManager.Get(40).HandlingGetCubeClassNames);
                for (int i = 0; i < inventory.SlotsCount; i++)
                {
                    int val = inventory.GetSlotValue(i);
                    int cnt = inventory.GetSlotCount(i);
                    if ((val == 0 && cnt == 0) || val == ArticlesValue)
                    {
                        inventory.RemoveSlotItems(inventory.ActiveSlotIndex, 1);
                        inventory.AddSlotItems(i, ArticlesValue, 1);
                        return true;
                    }
                }
            }
            return false;
        }

        public override void OnBlockAdded(int value, int oldValue, int x, int y, int z)
        {
            if (NewArticles.GetType(value) == 26)
            {
                if (subsystemTime.PeriodicGameTimeEvent(5.4, 0.0))
                {
                    subsystemTerrain.ChangeCell(x, y, z, 0);
                }
            }
        }

        public override void OnCollide(CellFace cellFace, float velocity, ComponentBody componentBody)
        {
            if (NewArticles.GetType(subsystemTerrain.Terrain.GetCellValueFast(cellFace.X, cellFace.Y, cellFace.Z)) == 26)
            {
                if (componentBody.Entity.FindComponent<ComponentPlayer>() == null && componentBody.Entity.FindComponent<ComponentChaseBehavior>().Target is ComponentPlayer)
                {
                    foreach (AccessSkills accessSkills in AccessSkillsManager.Data)
                    {
                        if (accessSkills.SkillsID == 1 && accessSkills.Select)
                        {
                            float Damage = 0;
                            if (accessSkills.AgileShare > 0)
                            {
                                Damage += (float)componentBody.Entity.FindComponent<ComponentChaseBehavior>().Target.Entity.FindComponent<ComponentPhysicalAttributes>().Agility * (accessSkills.AgileShare + (accessSkills.Level - 1) * 0.15f);
                            }
                            HitValueParticleSystem particleSystem = new(componentBody.Position, componentBody.Velocity, new Color(255, 255, 255), "-" + NumericalProcessingManager.NumericalProcessing((float)Math.Round(MathUtils.Max((Damage - componentBody.Entity.FindComponent<ComponentExtraAttributes>().Defense), 1))));
                            subsystemParticles.AddParticleSystem(particleSystem);
                            componentBody.m_componentHealth.Injure((MathUtils.Max(Damage - componentBody.Entity.FindComponent<ComponentExtraAttributes>().Defense, 1)) / componentBody.m_componentHealth.AttackResilience, componentBody.Entity.FindComponent<ComponentChaseBehavior>().Target, true, "被释放的" + accessSkills.Name + "技能杀死");
                            subsystemTerrain.ChangeCell(cellFace.X, cellFace.Y, cellFace.Z, 0);
                        }
                    }
                    componentBody.Entity.FindComponent<ComponentLocomotion>().WalkSpeed = 0;
                    componentBody.Entity.FindComponent<ComponentLocomotion>().JumpSpeed = 0;
                    componentBody.Entity.FindComponent<ComponentLocomotion>().FlySpeed = 0;
                    componentBody.Entity.FindComponent<ComponentLocomotion>().TurnSpeed = 0;
                    componentBody.Entity.FindComponent<ComponentLocomotion>().SwimSpeed = 0;
                }
            }
        }

        public override void Load(ValuesDictionary valuesDictionary)
        {
            base.Load(valuesDictionary);
            subsystemTime = Project.FindSubsystem<SubsystemTime>();
            subsystemTerrain = Project.FindSubsystem<SubsystemTerrain>();
            subsystemParticles = Project.FindSubsystem<SubsystemParticles>();
        }
    }
}
