//陷阱配方获取
namespace Game
{
    public class CraftingTrapRecipe
    {
        public int MaxSize = 3;
        public string BottomSquareValue;
        public string ResultValue;
        public int ResultCount;
        public int DisplayOrder = 0;

        /// <summary>
        /// 配方材料字典：key=材料ID，value=所需数量
        /// </summary>
        public Dictionary<string, int> Ingredients = new Dictionary<string, int>();

        /// <summary>
        /// 获得材料字典：key=获取ID，value1=获得数量, value2=概率, value3=耐久减少
        /// </summary>
        public Dictionary<string, (int, float, int)> getIngredients = new Dictionary<string, (int, float, int)>();
    }

    public static class CraftingTrapRecipeManager
    {
        public static List<CraftingTrapRecipe> m_recipes = new List<CraftingTrapRecipe>();
        public static List<CraftingTrapRecipe> Recipes => m_recipes;
        public static bool EnableLevelRestrictions = true;

        public static void Initialize()
        {
            if (m_recipes.Count == 0)
            {
                // 从XML文件加载配方数据
                XElement recipesRoot = ContentManager.Get<XElement>("CraftingTrapRecipes");

                foreach (XElement recipeElement in recipesRoot.Descendants("Recipe"))
                {
                    try
                    {
                        CraftingTrapRecipe recipe = DecodeRecipeElement(recipeElement);
                        if (recipe != null)
                        {
                            m_recipes.Add(recipe);
                        }
                    }
                    catch (Exception ex)
                    {
                        Log.Error($"Failed to load recipe: {ex.Message}");
                    }
                }

                // 排序配方
                m_recipes.Sort((r1, r2) =>
                {
                    if (r1.DisplayOrder == r2.DisplayOrder)
                    {
                        return Comparer<int>.Default.Compare(r1.Ingredients.Count, r2.Ingredients.Count);
                    }
                    return Comparer<int>.Default.Compare(r1.DisplayOrder, r2.DisplayOrder);
                });

                Log.Information($"Loaded {m_recipes.Count} crafting recipes");
            }
        }

        public static CraftingTrapRecipe FindMatchingRecipe(SubsystemTerrain terrain, Dictionary<string, int> inputIngredients, float heatLevel, float playerLevel)
        {
            if (inputIngredients == null || inputIngredients.Count == 0)
            {
                return null;
            }

            // 检查预定义配方
            foreach (CraftingTrapRecipe recipe in Recipes)
            {
                if (MatchRecipe(recipe.Ingredients, inputIngredients))
                {
                    return recipe;
                }
            }

            return null;
        }

        public static bool MatchRecipe(Dictionary<string, int> requiredIngredients, Dictionary<string, int> actualIngredients)
        {
            if (requiredIngredients.Count != actualIngredients.Count)
            {
                return false;
            }

            foreach (var kvp in requiredIngredients)
            {
                string ingredientId = kvp.Key;
                int requiredCount = kvp.Value;

                if (!actualIngredients.TryGetValue(ingredientId, out int actualCount) || actualCount != requiredCount)
                {
                    return false;
                }
            }

            return true;
        }

        public static CraftingTrapRecipe ConvertToHYZLRecipe(CraftingRecipe oldRecipe)
        {
            if (oldRecipe == null) return null;

            CraftingTrapRecipe newRecipe = new CraftingTrapRecipe
            {
                ResultValue = "" + oldRecipe.ResultValue,
                ResultCount = oldRecipe.ResultCount,
                DisplayOrder = oldRecipe.DisplayOrder
            };

            // 转换材料
            foreach (string ingredient in oldRecipe.Ingredients)
            {
                if (!string.IsNullOrEmpty(ingredient))
                {
                    if (newRecipe.Ingredients.ContainsKey(ingredient))
                    {
                        newRecipe.Ingredients[ingredient]++;
                    }
                    else
                    {
                        newRecipe.Ingredients[ingredient] = 1;
                    }
                }
            }

            return newRecipe;
        }

        public static CraftingTrapRecipe DecodeRecipeElement(XElement recipeElement)
        {
            CraftingTrapRecipe recipe = new CraftingTrapRecipe();

            // 解析基础属性
            recipe.BottomSquareValue = XmlUtils.GetAttributeValue<string>(recipeElement, "BottomSquareValue");
            recipe.ResultValue = XmlUtils.GetAttributeValue<string>(recipeElement, "ResultValue");
            recipe.ResultCount = XmlUtils.GetAttributeValue<int>(recipeElement, "ResultCount", 1);
            recipe.DisplayOrder = XmlUtils.GetAttributeValue<int>(recipeElement, "DisplayOrder", 0);

            // 解析材料 (a-z 和对应的数量属性)
            ParseRecipeIngredients(recipe, recipeElement);

            // 解析获取材料 (aa-az 和对应的数量属性)
            ParseRecipeGetIngredients(recipe, recipeElement);

            return recipe;
        }

        public static void ParseRecipeIngredients(CraftingTrapRecipe recipe, XElement recipeElement)
        {
            for (char c = 'a'; c <= 'z'; c++)
            {
                string ingredientKey = c.ToString();
                string countKey = c + "count";

                string ingredientValue = XmlUtils.GetAttributeValue<string>(recipeElement, ingredientKey, null);

                if (!string.IsNullOrEmpty(ingredientValue))
                {
                    int ingredientCount = XmlUtils.GetAttributeValue<int>(recipeElement, countKey, 1);
                    AddIngredientToRecipe(recipe, ingredientValue, ingredientCount);
                }
            }
        }

        public static void ParseRecipeGetIngredients(CraftingTrapRecipe recipe, XElement recipeElement)
        {
            // 解析aa-az的获取材料
            for (char c1 = 'a'; c1 <= 'a'; c1++) // 第一个字母固定为a
            {
                for (char c2 = 'a'; c2 <= 'z'; c2++) // 第二个字母从a到z
                {
                    string ingredientKey = $"{c1}{c2}";
                    string countKey = ingredientKey + "count";

                    string ingredientValue = XmlUtils.GetAttributeValue<string>(recipeElement, ingredientKey, null);

                    if (!string.IsNullOrEmpty(ingredientValue))
                    {
                        int getCount = XmlUtils.GetAttributeValue<int>(recipeElement, countKey, 1);
                        // 默认概率为1.0，耐久减少为0
                        float chance = XmlUtils.GetAttributeValue<float>(recipeElement, ingredientKey + "chance", 1.0f);
                        int durabilityReduction = XmlUtils.GetAttributeValue<int>(recipeElement, ingredientKey + "dur", 0);

                        recipe.getIngredients[ingredientValue] = (getCount, chance, durabilityReduction);
                    }
                }
            }
        }

        public static void AddIngredientToRecipe(CraftingTrapRecipe recipe, string ingredientValue, int count)
        {
            DecodeIngredient(ingredientValue, out string craftingId, out int? data);

            // 验证材料是否存在
            if (BlocksManager.FindBlocksByCraftingId(craftingId).Length == 0)
            {
                throw new InvalidOperationException($"Block with craftingId \"{ingredientValue}\" not found.");
            }

            if (data.HasValue && (data.Value < 0 || data.Value > 262143))
            {
                throw new InvalidOperationException($"Data in recipe ingredient \"{ingredientValue}\" must be between 0 and 0x3FFFF.");
            }

            // 生成完整的材料ID（包含数据值）
            string fullIngredientId = craftingId;
            if (data.HasValue)
            {
                fullIngredientId += ":" + data.Value;
            }

            // 添加到材料字典
            if (recipe.Ingredients.ContainsKey(fullIngredientId))
            {
                recipe.Ingredients[fullIngredientId] += count;
            }
            else
            {
                recipe.Ingredients[fullIngredientId] = count;
            }
        }

        public static void DecodeIngredient(string ingredient, out string craftingId, out int? data)
        {
            string[] array = ingredient.Split([':'], StringSplitOptions.None);
            craftingId = array[0];
            data = array.Length >= 2 ? new int?(int.Parse(array[1], CultureInfo.InvariantCulture)) : null;
        }
    }
}
//耐久设置圆圈指针界面
namespace Game
{
    public class DurabilitySettingCirclePointerWidget : CanvasWidget
    {
        // 颜色配置
        public Color Color1 { get; set; }
        public Color Color2 { get; set; }
        public Color Color3 { get; set; }
        public Color PointerColor { get; set; }
        public Color BackColor { get; set; }

        // 尺寸配置
        public float CircleSize { get; set; }
        public float Thickness { get; set; }
        public float PointerLength { get; set; }

        // 区域比例配置
        public float Color1Ratio { get; set; }
        public float Color2Ratio { get; set; }
        public float Color3Ratio { get; set; }

        // 旋转控制
        public float PointerStartAngle { get; set; }
        public float PointerEndAngle { get; set; }
        public float PointerSpeed { get; set; }
        public float CurrentAngle { get; private set; }
        public bool IsReversed { get; set; }

        // 新增：旋转控制标志
        public bool IsRotating { get; set; }
        public bool IsRotationComplete { get; set; }

        // 区域接触状态
        public bool IsInColor1 { get; private set; }
        public bool IsInColor2 { get; private set; }
        public bool IsInColor3 { get; private set; }

        public DurabilitySettingCirclePointerWidget()
        {
            IsDrawRequired = true;
        }

        public override void Update()
        {
            base.Update();

            // 仅在旋转且未完成时更新角度
            if (IsRotating && !IsRotationComplete)
            {
                float delta = PointerSpeed * Time.FrameDuration;
                CurrentAngle += IsReversed ? -delta : delta;

                // 角度循环（如果未设置完成标志）
                if (CurrentAngle > PointerEndAngle) CurrentAngle = PointerStartAngle;
                if (CurrentAngle < PointerStartAngle) CurrentAngle = PointerEndAngle;
            }

            // 计算区域边界
            float totalAngle = PointerEndAngle - PointerStartAngle;
            float color1End = PointerStartAngle + totalAngle * Color1Ratio;
            float color2End = color1End + totalAngle * Color2Ratio;
            float color3End = color2End + totalAngle * Color3Ratio;

            // 检测当前在哪个区域
            IsInColor1 = CurrentAngle >= PointerStartAngle && CurrentAngle <= color1End;
            IsInColor2 = CurrentAngle > color1End && CurrentAngle <= color2End;
            IsInColor3 = CurrentAngle > color2End && CurrentAngle <= color3End;
        }

        public override void Draw(DrawContext dc)
        {
            float radius = CircleSize * GlobalTransform.Right.Length();
            var center = Vector2.Transform(ActualSize / 2f, GlobalTransform);
            FlatBatch2D flatBatch = dc.PrimitivesRenderer2D.FlatBatch(100);

            // 绘制背景圆环
            flatBatch.QueueDisc(center,
                new Vector2(radius),
                new Vector2(radius * Thickness),
                0f,
                BackColor,
                BackColor);

            // 计算各区域角度
            float totalAngle = PointerEndAngle - PointerStartAngle;
            float color1End = PointerStartAngle + totalAngle * Color1Ratio;
            float color2End = color1End + totalAngle * Color2Ratio;
            float color3End = color2End + totalAngle * Color3Ratio;

            // 绘制三个颜色区域
            flatBatch.QueueDisc(center,
                new Vector2(radius),
                new Vector2(radius * Thickness),
                0f,
                Color1,
                Color1,
                startAngle: PointerStartAngle,
                endAngle: color1End);

            flatBatch.QueueDisc(center,
                new Vector2(radius),
                new Vector2(radius * Thickness),
                0f,
                Color2,
                Color2,
                startAngle: color1End,
                endAngle: color2End);

            flatBatch.QueueDisc(center,
                new Vector2(radius),
                new Vector2(radius * Thickness),
                0f,
                Color3,
                Color3,
                startAngle: color2End,
                endAngle: color3End);

            // 绘制指针
            Vector2 direction = new Vector2(MathF.Cos(CurrentAngle), MathF.Sin(CurrentAngle));
            Vector2 endPoint = center + direction * radius * PointerLength;

            // 绘制指针线
            flatBatch.QueueLine(center, endPoint, 0f, PointerColor);

            // 绘制指针头部
            flatBatch.QueueDisc(endPoint,
                new Vector2(CircleSize * 0.05f),
                0f,
                PointerColor);
        }
    }
}
//陷阱耐久设置界面
namespace Game
{
    public class TrapDurabilitySettingsWidget : CanvasWidget
    {
        public ComponentBody m_componentBody;
        public BlockIconWidget icon;
        public DurabilitySettingCirclePointerWidget pointer;
        public BevelledButtonWidget iAmSureButton;
        public int selectedIndex, Part1Damage, Part2Damage;

        public TrapDurabilitySettingsWidget(ComponentBody componentBody, int SelectedIndex)
        {
            m_componentBody = componentBody;
            selectedIndex = SelectedIndex;

            XElement node = ContentManager.Get<XElement>("Widgets/TrapDurabilitySettingsWidget");
            LoadContents(this, node);

            icon = Children.Find<BlockIconWidget>("Icon");
            pointer = Children.Find<DurabilitySettingCirclePointerWidget>("Pointer");
            iAmSureButton = Children.Find<BevelledButtonWidget>("IAmSureButton");
            pointer.IsRotating = true;
            pointer.IsRotationComplete = false;
        }

        public override void Update()
        {
            if (iAmSureButton.IsClicked)
            {
                pointer.IsRotating = false;
                pointer.IsRotationComplete = true;

                if (pointer.IsInColor1) SetDamage(1);
                else if (pointer.IsInColor2) SetDamage(2);
                else if (pointer.IsInColor3) SetDamage(3);

                pointer.IsRotating = true;
                pointer.IsRotationComplete = false;
            }

            int recipeResult = CraftingRecipesManager.DecodeResult(CraftingTrapRecipeManager.Recipes[selectedIndex].ResultValue);
            int blockValue = NewTrap.SetPart2Damage(NewTrap.SetPart1Damage(recipeResult, Part1Damage), Part2Damage);
            blockValue = BlocksManager.Blocks[Terrain.ExtractContents(recipeResult)].SetDamage(blockValue, BlocksManager.Blocks[Terrain.ExtractContents(recipeResult)].GetDurability(blockValue));
            icon.Value = blockValue;

            if (Part1Damage != 0 && Part2Damage != 0)
            {
                m_componentBody.m_subsystemTerrain.ChangeCell((int)m_componentBody.Position.X, (int)m_componentBody.Position.Y, (int)m_componentBody.Position.Z, icon.Value);
                m_componentBody.Entity.FindComponent<ComponentGui>().ModalPanelWidget = null;
            }
        }

        public void SetDamage(int damage)
        {
            if (Part1Damage == 0) Part1Damage = damage;
            else if (Part2Damage == 0) Part2Damage = damage;
        }
    }
}
