//组件陷阱获取品
namespace Game
{
    public class ComponentTrapItems : ComponentInventoryBase, HYZLInventory, IUpdateable
    {
        public ComponentBlockEntity componentBlockEntity;
        public SubsystemTime subsystemTime;
        public SubsystemTerrain subsystemTerrain;

        public int m_activeSlotIndex;

        public int m_visibleSlotsCount = 41;

        public override int ActiveSlotIndex
        {
            get
            {
                return m_activeSlotIndex;
            }
            set
            {
                m_activeSlotIndex = MathUtils.Clamp(value, 0, VisibleSlotsCount - 1);
            }
        }

        public override int VisibleSlotsCount
        {
            get
            {
                return m_visibleSlotsCount;
            }
            set
            {
                value = MathUtils.Clamp(value, 0, 41);
                if (value == m_visibleSlotsCount)
                {
                    return;
                }
                m_visibleSlotsCount = value;
                ActiveSlotIndex = ActiveSlotIndex;
                ComponentFrame componentFrame = Entity.FindComponent<ComponentFrame>();
                if (componentFrame != null)
                {
                    Vector3 position = componentFrame.Position + new Vector3(0f, 0.5f, 0f);
                    Vector3 velocity = 2f * componentFrame.Rotation.GetForwardVector();
                    for (int i = m_visibleSlotsCount; i < 41; i++)
                    {
                        DropSlotItems(this, i, position, velocity);
                    }
                }
            }
        }

        public void Update(float dt)
        {
            int x = componentBlockEntity.Coordinates.X;
            int y = componentBlockEntity.Coordinates.Y;
            int z = componentBlockEntity.Coordinates.Z;
            int currentBlockValue = subsystemTerrain.Terrain.GetCellValue(x, y, z);
            if (BlocksManager.Blocks[Terrain.ExtractContents(currentBlockValue)].GetDamage(currentBlockValue) > 0)
            {
                if (subsystemTime.PeriodicGameTimeEvent(2400, 0.0))
                {
                    foreach (var recipe in CraftingTrapRecipeManager.Recipes[NewTrap.GetType(currentBlockValue)].getIngredients)
                    {
                        if (m_random.Bool(recipe.Value.Item2 * (NewTrap.GetPart1Damage(currentBlockValue) + NewTrap.GetPart2Damage(currentBlockValue)) / 5))
                        {
                            for (int i = 0; i < SlotsCount; i++)
                            {
                                int content = Terrain.ExtractContents(GetSlotValue(i));
                                int data = Terrain.ExtractData(GetSlotValue(i));
                                Block block = BlocksManager.Blocks[content];
                                string craftingId = block.GetCraftingId(GetSlotValue(i));
                                string currentIngredientId = $"{craftingId}:{data}";

                                string[] safeParts = recipe.Key.Split(':');
                                string beforeChar = safeParts[0];
                                string afterChar = safeParts.Length > 1 ? safeParts[1] : string.Empty;

                                if (currentIngredientId == recipe.Key && GetSlotCount(i) <= BlocksManager.Blocks[BlocksManager.FindBlocksByCraftingId(beforeChar)[0].BlockIndex].GetMaxStacking(Terrain.MakeBlockValue(BlocksManager.FindBlocksByCraftingId(beforeChar)[0].BlockIndex, 0, int.Parse(afterChar))))
                                {
                                    AddSlotItems(i, GetSlotValue(i), recipe.Value.Item1);

                                    int repairedBlockValue = BlocksManager.Blocks[Terrain.ExtractContents(currentBlockValue)].SetDamage(currentBlockValue, BlocksManager.Blocks[Terrain.ExtractContents(currentBlockValue)].GetDamage(currentBlockValue) - recipe.Value.Item3);

                                    subsystemTerrain.ChangeCell(
                                        componentBlockEntity.Coordinates.X,
                                        componentBlockEntity.Coordinates.Y,
                                        componentBlockEntity.Coordinates.Z,
                                        repairedBlockValue
                                    );
                                    break;
                                }
                                else if (GetSlotValue(i) == 0)
                                {
                                    AddSlotItems(i, Terrain.MakeBlockValue(BlocksManager.FindBlocksByCraftingId(beforeChar)[0].BlockIndex, 0, int.Parse(afterChar)), recipe.Value.Item1);

                                    int repairedBlockValue = BlocksManager.Blocks[Terrain.ExtractContents(currentBlockValue)].SetDamage(currentBlockValue, BlocksManager.Blocks[Terrain.ExtractContents(currentBlockValue)].GetDamage(currentBlockValue) - recipe.Value.Item3);

                                    subsystemTerrain.ChangeCell(
                                        componentBlockEntity.Coordinates.X,
                                        componentBlockEntity.Coordinates.Y,
                                        componentBlockEntity.Coordinates.Z,
                                        repairedBlockValue
                                    );
                                    break;
                                }
                            }
                        }
                    }
                }
            }
            else
            {
                subsystemTerrain.ChangeCell(
                    componentBlockEntity.Coordinates.X,
                    componentBlockEntity.Coordinates.Y,
                    componentBlockEntity.Coordinates.Z,
                    0
                );
            }
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            componentBlockEntity = Entity.FindComponent<ComponentBlockEntity>();
            subsystemTime = Project.FindSubsystem<SubsystemTime>();
            subsystemTerrain = Project.FindSubsystem<SubsystemTerrain>();
            ActiveSlotIndex = valuesDictionary.GetValue<int>("ActiveSlotIndex");
        }

        public override void Save(ValuesDictionary valuesDictionary, EntityToIdMap entityToIdMap)
        {
            base.Save(valuesDictionary, entityToIdMap);
            valuesDictionary.SetValue("ActiveSlotIndex", ActiveSlotIndex);
        }

        public override int GetSlotCapacity(int slotIndex, int value)
        {
            if (slotIndex >= VisibleSlotsCount && slotIndex < 41)
            {
                return 0;
            }
            return BlocksManager.Blocks[Terrain.ExtractContents(value)].GetMaxStacking(value);
        }
    }
}
