            InitializeGrid(trapItemsGrid, m_componentTrapItems);
        }

        public override void Update()
        {
            icon.Value = componentBlockEntity.BlockValue;
            precisionLabel.Text = "精良度：" + ((NewTrap.GetPart1Damage(icon.Value) + NewTrap.GetPart2Damage(icon.Value)) * 20) + "%";
            durabilityLabel.Text = "耐久度：" + BlocksManager.Blocks[Terrain.ExtractContents(icon.Value)].GetDamage(icon.Value);
        }

        public void InitializeGrid(GridPanelWidget grid, IInventory inventory)
        {
            int slotIndex = 0;
            for (int row = 0; row < grid.RowsCount; row++)
            {
                for (int col = 0; col < grid.ColumnsCount; col++)
                {
                    var slotWidget = new InventorySlotWidget
                    {
                        Size = new Vector2(48f, 48f)
                    };
                    slotWidget.AssignInventorySlot(inventory, slotIndex++);
                    grid.Children.Add(slotWidget);
                    grid.SetWidgetCell(slotWidget, new Point2(col, row));
                }
            }
        }
    }
