//组件箱子
namespace Game
{
    public class ComponentBox : ComponentInventoryBase, IUpdateable
    {
        public ComponentBlockEntity componentBlockEntity;
        public int _cachedBlockType = -1;

        public int Level { get; private set; }
        public int NumberOfPages;
        public int NumberOfCells { get; private set; }
        public float GridSize { get; private set; }
        public int MaxNumberOfPages { get; private set; }
        public int CapacityDisplay { get; private set; }

        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public virtual void Update(float dt)
        {
            int blockType = NewBox.GetType(componentBlockEntity.BlockValue);
            Level = blockType + 1;

            if (_cachedBlockType != blockType)
            {
                _cachedBlockType = blockType;

                NumberOfCells = AccessNewBoxManager.Get(_cachedBlockType).NumberOfCells;
                GridSize = AccessNewBoxManager.Get(_cachedBlockType).GridSize;
                MaxNumberOfPages = AccessNewBoxManager.Get(_cachedBlockType).MaxNumberOfPages;
            }

            int requiredSlots = NumberOfCells * NumberOfCells * MaxNumberOfPages;
            if (m_slots.Count < requiredSlots)
            {
                int slotsToAdd = requiredSlots - m_slots.Count;
                for (int i = 0; i < slotsToAdd; i++)
                {
                    m_slots.Add(new Slot());
                }

                ValuesDictionary slotsDict = m_valuesDictionary.GetValue<ValuesDictionary>("Slots");
                if (slotsDict != null)
                {
                    for (int j = 0; j < m_slots.Count; j++)
                    {
                        ValuesDictionary slotData = slotsDict.GetValue<ValuesDictionary>($"Slot{j.ToString(CultureInfo.InvariantCulture)}", null);
                        if (slotData != null)
                        {
                            Slot slot = m_slots[j];
                            slot.Value = slotData.GetValue<int>("Contents");
                            slot.Count = slotData.GetValue<int>("Count");
                        }
                    }
                }
            }

            CapacityDisplay = 0;
            foreach (Slot slot in m_slots)
            {
                if (slot.Count > 0)
                {
                    CapacityDisplay++;
                }
            }
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            componentBlockEntity = Entity.FindComponent<ComponentBlockEntity>(throwOnError: true);
            m_valuesDictionary = valuesDictionary;
        }

        public override void Save(ValuesDictionary valuesDictionary, EntityToIdMap entityToIdMap)
        {
            base.Save(valuesDictionary, entityToIdMap);
            valuesDictionary.SetValue("NumberOfPages", NumberOfPages);
        }
    }
}
