            boxGridPanel = Children.Find<GridPanelWidget>("BoxGridPanel");
            boxPageUpButton = Children.Find<BitmapButtonWidget>("BoxPageUpButton");
            boxPageDownButton = Children.Find<BitmapButtonWidget>("BoxPageDownButton");
            upgradeButton = Children.Find<BitmapButtonWidget>("UpgradeButton");
            capacityDisplayLabel = Children.Find<LabelWidget>("CapacityDisplayLabel");

            int gridSize = m_componentBox.NumberOfCells;
            int slotIndex = gridSize * gridSize * m_componentBox.NumberOfPages;
            boxGridPanel.ColumnsCount = boxGridPanel.RowsCount = gridSize;

            for (int a = 0; a < gridSize; a++)
            {
                for (int b = 0; b < gridSize; b++)
                {
                    var slotWidget = new InventorySlotWidget
                    {
                        Size = new Vector2(m_componentBox.GridSize, m_componentBox.GridSize)
                    };
                    slotWidget.AssignInventorySlot(m_componentBox, slotIndex++);
                    boxGridPanel.Children.Add(slotWidget);
                    boxGridPanel.SetWidgetCell(slotWidget, new Point2(b, a));
                }
            }
            componentPlayer.PlayerStats.ValuesDictionaryForMods["BoxLevel"] = (componentPlayer.PlayerStats.ValuesDictionaryForMods.ContainsKey("BoxLevel") ? ((int)componentPlayer.PlayerStats.ValuesDictionaryForMods["BoxLevel"] > m_componentBox.Level ? componentPlayer.PlayerStats.ValuesDictionaryForMods["BoxLevel"] : m_componentBox.Level) : m_componentBox.Level);
        }

        public override void Update()
        {
            int maxCapacity = m_componentBox.NumberOfCells * m_componentBox.NumberOfCells * m_componentBox.MaxNumberOfPages;
            boxPageUpButton.IsVisible = m_componentBox.NumberOfPages + 1 < m_componentBox.MaxNumberOfPages;
            boxPageDownButton.IsVisible = m_componentBox.NumberOfPages != 0;
            upgradeButton.IsVisible = m_componentBox.Level < AccessNewBoxManager.Data.Count;
            capacityDisplayLabel.Text = $"容量{m_componentBox.CapacityDisplay}/{maxCapacity}";

            if (boxPageUpButton.IsClicked)
            {
                m_componentBox.NumberOfPages++;
                m_componentPlayer.ComponentGui.ModalPanelWidget = new BoxWidget(m_componentPlayer, m_componentBox);
            }
            if (boxPageDownButton.IsClicked)
            {
                m_componentBox.NumberOfPages--;
                m_componentPlayer.ComponentGui.ModalPanelWidget = new BoxWidget(m_componentPlayer, m_componentBox);
            }
            if (upgradeButton.IsClicked)
            {
                m_componentPlayer.ComponentGui.ModalPanelWidget = new BoxUpgradeWidget(m_componentPlayer, m_componentBox);
            }
        }
    }
}
//箱子升级界面
namespace Game
{
    public class BoxUpgradeWidget : CanvasWidget
    {
        public ComponentPlayer m_componentPlayer;
        public ComponentBox m_componentBox;
        public ComponentUpgradeBox m_componentUpgradeBox;

        public BlockIconWidget icon;
        public LabelWidget levelLabel;
        public LabelWidget descriptionLabel;
        public LabelWidget timeConsumingLabel;
        public BevelledButtonWidget cancelItButton;
        public BevelledButtonWidget iAmSureButton;

        public CraftingBoxRecipe craftingBoxRecipe;

        public Dictionary<BlockIconWidget, LabelWidget> Ingredients = new Dictionary<BlockIconWidget, LabelWidget>();

        public BoxUpgradeWidget(ComponentPlayer componentPlayer, ComponentBox componentBox)
        {
            m_componentPlayer = componentPlayer;
            m_componentBox = componentBox;
            m_componentUpgradeBox = m_componentBox.Entity.FindComponent<ComponentUpgradeBox>();
            XElement node = ContentManager.Get<XElement>("Widgets/BoxUpgradeWidget");
            LoadContents(this, node);
            icon = Children.Find<BlockIconWidget>("Icon");
            levelLabel = Children.Find<LabelWidget>("LevelLabel");
            descriptionLabel = Children.Find<LabelWidget>("DescriptionLabel");
            for (int a = 1; a < 27; a++)
            {
                Ingredients.Add(Children.Find<BlockIconWidget>("Materials" + a), Children.Find<LabelWidget>("Materials" + a + "Label"));
            }
            timeConsumingLabel = Children.Find<LabelWidget>("TimeConsumingLabel");
            cancelItButton = Children.Find<BevelledButtonWidget>("CancelItButton");
            iAmSureButton = Children.Find<BevelledButtonWidget>("IAmSureButton");
        }

        public override void Update()
        {
            if (m_componentBox.Level >= AccessNewBoxManager.Data.Count)
            {
                icon.Value = Terrain.MakeBlockValue(NewBox.Index, 0, AccessNewBoxManager.Data.Count - 1);
            }
            else
            {
                icon.Value = Terrain.MakeBlockValue(NewBox.Index, 0, m_componentBox.Level);
            }
            levelLabel.Text = "等级:" + (m_componentBox.Level + 1);

            if (cancelItButton.IsClicked)
            {
                m_componentPlayer.ComponentGui.ModalPanelWidget = new BoxWidget(m_componentPlayer, m_componentBox);
            }
            if (iAmSureButton.IsClicked && craftingBoxRecipe != null)
            {
                m_componentUpgradeBox.TryUpgradeBox(craftingBoxRecipe, m_componentPlayer);
                craftingBoxRecipe = null;
            }

            if (craftingBoxRecipe == null)
            {
                foreach (CraftingBoxRecipe recipe in CraftingBoxRecipeManager.Recipes)
                {
                    if (m_componentBox.Level == recipe.RequiredBoxLevel)
                    {
                        craftingBoxRecipe = recipe;
                        descriptionLabel.Text = recipe.Description;
                        timeConsumingLabel.Text = "耗时:" + recipe.TimeConsuming + "分钟";
                        for (int a = 0; a < 26; a++)
                        {
                            try
                            {
                                string[] safeParts = recipe.Ingredients.ElementAt(a).Key.Split(':');
                                string beforeChar = safeParts[0];
                                string afterChar = safeParts.Length > 1 ? safeParts[1] : string.Empty;
                                Ingredients.ElementAt(a).Key.Value = Terrain.MakeBlockValue(BlocksManager.FindBlocksByCraftingId(beforeChar)[0].BlockIndex, 0, int.Parse(afterChar));
                                Ingredients.ElementAt(a).Value.Text = "X" + recipe.Ingredients.ElementAt(a).Value;
                            }
                            catch
                            {
                                Ingredients.ElementAt(a).Key.Value = 0;
                                Ingredients.ElementAt(a).Value.Text = "";
                            }
                        }
                    }
                }
            }
        }
    }
}
//组件箱子升级
namespace Game
{
    public class ComponentUpgradeBox : ComponentInventoryBase, IUpdateable
    {
        public ComponentBlockEntity componentBlockEntity;
        public ComponentBox componentBox;
        public SubsystemPickables subsystemPickables;
        public SubsystemTime subsystemTime;
        public SubsystemGameInfo subsystemGameInfo;
        public SubsystemTerrain subsystemTerrain;
        public SubsystemAudio subsystemAudio;

        // 配方匹配
        public CraftingBoxRecipe m_matchedUpgradeRecipe;
        public bool m_recipeUpdateNeeded;
        public bool m_recipeRefindNeeded;
        public int Level;

        // 升级时间相关字段
        public double m_upgradeStartTime;
        public double m_upgradeDuration;
        public bool m_isUpgrading;
        public CraftingBoxRecipe m_currentUpgradeRecipe;
        public ComponentPlayer m_currentUpgradingPlayer;

        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public virtual void Update(float dt)
        {
            // 处理升级时间逻辑
            if (m_isUpgrading)
            {
                if (!CheckConditions(m_currentUpgradingPlayer))
                {
                    CancelOperationDueToConditions();
                    return;
                }

                subsystemTime.m_gameTimeFactor = 120;
                double currentTime = subsystemGameInfo.TotalElapsedGameTime;
                double elapsedTime = (currentTime - m_upgradeStartTime);

                if (elapsedTime >= m_upgradeDuration)
                {
                    subsystemTime.m_gameTimeFactor = 1;
                    CompleteUpgrade();
                }
            }

            if (m_recipeUpdateNeeded)
            {
                UpdateRecipeResult(m_recipeRefindNeeded);
            }
            m_recipeUpdateNeeded = false;
            m_recipeRefindNeeded = false;

            UpdateBoxStatus();
        }

        public void UpdateBoxStatus()
        {
            if (componentBlockEntity != null && componentBox != null)
            {
                Level = componentBox.Level;
            }
        }

        // 条件检查
        public bool CheckConditions(ComponentPlayer player)
        {
            if (player == null) return false;

            ComponentHealth health = player.Entity.FindComponent<ComponentHealth>();
            if (health != null && health.Health <= 0f) return false;

            // 检查玩家是否打开正确的界面
            if (!(player.ComponentGui.ModalPanelWidget is BoxUpgradeWidget)) return false;

            if (componentBlockEntity != null)
            {
                float distance = Vector3.Distance(player.ComponentBody.Position, componentBlockEntity.Position);
                if (distance > 5f) return false;
            }

            ComponentVitalStats vitalStats = player.ComponentVitalStats;
            if (vitalStats != null && vitalStats.Sleep <= 0.2f)
            {
                player.ComponentGui.DisplaySmallMessage("太困了，无法继续操作！", Color.Red, true, true);
                return false;
            }

            return true;
        }

        // 取消操作
        public void CancelOperationDueToConditions()
        {
            if (m_currentUpgradingPlayer != null)
            {
                m_currentUpgradingPlayer.ComponentGui.DisplaySmallMessage("升级已取消", Color.Yellow, true, true);
            }

            subsystemTime.m_gameTimeFactor = 1;

            m_isUpgrading = false;
            m_currentUpgradeRecipe = null;
            m_currentUpgradingPlayer = null;
        }

        public override void AddSlotItems(int slotIndex, int value, int count)
        {
            base.AddSlotItems(slotIndex, value, count);
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }

        public override int RemoveSlotItems(int slotIndex, int count)
        {
            int num = base.RemoveSlotItems(slotIndex, count);
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
            return num;
        }

        public virtual void UpdateRecipeResult(bool recipeRefindNeeded)
        {
            ComponentPlayer componentPlayer = FindInteractingPlayer();
            if (componentPlayer == null) return;

            if (!CheckConditions(componentPlayer)) return;

            Dictionary<string, int> playerIngredients = GetPlayerIngredients(componentPlayer);

            CraftingBoxRecipe upgradeRecipe;
            if (recipeRefindNeeded || m_matchedUpgradeRecipe == null)
            {
                upgradeRecipe = CraftingBoxRecipeManager.FindMatchingRecipe(playerIngredients, Level);
            }
            else
            {
                upgradeRecipe = m_matchedUpgradeRecipe;
            }

            if (upgradeRecipe != null)
            {
                m_matchedUpgradeRecipe = upgradeRecipe;
                if (CheckIngredientsAvailable(upgradeRecipe, componentPlayer, out var lackDict))
                {
                    componentPlayer.ComponentGui.DisplaySmallMessage($"可以升级到{upgradeRecipe.Description}！", Color.Green, true, true);
                }
            }
            else
            {
                m_matchedUpgradeRecipe = null;
            }
        }

        public Dictionary<string, int> GetPlayerIngredients(ComponentPlayer player)
        {
            Dictionary<string, int> playerIngredients = new Dictionary<string, int>();
            ComponentInventory playerInventory = player.Entity.FindComponent<ComponentInventory>();

            for (int i = 0; i < playerInventory.SlotsCount; i++)
            {
                int slotValue = playerInventory.GetSlotValue(i);
                int slotCount = playerInventory.GetSlotCount(i);

                if (slotValue != 0 && slotCount > 0)
                {
                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string ingredientKey = $"{craftingId}:{data}";

                    if (playerIngredients.ContainsKey(ingredientKey))
                    {
                        playerIngredients[ingredientKey] += slotCount;
                    }
                    else
                    {
                        playerIngredients[ingredientKey] = slotCount;
                    }
                }
            }

            return playerIngredients;
        }

        public bool CheckIngredientsAvailable(CraftingBoxRecipe recipe, ComponentPlayer player, out Dictionary<string, int> lackDict)
        {
            lackDict = new Dictionary<string, int>();
            if (!CheckConditions(player)) return false;

            Dictionary<string, int> playerIngredients = GetPlayerIngredients(player);

            foreach (var ingredient in recipe.Ingredients)
            {
                string ingredientId = ingredient.Key;
                int requiredCount = ingredient.Value;
                int actualCount = playerIngredients.ContainsKey(ingredientId) ? playerIngredients[ingredientId] : 0;

                if (actualCount < requiredCount)
                {
                    lackDict[ingredientId] = requiredCount - actualCount;
                }
            }

            return lackDict.Count == 0;
        }

        // 开始升级操作
        public bool StartOperation(ComponentPlayer player, CraftingBoxRecipe recipe)
        {
            if (!CheckConditions(player))
            {
                player.ComponentGui.DisplaySmallMessage("无法开始升级：条件不满足", Color.Red, true, true);
                return false;
            }

            if (m_isUpgrading)
            {
                player.ComponentGui.DisplaySmallMessage("正在升级中，请等待完成！", Color.Yellow, true, true);
                return false;
            }

            if (!CheckIngredientsAvailable(recipe, player, out var lackDict))
            {
                player.ComponentGui.DisplaySmallMessage("材料不足！", Color.Red, true, true);
                return false;
            }

            double operationTimeSeconds = recipe.TimeConsuming;

            m_upgradeDuration = operationTimeSeconds;
            m_upgradeStartTime = subsystemGameInfo.TotalElapsedGameTime;
            m_isUpgrading = true;
            m_currentUpgradeRecipe = recipe;
            m_currentUpgradingPlayer = player;

            player.ComponentGui.DisplaySmallMessage($"开始升级箱子：{recipe.Description}，预计需要 {operationTimeSeconds} 分钟", Color.Yellow, true, true);
            return true;
        }

        // 完成升级
        public void CompleteUpgrade()
        {
            if (!CheckConditions(m_currentUpgradingPlayer))
            {
                CancelOperationDueToConditions();
                return;
            }

            if (!m_isUpgrading || m_currentUpgradeRecipe == null || m_currentUpgradingPlayer == null)
            {
                m_isUpgrading = false;
                return;
            }

            if (ConsumeIngredientsAndOperate(m_currentUpgradingPlayer, m_currentUpgradeRecipe))
            {
                m_currentUpgradingPlayer.ComponentGui.DisplaySmallMessage($"箱子升级成功：{m_currentUpgradeRecipe.Description}！", Color.Green, true, true);

                if (!string.IsNullOrEmpty(m_currentUpgradeRecipe.Message))
                {
                    m_currentUpgradingPlayer.ComponentGui.DisplaySmallMessage(m_currentUpgradeRecipe.Message, Color.White, true, true);
                }
            }

            m_currentUpgradingPlayer.ComponentGui.ModalPanelWidget = null;
            m_isUpgrading = false;
            m_currentUpgradeRecipe = null;
            m_currentUpgradingPlayer = null;

            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }

        // 消耗材料并执行操作
        public bool ConsumeIngredientsAndOperate(ComponentPlayer player, CraftingBoxRecipe recipe)
        {
            if (!CheckConditions(player)) return false;

            ComponentInventory playerInventory = player.Entity.FindComponent<ComponentInventory>();

            if (!CheckIngredientsAvailable(recipe, player, out var lackDict)) return false;

            // 消耗材料
            foreach (var ingredient in recipe.Ingredients)
            {
                string ingredientId = ingredient.Key;
                int totalRequiredCount = ingredient.Value;
                int remainingToConsume = totalRequiredCount;

                for (int i = 0; i < playerInventory.SlotsCount && remainingToConsume > 0; i++)
                {
                    int slotValue = playerInventory.GetSlotValue(i);
                    if (slotValue == 0) continue;

                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string currentIngredientId = $"{craftingId}:{data}";

                    if (currentIngredientId == ingredientId)
                    {
                        int availableCount = playerInventory.GetSlotCount(i);
                        int consumeCount = Math.Min(availableCount, remainingToConsume);
                        playerInventory.RemoveSlotItems(i, consumeCount);
                        remainingToConsume -= consumeCount;
                    }
                }
            }

            // 执行升级操作
            PerformBoxUpgrade(recipe);
            return true;
        }

        // 执行箱子升级
        public void PerformBoxUpgrade(CraftingBoxRecipe recipe)
        {
            if (componentBlockEntity == null || subsystemTerrain == null) return;

            int newLevel = Level + 1;
            int newBlockValue = Terrain.MakeBlockValue(NewBox.Index, 0, NewBox.SetType(componentBlockEntity.BlockValue, NewBox.GetType(componentBlockEntity.BlockValue) + 1));

            subsystemTerrain.ChangeCell(
                componentBlockEntity.Coordinates.X,
                componentBlockEntity.Coordinates.Y,
                componentBlockEntity.Coordinates.Z,
                newBlockValue
            );

            componentBlockEntity.BlockValue = newBlockValue;
        }

        public int CreateUpgradedBlockValue(int newLevel)
        {
            int content = Terrain.ExtractContents(componentBlockEntity.BlockValue);
            int currentData = Terrain.ExtractData(componentBlockEntity.BlockValue);
            int newData = (currentData & ~0xF) | (newLevel & 0xF);
            return Terrain.MakeBlockValue(content, 0, newData);
        }

        // 获取操作进度
        public float GetOperationProgress()
        {
            if (!m_isUpgrading) return 0f;

            double currentTime = subsystemGameInfo.TotalElapsedGameTime;
            double elapsedTime = (currentTime - m_upgradeStartTime) * subsystemTime.m_gameTimeFactor;

            return MathUtils.Clamp((float)(elapsedTime / m_upgradeDuration), 0f, 1f);
        }

        // 检查是否正在操作
        public bool IsOperating()
        {
            return m_isUpgrading;
        }

        // 获取当前操作信息
        public string GetCurrentOperationInfo()
        {
            if (!m_isUpgrading || m_currentUpgradeRecipe == null)
                return string.Empty;

            float progress = GetOperationProgress() * 100f;
            double remainingTime = (m_upgradeDuration - (subsystemGameInfo.TotalElapsedGameTime - m_upgradeStartTime) * subsystemTime.m_gameTimeFactor);

            return $"正在升级: {m_currentUpgradeRecipe.Description}\n进度: {progress:F1}%\n剩余时间: {remainingTime:F1}分钟";
        }

        // 尝试升级箱子
        public bool TryUpgradeBox(CraftingBoxRecipe recipe, ComponentPlayer player)
        {
            if (recipe == null || player == null) return false;

            if (!CheckConditions(player))
            {
                player.ComponentGui.DisplaySmallMessage("无法升级：条件不满足", Color.Red, true, true);
                return false;
            }

            // 检查材料，并获取缺少字典
            if (!CheckIngredientsAvailable(recipe, player, out var lackDict))
            {
                // 只在这里弹窗一次
                DialogsManager.ShowDialog(null, new ShellSupplementMaterialsDialog(player, lackDict));
                player.ComponentGui.DisplaySmallMessage("材料不足！", Color.Red, true, true);
                return false;
            }

            subsystemAudio.PlaySound("Audio/UI/Production/Upgrade", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);

            return StartOperation(player, recipe);
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            componentBlockEntity = Entity.FindComponent<ComponentBlockEntity>(throwOnError: true);
            componentBox = Entity.FindComponent<ComponentBox>(throwOnError: true);
            subsystemPickables = Project.FindSubsystem<SubsystemPickables>(throwOnError: true);
            subsystemTime = Project.FindSubsystem<SubsystemTime>();
            subsystemGameInfo = Project.FindSubsystem<SubsystemGameInfo>();
            subsystemTerrain = Project.FindSubsystem<SubsystemTerrain>();
            subsystemAudio = Project.FindSubsystem<SubsystemAudio>();
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }
    }
}
//箱子升级配方获取
namespace Game
{
    public class CraftingBoxRecipe
    {
        public int MaxSize = 3;
        public string Description;
        public string Message;
        public int TimeConsuming;
        public int RequiredBoxLevel;
        public int DisplayOrder = 0;

        /// <summary>
        /// 配方材料字典：key=材料ID，value=所需数量
        /// </summary>
        public Dictionary<string, int> Ingredients = new Dictionary<string, int>();
    }

    public static class CraftingBoxRecipeManager
    {
        public static int Index = 0;
        public static List<CraftingBoxRecipe> m_recipes = new List<CraftingBoxRecipe>();
        public static List<CraftingBoxRecipe> Recipes => m_recipes;
        public static bool EnableLevelRestrictions = true;

        public static void Initialize()
        {
            if (Index == 0)
            {
                // 从XML文件加载配方数据
                XElement recipesRoot = ContentManager.Get<XElement>("CraftingBoxRecipes");

                foreach (XElement recipeElement in recipesRoot.Descendants("Recipe"))
                {
                    try
                    {
                        CraftingBoxRecipe recipe = DecodeRecipeElement(recipeElement);
                        if (recipe != null)
                        {
                            m_recipes.Add(recipe);
                            Index++;
                        }
                    }
                    catch (Exception ex)
                    {
                        Log.Error($"Failed to load recipe: {ex.Message}");
                    }
                }

                // 排序配方
                m_recipes.Sort((r1, r2) =>
                {
                    if (r1.DisplayOrder == r2.DisplayOrder)
                    {
                        return Comparer<int>.Default.Compare(r1.Ingredients.Count, r2.Ingredients.Count);
                    }
                    return Comparer<int>.Default.Compare(r1.DisplayOrder, r2.DisplayOrder);
                });

                Log.Information($"Loaded {Index} crafting box recipes");
            }
        }

        public static CraftingBoxRecipe DecodeRecipeElement(XElement recipeElement)
        {
            CraftingBoxRecipe recipe = new CraftingBoxRecipe();

            // 解析基础属性
            recipe.Description = XmlUtils.GetAttributeValue<string>(recipeElement, "Description");
            recipe.Message = XmlUtils.GetAttributeValue<string>(recipeElement, "Message");
            recipe.DisplayOrder = XmlUtils.GetAttributeValue(recipeElement, "DisplayOrder", 0);
            recipe.RequiredBoxLevel = XmlUtils.GetAttributeValue(recipeElement, "RequiredBoxLevel", 0);
            recipe.TimeConsuming = XmlUtils.GetAttributeValue(recipeElement, "TimeConsuming", 0);

            // 解析材料 (a-z 和对应的数量属性)
            for (char c = 'a'; c <= 'z'; c++)
            {
                string ingredientKey = c.ToString();
                string countKey = c + "count";

                string ingredientValue = XmlUtils.GetAttributeValue<string>(recipeElement, ingredientKey, null);
                int ingredientCount = XmlUtils.GetAttributeValue(recipeElement, countKey, 1);

                if (!string.IsNullOrEmpty(ingredientValue))
                {
                    string[] array = ingredientValue.Split([':'], StringSplitOptions.None);
                    string craftingId = array[0];
                    int? data = array.Length >= 2 ? new int?(int.Parse(array[1], CultureInfo.InvariantCulture)) : null;

                    // 验证材料是否存在
                    if (BlocksManager.FindBlocksByCraftingId(craftingId).Length == 0)
                    {
                        throw new InvalidOperationException($"Block with craftingId \"{ingredientValue}\" not found.");
                    }

                    if (data.HasValue && (data.Value < 0 || data.Value > 262143))
                    {
                        throw new InvalidOperationException($"Data in recipe ingredient \"{ingredientValue}\" must be between 0 and 0x3FFFF.");
                    }

                    // 生成完整的材料ID（包含数据值）
                    string fullIngredientId = craftingId;
                    if (data.HasValue)
                    {
                        fullIngredientId += ":" + data.Value;
                    }

                    // 添加到材料字典
                    if (recipe.Ingredients.ContainsKey(fullIngredientId))
                    {
                        recipe.Ingredients[fullIngredientId] += ingredientCount;
                    }
                    else
                    {
                        recipe.Ingredients[fullIngredientId] = ingredientCount;
                    }
                }
            }

            return recipe;
        }

        public static CraftingBoxRecipe FindMatchingRecipe(Dictionary<string, int> inputIngredients, int boxLevel)
        {
            if (inputIngredients == null || inputIngredients.Count == 0)
            {
                return null;
            }

            // 检查预定义配方
            foreach (CraftingBoxRecipe recipe in Recipes)
            {
                // 检查箱子等级限制
                if (EnableLevelRestrictions && recipe.RequiredBoxLevel != boxLevel)
                {
                    continue;
                }

                if (MatchRecipe(recipe.Ingredients, inputIngredients))
                {
                    return recipe;
                }
            }

            return null;
        }

        public static bool MatchRecipe(Dictionary<string, int> requiredIngredients, Dictionary<string, int> actualIngredients)
        {
            // 如果材料数量不匹配，直接返回false
            if (requiredIngredients.Count != actualIngredients.Count)
            {
                return false;
            }

            // 检查每个材料是否匹配
            foreach (var kvp in requiredIngredients)
            {
                string ingredientId = kvp.Key;
                int requiredCount = kvp.Value;

                if (!actualIngredients.TryGetValue(ingredientId, out int actualCount) || actualCount != requiredCount)
                {
                    return false;
                }
            }

            return true;
        }
    }
}
//数值处理经理
namespace Game
{
    public static class NumericalProcessingManager
    {
        public static readonly string[] Suffixes = { "", "K", "M", "B", "T", "P", "E", "Z", "Y", "Qc", "No", "Dc" };

        public static string NumericalProcessing(float number)
        {
            if (Math.Abs(number) < 1000)
            {
                return Math.Round(number).ToString();
            }

            int suffixIndex = 0;
            float scaledNumber = Math.Abs(number);

            for (; scaledNumber >= 1000 && suffixIndex < Suffixes.Length - 1; suffixIndex++)
            {
                scaledNumber /= 1000;
            }

            if (number < 0)
            {
                scaledNumber = -scaledNumber;
            }

            return string.Format(number < 0 ? "-{0:F2}{1}" : "{0:F2}{1}",
                                 Math.Abs(scaledNumber),
                                 Suffixes[suffixIndex]);
        }
    }
}
//组件冲刺行为
namespace Game
{
    public class ComponentSprintsBehavior : ComponentBehavior, IUpdateable
    {
        public ComponentLocomotion componentLocomotion;
        public ComponentHealth componentHealth;
        public ComponentChaseBehavior componentChaseBehavior;
        public ComponentBody componentBody;
        public ComponentExtraAttributes componentExtraAttributes;
        public ComponentCreatureModel componentCreatureModel;
        public SubsystemParticles subsystemParticles;
        public SubsystemAudio subsystemAudio;

        public int AttackCount;
        public float m_importanceLevel;
        public float WalkSpeed;

        // 新增变量：记录上一帧是否有目标
        public bool m_previousHasPlayerTarget;

        public Random m_random = new();

        public UpdateOrder UpdateOrder => UpdateOrder.Default;
        public override float ImportanceLevel => m_importanceLevel;

        public virtual void Update(float dt)
        {
            bool hasPlayerTarget = componentChaseBehavior.Target != null;

            // 新增：检测目标状态变化（从无到有）
            if (!m_previousHasPlayerTarget && hasPlayerTarget)
            {
                AttackCount = 0;
                subsystemAudio.PlayRandomSound("Audio/Creatures/Skills/Sprints", 1f, m_random.Float(-0.1f, 0.4f), 0f, 0f);
            }

            // 更新上一帧的目标状态
            m_previousHasPlayerTarget = hasPlayerTarget;

            if (hasPlayerTarget)
            {
                componentLocomotion.WalkSpeed = WalkSpeed;
            }

            if (hasPlayerTarget && componentHealth.Health > 0 && componentLocomotion.StunTime == 0 && AttackCount < 3)
            {
                Vector3 targetPos = componentChaseBehavior.Target.ComponentBody.Position;
                Vector3 attackerPos = componentBody.Position;
                Matrix attackerMatrix = componentBody.Matrix;
                Vector3 toTarget = targetPos - attackerPos;
                toTarget.Y = 0;

                // 计算水平方向向量
                if (toTarget.LengthSquared() < componentExtraAttributes.AttackDistance * componentExtraAttributes.AttackDistance)
                {
                    componentCreatureModel.AttackOrder = true;
                    HitValueParticleSystem particleSystem = new(
                        targetPos + 0.75f * componentBody.Rotation.ToYawPitchRoll(),
                        1f * componentBody.Rotation.ToYawPitchRoll() + componentChaseBehavior.Target.ComponentBody.Velocity,
                        new Color(255, 255, 100),
                        "眩晕"
                    );
                    subsystemParticles.AddParticleSystem(particleSystem);
                    componentChaseBehavior.Target.ComponentLocomotion.StunTime = 5.4f;
                    AttackCount++;
                    componentLocomotion.WalkOrder = Vector2.Zero;
                    return;
                }

                // 获取角色局部坐标轴
                Vector3 forward = Vector3.Normalize(attackerMatrix.Forward * new Vector3(1, 0, 1));
                Vector3 right = Vector3.Normalize(attackerMatrix.Right * new Vector3(1, 0, 1));

                // 计算局部坐标系下的移动方向
                float forwardDot = Vector3.Dot(toTarget, forward);
                float rightDot = Vector3.Dot(toTarget, right);
                Vector2 walkOrder = new Vector2(rightDot, forwardDot);
                float angleDifference = MathF.Acos(MathUtils.Clamp(forwardDot, -1f, 1f));

                // 根据角度差调整移动和转向
                if (angleDifference > MathUtils.DegToRad(30f))
                {
                    componentLocomotion.WalkOrder = new Vector2(0, 0.1f);
                    componentLocomotion.TurnOrder = new Vector2(MathUtils.Sign(rightDot) * 0.8f, 0);
                }
                else
                {
                    componentLocomotion.WalkOrder = walkOrder;
                    componentLocomotion.TurnOrder = new Vector2(rightDot * 0.5f, 0);
                }

                componentLocomotion.WalkSpeed = WalkSpeed * Math.Clamp(walkOrder.Length(), 1f, 3f);

                // 处理垂直移动
                float heightDiff = targetPos.Y - attackerPos.Y;
                if (heightDiff > 1.5f)
                {
                    componentLocomotion.JumpOrder = MathUtils.Clamp(heightDiff / 4f, 0.1f, 1f);
                }
            }
            else
            {
                componentLocomotion.WalkSpeed = WalkSpeed;
            }
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            componentLocomotion = Entity.FindComponent<ComponentLocomotion>();
            componentHealth = Entity.FindComponent<ComponentHealth>();
            componentChaseBehavior = Entity.FindComponent<ComponentChaseBehavior>();
            componentBody = Entity.FindComponent<ComponentBody>();
            componentExtraAttributes = Entity.FindComponent<ComponentExtraAttributes>();
            componentCreatureModel = Entity.FindComponent<ComponentCreatureModel>();
            subsystemParticles = Project.FindSubsystem<SubsystemParticles>();
            subsystemAudio = Project.FindSubsystem<SubsystemAudio>();

            WalkSpeed = componentLocomotion.WalkSpeed;

            // 初始化上一帧目标状态
            m_previousHasPlayerTarget = componentChaseBehavior.Target != null;
        }
    }
}
//组件毒蝎模型动画
namespace Game
{
    /// <summary>
    /// 毒蝎模型动画组件 - 支持6腿+2钳+尾，采用三角步态
    /// </summary>
    public class ComponentScorpionModel : ComponentCreatureModel
    {
        // ---------- 骨骼引用 ----------
        public ModelBone m_bodyBone;
        public ModelBone m_neckBone;          // 可选的颈部骨骼
        public ModelBone m_headBone;
        public ModelBone m_hand1Bone;         // 左钳
        public ModelBone m_hand2Bone;         // 右钳
        public ModelBone[] m_legBones = new ModelBone[6]; // Leg1~Leg6
        public ModelBone m_tailBone;          // 可选尾巴

        // ---------- 动画参数（从配置加载）----------
        public float m_walkAnimationSpeed;     // 步行速度系数
        public float m_crawlAnimationSpeed;    // 爬行速度系数
        public float m_handAngle;              // 钳子摆动幅度
        public float m_frontLegsAngle;         // 前腿幅度
        public float m_midLegsAngle;           // 中腿幅度
        public float m_hindLegsAngle;          // 后腿幅度
        public float m_bodySwingAmplitude;     // 身体左右摆动幅度
        public float m_bodyBobHeight;          // 身体上下起伏高度
        public float m_tailSwingAmplitude;     // 尾巴摆动幅度
        public bool m_hasTailAnimation;        // 是否有尾巴动画

        // ---------- 动画状态 ----------
        public enum Gait { Crawl, Walk }       // 仅保留蝎子实际使用的步态
        public Gait m_gait;
        public float m_feedFactor;             // 喂食动画进度
        public float m_attackFactor;           // 攻击动画进度
        public float m_attackPhase;            // 攻击相位
        public float m_movementPhase;          // 移动相位
        public float[] m_legAngles = new float[6]; // 6条腿的当前角度
        public float m_handAngle1;             // 左钳角度
        public float m_handAngle2;             // 右钳角度
        public float m_bodySwing;              // 当前身体摆动值
        public float m_headAngleY;             // 头部水平摆动
        public float m_tailAngle;              // 尾巴角度

        // ---------- 属性重写 ----------
        public override float AttackPhase { get => m_attackPhase; set => m_attackPhase = value; }
        public override float AttackFactor { get => m_attackFactor; set => m_attackFactor = value; }

        // -----------------------------------------------------------------
        // Update – 每帧更新动画状态（速度、步态、相位、攻击/喂食等）
        // -----------------------------------------------------------------
        public override void Update(float dt)
        {
            // 获取移动速度
            float speed = m_componentCreature.ComponentLocomotion.SlipSpeed ??
                Vector3.Dot(m_componentCreature.ComponentBody.Velocity, m_componentCreature.ComponentBody.Matrix.Forward);
            float walkSpeed = m_componentCreature.ComponentLocomotion.WalkSpeed;

            // 根据速度选择步态并累加相位
            if (MathF.Abs(speed) > 0.1f)
            {
                if (speed > 0.5f * walkSpeed)
                {
                    m_gait = Gait.Walk;
                    m_movementPhase += speed * dt * m_walkAnimationSpeed;
                }
                else
                {
                    m_gait = Gait.Crawl;
                    m_movementPhase += speed * dt * m_crawlAnimationSpeed;
                }
            }
            else
            {
                m_gait = Gait.Crawl;
                m_movementPhase = 0f;
            }

            // ---------- 身体摆动与起伏 ----------
            float targetBodySwing = 0f, targetBob = 0f;
            switch (m_gait)
            {
                case Gait.Crawl:
                    targetBodySwing = m_bodySwingAmplitude * 0.3f * MathF.Sin(MathF.PI * 2f * m_movementPhase);
                    targetBob = m_bodyBobHeight * 0.2f * MathF.Sin(MathF.PI * 4f * m_movementPhase);
                    break;
                case Gait.Walk:
                    targetBodySwing = m_bodySwingAmplitude * 0.6f * MathF.Sin(MathF.PI * 2f * m_movementPhase);
                    targetBob = m_bodyBobHeight * 0.8f * MathF.Sin(MathF.PI * 4f * m_movementPhase);
                    break;
            }
            float smooth = MathUtils.Min(12f * dt, 1f);
            m_bodySwing += smooth * (targetBodySwing - m_bodySwing);
            Bob += smooth * (targetBob - Bob);

            // ---------- 尾巴动画 ----------
            if (m_hasTailAnimation && m_tailBone != null)
            {
                float targetTail = m_tailSwingAmplitude * MathF.Sin(MathF.PI * 2f * m_movementPhase * 0.5f);
                m_tailAngle += smooth * (targetTail - m_tailAngle);
            }

            // ---------- 脚步声（每步触发一次）----------
            if (m_movementPhase > MathF.Floor(m_movementPhase) && m_movementPhase - dt <= MathF.Floor(m_movementPhase))
                m_componentCreature.ComponentCreatureSounds.PlayFootstepSound(1f);

            // ---------- 喂食动画 ----------
            m_feedFactor = FeedOrder ?
                MathUtils.Min(m_feedFactor + 2f * dt, 1f) :
                MathUtils.Max(m_feedFactor - 2f * dt, 0f);

            // ---------- 攻击动画 ----------
            IsAttackHitMoment = false;
            if (AttackOrder)
            {
                m_attackFactor = MathUtils.Min(m_attackFactor + 4f * dt, 1f);
                float oldPhase = m_attackPhase;
                m_attackPhase = MathUtils.Remainder(m_attackPhase + dt * 3f, 1f);
                if (oldPhase < 0.3f && m_attackPhase >= 0.3f) IsAttackHitMoment = true;
            }
            else
            {
                m_attackFactor = MathUtils.Max(m_attackFactor - 4f * dt, 0f);
                if (m_attackPhase > 0f) m_attackPhase = MathUtils.Max(m_attackPhase - dt * 2f, 0f);
            }

            FeedOrder = false;
            AttackOrder = false;
            base.Update(dt);
        }

        // -----------------------------------------------------------------
        // AnimateCreature – 根据生命状态选择动画分支
        // -----------------------------------------------------------------
        public override void AnimateCreature()
        {
            Vector3 pos = m_componentCreature.ComponentBody.Position;
            Vector3 rot = m_componentCreature.ComponentBody.Rotation.ToYawPitchRoll();
            if (m_componentCreature.ComponentHealth.Health > 0f)
                AnimateAliveCreature(pos, rot);
            else
                AnimateDeadCreature(pos, rot);
        }

        // -----------------------------------------------------------------
        // AnimateAliveCreature – 活体动画（腿、钳、头、尾）
        // -----------------------------------------------------------------
        public void AnimateAliveCreature(Vector3 position, Vector3 rotation)
        {
            // ---------- 腿/钳目标角度计算 ----------
            float[] targetLegs = new float[6];
            float targetHand1 = 0f, targetHand2 = 0f, targetHeadY = 0f, targetTail = 0f;

            if (m_movementPhase != 0f && (m_componentCreature.ComponentBody.StandingOnValue.HasValue || m_componentCreature.ComponentBody.ImmersionFactor > 0f))
            {
                float phase = m_movementPhase;
                switch (m_gait)
                {
                    case Gait.Crawl:
                        // 慢速爬行：左右交替，所有腿小幅度摆动
                        for (int i = 0; i < 6; i++)
                        {
                            float offset = (i % 2 == 0) ? 0f : 0.5f;
                            targetLegs[i] = GetLegAmplitude(i) * MathF.Sin(MathF.PI * 2f * (phase + offset));
                        }
                        targetHand1 = m_handAngle * 0.3f * MathF.Sin(MathF.PI * 2f * (phase + 0.25f));
                        targetHand2 = m_handAngle * 0.3f * MathF.Sin(MathF.PI * 2f * (phase + 0.75f));
                        targetHeadY = MathUtils.DegToRad(2f) * MathF.Sin(MathF.PI * 4f * phase);
                        targetTail = m_tailSwingAmplitude * 0.3f * MathF.Sin(MathF.PI * 2f * phase * 0.5f);
                        break;

                    case Gait.Walk:
                        // 三角步态：组1(Leg1,Leg4,Leg5) 组2(Leg2,Leg3,Leg6)
                        targetLegs[0] = GetLegAmplitude(0) * MathF.Sin(MathF.PI * 2f * (phase + 0.0f)); // Leg1
                        targetLegs[3] = GetLegAmplitude(3) * MathF.Sin(MathF.PI * 2f * (phase + 0.0f)); // Leg4
                        targetLegs[4] = GetLegAmplitude(4) * MathF.Sin(MathF.PI * 2f * (phase + 0.0f)); // Leg5
                        targetLegs[1] = GetLegAmplitude(1) * MathF.Sin(MathF.PI * 2f * (phase + 0.5f)); // Leg2
                        targetLegs[2] = GetLegAmplitude(2) * MathF.Sin(MathF.PI * 2f * (phase + 0.5f)); // Leg3
                        targetLegs[5] = GetLegAmplitude(5) * MathF.Sin(MathF.PI * 2f * (phase + 0.5f)); // Leg6
                        targetHand1 = m_handAngle * 0.5f * MathF.Sin(MathF.PI * 2f * (phase + 0.0f));
                        targetHand2 = m_handAngle * 0.5f * MathF.Sin(MathF.PI * 2f * (phase + 0.5f));
                        targetHeadY = MathUtils.DegToRad(3f) * MathF.Sin(MathF.PI * 4f * phase);
                        targetTail = m_tailSwingAmplitude * 0.6f * MathF.Sin(MathF.PI * 2f * phase * 0.5f);
                        break;
                }
            }

            // ---------- 平滑插值 ----------
            float smooth = MathUtils.Min(12f * m_subsystemTime.GameTimeDelta, 1f);
            for (int i = 0; i < 6; i++) m_legAngles[i] += smooth * (targetLegs[i] - m_legAngles[i]);
            m_handAngle1 += smooth * (targetHand1 - m_handAngle1);
            m_handAngle2 += smooth * (targetHand2 - m_handAngle2);
            m_headAngleY += smooth * (targetHeadY - m_headAngleY);
            if (m_hasTailAnimation) m_tailAngle += smooth * (targetTail - m_tailAngle);

            // ---------- 头部/颈部控制（注视方向）----------
            Vector2 look = m_componentCreature.ComponentLocomotion.LookAngles;
            look.Y += m_headAngleY;
            look.X = Math.Clamp(look.X, -MathUtils.DegToRad(65f), MathUtils.DegToRad(65f));
            look.Y = Math.Clamp(look.Y, -MathUtils.DegToRad(55f), MathUtils.DegToRad(55f));

            Vector2 neckLook = Vector2.Zero;
            if (m_neckBone != null)
            {
                neckLook = 0.6f * look;
                look = 0.4f * look;
            }

            // ---------- 喂食动画（低头、钳微合）----------
            if (m_feedFactor > 0f)
            {
                float feedHead = -MathUtils.DegToRad(25f + 45f * SimplexNoise.OctavedNoise((float)m_subsystemTime.GameTime, 3f, 2, 2f, 0.75f));
                look = Vector2.Lerp(look, new Vector2(0f, feedHead), m_feedFactor);
                float feedHand = -0.2f * m_handAngle * m_feedFactor;
                m_handAngle1 += smooth * (feedHand - m_handAngle1);
                m_handAngle2 += smooth * (feedHand - m_handAngle2);
            }

            // ---------- 攻击动画（头下压、钳夹击）----------
            if (m_attackFactor > 0f)
            {
                float attackHead = -MathUtils.DegToRad(40f) * MathF.Sin(MathF.PI * 2f * MathUtils.Sigmoid(m_attackPhase, 4f));
                look = Vector2.Lerp(look, new Vector2(0f, attackHead), m_attackFactor);
                float attackHand = m_handAngle * 0.8f * MathF.Sin(MathF.PI * 2f * m_attackPhase * 2f);
                m_handAngle1 += smooth * (attackHand - m_handAngle1);
                m_handAngle2 += smooth * (-attackHand - m_handAngle2); // 钳子对称夹击
            }

            // ---------- 应用骨骼变换 ----------
            Matrix bodyMat = Matrix.CreateRotationY(rotation.X + m_bodySwing)
                           * Matrix.CreateTranslation(position.X, position.Y + Bob, position.Z);
            SetBoneTransform(m_bodyBone.Index, bodyMat);

            SetBoneTransform(m_headBone.Index, Matrix.CreateRotationX(look.Y) * Matrix.CreateRotationZ(-look.X));
            if (m_neckBone != null)
                SetBoneTransform(m_neckBone.Index, Matrix.CreateRotationX(neckLook.Y) * Matrix.CreateRotationZ(-neckLook.X));

            // 钳子
            SetBoneTransform(m_hand1Bone.Index, Matrix.CreateRotationX(m_handAngle1));
            SetBoneTransform(m_hand2Bone.Index, Matrix.CreateRotationX(m_handAngle2));

            // 六条腿
            for (int i = 0; i < 6; i++)
                if (m_legBones[i] != null)
                    SetBoneTransform(m_legBones[i].Index, Matrix.CreateRotationX(m_legAngles[i]));

            // 尾巴
            if (m_hasTailAnimation && m_tailBone != null)
                SetBoneTransform(m_tailBone.Index, Matrix.CreateRotationY(m_tailAngle));
        }

        // 辅助：根据腿索引获取对应幅度（内联，无额外方法）
        public float GetLegAmplitude(int idx)
        {
            if (idx < 2) return m_frontLegsAngle;  // Leg1,Leg2
            if (idx < 4) return m_midLegsAngle;    // Leg3,Leg4
            return m_hindLegsAngle;                // Leg5,Leg6
        }

        // -----------------------------------------------------------------
        // AnimateDeadCreature – 死亡动画（侧倒、肢体松弛）
        // -----------------------------------------------------------------
        public void AnimateDeadCreature(Vector3 position, Vector3 rotation)
        {
            float deathFactor = 1f - DeathPhase;
            float side = Vector3.Dot(m_componentFrame.Matrix.Right, DeathCauseOffset) > 0f ? 1 : -1;
            float bodyHeight = m_componentCreature.ComponentBody.BoundingBox.Max.Y - m_componentCreature.ComponentBody.BoundingBox.Min.Y;

            Matrix bodyMat = Matrix.CreateTranslation(-0.5f * bodyHeight * Vector3.UnitY * DeathPhase)
                           * Matrix.CreateFromYawPitchRoll(rotation.X, 0f, MathF.PI / 2f * DeathPhase * side)
                           * Matrix.CreateTranslation(0.2f * bodyHeight * Vector3.UnitY * DeathPhase)
                           * Matrix.CreateTranslation(position);
            SetBoneTransform(m_bodyBone.Index, bodyMat);

            SetBoneTransform(m_headBone.Index, Matrix.CreateRotationX(MathUtils.DegToRad(50f) * DeathPhase));
            if (m_neckBone != null) SetBoneTransform(m_neckBone.Index, Matrix.Identity);

            // 钳子和腿逐渐松弛
            SetBoneTransform(m_hand1Bone.Index, Matrix.CreateRotationX(m_handAngle1 * deathFactor));
            SetBoneTransform(m_hand2Bone.Index, Matrix.CreateRotationX(m_handAngle2 * deathFactor));
            for (int i = 0; i < 6; i++)
                if (m_legBones[i] != null)
                    SetBoneTransform(m_legBones[i].Index, Matrix.CreateRotationX(m_legAngles[i] * deathFactor));
        }

        // -----------------------------------------------------------------
        // Load – 从配置字典加载参数
        // -----------------------------------------------------------------
        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            m_walkAnimationSpeed = valuesDictionary.GetValue<float>("WalkAnimationSpeed");
            m_crawlAnimationSpeed = valuesDictionary.GetValue<float>("CrawlAnimationSpeed");
            m_handAngle = valuesDictionary.GetValue<float>("HandAngle");
            m_frontLegsAngle = valuesDictionary.GetValue<float>("FrontLegsAngle");
            m_midLegsAngle = valuesDictionary.GetValue<float>("MidLegsAngle");
            m_hindLegsAngle = valuesDictionary.GetValue<float>("HindLegsAngle");
            m_bodySwingAmplitude = valuesDictionary.GetValue<float>("BodySwingAmplitude");
            m_bodyBobHeight = valuesDictionary.GetValue<float>("BodyBobHeight");
            m_tailSwingAmplitude = valuesDictionary.GetValue<float>("TailSwingAmplitude");
            m_hasTailAnimation = valuesDictionary.GetValue<bool>("HasTailAnimation");
        }

        // -----------------------------------------------------------------
        // SetModel – 绑定模型并查找骨骼
        // -----------------------------------------------------------------
        public override void SetModel(Model model)
        {
            base.SetModel(model);
            if (IsSet) return;

            if (Model != null)
            {
                m_bodyBone = Model.FindBone("Body");
                m_neckBone = Model.FindBone("Neck", false);
                m_headBone = Model.FindBone("Head");
                m_hand1Bone = Model.FindBone("Hand1");
                m_hand2Bone = Model.FindBone("Hand2");
                m_legBones[0] = Model.FindBone("Leg1");
                m_legBones[1] = Model.FindBone("Leg2");
                m_legBones[2] = Model.FindBone("Leg3");
                m_legBones[3] = Model.FindBone("Leg4");
                m_legBones[4] = Model.FindBone("Leg5");
                m_legBones[5] = Model.FindBone("Leg6");
                m_tailBone = Model.FindBone("Tail", false);
            }
            else
            {
                m_bodyBone = m_neckBone = m_headBone = null;
                m_hand1Bone = m_hand2Bone = null;
                for (int i = 0; i < 6; i++) m_legBones[i] = null;
                m_tailBone = null;
            }
        }
    }
}
