//子系统可交互方块行为
namespace Game
{
    public class SubsystemNewInteroperableCubeBlockBehavior : SubsystemEntityBlockBehavior, IUpdateable
    {
        public static readonly int[] _handledBlocks = new int[1] { BlocksManager.GetBlockIndex<NewInteroperableCube>() };

        public SubsystemItemsScanner m_subsystemItemsScanner;
        public SubsystemTime subsystemTime;

        public Dictionary<int, MechanicalDollsItemsData> m_itemsData = new Dictionary<int, MechanicalDollsItemsData>();
        public Dictionary<Point3, MechanicalDollsItemsData> m_blocksData = new Dictionary<Point3, MechanicalDollsItemsData>();
        public Dictionary<MovingBlock, MechanicalDollsItemsData> m_movingBlocksData = new Dictionary<MovingBlock, MechanicalDollsItemsData>();

        public DateTime _now;
        public TimeSpan _accumulatedTime;

        public override int[] HandledBlocks => _handledBlocks;
        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public override void Load(ValuesDictionary valuesDictionary)
        {
            base.Load(valuesDictionary);

            m_subsystemItemsScanner = Project.FindSubsystem<SubsystemItemsScanner>(true);
            subsystemTime = Project.FindSubsystem<SubsystemTime>(true);

            _now = valuesDictionary.GetValue<DateTime>("Now", DateTime.Now);
            TimeSpan offlineTime = DateTime.Now - _now;
            int offlineMinutes = (int)offlineTime.TotalMinutes;
            _accumulatedTime = offlineTime - TimeSpan.FromMinutes(offlineMinutes);

            if (valuesDictionary.TryGetValue("Blocks", out ValuesDictionary blocksDict))
            {
                foreach (var pair in blocksDict)
                {
                    var data = new MechanicalDollsItemsData();
                    data.LoadString((string)pair.Value);

                    if (offlineMinutes > 0)
                    {
                        int blockType = NewComponents.GetType(CraftingRecipesManager.DecodeResult(data.Items[3].ClassName));
                        if (AccessNewComponentsManager.Get(blockType).RealTimeLimit > 0)
                        {
                            data.Items2[0].CurrentCapacity += offlineMinutes;
                            break;
                        }
                    }

                    MovingBlock movingBlock = MovingBlock.LoadFromString(Project, pair.Key, out Exception ex);
                    if (ex == null)
                        m_movingBlocksData[movingBlock] = data;
                    else
                    {
                        Point3 point = HumanReadableConverter.ConvertFromString<Point3>(pair.Key);
                        m_blocksData[point] = data;
                    }
                }
            }

            if (valuesDictionary.TryGetValue("Items", out ValuesDictionary itemsDict))
            {
                foreach (var pair in itemsDict)
                {
                    int id = HumanReadableConverter.ConvertFromString<int>(pair.Key);
                    var data = new MechanicalDollsItemsData();
                    data.LoadString((string)pair.Value);
                    m_itemsData[id] = data;
                }
            }

            m_subsystemItemsScanner.ItemsScanned += GarbageCollectItems;
        }

        public override void Save(ValuesDictionary valuesDictionary)
        {
            base.Save(valuesDictionary);

            ValuesDictionary blocksDict = new ValuesDictionary();
            foreach (var kv in m_blocksData)
                blocksDict.SetValue(HumanReadableConverter.ConvertToString(kv.Key), kv.Value.SaveString());
            foreach (var kv in m_movingBlocksData)
                blocksDict.SetValue(kv.Key.ToString(), kv.Value.SaveString());
            valuesDictionary.SetValue("Blocks", blocksDict);

            ValuesDictionary itemsDict = new ValuesDictionary();
            foreach (var kv in m_itemsData)
                itemsDict.SetValue(HumanReadableConverter.ConvertToString(kv.Key), kv.Value.SaveString());
            valuesDictionary.SetValue("Items", itemsDict);

            valuesDictionary.SetValue("Now", DateTime.Now);
        }

        public MechanicalDollsItemsData GetBlockData(Point3 point)
        {
            m_blocksData.TryGetValue(point, out MechanicalDollsItemsData data);
            return data;
        }

        public void SetBlockData(Point3 point, MechanicalDollsItemsData data)
        {
            if (data != null)
                m_blocksData[point] = data;
            else
                m_blocksData.Remove(point);
        }

        public MechanicalDollsItemsData GetBlockData(MovingBlock movingBlock)
        {
            m_movingBlocksData.TryGetValue(movingBlock, out MechanicalDollsItemsData data);
            return data;
        }

        public void SetBlockData(MovingBlock movingBlock, MechanicalDollsItemsData data)
        {
            if (data != null)
                m_movingBlocksData[movingBlock] = data;
            else
                m_movingBlocksData.Remove(movingBlock);
        }

        public MechanicalDollsItemsData GetItemData(int id)
        {
            m_itemsData.TryGetValue(id, out MechanicalDollsItemsData data);
            return data;
        }

        public int StoreItemDataAtUniqueId(MechanicalDollsItemsData data)
        {
            int id = FindFreeItemId();
            m_itemsData[id] = (MechanicalDollsItemsData)data.Copy();
            return id;
        }

        public int FindFreeItemId()
        {
            for (int i = 1; i < 1000; i++)
                if (!m_itemsData.ContainsKey(i))
                    return i;
            return 0;
        }

        public void GarbageCollectItems(ReadOnlyList<ScannedItemData> allExistingItems)
        {
            HashSet<int> usedIds = new HashSet<int>();
            foreach (var item in allExistingItems)
            {
                if (Terrain.ExtractContents(item.Value) == BlocksManager.GetBlockIndex<NewInteroperableCube>())
                    usedIds.Add(Terrain.ExtractData(item.Value));
            }

            List<int> toRemove = new List<int>();
            foreach (int id in m_itemsData.Keys)
                if (!usedIds.Contains(id))
                    toRemove.Add(id);

            foreach (int id in toRemove)
                m_itemsData.Remove(id);
        }

        public override void OnItemPlaced(int x, int y, int z, ref BlockPlacementData placementData, int itemValue)
        {
            base.OnItemPlaced(x, y, z, ref placementData, itemValue);
            int id = Terrain.ExtractData(itemValue);
            MechanicalDollsItemsData itemData = GetItemData(id);
            if (itemData != null)
                SetBlockData(new Point3(x, y, z), (MechanicalDollsItemsData)itemData.Copy());
        }

        public override void OnItemHarvested(int x, int y, int z, int blockValue, ref BlockDropValue dropValue, ref int newBlockValue)
        {
            base.OnItemHarvested(x, y, z, blockValue, ref dropValue, ref newBlockValue);
            MechanicalDollsItemsData blockData = GetBlockData(new Point3(x, y, z));
        }

        public override void OnBlockAdded(int value, int oldValue, int x, int y, int z)
        {
            m_databaseObject = Project.GameDatabase.Database.FindDatabaseObject(AccessNewInteroperableCubeManager.Get(NewInteroperableCube.GetType(value)).ModelComponents, Project.GameDatabase.EntityTemplateType, true);
            base.OnBlockAdded(value, oldValue, x, y, z);
        }

        public override void OnBlockRemoved(int value, int newValue, int x, int y, int z)
        {
            m_blocksData.Remove(new Point3(x, y, z));
            base.OnBlockRemoved(value, newValue, x, y, z);
        }

        public override void OnBlockStartMoving(int value, int newValue, int x, int y, int z, MovingBlock movingBlock)
        {
            Point3 point = new Point3(x, y, z);
            if (m_blocksData.TryGetValue(point, out MechanicalDollsItemsData data))
            {
                m_blocksData.Remove(point);
                m_movingBlocksData[movingBlock] = data;
            }
            base.OnBlockStartMoving(value, newValue, x, y, z, movingBlock);
        }

        public override void OnBlockStopMoving(int value, int oldValue, int x, int y, int z, MovingBlock movingBlock)
        {
            if (m_movingBlocksData.TryGetValue(movingBlock, out MechanicalDollsItemsData data))
            {
                m_movingBlocksData.Remove(movingBlock);
                m_blocksData[new Point3(x, y, z)] = data;
            }
            base.OnBlockStopMoving(value, oldValue, x, y, z, movingBlock);
        }

        public override bool InteractBlockEntity(ComponentBlockEntity blockEntity, ComponentMiner componentMiner)
        {
            if (blockEntity != null && componentMiner.ComponentPlayer != null)
            {
                if (NewInteroperableCube.GetType(blockEntity.BlockValue) == 0)
                {
                    Point3 coordinates = blockEntity.Coordinates;
                    MechanicalDollsItemsData data = GetBlockData(coordinates) ?? new MechanicalDollsItemsData();
                    if (!componentMiner.ComponentPlayer.PlayerStats.ValuesDictionaryForMods.ContainsKey("ComponentManufacturing0"))
                    {
                        for (int a = 0; a < 17; a++)
                        {
                            componentMiner.ComponentPlayer.PlayerStats.ValuesDictionaryForMods["ComponentManufacturing" + a] = false;
                        }
                        componentMiner.ComponentPlayer.PlayerStats.ValuesDictionaryForMods["ComponentManufacturing0"] = true;
                        componentMiner.ComponentPlayer.PlayerStats.ValuesDictionaryForMods["ComponentManufacturing1"] = true;
                        componentMiner.ComponentPlayer.PlayerStats.ValuesDictionaryForMods["ComponentManufacturing8"] = true;
                        componentMiner.ComponentPlayer.PlayerStats.ValuesDictionaryForMods["ComponentManufacturing12"] = true;
                    }

                    componentMiner.ComponentPlayer.ComponentGui.ModalPanelWidget = new MechanicalDollsWidget(componentMiner.ComponentPlayer, data);
                    AudioManager.PlaySound("Audio/UI/ButtonClick", 1f, 0f, 0f);

                    SetBlockData(coordinates, data);
                    return true;
                }
                if (NewInteroperableCube.GetType(blockEntity.BlockValue) == 1)
                {
                    ComponentMechaProductionDesk componentMechaProductionDesk = blockEntity.Entity.FindComponent<ComponentMechaProductionDesk>(true);
                    componentMiner.ComponentPlayer.ComponentGui.ModalPanelWidget = new MechaProductionDeskWidget(componentMiner.ComponentPlayer, componentMechaProductionDesk);
                    AudioManager.PlaySound("Audio/UI/ButtonClick", 1f, 0f, 0f);
                    return true;
                }
                if (NewInteroperableCube.GetType(blockEntity.BlockValue) == 2)
                {
                    componentMiner.ComponentPlayer.ComponentGui.ModalPanelWidget = new MysteryBoxWidget(componentMiner.ComponentPlayer, blockEntity.BlockValue);
                    AudioManager.PlaySound("Audio/UI/ButtonClick", 1f, 0f, 0f);
                    return true;
                }
            }
            return base.InteractBlockEntity(blockEntity, componentMiner);
        }

        public override void OnEntityAdded(Entity entity)
        {
            base.OnEntityAdded(entity);
        }

        public void CurrentCapacityAdd(int amount, int type)
        {
            foreach (var kv in m_blocksData)
            {
                var data = kv.Value;
                int blockType = NewComponents.GetType(CraftingRecipesManager.DecodeResult(data.Items[3].ClassName));
                bool shouldAdd = (type == 0 && AccessNewComponentsManager.Get(blockType).MaximumNumberOfFishingTrips > 0) ||
                                 (type == 1 && AccessNewComponentsManager.Get(blockType).MaximumNumberOfBattles > 0) ||
                                 (type == 2 && AccessNewComponentsManager.Get(blockType).MaximumNumberOfProductions > 0);
                if (shouldAdd)
                {
                    data.Items2[0].CurrentCapacity += amount;
                    break;
                }
            }
        }

        public virtual void Update(float dt)
        {
            DateTime now = DateTime.Now;
            _accumulatedTime += now - _now;

            // 容量转换（每帧最多转换一次）
            foreach (var kv in m_blocksData)
            {
                var item2 = kv.Value.Items2[0];
                if (item2.CurrentCapacity >= item2.MaximumCapacity)
                {
                    if (item2.TheCurrentAmountOfStorage < item2.MaximumAmountOfStorage)
                    {
                        item2.CurrentCapacity -= item2.MaximumCapacity;
                        item2.TheCurrentAmountOfStorage++;
                    }
                    else
                    {
                        item2.CurrentCapacity = item2.MaximumCapacity;
                    }
                }
            }

            // 现实时间累积容量
            if (_accumulatedTime.TotalMinutes >= 1.0)
            {
                int minutes = (int)_accumulatedTime.TotalMinutes;

                foreach (var kv in m_blocksData)
                {
                    var data = kv.Value;
                    int blockType = NewComponents.GetType(CraftingRecipesManager.DecodeResult(data.Items[3].ClassName));
                    if (AccessNewComponentsManager.Get(blockType).RealTimeLimit > 0)
                    {
                        data.Items2[0].CurrentCapacity += minutes;
                        break;
                    }
                }

                _accumulatedTime -= TimeSpan.FromMinutes(minutes);
            }

            // 游戏时间事件（每50秒）
            if (subsystemTime.PeriodicGameTimeEvent(50.0, 0.0))
            {
                foreach (var kv in m_blocksData)
                {
                    var data = kv.Value;
                    int blockType = NewComponents.GetType(CraftingRecipesManager.DecodeResult(data.Items[3].ClassName));
                    if (AccessNewComponentsManager.Get(blockType).MaximumSurvivalTime > 0)
                    {
                        data.Items2[0].CurrentCapacity++;
                        break;
                    }
                }
            }

            _now = now;
        }
    }
}
//机关假人信息大全
namespace Game
{
    public class MechanicalDollsItemsData : IEditableItemData
    {
        public class ItemInfo
        {
            public string ClassName;
            public int CurrentExp;
            public int MaxExp;
            public int Level;
        }

        public class ItemInfo2
        {
            public int CurrentCapacity;
            public int MaximumCapacity;
            public int TheCurrentAmountOfStorage;
            public int MaximumAmountOfStorage;
        }

        public ItemInfo[] Items = new ItemInfo[4]; // 默认初始化，可在构造函数中创建空对象
        public ItemInfo2[] Items2 = new ItemInfo2[1];

        public MechanicalDollsItemsData()
        {
            for (int i = 0; i < 4; i++)
            {
                Items[i] = new ItemInfo();
                Items[i].Level = 1;
                Items[i].MaxExp = Items[i].Level;
            }
            Items[0].ClassName = "NewComponents:0";
            Items[1].ClassName = "NewComponents:1";
            Items[2].ClassName = "NewComponents:8";
            Items[3].ClassName = "NewComponents:12";
            Items2[0] = new ItemInfo2();
            Items2[0].CurrentCapacity = 0;
            Items2[0].MaximumCapacity = 240;
            Items2[0].TheCurrentAmountOfStorage = 0;
            Items2[0].MaximumAmountOfStorage = 1;
        }

        public IEditableItemData Copy()
        {
            MechanicalDollsItemsData copy = new MechanicalDollsItemsData();
            for (int i = 0; i < 4; i++)
            {
                copy.Items[i].ClassName = this.Items[i].ClassName;
                copy.Items[i].CurrentExp = this.Items[i].CurrentExp;
                copy.Items[i].MaxExp = this.Items[i].MaxExp;
                copy.Items[i].Level = this.Items[i].Level;
            }
            copy.Items2[0].CurrentCapacity = this.Items2[0].CurrentCapacity;
            copy.Items2[0].MaximumCapacity = this.Items2[0].MaximumCapacity;
            copy.Items2[0].TheCurrentAmountOfStorage = this.Items2[0].TheCurrentAmountOfStorage;
            copy.Items2[0].MaximumAmountOfStorage = this.Items2[0].MaximumAmountOfStorage;
            return copy;
        }

        public void LoadString(string data)
        {
            // 格式：每个物品的字段用逗号分隔，四个物品用分号分隔
            // 例如："战士,100,200,5;法师,80,150,4;牧师,60,120,3;盗贼,90,180,4"
            string[] itemStrings = data.Split(';', StringSplitOptions.RemoveEmptyEntries);
            for (int i = 0; i < Math.Min(5, itemStrings.Length); i++)
            {
                string[] fields = itemStrings[i].Split(',');
                if (i != 4)
                {
                    if (fields.Length >= 4)
                    {
                        Items[i].ClassName = fields[0];
                        int.TryParse(fields[1], out Items[i].CurrentExp);
                        int.TryParse(fields[2], out Items[i].MaxExp);
                        int.TryParse(fields[3], out Items[i].Level);
                    }
                }
                else
                {
                    if (fields.Length >= 4)
                    {
                        int.TryParse(fields[0], out Items2[0].CurrentCapacity);
                        int.TryParse(fields[1], out Items2[0].MaximumCapacity);
                        int.TryParse(fields[2], out Items2[0].TheCurrentAmountOfStorage);
                        int.TryParse(fields[3], out Items2[0].MaximumAmountOfStorage);
                    }
                }
            }
        }

        public string SaveString()
        {
            StringBuilder sb = new();
            for (int i = 0; i < 5; i++)
            {
                if (i > 0) sb.Append(';');
                if (i != 4)
                {
                    sb.Append(Items[i].ClassName ?? "");
                    sb.Append(',');
                    sb.Append(Items[i].CurrentExp);
                    sb.Append(',');
                    sb.Append(Items[i].MaxExp);
                    sb.Append(',');
                    sb.Append(Items[i].Level);
                }
                else
                {
                    sb.Append(Items2[0].CurrentCapacity);
                    sb.Append(',');
                    sb.Append(Items2[0].MaximumCapacity);
                    sb.Append(',');
                    sb.Append(Items2[0].TheCurrentAmountOfStorage);
                    sb.Append(',');
                    sb.Append(Items2[0].MaximumAmountOfStorage);
                }
            }
            return sb.ToString();
        }
    }
}
//机关假人界面
namespace Game
{
    public class MechanicalDollsWidget : CanvasWidget
    {
        public ComponentPlayer m_componentPlayer;
        public BlockIconWidget icon;
        public ValueBarWidget collectingBar;
        public LabelWidget collectingLabel;
        public BitmapButtonWidget boxButton;
        public LabelWidget theCurrentAmountOfStorageLabel;
        public LabelWidget fullLabel;
        public MechanicalDollsItemsData m_mechanicalDollsItemsData;

        // 使用数组替代字典，提高访问效率
        public struct ButtonGroup
        {
            public BlockIconWidget Icon;
            public BitmapButtonWidget Button;
            public LabelWidget NameLabel;
            public LabelWidget LevelLabel;
        }
        public ButtonGroup[] buttonGroups;

        public MechanicalDollsWidget(ComponentPlayer componentPlayer, MechanicalDollsItemsData mechanicalDollsItemsData)
        {
            m_componentPlayer = componentPlayer;
            m_mechanicalDollsItemsData = mechanicalDollsItemsData;
            XElement node = ContentManager.Get<XElement>("Widgets/MechanicalDollsWidget");
            LoadContents(this, node);
            icon = Children.Find<BlockIconWidget>("Icon");
            collectingBar = Children.Find<ValueBarWidget>("CollectingBar");
            collectingLabel = Children.Find<LabelWidget>("CollectingLabel");
            boxButton = Children.Find<BitmapButtonWidget>("BoxButton");
            theCurrentAmountOfStorageLabel = Children.Find<LabelWidget>("TheCurrentAmountOfStorageLabel");
            fullLabel = Children.Find<LabelWidget>("FullLabel");

            // 初始化按钮组数组
            buttonGroups = new ButtonGroup[4];
            for (int i = 0; i < 4; i++)
            {
                int index = i + 1; // 控件名称后缀从1开始
                buttonGroups[i] = new ButtonGroup
                {
                    Icon = Children.Find<BlockIconWidget>("Icon" + index),
                    Button = Children.Find<BitmapButtonWidget>("Button" + index),
                    NameLabel = Children.Find<LabelWidget>("NameLabel" + index),
                    LevelLabel = Children.Find<LabelWidget>("LevelLabel" + index)
                };
            }
        }

        public override void Update()
        {
            // 缓存常用对象
            var items = m_mechanicalDollsItemsData.Items;
            var items2 = m_mechanicalDollsItemsData.Items2;
            var firstItem = items2[0];

            // 更新主图标
            icon.Value = Terrain.MakeBlockValue(NewInteroperableCube.Index, 0, 0);

            // 更新收集进度
            collectingBar.Value = (float)firstItem.CurrentCapacity / firstItem.MaximumCapacity;
            collectingLabel.Text = NumericalProcessingManager.NumericalProcessing(firstItem.CurrentCapacity) + "/" +
                                    NumericalProcessingManager.NumericalProcessing(firstItem.MaximumCapacity);

            // 更新存储量显示
            theCurrentAmountOfStorageLabel.Text = firstItem.TheCurrentAmountOfStorage == 0
                ? ""
                : NumericalProcessingManager.NumericalProcessing(firstItem.TheCurrentAmountOfStorage);

            // 更新“满”标签
            fullLabel.Text = firstItem.TheCurrentAmountOfStorage >= firstItem.MaximumAmountOfStorage ? "满" : "";

            // 计算最大容量和最大存储量（基于组件等级）
            int num = 0;  // 用于 Items2[0].MaximumCapacity
            int num2 = 0; // 用于 Items2[0].MaximumAmountOfStorage

            // 获取需要检查的两个组件类名
            string classNameForNum = items[3].ClassName;   // 影响容量
            string classNameForNum2 = items[2].ClassName;  // 影响存储上限

            int blockId = NewComponents.GetType(CraftingRecipesManager.DecodeResult(classNameForNum));
            // 计算最大容量（取组件对应的最大值减去等级折扣）
            int baseValue = 0;
            if (AccessNewComponentsManager.Get(blockId).RealTimeLimit > 0)
                baseValue = AccessNewComponentsManager.Get(blockId).RealTimeLimit;
            else if (AccessNewComponentsManager.Get(blockId).MaximumSurvivalTime > 0)
                baseValue = AccessNewComponentsManager.Get(blockId).MaximumSurvivalTime;
            else if (AccessNewComponentsManager.Get(blockId).MaximumNumberOfFishingTrips > 0)
                baseValue = AccessNewComponentsManager.Get(blockId).MaximumNumberOfFishingTrips;
            else if (AccessNewComponentsManager.Get(blockId).MaximumNumberOfBattles > 0)
                baseValue = AccessNewComponentsManager.Get(blockId).MaximumNumberOfBattles;
            else if (AccessNewComponentsManager.Get(blockId).MaximumNumberOfProductions > 0)
                baseValue = AccessNewComponentsManager.Get(blockId).MaximumNumberOfProductions;

            if (baseValue > 0)
            {
                int level = items[3].Level;
                float discount = Math.Min((level - 1) * baseValue * 0.05f, baseValue * 0.9f);
                num = baseValue - (int)discount;
            }

            int blockId2 = NewComponents.GetType(CraftingRecipesManager.DecodeResult(classNameForNum2));
            if (AccessNewComponentsManager.Get(blockId2).MaximumCapacity > 0)
            {
                num2 = AccessNewComponentsManager.Get(blockId2).MaximumCapacity + items[2].Level - 1;
            }

            // 更新数据
            firstItem.MaximumCapacity = num;
            firstItem.MaximumAmountOfStorage = num2;

            // 更新四个按钮组
            for (int i = 0; i < buttonGroups.Length; i++)
            {
                var group = buttonGroups[i];
                var item = items[i];
                int blockValue = CraftingRecipesManager.DecodeResult(item.ClassName);
                group.Icon.Value = blockValue;

                string displayName = BlocksManager.Blocks[Terrain.ExtractContents(blockValue)].GetDisplayName(null, blockValue);
                group.NameLabel.Text = displayName;

                group.LevelLabel.Text = "等级：" + NumericalProcessingManager.NumericalProcessing(item.Level);

                if (group.Button.IsClicked)
                {
                    DialogsManager.ShowDialog(null, new ComponentChoiceDialog(item.ClassName, m_mechanicalDollsItemsData, m_componentPlayer));
                }
            }

            // 处理“箱子”按钮点击
            if (boxButton.IsClicked)
            {
                DialogsManager.ShowDialog(null, new ObtainingCollectionItemsDialog(m_mechanicalDollsItemsData, m_componentPlayer));
            }
        }
    }
}
