//组件选择对话
namespace Game
{
    public class ComponentChoiceDialog : Dialog
    {
        public ComponentPlayer m_componentPlayer;

        public ListPanelWidget componentList;
        public BevelledButtonWidget returnButton;

        public MechanicalDollsItemsData m_mechanicalDollsItemsData;

        public ComponentChoiceDialog(string ComponentType, MechanicalDollsItemsData mechanicalDollsItemsData, ComponentPlayer componentPlayer)
        {
            m_componentPlayer = componentPlayer;

            XElement node = ContentManager.Get<XElement>("Dialogs/ComponentChoiceDialog");
            LoadContents(this, node);

            componentList = Children.Find<ListPanelWidget>("ComponentList");
            returnButton = Children.Find<BevelledButtonWidget>("ReturnButton");
            m_mechanicalDollsItemsData = mechanicalDollsItemsData;

            // Precompute ComponentType display name and its last two characters for filtering
            int componentTypeDecoded = CraftingRecipesManager.DecodeResult(ComponentType);
            int componentTypeContents = Terrain.ExtractContents(componentTypeDecoded);
            string componentTypeDisplayName = BlocksManager.Blocks[componentTypeContents].GetDisplayName(null, componentTypeDecoded);
            string componentTypeSuffix = componentTypeDisplayName.Substring(componentTypeDisplayName.Length - 2);

            componentList.ItemWidgetFactory = delegate (object item)
            {
                var craftingHYZLRecipe = (CraftingHYZLRecipe)item;
                XElement node2 = ContentManager.Get<XElement>("Widgets/ComponentItem");
                var obj = (ContainerWidget)LoadWidget(this, node2, null);

                var iconWidget = obj.Children.Find<BlockIconWidget>("Icon");
                int decodedValue = CraftingRecipesManager.DecodeResult(craftingHYZLRecipe.ResultValue);
                iconWidget.Value = decodedValue;

                int contents = Terrain.ExtractContents(decodedValue);
                var block = BlocksManager.Blocks[contents];

                obj.Children.Find<LabelWidget>("Name").Text = block.GetDisplayName(null, decodedValue);
                obj.Children.Find<LabelWidget>("Level").Text = "等级" + NumericalProcessingManager.NumericalProcessing(PermanentlySavedAttributesManager.ComponentBlock[ComponentType].Item5);
                obj.Children.Find<LabelWidget>("Introduction").Text = block.GetDescription(decodedValue);
                return obj;
            };

            foreach (CraftingHYZLRecipe recipe in CraftingHYZLRecipesManager.Recipes)
            {
                if (recipe.MechanicalPuppetParts &&
                    PermanentlySavedAttributesManager.ComponentBlock[recipe.ResultValue].Item1)
                {
                    int recipeDecoded = CraftingRecipesManager.DecodeResult(recipe.ResultValue);
                    int recipeContents = Terrain.ExtractContents(recipeDecoded);
                    string recipeDisplayName = BlocksManager.Blocks[recipeContents].GetDisplayName(null, recipeDecoded);
                    if (recipeDisplayName.EndsWith(componentTypeSuffix))
                    {
                        if ((bool)componentPlayer.PlayerStats.ValuesDictionaryForMods["ComponentManufacturing" + NewComponents.GetType(CraftingRecipesManager.DecodeResult(recipe.ResultValue))])
                        {
                            componentList.AddItem(recipe);
                        }
                    }
                }
            }

            componentList.ItemClicked = delegate (object item)
            {
                var craftingHYZLRecipe = (CraftingHYZLRecipe)item;

                // Precompute clicked item's display name and suffix
                int clickedDecoded = CraftingRecipesManager.DecodeResult(craftingHYZLRecipe.ResultValue);
                int clickedContents = Terrain.ExtractContents(clickedDecoded);
                string clickedDisplayName = BlocksManager.Blocks[clickedContents].GetDisplayName(null, clickedDecoded);
                string clickedSuffix = clickedDisplayName.Substring(clickedDisplayName.Length - 2);

                foreach (var kvp in PermanentlySavedAttributesManager.ComponentBlock)
                {
                    int keyDecoded = CraftingRecipesManager.DecodeResult(kvp.Key);
                    int keyContents = Terrain.ExtractContents(keyDecoded);
                    string keyDisplayName = BlocksManager.Blocks[keyContents].GetDisplayName(null, keyDecoded);

                    if (keyDisplayName.EndsWith(clickedSuffix))
                    {
                        var val = kvp.Value;
                        PermanentlySavedAttributesManager.ComponentBlock[kvp.Key] = (val.Item1, false, val.Item3, val.Item4, val.Item5);
                    }

                    if (kvp.Key == craftingHYZLRecipe.ResultValue)
                    {
                        var current = PermanentlySavedAttributesManager.ComponentBlock[kvp.Key];
                        if (!current.Item2)
                        {
                            PermanentlySavedAttributesManager.ComponentBlock[kvp.Key] = (current.Item1, true, current.Item3, current.Item4, current.Item5);

                            int a = 0;
                            if (clickedDisplayName.EndsWith("手臂")) a = 1;
                            else if (clickedDisplayName.EndsWith("躯干")) a = 2;
                            else if (clickedDisplayName.EndsWith("之足")) a = 3;

                            var items = m_mechanicalDollsItemsData.Items;
                            items[a].ClassName = kvp.Key;
                            items[a].CurrentExp = current.Item3;
                            items[a].MaxExp = current.Item4;
                            items[a].Level = current.Item5;

                            m_mechanicalDollsItemsData.Items2[0].CurrentCapacity = 0;
                            m_mechanicalDollsItemsData.Items2[0].TheCurrentAmountOfStorage = 0;
                        }
                    }
                }
                DialogsManager.HideDialog(this);
            };
        }

        public override void Update()
        {
            if (returnButton.IsClicked)
            {
                DialogsManager.HideDialog(this);
            }
        }
    }
}
//永久保存属性经理
namespace Game
{
    public static class PermanentlySavedAttributesManager
    {
        public static DateTime LastResetDate;

        public static Dictionary<int, (bool, int)> Talent = new Dictionary<int, (bool, int)>();
        public static Dictionary<int, bool> Skills = new Dictionary<int, bool>();
        public static Dictionary<string, (bool, bool, int, int, int)> ComponentBlock = new Dictionary<string, (bool, bool, int, int, int)>();
        public static Dictionary<int, (string, string, long, string, string, double, bool)> Mailbox = new Dictionary<int, (string, string, long, string, string, double, bool)>();
        public static Dictionary<string, float> Money = new Dictionary<string, float>();
        public static Dictionary<string, float> ActivityParameters = new Dictionary<string, float>();
        public static Dictionary<int, (bool, bool)> ActivityCompletion = new Dictionary<int, (bool, bool)>();
        public static Dictionary<string, bool> Stepping = new Dictionary<string, bool>();
        public static Dictionary<int, double> ArchiveProperties = new Dictionary<int, double>();

        public static Random m_random = new();

        public static void Initialize()
        {
            Money["MysteryKey"] = 0;
            Money["SurvivalManual"] = 0;
            Money["SurvivalSelection"] = 0;
            Money["Shells"] = 0;
            Money["SilverCoins"] = 0;
            ActivityParameters["NumberzOfShellsSpent"] = 0;
            ActivityParameters["NumberOfQuestionsAndAnswers"] = 0;
            ActivityParameters["NumberOfTopics"] = 1;
            ActivityParameters["CorrectNumbers"] = 0;
            ActivityParameters["QuestionID"] = m_random.Int(0, AccessWildernessQuestionAndAnswerManager.Data.Count - 1);
            ActivityParameters["AdvertisingLotteryNumber"] = 0;
            LastResetDate = DateTime.MinValue;
            foreach (AccessTalent accessTalent in AccessTalentManager.Data)
            {
                Talent.Add(accessTalent.TalentID, (false, 1));
            }
            foreach (AccessSkills accessSkills in AccessSkillsManager.Data)
            {
                Skills.Add(accessSkills.SkillsID, false);
            }
            Skills[0] = true;
            foreach (CraftingHYZLRecipe recipe in CraftingHYZLRecipesManager.Recipes)
            {
                if (recipe.MechanicalPuppetParts)
                {
                    if (recipe.Ingredients.Count == 0)
                    {
                        ComponentBlock.Add(recipe.ResultValue, (true, true, 0, 1, 1));
                    }
                    else
                    {
                        ComponentBlock.Add(recipe.ResultValue, (false, false, 0, 1, 1));
                    }
                }
            }
            foreach (AccessEventCenter accessEventCenter in AccessEventCenterManager.Data)
            {
                if (accessEventCenter.ExploringTerrainNames != "")
                {
                    ActivityCompletion[accessEventCenter.ActivityTasksID] = (false, false);
                    Stepping[accessEventCenter.ExploringTerrainNames] = false;
                }
                else if (accessEventCenter.WorkstationLevel > 0 || accessEventCenter.KitchenCounterLevel > 0 || accessEventCenter.MedicalStationLevel > 0 || accessEventCenter.BedLevel > 0 || accessEventCenter.BoxLevel > 0 || accessEventCenter.PlantPlateLevel > 0 || accessEventCenter.BarrierLevel > 0)
                    ActivityCompletion[accessEventCenter.ActivityTasksID] = (false, false);
                else
                    ActivityCompletion[accessEventCenter.ActivityTasksID] = (false, true);
            }
        }
    }
}
//获得采集物品对话
namespace Game
{
    public class ObtainingCollectionItemsDialog : Dialog
    {
        public ComponentPlayer m_componentPlayer;
        public BevelledButtonWidget returnButton;
        public Dictionary<BlockIconWidget, LabelWidget> Items = new Dictionary<BlockIconWidget, LabelWidget>();
        public MechanicalDollsItemsData m_mechanicalDollsItemsData;
        public int TheCurrentAmountOfStorage;
        public System.Random m_random = new System.Random(); // 明确使用 System.Random

        // 内部优化字段
        public BlockIconWidget[] _iconWidgets = new BlockIconWidget[40];
        public LabelWidget[] _labelWidgets = new LabelWidget[40];
        public List<(int Decoded, int Count)> _itemsForDisplay; // Decoded 改为 int 类型

        public ObtainingCollectionItemsDialog(MechanicalDollsItemsData mechanicalDollsItemsData, ComponentPlayer componentPlayer)
        {
            XElement node = ContentManager.Get<XElement>("Dialogs/ObtainingCollectionItemsDialog");
            LoadContents(this, node);

            m_mechanicalDollsItemsData = mechanicalDollsItemsData;
            TheCurrentAmountOfStorage = m_mechanicalDollsItemsData.Items2[0].TheCurrentAmountOfStorage;
            m_componentPlayer = componentPlayer;
            returnButton = Children.Find<BevelledButtonWidget>("ReturnButton");

            // 初始化控件数组，并填充 Items 字典（供外部引用）
            for (int i = 0; i < 40; i++)
            {
                string suffix = (i + 1).ToString();
                BlockIconWidget icon = Children.Find<BlockIconWidget>("Icon" + suffix);
                LabelWidget label = Children.Find<LabelWidget>("QuantityLabel" + suffix);
                _iconWidgets[i] = icon;
                _labelWidgets[i] = label;
                Items[icon] = label;
            }

            // 预计算不变数据
            string targetClassName = mechanicalDollsItemsData.Items[1].ClassName;
            int targetBlockID = NewComponents.GetType(CraftingRecipesManager.DecodeResult(targetClassName));
            int level = mechanicalDollsItemsData.Items[1].Level;
            int storageCount = TheCurrentAmountOfStorage;

            // 收集所有物品来源
            List<(string Item, float Probability)> sources = new List<(string, float)>();
            int maxC = Math.Min(level, AccessNewComponentsManager.Get(targetBlockID).CollectingItems.Length);
            for (int c = 0; c < maxC; c++)
            {
                string[] items = AccessNewComponentsManager.Get(targetBlockID).CollectingItems[c].Split(',');
                float probFactor = AccessNewComponentsManager.Get(targetBlockID).Probability * level / (c + 1);
                foreach (string item in items)
                {
                    sources.Add((item, probFactor));
                }
            }

            // 计算物品数量
            Dictionary<string, int> blocks = new Dictionary<string, int>();
            List<string> itemOrder = new List<string>(); // 保持插入顺序

            for (int b = 0; b < storageCount; b++)
            {
                foreach (var source in sources)
                {
                    float prob = source.Probability;
                    int floorVal = (int)prob;          // 对于正数等价于 Math.Floor
                    float frac = prob - floorVal;

                    if (!blocks.ContainsKey(source.Item))
                    {
                        blocks[source.Item] = 0;
                        itemOrder.Add(source.Item);
                    }
                    blocks[source.Item] += floorVal;
                    if (frac > 0 && m_random.NextDouble() < frac)
                    {
                        blocks[source.Item]++;
                    }
                    // 防止溢出
                    if (blocks[source.Item] < 0) blocks[source.Item] = int.MaxValue;
                }
            }

            // 构建显示与掉落列表，并缓存解码后的 int 值
            _itemsForDisplay = new List<(int, int)>();
            Dictionary<string, int> decodedCache = new Dictionary<string, int>();
            foreach (string itemKey in itemOrder)
            {
                if (!decodedCache.TryGetValue(itemKey, out int decoded))
                {
                    decoded = (int)CraftingRecipesManager.DecodeResult(itemKey); // 显式转换为 int
                    decodedCache[itemKey] = decoded;
                }
                _itemsForDisplay.Add((decoded, blocks[itemKey]));
            }

            // 一次性更新 UI（前 40 个）
            for (int i = 0; i < Math.Min(40, _itemsForDisplay.Count); i++)
            {
                _iconWidgets[i].Value = _itemsForDisplay[i].Decoded; // Value 可接受 object
                _labelWidgets[i].Text = NumericalProcessingManager.NumericalProcessing(_itemsForDisplay[i].Count).ToString();
            }
        }

        public override void Update()
        {
            if (returnButton.IsClicked)
            {
                // 生成所有物品
                foreach (var item in _itemsForDisplay)
                {
                    m_componentPlayer.m_subsystemPickables.AddPickable(
                        item.Decoded,      // 现在为 int，符合方法签名
                        item.Count,
                        m_componentPlayer.ComponentBody.Position,
                        null,
                        null
                    );
                }
                // 减少存储量
                m_mechanicalDollsItemsData.Items2[0].TheCurrentAmountOfStorage -= TheCurrentAmountOfStorage;
                DialogsManager.HideDialog(this);
            }
        }
    }
}
//子系统玩家数据
namespace Game
{
    public class SubsystemHYZLPlayerStats : SubsystemPlayerStats
    {
        public override void Load(ValuesDictionary valuesDictionary)
        {
            foreach (KeyValuePair<string, object> item in valuesDictionary.GetValue<ValuesDictionary>("Stats"))
            {
                PlayerStats playerStats = new();
                playerStats.ValuesDictionaryForMods = (ValuesDictionary)item.Value;
                playerStats.Load((ValuesDictionary)item.Value);
                m_playerStats.Add(int.Parse(item.Key, CultureInfo.InvariantCulture), playerStats);
            }
        }

        public override void Save(ValuesDictionary valuesDictionary)
        {
            ValuesDictionary valuesDictionary2 = new();
            valuesDictionary.SetValue("Stats", valuesDictionary2);
            foreach (KeyValuePair<int, PlayerStats> playerStat in m_playerStats)
            {
                ValuesDictionary valuesDictionary3 = new();
                valuesDictionary2.SetValue(playerStat.Key.ToString(CultureInfo.InvariantCulture), valuesDictionary3);
                foreach (KeyValuePair<string, object> valuesDictionaryForMods in playerStat.Value.ValuesDictionaryForMods)
                {
                    valuesDictionary3.SetValue(valuesDictionaryForMods.Key.ToString(CultureInfo.InvariantCulture), valuesDictionaryForMods.Value);
                }
                playerStat.Value.Save(valuesDictionary3);
            }
        }
    }
}
