//机甲制作台界面
namespace Game
{
    public class MechaProductionDeskWidget : CanvasWidget
    {
        public BlockIconWidget icon;
        public ListPanelWidget componentList;

        public MechaProductionDeskWidget(ComponentPlayer componentPlayer, ComponentMechaProductionDesk componentMechaProductionDesk)
        {
            XElement node = ContentManager.Get<XElement>("Widgets/MechaProductionDeskWidget");
            LoadContents(this, node);
            icon = Children.Find<BlockIconWidget>("Icon");
            componentList = Children.Find<ListPanelWidget>("ComponentList");

            componentList.ItemWidgetFactory = delegate (object item)
            {
                var recipe = (CraftingHYZLRecipe)item;
                XElement node2 = ContentManager.Get<XElement>("Widgets/ComponentItem2");
                var obj = (ContainerWidget)LoadWidget(this, node2, null);
                obj.Children.Find<BlockIconWidget>("Icon").Value = CraftingRecipesManager.DecodeResult(recipe.ResultValue);
                obj.Children.Find<LabelWidget>("Introduction").Text = BlocksManager.Blocks[Terrain.ExtractContents(CraftingRecipesManager.DecodeResult(recipe.ResultValue))].GetDescription(CraftingRecipesManager.DecodeResult(recipe.ResultValue));
                return obj;
            };

            foreach (CraftingHYZLRecipe recipe in CraftingHYZLRecipesManager.Recipes)
            {
                if (recipe.MechanicalPuppetParts)
                {
                    componentList.AddItem(recipe);
                }
            }

            componentList.ItemClicked += delegate (object item)
            {
                var craftingHYZLRecipe = (CraftingHYZLRecipe)item;
                if (!PermanentlySavedAttributesManager.ComponentBlock[craftingHYZLRecipe.ResultValue].Item1)
                {
                    componentPlayer.ComponentGui.DisplaySmallMessage("未解锁", Color.White, true, true);
                }
                else if ((bool)componentPlayer.PlayerStats.ValuesDictionaryForMods["ComponentManufacturing" + NewComponents.GetType(CraftingRecipesManager.DecodeResult(craftingHYZLRecipe.ResultValue))])
                {
                    componentPlayer.ComponentGui.DisplaySmallMessage("已制作", Color.White, true, true);
                }
                else
                {
                    componentMechaProductionDesk.TryCraftSelectedRecipe(craftingHYZLRecipe, componentPlayer);
                }
            };
        }

        public override void Update()
        {
            icon.Value = Terrain.MakeBlockValue(NewInteroperableCube.Index, 0, 1);
        }
    }
}
//组件机甲制作台
namespace Game
{
    public class ComponentMechaProductionDesk : ComponentInventoryBase, IUpdateable
    {
        public ComponentBlockEntity componentBlockEntity;
        public ComponentPlayer m_craftingPlayer;
        public SubsystemPickables subsystemPickables;
        public SubsystemTime subsystemTime;
        public SubsystemGameInfo subsystemGameInfo;
        public SubsystemAudio subsystemAudio;
        public CraftingHYZLRecipe m_matchedRecipe;
        public bool m_recipeUpdateNeeded;
        public bool m_recipeRefindNeeded;
        public CraftingHYZLRecipe m_selectedRecipe;

        // 合成时间相关字段
        public double m_craftingStartTime;
        public double m_craftingDuration;
        public bool m_isCrafting;
        public CraftingHYZLRecipe m_currentCraftingRecipe;
        public int m_currentCraftingCount;
        public ComponentPlayer m_currentCraftingPlayer;

        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public virtual void Update(float dt)
        {
            // 处理合成时间逻辑
            if (m_isCrafting)
            {
                // 检查合成条件
                if (!CheckCraftingConditions(m_currentCraftingPlayer))
                {
                    CancelCraftingDueToConditions();
                    return;
                }

                subsystemTime.m_gameTimeFactor = 120;
                double currentTime = subsystemGameInfo.TotalElapsedGameTime;
                double elapsedTime = (currentTime - m_craftingStartTime);

                if (elapsedTime >= m_craftingDuration)
                {
                    subsystemTime.m_gameTimeFactor = 1;
                    // 合成完成
                    CompleteCrafting();
                }
            }

            if (m_recipeUpdateNeeded)
            {
                UpdateCraftingResult(m_recipeRefindNeeded);
            }
            m_recipeUpdateNeeded = false;
            m_recipeRefindNeeded = false;
        }

        // 新增：检查合成条件
        public bool CheckCraftingConditions(ComponentPlayer player)
        {
            if (IsPlayerDeadOrInvalid(player))
            {
                return false;
            }

            // 检查玩家睡眠值
            ComponentVitalStats vitalStats = player.ComponentVitalStats;
            if (vitalStats != null && vitalStats.Sleep <= 0.2f)
            {
                player.ComponentGui.DisplaySmallMessage("太困了，无法继续合成！", Color.Red, true, true);
                return false;
            }

            return true;
        }

        // 新增：因条件不满足取消合成
        public void CancelCraftingDueToConditions()
        {
            if (m_currentCraftingPlayer != null)
            {
                m_currentCraftingPlayer.ComponentGui.DisplaySmallMessage("合成已取消", Color.Yellow, true, true);
            }

            subsystemTime.m_gameTimeFactor = 1;
            m_isCrafting = false;
            m_currentCraftingRecipe = null;
            m_currentCraftingCount = 0;
            m_currentCraftingPlayer = null;
        }

        public override void AddSlotItems(int slotIndex, int value, int count)
        {
            base.AddSlotItems(slotIndex, value, count);
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }

        public override int RemoveSlotItems(int slotIndex, int count)
        {
            int num = base.RemoveSlotItems(slotIndex, count);
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
            return num;
        }

        public virtual void UpdateCraftingResult(bool recipeRefindNeeded)
        {
            ComponentPlayer componentPlayer = FindInteractingPlayer();
            if (componentPlayer == null) return;

            // 检查玩家状态和合成条件
            if (IsPlayerDeadOrInvalid(componentPlayer) || !CheckCraftingConditions(componentPlayer))
            {
                return;
            }

            Dictionary<string, int> playerIngredients = new Dictionary<string, int>();
            ComponentInventory playerInventory = componentPlayer.Entity.FindComponent<ComponentInventory>();

            for (int i = 0; i < playerInventory.SlotsCount; i++)
            {
                int slotValue = playerInventory.GetSlotValue(i);
                int slotCount = playerInventory.GetSlotCount(i);

                if (slotValue != 0 && slotCount > 0)
                {
                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string ingredientKey = $"{craftingId}:{data}";

                    if (playerIngredients.ContainsKey(ingredientKey))
                    {
                        playerIngredients[ingredientKey] += slotCount;
                    }
                    else
                    {
                        playerIngredients[ingredientKey] = slotCount;
                    }
                }
            }

            CraftingHYZLRecipe craftingRecipe;
            if (recipeRefindNeeded || m_matchedRecipe == null)
            {
                craftingRecipe = CraftingHYZLRecipesManager.FindMatchingRecipe(
                    Project.FindSubsystem<SubsystemTerrain>(true),
                    playerIngredients,
                    0f,
                    componentPlayer.PlayerData.Level
                );
            }
            else
            {
                craftingRecipe = m_matchedRecipe;
            }

            if (craftingRecipe != null && !string.IsNullOrEmpty(craftingRecipe.ResultValue))
            {
                m_matchedRecipe = craftingRecipe;

                if (CheckIngredientsAvailable(craftingRecipe, componentPlayer, 1))
                {
                    if (ConsumeIngredientsAndCraft(componentPlayer, craftingRecipe, 1))
                    {
                        if (!string.IsNullOrEmpty(craftingRecipe.Message))
                        {
                            string message = craftingRecipe.Message;
                            if (message.StartsWith('[') && message.EndsWith(']'))
                            {
                                message = LanguageControl.Get("CRMessage", message.Substring(1, message.Length - 2));
                            }
                            componentPlayer.ComponentGui.DisplaySmallMessage(message, Color.White, true, true);
                        }
                    }
                }
            }
            else
            {
                m_matchedRecipe = null;
            }
        }

        public bool CheckIngredientsAvailable(CraftingHYZLRecipe recipe, ComponentPlayer player, int count)
        {
            if (IsPlayerDeadOrInvalid(player))
            {
                return false;
            }

            ComponentInventory playerInventory = player.Entity.FindComponent<ComponentInventory>();

            foreach (var ingredient in recipe.Ingredients)
            {
                string ingredientId = ingredient.Key;
                int requiredCount = ingredient.Value * count;
                int totalCount = 0;

                for (int i = 0; i < playerInventory.SlotsCount; i++)
                {
                    int slotValue = playerInventory.GetSlotValue(i);
                    if (slotValue == 0) continue;

                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string currentIngredientId = $"{craftingId}:{data}";

                    if (currentIngredientId == ingredientId)
                    {
                        totalCount += playerInventory.GetSlotCount(i);
                    }
                }

                if (totalCount < requiredCount)
                {
                    return false;
                }
            }

            return true;
        }

        public int CalculateMaxCraftCount(CraftingHYZLRecipe recipe, ComponentPlayer player)
        {
            if (IsPlayerDeadOrInvalid(player))
            {
                return 0;
            }

            ComponentInventory playerInventory = player.Entity.FindComponent<ComponentInventory>();
            int maxCraftCount = int.MaxValue;

            foreach (var ingredient in recipe.Ingredients)
            {
                string ingredientId = ingredient.Key;
                int requiredCount = ingredient.Value;
                int totalCount = 0;

                for (int i = 0; i < playerInventory.SlotsCount; i++)
                {
                    int slotValue = playerInventory.GetSlotValue(i);
                    if (slotValue == 0) continue;

                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string currentIngredientId = $"{craftingId}:{data}";

                    if (currentIngredientId == ingredientId)
                    {
                        totalCount += playerInventory.GetSlotCount(i);
                    }
                }

                int craftCountForThisIngredient = totalCount / requiredCount;
                if (craftCountForThisIngredient < maxCraftCount)
                {
                    maxCraftCount = craftCountForThisIngredient;
                }
            }

            return Math.Max(1, maxCraftCount);
        }

        // 开始合成（消耗时间）
        public bool StartCrafting(ComponentPlayer player, CraftingHYZLRecipe recipe, int count)
        {
            if (IsPlayerDeadOrInvalid(player) || !CheckCraftingConditions(player))
            {
                player.ComponentGui.DisplaySmallMessage("无法开始合成：条件不满足", Color.Red, true, true);
                return false;
            }

            if (m_isCrafting)
            {
                player.ComponentGui.DisplaySmallMessage("正在合成中，请等待完成！", Color.Yellow, true, true);
                return false;
            }

            // 检查材料是否足够
            if (!CheckIngredientsAvailable(recipe, player, count))
            {
                player.ComponentGui.DisplaySmallMessage("材料不足！", Color.Red, true, true);
                return false;
            }

            // 计算合成时间（秒）
            double craftingTimeSeconds = recipe.TimeConsuming * count;
            m_craftingDuration = craftingTimeSeconds;
            m_craftingStartTime = subsystemGameInfo.TotalElapsedGameTime;

            // 设置合成状态
            m_isCrafting = true;
            m_currentCraftingRecipe = recipe;
            m_currentCraftingCount = count;
            m_currentCraftingPlayer = player;

            // 显示开始合成消息
            string itemName = BlocksManager.Blocks[Terrain.ExtractContents(CraftingRecipesManager.DecodeResult(recipe.ResultValue))].GetDisplayName(null, CraftingRecipesManager.DecodeResult(recipe.ResultValue));
            player.ComponentGui.DisplaySmallMessage($"开始合成 {count * recipe.ResultCount} 个 {itemName}，预计需要 {craftingTimeSeconds} 分钟", Color.Yellow, true, true);

            return true;
        }

        // 完成合成
        public void CompleteCrafting()
        {
            if (IsPlayerDeadOrInvalid(m_currentCraftingPlayer) || !CheckCraftingConditions(m_currentCraftingPlayer))
            {
                CancelCraftingDueToConditions();
                return;
            }

            if (!m_isCrafting || m_currentCraftingRecipe == null || m_currentCraftingPlayer == null)
            {
                m_isCrafting = false;
                return;
            }

            // 消耗材料并生成产物
            if (ConsumeIngredientsAndCraft(m_currentCraftingPlayer, m_currentCraftingRecipe, m_currentCraftingCount))
            {
                string itemName = BlocksManager.Blocks[Terrain.ExtractContents(CraftingRecipesManager.DecodeResult(m_currentCraftingRecipe.ResultValue))].GetDisplayName(null, CraftingRecipesManager.DecodeResult(m_currentCraftingRecipe.ResultValue));
                m_currentCraftingPlayer.ComponentGui.DisplaySmallMessage($"成功合成 {m_currentCraftingCount * m_currentCraftingRecipe.ResultCount} 个 {itemName}！", Color.Green, true, true);
                m_currentCraftingPlayer.ComponentGui.ModalPanelWidget = null;
            }

            // 重置合成状态
            m_isCrafting = false;
            m_currentCraftingRecipe = null;
            m_currentCraftingCount = 0;
            m_currentCraftingPlayer = null;

            // 触发配方更新
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }

        public string GetIngredientId(int slotValue)
        {
            int content = Terrain.ExtractContents(slotValue);
            int data = Terrain.ExtractData(slotValue);
            Block block = BlocksManager.Blocks[content];
            string craftingId = block.GetCraftingId(slotValue);
            return $"{craftingId}:{data}";
        }

        // 修改：现在只消耗材料，不立即生成产物
        public bool ConsumeIngredientsAndCraft(ComponentPlayer player, CraftingHYZLRecipe recipe, int count)
        {
            if (IsPlayerDeadOrInvalid(player) || !CheckCraftingConditions(player))
            {
                return false;
            }

            ComponentInventory playerInventory = player.Entity.FindComponent<ComponentInventory>();

            // 检查材料是否足够合成指定数量
            if (!CheckIngredientsAvailable(recipe, player, count))
            {
                return false;
            }

            // 消耗材料
            foreach (var ingredient in recipe.Ingredients)
            {
                string ingredientId = ingredient.Key;
                int totalRequiredCount = ingredient.Value * count;
                int remainingToConsume = totalRequiredCount;

                for (int i = 0; i < playerInventory.SlotsCount && remainingToConsume > 0; i++)
                {
                    int slotValue = playerInventory.GetSlotValue(i);
                    if (slotValue == 0) continue;

                    int content = Terrain.ExtractContents(slotValue);
                    int data = Terrain.ExtractData(slotValue);
                    Block block = BlocksManager.Blocks[content];
                    string craftingId = block.GetCraftingId(slotValue);
                    string currentIngredientId = $"{craftingId}:{data}";

                    if (currentIngredientId == ingredientId)
                    {
                        int availableCount = playerInventory.GetSlotCount(i);
                        int consumeCount = Math.Min(availableCount, remainingToConsume);

                        playerInventory.RemoveSlotItems(i, consumeCount);
                        remainingToConsume -= consumeCount;
                    }
                }
            }

            // 添加合成结果
            Vector3 dropPosition = componentBlockEntity.Position + new Vector3(0.5f, 1.5f, 0.5f);

            player.PlayerStats.ValuesDictionaryForMods["ComponentManufacturing" + NewComponents.GetType(CraftingRecipesManager.DecodeResult(recipe.ResultValue))] = true;

            subsystemAudio.PlaySound("Audio/UI/Production/SuccessInMakingObjects", 5f, m_random.Float(-0.2f, 0.2f), 0f, 0f);

            return true;
        }

        // 获取合成进度
        public float GetCraftingProgress()
        {
            if (!m_isCrafting) return 0f;

            double currentTime = subsystemGameInfo.TotalElapsedGameTime;
            double elapsedTime = (currentTime - m_craftingStartTime) * subsystemTime.m_gameTimeFactor;
            return MathUtils.Clamp((float)(elapsedTime / m_craftingDuration), 0f, 1f);
        }

        // 检查是否正在合成
        public bool IsCrafting()
        {
            return m_isCrafting;
        }

        // 获取当前合成信息
        public string GetCurrentCraftingInfo()
        {
            if (!m_isCrafting || m_currentCraftingRecipe == null) return string.Empty;

            string itemName = BlocksManager.Blocks[Terrain.ExtractContents(CraftingRecipesManager.DecodeResult(m_currentCraftingRecipe.ResultValue))].GetDisplayName(null, CraftingRecipesManager.DecodeResult(m_currentCraftingRecipe.ResultValue));
            float progress = GetCraftingProgress() * 100f;
            double remainingTime = (m_craftingDuration - (subsystemGameInfo.TotalElapsedGameTime - m_craftingStartTime) * subsystemTime.m_gameTimeFactor);

            return $"正在合成: {itemName} x{m_currentCraftingCount}\n进度: {progress:F1}%\n剩余时间: {remainingTime:F1}分钟";
        }

        public bool TryCraftSelectedRecipe(CraftingHYZLRecipe recipe, ComponentPlayer player)
        {
            if (recipe == null || player == null) return false;

            // 检查玩家状态和合成条件
            if (IsPlayerDeadOrInvalid(player) || !CheckCraftingConditions(player))
            {
                player.ComponentGui.DisplaySmallMessage("无法合成：条件不满足", Color.Red, true, true);
                return false;
            }

            // 检查材料是否匹配
            if (!CheckIngredientsAvailable(recipe, player, 1))
            {
                player.ComponentGui.DisplaySmallMessage("材料不足！", Color.Red, true, true);
                return false;
            }

            // 计算最大合成数量
            int maxCraftCount = CalculateMaxCraftCount(recipe, player);

            // 保存当前配方和玩家，用于对话框回调
            m_selectedRecipe = recipe;
            m_craftingPlayer = player;

            StartCrafting(m_craftingPlayer, m_selectedRecipe, 1);

            return true;
        }

        public bool IsPlayerDeadOrInvalid(ComponentPlayer player)
        {
            if (player == null) return true;

            // 检查玩家是否死亡
            ComponentHealth health = player.Entity.FindComponent<ComponentHealth>();
            if (health != null && health.Health <= 0f)
            {
                return true;
            }

            // 检查玩家是否打开合成界面
            if (player.ComponentGui.ModalPanelWidget is MechaProductionDeskWidget)
            {
                // 在合成界面中
            }
            else
            {
                return true;
            }

            // 检查玩家是否离合成台太远
            if (componentBlockEntity != null)
            {
                float distance = Vector3.Distance(player.ComponentBody.Position, componentBlockEntity.Position);
                if (distance > 5f) // 如果玩家离合成台超过5个单位，认为已离开
                {
                    return true;
                }
            }

            return false;
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            componentBlockEntity = Entity.FindComponent<ComponentBlockEntity>(throwOnError: true);
            subsystemPickables = Project.FindSubsystem<SubsystemPickables>(throwOnError: true);
            subsystemTime = Project.FindSubsystem<SubsystemTime>();
            subsystemGameInfo = Project.FindSubsystem<SubsystemGameInfo>();
            subsystemAudio = Project.FindSubsystem<SubsystemAudio>();
            m_recipeUpdateNeeded = true;
            m_recipeRefindNeeded = true;
        }
    }
}
