//子系统新枪方块行为
namespace Game
{
    public class SubsystemMusketNewBlockBehavior : SubsystemBlockBehavior
    {
        public SubsystemTerrain m_subsystemTerrain;
        public SubsystemTime m_subsystemTime;
        public SubsystemProjectiles m_subsystemProjectiles;
        public SubsystemParticles m_subsystemParticles;
        public SubsystemAudio m_subsystemAudio;
        public SubsystemNoise m_subsystemNoise;
        public Random m_random = new Random();
        public Dictionary<ComponentMiner, double> m_aimStartTimes = new Dictionary<ComponentMiner, double>();

        // 处理枪的方块ID（假设为600）
        public override int[] HandledBlocks => new int[1]
        {
            BlocksManager.GetBlockIndex<MusketNewBlock>()
        };

        // 编辑物品时显示耐久度
        public override bool OnEditInventoryItem(IInventory inventory, int slotIndex, ComponentPlayer componentPlayer)
        {
            int value = inventory.GetSlotValue(slotIndex);
            int damage = BlocksManager.Blocks[Terrain.ExtractContents(value)].GetDamage(value);
            componentPlayer.ComponentGui.DisplaySmallMessage(
                string.Format("损坏度:{0}/15", damage),
                Color.White, blinking: true, playNotificationSound: false);
            return false;
        }

        // 瞄准处理
        public override bool OnAim(Ray3 aim, ComponentMiner componentMiner, AimState state)
        {
            IInventory inventory = componentMiner.Inventory;
            if (inventory == null) return false;

            int activeSlotIndex = inventory.ActiveSlotIndex;
            if (activeSlotIndex < 0) return false;

            int slotValue = inventory.GetSlotValue(activeSlotIndex);
            int slotCount = inventory.GetSlotCount(activeSlotIndex);
            int id = Terrain.ExtractContents(slotValue);
            if (id != MusketNewBlock.Index || slotCount <= 0) return false;

            int type = MusketNewBlock.GetType(slotValue);
            MusketParameter musketParameter = MusketParameter.GetMusketParameter(type);

            // 记录瞄准开始（用于状态管理）
            if (!m_aimStartTimes.ContainsKey(componentMiner))
                m_aimStartTimes[componentMiner] = m_subsystemTime.GameTime;

            switch (state)
            {
                case AimState.InProgress:
                    AimHandAction(componentMiner, aim);
                    break;

                case AimState.Cancelled:
                    m_aimStartTimes.Remove(componentMiner);
                    break;

                case AimState.Completed:
                    bool success = ShootBullet(componentMiner, musketParameter, aim, activeSlotIndex, slotValue);
                    if (success) // 一次性武器直接移除
                        inventory.RemoveSlotItems(activeSlotIndex, 1);
                    m_aimStartTimes.Remove(componentMiner);
                    break;
            }

            return false;
        }

        // 发射子弹核心逻辑
        public bool ShootBullet(ComponentMiner componentMiner, MusketParameter musketParameter, Ray3 aim,
                                 int activeSlotIndex, int slotValue)
        {
            // 浸水检查
            if (componentMiner.ComponentCreature.ComponentBody.ImmersionFactor > 0.4f)
            {
                m_subsystemAudio.PlaySound("Audio/Impacts/Musket/" + AccessMusketNewBlockManager.Get(MusketNewBlock.GetType(slotValue)).ModelComponents + "Misfire", 1f, m_random.Float(-0.1f, 0.1f),
                    componentMiner.ComponentCreature.ComponentCreatureModel.EyePosition, 3f, autoDelay: true);
                return false;
            }

            IInventory inventory = componentMiner.Inventory;
            int bulletValue = CraftingRecipesManager.DecodeResult(musketParameter.Bulletvalue);
            int bulletSlot = -1;

            // 查找背包中的子弹
            for (int i = 0; i < inventory.SlotsCount; i++)
            {
                int val = inventory.GetSlotValue(i);
                int cnt = inventory.GetSlotCount(i);
                if (val == bulletValue && cnt > 0)
                {
                    bulletSlot = i;
                    break;
                }
            }

            if (bulletSlot == -1 && !musketParameter.InfiniteBullet)
            {
                componentMiner.ComponentPlayer?.ComponentGui.DisplaySmallMessage(
                    "没有子弹! 需要子弹: " + BlocksManager.Blocks[Terrain.ExtractContents(bulletValue)].GetDisplayName(null, bulletValue), Color.White, blinking: true, playNotificationSound: false);
                return false;
            }

            // 消耗一个子弹
            if (!musketParameter.InfiniteBullet)
            {
                inventory.RemoveSlotItems(bulletSlot, 1);
            }

            // 计算发射位置和方向
            Vector3 eye = componentMiner.ComponentCreature.ComponentCreatureModel.EyePosition;
            Vector3 right = componentMiner.ComponentCreature.ComponentBody.Matrix.Right;
            Vector3 up = componentMiner.ComponentCreature.ComponentBody.Matrix.Up;
            Vector3 position = eye + right * 0.3f - up * 0.2f;
            Vector3 direction = aim.Direction;

            // 发射抛射物
            Projectile projectile = m_subsystemProjectiles.FireProjectile(
                CraftingRecipesManager.DecodeResult(musketParameter.Bulletvalue), position, musketParameter.Bulletspeed * direction,
                Vector3.Zero, componentMiner.ComponentCreature);
            if (projectile != null)
                projectile.ProjectileStoppedAction = ProjectileStoppedAction.Disappear;

            // 后坐力
            Vector3 impulse = -musketParameter.Impulse * direction;
            componentMiner.ComponentCreature.ComponentBody.ApplyImpulse(impulse);

            // 枪烟
            if (musketParameter.Gunsmoke)
            {
                m_subsystemParticles.AddParticleSystem(
                    new GunSmokeParticleSystem(m_subsystemTerrain, position + 0.3f * direction, direction));
            }

            // 音效和噪音
            m_subsystemAudio.PlaySound("Audio/Impacts/Musket/" + AccessMusketNewBlockManager.Get(MusketNewBlock.GetType(slotValue)).ModelComponents + "Fire", 1f, m_random.Float(-0.1f, 0.1f),
                componentMiner.ComponentCreature.ComponentCreatureModel.EyePosition, 10f, autoDelay: true);
            m_subsystemNoise.MakeNoise(position, 1f, 40f);

            if (musketParameter.Damage > 0f)                                                //如果枪的破坏度影响因素大于0且可执行损坏操作				
            {
                int num = (int)(16 / (musketParameter.Damage * (MusketNewBlock.GetMoreDurable(slotValue) ? 2 : 1)));                                           //获取破坏度影响因素16等分的倒数
                int num2 = m_random.Int(0, num);                                                        //定义一个随机整数，取值范围为0到上面获取的倒数
                if (num2 <= 1)                                                                          //如果获得的随机数小于等于1
                {
                    componentMiner.DamageActiveTool((int)((musketParameter.Damage * (MusketNewBlock.GetMoreDurable(slotValue) ? 2 : 1)) / 16f) + 1);           //让枪受损，受损值由破坏度影响因素决定
                }
            }

            // 显示当前耐久
            int currentDamage = BlocksManager.Blocks[Terrain.ExtractContents(slotValue)].GetDamage(slotValue);
            componentMiner.ComponentPlayer?.ComponentGui.DisplaySmallMessage(
                $"损坏度:{currentDamage}/15", Color.White, blinking: true, playNotificationSound: false);

            return true;
        }

        // 瞄准时的手部动作（保持不变）
        public void AimHandAction(ComponentMiner componentMiner, Ray3 aim)
        {
            ComponentFirstPersonModel fpModel = componentMiner.Entity.FindComponent<ComponentFirstPersonModel>();
            if (fpModel != null)
            {
                componentMiner.ComponentPlayer?.ComponentAimingSights.ShowAimingSights(aim.Position, aim.Direction);
                fpModel.ItemOffsetOrder = new Vector3(-0.21f, 0.15f, 0.08f);
                fpModel.ItemRotationOrder = new Vector3(-0.7f, 0f, 0f);
            }
            componentMiner.ComponentCreature.ComponentCreatureModel.AimHandAngleOrder = 1.4f;
            componentMiner.ComponentCreature.ComponentCreatureModel.InHandItemOffsetOrder = new Vector3(-0.08f, -0.08f, 0.07f);
            componentMiner.ComponentCreature.ComponentCreatureModel.InHandItemRotationOrder = new Vector3(-1.7f, 0f, 0f);
        }

        // 偏移量取消（返回零）
        public Vector3 GetOffset(ComponentMiner componentMiner, float time, int type) => Vector3.Zero;

        // 不再需要装填逻辑，移除原 ProcessInventoryItem 和 GetProcessInventoryItemCapacity

        public override void Load(ValuesDictionary valuesDictionary)
        {
            m_subsystemTerrain = Project.FindSubsystem<SubsystemTerrain>(throwOnError: true);
            m_subsystemTime = Project.FindSubsystem<SubsystemTime>(throwOnError: true);
            m_subsystemProjectiles = Project.FindSubsystem<SubsystemProjectiles>(throwOnError: true);
            m_subsystemParticles = Project.FindSubsystem<SubsystemParticles>(throwOnError: true);
            m_subsystemAudio = Project.FindSubsystem<SubsystemAudio>(throwOnError: true);
            m_subsystemNoise = Project.FindSubsystem<SubsystemNoise>(throwOnError: true);
            base.Load(valuesDictionary);
        }
    }
}
//组件生物Buff
namespace Game
{
    public class ComponentBiologyBuff : Component, IUpdateable
    {
        public ComponentLocomotion componentLocomotion;

        public static string fName = "ComponentBiologyBuff";

        public Dictionary<string, float> NewProjectilesBuff = new Dictionary<string, float>();

        public UpdateOrder UpdateOrder => UpdateOrder.Default;

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            componentLocomotion = Entity.FindComponent<ComponentLocomotion>();

            ValuesDictionary value2 = valuesDictionary.GetValue<ValuesDictionary>("NewProjectilesBuff", null);
            if (value2 != null)
            {
                for (int j = 0; j < valuesDictionary.GetValue<int>("NewProjectilesBuffCount"); j++)
                {
                    ValuesDictionary value3 = value2.GetValue<ValuesDictionary>("NewProjectilesBuff" + j, null);
                    if (value3 != null)
                    {
                        NewProjectilesBuff[value3.GetValue<string>("BuffName")] = value3.GetValue<float>("Frozen");
                    }
                }
            }
        }

        public override void Save(ValuesDictionary valuesDictionary, EntityToIdMap entityToIdMap)
        {
            valuesDictionary.SetValue("NewProjectilesBuffCount", NewProjectilesBuff.Count);
            ValuesDictionary valuesDictionary2 = new();
            valuesDictionary.SetValue("NewProjectilesBuff", valuesDictionary2);
            for (int i = 0; i < NewProjectilesBuff.Count; i++)
            {
                float newProjectilesBuff = NewProjectilesBuff.ElementAt(i).Value;
                if (newProjectilesBuff > 0)
                {
                    ValuesDictionary valuesDictionary3 = new();
                    valuesDictionary2.SetValue("NewProjectilesBuff" + i, valuesDictionary3);
                    valuesDictionary3.SetValue("BuffName", NewProjectilesBuff.ElementAt(i).Key);
                    valuesDictionary3.SetValue("Frozen", newProjectilesBuff);
                }
            }
        }

        public void Update(float dt)
        {
            foreach (var key in NewProjectilesBuff.Keys.ToList())
            {
                var tuple = NewProjectilesBuff[key];
                if (tuple > 0)
                {
                    componentLocomotion.WalkOrder = Vector2.Zero;
                    componentLocomotion.FlyOrder = Vector3.Zero;
                    componentLocomotion.SwimOrder = Vector3.Zero;
                    componentLocomotion.TurnOrder = Vector2.Zero;
                    componentLocomotion.LookOrder = Vector2.Zero;
                    componentLocomotion.JumpOrder = 0;
                }
                NewProjectilesBuff[key] = MathUtils.Max(tuple - dt, 0f);
            }
        }
    }
}
//神秘匣子界面
namespace Game
{
    public class MysteryBoxWidget : CanvasWidget
    {
        public LabelWidget quantityLabel1;
        public BitmapButtonWidget viewTheRecipeButton;
        public BlockIconWidget icon;
        public BevelledButtonWidget startOnceButton;
        public BevelledButtonWidget startTenButton;
        public ComponentPlayer m_componentPlayer;
        public int blockValue;
        public Random m_random = new();
        public List<(string itemId, int quantity, float weight)> cachedPrizes;
        public float totalWeight;

        public MysteryBoxWidget(ComponentPlayer componentPlayer, int BlockValue)
        {
            m_componentPlayer = componentPlayer;
            blockValue = BlockValue;
            XElement node = ContentManager.Get<XElement>("Widgets/MysteryBoxWidget");
            LoadContents(this, node);
            quantityLabel1 = Children.Find<LabelWidget>("QuantityLabel1");
            viewTheRecipeButton = Children.Find<BitmapButtonWidget>("ViewTheRecipeButton");
            icon = Children.Find<BlockIconWidget>("Icon");
            startOnceButton = Children.Find<BevelledButtonWidget>("StartOnceButton");
            startTenButton = Children.Find<BevelledButtonWidget>("StartTenButton");
        }

        public override void Update()
        {
            quantityLabel1.Text = NumericalProcessingManager.NumericalProcessing(PermanentlySavedAttributesManager.Money["MysteryKey"]);
            icon.Value = blockValue;

            if (viewTheRecipeButton.IsClicked)
            {
                DialogsManager.ShowDialog(null, new ComponentRecipeAcquisitionDialog());
            }

            if (cachedPrizes == null)
            {
                cachedPrizes = new List<(string, int, float)>();
                var lotteryData = AccessLotteryManager.Get(0);
                int globalIndex = 0;
                foreach (string lotteryItem in lotteryData.LotteryItems)
                {
                    string[] itemGroup = lotteryItem.Split('/');
                    if (itemGroup.Length < 2) continue;
                    for (int i = 0; i < itemGroup.Length - 1; i++)
                    {
                        string[] itemParts = itemGroup[i].Split(',');
                        if (itemParts.Length % 2 != 0) continue;
                        int pairCount = itemParts.Length / 2;
                        for (int j = 0; j < pairCount; j++)
                        {
                            string itemId = itemParts[j * 2];
                            int quantity = int.Parse(itemParts[j * 2 + 1]);
                            float weight = 100f / (globalIndex + 1);
                            cachedPrizes.Add((itemId, quantity, weight));
                            globalIndex++;
                        }
                    }
                }
                totalWeight = 0f;
                foreach (var prize in cachedPrizes) totalWeight += prize.weight;
            }

            if (startOnceButton.IsClicked)
            {
                if (PermanentlySavedAttributesManager.Money["MysteryKey"] < 1)
                {
                    m_componentPlayer.ComponentGui.DisplaySmallMessage("神秘钥匙不足", Color.Red, true, true);
                }
                else
                {
                    float randVal = m_random.Float() * totalWeight;
                    float accumulator = 0f;
                    string itemId = null;
                    int quantity = 0;
                    foreach (var prize in cachedPrizes)
                    {
                        accumulator += prize.weight;
                        if (randVal <= accumulator)
                        {
                            itemId = prize.itemId;
                            quantity = prize.quantity;
                            break;
                        }
                    }
                    if (itemId == null)
                    {
                        itemId = cachedPrizes[0].itemId;
                        quantity = cachedPrizes[0].quantity;
                    }
                    var obtained = new Dictionary<string, int> { { itemId, quantity } };
                    DialogsManager.ShowDialog(null, new LotteryItemDisplayDialog(
                        AccessLotteryManager.Get(0).Title,
                        AccessLotteryManager.Get(0).Introduction,
                        obtained));
                    if (Terrain.ExtractContents(CraftingRecipesManager.DecodeResult(itemId)) != NewComponents.Index)
                    {
                        int num = 0;
                        while (PermanentlySavedAttributesManager.Mailbox.ContainsKey(num)) num++;
                        double futureMinutes = DateTime.UtcNow.AddDays(30).Ticks / (double)TimeSpan.TicksPerMinute;
                        PermanentlySavedAttributesManager.Mailbox[num] = ("神秘匣子", "十分的勇", 1145141919810917813, "", string.Join(";", obtained.Select(kvp => $"{kvp.Key},{kvp.Value}")), futureMinutes, false);
                    }
                    else
                    {
                        var block = PermanentlySavedAttributesManager.ComponentBlock[itemId];
                        bool flag = block.Item1;
                        bool flag2 = block.Item2;
                        int current = block.Item3;
                        int required = block.Item4;
                        int level = block.Item5;
                        if (!flag)
                        {
                            PermanentlySavedAttributesManager.ComponentBlock[itemId] = (true, flag2, current, required, level);
                        }
                        current++;
                        if (current >= required)
                        {
                            current = 0;
                            required++;
                            level++;
                        }
                        PermanentlySavedAttributesManager.ComponentBlock[itemId] = (true, flag2, current, required, level);
                    }
                    PermanentlySavedAttributesManager.Money["MysteryKey"]--;
                }
            }

            if (startTenButton.IsClicked)
            {
                if (PermanentlySavedAttributesManager.Money["MysteryKey"] < 9)
                {
                    m_componentPlayer.ComponentGui.DisplaySmallMessage("神秘钥匙不足", Color.Red, true, true);
                }
                else
                {
                    var allObtained = new Dictionary<string, int>();
                    for (int i = 0; i < 10; i++)
                    {
                        float randVal = m_random.Float() * totalWeight;
                        float accumulator = 0f;
                        string itemId = null;
                        int quantity = 0;
                        foreach (var prize in cachedPrizes)
                        {
                            accumulator += prize.weight;
                            if (randVal <= accumulator)
                            {
                                itemId = prize.itemId;
                                quantity = prize.quantity;
                                break;
                            }
                        }
                        if (itemId == null)
                        {
                            itemId = cachedPrizes[0].itemId;
                            quantity = cachedPrizes[0].quantity;
                        }
                        if (allObtained.ContainsKey(itemId))
                            allObtained[itemId] += quantity;
                        else
                            allObtained[itemId] = quantity;
                        if (Terrain.ExtractContents(CraftingRecipesManager.DecodeResult(itemId)) == NewComponents.Index)
                        {
                            var block = PermanentlySavedAttributesManager.ComponentBlock[itemId];
                            bool flag = block.Item1;
                            bool flag2 = block.Item2;
                            int current = block.Item3;
                            int required = block.Item4;
                            int level = block.Item5;
                            if (!flag)
                            {
                                PermanentlySavedAttributesManager.ComponentBlock[itemId] = (true, flag2, current, required, level);
                            }
                            current++;
                            if (current >= required)
                            {
                                current = 0;
                                required++;
                                level++;
                            }
                            PermanentlySavedAttributesManager.ComponentBlock[itemId] = (true, flag2, current, required, level);
                        }
                    }
                    DialogsManager.ShowDialog(null, new LotteryItemDisplayDialog(
                        AccessLotteryManager.Get(0).Title,
                        AccessLotteryManager.Get(0).Introduction,
                        allObtained));
                    var mailItems = new Dictionary<string, int>();
                    foreach (var kvp in allObtained)
                    {
                        if (Terrain.ExtractContents(CraftingRecipesManager.DecodeResult(kvp.Key)) != NewComponents.Index)
                        {
                            mailItems[kvp.Key] = kvp.Value;
                        }
                    }
                    if (mailItems.Count > 0)
                    {
                        int num = 0;
                        while (PermanentlySavedAttributesManager.Mailbox.ContainsKey(num)) num++;
                        double futureMinutes = DateTime.UtcNow.AddDays(30).Ticks / (double)TimeSpan.TicksPerMinute;
                        PermanentlySavedAttributesManager.Mailbox[num] = ("神秘匣子", "十分的勇", 1145141919810917813, "", string.Join(";", mailItems.Select(kvp => $"{kvp.Key},{kvp.Value}")), futureMinutes, false);
                    }
                    PermanentlySavedAttributesManager.Money["MysteryKey"] -= 9;
                }
            }
        }
    }
}
//组件配方获取对话
namespace Game
{
    public class ComponentRecipeAcquisitionDialog : Dialog
    {
        public ListPanelWidget componentList;
        public BevelledButtonWidget returnButton;
        public XElement componentItemTemplate;

        public ComponentRecipeAcquisitionDialog()
        {
            XElement node = ContentManager.Get<XElement>("Dialogs/ComponentRecipeAcquisitionDialog");
            LoadContents(this, node);
            componentList = Children.Find<ListPanelWidget>("ComponentList");
            returnButton = Children.Find<BevelledButtonWidget>("ReturnButton");
            componentItemTemplate = ContentManager.Get<XElement>("Widgets/ComponentItem3");

            componentList.ItemWidgetFactory = delegate (object item)
            {
                var recipe = (CraftingHYZLRecipe)item;
                var decodedResult = CraftingRecipesManager.DecodeResult(recipe.ResultValue);
                var contentsId = Terrain.ExtractContents(decodedResult);
                var block = BlocksManager.Blocks[contentsId];
                var compBlock = PermanentlySavedAttributesManager.ComponentBlock[recipe.ResultValue];

                var widget = (ContainerWidget)LoadWidget(this, componentItemTemplate, null);
                widget.Children.Find<BlockIconWidget>("Icon").Value = decodedResult;
                widget.Children.Find<LabelWidget>("Name").Text = block.GetDisplayName(null, decodedResult);
                widget.Children.Find<LabelWidget>("Level").Text = "等级" + NumericalProcessingManager.NumericalProcessing(compBlock.Item5);
                widget.Children.Find<LabelWidget>("Introduction").Text = block.GetDescription(decodedResult);
                widget.Children.Find<ValueBarWidget>("LevelBar").Value = (float)compBlock.Item3 / compBlock.Item4;
                widget.Children.Find<LabelWidget>("LevelLabel").Text = NumericalProcessingManager.NumericalProcessing(compBlock.Item3) + "/" + NumericalProcessingManager.NumericalProcessing(compBlock.Item4);
                return widget;
            };

            foreach (CraftingHYZLRecipe recipe in CraftingHYZLRecipesManager.Recipes)
            {
                if (recipe.MechanicalPuppetParts && PermanentlySavedAttributesManager.ComponentBlock[recipe.ResultValue].Item1)
                {
                    componentList.AddItem(recipe);
                }
            }
        }

        public override void Update()
        {
            if (returnButton.IsClicked)
            {
                DialogsManager.HideDialog(this);
            }
        }
    }
}
