//抽奖物品显示对话
namespace Game
{
    public class LotteryItemDisplayDialog : Dialog
    {
        public LabelWidget titleLabel;
        public ListPanelWidget introductionList;
        public ListPanelWidget lotteryItemsList;
        public BevelledButtonWidget iAmSureButton;

        public string title;

        // 优化：缓存模板和物品列表，避免重复加载和索引开销
        public readonly XElement introTemplate;
        public readonly XElement lotteryItemTemplate;
        public readonly List<KeyValuePair<string, int>> itemsList;

        public LotteryItemDisplayDialog(string Title, string Introduction, Dictionary<string, int> ObtainingItems)
        {
            title = Title;
            XElement node = ContentManager.Get<XElement>("Dialogs/LotteryItemDisplayDialog");
            LoadContents(this, node);

            titleLabel = Children.Find<LabelWidget>("TitleLabel");
            introductionList = Children.Find<ListPanelWidget>("IntroductionList");
            lotteryItemsList = Children.Find<ListPanelWidget>("LotteryItemsList");
            iAmSureButton = Children.Find<BevelledButtonWidget>("IAmSureButton");

            // 预先加载模板，避免工厂中重复调用 ContentManager.Get
            introTemplate = ContentManager.Get<XElement>("Widgets/IntroductionToLottery");
            lotteryItemTemplate = ContentManager.Get<XElement>("Widgets/LotteryItems");

            // 将字典转为列表，提升索引访问效率（保持原始枚举顺序）
            itemsList = ObtainingItems.ToList();

            // 设置简介列表工厂
            int introPageCount = (int)Math.Ceiling((double)Introduction.Length / 20);
            introductionList.ItemWidgetFactory = item =>
            {
                int page = (int)item;
                var widget = (ContainerWidget)LoadWidget(this, introTemplate, null);
                int start = (page - 1) * 20;
                int length = Math.Min(20, Introduction.Length - start);
                widget.Children.Find<LabelWidget>("Introduction").Text = Introduction.Substring(start, length);
                return widget;
            };

            // 设置物品列表工厂
            int itemPageCount = (int)Math.Ceiling((double)itemsList.Count / 4);
            lotteryItemsList.ItemWidgetFactory = item =>
            {
                int page = (int)item;
                var widget = (ContainerWidget)LoadWidget(this, lotteryItemTemplate, null);
                int baseIndex = (page - 1) * 4;
                for (int i = 1; i <= 4; i++)
                {
                    int idx = baseIndex + i - 1;
                    if (idx < itemsList.Count)
                    {
                        var pair = itemsList[idx];
                        if (pair.Key.Contains(":"))
                        {
                            widget.Children.Find<BlockIconWidget>("Icon" + i).Value = CraftingRecipesManager.DecodeResult(pair.Key);
                            widget.Children.Find<BitmapButtonWidget>("Money" + i).IsVisible = false;
                        }
                        else
                        {
                            widget.Children.Find<BlockIconWidget>("Icon" + i).Value = 0;
                            widget.Children.Find<BitmapButtonWidget>("Money" + i).IsVisible = true;
                            widget.Children.Find<BitmapButtonWidget>("Money" + i).NormalSubtexture = widget.Children.Find<BitmapButtonWidget>("Money" + i).ClickedSubtexture = ContentManager.Get<Texture2D>("Textures/Gui/Money/" + pair.Key);
                        }
                        widget.Children.Find<LabelWidget>("Quantity" + i).Text = pair.Value.ToString();
                    }
                    else
                    {
                        widget.Children.Find<BlockIconWidget>("Icon" + i).Value = 0;
                        widget.Children.Find<LabelWidget>("Quantity" + i).Text = "";
                        widget.Children.Find<BitmapButtonWidget>("Money" + i).IsVisible = false;
                    }
                }
                return widget;
            };

            // 添加分页项
            for (int i = 1; i <= introPageCount; i++)
                introductionList.AddItem(i);

            for (int i = 1; i <= itemPageCount; i++)
                lotteryItemsList.AddItem(i);

            // 直接设置标题文本，避免每帧重复赋值
            titleLabel.Text = title;
        }

        public override void Update()
        {
            if (iAmSureButton.IsClicked)
                DialogsManager.HideDialog(this);
        }
    }
}
//邮箱屏幕
namespace Game
{
    public class MailboxScreen : Screen
    {
        public ListPanelWidget mailboxList;
        public BevelledButtonWidget receiveAllMailButton;

        public ComponentPlayer m_componentPlayer;

        public string lastMailboxState;

        public MailboxScreen(ComponentPlayer componentPlayer)
        {
            m_componentPlayer = componentPlayer;

            XElement node = ContentManager.Get<XElement>("Screens/MailboxScreen");
            LoadContents(this, node);
            mailboxList = Children.Find<ListPanelWidget>("MailboxList");
            receiveAllMailButton = Children.Find<BevelledButtonWidget>("ReceiveAllMailButton");

            Texture2D textureNormal = ContentManager.Get<Texture2D>("Textures/Gui/Button/MailButton");
            Texture2D textureOpen = ContentManager.Get<Texture2D>("Textures/Gui/Button/MailButton_Open");

            mailboxList.ItemWidgetFactory = (object item) =>
            {
                var mailbox = ((int, string, string, long, string, string, double, bool))item;
                XElement node2 = ContentManager.Get<XElement>("Widgets/Mail");
                var obj = (ContainerWidget)Widget.LoadWidget(this, node2, null);
                var mailButton = obj.Children.Find<BitmapButtonWidget>("MailButton");
                mailButton.NormalSubtexture = mailButton.ClickedSubtexture = mailbox.Item8 ? textureOpen : textureNormal;
                obj.Children.Find<LabelWidget>("Title").Text = mailbox.Item2;
                return obj;
            };

            mailboxList.ItemClicked = (object item) =>
            {
                var mailbox = ((int, string, string, long, string, string, double, bool))item;
                if (mailboxList.SelectedIndex.HasValue)
                {
                    DialogsManager.ShowDialog(null, new EmailInformationDialog(componentPlayer, mailbox.Item1));
                    PermanentlySavedAttributesManager.Mailbox[mailbox.Item1] = (mailbox.Item2, mailbox.Item3, mailbox.Item4, mailbox.Item5, mailbox.Item6, mailbox.Item7, true);

                    mailboxList.ClearItems();
                    foreach (var kv in PermanentlySavedAttributesManager.Mailbox)
                    {
                        mailboxList.AddItem((kv.Key, kv.Value.Item1, kv.Value.Item2, kv.Value.Item3, kv.Value.Item4, kv.Value.Item5, kv.Value.Item6, kv.Value.Item7));
                    }

                    string newState = "";
                    foreach (var kv in PermanentlySavedAttributesManager.Mailbox)
                    {
                        newState += kv.Key.ToString() + ":" + (kv.Value.Item7 ? "1" : "0") + ";";
                    }
                    lastMailboxState = newState;
                }
            };

            mailboxList.ClearItems();
            foreach (var kv in PermanentlySavedAttributesManager.Mailbox)
            {
                mailboxList.AddItem((kv.Key, kv.Value.Item1, kv.Value.Item2, kv.Value.Item3, kv.Value.Item4, kv.Value.Item5, kv.Value.Item6, kv.Value.Item7));
            }
            string initialState = "";
            foreach (var kv in PermanentlySavedAttributesManager.Mailbox)
            {
                initialState += kv.Key.ToString() + ":" + (kv.Value.Item7 ? "1" : "0") + ";";
            }
            lastMailboxState = initialState;
        }

        public override void Update()
        {
            if (Input.Back || Input.Cancel || Children.Find<ButtonWidget>("TopBar.Back").IsClicked)
            {
                ScreensManager.SwitchScreen(ScreensManager.PreviousScreen);
            }
            if (receiveAllMailButton.IsClicked)
            {
                foreach (var kv in PermanentlySavedAttributesManager.Mailbox)
                {
                    foreach (string pair in kv.Value.Item5.Split(';'))
                    {
                        string[] parts = pair.Split(',');
                        if (parts.Length >= 2)
                            m_componentPlayer.m_subsystemPickables.AddPickable(CraftingRecipesManager.DecodeResult(parts[0]), int.Parse(parts[1]), m_componentPlayer.ComponentBody.Position, null, null);
                    }
                    PermanentlySavedAttributesManager.Mailbox.Remove(kv.Key);
                }
            }

            string currentState = "";
            foreach (var kv in PermanentlySavedAttributesManager.Mailbox)
            {
                currentState += kv.Key.ToString() + ":" + (kv.Value.Item7 ? "1" : "0") + ";";
            }
            if (currentState != lastMailboxState)
            {
                mailboxList.ClearItems();
                foreach (var kv in PermanentlySavedAttributesManager.Mailbox)
                {
                    mailboxList.AddItem((kv.Key, kv.Value.Item1, kv.Value.Item2, kv.Value.Item3, kv.Value.Item4, kv.Value.Item5, kv.Value.Item6, kv.Value.Item7));
                }
                lastMailboxState = currentState;
            }
        }
    }
}
//邮箱信息对话
namespace Game
{
    public class EmailInformationDialog : Dialog
    {
        public LabelWidget titleLabel;
        public LabelWidget nameLabel;
        public LabelWidget uIDLabel;
        public ListPanelWidget introductionList;
        public ListPanelWidget lotteryItemsList;
        public LabelWidget mailDeletionLabel;
        public BevelledButtonWidget returnButton;
        public BevelledButtonWidget iAmSureButton;
        public ComponentPlayer m_componentPlayer;
        public string[] LotteryItems;
        public int iD;

        public EmailInformationDialog(ComponentPlayer componentPlayer, int ID)
        {
            m_componentPlayer = componentPlayer;
            iD = ID;
            var mail = PermanentlySavedAttributesManager.Mailbox[ID];
            LoadContents(this, ContentManager.Get<XElement>("Dialogs/EmailInformationDialog"));
            titleLabel = Children.Find<LabelWidget>("TitleLabel");
            nameLabel = Children.Find<LabelWidget>("NameLabel");
            uIDLabel = Children.Find<LabelWidget>("UIDLabel");
            introductionList = Children.Find<ListPanelWidget>("IntroductionList");
            lotteryItemsList = Children.Find<ListPanelWidget>("LotteryItemsList");
            mailDeletionLabel = Children.Find<LabelWidget>("MailDeletionLabel");
            returnButton = Children.Find<BevelledButtonWidget>("ReturnButton");
            iAmSureButton = Children.Find<BevelledButtonWidget>("IAmSureButton");
            titleLabel.Text = mail.Item1;
            nameLabel.Text = "发件人昵称：" + mail.Item2;
            uIDLabel.Text = "发件人UID：" + mail.Item3;
            string introduction = mail.Item4;
            int introPageCount = (int)Math.Ceiling((double)introduction.Length / 16);
            introductionList.ItemWidgetFactory = item =>
            {
                int page = (int)item;
                var widget = (ContainerWidget)LoadWidget(this, ContentManager.Get<XElement>("Widgets/IntroductionToLottery"), null);
                int start = (page - 1) * 16;
                int length = Math.Min(16, introduction.Length - start);
                widget.Children.Find<LabelWidget>("Introduction").Text = introduction.Substring(start, length);
                return widget;
            };
            LotteryItems = mail.Item5.Split(';');
            int itemPageCount = (int)Math.Ceiling((double)LotteryItems.Length / 3);
            lotteryItemsList.ItemWidgetFactory = item =>
            {
                int page = (int)item;
                var widget = (ContainerWidget)LoadWidget(this, ContentManager.Get<XElement>("Widgets/MailItems"), null);
                int baseIndex = (page - 1) * 3;
                for (int i = 1; i <= 3; i++)
                {
                    int idx = baseIndex + i - 1;
                    if (idx < LotteryItems.Length)
                    {
                        string[] parts = LotteryItems[idx].Split(',');
                        if (parts.Length >= 2)
                        {
                            if (parts[0].Contains(":"))
                            {
                                widget.Children.Find<BlockIconWidget>("Icon" + i).Value = CraftingRecipesManager.DecodeResult(parts[0]);
                                widget.Children.Find<BitmapButtonWidget>("Money" + i).IsVisible = false;
                            }
                            else
                            {
                                widget.Children.Find<BlockIconWidget>("Icon" + i).Value = 0;
                                widget.Children.Find<BitmapButtonWidget>("Money" + i).IsVisible = true;
                                widget.Children.Find<BitmapButtonWidget>("Money" + i).NormalSubtexture = widget.Children.Find<BitmapButtonWidget>("Money" + i).ClickedSubtexture = ContentManager.Get<Texture2D>("Textures/Gui/Money/" + parts[0]);
                            }
                            widget.Children.Find<LabelWidget>("Quantity" + i).Text = parts[1];
                            continue;
                        }
                    }
                    widget.Children.Find<BlockIconWidget>("Icon" + i).Value = 0;
                    widget.Children.Find<LabelWidget>("Quantity" + i).Text = "";
                    widget.Children.Find<BitmapButtonWidget>("Background" + i).IsVisible = false;
                    widget.Children.Find<BitmapButtonWidget>("Money" + i).IsVisible = false;
                }
                return widget;
            };
            for (int i = 1; i <= introPageCount; i++) introductionList.AddItem(i);
            for (int i = 1; i <= itemPageCount; i++) lotteryItemsList.AddItem(i);
        }

        public override void Update()
        {
            if (!PermanentlySavedAttributesManager.Mailbox.TryGetValue(iD, out var mail))
            {
                DialogsManager.HideDialog(this);
                return;
            }
            TimeSpan diff = new DateTime((long)(mail.Item6 * TimeSpan.TicksPerMinute), DateTimeKind.Utc) - DateTime.Now;
            mailDeletionLabel.Text = "邮件删除倒计时" + diff.Days + "天" + diff.Hours + "时" + diff.Minutes + "分";
            if (returnButton.IsClicked) DialogsManager.HideDialog(this);
            if (iAmSureButton.IsClicked)
            {
                foreach (string pair in LotteryItems)
                {
                    string[] parts = pair.Split(',');
                    if (parts.Length >= 2)
                        m_componentPlayer.m_subsystemPickables.AddPickable(CraftingRecipesManager.DecodeResult(parts[0]), int.Parse(parts[1]), m_componentPlayer.ComponentBody.Position, null, null);
                }
                PermanentlySavedAttributesManager.Mailbox.Remove(iD);
                DialogsManager.HideDialog(this);
            }
        }
    }
}
//活动中心界面
namespace Game
{
    public class EventCenterWidget : CanvasWidget
    {
        public ListPanelWidget typesList;
        public BitmapButtonWidget background;
        public LabelWidget textLabel;
        public ListPanelWidget taskList;

        public EventCenterWidget(ComponentPlayer componentPlayer)
        {
            XElement node = ContentManager.Get<XElement>("Widgets/EventCenterWidget");
            LoadContents(this, node);

            typesList = Children.Find<ListPanelWidget>("TypesList");
            background = Children.Find<BitmapButtonWidget>("Background");
            textLabel = Children.Find<LabelWidget>("TextLabel");
            taskList = Children.Find<ListPanelWidget>("TaskList");

            typesList.ItemWidgetFactory = delegate (object item)
            {
                var accessEventCenter = ((string, string, string, string, string))item;
                XElement node2 = ContentManager.Get<XElement>("Widgets/EventCenterButton");
                var obj = (ContainerWidget)LoadWidget(this, node2, null);
                obj.Children.Find<BitmapButtonWidget>("Icon").NormalSubtexture = obj.Children.Find<BitmapButtonWidget>("Icon").ClickedSubtexture = ContentManager.Get<Texture2D>(accessEventCenter.Item3);
                obj.Children.Find<BitmapButtonWidget>("Select").IsVisible = false;
                obj.Children.Find<LabelWidget>("Introduction").Text = accessEventCenter.Item2;

                return obj;
            };

            taskList.ItemWidgetFactory = delegate (object item)
            {
                var accessEventCenter = ((int, string, string, int, string[], int, string, int, int, int, int, int, int, int, int))item;
                XElement node2 = ContentManager.Get<XElement>("Widgets/ActivityTasks");
                var obj = (ContainerWidget)LoadWidget(this, node2, null);
                float num = 0;
                int text = 0;
                if (accessEventCenter.Item4 > 0)
                {
                    num = PermanentlySavedAttributesManager.ActivityParameters["NumberzOfShellsSpent"];
                    text = accessEventCenter.Item4;
                }
                else if (accessEventCenter.Item6 > 0)
                {
                    num = PermanentlySavedAttributesManager.ActivityParameters["NumberOfQuestionsAndAnswers"];
                    text = accessEventCenter.Item6;
                }
                else if (accessEventCenter.Item7 != "")
                {
                    num = (PermanentlySavedAttributesManager.Stepping[accessEventCenter.Item7] ? 1 : 0);
                    text = 1;
                }
                else if (accessEventCenter.Item8 > 0)
                {
                    if (componentPlayer.PlayerStats.ValuesDictionaryForMods.ContainsKey("TableLevel"))
                        num = (int)componentPlayer.PlayerStats.ValuesDictionaryForMods["TableLevel"];
                    text = accessEventCenter.Item8;
                }
                else if (accessEventCenter.Item9 > 0)
                {
                    if (componentPlayer.PlayerStats.ValuesDictionaryForMods.ContainsKey("CookingTableLevel"))
                        num = (int)componentPlayer.PlayerStats.ValuesDictionaryForMods["CookingTableLevel"];
                    text = accessEventCenter.Item9;
                }
                else if (accessEventCenter.Item10 > 0)
                {
                    if (componentPlayer.PlayerStats.ValuesDictionaryForMods.ContainsKey("MedicineStationLevel"))
                        num = (int)componentPlayer.PlayerStats.ValuesDictionaryForMods["MedicineStationLevel"];
                    text = accessEventCenter.Item10;
                }
                else if (accessEventCenter.Item11 > 0)
                {
                    if (componentPlayer.PlayerStats.ValuesDictionaryForMods.ContainsKey("BedLevel"))
                        num = (int)componentPlayer.PlayerStats.ValuesDictionaryForMods["BedLevel"];
                    text = accessEventCenter.Item11;
                }
                else if (accessEventCenter.Item12 > 0)
                {
                    if (componentPlayer.PlayerStats.ValuesDictionaryForMods.ContainsKey("BoxLevel"))
                        num = (int)componentPlayer.PlayerStats.ValuesDictionaryForMods["BoxLevel"];
                    text = accessEventCenter.Item12;
                }
                else if (accessEventCenter.Item13 > 0)
                {
                    if (componentPlayer.PlayerStats.ValuesDictionaryForMods.ContainsKey("PlantPlateLevel"))
                        num = (int)componentPlayer.PlayerStats.ValuesDictionaryForMods["PlantPlateLevel"];
                    text = accessEventCenter.Item13;
                }
                else if (accessEventCenter.Item14 > 0)
                {
                    if (componentPlayer.PlayerStats.ValuesDictionaryForMods.ContainsKey("BarrierLevel"))
                        num = (int)componentPlayer.PlayerStats.ValuesDictionaryForMods["BarrierLevel"];
                    text = accessEventCenter.Item14;
                }
                else if (accessEventCenter.Item15 > 0)
                {
                    num = (float)Math.Round((componentPlayer.m_subsystemGameInfo.TotalElapsedGameTime - PermanentlySavedAttributesManager.ArchiveProperties[(int)componentPlayer.PlayerStats.ValuesDictionaryForMods["ArchiveID"]]) / 1200, 1);
                    text = accessEventCenter.Item15;
                }
                obj.Children.Find<LabelWidget>("TaskDescription").Text = accessEventCenter.Item3;
                obj.Children.Find<LabelWidget>("TaskProgress").Text = num + "/" + text;
                for (int a = 1; a < 5; a++)
                {
                    if (a < accessEventCenter.Item5.Length + 1)
                    {
                        obj.Children.Find<BitmapButtonWidget>("MoneyButton" + a).NormalSubtexture = obj.Children.Find<BitmapButtonWidget>("MoneyButton" + a).ClickedSubtexture = ContentManager.Get<Texture2D>("Textures/Gui/Money/" + accessEventCenter.Item5[a - 1].Split(',')[0]);
                        obj.Children.Find<BitmapButtonWidget>("MoneyButton" + a).IsVisible = true;
                        if (accessEventCenter.Item5[a - 1].Split(',')[1] == "?")
                            obj.Children.Find<LabelWidget>("Quantity" + a).Text = "X?";
                        else
                            obj.Children.Find<LabelWidget>("Quantity" + a).Text = "X" + accessEventCenter.Item5[a - 1].Split(',')[1];
                    }
                    else
                    {
                        obj.Children.Find<BitmapButtonWidget>("MoneyButton" + a).IsVisible = false;
                        obj.Children.Find<LabelWidget>("Quantity" + a).Text = "";
                    }
                }

                return obj;
            };

            foreach (AccessEventCenter accessEventCenter in AccessEventCenterManager.Data)
            {
                if (accessEventCenter.ActivityText != "")
                {
                    typesList.AddItem((accessEventCenter.ActivityType, accessEventCenter.ActivityText, accessEventCenter.ActivityButtonMap, accessEventCenter.ActivityBackgroundMap, accessEventCenter.ActivityBackgroundText));
                }
            }

            typesList.ItemClicked = delegate (object item)
            {
                var accessEventCenter = ((string, string, string, string, string))item;

                foreach (Widget child in typesList.Children)
                {
                    if (child is ContainerWidget container)
                    {
                        var select = container.Children.Find<BitmapButtonWidget>("Select");
                        if (select != null) select.IsVisible = false;
                    }
                }

                foreach (Widget child in typesList.Children)
                {
                    if (child is ContainerWidget container && container.Tag == item)
                    {
                        var select = container.Children.Find<BitmapButtonWidget>("Select");
                        if (select != null) select.IsVisible = true;
                        break;
                    }
                }

                taskList.ClearItems();

                foreach (AccessEventCenter accessEventCenter2 in AccessEventCenterManager.Data)
                {
                    if (accessEventCenter.Item1 == accessEventCenter2.ActivityType)
                    {
                        taskList.AddItem((accessEventCenter2.ActivityTasksID, accessEventCenter2.ActivityType, accessEventCenter2.ActivityTaskDescription, accessEventCenter2.NumberOfShellsSpent, accessEventCenter2.MoneyItems, accessEventCenter2.NumberOfQuestionsAndAnswers, accessEventCenter2.ExploringTerrainNames, accessEventCenter2.WorkstationLevel, accessEventCenter2.KitchenCounterLevel, accessEventCenter2.MedicalStationLevel, accessEventCenter2.BedLevel, accessEventCenter2.BoxLevel, accessEventCenter2.PlantPlateLevel, accessEventCenter2.BarrierLevel, accessEventCenter2.SurvivalDays));
                    }
                }

                background.NormalSubtexture = background.ClickedSubtexture = ContentManager.Get<Texture2D>(accessEventCenter.Item4);
                textLabel.Text = accessEventCenter.Item5;
            };

            taskList.ItemClicked = delegate (object item)
            {
                var accessEventCenter = ((int, string, string, int, string[], int, string, int, int, int, int, int, int, int, int))item;
                if (accessEventCenter.Item2 == "贝壳狂欢")
                {
                    if (PermanentlySavedAttributesManager.ActivityParameters["NumberzOfShellsSpent"] > accessEventCenter.Item4)
                    {
                        var ActivityCompletion = PermanentlySavedAttributesManager.ActivityCompletion[accessEventCenter.Item1];
                        if (ActivityCompletion.Item1)
                        {
                            componentPlayer.ComponentGui.DisplaySmallMessage("已领取！", Color.Green, true, true);
                        }
                        else
                        {
                            var dict = accessEventCenter.Item5.Select(item => item.Split(',')).ToDictionary(parts => parts[0], parts => int.Parse(parts[1]));
                            foreach (var key in dict.ToList())
                            {
                                PermanentlySavedAttributesManager.Money[key.Key] += key.Value;
                            }
                            DialogsManager.ShowDialog(null, new LotteryItemDisplayDialog("恭喜获得", "", dict));
                            PermanentlySavedAttributesManager.ActivityCompletion[accessEventCenter.Item1] = (true, ActivityCompletion.Item2);
                        }
                    }
                }
                if (accessEventCenter.Item2 == "荒野问答")
                {
                    if (PermanentlySavedAttributesManager.ActivityParameters["NumberOfQuestionsAndAnswers"] == 0)
                    {
                        DialogsManager.ShowDialog(null, new WildernessQuestionAndAnswerDialog());
                    }
                }
                if (accessEventCenter.Item2 == "探险旅程")
                {
                    if (PermanentlySavedAttributesManager.Stepping[accessEventCenter.Item7])
                    {
                        var ActivityCompletion = PermanentlySavedAttributesManager.ActivityCompletion[accessEventCenter.Item1];
                        if (ActivityCompletion.Item1)
                        {
                            componentPlayer.ComponentGui.DisplaySmallMessage("已领取！", Color.Green, true, true);
                        }
                        else
                        {
                            var dict = accessEventCenter.Item5.Select(item => item.Split(',')).ToDictionary(parts => parts[0], parts => int.Parse(parts[1]));
                            foreach (var key in dict.ToList())
                            {
                                PermanentlySavedAttributesManager.Money[key.Key] += key.Value;
                            }
                            DialogsManager.ShowDialog(null, new LotteryItemDisplayDialog("恭喜获得", "", dict));
                            PermanentlySavedAttributesManager.ActivityCompletion[accessEventCenter.Item1] = (true, ActivityCompletion.Item2);
                        }
                    }
                }
                if (accessEventCenter.Item2 == "金窝银窝")
                {
                    if (((int)componentPlayer.PlayerStats.ValuesDictionaryForMods["TableLevel"] > accessEventCenter.Item8 - 1 && accessEventCenter.Item8 != 0) ||
                    ((int)componentPlayer.PlayerStats.ValuesDictionaryForMods["CookingTableLevel"] > accessEventCenter.Item9 - 1 && accessEventCenter.Item9 != 0) ||
                    ((int)componentPlayer.PlayerStats.ValuesDictionaryForMods["MedicineStationLevel"] > accessEventCenter.Item10 - 1 && accessEventCenter.Item10 != 0) ||
                    ((int)componentPlayer.PlayerStats.ValuesDictionaryForMods["BedLevel"] > accessEventCenter.Item11 - 1 && accessEventCenter.Item11 != 0) ||
                    ((int)componentPlayer.PlayerStats.ValuesDictionaryForMods["BoxLevel"] > accessEventCenter.Item12 - 1 && accessEventCenter.Item12 != 0) ||
                    ((int)componentPlayer.PlayerStats.ValuesDictionaryForMods["PlantPlateLevel"] > accessEventCenter.Item13 - 1 && accessEventCenter.Item13 != 0) ||
                    ((int)componentPlayer.PlayerStats.ValuesDictionaryForMods["BarrierLevel"] > accessEventCenter.Item14 - 1 && accessEventCenter.Item14 != 0))
                    {
                        var ActivityCompletion = PermanentlySavedAttributesManager.ActivityCompletion[accessEventCenter.Item1];
                        if (ActivityCompletion.Item1)
                        {
                            componentPlayer.ComponentGui.DisplaySmallMessage("已领取！", Color.Green, true, true);
                        }
                        else
                        {
                            var dict = accessEventCenter.Item5.Select(item => item.Split(',')).ToDictionary(parts => parts[0], parts => int.Parse(parts[1]));
                            foreach (var key in dict.ToList())
                            {
                                PermanentlySavedAttributesManager.Money[key.Key] += key.Value;
                            }
                            DialogsManager.ShowDialog(null, new LotteryItemDisplayDialog("恭喜获得", "", dict));
                            PermanentlySavedAttributesManager.ActivityCompletion[accessEventCenter.Item1] = (true, ActivityCompletion.Item2);
                        }
                    }
                }
                if (accessEventCenter.Item2 == "活着真好")
                {
                    if (Math.Round(componentPlayer.m_subsystemGameInfo.TotalElapsedGameTime - PermanentlySavedAttributesManager.ArchiveProperties[(int)componentPlayer.PlayerStats.ValuesDictionaryForMods["ArchiveID"]] / 1200, 1) > accessEventCenter.Item15 - 1)
                    {
                        var ActivityCompletion = PermanentlySavedAttributesManager.ActivityCompletion[accessEventCenter.Item1];
                        if (ActivityCompletion.Item1)
                        {
                            componentPlayer.ComponentGui.DisplaySmallMessage("已领取！", Color.Green, true, true);
                        }
                        else
                        {
                            var dict = accessEventCenter.Item5.Select(item => item.Split(',')).ToDictionary(parts => parts[0], parts => int.Parse(parts[1]));
                            foreach (var key in dict.ToList())
                            {
                                PermanentlySavedAttributesManager.Money[key.Key] += key.Value;
                            }
                            DialogsManager.ShowDialog(null, new LotteryItemDisplayDialog("恭喜获得", "", dict));
                            PermanentlySavedAttributesManager.ActivityCompletion[accessEventCenter.Item1] = (true, ActivityCompletion.Item2);
                        }
                    }
                }
            };

            typesList.SelectedIndex = 0;
        }

        public override void Update()
        {
        }
    }
}
