//贝壳补齐材料对话
namespace Game
{
    public class ShellSupplementMaterialsDialog : Dialog
    {
        public ListPanelWidget materialsList;
        public LabelWidget quantity;
        public BevelledButtonWidget returnButton;
        public BevelledButtonWidget iAmSureButton;

        public ComponentPlayer m_componentPlayer;
        public Dictionary<string, int> m_lackIngredients;
        public int num = 0;

        public List<(int blockIndex, int damage, int price, int quantity)> m_ingredients;

        public ShellSupplementMaterialsDialog(ComponentPlayer componentPlayer, Dictionary<string, int> lackIngredients)
        {
            m_componentPlayer = componentPlayer;
            m_lackIngredients = lackIngredients;

            LoadContents(this, ContentManager.Get<XElement>("Dialogs/ShellSupplementMaterialsDialog"));

            materialsList = Children.Find<ListPanelWidget>("MaterialsList");
            quantity = Children.Find<LabelWidget>("Quantity");
            returnButton = Children.Find<BevelledButtonWidget>("ReturnButton");
            iAmSureButton = Children.Find<BevelledButtonWidget>("IAmSureButton");

            m_ingredients = new List<(int blockIndex, int damage, int price, int quantity)>();
            foreach (var kvp in lackIngredients)
            {
                string[] safeParts = kvp.Key.Split(':');
                string beforeChar = safeParts[0];
                string afterChar = safeParts.Length > 1 ? safeParts[1] : string.Empty;
                var block = BlocksManager.FindBlocksByCraftingId(beforeChar)[0];
                int blockIndex = block.BlockIndex;
                int damage = string.IsNullOrEmpty(afterChar) ? 0 : int.Parse(afterChar);
                string priceKey = $"{block.GetType().Name}:{damage}";
                int price = AccessCubeAdditionalPropertiesManager.Get(priceKey).Price;
                m_ingredients.Add((blockIndex, damage, price, kvp.Value));
            }

            num = 0;
            for (int i = 0; i < m_ingredients.Count; i++)
            {
                var ing = m_ingredients[i];
                num += ing.price * ing.quantity * 30;
                materialsList.AddItem(i + 1);
            }

            materialsList.ItemWidgetFactory = item =>
            {
                int page = (int)item;
                var widget = (ContainerWidget)LoadWidget(this, ContentManager.Get<XElement>("Widgets/SupplementaryMaterialsItems"), null);
                int baseIndex = (page - 1) * 3;
                for (int i = 1; i <= 3; i++)
                {
                    int idx = baseIndex + i - 1;
                    if (idx < m_ingredients.Count)
                    {
                        var ing = m_ingredients[idx];
                        widget.Children.Find<BlockIconWidget>("Icon" + i).Value = Terrain.MakeBlockValue(ing.blockIndex, 0, ing.damage);
                        widget.Children.Find<LabelWidget>("Quantity" + i).Text = "X" + ing.quantity;
                    }
                    else
                    {
                        widget.Children.Find<BlockIconWidget>("Icon" + i).Value = 0;
                        widget.Children.Find<LabelWidget>("Quantity" + i).Text = "";
                    }
                }
                return widget;
            };
        }

        public override void Update()
        {
            quantity.Text = "X" + num;
            if (returnButton.IsClicked)
            {
                DialogsManager.HideDialog(this);
            }

            if (iAmSureButton.IsClicked)
            {
                if (PermanentlySavedAttributesManager.Money["Shells"] > num - 1)
                {
                    PermanentlySavedAttributesManager.Money["Shells"] -= num;
                    PermanentlySavedAttributesManager.ActivityParameters["NumberzOfShellsSpent"] += num;
                    foreach (var ing in m_ingredients)
                    {
                        m_componentPlayer.m_subsystemPickables.AddPickable(Terrain.MakeBlockValue(ing.blockIndex, 0, ing.damage), ing.quantity, m_componentPlayer.ComponentBody.Position, null, null);
                    }
                }
                else
                {
                    m_componentPlayer.ComponentGui.DisplaySmallMessage("贝壳不足！", Color.Red, true, true);
                }
                DialogsManager.HideDialog(this);
            }
        }
    }
}
