//荒野问答对话
namespace Game
{
    public class WildernessQuestionAndAnswerDialog : Dialog
    {
        public BitmapButtonWidget cancelButton;
        public LabelWidget numberOfTopicsLabel, correctNumbersLabel;
        public ListPanelWidget introductionList, optionsList;
        public BevelledButtonWidget nextQuestionButton;
        public int introPageCount;
        public Random m_random = new Random();

        public WildernessQuestionAndAnswerDialog()
        {
            LoadContents(this, ContentManager.Get<XElement>("Dialogs/WildernessQuestionAndAnswerDialog"));
            cancelButton = Children.Find<BitmapButtonWidget>("CancelButton");
            numberOfTopicsLabel = Children.Find<LabelWidget>("NumberOfTopicsLabel");
            correctNumbersLabel = Children.Find<LabelWidget>("CorrectNumbersLabel");
            introductionList = Children.Find<ListPanelWidget>("IntroductionList");
            optionsList = Children.Find<ListPanelWidget>("OptionsList");
            nextQuestionButton = Children.Find<BevelledButtonWidget>("NextQuestionButton");

            SettingTopics();

            introductionList.ItemWidgetFactory = item =>
            {
                int page = (int)item, start = (page - 1) * 24;
                var widget = (ContainerWidget)LoadWidget(this, ContentManager.Get<XElement>("Widgets/IntroductionToLottery"), null);
                widget.Children.Find<LabelWidget>("Introduction").Text = AccessWildernessQuestionAndAnswerManager.GetAll()[(int)PermanentlySavedAttributesManager.ActivityParameters["QuestionID"]].Question.Substring(start, Math.Min(24, AccessWildernessQuestionAndAnswerManager.GetAll()[(int)PermanentlySavedAttributesManager.ActivityParameters["QuestionID"]].Question.Length - start));
                return widget;
            };

            optionsList.ItemWidgetFactory = item =>
            {
                var (page, hasValue) = ((int, bool?))item;
                var widget = (ContainerWidget)LoadWidget(this, ContentManager.Get<XElement>("Widgets/Options"), null);
                widget.Children.Find<BitmapButtonWidget>("RightWrong").IsVisible = hasValue.HasValue;
                widget.Children.Find<LabelWidget>("OptionsLabel").Text = AccessWildernessQuestionAndAnswerManager.GetAll()[(int)PermanentlySavedAttributesManager.ActivityParameters["QuestionID"]].Options[page - 1];
                if (hasValue.HasValue)
                    widget.Children.Find<BitmapButtonWidget>("RightWrong").NormalSubtexture = widget.Children.Find<BitmapButtonWidget>("RightWrong").ClickedSubtexture = ContentManager.Get<Texture2D>("Textures/Gui/Activity/Options" + hasValue.Value.ToString());
                return widget;
            };

            optionsList.ItemClicked = item =>
            {
                if (nextQuestionButton.IsVisible) return;
                var (selected, _) = ((int, bool?))item;
                var currentQA = AccessWildernessQuestionAndAnswerManager.GetAll()[(int)PermanentlySavedAttributesManager.ActivityParameters["QuestionID"]];
                optionsList.ClearItems();
                for (int i = 1; i <= currentQA.Options.Length; i++)
                {
                    if (i == selected)
                    {
                        bool isCorrect = selected == currentQA.Answer + 1;
                        if (isCorrect) PermanentlySavedAttributesManager.ActivityParameters["CorrectNumbers"]++;
                        optionsList.AddItem((selected, (bool?)isCorrect));
                    }
                    else optionsList.AddItem((i, (bool?)null));
                }
                nextQuestionButton.IsVisible = true;
            };

            nextQuestionButton.IsVisible = false;
        }

        public override void Update()
        {
            var param = PermanentlySavedAttributesManager.ActivityParameters;
            numberOfTopicsLabel.Text = $"第{param["NumberOfTopics"]}题";
            correctNumbersLabel.Text = $"已答对：{param["CorrectNumbers"]}/5";

            if (cancelButton.IsClicked) DialogsManager.HideDialog(this);

            if (nextQuestionButton.IsClicked)
            {
                if ((int)param["NumberOfTopics"] == 5)
                {
                    DialogsManager.ShowDialog(null, new WildernessQuestionAndAnswerReceivingAwardsDialog());
                    DialogsManager.HideDialog(this);
                }
                else
                {
                    param["QuestionID"] = m_random.Int(0, AccessWildernessQuestionAndAnswerManager.Data.Count - 1);
                    param["NumberOfTopics"] = (int)param["NumberOfTopics"] + 1;
                    SettingTopics();
                    nextQuestionButton.IsVisible = false;
                }
            }
        }

        public virtual void SettingTopics()
        {
            introductionList.ClearItems();
            optionsList.ClearItems();
            var currentQA = AccessWildernessQuestionAndAnswerManager.GetAll()[(int)PermanentlySavedAttributesManager.ActivityParameters["QuestionID"]];
            introPageCount = (int)Math.Ceiling(currentQA.Question.Length / 24.0);
            for (int i = 1; i <= introPageCount; i++) introductionList.AddItem(i);
            for (int a = 1; a <= currentQA.Options.Length; a++) optionsList.AddItem(((int, bool?))(a, null));
        }
    }
}
