        public WildernessQuestionAndAnswerReceivingAwardsDialog()
        {
            LoadContents(this, ContentManager.Get<XElement>("Dialogs/WildernessQuestionAndAnswerReceivingAwardsDialog"));
            cancelButton = Children.Find<BitmapButtonWidget>("CancelButton");
            answerLogarithmsLabel = Children.Find<LabelWidget>("AnswerLogarithmsLabel");
            shellsButton = Children.Find<BitmapButtonWidget>("ShellsButton");
            shellsLabel = Children.Find<LabelWidget>("ShellsLabel");
            survivalManualButton = Children.Find<BitmapButtonWidget>("SurvivalManualButton");
            survivalManualLabel = Children.Find<LabelWidget>("SurvivalManualLabel");
            receiveRewardsButton = Children.Find<BevelledButtonWidget>("ReceiveRewardsButton");
            shellsButton.IsVisible = false;
            survivalManualButton.IsVisible = false;
        }

        public override void Update()
        {
            int correct = (int)PermanentlySavedAttributesManager.ActivityParameters["CorrectNumbers"];
            answerLogarithmsLabel.Text = "共答对：" + correct;
            if (correct > 0)
            {
                shellsButton.IsVisible = true;
                shellsLabel.Text = "X" + (correct * 10);
            }
            int manuals = correct / 5;
            if (manuals > 0)
            {
                survivalManualButton.IsVisible = true;
                survivalManualLabel.Text = "X" + (manuals * 10);
            }
            if (cancelButton.IsClicked)
                DialogsManager.HideDialog(this);
            if (receiveRewardsButton.IsClicked)
            {
                PermanentlySavedAttributesManager.Money["Shells"] += correct * 10;
                PermanentlySavedAttributesManager.Money["SurvivalManual"] += manuals * 10;
                PermanentlySavedAttributesManager.ActivityParameters["NumberOfQuestionsAndAnswers"] = 1;
                DialogsManager.HideDialog(this);
            }
        }
    }
}
