namespace Game
{
    public class AdvertisingLotteryWidget : CanvasWidget
    {
        public UShapedLotteryWidget uShapedLotteryButton;
        public BevelledButtonWidget extractionButton;
        public ComponentPlayer m_componentPlayer;
        public Random m_random = new Random();

        public AdvertisingLotteryWidget(ComponentPlayer componentPlayer)
        {
            m_componentPlayer = componentPlayer;
            LoadContents(this, ContentManager.Get<XElement>("Widgets/AdvertisingLotteryWidget"));
            uShapedLotteryButton = Children.Find<UShapedLotteryWidget>("UShapedLotteryButton");
            extractionButton = Children.Find<BevelledButtonWidget>("ExtractionButton");
        }

        public override void Update()
        {
            if (extractionButton.IsClicked)
                if ((int)PermanentlySavedAttributesManager.ActivityParameters["AdvertisingLotteryNumber"] < 11)
                    uShapedLotteryButton.StartLottery();
                else
                    m_componentPlayer.ComponentGui.DisplaySmallMessage("今日抽奖次数达到上限，明天再来", Color.Red, true, true);

            if (uShapedLotteryButton.GetResultIndex().HasValue)
            {
                var items = AccessLotteryManager.Get(uShapedLotteryButton.GetResultType() + 1).LotteryItems;
                var groups = new List<string[]>();
                for (int i = 0; i < items.Length; i++)
                {
                    string[] parts = items[i].Split('/');
                    if (parts.Length >= 2)
                        groups.Add(parts);
                }

                if (groups.Count > 0)
                {
                    string[] chosen = groups[m_random.Int(groups.Count)];
                    var obtained = new Dictionary<string, int>();
                    for (int j = 0; j < chosen.Length; j++)
                    {
                        string[] pair = chosen[j].Split(',');
                        if (pair.Length == 2)
                            obtained[pair[0]] = int.Parse(pair[1]);
                    }

                    uShapedLotteryButton.m_resultReady = false;
                    DialogsManager.ShowDialog(null, new LotteryItemDisplayDialog(
                        AccessLotteryManager.Get(1).Title,
                        AccessLotteryManager.Get(1).Introduction,
                        obtained));

                    foreach (var kv in obtained)
                    {
                        if (kv.Key.Contains(":"))
                            m_componentPlayer.m_subsystemPickables.AddPickable(
                                CraftingRecipesManager.DecodeResult(kv.Key),
                                kv.Value,
                                m_componentPlayer.ComponentBody.Position,
                                null, null);
                        else
                            PermanentlySavedAttributesManager.Money[kv.Key] += kv.Value;
                    }
                }

                PermanentlySavedAttributesManager.ActivityParameters["AdvertisingLotteryNumber"] =
                    (int)PermanentlySavedAttributesManager.ActivityParameters["AdvertisingLotteryNumber"] + 1;
            }
        }
    }
}
//U形抽奖界面
namespace Game
{
    public class UShapedLotteryWidget : CanvasWidget
    {
        public int VerticalCells { get; set; }
        public int HorizontalCells { get; set; }
        public float CellSize { get; set; }
        public float Scale { get; set; }
        public float AnimDuration { get; set; }
        public int MinCycles { get; set; }
        public int MaxCycles { get; set; }
        public Subtexture GoldTexture { get; set; }
        public Subtexture SilverTexture { get; set; }
        public Subtexture CopperTexture { get; set; }
        public Color HighlightBorderColor { get; set; }
        public Color SlotBackgroundColor { get; set; }
        public Color SlotBorderColor { get; set; }
        public int SilverChestCount { get; set; }
        public bool AutoResetOnLoad { get; set; }

        public int m_totalCells;
        public Widget[] m_slots;
        public int[] m_slotTypes;
        public bool[] m_cellsExtracted;
        public RectangleWidget[] m_iconWidgets;
        public RectangleWidget[] m_highlightWidgets;
        public LabelWidget[] m_statusLabels;
        public Point2[] m_cellPositions;
        public bool m_isBuilt;

        public bool m_isRunning;
        public float m_animProgress;
        public float m_totalDistance;
        public int m_highlightIndex;
        public int m_targetIndex;
        public float m_elapsedTime;

        public int m_resultIndex;
        public int m_resultType;
        public bool m_resultReady;
        public Random m_rand;

        public Vector2 m_baseIconSize;

        public UShapedLotteryWidget()
        {
            IsDrawRequired = true;
            ClampToBounds = true;
            m_rand = new Random();
            VerticalCells = 7;
            HorizontalCells = 5;
            CellSize = 72f;
            Scale = 1f;
            AnimDuration = 3f;
            MinCycles = 4;
            MaxCycles = 6;
            HighlightBorderColor = new Color(255, 215, 0);
            SlotBackgroundColor = new Color(32, 32, 32);
            SlotBorderColor = new Color(64, 64, 64);
            SilverChestCount = 2;
            AutoResetOnLoad = false;
        }

        public override void LoadContents(object eventsTarget, System.Xml.Linq.XElement node)
        {
            base.LoadContents(eventsTarget, node);
            if (!m_isBuilt)
            {
                BuildSlots();
                m_isBuilt = true;
                ResetPool();
            }
            else if (AutoResetOnLoad)
            {
                ResetPool();
            }
        }

        public void BuildSlots()
        {
            if (m_slots != null)
                foreach (var s in m_slots) Children.Remove(s);

            m_totalCells = 2 * VerticalCells + HorizontalCells;
            m_slotTypes = new int[m_totalCells];
            m_cellsExtracted = new bool[m_totalCells];
            m_iconWidgets = new RectangleWidget[m_totalCells];
            m_highlightWidgets = new RectangleWidget[m_totalCells];
            m_statusLabels = new LabelWidget[m_totalCells];
            m_cellPositions = new Point2[m_totalCells];
            m_slots = new Widget[m_totalCells];

            int idx = 0;
            for (int y = 0; y < VerticalCells; y++)
                m_cellPositions[idx++] = new Point2(0, y);
            for (int x = 1; x <= HorizontalCells; x++)
                m_cellPositions[idx++] = new Point2(x, VerticalCells - 1);
            for (int y = VerticalCells - 1; y >= 0; y--)
                m_cellPositions[idx++] = new Point2(HorizontalCells + 1, y);

            m_baseIconSize = new Vector2(CellSize * 0.8f);

            for (int i = 0; i < m_totalCells; i++)
            {
                var slot = new CanvasWidget { Size = new Vector2(CellSize, CellSize) };

                slot.Children.Add(new RectangleWidget
                {
                    FillColor = SlotBackgroundColor,
                    OutlineColor = SlotBorderColor,
                    Size = new Vector2(CellSize, CellSize)
                });

                var icon = new RectangleWidget
                {
                    FillColor = Color.White,
                    OutlineColor = Color.Transparent,
                    HorizontalAlignment = WidgetAlignment.Center,
                    VerticalAlignment = WidgetAlignment.Center,
                    Size = m_baseIconSize
                };
                slot.Children.Add(icon);
                m_iconWidgets[i] = icon;

                var highlight = new RectangleWidget
                {
                    FillColor = Color.Transparent,
                    OutlineColor = Color.Transparent,
                    Size = new Vector2(CellSize, CellSize),
                    OutlineThickness = 3f
                };
                slot.Children.Add(highlight);
                m_highlightWidgets[i] = highlight;

                var label = new LabelWidget
                {
                    Text = "已抽取",
                    Color = Color.Red,
                    FontScale = 0.7f,
                    HorizontalAlignment = WidgetAlignment.Center,
                    VerticalAlignment = WidgetAlignment.Center,
                    IsVisible = false
                };
                slot.Children.Add(label);
                m_statusLabels[i] = label;

                m_slots[i] = slot;
                Children.Add(slot);
            }
        }

        public void ResetPool()
        {
            for (int i = 0; i < m_totalCells; i++)
            {
                m_slotTypes[i] = 0;
                m_cellsExtracted[i] = false;
            }

            int bottomCenterIndex = VerticalCells + HorizontalCells / 2;
            int goldIndex = bottomCenterIndex;
            if (HorizontalCells % 2 == 0)
            {
                int left = bottomCenterIndex - 1;
                int right = bottomCenterIndex;
                goldIndex = m_rand.Int(2) == 0 ? left : right;
            }
            m_slotTypes[goldIndex] = 2;

            var availableIndices = Enumerable.Range(0, m_totalCells)
                .Where(i => i != goldIndex)
                .ToList();
            var sorted = availableIndices
                .OrderBy(i => Math.Abs(m_cellPositions[i].X - m_cellPositions[goldIndex].X) +
                              Math.Abs(m_cellPositions[i].Y - m_cellPositions[goldIndex].Y))
                .ThenBy(_ => m_rand.Int())
                .ToList();

            int silverToPlace = Math.Min(SilverChestCount, sorted.Count);
            for (int i = 0; i < silverToPlace; i++)
                m_slotTypes[sorted[i]] = 1;

            for (int i = 0; i < m_totalCells; i++)
            {
                m_iconWidgets[i].Subtexture = m_slotTypes[i] switch
                {
                    2 => GoldTexture,
                    1 => SilverTexture,
                    _ => CopperTexture
                };
                m_iconWidgets[i].IsVisible = true;
                m_statusLabels[i].IsVisible = false;
                m_iconWidgets[i].Size = m_baseIconSize;
            }
        }

        public void StartLottery()
        {
            if (m_isRunning || m_totalCells == 0) return;

            var available = new List<int>();
            for (int i = 0; i < m_totalCells; i++)
                if (!m_cellsExtracted[i])
                    available.Add(i);
            if (available.Count == 0) return;

            m_targetIndex = available[m_rand.Int(available.Count)];

            int cycles = m_rand.Int(MaxCycles - MinCycles + 1) + MinCycles;
            m_totalDistance = cycles * m_totalCells + m_targetIndex;

            m_isRunning = true;
            m_resultReady = false;
            m_animProgress = 0f;
            m_elapsedTime = 0f;
            m_highlightIndex = 0;
        }

        public override void Update()
        {
            base.Update();
            if (!m_isRunning) return;

            m_elapsedTime += 0.016f;
            float t = MathUtils.Saturate(m_elapsedTime / AnimDuration);
            float eased = 1f - (1f - t) * (1f - t);
            m_animProgress = eased * m_totalDistance;

            int newIndex = ((int)m_animProgress) % m_totalCells;
            if (newIndex != m_highlightIndex)
            {
                m_iconWidgets[m_highlightIndex].Size = m_baseIconSize;
                m_highlightWidgets[m_highlightIndex].OutlineColor = Color.Transparent;
                m_highlightIndex = newIndex;
                m_highlightWidgets[m_highlightIndex].OutlineColor = HighlightBorderColor;
                m_iconWidgets[m_highlightIndex].Size = new Vector2(m_baseIconSize.X * Scale, m_baseIconSize.Y * Scale);
            }

            if (t >= 1f || m_animProgress >= m_totalDistance - 0.001f)
            {
                if (m_highlightIndex != m_targetIndex)
                {
                    m_iconWidgets[m_highlightIndex].Size = m_baseIconSize;
                    m_highlightWidgets[m_highlightIndex].OutlineColor = Color.Transparent;
                    m_highlightIndex = m_targetIndex;
                    m_highlightWidgets[m_highlightIndex].OutlineColor = HighlightBorderColor;
                    m_iconWidgets[m_highlightIndex].Size = new Vector2(m_baseIconSize.X * Scale, m_baseIconSize.Y * Scale);
                }
                m_iconWidgets[m_highlightIndex].Size = m_baseIconSize;
                m_highlightWidgets[m_highlightIndex].OutlineColor = Color.Transparent;
                m_isRunning = false;

                m_resultIndex = m_highlightIndex;
                m_resultType = m_slotTypes[m_resultIndex];
                m_resultReady = true;

                m_cellsExtracted[m_resultIndex] = true;
                m_iconWidgets[m_resultIndex].IsVisible = false;
                m_statusLabels[m_resultIndex].IsVisible = true;

                if (m_resultType == 2)
                    ResetPool();
            }
        }

        public override void MeasureOverride(Vector2 parentAvailableSize)
        {
            float totalWidth = (HorizontalCells + 2) * CellSize;
            float totalHeight = VerticalCells * CellSize;
            DesiredSize = new Vector2(totalWidth, totalHeight);
            base.MeasureOverride(parentAvailableSize);
        }

        public override void ArrangeOverride()
        {
            for (int i = 0; i < m_totalCells; i++)
            {
                Vector2 pos = new Vector2(m_cellPositions[i].X * CellSize, m_cellPositions[i].Y * CellSize);
                SetWidgetPosition(m_slots[i], pos);
            }
            base.ArrangeOverride();
        }

        public int? GetResultIndex() { return m_resultReady ? m_resultIndex : null; }
        public int GetResultType() { return m_resultReady ? m_resultType : -1; }
        public int[] GetPoolState() { return (int[])m_slotTypes.Clone(); }
    }
}
//字典键非int型经理大全
namespace Game
{
    // 通用泛型基类，键类型 TKey 由子类指定，键名通过参数传入
    public abstract class DictDataManager<T, TKey> where T : new()
    {
        public static readonly Dictionary<TKey, T> Data = new Dictionary<TKey, T>();
        public static T Get(TKey id) => Data.TryGetValue(id, out var t) ? t : default;
        public static IReadOnlyDictionary<TKey, T> All => Data;

        // 核心初始化方法，需显式传入键的属性名（例如 "BlockID" 或 "ID"）
        public static void Initialize(string xmlPath, string keyPropertyName)
        {
            if (Data.Count > 0) return;
            foreach (var elem in ContentManager.Get<XElement>(xmlPath).Descendants(typeof(T).Name))
            {
                var method = typeof(XmlUtils).GetMethod("GetAttributeValue", new[] { typeof(XElement), typeof(string) });
                var generic = method.MakeGenericMethod(typeof(TKey));
                TKey id = (TKey)generic.Invoke(null, new object[] { elem, keyPropertyName });
                Data[id] = AutoFill(elem);
            }
        }

        public static T AutoFill(XElement elem)
        {
            T obj = new T();
            foreach (var field in typeof(T).GetFields(BindingFlags.Public | BindingFlags.Instance))
            {
                var attr = elem.Attribute(field.Name);
                if (attr == null) continue;
                try
                {
                    object value;
                    Type type = field.FieldType;
                    if (type.IsArray)
                        value = ParseArray(attr.Value, type.GetElementType(), elem, field.Name);
                    else if (IsSimpleType(type))
                        value = ConvertValue(attr.Value, type);
                    else
                    {
                        var m = typeof(XmlUtils).GetMethod("GetAttributeValue", new[] { typeof(XElement), typeof(string) });
                        var gm = m.MakeGenericMethod(type);
                        value = gm.Invoke(null, new object[] { elem, field.Name });
                    }
                    field.SetValue(obj, value);
                }
                catch { }
            }
            return obj;
        }

        public static object ParseArray(string raw, Type elementType, XElement elem, string fieldName)
        {
            if (string.IsNullOrEmpty(raw)) return Array.CreateInstance(elementType, 0);
            string[] parts = raw.Split(';');
            Array arr = Array.CreateInstance(elementType, parts.Length);
            for (int i = 0; i < parts.Length; i++)
            {
                object itemVal;
                if (IsSimpleType(elementType))
                    itemVal = ConvertValue(parts[i], elementType);
                else
                {
                    var m = typeof(XmlUtils).GetMethod("GetAttributeValue", new[] { typeof(XElement), typeof(string) });
                    var gm = m.MakeGenericMethod(elementType);
                    itemVal = gm.Invoke(null, new object[] { elem, fieldName });
                }
                arr.SetValue(itemVal, i);
            }
            return arr;
        }

        public static bool IsSimpleType(Type type)
        {
            if (type == typeof(string) || type == typeof(int) || type == typeof(float) ||
                type == typeof(bool) || type == typeof(double) || type.IsEnum) return true;
            if (Nullable.GetUnderlyingType(type) != null) return true;
            return false;
        }

        public static object ConvertValue(string value, Type targetType)
        {
            Type underlying = Nullable.GetUnderlyingType(targetType);
            if (underlying != null) return string.IsNullOrEmpty(value) ? null : ConvertValue(value, underlying);
            if (targetType == typeof(string)) return value;
            if (targetType == typeof(int)) return int.Parse(value);
            if (targetType == typeof(float)) return float.Parse(value);
            if (targetType == typeof(bool)) return bool.Parse(value);
            if (targetType == typeof(double)) return double.Parse(value);
            if (targetType.IsEnum) return Enum.Parse(targetType, value);
            throw new NotSupportedException();
        }
    }
}
//字典键int型经理大全
namespace Game
{
    // int 键的默认实现（使用 BlockID）
    public abstract class DictDataManager<T> : DictDataManager<T, int> where T : new()
    {
        // 封装默认键名，保持老用法不变
        public static void Initialize(string xmlPath)
        {
            DictDataManager<T, int>.Initialize(xmlPath, "BlockID");
        }
    }
