namespace Game
{
    // 列表管理器（无键）
    public abstract class ListDataManager<T> where T : new()
    {
        public static readonly List<T> Data = new List<T>();
        public static List<T> GetAll() => Data;

        public static void Initialize(string xmlPath)
        {
            if (Data.Count > 0) return;
            foreach (var elem in ContentManager.Get<XElement>(xmlPath).Descendants(typeof(T).Name))
                Data.Add(AutoFill(elem));
        }

        public static T AutoFill(XElement elem)
        {
            T obj = new T();
            foreach (var field in typeof(T).GetFields(BindingFlags.Public | BindingFlags.Instance))
            {
                var attr = elem.Attribute(field.Name);
                if (attr == null) continue;
                try
                {
                    object value;
                    Type type = field.FieldType;
                    if (type.IsArray)
                        value = ParseArray(attr.Value, type.GetElementType(), elem, field.Name);
                    else if (IsSimpleType(type))
                        value = ConvertValue(attr.Value, type);
                    else
                    {
                        var m = typeof(XmlUtils).GetMethod("GetAttributeValue", new[] { typeof(XElement), typeof(string) });
                        var gm = m.MakeGenericMethod(type);
                        value = gm.Invoke(null, new object[] { elem, field.Name });
                    }
                    field.SetValue(obj, value);
                }
                catch { }
            }
            return obj;
        }

        public static object ParseArray(string raw, Type elementType, XElement elem, string fieldName)
        {
            if (string.IsNullOrEmpty(raw)) return Array.CreateInstance(elementType, 0);
            string[] parts = raw.Split(';');
            Array arr = Array.CreateInstance(elementType, parts.Length);
            for (int i = 0; i < parts.Length; i++)
            {
                object itemVal;
                if (IsSimpleType(elementType))
                    itemVal = ConvertValue(parts[i], elementType);
                else
                {
                    var m = typeof(XmlUtils).GetMethod("GetAttributeValue", new[] { typeof(XElement), typeof(string) });
                    var gm = m.MakeGenericMethod(elementType);
                    itemVal = gm.Invoke(null, new object[] { elem, fieldName });
                }
                arr.SetValue(itemVal, i);
            }
            return arr;
        }

        public static bool IsSimpleType(Type type)
        {
            if (type == typeof(string) || type == typeof(int) || type == typeof(float) ||
                type == typeof(bool) || type == typeof(double) || type.IsEnum) return true;
            if (Nullable.GetUnderlyingType(type) != null) return true;
            return false;
        }

        public static object ConvertValue(string value, Type targetType)
        {
            Type underlying = Nullable.GetUnderlyingType(targetType);
            if (underlying != null) return string.IsNullOrEmpty(value) ? null : ConvertValue(value, underlying);
            if (targetType == typeof(string)) return value;
            if (targetType == typeof(int)) return int.Parse(value);
            if (targetType == typeof(float)) return float.Parse(value);
            if (targetType == typeof(bool)) return bool.Parse(value);
            if (targetType == typeof(double)) return double.Parse(value);
            if (targetType.IsEnum) return Enum.Parse(targetType, value);
            throw new NotSupportedException();
        }
    }
}
//子系统多维世界
namespace Game
{
    public enum WorldTransferType { ToLastWorld, ChildToMajor, MajorToChild, ChildToChild }

    public class SubsystemWorld : Subsystem, IUpdateable
    {
        public SubsystemTerrain m_subsystemTerrain;
        public SubsystemGameInfo m_subsystemGameInfo;
        public SubsystemBodies m_subsystemBodies;
        public SubsystemTime m_subsystemTime;
        public SubsystemSpawn m_subsystemSpawn;
        public PrimitivesRenderer3D m_primitivesRenderer3D = new PrimitivesRenderer3D();
        public ComponentPlayer m_componentPlayer;
        public List<Entity> m_creatureEntitys = new List<Entity>();
        public string m_worldPath;
        public string LastWorldPath = string.Empty;
        public bool m_initialize;
        public Random m_random = new Random();
        public SubsystemPlayers m_subsystemPlayers;
        public UpdateOrder UpdateOrder => UpdateOrder.Default;
        public event Action<ComponentPlayer> ChangeWorldEvent;
        public event Action<Entity> LoadCreatureEntityBegin;
        public event Action<Entity> LoadCreatureEntityEnd;
        public bool ProhibitTransmission = true;
        public List<string> MultidimensionalWorlds = new List<string> { "MainWorld" };
        public bool m_portalGenerated;
        public string m_pendingTransferPath;
        public bool m_isTransferring;
        public string WorldName = "";
        public double m_lastTransferTime = -10;

        public void Update(float dt)
        {
            if (m_componentPlayer == null || m_isTransferring) return;
            if (!string.IsNullOrEmpty(m_pendingTransferPath))
            {
                string current = GameManager.WorldInfo.DirectoryName;
                if (m_pendingTransferPath != current)
                {
                    m_isTransferring = true;
                    ChangeWorld(current, m_pendingTransferPath);
                    return;
                }
                m_pendingTransferPath = null;
            }
            if (!m_initialize) PerformInitialization();
            if (m_subsystemTime.GameTime - m_lastTransferTime < 5.0) return;
            Point3 underFoot = new Point3(
                (int)MathF.Floor(m_componentPlayer.ComponentBody.Position.X),
                (int)MathF.Floor(m_componentPlayer.ComponentBody.Position.Y - 0.5f),
                (int)MathF.Floor(m_componentPlayer.ComponentBody.Position.Z));
            int blockValue = m_subsystemTerrain.Terrain.GetCellValueFast(underFoot.X, underFoot.Y, underFoot.Z);
            string curWorldName = Path.GetFileName(m_worldPath.Replace("\\", "/"));
            foreach (var kvp in AccessMultidimensionalWorldManager.All)
            {
                if (blockValue != CraftingRecipesManager.DecodeResult(kvp.Value.TransportCubeClassName)) continue;
                if (ProhibitTransmission)
                {
                    m_componentPlayer.ComponentGui.DisplaySmallMessage("刚进入世界10秒内禁止传送，请等待片刻", Color.Red, false, false);
                    return;
                }
                m_isTransferring = true;
                bool success;
                if (IsChildWorld(m_worldPath))
                    success = InternalTransfer(null, WorldTransferType.ChildToMajor, null);
                else
                {
                    if (kvp.Key == curWorldName) { m_isTransferring = false; return; }
                    success = InternalTransfer(kvp.Key, WorldTransferType.MajorToChild, null);
                }
                if (!success) m_isTransferring = false;
                break;
            }
        }

        public void PerformInitialization()
        {
            m_initialize = true;
            Point3 p = new Point3(m_componentPlayer.ComponentBody.Position);
            foreach (Entity creature in m_creatureEntitys)
            {
                LoadCreatureEntityBegin?.Invoke(creature);
                Point3 spawn = Point3.Zero;
                for (int yo = 0; yo <= 5; yo++)
                {
                    int x = p.X + m_random.Int(-5, 5), y = p.Y + yo, z = p.Z + m_random.Int(-5, 5);
                    if (m_subsystemTerrain.Terrain.GetCellContents(x, y, z) == 0) { spawn = new Point3(x, y, z); break; }
                }
                if (spawn == Point3.Zero) spawn = p;
                ComponentBody body = creature.FindComponent<ComponentBody>();
                body.Position = new Vector3(spawn.X, spawn.Y, spawn.Z);
                body.Rotation = Quaternion.CreateFromAxisAngle(Vector3.UnitY, m_random.Float(0f, MathF.PI * 2));
                creature.FindComponent<ComponentSpawn>().SpawnDuration = 0f;
                Project.AddEntity(creature);
            }
            m_creatureEntitys.ForEach(e => LoadCreatureEntityEnd?.Invoke(e));
            m_creatureEntitys.Clear();
            if (!m_portalGenerated && AccessMultidimensionalWorldManager.All.ContainsKey(Path.GetFileName(m_worldPath.Replace("\\", "/"))) && IsChildWorld(m_worldPath))
            {
                m_portalGenerated = true;
                m_subsystemTime.QueueGameTimeDelayedExecution(m_subsystemTime.GameTime + 0.5, GeneratePortal);
            }
        }

        public override void Load(ValuesDictionary valuesDictionary)
        {
            m_subsystemPlayers = Project.FindSubsystem<SubsystemPlayers>();
            m_subsystemTime = Project.FindSubsystem<SubsystemTime>();
            m_subsystemGameInfo = Project.FindSubsystem<SubsystemGameInfo>();
            m_subsystemTerrain = Project.FindSubsystem<SubsystemTerrain>();
            m_subsystemBodies = Project.FindSubsystem<SubsystemBodies>();
            m_subsystemSpawn = Project.FindSubsystem<SubsystemSpawn>();

            if (AccessMultidimensionalWorldManager.All.Count == 0)
                AccessMultidimensionalWorldManager.Initialize("AccessMultidimensionalWorldManager");

            string currentWorldPath = GameManager.WorldInfo?.DirectoryName ?? ScreensManager.FindScreen<GameLoadingScreen>("GameLoading").m_worldInfo.DirectoryName;
            string savedWorldPath = valuesDictionary.GetValue<string>("WorldPath", currentWorldPath);
            m_worldPath = currentWorldPath;

            if (!string.IsNullOrEmpty(savedWorldPath) && savedWorldPath != currentWorldPath && Storage.DirectoryExists(savedWorldPath))
                m_pendingTransferPath = savedWorldPath;
            else if (savedWorldPath != currentWorldPath)
            {
                XElement project;
                using (Stream s = Storage.OpenFile(Path.Combine(currentWorldPath, "Project.xml"), OpenFileMode.Read))
                    project = XmlUtils.LoadXmlFromStream(s, null, true);
                XElement subsystems = project.Element("Subsystems");
                XElement subWorld = subsystems?.Elements().FirstOrDefault(e => (string)e.Attribute("Name") == "World");
                if (subWorld == null)
                {
                    subWorld = new XElement("Values", new XAttribute("Name", "World"));
                    subsystems?.Add(subWorld);
                }
                XElement valElem = subWorld?.Elements("Value").FirstOrDefault(e => (string)e.Attribute("Name") == "WorldPath");
                if (valElem == null)
                {
                    valElem = new XElement("Value", new XAttribute("Name", "WorldPath"), new XAttribute("Type", "string"));
                    subWorld?.Add(valElem);
                }
                valElem?.SetAttributeValue("Value", currentWorldPath);
                using (Stream s = Storage.OpenFile(Path.Combine(currentWorldPath, "Project.xml"), OpenFileMode.Create))
                    XmlUtils.SaveXmlToStream(project, s, null, true);
            }

            WorldName = Path.GetFileName(currentWorldPath.Replace("\\", "/"));
            if (WorldName == "") WorldName = "MainWorld";

            LastWorldPath = valuesDictionary.GetValue("LastWorldPath", m_worldPath);
            m_subsystemTime.QueueGameTimeDelayedExecution(m_subsystemTime.GameTime + 10f, () => ProhibitTransmission = false);
            m_initialize = false;
            m_portalGenerated = valuesDictionary.GetValue<bool>("PortalGenerated", false);
            LoadAndSpawnCreatures(valuesDictionary);
            base.Load(valuesDictionary);

            if (IsChildWorld(m_worldPath))
            {
                string masterPath = Path.GetDirectoryName(m_worldPath);
                if (!string.IsNullOrEmpty(masterPath) && Storage.DirectoryExists(masterPath))
                {
                    XElement masterProj;
                    using (Stream s = Storage.OpenFile(Path.Combine(masterPath, "Project.xml"), OpenFileMode.Read))
                        masterProj = XmlUtils.LoadXmlFromStream(s, null, true);
                    XElement masterGameInfo = masterProj.Element("Subsystems")?.Elements("Values").FirstOrDefault(e => (string)e.Attribute("Name") == "GameInfo");
                    if (masterGameInfo != null)
                    {
                        string gameMode = masterGameInfo.Elements("Value").FirstOrDefault(e => (string)e.Attribute("Name") == "GameMode")?.Attribute("Value")?.Value;
                        if (!string.IsNullOrEmpty(gameMode))
                        {
                            var currentGameInfo = Project.FindSubsystem<SubsystemGameInfo>();
                            if (currentGameInfo != null && currentGameInfo.WorldSettings.GameMode.ToString() != gameMode)
                            {
                                currentGameInfo.WorldSettings.GameMode = (GameMode)Enum.Parse(typeof(GameMode), gameMode);
                                m_subsystemTime.QueueGameTimeDelayedExecution(m_subsystemTime.GameTime + 0.1, () =>
                                {
                                    XElement proj;
                                    using (Stream s = Storage.OpenFile(Path.Combine(m_worldPath, "Project.xml"), OpenFileMode.Read))
                                        proj = XmlUtils.LoadXmlFromStream(s, null, true);
                                    XElement gi = proj.Element("Subsystems")?.Elements("Values").FirstOrDefault(e => (string)e.Attribute("Name") == "GameInfo");
                                    if (gi == null)
                                    {
                                        gi = new XElement("Values", new XAttribute("Name", "GameInfo"));
                                        proj.Element("Subsystems")?.Add(gi);
                                    }
                                    XElement gmElem = gi.Elements("Value").FirstOrDefault(e => (string)e.Attribute("Name") == "GameMode");
                                    if (gmElem == null)
                                    {
                                        gmElem = new XElement("Value", new XAttribute("Name", "GameMode"), new XAttribute("Type", "string"));
                                        gi.Add(gmElem);
                                    }
                                    gmElem.SetAttributeValue("Value", gameMode);
                                    using (Stream s = Storage.OpenFile(Path.Combine(m_worldPath, "Project.xml"), OpenFileMode.Create))
                                        XmlUtils.SaveXmlToStream(proj, s, null, true);
                                });
                            }
                        }
                    }
                }
            }
        }

        public override void Save(ValuesDictionary valuesDictionary)
        {
            valuesDictionary.SetValue("WorldPath", m_worldPath);
            valuesDictionary.SetValue("LastWorldPath", LastWorldPath);
            valuesDictionary.SetValue("PortalGenerated", m_portalGenerated);
            base.Save(valuesDictionary);
        }

        public override void OnEntityAdded(Entity entity)
        {
            ComponentPlayer player = entity.FindComponent<ComponentPlayer>();
            if (player != null)
            {
                m_componentPlayer = player;
                if (m_componentPlayer.PlayerData.SpawnPosition == Vector3.Zero)
                {
                    Vector3 spawnPos = m_subsystemTerrain.TerrainContentsGenerator.FindCoarseSpawnPosition();
                    m_componentPlayer.PlayerData.SpawnPosition = spawnPos;
                    m_componentPlayer.ComponentBody.Position = spawnPos;
                }
                if (!m_initialize) PerformInitialization();
            }
            base.OnEntityAdded(entity);
        }

        public override void OnEntityRemoved(Entity entity) => base.OnEntityRemoved(entity);
        public override void Dispose() => base.Dispose();

        public bool InternalTransfer(string targetWorldName, WorldTransferType transferType, List<Entity> entities)
        {
            try
            {
                if (GameManager.WorldInfo == null) return false;
                string currentPath = m_worldPath;
                bool isChild = IsChildWorld(currentPath);
                string targetPath = transferType switch
                {
                    WorldTransferType.ToLastWorld => !string.IsNullOrEmpty(LastWorldPath) ? (IsChildWorld(LastWorldPath) ? Path.GetDirectoryName(LastWorldPath) : LastWorldPath) == (isChild ? Path.GetDirectoryName(currentPath) : currentPath) ? LastWorldPath : null : (isChild ? Path.GetDirectoryName(currentPath) : null),
                    WorldTransferType.ChildToMajor => Path.GetDirectoryName(currentPath),
                    WorldTransferType.MajorToChild => Path.Combine(currentPath, targetWorldName),
                    WorldTransferType.ChildToChild => Path.Combine(Path.GetDirectoryName(currentPath), targetWorldName),
                    _ => null
                };
                if (targetPath == null) return false;
                if (ProhibitTransmission)
                {
                    m_componentPlayer?.ComponentGui.DisplaySmallMessage("刚进入世界10秒内禁止传送，请等待片刻", Color.Red, false, false);
                    return false;
                }
                if ((transferType == WorldTransferType.ChildToMajor && !isChild) ||
                    (transferType == WorldTransferType.MajorToChild && (isChild || !IsChildWorld(targetPath))) ||
                    (transferType == WorldTransferType.ChildToChild && (!isChild || !IsChildWorld(targetPath))))
                {
                    m_componentPlayer?.ComponentGui.DisplaySmallMessage("传送路径无效", Color.Yellow, false, false);
                    return false;
                }
                if (entities != null)
                {
                    List<SpawnEntityData> spawnList = new List<SpawnEntityData>();
                    foreach (Entity e in entities)
                    {
                        SpawnEntityData data = new SpawnEntityData { TemplateName = e.ValuesDictionary.DatabaseObject.Name, Data = string.Empty, EntityId = e.Id };
                        ModsManager.HookAction("OnSaveSpawnData", loader => { loader.OnSaveSpawnData(e.FindComponent<ComponentSpawn>(), data); return true; });
                        spawnList.Add(data);
                    }
                    string creatureDatas = m_subsystemSpawn.SaveSpawnsData(spawnList);
                    if (!string.IsNullOrEmpty(creatureDatas))
                    {
                        if (!Storage.DirectoryExists(targetPath))
                        {
                            Storage.CreateDirectory(targetPath);
                            XElement srcProj;
                            using (Stream s = Storage.OpenFile(Path.Combine(currentPath, "Project.xml"), OpenFileMode.Read))
                                srcProj = XmlUtils.LoadXmlFromStream(s, null, true);
                            XElement tgtProj = new XElement(srcProj);
                            XElement tgtSub = tgtProj.Element("Subsystems");
                            XElement tgtGameInfo = tgtSub?.Element("Values");
                            tgtGameInfo?.SetAttributeValue("WorldDirectoryName", targetPath);
                            tgtGameInfo?.SetAttributeValue("WorldSeed", (int)(long)(Time.RealTime * 1000.0));
                            XElement tgtWorld = tgtSub?.Elements().FirstOrDefault(e => (string)e.Attribute("Name") == "World");
                            if (tgtWorld != null)
                            {
                                XElement pathElem = tgtWorld.Elements("Value").FirstOrDefault(e => (string)e.Attribute("Name") == "WorldPath");
                                if (pathElem != null) pathElem.SetAttributeValue("Value", targetPath);
                                XElement lastElem = tgtWorld.Elements("Value").FirstOrDefault(e => (string)e.Attribute("Name") == "LastWorldPath");
                                if (lastElem != null) lastElem.SetAttributeValue("Value", "");
                            }
                            using (var s = Storage.OpenFile(Path.Combine(targetPath, "Project.xml"), OpenFileMode.Create))
                                XmlUtils.SaveXmlToStream(tgtProj, s, null, true);
                        }
                        XElement tgtProj2;
                        using (Stream stream = Storage.OpenFile(Path.Combine(targetPath, "Project.xml"), OpenFileMode.Read))
                            tgtProj2 = XmlUtils.LoadXmlFromStream(stream, null, true);
                        XElement subs = tgtProj2.Element("Subsystems");
                        XElement subW = subs?.Elements().FirstOrDefault(e => (string)e.Attribute("Name") == "World");
                        if (subW == null) { subW = new XElement("Values", new XAttribute("Name", "World")); subs?.Add(subW); }
                        XElement existing = subW.Elements().FirstOrDefault(e => (string)e.Attribute("Name") == "CreatureDatas");
                        if (existing != null)
                        {
                            string old = (string)existing.Attribute("Value");
                            existing.SetAttributeValue("Value", (old == "Null" ? "" : old.EndsWith(";") ? old : old + ";") + creatureDatas);
                        }
                        else subW.Add(new XElement("Value", new XAttribute("Name", "CreatureDatas"), new XAttribute("Type", "string"), new XAttribute("Value", creatureDatas)));
                        using (Stream stream = Storage.OpenFile(Path.Combine(targetPath, "Project.xml"), OpenFileMode.Create))
                            XmlUtils.SaveXmlToStream(tgtProj2, stream, null, true);
                    }
                }
                else ChangeWorld(currentPath, targetPath);
                return true;
            }
            catch (Exception e) { Log.Error($"世界传送错误({transferType}): {e.Message}"); return false; }
        }

        public void ToLastWorld(List<Entity> entities = null) => InternalTransfer(null, WorldTransferType.ToLastWorld, entities);
        public void ChildToMajorWorld(bool isAnimal = false, List<Entity> entities = null) => InternalTransfer(null, WorldTransferType.ChildToMajor, isAnimal ? entities : null);
        public void MajorToChildWorld(string worldName, bool isAnimal = false, List<Entity> entities = null) => InternalTransfer(worldName, WorldTransferType.MajorToChild, isAnimal ? entities : null);
        public void ChildToChildWorld(string worldName, bool isAnimal = false, List<Entity> entities = null) => InternalTransfer(worldName, WorldTransferType.ChildToChild, isAnimal ? entities : null);

        public void GeneratePortal()
        {
            if (!IsChildWorld(m_worldPath)) return;
            AccessMultidimensionalWorld cfg = AccessMultidimensionalWorldManager.Get(Path.GetFileName(m_worldPath.Replace("\\", "/")));
            if (cfg == null) return;
            Vector3 pos = m_componentPlayer.ComponentBody.Position;
            Vector3 forward = m_componentPlayer.ComponentBody.Matrix.Forward * 2f;
            Point3 center = new Point3((int)MathF.Floor(pos.X + forward.X), (int)MathF.Floor(pos.Y), (int)MathF.Floor(pos.Z + forward.Z));
            Vector3 clearSize = cfg.ClearingARangeOfSquares;
            int cx = center.X, cy = center.Y, cz = center.Z;
            for (int x = (int)(-clearSize.X / 2); x < (int)(clearSize.X / 2); x++)
                for (int y = 0; y < (int)clearSize.Y; y++)
                    for (int z = (int)(-clearSize.Z / 2); z < (int)(clearSize.Z / 2); z++)
                        m_subsystemTerrain.ChangeCell(cx + x, cy + y, cz + z, 0);
            Vector2 baseRange = cfg.GenerateBaseRange;
            int baseValue = CraftingRecipesManager.DecodeResult(cfg.BaseCubeClassName);
            for (int x = (int)(-baseRange.X / 2); x < (int)(baseRange.X / 2); x++)
                for (int z = (int)(-baseRange.Y / 2); z < (int)(baseRange.Y / 2); z++)
                    m_subsystemTerrain.ChangeCell(cx + x, cy - 1, cz + z, baseValue);
            if (!string.IsNullOrEmpty(cfg.PortalPath))
            {
                string[] lines = ContentManager.Get<string>(cfg.PortalPath).Replace("\r", "").Split('\n', StringSplitOptions.RemoveEmptyEntries);
                Point3 portalOrigin = new Point3(cx + (int)cfg.PortalPositionOffset.X, cy, cz + (int)cfg.PortalPositionOffset.Y);
                foreach (string line in lines)
                {
                    string[] parts = line.Split(',');
                    if (parts.Length >= 4 && int.TryParse(parts[0], out int ox) && int.TryParse(parts[1], out int oy) && int.TryParse(parts[2], out int oz))
                        m_subsystemTerrain.ChangeCell(portalOrigin.X + ox, portalOrigin.Y + oy, portalOrigin.Z + oz, CraftingRecipesManager.DecodeResult(parts[3]));
                }
            }
            if (cfg.ObtainingItems.Length > 0)
            {
                foreach (var kv in cfg.ObtainingItems)
                    foreach (string pair in kv.Split(';'))
                    {
                        string[] parts = pair.Split(',');
                        if (parts.Length >= 2)
                            m_componentPlayer.m_subsystemPickables.AddPickable(CraftingRecipesManager.DecodeResult(parts[0]), int.Parse(parts[1]), m_componentPlayer.ComponentBody.Position, null, null);
                    }
            }
        }

        public void LoadAndSpawnCreatures(ValuesDictionary valuesDictionary)
        {
            if (!valuesDictionary.ContainsKey("CreatureDatas")) return;
            string creatures = valuesDictionary.GetValue<string>("CreatureDatas");
            if (creatures == "Null") return;
            foreach (string entry in creatures.Split(';', StringSplitOptions.RemoveEmptyEntries))
            {
                string[] parts = entry.Split(',');
                if (parts.Length < 7) continue;
                SpawnEntityData data = new SpawnEntityData
                {
                    TemplateName = parts[0],
                    Position = new Vector3(float.Parse(parts[1], CultureInfo.InvariantCulture), float.Parse(parts[2], CultureInfo.InvariantCulture), float.Parse(parts[3], CultureInfo.InvariantCulture)),
                    ConstantSpawn = bool.Parse(parts[4]),
                    Data = parts.Length >= 6 ? parts[5] : string.Empty,
                    EntityId = int.Parse(parts[6])
                };
                try
                {
                    Entity entity = Project.CreateEntity(DatabaseManager.FindEntityValuesDictionary(data.TemplateName, true), data.EntityId);
                    ModsManager.HookAction("OnReadSpawnData", loader => { loader.OnReadSpawnData(entity, data); return true; });
                    ComponentBody body = entity.FindComponent<ComponentBody>(true);
                    body.Position = data.Position;
                    body.Rotation = Quaternion.CreateFromAxisAngle(Vector3.UnitY, m_random.Float(0f, MathF.PI * 2));
                    ComponentCreature creature = entity.FindComponent<ComponentCreature>();
                    if (creature != null) creature.ConstantSpawn = data.ConstantSpawn;
                    m_creatureEntitys.Add(entity);
                }
                catch (Exception ex) { Log.Error($"无法生成实体 \"{data.TemplateName}\": {ex}"); }
            }
            valuesDictionary.SetValue("CreatureDatas", "Null");
        }

        public void ChangeWorld(string currentPath, string targetPath)
        {
            ChangeWorldEvent?.Invoke(m_componentPlayer);
            bool isNew = !Storage.DirectoryExists(targetPath);
            if (isNew) Storage.CreateDirectory(targetPath);

            GameManager.SaveProject(true, true);

            XElement srcProj;
            using (Stream s = Storage.OpenFile(Path.Combine(currentPath, "Project.xml"), OpenFileMode.Read))
                srcProj = XmlUtils.LoadXmlFromStream(s, null, true);

            XElement tgtProj;
            if (isNew)
            {
                tgtProj = new XElement(srcProj);
                XElement tgtSub = tgtProj.Element("Subsystems");
                XElement tgtGameInfo = tgtSub?.Element("Values");
                tgtGameInfo?.SetAttributeValue("WorldDirectoryName", targetPath);
                tgtGameInfo?.SetAttributeValue("WorldSeed", (int)(long)(Time.RealTime * 1000.0));
                XElement tgtWorld = tgtSub?.Elements().FirstOrDefault(e => (string)e.Attribute("Name") == "World");
                if (tgtWorld != null)
                {
                    XElement pathElem = tgtWorld.Elements("Value").FirstOrDefault(e => (string)e.Attribute("Name") == "WorldPath");
                    if (pathElem != null) pathElem.SetAttributeValue("Value", targetPath);
                    XElement lastElem = tgtWorld.Elements("Value").FirstOrDefault(e => (string)e.Attribute("Name") == "LastWorldPath");
                    if (lastElem != null) lastElem.SetAttributeValue("Value", "");
                    XElement creatureElem = tgtWorld.Elements("Value").FirstOrDefault(e => (string)e.Attribute("Name") == "CreatureDatas");
                    if (creatureElem != null) creatureElem.SetAttributeValue("Value", "Null");
                }
                foreach (XElement sub in tgtSub.Elements("Values"))
                {
                    string name = (string)sub.Attribute("Name");
                    if (name == "Time" || name == "Weather" || name == "Spawn")
                        sub.RemoveNodes();
                }

                XElement srcPlayer = srcProj.Element("Entities")?.Elements().FirstOrDefault(e => (string)e.Attribute("Name") == "MalePlayer" || (string)e.Attribute("Name") == "FemalePlayer");
                XElement newPlayer = srcPlayer != null ? new XElement(srcPlayer) : new XElement("Entity", new XAttribute("Name", "MalePlayer"));
                XElement invComp = newPlayer.Elements("Component").FirstOrDefault(e => (string)e.Attribute("Name") == "Inventory");
                if (invComp != null) invComp.RemoveNodes();
                Vector3 playerPos = m_componentPlayer.ComponentBody.Position;
                XElement bodyComp = newPlayer.Elements("Component").FirstOrDefault(e => (string)e.Attribute("Name") == "Body");
                if (bodyComp != null)
                {
                    XElement posVal = bodyComp.Elements("Value").FirstOrDefault(e => (string)e.Attribute("Name") == "Position");
                    if (posVal != null) posVal.SetAttributeValue("Value", playerPos.X + "," + (playerPos.Y + 2) + "," + playerPos.Z);
                }
                XElement tgtEntities = tgtProj.Element("Entities");
                if (tgtEntities != null)
                {
                    tgtEntities.RemoveNodes();
                    tgtEntities.Add(newPlayer);
                }
            }
            else
            {
                using (Stream s = Storage.OpenFile(Path.Combine(targetPath, "Project.xml"), OpenFileMode.Read))
                    tgtProj = XmlUtils.LoadXmlFromStream(s, null, true);
                XElement tgtPlayer = tgtProj.Element("Entities")?.Elements().FirstOrDefault(e => (string)e.Attribute("Name") == "MalePlayer" || (string)e.Attribute("Name") == "FemalePlayer");
                if (tgtPlayer != null)
                {
                    Vector3 playerPos = m_componentPlayer.ComponentBody.Position;
                    XElement bodyComp = tgtPlayer.Elements("Component").FirstOrDefault(e => (string)e.Attribute("Name") == "Body");
                    if (bodyComp != null)
                    {
                        XElement posVal = bodyComp.Elements("Value").FirstOrDefault(e => (string)e.Attribute("Name") == "Position");
                        if (posVal != null) posVal.SetAttributeValue("Value", playerPos.X + "," + (playerPos.Y + 2) + "," + playerPos.Z);
                    }
                }
                else
                {
                    XElement srcPlayer = srcProj.Element("Entities")?.Elements().FirstOrDefault(e => (string)e.Attribute("Name") == "MalePlayer" || (string)e.Attribute("Name") == "FemalePlayer");
                    if (srcPlayer != null)
                    {
                        XElement newPlayer = new XElement(srcPlayer);
                        XElement invComp = newPlayer.Elements("Component").FirstOrDefault(e => (string)e.Attribute("Name") == "Inventory");
                        if (invComp != null) invComp.RemoveNodes();
                        Vector3 playerPos = m_componentPlayer.ComponentBody.Position;
                        XElement bodyComp = newPlayer.Elements("Component").FirstOrDefault(e => (string)e.Attribute("Name") == "Body");
                        if (bodyComp != null)
                        {
                            XElement posVal = bodyComp.Elements("Value").FirstOrDefault(e => (string)e.Attribute("Name") == "Position");
                            if (posVal != null) posVal.SetAttributeValue("Value", playerPos.X + "," + (playerPos.Y + 2) + "," + playerPos.Z);
                        }
                        XElement tgtEntities2 = tgtProj.Element("Entities");
                        if (tgtEntities2 != null)
                        {
                            tgtEntities2.RemoveNodes();
                            tgtEntities2.Add(newPlayer);
                        }
                    }
                }
            }

            using (Stream s = Storage.OpenFile(Path.Combine(targetPath, "Project.xml"), OpenFileMode.Create))
                XmlUtils.SaveXmlToStream(tgtProj, s, null, true);

            void UpdateWorldAttribute(string path, string attr, string value)
            {
                XElement p;
                using (Stream ss = Storage.OpenFile(Path.Combine(path, "Project.xml"), OpenFileMode.Read)) p = XmlUtils.LoadXmlFromStream(ss, null, true);
                XElement sub = p.Element("Subsystems");
                XElement sw = sub?.Elements().FirstOrDefault(e => (string)e.Attribute("Name") == "World");
                if (sw == null) { sw = new XElement("Values", new XAttribute("Name", "World")); sub?.Add(sw); }
                XElement ve = sw?.Elements("Value").FirstOrDefault(e => (string)e.Attribute("Name") == attr);
                if (ve == null) { ve = new XElement("Value", new XAttribute("Name", attr), new XAttribute("Type", "string")); sw?.Add(ve); }
                ve?.SetAttributeValue("Value", value);
                using (Stream ss = Storage.OpenFile(Path.Combine(path, "Project.xml"), OpenFileMode.Create))
                    XmlUtils.SaveXmlToStream(p, ss, null, true);
            }
            UpdateWorldAttribute(targetPath, "LastWorldPath", currentPath);
            UpdateWorldAttribute(targetPath, "WorldPath", targetPath);
            LastWorldPath = currentPath;
            m_worldPath = targetPath;

            m_lastTransferTime = m_subsystemTime.GameTime;
            ScreensManager.SwitchScreen("GameLoading", WorldsManager.GetWorldInfo(targetPath), null);
        }

        public static bool IsChildWorld(string path)
        {
            string dir = Path.GetDirectoryName(path);
            return dir != WorldsManager.WorldsDirectoryName && Path.GetDirectoryName(dir) == WorldsManager.WorldsDirectoryName;
        }
    }
}
