//世界删除
namespace Game
{
    [HarmonyPatch(typeof(WorldsManager), nameof(WorldsManager.DeleteWorld))]
    public static class DeleteWorld
    {
        public static void Prefix(string directoryName)
        {
            XElement srcProj;
            using (Stream s = Storage.OpenFile(Path.Combine(directoryName, "Project.xml"), OpenFileMode.Read))
                srcProj = XmlUtils.LoadXmlFromStream(s, null, true);
            XElement tgtProj = new XElement(srcProj);
            XElement tgtSub = tgtProj.Element("Subsystems");
            XElement tgtPlayerStats = tgtSub?.Elements().FirstOrDefault(e => (string)e.Attribute("Name") == "PlayerStats");
            XElement tgtStats = tgtPlayerStats?.Elements().FirstOrDefault(e => (string)e.Attribute("Name") == "Stats");
            XElement tgtStatsID = tgtStats;
            for (int a = 0; a < 100; a++)
            {
                tgtStatsID = tgtStats?.Elements().FirstOrDefault(e => (string)e.Attribute("Name") == a.ToString());
                if (tgtStatsID != null)
                {
                    int archiveId = tgtStatsID.Elements("Value").Where(e => (string)e.Attribute("Name") == "ArchiveID").Select(e => (int)e.Attribute("Value")).FirstOrDefault();
                    PermanentlySavedAttributesManager.ArchiveProperties.Remove(archiveId);
                    break;
                }
            }
        }
    }
}
