//组件蝙蝠模型动画
namespace Game
{
    public class ComponentBatModel : ComponentCreatureModel
    {
        public bool m_hasWings;
        public ModelBone m_bodyBone;
        public ModelBone m_headBone;
        public ModelBone m_wing1Bone;
        public ModelBone m_wing2Bone;
        public ModelBone m_leg1Bone;
        public ModelBone m_leg2Bone;
        public float m_flyAnimationSpeed;
        public float m_walkAnimationSpeed;
        public float m_attackAnimationSpeed;
        public float m_walkBobHeight;
        public float m_attackPhase;
        public float m_kickPhase;
        public float FlyPhase { get; set; }

        public override float AttackPhase
        {
            get => m_kickPhase;
            set => m_kickPhase = value;
        }

        public override float AttackFactor
        {
            get => m_attackAnimationSpeed;
            set => m_attackAnimationSpeed = value;
        }

        public override void Update(float dt)
        {
            float num = Vector3.Dot(m_componentCreature.ComponentBody.Velocity, m_componentCreature.ComponentBody.Matrix.Forward);
            if (MathF.Abs(num) > 0.1f)
            {
                MovementAnimationPhase += num * dt * m_walkAnimationSpeed;
            }
            else
            {
                float num2 = MathF.Floor(MovementAnimationPhase);
                if (MovementAnimationPhase != num2)
                {
                    MovementAnimationPhase = MovementAnimationPhase - num2 > 0.5f ? MathUtils.Min(MovementAnimationPhase + 2f * dt, num2 + 1f) : MathUtils.Max(MovementAnimationPhase - 2f * dt, num2);
                }
            }
            float num3 = (0f - m_walkBobHeight) * MathUtils.Sqr(MathF.Sin((float)Math.PI * 2f * MovementAnimationPhase));
            float num4 = MathUtils.Min(12f * m_subsystemTime.GameTimeDelta, 1f);
            Bob += num4 * (num3 - Bob);
            if (m_hasWings)
            {
                if (m_componentCreature.ComponentLocomotion.LastFlyOrder.HasValue)
                {
                    float num5 = m_componentCreature.ComponentLocomotion.LastFlyOrder.Value.LengthSquared() > 0.99f ? 1.5f : 1f;
                    FlyPhase = MathUtils.Remainder(FlyPhase + m_flyAnimationSpeed * num5 * dt, 1f);
                    if (m_componentCreature.ComponentLocomotion.LastFlyOrder.Value.Y < -0.1f && m_componentCreature.ComponentBody.Velocity.Length() > 4f)
                    {
                        FlyPhase = 0.72f;
                    }
                }
                else if (FlyPhase != 1f)
                {
                    FlyPhase = MathUtils.Min(FlyPhase + m_flyAnimationSpeed * dt, 1f);
                }
            }
            if (FeedOrder)
            {
                m_attackPhase += m_attackAnimationSpeed * dt;
                if (m_attackPhase > 0.75f)
                {
                    m_attackPhase -= 0.5f;
                }
            }
            else if (m_attackPhase != 0f)
            {
                m_attackPhase = MathUtils.Remainder(Math.Min(m_attackPhase + m_attackAnimationSpeed * dt, 1f), 1f);
            }
            FeedOrder = false;
            IsAttackHitMoment = false;
            if (AttackOrder)
            {
                m_attackAnimationSpeed = MathUtils.Min(m_attackAnimationSpeed + 2f * dt, 1f);
                float kickPhase = m_kickPhase;
                m_kickPhase = MathUtils.Remainder(m_kickPhase + dt * 2f, 1f);
                if (kickPhase < 0.5f && m_kickPhase >= 0.5f)
                {
                    IsAttackHitMoment = true;
                }
            }
            else
            {
                m_attackAnimationSpeed = MathUtils.Max(m_attackAnimationSpeed - 2f * dt, 0f);
                if (m_kickPhase != 0f)
                {
                    if (m_kickPhase > 0.5f)
                    {
                        m_kickPhase = MathUtils.Remainder(MathUtils.Min(m_kickPhase + dt * 2f, 1f), 1f);
                    }
                    else if (m_kickPhase > 0f)
                    {
                        m_kickPhase = MathUtils.Max(m_kickPhase - dt * 2f, 0f);
                    }
                }
            }
            AttackOrder = false;
            base.Update(dt);
        }

        public override void AnimateCreature()
        {
            float num = 0f;
            if (m_hasWings)
            {
                num = 1.2f * MathF.Sin((float)Math.PI * 2f * (FlyPhase + 0.75f));
                if (m_componentCreature.ComponentBody.StandingOnValue.HasValue)
                {
                    num += 0.3f * MathF.Sin((float)Math.PI * 2f * MovementAnimationPhase);
                }
            }
            float num2, num3;
            if (m_componentCreature.ComponentBody.StandingOnValue.HasValue || m_componentCreature.ComponentBody.ImmersionFactor > 0f || m_componentCreature.ComponentLocomotion.FlySpeed == 0f)
            {
                num2 = 0.6f * MathF.Sin((float)Math.PI * 2f * MovementAnimationPhase);
                num3 = 0f - num2;
            }
            else
            {
                num2 = num3 = 0f - MathUtils.DegToRad(60f);
            }
            Vector3 vector = m_componentCreature.ComponentBody.Rotation.ToYawPitchRoll();
            if (m_componentCreature.ComponentHealth.Health > 0f)
            {
                float yaw = m_componentCreature.ComponentLocomotion.LookAngles.X / 2f;
                float num4 = 0f;
                float num5 = 0f;
                if (m_componentCreature.ComponentBody.StandingOnValue.HasValue || m_componentCreature.ComponentBody.ImmersionFactor > 0f)
                {
                    num4 = 0.5f * MathF.Sin((float)Math.PI * 2f * MovementAnimationPhase / 2f);
                    num5 = 0f - num4;
                }
                float num6 = MathF.Cos((float)Math.PI * 2f * (m_kickPhase != 0f ? m_kickPhase : m_attackPhase));
                num4 -= 1.25f * (1f - (num6 >= 0f ? num6 : -0.5f * num6));
                num4 += m_componentCreature.ComponentLocomotion.LookAngles.Y;
                SetBoneTransform(m_bodyBone.Index, Matrix.CreateFromYawPitchRoll(vector.X, 0f, 0f) * Matrix.CreateTranslation(m_componentCreature.ComponentBody.Position + new Vector3(0f, Bob, 0f)));
                SetBoneTransform(m_headBone.Index, Matrix.CreateFromYawPitchRoll(yaw, num5 + Math.Clamp(vector.Y, -(float)Math.PI / 4f, (float)Math.PI / 4f), vector.Z) * Matrix.CreateTranslation(0f, 0f, 0f));
                if (m_hasWings)
                {
                    SetBoneTransform(m_wing1Bone.Index, Matrix.CreateRotationY(num));
                    SetBoneTransform(m_wing2Bone.Index, Matrix.CreateRotationY(0f - num));
                }
                SetBoneTransform(m_leg1Bone.Index, Matrix.CreateRotationX(num2));
                SetBoneTransform(m_leg2Bone.Index, Matrix.CreateRotationX(num3));
            }
            else
            {
                float num7 = 1f - DeathPhase;
                float num8 = m_componentCreature.ComponentBody.BoundingBox.Max.Y - m_componentCreature.ComponentBody.BoundingBox.Min.Y;
                Vector3 position = m_componentCreature.ComponentBody.Position + 0.5f * num8 * Vector3.Normalize(m_componentCreature.ComponentBody.Matrix.Forward * new Vector3(1f, 0f, 1f));
                SetBoneTransform(m_bodyBone.Index, Matrix.CreateFromYawPitchRoll(vector.X, (float)Math.PI / 2f * DeathPhase, 0f) * Matrix.CreateTranslation(position));
                SetBoneTransform(m_headBone.Index, Matrix.Identity);
                if (m_hasWings)
                {
                    SetBoneTransform(m_wing1Bone.Index, Matrix.CreateRotationY(num * num7));
                    SetBoneTransform(m_wing2Bone.Index, Matrix.CreateRotationY((0f - num) * num7));
                }
                SetBoneTransform(m_leg1Bone.Index, Matrix.CreateRotationX(num2 * num7));
                SetBoneTransform(m_leg2Bone.Index, Matrix.CreateRotationX(num3 * num7));
            }
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            m_flyAnimationSpeed = valuesDictionary.GetValue<float>("FlyAnimationSpeed");
            m_walkAnimationSpeed = valuesDictionary.GetValue<float>("WalkAnimationSpeed");
            m_attackAnimationSpeed = valuesDictionary.GetValue<float>("AttackAnimationSpeed");
            m_walkBobHeight = valuesDictionary.GetValue<float>("WalkBobHeight");
        }

        public override void SetModel(Model model)
        {
            base.SetModel(model);
            if (IsSet)
            {
                return;
            }
            if (Model != null)
            {
                m_bodyBone = Model.FindBone("Body");
                m_headBone = Model.FindBone("Head");
                m_leg1Bone = Model.FindBone("Leg1");
                m_leg2Bone = Model.FindBone("Leg2");
                m_wing1Bone = Model.FindBone("Wing1", false);
                m_wing2Bone = Model.FindBone("Wing2", false);
            }
            else
            {
                m_bodyBone = null;
                m_headBone = null;
                m_leg1Bone = null;
                m_leg2Bone = null;
                m_wing1Bone = null;
                m_wing2Bone = null;
            }
            m_hasWings = m_wing1Bone != null && m_wing2Bone != null;
        }
    }
}
//组件超声波行为
namespace Game
{
    public class ComponentUltrasonicWavesBehavior : ComponentBehavior, IUpdateable
    {
        public ComponentChaseBehavior componentChaseBehavior;
        public ComponentBody componentBody;
        public ComponentCreatureModel componentCreatureModel;
        public ComponentCreature componentCreature;
        public ComponentMiner componentMiner;
        public ComponentHealth componentHealth;
        public SubsystemParticles subsystemParticles;
        public SubsystemAudio subsystemAudio;
        public UltrasonicWaveParticleSystem ultrasonicWaveParticleSystem;
        public float m_importanceLevel;
        public float CooldownTime;
        public Random m_random = new();
        public UpdateOrder UpdateOrder => UpdateOrder.Default;
        public override float ImportanceLevel => m_importanceLevel;

        public virtual void Update(float dt)
        {
            CooldownTime = MathUtils.Max(CooldownTime - dt, 0f);
            float attackPower = componentMiner.AttackPower;
            float cooldownReset = attackPower / 20f;
            bool hasTarget = componentChaseBehavior.Target != null && componentHealth.Health > 0;

            if (CooldownTime == 0f && hasTarget)
            {
                Vector3 eyePos = componentCreatureModel.EyePosition;
                foreach (Entity entity in Project.Entities)
                {
                    if (entity == Entity) continue;
                    ComponentBody otherBody = entity.FindComponent<ComponentBody>();
                    if (otherBody != null && Vector3.DistanceSquared(otherBody.Position, componentBody.Position) < 25f)
                    {
                        Vector3 dir = Vector3.Normalize(otherBody.Position - eyePos + m_random.Vector3(0.1f) + 0.2f * Vector3.UnitY);
                        float impulse = attackPower / 20f * otherBody.Mass;
                        otherBody.ApplyImpulse(impulse * dir);
                        float damage = attackPower / 10f / otherBody.m_componentHealth.AttackResilience;
                        otherBody.m_componentHealth.Injure(damage, componentCreature, true, "被超声波杀死");
                        subsystemParticles.AddParticleSystem(new HitValueParticleSystem(
                            eyePos + 0.75f * dir,
                            1f * dir + otherBody.Velocity,
                            Color.White,
                            "-" + NumericalProcessingManager.NumericalProcessing(attackPower / 10f)
                        ));
                        subsystemAudio.PlayRandomSound("Audio/Creatures/Skills/UltrasonicWaves", 1f, m_random.Float(-0.1f, 0.4f), 0f, 0f);
                        otherBody.Entity.FindComponent<ComponentLocomotion>().StunTime = attackPower / 40f;
                        CooldownTime = cooldownReset;
                    }
                }
            }

            if (hasTarget && CooldownTime > cooldownReset - 5f)
            {
                if (ultrasonicWaveParticleSystem == null)
                {
                    ultrasonicWaveParticleSystem = new UltrasonicWaveParticleSystem();
                    subsystemParticles.AddParticleSystem(ultrasonicWaveParticleSystem);
                }
                ultrasonicWaveParticleSystem.Position = componentCreatureModel.CalculateEyePosition();
                ultrasonicWaveParticleSystem.Radius = 5f;
            }
            else if (ultrasonicWaveParticleSystem != null)
            {
                ultrasonicWaveParticleSystem.IsStopped = true;
                ultrasonicWaveParticleSystem = null;
            }
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            componentChaseBehavior = Entity.FindComponent<ComponentChaseBehavior>();
            componentBody = Entity.FindComponent<ComponentBody>();
            componentCreatureModel = Entity.FindComponent<ComponentCreatureModel>();
            componentCreature = Entity.FindComponent<ComponentCreature>();
            componentMiner = Entity.FindComponent<ComponentMiner>();
            componentHealth = Entity.FindComponent<ComponentHealth>();
            subsystemParticles = Project.FindSubsystem<SubsystemParticles>();
            subsystemAudio = Project.FindSubsystem<SubsystemAudio>();
            CooldownTime = valuesDictionary.GetValue<float>("CooldownTime");
        }

        public override void Save(ValuesDictionary valuesDictionary, EntityToIdMap entityToIdMap)
        {
            valuesDictionary.SetValue("CooldownTime", CooldownTime);
        }
    }
}
//超声波特效
namespace Game
{
    public class UltrasonicWaveParticleSystem : ParticleSystem<UltrasonicWaveParticleSystem.Particle>
    {
        public class Particle : Game.Particle
        {
            public float Time;
            public float Duration;
        }

        public PrimitivesRenderer3D m_primitivesRenderer3D = new PrimitivesRenderer3D();
        public Random m_random = new Random();
        public float m_toGenerate;
        public bool m_visible;

        public Vector3 Position { get; set; }
        public float Radius { get; set; }
        public bool IsStopped { get; set; }

        public UltrasonicWaveParticleSystem() : base(1)
        {
            Radius = 5f;
            for (int i = 0; i < Particles.Length; i++)
                Particles[i].IsActive = false;
        }

        public override bool Simulate(float dt)
        {
            dt = dt > 0.1f ? 0.1f : (dt < 0f ? 0f : dt);
            bool anyActive = false;

            if (m_visible)
            {
                m_toGenerate += 6f * dt;
                for (int i = 0; i < Particles.Length; i++)
                {
                    Particle p = Particles[i];
                    if (!p.IsActive && m_toGenerate >= 1f)
                    {
                        p.IsActive = true;
                        p.Position = Position;
                        p.Time = 0f;
                        p.Duration = 0.4f;
                        p.Color = Color.White;
                        p.Size = Vector2.One;
                        m_toGenerate -= 1f;
                    }
                }
                m_toGenerate = m_toGenerate % 1f;
                m_visible = false;
            }

            for (int i = 0; i < Particles.Length; i++)
            {
                Particle p = Particles[i];
                if (p.IsActive)
                {
                    anyActive = true;
                    p.Time += dt;
                    if (p.Time >= p.Duration)
                        p.IsActive = false;
                }
            }

            return IsStopped && !anyActive;
        }

        public override void Draw(Camera camera)
        {
            float dist = Vector3.Dot(Position - camera.ViewPosition, camera.ViewDirection);
            if (dist > -5f && dist <= 48f)
                m_visible = true;

            FlatBatch3D flatBatch = m_primitivesRenderer3D.FlatBatch(0, DepthStencilState.DepthRead, null, BlendState.Additive);
            Vector3 camDir = camera.ViewDirection;
            Vector3 camUp = Vector3.UnitY;
            Vector3 right = Vector3.Normalize(Vector3.Cross(camDir, camUp));
            Vector3 up = Vector3.Normalize(Vector3.Cross(right, camDir));

            for (int i = 0; i < Particles.Length; i++)
            {
                Particle p = Particles[i];
                if (!p.IsActive) continue;

                float t = p.Time / p.Duration;
                float radius = Radius * t;
                float alpha = (1f - t * 0.7f) * 0.6f;
                Color color = new Color(0.2f, 0.6f, 1f, 1f) * alpha * 12f;

                int segments = (int)(radius * 5f) + 12;
                if (segments < 8) segments = 8;

                Vector3 prev = Vector3.Zero;
                for (int s = 0; s <= segments; s++)
                {
                    float angle = (float)s / segments * MathF.PI * 2f;
                    Vector3 offset = right * (MathF.Cos(angle) * radius) + up * (MathF.Sin(angle) * radius);
                    Vector3 point = p.Position + offset;
                    if (s > 0) flatBatch.QueueLine(prev, point, color, color);
                    prev = point;
                }
            }

            m_primitivesRenderer3D.Flush(camera.ViewProjectionMatrix);
        }
    }
}
//组件人形模型动画
namespace Game
{
    public class ComponentHumanoidModel : ComponentCreatureModel
    {
        public SubsystemTerrain m_subsystemTerrain;
        public SubsystemModelsRenderer m_subsystemModelsRenderer;
        public SubsystemNoise m_subsystemNoise;
        public SubsystemAudio m_subsystemAudio;
        public ComponentMiner m_componentMiner;
        public ComponentRider m_componentRider;
        public ComponentSleep m_componentSleep;
        public ComponentPlayer m_componentPlayer;
        public DrawBlockEnvironmentData m_drawBlockEnvironmentData = new DrawBlockEnvironmentData();

        public ModelBone m_bodyBone;
        public ModelBone m_headBone;
        public ModelBone m_leg1Bone;
        public ModelBone m_leg2Bone;
        public ModelBone m_hand1Bone;
        public ModelBone m_hand2Bone;

        public float m_sneakFactor;
        public float m_lieDownFactorEye;
        public float m_lieDownFactorModel;
        public float m_walkAnimationSpeed;
        public float m_walkLegsAngle;
        public float m_walkBobHeight;
        public float m_headingOffset;
        public float m_punchFactor;
        public float m_punchPhase;
        public int m_punchCounter;
        public float m_footstepsPhase;
        public bool m_rowLeft;
        public bool m_rowRight;
        public float m_aimHandAngle;
        public Vector3 m_inHandItemOffset;
        public Vector3 m_inHandItemRotation;
        public Vector2 m_headAngles;
        public Vector2 m_handAngles1;
        public Vector2 m_handAngles2;
        public Vector2 m_legAngles1;
        public Vector2 m_legAngles2;

        // 新增偏移参数
        public float m_bodyPitchOffset;
        public float m_bodyRollOffset;
        public float m_headPitchOffset;
        public float m_headYawOffset;
        public float m_hand1PitchOffset;
        public float m_hand1YawOffset;
        public float m_hand2PitchOffset;
        public float m_hand2YawOffset;
        public float m_leg1PitchOffset;
        public float m_leg1YawOffset;
        public float m_leg2PitchOffset;
        public float m_leg2YawOffset;

        public override float AttackPhase { get => m_punchPhase; set => m_punchPhase = value; }
        public override float AttackFactor { get => m_punchFactor; set => m_punchFactor = value; }

        public override void Update(float dt)
        {
            m_sneakFactor = m_componentCreature.ComponentBody.IsCrouching
                ? MathUtils.Min(m_sneakFactor + 2f * dt, 1f)
                : MathUtils.Max(m_sneakFactor - 2f * dt, 0f);

            if ((m_componentSleep != null && m_componentSleep.IsSleeping) || m_componentCreature.ComponentHealth.Health <= 0f)
            {
                m_lieDownFactorEye = MathUtils.Min(m_lieDownFactorEye + 1f * dt, 1f);
                m_lieDownFactorModel = MathUtils.Min(m_lieDownFactorModel + 3f * dt, 1f);
            }
            else
            {
                m_lieDownFactorEye = MathUtils.Max(m_lieDownFactorEye - 1f * dt, 0f);
                m_lieDownFactorModel = MathUtils.Max(m_lieDownFactorModel - 3f * dt, 0f);
            }

            bool flag = true;
            bool flag2 = true;
            float footstepsPhase = m_footstepsPhase;

            if (m_componentCreature.ComponentLocomotion.LadderValue.HasValue)
            {
                m_footstepsPhase += 1.5f * m_walkAnimationSpeed * m_componentCreature.ComponentBody.Velocity.Length() * dt;
                flag2 = false;
            }
            else if (!m_componentCreature.ComponentLocomotion.IsCreativeFlyEnabled)
            {
                float num = m_componentCreature.ComponentLocomotion.SlipSpeed
                    ?? (m_componentCreature.ComponentBody.Velocity.XZ - m_componentCreature.ComponentBody.StandingOnVelocity.XZ).Length();
                if (num > 0.5f)
                {
                    MovementAnimationPhase += num * dt * m_walkAnimationSpeed;
                    m_footstepsPhase += 1f * m_walkAnimationSpeed * num * dt;
                    flag = false;
                    flag2 = false;
                }
            }

            if (flag)
            {
                float num2 = 0.5f * MathF.Floor(2f * MovementAnimationPhase);
                if (MovementAnimationPhase != num2)
                {
                    MovementAnimationPhase = MovementAnimationPhase - num2 > 0.25f
                        ? MathUtils.Min(MovementAnimationPhase + 2f * dt, num2 + 0.5f)
                        : MathUtils.Max(MovementAnimationPhase - 2f * dt, num2);
                }
            }

            if (flag2) m_footstepsPhase = 0f;

            float num3 = 0f;
            ComponentMount componentMount = m_componentRider?.Mount;
            if (componentMount != null)
            {
                ComponentCreatureModel componentCreatureModel = componentMount.Entity.FindComponent<ComponentCreatureModel>();
                if (componentCreatureModel != null)
                {
                    Bob = componentCreatureModel.Bob;
                    num3 = Bob;
                }
                m_headingOffset = 0f;
            }
            else
            {
                float x = MathF.Sin((float)Math.PI * 2f * MovementAnimationPhase);
                num3 = m_walkBobHeight * MathUtils.Sqr(x);
                float num4 = 0f;
                if (m_componentCreature.ComponentLocomotion.LastWalkOrder.HasValue
                    && m_componentCreature.ComponentLocomotion.LastWalkOrder != Vector2.Zero)
                {
                    num4 = Vector2.Angle(Vector2.UnitY, m_componentCreature.ComponentLocomotion.LastWalkOrder.Value);
                }
                m_headingOffset += MathUtils.NormalizeAngle(num4 - m_headingOffset) * MathUtils.Saturate(8f * m_subsystemTime.GameTimeDelta);
                m_headingOffset = MathUtils.NormalizeAngle(m_headingOffset);
            }

            float num5 = MathUtils.Min(12f * m_subsystemTime.GameTimeDelta, 1f);
            Bob += num5 * (num3 - Bob);

            IsAttackHitMoment = false;
            if (AttackOrder)
            {
                m_punchFactor = MathUtils.Min(m_punchFactor + 4f * dt, 1f);
                float punchPhase = m_punchPhase;
                m_punchPhase = MathUtils.Remainder(m_punchPhase + dt * 2f, 1f);
                if (punchPhase < 0.5f && m_punchPhase >= 0.5f)
                {
                    IsAttackHitMoment = true;
                    m_punchCounter++;
                }
            }
            else
            {
                m_punchFactor = MathUtils.Max(m_punchFactor - 4f * dt, 0f);
                if (m_punchPhase != 0f)
                {
                    if (m_punchPhase > 0.5f)
                        m_punchPhase = MathUtils.Remainder(MathUtils.Min(m_punchPhase + dt * 2f, 1f), 1f);
                    else if (m_punchPhase > 0f)
                        m_punchPhase = MathUtils.Max(m_punchPhase - dt * m_punchPhase, 0f);
                }
            }

            m_rowLeft = RowLeftOrder;
            m_rowRight = RowRightOrder;
            if ((m_rowLeft || m_rowRight) && componentMount != null
                && componentMount.ComponentBody.ImmersionFactor > 0f
                && Math.Floor(1.1000000238418579 * m_subsystemTime.GameTime)
                != Math.Floor(1.1000000238418579 * (m_subsystemTime.GameTime - m_subsystemTime.GameTimeDelta)))
            {
                m_subsystemAudio.PlayRandomSound("Audio/Rowing", m_random.Float(0.4f, 0.6f),
                    m_random.Float(-0.3f, 0.2f), m_componentCreature.ComponentBody.Position, 3f, true);
            }

            float num6 = MathF.Floor(m_footstepsPhase);
            if (m_footstepsPhase > num6 && footstepsPhase <= num6)
            {
                if (m_componentCreature.ComponentBody.CrouchFactor < 1f)
                    m_subsystemNoise.MakeNoise(m_componentCreature.ComponentBody, 0.25f, 8f);
                if (!m_componentCreature.ComponentCreatureSounds.PlayFootstepSound(1f))
                    m_footstepsPhase = 0f;
            }

            m_aimHandAngle = AimHandAngleOrder;
            m_inHandItemOffset = Vector3.Lerp(m_inHandItemOffset, InHandItemOffsetOrder, 10f * dt);
            m_inHandItemRotation = Vector3.Lerp(m_inHandItemRotation, InHandItemRotationOrder, 10f * dt);
            AttackOrder = false;
            RowLeftOrder = false;
            RowRightOrder = false;
            AimHandAngleOrder = 0f;
            InHandItemOffsetOrder = Vector3.Zero;
            InHandItemRotationOrder = Vector3.Zero;
            base.Update(dt);
        }

        public override void AnimateCreature()
        {
            Vector3 position = m_componentCreature.ComponentBody.Position;
            Vector3 vector = m_componentCreature.ComponentBody.Rotation.ToYawPitchRoll();

            if (OnAnimate != null && OnAnimate()) return;

            if (m_lieDownFactorModel == 0f)
            {
                ComponentMount componentMount = m_componentRider?.Mount;
                float num = MathF.Sin((float)Math.PI * 2f * MovementAnimationPhase);
                position.Y += Bob;
                vector.X += m_headingOffset;

                float num2 = (float)MathUtils.Remainder(0.75 * m_subsystemGameInfo.TotalElapsedGameTime + (GetHashCode() & 0xFFFF), 10000.0);
                float x = Math.Clamp(
                    MathUtils.Lerp(-0.3f, 0.3f, SimplexNoise.Noise(1.02f * num2 - 100f))
                    + m_componentCreature.ComponentLocomotion.LookAngles.X
                    + 1f * m_componentCreature.ComponentLocomotion.LastTurnOrder.X
                    + m_headingOffset,
                    -MathUtils.DegToRad(80f), MathUtils.DegToRad(80f));

                float y = Math.Clamp(
                    MathUtils.Lerp(-0.3f, 0.3f, SimplexNoise.Noise(0.96f * num2 - 200f))
                    + m_componentCreature.ComponentLocomotion.LookAngles.Y,
                    -MathUtils.DegToRad(45f), MathUtils.DegToRad(45f));

                float num3 = 0f, y2 = 0f, x2 = 0f, y3 = 0f;
                float num4 = 0f, num5 = 0f, num6 = 0f, num7 = 0f;

                if (componentMount != null)
                {
                    if (componentMount.Entity.ValuesDictionary.DatabaseObject.Name == "Boat")
                    {
                        position.Y -= 0.2f;
                        vector.X += (float)Math.PI;
                        num4 = 0.4f; num6 = 0.4f; num5 = 0.2f; num7 = -0.2f;
                        num3 = 1.1f; x2 = 1.1f; y2 = 0.2f; y3 = -0.2f;
                    }
                    else
                    {
                        num4 = 0.5f; num6 = 0.5f; num5 = 0.15f; num7 = -0.15f;
                        y2 = 0.55f; y3 = -0.55f;
                    }
                }
                else if (m_componentCreature.ComponentLocomotion.IsCreativeFlyEnabled)
                {
                    float num8 = m_componentCreature.ComponentLocomotion.LastWalkOrder.HasValue
                        ? MathUtils.Min(0.03f * m_componentCreature.ComponentBody.Velocity.XZ.LengthSquared(), 0.5f) : 0f;
                    num3 = -0.1f - num8;
                    x2 = num3;
                    y2 = MathUtils.Lerp(0f, 0.25f, SimplexNoise.Noise(1.07f * num2 + 400f));
                    y3 = -MathUtils.Lerp(0f, 0.25f, SimplexNoise.Noise(0.93f * num2 + 500f));
                }
                else if (MovementAnimationPhase != 0f)
                {
                    num4 = -0.5f * num;
                    num6 = 0.5f * num;
                    num3 = m_walkLegsAngle * num;
                    x2 = -num3;
                }

                float num9 = 0f;
                if (m_componentMiner != null)
                {
                    float num10 = MathF.Sin(MathF.Sqrt(m_componentMiner.PokingPhase) * (float)Math.PI);
                    num9 = m_componentMiner.ActiveBlockValue == 0 ? 1f * num10 : 0.3f + 1f * num10;
                }

                float num11 = m_punchPhase != 0f
                    ? -MathUtils.DegToRad(90f) * MathF.Sin((float)Math.PI * 2f * MathUtils.Sigmoid(m_punchPhase, 4f)) : 0f;
                float num12 = (m_punchCounter & 1) == 0 ? num11 : 0f;
                float num13 = (m_punchCounter & 1) != 0 ? num11 : 0f;

                float num14 = 0f, num15 = 0f, num16 = 0f, num17 = 0f;
                if (m_rowLeft || m_rowRight)
                {
                    float num18 = 0.6f * (float)Math.Sin(6.91150426864624 * m_subsystemTime.GameTime);
                    float num19 = 0.2f + 0.2f * (float)Math.Cos(6.91150426864624 * (m_subsystemTime.GameTime + 0.5));
                    if (m_rowLeft) { num14 = num18; num15 = num19; }
                    if (m_rowRight) { num16 = num18; num17 = -num19; }
                }

                float num20 = 0f, num21 = 0f, num22 = 0f, num23 = 0f;
                if (m_aimHandAngle != 0f)
                {
                    num20 = 1.5f; num21 = -0.7f; num22 = m_aimHandAngle * 1f; num23 = 0f;
                }

                float num24 = !m_componentCreature.ComponentLocomotion.IsCreativeFlyEnabled ? 1 : 4;
                num4 += MathUtils.Lerp(-0.1f, 0.1f, SimplexNoise.Noise(num2)) + num12 + num14 + num20;
                num5 += MathUtils.Lerp(0f, num24 * 0.15f, SimplexNoise.Noise(1.1f * num2 + 100f)) + num15 + num21;
                num6 += num9 + MathUtils.Lerp(-0.1f, 0.1f, SimplexNoise.Noise(0.9f * num2 + 200f)) + num13 + num16 + num22;
                num7 += -MathUtils.Lerp(0f, num24 * 0.15f, SimplexNoise.Noise(1.05f * num2 + 300f)) + num17 + num23;

                float s = MathUtils.Min(12f * m_subsystemTime.GameTimeDelta, 1f);
                m_headAngles += s * (new Vector2(x, y) - m_headAngles);
                m_handAngles1 += s * (new Vector2(num4, num5) - m_handAngles1);
                m_handAngles2 += s * (new Vector2(num6, num7) - m_handAngles2);
                m_legAngles1 += s * (new Vector2(num3, y2) - m_legAngles1);
                m_legAngles2 += s * (new Vector2(x2, y3) - m_legAngles2);

                if (m_componentCreature.ComponentBody.CrouchFactor == 1)
                {
                    m_legAngles1 *= 0.5f;
                    m_legAngles2 *= 0.5f;
                }

                float f = MathUtils.Sigmoid(m_componentCreature.ComponentBody.CrouchFactor, 4f);
                Vector3 position3 = new Vector3(position.X, position.Y - MathUtils.Lerp(0f, 0.7f, f), position.Z);
                Vector3 position4 = new Vector3(0f, MathUtils.Lerp(0f, 7f, f), MathUtils.Lerp(0f, 28f, f));
                Vector3 scale = new Vector3(1f, 1f, MathUtils.Lerp(1f, 0.5f, f));

                // 应用偏移
                SetBoneTransform(m_bodyBone.Index,
                    Matrix.CreateRotationY(vector.X)
                    * Matrix.CreateRotationX(m_bodyPitchOffset)
                    * Matrix.CreateRotationZ(m_bodyRollOffset)
                    * Matrix.CreateTranslation(position3));

                SetBoneTransform(m_headBone.Index,
                    Matrix.CreateRotationX(m_headAngles.Y + m_headPitchOffset)
                    * Matrix.CreateRotationZ(-m_headAngles.X + m_headYawOffset));

                SetBoneTransform(m_hand1Bone.Index,
                    Matrix.CreateRotationY(m_handAngles1.Y + m_hand1YawOffset)
                    * Matrix.CreateRotationX(m_handAngles1.X + m_hand1PitchOffset));

                SetBoneTransform(m_hand2Bone.Index,
                    Matrix.CreateRotationY(m_handAngles2.Y + m_hand2YawOffset)
                    * Matrix.CreateRotationX(m_handAngles2.X + m_hand2PitchOffset));

                SetBoneTransform(m_leg1Bone.Index,
                    Matrix.CreateRotationY(m_legAngles1.Y + m_leg1YawOffset)
                    * Matrix.CreateRotationX(m_legAngles1.X + m_leg1PitchOffset)
                    * Matrix.CreateTranslation(position4)
                    * Matrix.CreateScale(scale));

                SetBoneTransform(m_leg2Bone.Index,
                    Matrix.CreateRotationY(m_legAngles2.Y + m_leg2YawOffset)
                    * Matrix.CreateRotationX(m_legAngles2.X + m_leg2PitchOffset)
                    * Matrix.CreateTranslation(position4)
                    * Matrix.CreateScale(scale));
            }
            else
            {
                float num25 = MathUtils.Max(DeathPhase, m_lieDownFactorModel);
                float num26 = 1f - num25;
                Vector3 position2 = position
                    + num25 * 0.5f * m_componentCreature.ComponentBody.BoxSize.Y
                    * Vector3.Normalize(m_componentCreature.ComponentBody.Matrix.Forward * new Vector3(1f, 0f, 1f))
                    + num25 * Vector3.UnitY * m_componentCreature.ComponentBody.BoxSize.Z * 0.1f;

                SetBoneTransform(m_bodyBone.Index,
                    Matrix.CreateFromYawPitchRoll(vector.X, (float)Math.PI / 2f * num25, 0f)
                    * Matrix.CreateTranslation(position2));
                SetBoneTransform(m_headBone.Index, Matrix.Identity);
                SetBoneTransform(m_hand1Bone.Index,
                    Matrix.CreateRotationY((m_handAngles1.Y + m_hand1YawOffset) * num26)
                    * Matrix.CreateRotationX((m_handAngles1.X + m_hand1PitchOffset) * num26));
                SetBoneTransform(m_hand2Bone.Index,
                    Matrix.CreateRotationY((m_handAngles2.Y + m_hand2YawOffset) * num26)
                    * Matrix.CreateRotationX((m_handAngles2.X + m_hand2PitchOffset) * num26));
                SetBoneTransform(m_leg1Bone.Index,
                    Matrix.CreateRotationY((m_legAngles1.Y + m_leg1YawOffset) * num26)
                    * Matrix.CreateRotationX((m_legAngles1.X + m_leg1PitchOffset) * num26));
                SetBoneTransform(m_leg2Bone.Index,
                    Matrix.CreateRotationY((m_legAngles2.Y + m_leg2YawOffset) * num26)
                    * Matrix.CreateRotationX((m_legAngles2.X + m_leg2PitchOffset) * num26));
            }
        }

        public override void DrawExtras(Camera camera)
        {
            base.DrawExtras(camera);
            if (IsExtrasDrawn) return;

            if (m_componentCreature.ComponentHealth.Health > 0f && m_componentMiner != null && m_componentMiner.ActiveBlockValue != 0)
            {
                int num = Terrain.ExtractContents(m_componentMiner.ActiveBlockValue);
                Block block = BlocksManager.Blocks[num];
                Matrix m = AbsoluteBoneTransformsForCamera[m_hand2Bone.Index];
                m *= camera.InvertedViewMatrix;
                m.Right = Vector3.Normalize(m.Right);
                m.Up = Vector3.Normalize(m.Up);
                m.Forward = Vector3.Normalize(m.Forward);

                Vector3 InhandRotation = block.GetInHandRotation(m_componentMiner.ActiveBlockValue);
                Matrix matrix = Matrix.CreateRotationY(MathUtils.DegToRad(InhandRotation.Y) + m_inHandItemRotation.Y)
                    * Matrix.CreateRotationZ(MathUtils.DegToRad(InhandRotation.Z) + m_inHandItemRotation.Z)
                    * Matrix.CreateRotationX(MathUtils.DegToRad(InhandRotation.X) + m_inHandItemRotation.X)
                    * Matrix.CreateTranslation(block.GetInHandOffset(m_componentMiner.ActiveBlockValue) + m_inHandItemOffset)
                    * Matrix.CreateTranslation(new Vector3(0.05f, 0.05f, -0.56f) * (m_componentCreature.ComponentBody.BoxSize.Y / 1.77f))
                    * m;

                int x = Terrain.ToCell(matrix.Translation.X);
                int y = Terrain.ToCell(matrix.Translation.Y);
                int z = Terrain.ToCell(matrix.Translation.Z);
                m_drawBlockEnvironmentData.DrawBlockMode = DrawBlockMode.ThirdPerson;
                m_drawBlockEnvironmentData.InWorldMatrix = matrix;
                m_drawBlockEnvironmentData.Humidity = m_subsystemTerrain.Terrain.GetSeasonalHumidity(x, z);
                m_drawBlockEnvironmentData.Temperature = m_subsystemTerrain.Terrain.GetSeasonalTemperature(x, z)
                    + SubsystemWeather.GetTemperatureAdjustmentAtHeight(y);
                m_drawBlockEnvironmentData.Light = m_subsystemTerrain.Terrain.GetCellLight(x, y, z);
                m_drawBlockEnvironmentData.BillboardDirection = -Vector3.UnitZ;
                m_drawBlockEnvironmentData.SubsystemTerrain = m_subsystemTerrain;
                m_drawBlockEnvironmentData.Owner = m_entity;

                Matrix matrix2 = matrix * camera.ViewMatrix;
                block.DrawBlock(m_subsystemModelsRenderer.PrimitivesRenderer,
                    m_componentMiner.ActiveBlockValue, Color.White,
                    block.GetInHandScale(m_componentMiner.ActiveBlockValue),
                    ref matrix2, m_drawBlockEnvironmentData);
            }
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            m_subsystemTerrain = Project.FindSubsystem<SubsystemTerrain>(true);
            m_subsystemModelsRenderer = Project.FindSubsystem<SubsystemModelsRenderer>(true);
            m_subsystemNoise = Project.FindSubsystem<SubsystemNoise>(true);
            m_subsystemAudio = Project.FindSubsystem<SubsystemAudio>(true);
            m_componentMiner = Entity.FindComponent<ComponentMiner>();
            m_componentRider = Entity.FindComponent<ComponentRider>();
            m_componentSleep = Entity.FindComponent<ComponentSleep>();
            m_componentPlayer = Entity.FindComponent<ComponentPlayer>();

            m_walkAnimationSpeed = valuesDictionary.GetValue<float>("WalkAnimationSpeed");
            m_walkBobHeight = valuesDictionary.GetValue<float>("WalkBobHeight");
            m_walkLegsAngle = valuesDictionary.GetValue<float>("WalkLegsAngle");

            m_bodyPitchOffset = valuesDictionary.GetValue<float>("BodyPitchOffset");
            m_bodyRollOffset = valuesDictionary.GetValue<float>("BodyRollOffset");
            m_headPitchOffset = valuesDictionary.GetValue<float>("HeadPitchOffset");
            m_headYawOffset = valuesDictionary.GetValue<float>("HeadYawOffset");
            m_hand1PitchOffset = valuesDictionary.GetValue<float>("Hand1PitchOffset");
            m_hand1YawOffset = valuesDictionary.GetValue<float>("Hand1YawOffset");
            m_hand2PitchOffset = valuesDictionary.GetValue<float>("Hand2PitchOffset");
            m_hand2YawOffset = valuesDictionary.GetValue<float>("Hand2YawOffset");
            m_leg1PitchOffset = valuesDictionary.GetValue<float>("Leg1PitchOffset");
            m_leg1YawOffset = valuesDictionary.GetValue<float>("Leg1YawOffset");
            m_leg2PitchOffset = valuesDictionary.GetValue<float>("Leg2PitchOffset");
            m_leg2YawOffset = valuesDictionary.GetValue<float>("Leg2YawOffset");
        }

        public override void SetModel(Model model)
        {
            base.SetModel(model);
            if (IsSet) return;
            if (Model != null)
            {
                m_bodyBone = Model.FindBone("Body");
                m_headBone = Model.FindBone("Head");
                m_leg1Bone = Model.FindBone("Leg1");
                m_leg2Bone = Model.FindBone("Leg2");
                m_hand1Bone = Model.FindBone("Hand1");
                m_hand2Bone = Model.FindBone("Hand2");
            }
            else
            {
                m_bodyBone = null;
                m_headBone = null;
                m_leg1Bone = null;
                m_leg2Bone = null;
                m_hand1Bone = null;
                m_hand2Bone = null;
            }
        }

        public override Vector3 CalculateEyePosition()
        {
            float f = MathUtils.Sigmoid(m_lieDownFactorEye, 1f);
            float num = MathUtils.Sigmoid(m_componentCreature.ComponentBody.CrouchFactor, 4f);
            float num2 = 0.875f * m_componentCreature.ComponentBody.BoxSize.Y;
            float num3 = MathUtils.Lerp(MathUtils.Lerp(num2, 0.45f * num2, num), 0.2f * num2, f);
            Matrix matrix = m_componentCreature.ComponentBody.Matrix;
            Vector3 result = m_componentCreature.ComponentBody.Position + matrix.Up * (num3 + 2f * Bob) + matrix.Forward * -0.2f * num;
            ModsManager.HookAction("RecalculateModelEyePosition", loader => { loader.RecalculateModelEyePosition(this, ref result); return false; });
            return result;
        }

        public override Quaternion CalculateEyeRotation()
        {
            float num = 0f;
            if (m_lieDownFactorEye != 0f)
                num += MathUtils.DegToRad(80f) * MathUtils.Sigmoid(MathUtils.Max(m_lieDownFactorEye - 0.2f, 0f) / 0.8f, 4f);
            Quaternion result = m_componentCreature.ComponentBody.Rotation
                * Quaternion.CreateFromYawPitchRoll(-m_componentCreature.ComponentLocomotion.LookAngles.X,
                    m_componentCreature.ComponentLocomotion.LookAngles.Y, num);
            ModsManager.HookAction("RecalculateModelEyeRotation", loader => { loader.RecalculateModelEyeRotation(this, ref result); return false; });
            return result;
        }
    }
}
//组件狐猴模型动画
namespace Game
{
    public class ComponentLemurModel : ComponentCreatureModel
    {
        public SubsystemAudio m_subsystemAudio;
        public SubsystemSoundMaterials m_subsystemSoundMaterials;

        public ModelBone m_bodyBone;
        public ModelBone m_headBone;
        public ModelBone m_hand1Bone;
        public ModelBone m_hand2Bone;
        public ModelBone m_leg1Bone;
        public ModelBone m_leg2Bone;

        public float m_walkAnimationSpeed;
        public float m_walkFrontLegsAngle;
        public float m_walkHindLegsAngle;
        public float m_canterLegsAngleFactor;
        public float m_walkBobHeight;
        public bool m_canCanter;
        public bool m_canTrot;
        public bool m_useCanterSound;
        public float m_attackSpeed;
        public float m_attackAngle;

        public enum Gait
        {
            Walk,
            Trot,
            Canter
        }

        public Gait m_gait;
        public float m_footstepsPhase;
        public float m_hand1Angle;
        public float m_hand2Angle;
        public float m_leg1Angle;
        public float m_leg2Angle;
        public float m_attackFactor;
        public float m_attackPhase;
        public int m_attackCounter;

        public override float AttackPhase
        {
            get => m_attackPhase;
            set => m_attackPhase = value;
        }

        public override float AttackFactor
        {
            get => m_attackFactor;
            set => m_attackFactor = value;
        }

        public override void Update(float dt)
        {
            float footstepsPhase = m_footstepsPhase;
            float num = m_componentCreature.ComponentLocomotion.SlipSpeed ??
                Vector3.Dot(m_componentCreature.ComponentBody.Velocity, m_componentCreature.ComponentBody.Matrix.Forward);

            if (m_canCanter && num > 0.7f * m_componentCreature.ComponentLocomotion.WalkSpeed)
            {
                m_gait = Gait.Canter;
                MovementAnimationPhase += num * dt * 0.7f * m_walkAnimationSpeed;
                m_footstepsPhase += 0.7f * m_walkAnimationSpeed * num * dt;
            }
            else if (m_canTrot && num > 0.5f * m_componentCreature.ComponentLocomotion.WalkSpeed)
            {
                m_gait = Gait.Trot;
                MovementAnimationPhase += num * dt * m_walkAnimationSpeed;
                m_footstepsPhase += 1.25f * m_walkAnimationSpeed * num * dt;
            }
            else if (MathF.Abs(num) > 0.2f)
            {
                m_gait = Gait.Walk;
                MovementAnimationPhase += num * dt * m_walkAnimationSpeed;
                m_footstepsPhase += 1.25f * m_walkAnimationSpeed * num * dt;
            }
            else
            {
                m_gait = Gait.Walk;
                MovementAnimationPhase = 0f;
                m_footstepsPhase = 0f;
            }

            float targetBob = 0f;
            if (m_gait == Gait.Canter)
                targetBob = -m_walkBobHeight * 1.5f * MathF.Sin(2f * MathF.PI * MovementAnimationPhase);
            else if (m_gait == Gait.Trot)
                targetBob = m_walkBobHeight * 1.5f * MathUtils.Sqr(MathF.Sin(2f * MathF.PI * MovementAnimationPhase));
            else if (m_gait == Gait.Walk)
                targetBob = -m_walkBobHeight * MathUtils.Sqr(MathF.Sin(2f * MathF.PI * MovementAnimationPhase));

            float smooth = MathUtils.Min(12f * m_subsystemTime.GameTimeDelta, 1f);
            Bob += smooth * (targetBob - Bob);

            if (m_gait == Gait.Canter && m_useCanterSound)
            {
                float num4 = MathF.Floor(m_footstepsPhase);
                if (m_footstepsPhase > num4 && footstepsPhase <= num4)
                {
                    string footstepSoundMaterialName = m_subsystemSoundMaterials.GetFootstepSoundMaterialName(m_componentCreature);
                    if (!string.IsNullOrEmpty(footstepSoundMaterialName) && footstepSoundMaterialName != "Water")
                    {
                        m_subsystemAudio.PlayRandomSound("Audio/Footsteps/CanterDirt", 0.75f, m_random.Float(-0.25f, 0f),
                            m_componentCreature.ComponentBody.Position, 3f, true);
                    }
                }
            }
            else
            {
                float num5 = MathF.Floor(m_footstepsPhase);
                if (m_footstepsPhase > num5 && footstepsPhase <= num5)
                {
                    m_componentCreature.ComponentCreatureSounds.PlayFootstepSound(1f);
                }
            }

            IsAttackHitMoment = false;
            if (AttackOrder)
            {
                m_attackFactor = MathUtils.Min(m_attackFactor + 4f * dt, 1f);
                float prevPhase = m_attackPhase;
                m_attackPhase = MathUtils.Remainder(m_attackPhase + dt * m_attackSpeed, 1f);
                if (prevPhase < 0.5f && m_attackPhase >= 0.5f)
                {
                    IsAttackHitMoment = true;
                    m_attackCounter++;
                }
            }
            else
            {
                m_attackFactor = MathUtils.Max(m_attackFactor - 4f * dt, 0f);
                if (m_attackPhase != 0f)
                {
                    if (m_attackPhase > 0.5f)
                        m_attackPhase = MathUtils.Remainder(MathUtils.Min(m_attackPhase + dt * 2f, 1f), 1f);
                    else if (m_attackPhase > 0f)
                        m_attackPhase = MathUtils.Max(m_attackPhase - dt * 2f, 0f);
                }
            }
            AttackOrder = false;

            base.Update(dt);
        }

        public override void AnimateCreature()
        {
            Vector3 pos = m_componentCreature.ComponentBody.Position;
            Vector3 rot = m_componentCreature.ComponentBody.Rotation.ToYawPitchRoll();

            if (m_componentCreature.ComponentHealth.Health > 0f)
            {
                float targetHand1 = 0f, targetHand2 = 0f, targetLeg1 = 0f, targetLeg2 = 0f;
                float headSway = 0f;

                if (MovementAnimationPhase != 0f && (m_componentCreature.ComponentBody.StandingOnValue.HasValue || m_componentCreature.ComponentBody.ImmersionFactor > 0f))
                {
                    if (m_gait == Gait.Canter)
                    {
                        float s1 = MathF.Sin(2f * MathF.PI * (MovementAnimationPhase + 0f));
                        float s2 = MathF.Sin(2f * MathF.PI * (MovementAnimationPhase + 0.25f));
                        float s3 = MathF.Sin(2f * MathF.PI * (MovementAnimationPhase + 0.15f));
                        float s4 = MathF.Sin(2f * MathF.PI * (MovementAnimationPhase + 0.4f));
                        targetHand1 = m_walkFrontLegsAngle * m_canterLegsAngleFactor * s1;
                        targetHand2 = m_walkFrontLegsAngle * m_canterLegsAngleFactor * s2;
                        targetLeg1 = m_walkHindLegsAngle * m_canterLegsAngleFactor * s3;
                        targetLeg2 = m_walkHindLegsAngle * m_canterLegsAngleFactor * s4;
                        headSway = MathUtils.DegToRad(8f) * MathF.Sin(2f * MathF.PI * MovementAnimationPhase);
                    }
                    else if (m_gait == Gait.Trot)
                    {
                        float s1 = MathF.Sin(2f * MathF.PI * (MovementAnimationPhase + 0f));
                        float s2 = MathF.Sin(2f * MathF.PI * (MovementAnimationPhase + 0.5f));
                        float s3 = MathF.Sin(2f * MathF.PI * (MovementAnimationPhase + 0.5f));
                        float s4 = MathF.Sin(2f * MathF.PI * (MovementAnimationPhase + 0f));
                        targetHand1 = m_walkFrontLegsAngle * s1;
                        targetHand2 = m_walkFrontLegsAngle * s2;
                        targetLeg1 = m_walkHindLegsAngle * s3;
                        targetLeg2 = m_walkHindLegsAngle * s4;
                        headSway = MathUtils.DegToRad(3f) * MathF.Sin(4f * MathF.PI * MovementAnimationPhase);
                    }
                    else
                    {
                        float s1 = MathF.Sin(2f * MathF.PI * (MovementAnimationPhase + 0f));
                        float s2 = MathF.Sin(2f * MathF.PI * (MovementAnimationPhase + 0.5f));
                        float s3 = MathF.Sin(2f * MathF.PI * (MovementAnimationPhase + 0.25f));
                        float s4 = MathF.Sin(2f * MathF.PI * (MovementAnimationPhase + 0.75f));
                        targetHand1 = m_walkFrontLegsAngle * s1;
                        targetHand2 = m_walkFrontLegsAngle * s2;
                        targetLeg1 = m_walkHindLegsAngle * s3;
                        targetLeg2 = m_walkHindLegsAngle * s4;
                        headSway = MathUtils.DegToRad(3f) * MathF.Sin(4f * MathF.PI * MovementAnimationPhase);
                    }
                }

                if (m_attackFactor > 0f)
                {
                    float attackAngle = m_attackAngle * MathF.Sin(2f * MathF.PI * MathUtils.Sigmoid(m_attackPhase, 4f));
                    if ((m_attackCounter & 1) == 0)
                        targetHand2 += attackAngle;
                    else
                        targetHand1 += attackAngle;
                }

                float smooth = MathUtils.Min(12f * m_subsystemTime.GameTimeDelta, 1f);
                m_hand1Angle += smooth * (targetHand1 - m_hand1Angle);
                m_hand2Angle += smooth * (targetHand2 - m_hand2Angle);
                m_leg1Angle += smooth * (targetLeg1 - m_leg1Angle);
                m_leg2Angle += smooth * (targetLeg2 - m_leg2Angle);

                Vector2 look = m_componentCreature.ComponentLocomotion.LookAngles;
                look.Y += headSway;
                look.X = Math.Clamp(look.X, -MathUtils.DegToRad(65f), MathUtils.DegToRad(65f));
                look.Y = Math.Clamp(look.Y, -MathUtils.DegToRad(55f), MathUtils.DegToRad(55f));

                Vector3 bodyPos = new Vector3(pos.X, pos.Y + Bob, pos.Z);
                SetBoneTransform(m_bodyBone.Index, Matrix.CreateRotationY(rot.X) * Matrix.CreateTranslation(bodyPos));
                SetBoneTransform(m_headBone.Index, Matrix.CreateRotationX(look.Y) * Matrix.CreateRotationZ(-look.X));
                SetBoneTransform(m_hand1Bone.Index, Matrix.CreateRotationX(m_hand1Angle));
                SetBoneTransform(m_hand2Bone.Index, Matrix.CreateRotationX(m_hand2Angle));
                SetBoneTransform(m_leg1Bone.Index, Matrix.CreateRotationX(m_leg1Angle));
                SetBoneTransform(m_leg2Bone.Index, Matrix.CreateRotationX(m_leg2Angle));
            }
            else
            {
                float death = 1f - DeathPhase;
                float dir = Vector3.Dot(m_componentFrame.Matrix.Right, DeathCauseOffset) > 0f ? 1 : -1;
                float height = m_componentCreature.ComponentBody.BoundingBox.Max.Y - m_componentCreature.ComponentBody.BoundingBox.Min.Y;
                SetBoneTransform(m_bodyBone.Index,
                    Matrix.CreateTranslation(-0.5f * height * Vector3.UnitY * DeathPhase)
                    * Matrix.CreateFromYawPitchRoll(rot.X, 0f, MathF.PI / 2f * DeathPhase * dir)
                    * Matrix.CreateTranslation(0.2f * height * Vector3.UnitY * DeathPhase)
                    * Matrix.CreateTranslation(pos));
                SetBoneTransform(m_headBone.Index, Matrix.CreateRotationX(MathUtils.DegToRad(50f) * DeathPhase));
                SetBoneTransform(m_hand1Bone.Index, Matrix.CreateRotationX(m_hand1Angle * death));
                SetBoneTransform(m_hand2Bone.Index, Matrix.CreateRotationX(m_hand2Angle * death));
                SetBoneTransform(m_leg1Bone.Index, Matrix.CreateRotationX(m_leg1Angle * death));
                SetBoneTransform(m_leg2Bone.Index, Matrix.CreateRotationX(m_leg2Angle * death));
            }
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            m_subsystemAudio = Project.FindSubsystem<SubsystemAudio>(true);
            m_subsystemSoundMaterials = Project.FindSubsystem<SubsystemSoundMaterials>(true);

            m_walkAnimationSpeed = valuesDictionary.GetValue<float>("WalkAnimationSpeed");
            m_walkFrontLegsAngle = valuesDictionary.GetValue<float>("WalkFrontLegsAngle");
            m_walkHindLegsAngle = valuesDictionary.GetValue<float>("WalkHindLegsAngle");
            m_canterLegsAngleFactor = valuesDictionary.GetValue<float>("CanterLegsAngleFactor");
            m_walkBobHeight = valuesDictionary.GetValue<float>("WalkBobHeight");
            m_canCanter = valuesDictionary.GetValue<bool>("CanCanter");
            m_canTrot = valuesDictionary.GetValue<bool>("CanTrot");
            m_useCanterSound = valuesDictionary.GetValue<bool>("UseCanterSound");
            m_attackSpeed = valuesDictionary.GetValue<float>("AttackSpeed");
            m_attackAngle = valuesDictionary.GetValue<float>("AttackAngle");
        }

        public override void SetModel(Model model)
        {
            base.SetModel(model);
            if (IsSet) return;
            if (Model != null)
            {
                m_bodyBone = Model.FindBone("Body");
                m_headBone = Model.FindBone("Head");
                m_hand1Bone = Model.FindBone("Hand1");
                m_hand2Bone = Model.FindBone("Hand2");
                m_leg1Bone = Model.FindBone("Leg1");
                m_leg2Bone = Model.FindBone("Leg2");
            }
            else
            {
                m_bodyBone = null;
                m_headBone = null;
                m_hand1Bone = null;
                m_hand2Bone = null;
                m_leg1Bone = null;
                m_leg2Bone = null;
            }
        }
    }
}
