//组件遗迹石像模型动画
namespace Game
{
    public class ComponentStoneStatueOfRuinsModel : ComponentCreatureModel
    {
        public ModelBone m_bodyBone, m_hand1Bone, m_hand2Bone, m_swordBone, m_spearBone, m_hammerBone;
        public Matrix m_swordRel, m_spearRel, m_hammerRel;
        public enum WeaponType { Sword, Spear, Hammer }
        public WeaponType m_weaponType;
        public enum AttackType { Slash, Thrust, Smash }
        public AttackType m_attackType;
        public float m_attackPhase, m_attackFactor;
        public bool m_attackTriggered, m_hitTriggered;
        public float m_walkSpeed = 1f, m_bobHeight = 0.15f;

        public override void Update(float dt)
        {
            float speed = m_componentCreature.ComponentBody.Velocity.XZ.Length();
            if (speed > 0.2f)
            {
                MovementAnimationPhase += speed * dt * m_walkSpeed;
                Bob = m_bobHeight * MathUtils.Sqr(MathF.Sin(MathF.PI * 2f * MovementAnimationPhase));
            }
            else Bob *= MathF.Exp(-dt * 5f);

            if (AttackOrder && !m_attackTriggered)
            {
                switch (m_weaponType)
                {
                    case WeaponType.Sword: m_attackType = AttackType.Slash; break;
                    case WeaponType.Spear: m_attackType = AttackType.Thrust; break;
                    case WeaponType.Hammer: m_attackType = AttackType.Smash; break;
                }
                m_attackPhase = 0f;
                m_attackFactor = 0f;
                m_attackTriggered = true;
                m_hitTriggered = false;
                AttackOrder = false;
            }

            if (m_attackTriggered)
            {
                m_attackFactor = MathUtils.Min(m_attackFactor + 4f * dt, 1f);
                m_attackPhase += dt * 2f;
                if (m_attackPhase >= 1f)
                {
                    m_attackPhase = 0f;
                    m_attackTriggered = false;
                    m_attackFactor = 0f;
                    m_hitTriggered = false;
                }
                if (!m_hitTriggered && m_attackFactor > 0.5f && m_attackPhase >= 0.4f && m_attackPhase < 0.6f)
                {
                    IsAttackHitMoment = true;
                    m_hitTriggered = true;
                }
                else IsAttackHitMoment = false;
            }
            else
            {
                m_attackFactor = MathUtils.Max(m_attackFactor - 4f * dt, 0f);
                IsAttackHitMoment = false;
                m_hitTriggered = false;
            }

            DeathPhase = m_componentCreature.ComponentHealth.Health <= 0f ?
                MathUtils.Min(DeathPhase + 3f * dt, 1f) :
                MathUtils.Max(DeathPhase - 3f * dt, 0f);

            base.Update(dt);
        }

        public override void AnimateCreature()
        {
            Vector3 pos = m_componentCreature.ComponentBody.Position + Vector3.UnitY * Bob;
            float yaw = m_componentCreature.ComponentBody.Rotation.ToYawPitchRoll().X;

            SetBoneTransform(m_bodyBone.Index, Matrix.CreateRotationY(yaw) * Matrix.CreateTranslation(pos));

            Vector2 h1 = Vector2.Zero;
            float p = MathUtils.Saturate(m_attackPhase);
            bool attacking = m_attackTriggered || m_attackFactor > 0f;

            if (attacking)
            {
                switch (m_attackType)
                {
                    case AttackType.Slash:
                        h1.X = MathUtils.DegToRad(-15f) * MathF.Sin(MathF.PI * p);
                        h1.Y = MathUtils.DegToRad(70f) * MathF.Sin(MathF.PI * p);
                        break;
                    case AttackType.Thrust:
                        h1.X = MathUtils.DegToRad(-10f) + MathUtils.DegToRad(-20f) * MathF.Sin(MathF.PI * p);
                        h1.Y = 0f;
                        break;
                    case AttackType.Smash:
                        h1.X = MathUtils.DegToRad(60f) * (1f - 2f * p);
                        h1.Y = 0f;
                        break;
                }
            }
            else
            {
                h1.X = MathUtils.DegToRad(-10f);
                h1.Y = 0f;
            }

            Matrix hand1Matrix = Matrix.CreateRotationY(h1.Y) * Matrix.CreateRotationX(h1.X);
            SetBoneTransform(m_hand1Bone.Index, hand1Matrix);

            Vector2 h2 = Vector2.Zero;
            if (MovementAnimationPhase != 0f && DeathPhase == 0f)
            {
                float s = MathF.Sin(MathF.PI * 2f * MovementAnimationPhase);
                h2.X = -0.3f * s;
                h2.Y = 0.2f * s;
            }
            SetBoneTransform(m_hand2Bone.Index, Matrix.CreateRotationY(h2.Y) * Matrix.CreateRotationX(h2.X));

            if (m_swordBone != null)
                SetBoneTransform(m_swordBone.Index,
                    (m_weaponType == WeaponType.Sword) ? hand1Matrix * m_swordRel : Matrix.CreateScale(0f));

            if (m_spearBone != null)
            {
                float spearOffset = 0f;
                if (m_weaponType == WeaponType.Spear && attacking && m_attackType == AttackType.Thrust)
                    spearOffset = 0.5f * MathF.Sin(MathF.PI * p); // 刺出幅度
                Matrix spearTransform = hand1Matrix * Matrix.CreateTranslation(0, 0, spearOffset) * m_spearRel;
                SetBoneTransform(m_spearBone.Index,
                    (m_weaponType == WeaponType.Spear) ? spearTransform : Matrix.CreateScale(0f));
            }

            if (m_hammerBone != null)
                SetBoneTransform(m_hammerBone.Index,
                    (m_weaponType == WeaponType.Hammer) ? hand1Matrix * m_hammerRel : Matrix.CreateScale(0f));

            if (DeathPhase > 0f)
            {
                float a = MathUtils.DegToRad(90f) * DeathPhase;
                Vector3 dPos = pos + Vector3.UnitY * (0.5f * DeathPhase * m_componentCreature.ComponentBody.BoxSize.Y);
                SetBoneTransform(m_bodyBone.Index, Matrix.CreateFromYawPitchRoll(yaw, a, 0f) * Matrix.CreateTranslation(dPos));
                SetBoneTransform(m_hand1Bone.Index, Matrix.CreateRotationX(MathUtils.DegToRad(-30f)));
                SetBoneTransform(m_hand2Bone.Index, Matrix.CreateRotationX(MathUtils.DegToRad(-30f)));
                if (m_swordBone != null) SetBoneTransform(m_swordBone.Index, Matrix.CreateScale(0));
                if (m_spearBone != null) SetBoneTransform(m_spearBone.Index, Matrix.CreateScale(0));
                if (m_hammerBone != null) SetBoneTransform(m_hammerBone.Index, Matrix.CreateScale(0));
            }
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            string w = valuesDictionary.GetValue<string>("StoneStatueOfRuinsWeaponType");
            if (w == "Sword") m_weaponType = WeaponType.Sword;
            else if (w == "Spear") m_weaponType = WeaponType.Spear;
            else if (w == "Hammer") m_weaponType = WeaponType.Hammer;
            else throw new InvalidOperationException("Invalid GolemWeaponType");
        }

        public override void SetModel(Model model)
        {
            base.SetModel(model);
            if (IsSet) return;
            if (Model != null)
            {
                m_bodyBone = Model.FindBone("Body");
                m_hand1Bone = Model.FindBone("Hand1");
                m_hand2Bone = Model.FindBone("Hand2");
                m_swordBone = Model.FindBone("Sword");
                m_spearBone = Model.FindBone("Spear");
                m_hammerBone = Model.FindBone("Hammer");

                if (m_hand1Bone != null)
                {
                    Matrix hand1Init = m_hand1Bone.Transform;
                    if (m_swordBone != null)
                    {
                        m_swordRel = Matrix.Invert(hand1Init) * m_swordBone.Transform;
                        m_swordRel *= Matrix.CreateTranslation(-0.15f, -0.6f, 0.95f) *
                                      Matrix.CreateRotationY(MathUtils.DegToRad(-90f)) *
                                      Matrix.CreateRotationZ(MathUtils.DegToRad(-90f));
                    }
                    if (m_spearBone != null)
                    {
                        m_spearRel = Matrix.Invert(hand1Init) * m_spearBone.Transform;
                        m_spearRel *= Matrix.CreateTranslation(0.5f, -0.5f, 0f) *
                                      Matrix.CreateRotationX(MathUtils.DegToRad(-90f)) *
                                      Matrix.CreateRotationZ(MathUtils.DegToRad(-90f));
                    }
                    if (m_hammerBone != null)
                    {
                        m_hammerRel = Matrix.Invert(hand1Init) * m_hammerBone.Transform;
                        m_hammerRel *= Matrix.CreateTranslation(-0.75f, -0.35f, -0.1f) *
                                      Matrix.CreateRotationX(MathUtils.DegToRad(-180f)) *
                                      Matrix.CreateRotationY(MathUtils.DegToRad(-45f)) *
                                      Matrix.CreateRotationZ(MathUtils.DegToRad(-90f));
                    }
                }
            }
            else
            {
                m_bodyBone = m_hand1Bone = m_hand2Bone = m_swordBone = m_spearBone = m_hammerBone = null;
                m_swordRel = m_spearRel = m_hammerRel = Matrix.Identity;
            }
        }

        public override Vector3 CalculateEyePosition()
        {
            Matrix m = m_componentCreature.ComponentBody.Matrix;
            return m_componentCreature.ComponentBody.Position + m.Up * 0.8f * m_componentCreature.ComponentBody.BoxSize.Y;
        }

        public override Quaternion CalculateEyeRotation()
        {
            return m_componentCreature.ComponentBody.Rotation;
        }
    }
}
//组件白鼠模型动画
namespace Game
{
    public class ComponentMutantRatModel : ComponentCreatureModel
    {
        public enum Gait
        {
            Walk,
            Trot,
            Canter
        }

        public SubsystemAudio m_subsystemAudio;
        public SubsystemSoundMaterials m_subsystemSoundMaterials;
        public ModelBone m_bodyBone;
        public ModelBone m_headBone;
        public ModelBone m_hand1Bone;
        public ModelBone m_hand2Bone;
        public ModelBone m_leg1Bone;
        public ModelBone m_leg2Bone;
        public float m_walkAnimationSpeed;
        public float m_canterLegsAngleFactor;
        public float m_walkFrontLegsAngle;
        public float m_walkHindLegsAngle;
        public float m_walkBobHeight;
        public bool m_moveLegWhenFeeding;
        public bool m_canCanter;
        public bool m_canTrot;
        public bool m_useCanterSound;
        public Gait m_gait;
        public float m_feedFactor;
        public float m_buttFactor;
        public float m_buttPhase;
        public float m_footstepsPhase;
        public float m_legAngle1;
        public float m_legAngle2;
        public float m_legAngle3;
        public float m_legAngle4;
        public float m_headAngleY;

        public override float AttackPhase
        {
            get => m_buttPhase;
            set => m_buttPhase = value;
        }

        public override float AttackFactor
        {
            get => m_buttFactor;
            set => m_buttFactor = value;
        }

        public override void Update(float dt)
        {
            float footstepsPhase = m_footstepsPhase;
            float num = m_componentCreature.ComponentLocomotion.SlipSpeed ?? Vector3.Dot(m_componentCreature.ComponentBody.Velocity, m_componentCreature.ComponentBody.Matrix.Forward);
            if (m_canCanter && num > 0.7f * m_componentCreature.ComponentLocomotion.WalkSpeed)
            {
                m_gait = Gait.Canter;
                MovementAnimationPhase += num * dt * 0.7f * m_walkAnimationSpeed;
                m_footstepsPhase += 0.7f * m_walkAnimationSpeed * num * dt;
            }
            else if (m_canTrot && num > 0.5f * m_componentCreature.ComponentLocomotion.WalkSpeed)
            {
                m_gait = Gait.Trot;
                MovementAnimationPhase += num * dt * m_walkAnimationSpeed;
                m_footstepsPhase += 1.25f * m_walkAnimationSpeed * num * dt;
            }
            else if (MathF.Abs(num) > 0.2f)
            {
                m_gait = Gait.Walk;
                MovementAnimationPhase += num * dt * m_walkAnimationSpeed;
                m_footstepsPhase += 1.25f * m_walkAnimationSpeed * num * dt;
            }
            else
            {
                m_gait = Gait.Walk;
                MovementAnimationPhase = 0f;
                m_footstepsPhase = 0f;
            }
            float num2 = 0f;
            if (m_gait == Gait.Canter)
            {
                num2 = (0f - m_walkBobHeight) * 1.5f * MathF.Sin(6.28318548f * MovementAnimationPhase);
            }
            else if (m_gait == Gait.Trot)
            {
                num2 = m_walkBobHeight * 1.5f * MathUtils.Sqr(MathF.Sin(6.28318548f * MovementAnimationPhase));
            }
            else if (m_gait == Gait.Walk)
            {
                num2 = (0f - m_walkBobHeight) * MathUtils.Sqr(MathF.Sin(6.28318548f * MovementAnimationPhase));
            }
            float num3 = MathUtils.Min(12f * m_subsystemTime.GameTimeDelta, 1f);
            Bob += num3 * (num2 - Bob);
            if (m_gait == Gait.Canter && m_useCanterSound)
            {
                float num4 = MathF.Floor(m_footstepsPhase);
                if (m_footstepsPhase > num4 && footstepsPhase <= num4)
                {
                    string footstepSoundMaterialName = m_subsystemSoundMaterials.GetFootstepSoundMaterialName(m_componentCreature);
                    if (!string.IsNullOrEmpty(footstepSoundMaterialName) && footstepSoundMaterialName != "Water")
                    {
                        m_subsystemAudio.PlayRandomSound("Audio/Footsteps/CanterDirt", 0.75f, m_random.Float(-0.25f, 0f), m_componentCreature.ComponentBody.Position, 3f, true);
                    }
                }
            }
            else
            {
                float num5 = MathF.Floor(m_footstepsPhase);
                if (m_footstepsPhase > num5 && footstepsPhase <= num5)
                {
                    m_componentCreature.ComponentCreatureSounds.PlayFootstepSound(1f);
                }
            }
            m_feedFactor = FeedOrder ? MathUtils.Min(m_feedFactor + 2f * dt, 1f) : MathUtils.Max(m_feedFactor - 2f * dt, 0f);
            IsAttackHitMoment = false;
            if (AttackOrder)
            {
                m_buttFactor = MathUtils.Min(m_buttFactor + 4f * dt, 1f);
                float buttPhase = m_buttPhase;
                m_buttPhase = MathUtils.Remainder(m_buttPhase + dt * 2f, 1f);
                if (buttPhase < 0.5f && m_buttPhase >= 0.5f)
                {
                    IsAttackHitMoment = true;
                }
            }
            else
            {
                m_buttFactor = MathUtils.Max(m_buttFactor - 4f * dt, 0f);
                if (m_buttPhase != 0f)
                {
                    if (m_buttPhase > 0.5f)
                    {
                        m_buttPhase = MathUtils.Remainder(MathUtils.Min(m_buttPhase + dt * 2f, 1f), 1f);
                    }
                    else if (m_buttPhase > 0f)
                    {
                        m_buttPhase = MathUtils.Max(m_buttPhase - dt * 2f, 0f);
                    }
                }
            }
            FeedOrder = false;
            AttackOrder = false;
            base.Update(dt);
        }

        public override void AnimateCreature()
        {
            Vector3 position = m_componentCreature.ComponentBody.Position;
            Vector3 vector = m_componentCreature.ComponentBody.Rotation.ToYawPitchRoll();
            if (m_componentCreature.ComponentHealth.Health > 0f)
            {
                float num = 0f;
                float num2 = 0f;
                float num3 = 0f;
                float num4 = 0f;
                float num5 = 0f;
                if (MovementAnimationPhase != 0f && (m_componentCreature.ComponentBody.StandingOnValue.HasValue || m_componentCreature.ComponentBody.ImmersionFactor > 0f))
                {
                    if (m_gait == Gait.Canter)
                    {
                        float num6 = MathF.Sin(6.28318548f * (MovementAnimationPhase + 0f));
                        float num7 = MathF.Sin(6.28318548f * (MovementAnimationPhase + 0.25f));
                        float num8 = MathF.Sin(6.28318548f * (MovementAnimationPhase + 0.15f));
                        float num9 = MathF.Sin(6.28318548f * (MovementAnimationPhase + 0.4f));
                        num = m_walkFrontLegsAngle * m_canterLegsAngleFactor * num6;
                        num2 = m_walkFrontLegsAngle * m_canterLegsAngleFactor * num7;
                        num3 = m_walkHindLegsAngle * m_canterLegsAngleFactor * num8;
                        num4 = m_walkHindLegsAngle * m_canterLegsAngleFactor * num9;
                        num5 = MathUtils.DegToRad(8f) * MathF.Sin(6.28318548f * MovementAnimationPhase);
                    }
                    else if (m_gait == Gait.Trot)
                    {
                        float num10 = MathF.Sin(6.28318548f * (MovementAnimationPhase + 0f));
                        float num11 = MathF.Sin(6.28318548f * (MovementAnimationPhase + 0.5f));
                        float num12 = MathF.Sin(6.28318548f * (MovementAnimationPhase + 0.5f));
                        float num13 = MathF.Sin(6.28318548f * (MovementAnimationPhase + 0f));
                        num = m_walkFrontLegsAngle * num10;
                        num2 = m_walkFrontLegsAngle * num11;
                        num3 = m_walkHindLegsAngle * num12;
                        num4 = m_walkHindLegsAngle * num13;
                        num5 = MathUtils.DegToRad(3f) * MathF.Sin(12.56637096f * MovementAnimationPhase);
                    }
                    else
                    {
                        float num14 = MathF.Sin(6.28318548f * (MovementAnimationPhase + 0f));
                        float num15 = MathF.Sin(6.28318548f * (MovementAnimationPhase + 0.5f));
                        float num16 = MathF.Sin(6.28318548f * (MovementAnimationPhase + 0.25f));
                        float num17 = MathF.Sin(6.28318548f * (MovementAnimationPhase + 0.75f));
                        num = m_walkFrontLegsAngle * num14;
                        num2 = m_walkFrontLegsAngle * num15;
                        num3 = m_walkHindLegsAngle * num16;
                        num4 = m_walkHindLegsAngle * num17;
                        num5 = MathUtils.DegToRad(3f) * MathF.Sin(12.56637096f * MovementAnimationPhase);
                    }
                }
                float num18 = MathUtils.Min(12f * m_subsystemTime.GameTimeDelta, 1f);
                m_legAngle1 += num18 * (num - m_legAngle1);
                m_legAngle2 += num18 * (num2 - m_legAngle2);
                m_legAngle3 += num18 * (num3 - m_legAngle3);
                m_legAngle4 += num18 * (num4 - m_legAngle4);
                m_headAngleY += num18 * (num5 - m_headAngleY);
                Vector2 vector2 = m_componentCreature.ComponentLocomotion.LookAngles;
                vector2.Y += m_headAngleY;
                vector2.X = Math.Clamp(vector2.X, -MathUtils.DegToRad(65f), MathUtils.DegToRad(65f));
                vector2.Y = Math.Clamp(vector2.Y, -MathUtils.DegToRad(55f), MathUtils.DegToRad(55f));
                if (m_feedFactor > 0f)
                {
                    float y = -MathUtils.DegToRad(25f + 45f * SimplexNoise.OctavedNoise((float)m_subsystemTime.GameTime, 3f, 2, 2f, 0.75f));
                    vector2 = Vector2.Lerp(new Vector2(0f, y), vector2, m_feedFactor);
                }
                if (m_buttFactor != 0f)
                {
                    float y2 = -MathUtils.DegToRad(40f) * MathF.Sin(6.28318548f * MathUtils.Sigmoid(m_buttPhase, 4f));
                    vector2 = Vector2.Lerp(new Vector2(0f, y2), vector2, m_buttFactor);
                }
                SetBoneTransform(m_bodyBone.Index, Matrix.CreateRotationY(vector.X) * Matrix.CreateTranslation(position.X, position.Y + Bob, position.Z));
                SetBoneTransform(m_headBone.Index, Matrix.CreateRotationX(vector2.Y) * Matrix.CreateRotationZ(-vector2.X));
                SetBoneTransform(m_hand1Bone.Index, Matrix.CreateRotationX(m_legAngle1));
                SetBoneTransform(m_hand2Bone.Index, Matrix.CreateRotationX(m_legAngle2));
                SetBoneTransform(m_leg1Bone.Index, Matrix.CreateRotationX(m_legAngle3));
                SetBoneTransform(m_leg2Bone.Index, Matrix.CreateRotationX(m_legAngle4));
            }
            else
            {
                float num19 = 1f - DeathPhase;
                float num20 = Vector3.Dot(m_componentFrame.Matrix.Right, DeathCauseOffset) > 0f ? 1 : -1;
                float num21 = m_componentCreature.ComponentBody.BoundingBox.Max.Y - m_componentCreature.ComponentBody.BoundingBox.Min.Y;
                SetBoneTransform(m_bodyBone.Index, Matrix.CreateTranslation(-0.5f * num21 * Vector3.UnitY * DeathPhase) * Matrix.CreateFromYawPitchRoll(vector.X, 0f, 1.57079637f * DeathPhase * num20) * Matrix.CreateTranslation(0.2f * num21 * Vector3.UnitY * DeathPhase) * Matrix.CreateTranslation(position));
                SetBoneTransform(m_headBone.Index, Matrix.CreateRotationX(MathUtils.DegToRad(50f) * DeathPhase));
                SetBoneTransform(m_hand1Bone.Index, Matrix.CreateRotationX(m_legAngle1 * num19));
                SetBoneTransform(m_hand2Bone.Index, Matrix.CreateRotationX(m_legAngle2 * num19));
                SetBoneTransform(m_leg1Bone.Index, Matrix.CreateRotationX(m_legAngle3 * num19));
                SetBoneTransform(m_leg2Bone.Index, Matrix.CreateRotationX(m_legAngle4 * num19));
            }
        }

        public override void Load(ValuesDictionary valuesDictionary, IdToEntityMap idToEntityMap)
        {
            base.Load(valuesDictionary, idToEntityMap);
            m_subsystemAudio = Project.FindSubsystem<SubsystemAudio>(true);
            m_subsystemSoundMaterials = Project.FindSubsystem<SubsystemSoundMaterials>(true);
            m_walkAnimationSpeed = valuesDictionary.GetValue<float>("WalkAnimationSpeed");
            m_walkFrontLegsAngle = valuesDictionary.GetValue<float>("WalkFrontLegsAngle");
            m_walkHindLegsAngle = valuesDictionary.GetValue<float>("WalkHindLegsAngle");
            m_canterLegsAngleFactor = valuesDictionary.GetValue<float>("CanterLegsAngleFactor");
            m_walkBobHeight = valuesDictionary.GetValue<float>("WalkBobHeight");
            m_moveLegWhenFeeding = valuesDictionary.GetValue<bool>("MoveLegWhenFeeding");
            m_canCanter = valuesDictionary.GetValue<bool>("CanCanter");
            m_canTrot = valuesDictionary.GetValue<bool>("CanTrot");
            m_useCanterSound = valuesDictionary.GetValue<bool>("UseCanterSound");
        }

        public override void SetModel(Model model)
        {
            base.SetModel(model);
            if (IsSet)
                return;
            if (Model != null)
            {
                m_bodyBone = Model.FindBone("Body");
                m_headBone = Model.FindBone("Head");
                m_hand1Bone = Model.FindBone("Hand1");
                m_hand2Bone = Model.FindBone("Hand2");
                m_leg1Bone = Model.FindBone("Leg1");
                m_leg2Bone = Model.FindBone("Leg2");
            }
            else
            {
                m_bodyBone = null;
                m_headBone = null;
                m_hand1Bone = null;
                m_hand2Bone = null;
                m_leg1Bone = null;
                m_leg2Bone = null;
            }
        }
    }
}